(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["md5"] = [{"id":"md5-105-1-1","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"下列那一個腹部器官在腹部鈍傷中最常受到傷害？","options":["(A) 肝臟","(B) 腎臟","(C) 脾臟","(D) 胰臟"],"answer":2,"image":""},{"id":"md5-105-1-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"25歲年輕男子，因騎乘重型機車發生事故，造成嚴重骨盆骨折（pelvic fracture）。抵達急診時呈現休克，經大量輸液與輸血灌救後，收縮壓高於90 mmHg，並隨即接受腹部電腦斷層攝影檢查。但發現骨盆腔出現顯影劑外滲（contrast extravasation）。下列何種治療方法治療出血性休克效果最佳？","options":["(A) 繼續輸血（transfusion）","(B) 骨盆外固定（external fixation）","(C) 剖腹手術結紮髂外動脈（external iliac artery ligation）","(D) 血管栓塞術（angio-embolization）"],"answer":3,"image":""},{"id":"md5-105-1-3","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"當車禍事故的傷患被送至急診室急救時，如果發現呼吸道有異物、呼吸困難或神智不清時，應立即給予氣管內插管（endotracheal intubation）。下列何項為外傷病患緊急插管時，最應該注意之事項？","options":["(A) 保護頸椎（cervical spine protection）","(B) 注意腦壓升高","(C) 注意吸入性肺炎（aspiration pneumonia）","(D) 注意麻藥劑量過多"],"answer":0,"image":""},{"id":"md5-105-1-4","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"一位70公斤且多重外傷之病人於急診之總輸血量超過2500毫升，雖經過緊急手術止血，受傷後第一天之總輸血量仍超過5000毫升。於加護病房照護初期，下列何種變化較少出現？","options":["(A) 稀釋性血小板缺乏（dilution thrombocytopenia）","(B) 酸中毒（metabolic acidosis）","(C) 高血鉀症（hyperkalemia）","(D) 溶血性反應（hemolytic reaction）"],"answer":3,"image":""},{"id":"md5-105-1-5","subject":"md5","topic":"神經外科","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"頭部外傷的急救處置應以何者為優先？","options":["(A) 胸部X光檢查","(B) 檢驗尿液","(C) 腹部X光檢查","(D) 矯正低血壓，維持足夠的供氧"],"answer":3,"image":""},{"id":"md5-105-1-6","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"70歲男性糖尿病人需接受小腸惡性腫瘤切除手術，應採取什麼措施來預防手術部位感染（surgical site infections）？","options":["(A) 在手術切開皮膚之後給予抗生素","(B) 控制其血糖在200〜250 mg/dL","(C) 手術中將病人體溫維持在35.5〜36℃","(D) 手術時間超過使用之抗生素的半生期（half life）2倍長時，追加一次抗生素"],"answer":3,"image":""},{"id":"md5-105-1-7","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"腹內實質臟器發生鈍性挫傷時，非手術療法（nonoperative management）已成為常態性之治療方式。當摩托車騎士受傷後，經確認診斷為單獨性肝臟裂傷（isolated liver laceration），經採用非手術療法後，下列何種合併症比較不會出現？","options":["(A) 延遲性腹內出血（delayed hemorrhage）","(B) 肝膿瘍（liver abscess）","(C) 黃疸（jaundice）","(D) 血尿（hematuria）"],"answer":3,"image":""},{"id":"md5-105-1-8","subject":"md5","topic":"小兒外科","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"Hirschsprung's disease信賴度最高（gold standard）的診斷依據為何？","options":["(A) 超過48小時未解胎便","(B) 肛門壓力計檢查（manometry study）","(C) 直腸切片檢查（rectal biopsy）","(D) 下消化道鋇劑檢查（lower GI barium enema）"],"answer":2,"image":""},{"id":"md5-105-1-9","subject":"md5","topic":"心臟血管外科","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"心包填塞（cardiac tamponade）是下列那一個情形？中心靜脈壓動脈壓心輸出量混合靜脈血氧飽和度A ↓ ↓ ↓ ↓ B ↑ ↓ ↓ ↓ C ↑ ↓ ↓ ↑ D ↑ ↑ ↑ ↓ 中心靜脈壓（central venous pressure），動脈壓（arterial blood pressure），心輸出量（cardiac output），混合靜脈血氧飽和度（mixed venous oxygenation saturation）","options":["(A) A","(B) B","(C) C","(D) D"],"answer":1,"image":""},{"id":"md5-105-1-10","subject":"md5","topic":"胸腔外科","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"下列有關治療多汗症手術的敘述，何者錯誤？","options":["(A) 手掌及腋下多汗可透過胸腔交感神經切除術改善","(B) 手術切除的主要部位是第四及第五胸交感神經節","(C) 可能副作用中的Horner's syndrome原因是將T1交感神經節切除","(D) 可能的副作用包括血胸及氣胸"],"answer":1,"image":""},{"id":"md5-105-1-11","subject":"md5","topic":"神經外科","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"最常造成自發性蜘蛛網膜下腔出血的原因是：","options":["(A) 高血壓","(B) 腫瘤出血","(C) 顱內動脈瘤破裂","(D) 顱內動靜脈畸形破裂"],"answer":2,"image":""},{"id":"md5-105-1-12","subject":"md5","topic":"神經外科","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"脊椎損傷病人中，容易出現呼吸衰竭的是那幾節？","options":["(A) 第三至第五頸椎","(B) 第六至第七頸椎","(C) 第三至第七胸椎","(D) 第四至第五腰椎"],"answer":0,"image":""},{"id":"md5-105-1-13","subject":"md5","topic":"神經外科","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"高血壓性腦內出血，最好發的位置在：","options":["(A) 豆狀核（putamen）","(B) 小腦（cerebellum）","(C) 橋腦（pons）","(D) 視丘（thalamus）"],"answer":0,"image":""},{"id":"md5-105-1-14","subject":"md5","topic":"神經外科","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"下列有關腦膜瘤（meningioma）的敘述，何者錯誤？","options":["(A) 腦膜瘤是由硬腦膜（dura）生長來的","(B) 一般而言生長較緩慢","(C) 鄰近骨頭有增生（hyperostosis）的現象","(D) 矢狀竇旁（parasagittal）的位置最常見"],"answer":0,"image":""},{"id":"md5-105-1-15","subject":"md5","topic":"神經外科","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"急性硬腦膜外血腫（epidural hematoma）的病人，下列敘述何者錯誤？","options":["(A) 常合併有顱骨骨折","(B) 常因是中腦膜動脈（middle meningeal artery）破裂所致","(C) 預後比急性硬腦膜內血腫（acute subdural hematoma）不好","(D) 約有1/3的病人到急診處呈昏迷狀態"],"answer":2,"image":""},{"id":"md5-105-1-16","subject":"md5","topic":"神經外科","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"表皮樣囊腫（epidermoid tumor）腦瘤會有下列何種特質？","options":["(A) 細菌性腦膜炎（bacterial meningitis）","(B) 伴有先天異常（associated congenital malformations）","(C) 對放射性治療有效（responsive to radiation therapy）","(D) 無菌性腦膜炎（aseptic meningitis）"],"answer":3,"image":""},{"id":"md5-105-1-17","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"下列有關掌內肌群（intrinsic muscles）之敘述，何者錯誤？","options":["(A) 外展拇肌（abductor pollicis）是由正中神經（median nerve）所支配的","(B) 掌短肌（palmaris brevis）是由正中神經（median nerve）所支配的","(C) 背側掌骨間肌（dorsal interossei）是由尺神經（ulnar nerve）所支配的","(D) 蚓狀肌（lumbricals）是由正中神經（median nerve）和尺神經（ulnar nerve）共同支配的"],"answer":1,"image":""},{"id":"md5-105-1-18","subject":"md5","topic":"整形重建外科","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"當褥瘡（pressure ulcer）侵蝕到肌肉及骨頭的時候屬於：","options":["(A) Stage I","(B) Stage II","(C) Stage III","(D) Stage IV"],"answer":3,"image":""},{"id":"md5-105-1-19","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"20歲、60公斤體重健康大學生，於餐廳打工時不慎打翻熱茶桶。高溫熱茶潑及他的兩側下肢，造成此二肢體全部燙傷起水泡。依據「9的規則」（rule of nines）與「帕克蘭公式」（Parkland formula）估算，下列關於此學生之「燙傷面積」及「受傷後24小時靜脈輸液量」敘述，何者最適當？","options":["(A) 36%體表面積、8,640公撮（miniliters, mL.）晶質溶液（crystalloid）","(B) 36%體表面積、3,240公撮晶質溶液（crystalloid）加上1,080公撮膠質溶液（colloid）","(C) 45%體表面積、10,8000公撮晶質溶液","(D) 45%體表面積、4,050公撮晶質溶液加上1,350公撮膠質溶液"],"answer":0,"image":""},{"id":"md5-105-1-20","subject":"md5","topic":"整形重建外科","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"使用局部的轉位皮瓣（local rotational flaps）時有那些注意事項，但何者除外：","options":["(A) 轉位皮瓣的長與寬之比例","(B) 縫合後轉位皮瓣周圍所承受的張力","(C) 傷口包紮的鬆緊度","(D) 縫線的顏色"],"answer":3,"image":""},{"id":"md5-105-1-21","subject":"md5","topic":"心臟血管外科","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"下列有關心房震顫（atrial fibrillation）之敘述，何者錯誤？","options":["(A) 藥物療法除了心率控制以外，須包括抗凝血療法以減少血栓產生","(B) 手術適應症包括藥物治療無效合併心房震顫引起之心肌病變、無法接受抗心律不整藥物或抗凝血藥物的治療","(C) 目前ablation術式包括冷凍療法（cryoablation）、微波燒灼（microwave）、雷射燒灼（laser）等","(D) 目前外科手術中，cut-and-sew Cox-Maze III procedure術後約只有一半的病患可跳回正常的竇性心律"],"answer":3,"image":""},{"id":"md5-105-1-22","subject":"md5","topic":"心臟血管外科","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"針對末期心臟衰竭的病人，在心臟移植之前，尚有其他手術方式可以改善心臟功能及臨床症狀，但下列何者除外？","options":["(A) 冠狀動脈繞道手術（coronary artery bypass surgery）","(B) 二尖瓣逆流重建手術（mitral reconstruction）","(C) 經心肌雷射血管再生術（transmyocardial laser revascularization）","(D) 部分左心室心肌切除手術（partial left ventriculectomy）"],"answer":2,"image":""},{"id":"md5-105-1-23","subject":"md5","topic":"心臟血管外科","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"下列關於急性心肌梗塞的敘述，何者錯誤？","options":["(A) 可能因僧帽瓣破裂（mitral valve）而併發急性僧帽瓣閉鎖不全（mitral regurgitation），需要緊急手術","(B) 若發生心室中隔破裂（ventricular septal rupture）需要緊急手術","(C) 若發生左心室游離壁破裂（left ventricular freewall rupture）需要緊急手術","(D) 主動脈內氣球幫浦（intra-aortic balloon pumping）常用於急性心肌梗塞併發休克"],"answer":0,"image":""},{"id":"md5-105-1-24","subject":"md5","topic":"心臟血管外科","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"下列有關腹主動脈瘤（abdominal aortic aneurysm）手術適應症之敘述，何者錯誤？","options":["(A) 最大直徑> 5.5 cm，應手術治療","(B) 最大直徑介於4.0～5.0 cm且每年增加1 cm，應手術治療","(C) 合併有腹痛，背痛或是血栓形成造成周邊動脈堵塞，應立即手術治療","(D) 破裂的腹主動脈瘤，手術死亡率極高，並不建議立即手術治療"],"answer":3,"image":""},{"id":"md5-105-1-25","subject":"md5","topic":"胸腔外科","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"在食道癌的TNM分期中，其T的分期最準確的檢查為下列何者？","options":["(A) 電腦斷層檢查（computed tomography）","(B) 內視鏡超音波檢查（endoscopic ultrasound）","(C) 核磁共振影像檢查（magnetic resonance imaging）","(D) 正子攝影檢查（positron emission tomography）"],"answer":1,"image":""},{"id":"md5-105-1-26","subject":"md5","topic":"胸腔外科","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"當一位肺癌病人其頸部有淋巴結硬塊時，最適當的處置為何？","options":["(A) 以內視鏡切除肺腫瘤","(B) 以內視鏡切除肺腫瘤加上縱隔淋巴結清掃","(C) 以內視鏡切除肺腫瘤加上縱隔及頸部淋巴結清掃","(D) 安排頸部淋巴結細針穿刺切片檢查"],"answer":3,"image":""},{"id":"md5-105-1-27","subject":"md5","topic":"胸腔外科","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"食道癌最常見的臨床狀況為何？","options":["(A) 發燒","(B) 胸痛","(C) 漸行性吞嚥困難","(D) 食道逆流"],"answer":2,"image":""},{"id":"md5-105-1-28","subject":"md5","topic":"胸腔外科","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"切除轉移性肺腫瘤，下列敘述何項錯誤？","options":["(A) 原發性腫瘤沒有復發情況下，才會進行肺轉移腫瘤切除","(B) 內視鏡手術切除轉移肺腫瘤已是標準手術方式","(C) 可減少腫瘤負擔（tumor burden）","(D) 手術前胸部的MRI不一定需要"],"answer":1,"image":""},{"id":"md5-105-1-29","subject":"md5","topic":"消化器外科","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"Model for End-Stage Liver Disease（MELD）scale是評估hepatic functional reserve的好方法，其內容不包括下列何者？","options":["(A) serum albumin level","(B) INR（international normalized ratio）","(C) serum bilirubin level","(D) serum creatinine level"],"answer":0,"image":""},{"id":"md5-105-1-30","subject":"md5","topic":"消化器外科","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"肝癌患者有下列何種狀況不適合手術切除？","options":["(A) 有肝硬化","(B) 腫瘤大於10公分","(C) 有腹水無法用利尿劑控制","(D) 有末梢門脈血栓"],"answer":2,"image":""},{"id":"md5-105-1-31","subject":"md5","topic":"消化器外科","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"下列有關肝臟解剖學之敘述，何者錯誤？","options":["(A) 通常膽囊動脈源自於右肝動脈","(B) 最常見的膽道構造為右前枝與右後枝膽管會合後，再與左膽管會合成總肝管（common hepatic duct）","(C) 尾狀葉（caudate lobe）指的是Couinaud分類中的第一節葉（segment 1）","(D) 即使在門脈高壓的情況底下，門脈循環與系統靜脈循環彼此之間仍然沒有聯繫（connection）"],"answer":3,"image":""},{"id":"md5-105-1-32","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"一位18歲單身女性，有氣喘病史，右腎萎縮但腎功能正常。兩天前有上腹間歇性疼痛，有時伴有腹脹。她並不在意，但昨天忽然覺得右下腹疼痛，且有加劇的現象。她來到急診室，當時胃口不佳，但無噁心或嘔吐。血壓107/71 mmHg，體溫36.8 oC，脈搏74下/min，呼吸20次/min。白血球：13000/ mm3，血色素：12.5 g/dL，血小板：259 × 103 /mm3。最可能的診斷為何？","options":["(A) 泌尿道結石","(B) 急性闌尾炎","(C) 子宮外孕","(D) 骨盆腔發炎"],"answer":1,"image":""},{"id":"md5-105-1-33","subject":"md5","topic":"消化器外科","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"有關胃腺癌之分期，TNM中“T”代表：","options":["(A) 腫瘤位置","(B) 腫瘤大小","(C) 腫瘤侵犯深度","(D) 腫瘤肉眼觀"],"answer":2,"image":""},{"id":"md5-105-1-34","subject":"md5","topic":"消化器外科","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"在切片的觀察中，胃黏膜上皮細胞佔比例最高的為：","options":["(A) mucous cell","(B) chief cell","(C) parietal cell","(D) endocrine cell"],"answer":1,"image":""},{"id":"md5-105-1-35","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"關於胰臟內分泌瘤（pancreatic endocrine tumor）之敘述，下列何者錯誤？","options":["(A) 對於有反覆發作難治癒型的消化性潰瘍、嚴重食道發炎或是持續性腹瀉的病人，必須要考慮是否有Zollinger-Ellison syndrome","(B) 在Zollinger-Ellison syndrome的病人中有75%其gastrinoma是偶發性的，但有25%的病人是合併有MEN 1 syndrome","(C) 所謂MEN 1 syndrome為染色體第11對突變之顯性遺傳，最常見的是有parathyroid tumor、prostate cancer及pancreatic endocrine tumor","(D) 對於同時合併有副甲狀腺亢進及pancreatic endocrine tumor的MEN 1病人，要優先處理副甲狀腺亢進的問題"],"answer":2,"image":""},{"id":"md5-105-1-36","subject":"md5","topic":"消化器外科","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"關於胰臟癌，下列何者錯誤？","options":["(A) 最常見的病理切片診斷為ductal adenocarcinoma","(B) 胰臟癌發生的危險因子包括有年紀、家族史、抽菸、慢性胰臟炎等","(C) 根據American Joint Committee on Cancer（AJCC）對於胰臟癌所作的分期，T3N0M0與T2N1M0皆是屬於stage IIB","(D) 胰臟頭部的癌症，可以考慮以pancreaticoduodenectomy來切除之"],"answer":2,"image":""},{"id":"md5-105-1-37","subject":"md5","topic":"消化器外科","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"52歲男性患者，因為發燒，右上腹悶痛來到急診，腹部電腦斷層如下圖所示，其可能的診斷為何？","options":["(A) 阿米巴肝膿瘍","(B) 細菌性肝膿瘍","(C) 總膽管結石併膽道炎","(D) 膽囊結石併膽囊炎"],"answer":2,"image":"md5-105-1-37.jpeg"},{"id":"md5-105-1-38","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"對孕婦來說，laparoscopic surgery最好的surgical position為：","options":["(A) prone position","(B) lithotomy position","(C) left lateral decubitus position","(D) right lateral decubitus position"],"answer":2,"image":""},{"id":"md5-105-1-39","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"下列有關治療甲狀腺風暴的敘述，何者錯誤？","options":["(A) 可使用抗甲狀腺藥物以降低血中T4轉化成T3的量","(B) 可使用乙型拮抗劑（beta-blockers）以降低血中T4轉化為T3的量","(C) 給予2%碘劑溶液（Lugol’s solution）可減少甲狀腺荷爾蒙分泌量","(D) 使用類固醇及阿斯匹靈退燒，同時需輸液治療"],"answer":3,"image":""},{"id":"md5-105-1-40","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"未分化型甲狀腺癌（anaplastic carcinoma），何者錯誤？","options":["(A) 不可能由分化良好型甲狀腺癌轉變而來","(B) 需作切片檢查或氣管切開","(C) 目前放射線治療（radiation therapy）及化學治療（chemotherapy）效果不彰","(D) 很少需要根除手術，預後甚差"],"answer":0,"image":""},{"id":"md5-105-1-41","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"甲狀腺髓質癌（medullary carcinoma），何者錯誤？","options":["(A) 宜作甲狀腺全切除合併中央隔間淋巴結切除（central compartment dissection）","(B) 診斷用CEA、calcitonin及細胞學檢查","(C) 伴有嗜鉻細胞癌（pheochromocytoma）病人時，要先進行甲狀腺髓質癌手術","(D) 碘131治療無效"],"answer":2,"image":""},{"id":"md5-105-1-42","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"乳房攝影檢查時，腫瘤或鈣化之影像因年齡增加而有所改變，下列敘述何者正確？","options":["(A) 脂肪減少，影像清晰","(B) 脂肪增加，影像模糊","(C) 脂肪減少，影像模糊","(D) 脂肪增加，影像清晰"],"answer":3,"image":""},{"id":"md5-105-1-43","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"下列有關喉返神經（recurrent laryngeal nerve）受傷會造成之症狀，何者錯誤？","options":["(A) 聲音沙啞","(B) 噎住（choking）","(C) 聲帶麻痺，處在中線旁（paramedian）位置或外展（abducted）位置","(D) 咽喉上聲門（supraglottic larynx）感覺麻痺"],"answer":3,"image":""},{"id":"md5-105-1-44","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"85歲女性右側第一期乳癌經乳房保留手術切除，病理報告為T1N0M0女性荷爾蒙接受器（estrogen receptor）陰性，黃體素接受器（progesterone receptor）陰性，HER-2/neu陰性腫瘤，邊緣接近，術後應先如何處理最適合？","options":["(A) 化學治療","(B) 荷爾蒙治療","(C) 放射線治療","(D) 標靶治療"],"answer":[0,2],"image":"","answer_note":"更正:第44題答Ａ、Ｃ給分"},{"id":"md5-105-1-45","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"下列何者不是罹患乳癌的危險因子？","options":["(A) 一等親姊妹罹患乳癌","(B) 40歲懷孕生第一胎","(C) 停經後服用10年的女性荷爾蒙取代劑","(D) 嬸嬸罹患乳癌"],"answer":3,"image":""},{"id":"md5-105-1-46","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"乳癌手術執行腋下前哨淋巴結摘除（sentinel node biopsy）；前哨淋巴結是指下列何者？","options":["(A) 第一群可能轉移的腋下淋巴結（level Ι）","(B) 第二群可能轉移的淋巴結（level II）","(C) 第一顆可能轉移的腋下淋巴結","(D) 第二顆可能轉移的腋下淋巴結"],"answer":[0,2],"image":"","answer_note":"更正:第46題答Ａ、Ｃ給分"},{"id":"md5-105-1-47","subject":"md5","topic":"小兒外科","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"在食道閉鎖（esophageal atresia）的畸型中，最常見的類型為何？","options":["(A) 食道閉鎖無併發瘻管（esophageal atresia without a tracheoesophageal fistula）","(B) 食道閉鎖併近端瘻管（esophageal atresia with a proximal tracheoesophageal fistula）","(C) 食道閉鎖併遠端瘻管（esophageal atresia with a distal tracheoesophageal fistula）","(D) 食道閉鎖併雙瘻管（esophageal atresia with a double tracheoesophageal fistula）"],"answer":2,"image":""},{"id":"md5-105-1-48","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"下列何者不是惡性乳房腫瘤在乳房超音波（ultrasound or sonography）的特徵？","options":["(A) hypo-echoic","(B) taller than wide shape","(C) tumor size larger than 3 cm","(D) posterior wall attenuation"],"answer":2,"image":""},{"id":"md5-105-1-49","subject":"md5","topic":"小兒外科","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"睪丸畸胎瘤（teratoma）病童，如果血中腫瘤標誌胎兒蛋白（α-fetoprotein）升高時，此腫瘤可能含有那種惡性成分？","options":["(A) 卵黃囊瘤（yolk sac tumor）","(B) 肝細胞癌(hepatocellular carcinoma )","(C) 消化道腺癌（adenocarcinoma）","(D) 神經母細胞瘤（neuroblastoma）"],"answer":0,"image":""},{"id":"md5-105-1-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"有關大腸生理功能的說明，下列何者錯誤？","options":["(A) 人體所放出的flatus，以吸入之大氣空氣為主","(B) 關於大腸癌好發在遠端大腸，有一說法是因為遠端大腸較缺乏醣類，所以遠端大腸的細菌主要行蛋白質putrefactive process，容易堆積毒素所造成的","(C) short-chain fatty acids（包含acetate, propionate和butyrate）對於大腸細胞是很重要的物質，可以幫助正常細胞生長和抑制癌細胞生長的功能","(D) 食用纖維（dietary fiber）中，water-soluble的可以被腸道細菌分解產生short-chain fatty acid，water-insoluble可以利用來治療便秘"],"answer":0,"image":""},{"id":"md5-105-1-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"105年第1次第51題","year":105,"session":1,"number":51,"question":"關於糞便潛血（fecal occult blood testing，FOBT）的敘述，何者錯誤？","options":["(A) 對沒有危險因子的民眾是很好的大腸直腸癌篩檢工具","(B) 藉由免疫反應檢測的糞便潛血其專一性較氧化還原法的糞便潛血檢測為高","(C) 因為血球蛋白會在上消化道被破壞，所以免疫反應檢測的糞便潛血是來自於大腸或直腸的出血","(D) 糞便潛血檢驗前三天都必須要避免紅肉的攝取"],"answer":3,"image":""},{"id":"md5-105-1-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"105年第1次第52題","year":105,"session":1,"number":52,"question":"克隆氏疾病（Crohn's disease）最常見的症狀為何？","options":["(A) 腹瀉及腹痛","(B) 直腸流血","(C) 肛門膿瘍","(D) 腸道皮膚廔管"],"answer":0,"image":""},{"id":"md5-105-1-53","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"105年第1次第53題","year":105,"session":1,"number":53,"question":"病人經檢查後發現為第3期直腸癌，下列何者為現階段之治療選項？","options":["(A) 術前單獨放射線治療","(B) 術前單獨化學藥物治療","(C) 術前放射線合併化學藥物治療","(D) 直接手術切除治療"],"answer":2,"image":""},{"id":"md5-105-1-54","subject":"md5","topic":"整形重建外科","meta":"105年第1次第54題","year":105,"session":1,"number":54,"question":"急診來一名左姆指掌指骨關節metacarpophalangeal joint完全截肢傷，該斷指可承受的warm ischemia time為：","options":["(A) 2小時","(B) 4小時","(C) 8小時","(D) 12小時"],"answer":[2,3],"image":"","answer_note":"更正:第54題答Ｃ、Ｄ給分"},{"id":"md5-105-1-55","subject":"md5","topic":"整形重建外科","meta":"105年第1次第55題","year":105,"session":1,"number":55,"question":"承上題，若該斷指經生理食鹽水溼紗包於密封塑膠袋再放入冰水中，該斷指可以承受最長的cold ischemia time為：","options":["(A) 4小時","(B) 8小時","(C) 12小時","(D) 24小時"],"answer":[2,3],"image":"","answer_note":"更正:第55題答Ｃ、Ｄ給分。"},{"id":"md5-105-1-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第1次第56題","year":105,"session":1,"number":56,"question":"有關良性骨腫瘤之敘述，下列何者錯誤？","options":["(A) 骨軟骨瘤（osteochondroma）是常見的良性骨骼腫瘤，往往不須手術切除，亦不會有惡性變化的機會","(B) 骨樣骨瘤（osteoid osteoma）大多發生在青少年，手術時切除腫瘤中之病巢（nidus），即可解決疼痛","(C) 動脈瘤性骨囊腫（aneurysmal bone cyst）好發於青少年，可於電腦斷層攝影下發現fluid-fluid level現象","(D) 單純性骨囊腫（simple bone cyst）好發於肱骨及股骨近端"],"answer":0,"image":""},{"id":"md5-105-1-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"105年第1次第57題","year":105,"session":1,"number":57,"question":"下列關於鎖骨中段骨折（midshaft clavicular fracture）與鎖骨遠端骨折（distal clavicular fracture）之敘述，何者錯誤？","options":["(A) 鎖骨遠端骨折（distal clavicular fracture）比鎖骨中段骨折（midshaft clavicular fracture）常見","(B) 鎖骨遠端骨折（distal clavicular fracture）接受保守治療的不癒合率（nonunion rate）比鎖骨中段骨折（midshaft clavicular fracture）高","(C) 大部分的鎖骨中段骨折（midshaft clavicular fracture）使用保守治療，可獲得不錯的癒合率（union rate）","(D) 根據Neer’s classification，在第二型鎖骨遠端骨折（type II distal clavicular fracture）中，喙鎖韌帶（coracoclavicular ligament）會從近端骨段剝離"],"answer":0,"image":""},{"id":"md5-105-1-58","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"105年第1次第58題","year":105,"session":1,"number":58,"question":"關於髕骨骨折（patellar fracture），下列敘述何者錯誤？","options":["(A) 大部分髕骨骨折（patellar fracture）發生的原因，是遭受到直接外力（direct forces）撞擊；間接外力（indirect forces）造成的髕骨骨折較少","(B) 若骨折沒有移位，且股四頭肌的直伸機轉沒有受損（nondisplaced fractures with intact extensor mechanism of quadriceps），可採用非手術治療","(C) 若骨折有移位，應考慮採用手術治療。手術治療的方式很多，其中以全髕骨切除手術（total patellectomy）的治療效果最好","(D) 髕骨骨折術後應盡早接受物理治療，以恢復膝關節之功能性活動範圍（functional range of motion）"],"answer":2,"image":""},{"id":"md5-105-1-59","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第1次第59題","year":105,"session":1,"number":59,"question":"3歲男童，父母因他左手掌無法外翻向上捧碗吃飯，帶來求診，並接受X光檢查，由症狀及X光影像顯示下列何者是最可能的診斷？","options":["(A) 先天橈骨頭脫臼（congenital radial head dislocation）","(B) 臂神經叢產程傷害（brachial plexus birth injury）","(C) 先天橈尺骨黏合（congenital radioulnar synostosis）","(D) 蒙特基亞氏骨折（Monteggia’s fracture）"],"answer":2,"image":"md5-105-1-59.jpeg"},{"id":"md5-105-1-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第1次第60題","year":105,"session":1,"number":60,"question":"肘隧道症候群（cubital tunnel syndrome），是下列那一條神經受到壓迫？","options":["(A) 正中神經（median nerve）","(B) 橈神經（radial nerve）","(C) 肌皮神經（musculocutaneous nerve）","(D) 尺神經（ulnar nerve）"],"answer":3,"image":""},{"id":"md5-105-1-61","subject":"md5","topic":"神經外科","meta":"105年第1次第61題","year":105,"session":1,"number":61,"question":"一位60歲的女性，有嚴重的下背痛且行走困難。脊椎X光檢查顯示第四、五腰椎椎莖（pedicle）完整、椎間盤空隙變窄（disc space narrowing）、椎體終板破壞（endplate erosion）。依照X光結果判斷，下列何者是最適當的診斷？","options":["(A) 惡性腫瘤轉移","(B) 椎間盤退化性病變","(C) 脊椎感染","(D) 脊椎滑脫症"],"answer":2,"image":""},{"id":"md5-105-1-62","subject":"md5","topic":"神經外科","meta":"105年第1次第62題","year":105,"session":1,"number":62,"question":"一位40歲的男性，有頸部疼痛酸麻且會延伸到左側前臂及手掌中指部位。病患步態穩定，肌力完整，左側三頭肌（triceps）之深層肌腱反射，有減弱狀況。初步的診斷為頸椎椎間盤突出合併神經壓迫，最可能的病灶為何？","options":["(A) 第三、四頸椎椎間盤","(B) 第四、五頸椎椎間盤","(C) 第五、六頸椎椎間盤","(D) 第六、七頸椎椎間盤"],"answer":3,"image":""},{"id":"md5-105-1-63","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"105年第1次第63題","year":105,"session":1,"number":63,"question":"有關骨盆（pelvis）及骨盆骨折相關之敘述，下列何者正確？","options":["(A) 在坐姿時，上半身之重力主要由髖關節（hip joint）承受","(B) 骨盆x-ray檢查中之pelvic outlet projection對判斷半側骨盆（hemipelvis）內轉或外轉變化很有幫忙","(C) 就受傷機轉及流行病學角度而言，骨盆骨折最常見的為外側壓迫性傷害（lateral compression）造成之骨折","(D) 骨盆骨折，若恥骨聯合分離超過1公分，為手術治療之適應症"],"answer":2,"image":""},{"id":"md5-105-1-64","subject":"md5","topic":"泌尿-結石與感染","meta":"105年第1次第64題","year":105,"session":1,"number":64,"question":"下列何者腎小管酸中毒症（renal tubular acidosis）會併發腎結石？","options":["(A) Type I","(B) Type II","(C) Type III","(D) Type IV"],"answer":0,"image":""},{"id":"md5-105-1-65","subject":"md5","topic":"泌尿-腫瘤","meta":"105年第1次第65題","year":105,"session":1,"number":65,"question":"下列有關腎細胞癌（renal cell carcinoma）接受根治性手術治療的敘述，何者正確？","options":["(A) 不論腫瘤長在腎臟任何位置，同側之腎上腺均必須一併切除","(B) 腎門附近之淋巴腺組織是否須一併清除，目前尚未定論","(C) 腎臟腫瘤如未切除乾淨，術後再加上局部放射治療，可以有效地延長病人之存活","(D) 術前每人應均先接受腎動脈栓塞，因為這樣可以有效地減少術中出血"],"answer":1,"image":""},{"id":"md5-105-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"105年第1次第66題","year":105,"session":1,"number":66,"question":"表淺性膀胱癌在診斷時若膀胱內同時有多處大小不一的腫瘤，經尿道切除（transurethral resection）後，若不做膀胱內灌注療法預防再發，則復發率約為多少?","options":["(A) 1～2成","(B) 3～4成","(C) 5～6成","(D) 7～8成"],"answer":3,"image":""},{"id":"md5-105-1-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"105年第1次第67題","year":105,"session":1,"number":67,"question":"前列腺肥大病患接受經尿道前列腺切除手術時，出現意識迷糊、噁心、高血壓、心跳變慢等症狀，其最可能之原因是：","options":["(A) 敗血症（sepsis）","(B) 出血性休克（hemorrhagic shock）","(C) 深部靜脈血栓（deep vein thrombosis）","(D) 經尿道切除症候群（transurethral resection syndrome）"],"answer":3,"image":""},{"id":"md5-105-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"105年第1次第68題","year":105,"session":1,"number":68,"question":"一位55歲男性來到急診，主訴膀胱脹，頻尿，但是尿不出來，用力也只能擠出3至5毫升的尿，急診的值班醫師欲為其導尿，下列何者最不可能或最不適當？","options":["(A) 如果導出500毫升尿液，病人可能是前列腺肥大，造成急性尿滯留（acute urinary retention）","(B) 病人得了急性膀胱炎，需要導尿，取得尿液做細菌培養","(C) 如果病人有發燒，小便疼痛，可能得了急性前列腺炎，最好不要導尿，可以先做下腹部超音波掃描","(D) 如果只導出10毫升的尿液，身體檢查下腹部也不脹，病人可能有輸尿管末端（UVJ）結石"],"answer":1,"image":""},{"id":"md5-105-1-69","subject":"md5","topic":"泌尿-結石與感染","meta":"105年第1次第69題","year":105,"session":1,"number":69,"question":"有關急性細菌性副睪丸炎之敘述，下列何者錯誤？","options":["(A) 如果細菌培養結果顯示與性傳染病有關，最好其性伴侶也要治療，以免重複感染（re-infection）","(B) 反覆發生的副睪丸炎及疼痛，可以考慮副睪丸及睪丸切除術，不能只切除副睪丸","(C) 急性期時尿中及血液中之白血球常會上升","(D) 除非發生明顯全身性症狀（constitutional symptoms），如發燒、寒顫或敗血症，一般來說，口服抗生素就足夠"],"answer":1,"image":""},{"id":"md5-105-1-70","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"105年第1次第70題","year":105,"session":1,"number":70,"question":"60歲丁先生，由於勃起時硬度夠，但無法持久而來就診，陰莖海綿體血流量檢查發現其海綿體動脈血流正常，但有靜脈溢漏（venous leakage）現象，最可能的病因是：","options":["(A) 陰莖海綿體神經病變","(B) 良性前列腺肥大","(C) 陰莖海綿體平滑肌病變","(D) 尿道炎"],"answer":2,"image":""},{"id":"md5-105-1-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"105年第1次第71題","year":105,"session":1,"number":71,"question":"逆行性射精（retrograde ejaculation）的病理變化是：","options":["(A) 無法達到性高潮","(B) 射精的收縮力道不夠","(C) 膀胱頸無法收縮或關閉","(D) 精液量不夠導致無法由尿道排出"],"answer":2,"image":""},{"id":"md5-105-1-72","subject":"md5","topic":"泌尿-腫瘤","meta":"105年第1次第72題","year":105,"session":1,"number":72,"question":"46歲林先生因排解血尿而到醫院檢查，他並沒有其他不舒適症狀。醫師為他做IVU檢查顯示膀胱異常，又進一步做CT檢查，病變如圖示。林先生最可能患了什麼病？","options":["(A) 膀胱結石","(B) 膀胱炎","(C) 膀胱癌","(D) 攝護腺肥大"],"answer":2,"image":"md5-105-1-72.jpeg"},{"id":"md5-105-1-73","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第1次第73題","year":105,"session":1,"number":73,"question":"15歲車禍傷患主訴左上腹部劇痛，而且逐漸呈現休克狀態。電腦斷層檢查如附圖。箭頭所指之異常最符合下列那一項診斷？","options":["(A) spleen laceration","(B) pancreas laceration","(C) kidney laceration","(D) diaphragm laceration"],"answer":0,"image":"md5-105-1-73.jpeg"},{"id":"md5-105-1-74","subject":"md5","topic":"骨科-關節重建","meta":"105年第1次第74題","year":105,"session":1,"number":74,"question":"51歲男性病人主訴右髖關節疼痛數年，髖關節X光片如附圖，最有可能的診斷為：","options":["(A) subchondral cyst","(B) bone metastasis","(C) osteomyelitis","(D) avascular necrosis"],"answer":3,"image":"md5-105-1-74.jpeg"},{"id":"md5-105-1-75","subject":"md5","topic":"胸腔外科","meta":"105年第1次第75題","year":105,"session":1,"number":75,"question":"47歲男性，右胸部遭槍擊造成血胸合併休克，胸管引流出600 ml血液後，血壓恢復為122/84 mmHg，脈搏96次/分，5分鐘後血壓下ཋ為84/62 mmHg，脈搏126次/分，下列何者為最優先的處理步驟？","options":["(A) ઄即執ཊ氣管內管插管","(B) 緊急開胸手術","(C) 再插另一支胸管","(D) 重新評估病人"],"answer":3,"image":""},{"id":"md5-105-1-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第1次第76題","year":105,"session":1,"number":76,"question":"50歲男性，體重70公斤，被熱水燙傷造成頭頸部、胸部及背部約40%面積的二ล燙傷，被送往急診室接受治療，下列處置何者不適當？","options":["(A) 依Parkland公式前8小時給予5.6公升的林格氏乳酸液","(B) 給予烤燈避免低體溫","(C) 可給予白蛋白（albumin）治ऋ","(D) 冷水沖洗約30分鐘"],"answer":1,"image":""},{"id":"md5-105-1-77","subject":"md5","topic":"胸腔外科","meta":"105年第1次第77題","year":105,"session":1,"number":77,"question":"一位36歲男性工人，不幸被一塊掉下來的石頭打到胸骨下方，一小時後被送到醫院來，病人主述胸部疼痛，X光檢查發現左側第八根肋骨骨折，經止痛後病人仍感到胸部不舒服，病人最不可能有什麼傷害？","options":["(A) 肺葉破裂","(B) 氣管破裂","(C) 大血管破裂","(D) 橫膈膜破裂"],"answer":2,"image":""},{"id":"md5-105-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"105年第1次第78題","year":105,"session":1,"number":78,"question":"陳老先生罹患肝細胞癌，於接受肝動脈栓塞治療術後半個小時，發生意識障礙的情況，經電腦斷層檢查發現腦部血管栓塞的現象，疑似肝動脈栓塞時所打進的藥物，部分流到腦部血管所致。因為腦中風的範圍相當廣泛，陳老先生隨即發生呼吸衰竭，隨後病況不斷惡化，最後死亡。肝動脈栓塞治療術所導致的腦栓塞個案相當罕見，對於這種很少見，但最後致命的併發症，依照目前相關法規或者法院的看法，是否屬於應該告知的範圍？","options":["(A) 屬於應該告知的併發症範圍，因為該併發症相當罕見，所以應該告知","(B) 屬於應該告知的併發症範圍，該併發症雖然罕見，但是其發生後的後果相當嚴重，應該告知","(C) 不屬於應該告知的併發症範圍，因為過於罕見","(D) 不屬於應該告知的併發症範圍，因為如果告知該併發症，病患就會決定不接受肝動脈栓塞治療術"],"answer":1,"image":""},{"id":"md5-105-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"105年第1次第79題","year":105,"session":1,"number":79,"question":"陳先生今年75歲，是原住民，發生左側硬腦膜下出血併腦幹壓迫，在順利接受血塊移除手術後被送到加護病房觀察。術後第3天醒來，第5天順利拔管後，他看起來焦慮，說著聽不懂的話語，不斷地想下床。當班的外科醫師應該如何處置？","options":["(A) 開顱手術術後病人本來就會神智不清，給予手腳約束，維護病人安全，免得陳先生亂拔管路","(B) 為了讓護理師比較好照顧，給予鎮靜劑讓陳先生不要那麼躁動","(C) 先請懂得原住民話語的同鄉或家屬聽聽說話的內容，試圖了解他的需求","(D) 陳先生此時應該算無行為能力，做必要的醫療處置如更換中央靜脈導管前不需要和他溝通"],"answer":2,"image":""},{"id":"md5-105-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"105年第1次第80題","year":105,"session":1,"number":80,"question":"有關病歷的記錄與修改，下列敘述何者錯誤？","options":["(A) 醫師應親自記載病歷或製作紀錄，簽名或蓋章及加註年月日","(B) 病歷或紀錄如有增刪，應於增刪處簽名或蓋章及加註年月日","(C) 病歷修改的部分，基於美觀及醫院評鑑的需要，可以修正帶或立可白塗銷塗毀","(D) 配偶代為申請病歷，即便身分確認，仍應有委託書"],"answer":2,"image":""},{"id":"md5-105-2-1","subject":"md5","topic":"小兒外科","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"小兒甲狀腺舌骨囊腫（thyroglossal duct cyst），為了減少復發，手術中除了囊腫外，還要切除那個結構的中央部分？","options":["(A) 甲狀軟骨（thyroid cartilage）","(B) 環狀軟骨（cricoid cartilage）","(C) 舌骨（hyoid bone）","(D) 杓狀軟骨（arytenoid cartilage）"],"answer":2,"image":""},{"id":"md5-105-2-2","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"下列敘述，何者正確？","options":["(A) 植入物（prosthesis）相關的感染通常發生在肺部","(B) 手術後發燒需立即給予抗生素","(C) 尿路感染（urinary tract infection）是手術後最常見的非手術感染（nonsurgical infection）","(D) 選擇抗生素做經驗性治療（empirical treatment）時，最好是同時使用抗厭氧菌的抗生素"],"answer":2,"image":""},{"id":"md5-105-2-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"嚴重外傷之病患，術後需要足量營養補充，以維持各項生理功能與組織復原。營養補充是否足夠，可藉由下列各種生化檢定來評估，何者除外？","options":["(A) 白蛋白（albumin）","(B) 球蛋白（globulin）","(C) 前白蛋白（prealbumin）","(D) 轉鐵蛋白（transferrin）"],"answer":1,"image":""},{"id":"md5-105-2-4","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"嚴重多重外傷病患經積極治療及手術後，如能夠存活超過一星期，最常見之晚期死亡原因為何？","options":["(A) 嚴重頭部外傷","(B) 多重器官衰竭","(C) 出血性休克","(D) 急性腎衰竭"],"answer":1,"image":""},{"id":"md5-105-2-5","subject":"md5","topic":"消化器外科","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"有關高齡病人急性闌尾炎（acute appendicitis）之敘述，下列何者錯誤？","options":["(A) 發生急性闌尾炎之機率，較年輕人高","(B) 較年輕族群症狀表現較不典型，診斷容易延遲","(C) 較年輕族群，穿孔（perforation）機率大，合併症較多","(D) 與盲腸憩室炎（cecal diverticulitis）鑑別診斷不易"],"answer":0,"image":""},{"id":"md5-105-2-6","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"有關全身性發炎反應症候群SIRS（systemic inflammatory response syndrome）的定義，下列何者錯誤？","options":["(A) 心跳每分鐘大於90下","(B) 收縮壓小於90 mmHg","(C) 在正常呼吸下呼吸速率每分鐘大於20下或是血液中二氧化碳分壓（PaCO2）小於32 mmHg","(D) 白血球大於12,000 cells/mm3或小於4000 cells/mm3或在周邊血液抹片有大於10% immature（Band）cells"],"answer":1,"image":""},{"id":"md5-105-2-7","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"42歲男性病人有低血壓並懷疑有敗血症，接受中央靜脈導管（central venous catheter）插入後應如何給予輸液？","options":["(A) 輸注晶體輸液（crystalloid fluid）100毫升／小時","(B) 輸注晶體輸液（crystalloid fluid）200毫升／小時","(C) 輸注晶體輸液（crystalloid fluid）500毫升／15分鐘，如果仍為低血壓而且中央靜脈壓力（CVP）＜8〜12 mmHg時，再給予500毫升的輸液","(D) 輸注晶體輸液（crystalloid fluid）500毫升／15分鐘，如果仍為低血壓而且中央靜脈壓力（CVP）＞15 mmHg時，再給予500毫升的輸液"],"answer":2,"image":""},{"id":"md5-105-2-8","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"導致手術部位感染（surgical site infections）的危險因子，下列何者錯誤？","options":["(A) 手術部位有血腫","(B) 低氧血症","(C) 不抽菸的年輕病人","(D) 營養不良"],"answer":2,"image":""},{"id":"md5-105-2-9","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"下列關於癌症和它的腫瘤標記（tumor markers）之配對，何者錯誤？","options":["(A) carbohydrate antigen 19-9（CA19-9）and ovarian cancer","(B) alpha fetoprotein（AFP）and hepatocellular carcinoma","(C) carcinoembryonic antigen（CEA）and colon cancer","(D) human chorionic gonadotropin（HCG）and choriocarcinoma"],"answer":0,"image":""},{"id":"md5-105-2-10","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"下列有關腕隧道症候群（carpal tunnel syndrome）的描述，何者錯誤？","options":["(A) 由腕隧道經過的神經為橈神經（radial nerve）","(B) Tinel's sign positive","(C) 病人若出現魚際肌（thenar muscle）萎縮或無力代表嚴重的運動神經壓迫","(D) 可透過神經傳導速度（nerve conduction velocity）檢查來確定診斷"],"answer":0,"image":""},{"id":"md5-105-2-11","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"下列有關神經性休克（neurogenic shock）之敘述，何者錯誤？","options":["(A) 低血壓","(B) 心跳慢","(C) 周邊血管灌流變差","(D) 可使用α agonist治療"],"answer":2,"image":""},{"id":"md5-105-2-12","subject":"md5","topic":"神經外科","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"下列有關脊髓的感覺神經分布之配對，何者正確？","options":["(A) T4－腋下","(B) T6－乳頭附近","(C) T10－肚臍周圍","(D) L5－腳踝外側"],"answer":2,"image":""},{"id":"md5-105-2-13","subject":"md5","topic":"神經外科","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"下列何者是最常見之脊椎硬脊膜上轉移（spinal epidural metastasis）初期症狀？","options":["(A) 神經根病變（radiculopathy）","(B) 局部疼痛（local pain）","(C) 尿液滯留（urinary retension）","(D) 下肢麻木（numbness of lower limbs）"],"answer":1,"image":""},{"id":"md5-105-2-14","subject":"md5","topic":"神經外科","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"下列腦膜瘤（meningiomas）中，何者不由內頸動脈（internal carotid artery）供應血流？","options":["(A) 嗅溝腦膜瘤（olfactory groove meningioma）","(B) 蝶骨翼腦膜瘤（sphenoid wing meningioma）","(C) 側腦室腦膜瘤（lateral ventricle meningioma）","(D) 顱凸處腦膜瘤（cranial convexity meningioma）"],"answer":3,"image":""},{"id":"md5-105-2-15","subject":"md5","topic":"神經外科","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"根據Hunt and Hess SAH classification，一個蜘蛛膜下腔出血（SAH）病人，臨床上只有輕微頭痛及輕微頸部僵硬，且無其他神經學檢查異常（focal neurological deficit），其grade應為下列何者？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":0,"image":""},{"id":"md5-105-2-16","subject":"md5","topic":"神經外科","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"下列有關腦部偽腫瘤（pseudotumor cerebri）的敘述，何者錯誤？","options":["(A) 常伴隨腦室變大","(B) 腦壓增高，作腰椎穿刺壓力往往超過200 mmH2O","(C) 會有視乳突水腫（papilledema）","(D) 內科治療以類固醇及利尿劑為主"],"answer":0,"image":""},{"id":"md5-105-2-17","subject":"md5","topic":"整形重建外科","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"17歲的陳大雄左手腕背面摸到一顆突起腫瘤，媽媽帶他到整形外科門診求診時，醫師會跟他說這顆腫瘤最常見是什麼？","options":["(A) 腱鞘囊腫（ganglion cyst）","(B) 巨大細胞瘤（giant cell tumor）","(C) 脂肪瘤（lipoma）","(D) 內生軟骨瘤（enchondroma）"],"answer":0,"image":""},{"id":"md5-105-2-18","subject":"md5","topic":"整形重建外科","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"神經的損傷依據Sunderland的分類可以分為幾類？","options":["(A) 三","(B) 四","(C) 五","(D) 六"],"answer":[2,3],"image":"","answer_note":"更正:第18題答Ｃ、Ｄ給分"},{"id":"md5-105-2-19","subject":"md5","topic":"整形重建外科","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"大部份血管瘤（hemangioma）在多少歲開始退化？","options":["(A) 1個月","(B) 3～6個月","(C) 6～9個月","(D) 12～18個月"],"answer":3,"image":""},{"id":"md5-105-2-20","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"下列關於燒燙傷深度（burn depths）的判斷，下列敘述何者錯誤？","options":["(A) 國中生到海水浴場玩，被太陽曬傷造成背部發紅及疼痛。發紅的皮膚受到壓迫會變白（blanch to the touch），壓力釋放後又變紅。這是一度燒燙傷","(B) 老人家燒熱水洗澡。水太熱又忘了加冷水。一腳踏進浴缸的熱水裡被燙傷。患處皮膚蒼白、起水泡、受到壓迫不變色（do not blanch to touch），但是碰觸尖細物品仍會疼痛（painful to pinprick）。這是淺二度燒燙傷","(C) 機車騎士出車禍。小腿遠端內側被灼熱的排氣管壓住造成灼傷。患處皮膚形成不痛的皮革狀焦痂（leathery eschar），這是三度燒燙傷","(D) 情侶分手，女方極度沮喪而燒炭自殺。女方昏迷後被發現，送醫成功挽回生命。但患者在燒炭昏迷的過程中，右腳太靠近炭火，連肌肉都被烤焦了。這是四度燒燙傷"],"answer":1,"image":""},{"id":"md5-105-2-21","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"關於褥瘡的分級，下列敘述何者錯誤？","options":["(A) 第一級，皮膚完整但出現下壓不會反白的發紅區","(B) 第二級，部分皮層缺損，呈現表淺性潰瘍，臨床上可看到擦傷、水泡、淺的火山口狀傷口","(C) 第三級，部分皮層缺損，可看到組織被破壞與壞死","(D) 第四級，全皮層缺損，可看到組織被嚴重破壞與壞死，壞死深及肌肉層、骨骼、支持性結構"],"answer":2,"image":""},{"id":"md5-105-2-22","subject":"md5","topic":"整形重建外科","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"與顯微組織皮瓣（microvascular free flaps）比較之下，局部皮瓣（local flaps）有下列限制，何者錯誤？","options":["(A) 局部皮瓣（local flaps）的覆蓋範圍是受限制的","(B) 局部皮瓣（local flaps）的遠端之血液循環可能不好","(C) 在外傷的情況下局部皮瓣（local flaps）可能受傷，不一定可靠","(D) 老人的局部皮瓣（local flaps）與年輕病患的局部皮瓣一樣可靠"],"answer":3,"image":""},{"id":"md5-105-2-23","subject":"md5","topic":"心臟血管外科","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"下列關於心臟瓣膜疾病，何者正確？①暈厥（syncope）為重度主動脈瓣狹窄之手術適應症之一 ②僧帽瓣修補術可用於擴張性心肌症（dilated cardiomyopathy）患者的手術治療 ③心臟移植手術可用於心臟瓣膜疾病患的手術治療 ④僧帽瓣修補的手術死亡率比僧帽瓣置換術的手術死亡率高","options":["(A) ①②③","(B) 僅①③","(C) ②④","(D) 僅④"],"answer":0,"image":""},{"id":"md5-105-2-24","subject":"md5","topic":"心臟血管外科","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"關於冠狀動脈繞道手術，下列何者之長期暢通率（long-term patency rate）最差？","options":["(A) 右內胸動脈（right internal thoracic artery）","(B) 大隱靜脈（greater saphenous vein）","(C) 右網膜動脈(right gastroepiploic artery)","(D) 左橈動脈（left radial artery）"],"answer":1,"image":""},{"id":"md5-105-2-25","subject":"md5","topic":"心臟血管外科","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"下列有關開心手術術中的心肌保護，何者錯誤？","options":["(A) 心臟一旦停止跳動，需留滯大量血液在腔室內，使含氧血可經由心內膜進入心肌細胞，達到心肌保護的效果","(B) 心肌保護液為高鉀離子之溶液，可降低心肌細胞的代謝","(C) 藉由體外循環的全身血液降溫以及心臟冰浴，可達到心肌保護的效果","(D) 心肌保護液可以藉由順行性或逆行性路徑灌注心肌細胞，兩者皆可達到心肌保護的效果"],"answer":0,"image":""},{"id":"md5-105-2-26","subject":"md5","topic":"心臟血管外科","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"有關大動脈轉位伴隨正常心室中隔（transposition of great arteries with intact ventricular septum）之敘述，下列何者正確？ ①prostaglandin E1靜脈輸注可增加肺動脈血流量 ②心房中隔氣球打洞術（balloon atrial septostomy）無法改善動脈血氧飽和度（oxygen saturation） ③大動脈移轉手術（arterial switch operation）之最佳時機為出生後一至二星期內 ④手術前確實瞭解冠狀動脈之分布情況是大動脈移轉手術的成敗關鍵","options":["(A) ①②","(B) ①③","(C) ②④","(D) 僅④"],"answer":1,"image":""},{"id":"md5-105-2-27","subject":"md5","topic":"胸腔外科","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"一位20歲男性因持續性胸痛2個月求診，胸部X-ray及電腦斷層檢查顯示：前縱隔腔腫瘤併主動脈侵犯，alpha-fetoprotein和beta-HCG為正常，下列何者錯誤？","options":["(A) 應先切除腫瘤，之後要以化學治療為輔助性治療（adjuvant treatment）","(B) 治療前應先做切片檢查","(C) 應檢查生殖腺是否有病變","(D) 這種腫瘤對放射線治療可能有反應"],"answer":0,"image":""},{"id":"md5-105-2-28","subject":"md5","topic":"胸腔外科","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"有關adenoid cystic carcinoma of lung之敘述，下列何者正確？①大部分發生於肺周邊組織 ②大部分腫瘤的治療以局部氣管手術切除即可 ③大部分腫瘤都是以局部生長緩慢的氣管支氣管病灶為表現 ④腫瘤絕不會有遠端轉移的現象","options":["(A) ①②","(B) ②③④","(C) ①③④","(D) 僅②③"],"answer":3,"image":""},{"id":"md5-105-2-29","subject":"md5","topic":"胸腔外科","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"關於食道弛緩不能（esophageal achalasia）的外科手術，下列何者正確？①可經由開胸與開腹手術施行 ②大部分必須施行食道切除與重建手術才能解決吞嚥困難的問題 ③下食道括約肌的肌肉切開術是最常使用的方法 ④胃底折疊手術（fundoplication）有助於減少術後胃液逆流的產生","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":3,"image":""},{"id":"md5-105-2-30","subject":"md5","topic":"胸腔外科","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"有關pectus excavatum（funnel chest）的手術矯正時機，下列何者最正確？","options":["(A) 剛出生時","(B) 2～8歲","(C) 成年之後","(D) 12～18歲"],"answer":[1,2,3],"image":"","answer_note":"更正:第30題答Ｂ、Ｃ、Ｄ給分"},{"id":"md5-105-2-31","subject":"md5","topic":"消化器外科","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"急性膽管炎指的是膽道系統細菌性感染，臨床症狀從輕微自癒到危及生命都有可能，何者非Charcot’s triad？","options":["(A) 發燒（fever）","(B) 黃疸（jaundice）","(C) 腹痛（abdominal pain）","(D) 意識譫妄（delirium）"],"answer":3,"image":""},{"id":"md5-105-2-32","subject":"md5","topic":"消化器外科","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"下列有關Mallory-Weiss tears之敘述，何者錯誤？","options":["(A) 常常需要外科手術止血","(B) 可以用endoscope確診","(C) 病人大部分為男性","(D) 典型的位置位於胃小彎（lesser curvature）靠近食道與胃交界處（esophagogastric junction）"],"answer":0,"image":""},{"id":"md5-105-2-33","subject":"md5","topic":"消化器外科","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"有關於消化性潰瘍（peptic ulcer)的分泌之敘述，何者錯誤？","options":["(A) 致病原因（pathogenesis)包括幽門螺旋桿菌感染（Helicobacter pylori infection），非類固醇性抗發炎藥（nonsteroidal anti- inflammatory drugs，NSAID）及胃酸（gastric acid）","(B) 90%的十二指腸潰瘍（duodenal ulcer）及75%的胃潰瘍（gastric ulcer）是和幽門螺旋桿菌感染（Helicobacter pylori infection）有關","(C) 胃潰瘍的病人較常見的分泌異常（secretory abnormalities）有重碳酸鹽分泌減少（decreased bicarbonate secretion），夜間胃酸分泌增加（increased nocturnal acid secretion）及日間胃酸分泌增加（increased daytime acid secretion）","(D) 胃酸過度分泌（gastric acid hypersecretion）在type II及type III的胃潰瘍病人比type I及type IV的胃潰瘍病人較常見"],"answer":2,"image":""},{"id":"md5-105-2-34","subject":"md5","topic":"消化器外科","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"急性胰臟炎局部合併症中，下列何者最不常見？","options":["(A) pancreatic phlegmon","(B) pancreatic abscess","(C) pancreatic pseudocyst","(D) renal artery thrombosis"],"answer":3,"image":""},{"id":"md5-105-2-35","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"戴先生最近覺得腹部間歇性腹痛，並有呼吸急促的現象，抽血檢查血色素為7 mg/dL，胃內視鏡檢查發現一潰瘍腫瘤且切片檢查證實為胃腸間質瘤（gastrointestinal stromal tumor，GIST）。下列敘述何者正確？","options":["(A) 手術切除範圍包括部分胃切除與局部淋巴清除","(B) 胃腸間質瘤淋巴轉移的機率約20%","(C) 術後化學治療可以提升存活率","(D) 男性病患復發風險較女性病患高"],"answer":3,"image":""},{"id":"md5-105-2-36","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"50歲劉先生因胃癌，1個半月前接受根除性次全胃切除手術（radical subtotal gastrectomy & Billroth-II gastrojejunostomy, ante-colic，病理檢查為T2b N1M0。恢復過程順利，術後10天出院。兩天前腹部不適，3小時前開始腹痛加劇及嘔吐，急診時生命徵象穩定，但冒冷汗。身體檢查上腹部有明顯壓痛，疑似觸摸到腹部腫塊，腸蠕動增加，除serum amylase 867 U/L，WBC 16290 /mm3外，血液檢查正常。放入鼻胃管後只有少量胃液回流，此時最可能的診斷為何？","options":["(A) gastric cancer recurrence","(B) anastomotic leakage","(C) acute pancreatitis","(D) afferent loop syndrome"],"answer":3,"image":""},{"id":"md5-105-2-37","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"有關消化性潰瘍手術後的早期併發症，下列敘述何者錯誤？","options":["(A) 術後出血","(B) 縫線處滲漏（sutureline leakage）","(C) 胰臟損傷","(D) 吻合處功能遲緩（stomal delay）"],"answer":3,"image":""},{"id":"md5-105-2-38","subject":"md5","topic":"消化器外科","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"王先生因為急性胰臟炎入院，下列何者最不像是他該有的症狀或檢查結果？","options":["(A) 腹痛位於上腹並且輻射到背部","(B) 持續性嘔吐","(C) 血鈣上升","(D) 發燒"],"answer":2,"image":""},{"id":"md5-105-2-39","subject":"md5","topic":"消化器外科","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"55歲男性，一個月來食慾不振，體重減少6公斤，家人發現其小便顏色變成茶色，帶來醫院檢查，抽血發現total bilirubin level為7.8 mg/dL，direct form bilirubin level為6.9 mg/dL，腫瘤指數也升高，下列何者最不可能為病因？","options":["(A) 膽管癌","(B) 胰臟癌","(C) 空腸癌","(D) 壺腹癌"],"answer":2,"image":""},{"id":"md5-105-2-40","subject":"md5","topic":"消化器外科","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"臨床常見膽囊切除的適應症中，下列何者錯誤？","options":["(A) 膽囊息肉（polyp）>10 mm","(B) 無症狀單顆膽結石>2 cm","(C) 急性無膽結石性膽囊炎（acute acalculous cholecystitis）","(D) 有症狀之膽結石（symptomatic cholelithiasis）"],"answer":1,"image":""},{"id":"md5-105-2-41","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"有關ansa cervicalis之敘述，何者錯誤？","options":["(A) 分布於infrahyoid muscles","(B) 舌下神經（hypoglossal nerve）與第一、第二頸椎神經（C1，C2）anastomosis後形成","(C) 由下方進入sternocleidomastoid muscle","(D) radical surgery可清除"],"answer":[1,2],"image":"","answer_note":"更正:第41題答Ｂ、Ｃ給分"},{"id":"md5-105-2-42","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"38歲女性因尿毒症接受透析治療已有8年，於一年多前接受腎移植手術後情況良好，在例行檢查時發現血中intact parathyroid hormone（iPTH）濃度為205 pg/mL，血鈣為12 mg/dL，此時可診斷為：","options":["(A) 原發性副甲狀腺機能亢進（primary hyperparathyroidism）","(B) 繼發性副甲狀腺機能亢進（secondary hyperparathyroidism）","(C) 三發性副甲狀腺機能亢進（tertiary hyperparathyroidism）","(D) 復發性副甲狀腺機能亢進（recurrent hyperparathyroidism）"],"answer":2,"image":""},{"id":"md5-105-2-43","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"分化良好的甲狀腺癌其頸部淋巴結轉移，依統計以那一區最常見及那一區最少見？","options":["(A) 第一區（level I）及第二區（level II）","(B) 第三區（level III）及第四區（level IV）","(C) 第五區（level V）及第六區（level VI）","(D) 第六區（level VI）及第一區（level I）"],"answer":3,"image":""},{"id":"md5-105-2-44","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"王女士現年47歲，有乳癌的家族病史，最近接受衛生所安排乳癌篩檢。檢查後接到回信告知左側乳房有異常結果，邀請她到醫院接受進一步檢查。王女士到外科門診，她和醫師對檢查結果提出相關問題討論，下列敘述何者錯誤？","options":["(A) 乳房攝影檢查通常包含兩種檢視影像，其一為craniocaudal view，另一為mediolateral oblique view","(B) 數位式的乳房攝影相較傳統式的優點，主要是能加強判讀乳房緻密的年輕族群","(C) 乳房超音波檢查可以判斷病灶是否為實質性（solid）或囊狀性（cystic），也可以判斷病灶的外型，因此乳房超音波成為無症狀婦女篩檢乳癌的影像檢查首選","(D) 乳房磁振照影檢查則對乳房緻密的年輕患者評估病灶，如侵襲性小葉癌（invasive lobular carcinoma）的範圍很有助益"],"answer":2,"image":""},{"id":"md5-105-2-45","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"喉返神經（recurrent laryngeal nerve）受傷切斷時，何者錯誤？","options":["(A) 聲帶麻痺，處於近中央位置（paramedian）","(B) 聲音沙啞","(C) 不宜縫補受傷之神經","(D) 環狀甲狀腺肌肉（cricothyroid muscle）不會麻痺"],"answer":2,"image":""},{"id":"md5-105-2-46","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"針對乳房的Mondor’s disease最佳的處置為何？","options":["(A) 手術切除","(B) 放射線治療","(C) 荷爾蒙治療","(D) 支持性治療"],"answer":3,"image":""},{"id":"md5-105-2-47","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"35歲女性乳癌，接受乳房改良性根除性乳房切除術（modified radical mastectomy）後的病理報告為T1N2M0女性荷爾蒙接受器（estrogen receptor，ER）陰性，黃體素荷爾蒙接受器（progesterone receptor，PR）陰性，HER-2/neu陽性，下列何者是最適合的治療？","options":["(A) 不需治療","(B) 只需要放射線治療","(C) 只需要標靶治療","(D) 化學治療，標靶治療、放射線治療全部均需要"],"answer":3,"image":""},{"id":"md5-105-2-48","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"乳癌手術後，手臂內側感覺麻木乃因下列何種神經受到傷害？","options":["(A) 胸背神經（thoracodorsal nerve）","(B) 肋間肱神經（intercostobrachial nerve）","(C) 長胸神經（long thoracic nerve）","(D) 肋間神經（intercostal nerve）"],"answer":1,"image":""},{"id":"md5-105-2-49","subject":"md5","topic":"內分泌與乳房外科","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"乳癌手術執行前哨淋巴結摘取術（sentinel node biopsy）的最重要目的為何？","options":["(A) 預防乳癌再發","(B) 減少因全腋下淋巴結廓清術引起之併發症","(C) 美觀","(D) 乳房無法全切除手術才做"],"answer":1,"image":""},{"id":"md5-105-2-50","subject":"md5","topic":"小兒外科","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"有一個十個月大的男嬰，持續有嘔吐及間歇性的哭鬧；醫師檢查後發現有腹脹並在右下腹有一可觸摸到的腫塊。最可能的診斷是：","options":["(A) 闌尾炎破裂形成腫塊","(B) 腸扭轉不全（malrotation）","(C) 腸套疊（intussusception）","(D) 糞便阻塞（stool impaction）"],"answer":2,"image":""},{"id":"md5-105-2-51","subject":"md5","topic":"小兒外科","meta":"105年第2次第51題","year":105,"session":2,"number":51,"question":"有關兒童腹股溝疝氣（inguinal hernia）的敘述，下列何者正確？①早產兒發生率較高 ②多為直接型疝氣（direct type） ③ 手術以疝氣袋高位結紮為主 ④手術年齡需大於一歲","options":["(A) ②④","(B) 僅①③","(C) ①③④","(D) ①②③"],"answer":1,"image":""},{"id":"md5-105-2-52","subject":"md5","topic":"小兒外科","meta":"105年第2次第52題","year":105,"session":2,"number":52,"question":"關於總膽管囊腫（choledochal cyst）的敘述，下列何者錯誤？","options":["(A) 女性的比例較高","(B) 手術的方法以囊腫全切除併Roux-en-Y膽管空腸吻合","(C) 很少有黃疸（jaundice）的現象","(D) 若不全切除囊腫，日後有惡性變化的可能"],"answer":2,"image":""},{"id":"md5-105-2-53","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"105年第2次第53題","year":105,"session":2,"number":53,"question":"針對肛門灰形溼疣（condyloma acuminatum），目前最廣用且有效的治療方式為下列那一項？","options":["(A) CO2雷射","(B) interferon-β的局部注射","(C) podophyllin或dichloroacetic acid的局部腐蝕","(D) 局部切除加上電燒灼"],"answer":3,"image":""},{"id":"md5-105-2-54","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"105年第2次第54題","year":105,"session":2,"number":54,"question":"關於人工肛門（ostomies）的敘述，何者錯誤？","options":["(A) 人工肛門的位置對病人的生活品質很重要","(B) 人工肛門應被置於腹直肌內並且容易被肉眼所見及方便操作","(C) 人工肛門應避免被置於先前手術的疤痕處及骨頭凸出的位置","(D) 直腸癌的患者術後都需要永久性人工肛門"],"answer":3,"image":""},{"id":"md5-105-2-55","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"105年第2次第55題","year":105,"session":2,"number":55,"question":"關於痔瘡（hemorrhoid）的敘述，何者錯誤？","options":["(A) 痔瘡是肛門黏膜下的構造其中包含動靜脈及平滑肌等組織","(B) 在維持肛門括約方面扮演重要角色","(C) 痔瘡切除術可用在保守治療無效的病患","(D) 所有的痔瘡都需要手術治療"],"answer":3,"image":""},{"id":"md5-105-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第2次第56題","year":105,"session":2,"number":56,"question":"14歲男孩主訴於右大腿出現逐漸長大的腫瘤約一年。病史詢問發現局部有痛感，尤其久站後疼痛明顯，經診斷為肌肉內血管瘤（intramuscular hemangioma）。有關診斷、預後及處置之敘述，下列何者最正確？","options":["(A) 大部分腫瘤還會繼續增大造成肢體變形","(B) 往往需要手術切除以解決疼痛","(C) 可能發生遠處轉移","(D) 腫瘤越深層愈不易診斷，易誤判為惡性腫瘤"],"answer":3,"image":""},{"id":"md5-105-2-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"105年第2次第57題","year":105,"session":2,"number":57,"question":"58歲女性病患，跌倒後導致右側遠端橈骨骨折（distal radius fracture），在急診室接受閉鎖式復位（closed reduction）後，以X光檢查復位情形。下列何者不是遠端橈骨骨折復位後可接受的放射參數（radiographic parameters）？","options":["(A) 患側的橈長（radial length）和健側相比，其差異在2mm以內","(B) 患側的關節內降差（intra-articular step-off）小於2mm","(C) 患側的背傾（dorsal tilt）角度為15度","(D) 患側的橈角（radial angle）和健側相比，其差異在5度以內"],"answer":2,"image":""},{"id":"md5-105-2-58","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第2次第58題","year":105,"session":2,"number":58,"question":"開放性骨折（open fracture）是骨科急症之一，下列敘述何者正確？","options":["(A) 根據Gustilo-Anderson分類，開放性傷口小於1公分，同時沒有嚴重的軟組織傷害者，為type III injury","(B) 所有的開放性骨折病患送至急診時，在完成初步傷口清洗後，骨科醫師應在第一時間在急診做傷口探查、清創及縫合；即便1小時內即可安排手術，也不可拖延到手術室後才行清創","(C) 傷口沖洗、清創及抗生素治療是預防開放性骨折後發生感染最重要的處理原則。若傷口清創不完全，靠大量抗生素的使用可完全避免感染的發生","(D) 對於type I及type II開放性骨折，在急診室時可選用第一代頭孢菌素（first-generation cephalosporins）治療；對於typeIII開放性骨折建議再加上氨基配醣體類抗生素（aminoglycosides）"],"answer":3,"image":""},{"id":"md5-105-2-59","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第2次第59題","year":105,"session":2,"number":59,"question":"35歲男性從高處跌落，造成背部嚴重疼痛及下肢無力，且從身體乳線（nipple line）以下有感覺異常情形。初步診斷為脊椎骨折脊髓損傷。經理學檢查，此患者最可能的脊髓損傷部位？","options":["(A) 第四胸椎（T4）","(B) 第八胸椎（T8）","(C) 第十胸椎（T10）","(D) 第十二胸椎（T12）"],"answer":0,"image":""},{"id":"md5-105-2-60","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"105年第2次第60題","year":105,"session":2,"number":60,"question":"有關膝關節內之半月板（meniscus）的特性，下列何者錯誤？","options":["(A) 它們協助承載體重，也增加了股骨脛骨間之吻合度（congruency）","(B) 提供膝關節本體位覺（proprioceptive）訊息，幫助關節之運動功能","(C) 通常內側半月板比起外側半月板較為彎曲，也覆蓋較大部分的脛骨平臺（tibial plateau）之面積","(D) 半月板（menisus）之white-white zone血液灌注差，破裂時即使加以縫合癒合能力亦很差"],"answer":2,"image":""},{"id":"md5-105-2-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第2次第61題","year":105,"session":2,"number":61,"question":"10歲男童從滑梯跌落以左膝著地，由於膝部疼痛腫脹，父母帶他來急診求診，並接受X光檢查，由此X光影像，顯示他發生了何種的生長板傷害？","options":["(A) Salter-Harris第一型","(B) Salter-Harris第二型","(C) Salter-Harris第三型","(D) Salter-Harris第四型"],"answer":1,"image":"md5-105-2-61.jpeg"},{"id":"md5-105-2-62","subject":"md5","topic":"神經外科","meta":"105年第2次第62題","year":105,"session":2,"number":62,"question":"45歲男性，5年前接受右側第四、五腰椎椎間盤突出切除手術，近一個月來，右側坐骨神經痛復發。初步診斷為椎間盤突出復發或硬膜上神經粘黏。下列何項檢查，最能區別此兩者？","options":["(A) 電腦斷層加顯影劑檢查（computed tomography with contrast enhancement）","(B) 電腦斷層加椎間盤造影檢查（computed tomographic discography）","(C) 電腦斷層加脊髓造影檢查（computed tomographic myelography）","(D) 磁振造影加顯影劑檢查（magnetic resonance imaging with gadolinium）"],"answer":3,"image":""},{"id":"md5-105-2-63","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"105年第2次第63題","year":105,"session":2,"number":63,"question":"有關骨髓炎（osteomyelitis）的敘述，何者最正確？","options":["(A) 成人骨髓炎最常見的原因是血行性感染（hematogenous infection）","(B) 當細菌在骨內形成菌落繁殖會破壞骨組織的血液循環，產生壞死，稱為包殼骨（involucrum）","(C) 慢性骨髓炎的病人，其血中白血球大多會超過12000/mm3","(D) 對於靜脈注射毒癮者感染骨髓炎，優先考慮的致病菌種分別為金黃色葡萄球菌（Staphylococcus aureus），綠膿桿菌（Pseudomonas aeruginosa）和格蘭氏陰性菌（gram-negative organisms）"],"answer":3,"image":""},{"id":"md5-105-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"105年第2次第64題","year":105,"session":2,"number":64,"question":"下列關於胱氨酸結石（cystine stone）的敘述，何者錯誤？","options":["(A) 自體隱性遺傳（autosomal recessive）","(B) 發生率為1～2%","(C) 預防結石生長及復發要酸化尿液","(D) 沒有已知的結石抑制因子"],"answer":[2,3],"image":"","answer_note":"更正:第64題答Ｃ、Ｄ給分。"},{"id":"md5-105-2-65","subject":"md5","topic":"泌尿-結石與感染","meta":"105年第2次第65題","year":105,"session":2,"number":65,"question":"一位懷孕30週婦女有尿路結石過去病史，因左側腰痛至急診求診，腎臟超音波呈現左側腎臟水腫，醫師診斷為疑似左側輸尿管結石，下列何者不是適當的處置？","options":["(A) 體外震波碎石術","(B) 半身麻醉下施行輸尿管鏡碎石術","(C) 局部麻醉下施行經皮腎臟造瘻術","(D) 內視鏡置放輸尿管導管"],"answer":0,"image":""},{"id":"md5-105-2-66","subject":"md5","topic":"泌尿-腫瘤","meta":"105年第2次第66題","year":105,"session":2,"number":66,"question":"關於高期別之非精細胞胚胎細胞癌（nonseminoma germ cell carcinoma），下列何者不是預測其化學治療之反應指標？","options":["(A) 血清LDH","(B) 血清β-hCG","(C) 血清CEA","(D) 轉移部位總數"],"answer":2,"image":""},{"id":"md5-105-2-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"105年第2次第67題","year":105,"session":2,"number":67,"question":"下列何者不是造成老年人夜尿症（nocturia）的原因？","options":["(A) 睡眠呼吸中止症候群（sleep apnea syndrome）","(B) 逼尿肌活性過強","(C) 前列腺肥大症併膀胱出口阻塞","(D) 應力性尿失禁（stress urinary incontinence）"],"answer":3,"image":""},{"id":"md5-105-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"105年第2次第68題","year":105,"session":2,"number":68,"question":"良性前列腺肥大手術的絕對適應症為何？","options":["(A) 每晚夜尿7次，嚴重影響生活品質","(B) 急性尿滯留","(C) 因膀胱出口阻塞造成的兩側腎水腫","(D) 尿路感染"],"answer":2,"image":""},{"id":"md5-105-2-69","subject":"md5","topic":"泌尿-結石與感染","meta":"105年第2次第69題","year":105,"session":2,"number":69,"question":"77歲中風病患，長期臥床且使用留置性導尿管。其看護發現尿液變臭且混濁持續三天，病患生命徵狀穩定，尿液檢查發現WBC > 100/HPF，尿路培養為念珠球菌（Candida albicans），下列何項處置最不適當？","options":["(A) 給予口服fluconazole","(B) 移除導尿管，改成每天定時間歇性清潔導尿（intermittent clean catheterization）","(C) 給予amphotericin-B膀胱連續沖洗","(D) 給予amphotericin-B靜脈注射"],"answer":3,"image":""},{"id":"md5-105-2-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"105年第2次第70題","year":105,"session":2,"number":70,"question":"有關多囊腎（polycystic kidney）之敘述，下列何者錯誤？","options":["(A) 於新生兒時期就診斷出來的，多是自體隱性（autosomal recessive）的多囊腎。自體顯性（autosomal dominant）的多囊腎則多在30到50歲才被確認","(B) 自體隱性多囊腎與第6對染色體上的PKHD1基因有關","(C) 自體顯性多囊腎與PKD1基因和PKD2基因有關，PKD1基因在第16對染色體，而PKD2基因在第4對染色體","(D) 有PKD2基因缺陷的病人，通常比有PKD1基因缺陷的病人惡化快速"],"answer":3,"image":""},{"id":"md5-105-2-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"105年第2次第71題","year":105,"session":2,"number":71,"question":"下列敘述那些正確？①陰莖骨折（penile fracture）多發生在陰莖懸韌帶（suspensory ligament）遠側 ②陰莖骨折如果採取保守治療會有10%以上發生勃起時陰莖彎曲（penile curvature） ③陰莖穿透傷（penetrating injury）要考慮做逆行性尿道攝影（retrograde urethrography） ④急診發現車禍受傷男性的尿道口有出血時，必須馬上放置導尿管治療","options":["(A) ①②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":0,"image":""},{"id":"md5-105-2-72","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"105年第2次第72題","year":105,"session":2,"number":72,"question":"59歲女性一個月前跌倒後出現左肩疼痛的症狀，影響睡眠，肩關節X光檢查如附圖，最可能的診斷為何？","options":["(A) avulsion fracture of greater tuberosity","(B) calcified tendinosis","(C) bone metastasis","(D) primary osteoblastic bone tumor"],"answer":1,"image":"md5-105-2-72.jpeg"},{"id":"md5-105-2-73","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第2次第73題","year":105,"session":2,"number":73,"question":"51歲女性病人主訴右髖關節疼痛約3週，附圖為骨盆X光片，箭號所指處最可能的診斷為：","options":["(A) fibrous dysplasia","(B) bone metastasis","(C) chondrosarcoma","(D) osteosarcoma"],"answer":0,"image":"md5-105-2-73.jpeg"},{"id":"md5-105-2-74","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"105年第2次第74題","year":105,"session":2,"number":74,"question":"20歲男性，因右膝受傷接受X光攝影。附圖為X光攝影影像，最可能的診斷為何？","options":["(A) fibrous dysplasia","(B) hereditary multiple exostoses","(C) osteogenic sarcoma","(D) eosinophilic granuloma"],"answer":1,"image":"md5-105-2-74.jpeg"},{"id":"md5-105-2-75","subject":"md5","topic":"消化器外科","meta":"105年第2次第75題","year":105,"session":2,"number":75,"question":"一位男性病人腹壁疼痛去看門診，醫師說這是從腹直肌外側跑出來的疝氣，此種疝氣稱為？","options":["(A) Littre's hernia","(B) Richter's hernia","(C) Spigelian hernia","(D) Obsturator hernia"],"answer":2,"image":""},{"id":"md5-105-2-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第2次第76題","year":105,"session":2,"number":76,"question":"一位50歲男性的卡車司機，因打瞌睡於高速公路追撞前方聯結車，卡在前座達20分鐘，到達急診時，血壓80/40 mmHg、意識清楚但躁動不安、腹部脹大、左腿變形，下列何項敘述最不適當？","options":["(A) 應立即進行腦部電腦斷層檢查","(B) 床邊腹部超音波可用於加速手術的決定","(C) 中心靜脈導管的放置不應拖延進手術室的時間","(D) 血氧飽和度92％可因為血壓低，故僅供參考"],"answer":0,"image":""},{"id":"md5-105-2-77","subject":"md5","topic":"外科-休克創傷傷口","meta":"105年第2次第77題","year":105,"session":2,"number":77,"question":"一輛學校校車和卡車對撞後，一位6歲小孩被送到急診室，這時小孩已生命垂危，但是二次施打周邊靜脈都失敗，此時最佳給予輸液路徑為：","options":["(A) 建立一個腹內導管（intraperitoneal catheter）","(B) 脛骨的骨內針置入術（intraosseous cannulation）","(C) 建立中心靜脈導管","(D) 繼續嘗試建立周邊的靜脈導管"],"answer":1,"image":""},{"id":"md5-105-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"105年第2次第78題","year":105,"session":2,"number":78,"question":"尊重病人自主是醫學倫理的重要原則。何謂尊重病人自主？","options":["(A) 醫院建立標準作業流程，確保病人在手術前一定要親筆簽署手術同意書，就是尊重病人自主","(B) 送到急診的頭部外傷病人，意識不清，在家屬沒有到院簽字前，絕對不可以進行手術，就是尊重自主","(C) 只要送進加護病房的病人，一律發給家屬病危通知書，好讓家屬預先做好心理準備以及相關生活規劃，就是尊重自主","(D) 以病人能了解的語言，主動告知病人相關病情資訊，確保病人理解醫療行為的相關風險與利益，協助病人做出一個符合其最佳利益的醫療決策，就是尊重自主"],"answer":3,"image":""},{"id":"md5-105-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"105年第2次第79題","year":105,"session":2,"number":79,"question":"63歲的楊先生在車禍後送到急診，電腦斷層檢查為急性硬腦膜下出血，此時加護病房滿床，醫師檢視每一床的病歷，沒有找到可以轉出加護病房的病患，醫師考慮把楊先生留在急診暫留區，但知道照顧楊先生不是暫留區醫護人力能夠負荷，目前附近也找不到其他機構可代為收治這種隨時可能要手術的神經外科病患；此時醫師應如何處理最適當？","options":["(A) 將楊先生放在暫留區，也只能以現有的醫護人力照顧他","(B) 請院方向政府提出地區層次資源分配問題","(C) 聯絡值班行政人員，調度具相關能力的額外人員至急診給予楊先生暫時性照護","(D) 每個病人都有平等競爭有限資源的機會，讓楊先生與加護病房病人們抽籤，抽到一位轉出加護病房"],"answer":2,"image":""},{"id":"md5-105-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"105年第2次第80題","year":105,"session":2,"number":80,"question":"安寧緩和醫療條例中，有關不施行心肺復甦術或維生醫療之規定，下列敘述何者錯誤？","options":["(A) 應由二位領有執業執照之醫師診斷確為末期病人","(B) 應有意願人簽署之意願書","(C) 有意願人為未成年人簽署意願書時，應得其法定代理人之同意","(D) 有意願人為未成年人無法表達意願時，則應由法定代理人簽署意願書"],"answer":0,"image":""},{"id":"md5-106-1-1","subject":"md5","topic":"小兒外科","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"有關新生兒薦尾部畸胎瘤（neonatal sacrococcygeal teratoma）的敍述，下列何者錯誤？","options":["(A) 是新生兒畸胎瘤中最常見者","(B) 手術切除時需保留尾骨（coccyx），避免術後馬尾症候群（cauda equina syndrome）發生","(C) 手術切除時需結紮中薦部動脈（middle sacral artery）以減少失血","(D) 大部分屬良性"],"answer":1,"image":""},{"id":"md5-106-1-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"腹部鈍傷時採用診斷性腹膜沖洗（diagnostic peritoneal lavage）的適應症，下列何者錯誤？","options":["(A) 理學檢查無法判斷的狀況","(B) 脊椎損傷","(C) 有剖腹探查的明顯適應症","(D) 不明原因的休克或是低血壓"],"answer":2,"image":""},{"id":"md5-106-1-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"關於老年人接受主要手術（major surgery）時，下列敘述何者錯誤？","options":["(A) 有心肌缺血心臟病並有抽菸，在手術前後期可使用乙型阻斷劑（β-blocker）","(B) 老年人發生無症狀菌尿症（bacteriuria）的機率比較高，手術前應檢查尿液","(C) 雖然老年人有糖尿病的比率較高，但是高血糖（hyperglycemia）並不會增加手術的發病率和死亡率（morbidity and mortality）","(D) 老年人在手術前應評估其肺部功能"],"answer":2,"image":""},{"id":"md5-106-1-4","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"嚴重外傷病患呈現腹內大量出血及休克時，有時必須採用傷害控制手術（damage control surgery）於短時間內來控制出血及其他搶救步驟，以挽救生命。否則會出現致死三元素（lethal triad）。下列何者不屬於lethal triad？","options":["(A) 凝血機能不全（coagulopathy）","(B) 代謝性酸中毒（metabolic acidosis）","(C) 低體溫（hypothermia）","(D) 敗血症（sepsis）"],"answer":3,"image":""},{"id":"md5-106-1-5","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"血壓是判定傷病患是否呈現休克的重要指標，當災難事故發生時，若現場並無血壓量測工具時，可藉由橈動脈脈搏（radial pulse）、股動脈脈搏（femoral pulse）及頸動脈脈搏（carotid pulse）之檢測，來估計傷病患之血壓高低。下列為當血壓低於90 mmHg時，三種脈搏消失之先後次序，何者正確？","options":["(A) 股脈搏 → 頸脈搏 → 橈脈搏","(B) 頸脈搏 → 股脈搏 → 橈脈搏","(C) 橈脈搏 → 股脈搏 → 頸脈搏","(D) 頸脈搏 → 橈脈搏 → 股脈搏"],"answer":2,"image":""},{"id":"md5-106-1-6","subject":"md5","topic":"胸腔外科","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"當小客車司機因追撞大貨車，於急救時出現大量血氣胸，必須緊急給予胸管引流治療。有關胸管置放之位置，下列敘述何者正確？","options":["(A) 第四或五肋間，腋中線（4th or 5th intercostal space, mid-axillary line）","(B) 第二肋間，鎖骨中線（2nd intercostal space, mid-clavicular line）","(C) 第六或七肋間，腋中線（6th or 7th intercostal space, mid-axillary line）","(D) 視病患之情況而定"],"answer":0,"image":""},{"id":"md5-106-1-7","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"與腹腔內感染（intra-abdominal infections）相關的敘述，下列何者錯誤？","options":["(A) 電腦斷層攝影（abdominal computed tomography）有助於診斷腹腔內感染","(B) 如果沒有妥善處理，會導致多器官功能障礙症候群（multiple organ dysfunction syndrome）","(C) 所有的腹腔內感染都必須手術治療","(D) 老年人及營養不良者之腹腔內感染比較有發生併發症的風險"],"answer":2,"image":""},{"id":"md5-106-1-8","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"進行全靜脈營養（total parenteral nutrition，TPN）時，下列與中央靜脈導管相關之併發症的敘述，何者錯誤？","options":["(A) 導管內血栓（thrombus）","(B) 氣胸（pneumothorax）","(C) 臂叢神經損傷（brachial plexus injury）","(D) 尿路感染（urinary tract infection）"],"answer":3,"image":""},{"id":"md5-106-1-9","subject":"md5","topic":"神經外科","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"最常見轉移性腦瘤之原發處，依發生比例由多到少之排序為何？","options":["(A) 乳房＞肺＞腎＞腸胃道","(B) 肺＞乳房＞腎＞腸胃道","(C) 腸胃道＞腎＞乳房＞肺","(D) 腎＞肺＞乳房＞腸胃道"],"answer":1,"image":""},{"id":"md5-106-1-10","subject":"md5","topic":"神經外科","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"下列有關脊神經及支配的肌肉配對，何者錯誤？","options":["(A) C5－deltoid muscle","(B) C6－triceps muscle","(C) L3－quadriceps muscle","(D) S1－gastronemius muscle"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第10題一律給分 (原公告答案 B)"},{"id":"md5-106-1-11","subject":"md5","topic":"神經外科","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"一位68歲男性因跌倒送來急診，意識狀態模糊，對痛刺激眼睛會張開，且左手會撥開痛刺激，但不會出聲，頭部電腦斷層如下圖所示，下列何者正確？","options":["(A) 出血位置位於硬腦膜下","(B) 出血的來源多半為顱骨骨折造成腦膜動脈破裂而成","(C) 最佳的治療方法為大量的使用降腦壓藥物，避免血塊對腦幹的壓迫","(D) 此病人目前GCS為10分"],"answer":0,"image":"md5-106-1-11.jpeg"},{"id":"md5-106-1-12","subject":"md5","topic":"神經外科","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"下列有關脊髓損傷病人使用高劑量皮質類固醇（corticosteroid）的敘述，何者錯誤？","options":["(A) 建議在受傷後8小時內使用","(B) bolus劑量為30 mg/kg靜脈滴注一小時後，給予5.4 mg/kg/hour靜脈滴注23小時","(C) 使用的藥物是methylprednisolone","(D) 此高劑量的皮質類固醇有相當大的副作用"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第12題一律給分 (原公告答案 D)"},{"id":"md5-106-1-13","subject":"md5","topic":"神經外科","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"下列何者最不適合做腰椎穿刺（lumbar puncture）？","options":["(A) 腦部腫瘤病變","(B) 腦膜炎","(C) 蜘蛛網膜下腔出血","(D) 交通性水腦症（communicating hydrocephalus）"],"answer":0,"image":""},{"id":"md5-106-1-14","subject":"md5","topic":"神經外科","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"腦膜瘤（meningioma）三個最好發之位置為何？","options":["(A) 矢狀竇旁－大腦鐮（parasagittal-falx）、岩骨（petrous bone）、顱凸處（convexity）","(B) 矢狀竇旁－大腦鐮（parasagittal-falx）、顱凸處（convexity）、蝶骨翼（sphenoid wing）","(C) 矢狀竇旁－大腦鐮（parasagittal-falx）、蝶骨平面（planum sphenoidale）、顱凸處（convexity）","(D) 顱凸處（convexity）、蝶骨翼（sphenoid wing）、岩骨（petrous bone）"],"answer":1,"image":""},{"id":"md5-106-1-15","subject":"md5","topic":"神經外科","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"頭部外傷造成的diffuse axonal injury（DAI），下列敘述何者錯誤？","options":["(A) 病人通常沒有清明期（lucid interval）","(B) 電腦斷層掃描（brain CT）上可能沒有明顯的病灶，但病人卻呈昏迷狀態","(C) 如果病人不幸死亡，解剖上腦部有明顯不正常的外觀","(D) 在胼胝體（corpus callosum）可見出血性壞死的病灶"],"answer":2,"image":""},{"id":"md5-106-1-16","subject":"md5","topic":"整形重建外科","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"眼瞼下垂（ptosis）依照其嚴重度來分，兩側眼瞼水平高度相差4 mm以上時屬於：","options":["(A) 嚴重（severe）","(B) 中等（moderate）","(C) 輕微（mild）","(D) 正常（normal）"],"answer":0,"image":""},{"id":"md5-106-1-17","subject":"md5","topic":"整形重建外科","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"下圖為一個顏面部創傷來急診的病人，急診醫師安排臉部電腦斷層，顏面骨有骨折的狀況，其受傷的情形分類為：","options":["(A) 右側Le Fort I + II，左側Le Fort III","(B) 右側Le Fort II + III，左側Le Fort I","(C) 右側Le Fort I + III，左側Le Fort II","(D) 右側Le Fort I + II，左側Le Fort IV"],"answer":2,"image":"md5-106-1-17.jpeg"},{"id":"md5-106-1-18","subject":"md5","topic":"整形重建外科","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"下列有關下頜骨骨折（mandibular fractures）的敘述，何者錯誤？","options":["(A) 下頜骨的組成包含下頜骨聯合（symphysis），下頜骨體（body）、下頜角（angle）、下頜枝（ramus）、下頜髁突（condyle）和下頜骨喙突（coronoid process）","(B) 下頜骨骨折可以依據上下頜齒列的關係，Angle classification system分類為Class I、Class II及Class III","(C) 上下頜齒列固定復位可用於無明顯位移、無齒列錯位及顳顎關節（temporo-mandibular joint）活動正常之情形","(D) 手術治療主要為骨折處和上下頜齒列固定復位，固定時間越久越好，不會有顳顎關節僵硬的問題"],"answer":3,"image":""},{"id":"md5-106-1-19","subject":"md5","topic":"整形重建外科","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"下列何者是造成傷口攣縮（wound contracture）的主要細胞？","options":["(A) 肌纖維母細胞（myofibroblast）","(B) B-淋巴球（B-lymphocyte）","(C) T-淋巴球（T-lymphocyte）","(D) 巨噬細胞（macrophage）"],"answer":0,"image":""},{"id":"md5-106-1-20","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"根據American Burn Association所訂，須到灼傷中心住院的情況，下列敘述何者錯誤？","options":["(A) 二及三度燒傷大於10% TBSA","(B) 三度燒傷","(C) inhalation injury","(D) 5歲以下，50歲以上，二及三度燒傷大於5% TBSA"],"answer":3,"image":""},{"id":"md5-106-1-21","subject":"md5","topic":"整形重建外科","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"下列有關microvascular surgery時使用anticoagulant運用的敘述，何者錯誤？","options":["(A) low dose aspirin的anti-platelet效果不錯","(B) heparin可全身性或局部使用","(C) fibrinolytic agent於microanastomosis thrombosis時有幫忙","(D) 使用anticoagulant可使free flap transfer之成功率大量提高"],"answer":3,"image":""},{"id":"md5-106-1-22","subject":"md5","topic":"心臟血管外科","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"病人於接受心臟手術後，轉入加護病房觀察。此時他的血壓由術後的140/80 mmHg下降至80/60 mmHg，肺動脈壓由30/18 mmHg上升至56/30 mmHg，肺楔壓為20 mmHg，中心靜脈壓為15 mmHg，心跳為130/min。下列立即處置何者適當？①給予血管放鬆劑，ཋ低後負荷 ②給予抗心律不整藥，改善心跳過速 ③給予裝置葉克膜(ECMO) ④給予強心劑，增強心肌收縮力","options":["(A) ①②③","(B) 僅①③","(C) ②④","(D) 僅④"],"answer":3,"image":""},{"id":"md5-106-1-23","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"下列病患中，何者並不適宜成為心臟移植的受贈者？","options":["(A) 63歲男性罹患嚴重冠狀動脈疾病，所有內科療法及外科手術療法皆無法改善心肌血液灌注","(B) 50歲男性罹患肥大性心肌病變，經心肌切除手術後仍為末期心衰竭","(C) 55歲男性罹患末期心衰竭以及肺氣腫合併肺高壓者（pulmonary vascular resistance > 5 Wood units）","(D) 22歲女性罹患良性心臟內腫瘤合併反覆性心室性頻脈，無法以外科手術切除者"],"answer":2,"image":""},{"id":"md5-106-1-24","subject":"md5","topic":"心臟血管外科","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"下列關於急性主動脈剝離症的敘述，何者正確？①主動脈剝離的範圍若僅包含胸部降主動脈，則大多需手術 ②主動脈剝離的範圍若包含胸部升主動脈，則大多需緊急手術 ③主動脈剝離的範圍若僅包含胸部降主動脈，大多不可用主動脈內徑血管支架（endovascular stent grafts）治療 ④主動脈剝離的範圍若包含胸部升主動脈，大多不可用主動脈內徑血管支架（endovascular stent grafts）治療","options":["(A) ①②③","(B) 僅①③","(C) ②④","(D) 僅④"],"answer":2,"image":""},{"id":"md5-106-1-25","subject":"md5","topic":"心臟血管外科","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"一位69歲男性病人因急性心肌梗塞住院。五天後，病人呼吸較喘，身體檢查顯示有新的心尖部心縮期雜音、血壓80/50 mmHg、中心靜脈壓30 mmHg、胸部X光顯示肺水腫現象。下列敘述何者錯誤？①診斷為心室中隔破裂 ②須裝置主動脈內氣球幫浦 ③不須緊急手術 ④手術死亡率約10%至20%","options":["(A) ①②③","(B) 僅①③","(C) ②④","(D) 僅④"],"answer":1,"image":""},{"id":"md5-106-1-26","subject":"md5","topic":"心臟血管外科","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"有關主動脈瓣膜置換的手術適應症，下列何者錯誤？","options":["(A) 一旦有症狀且合併嚴重主動脈瓣膜逆流，需要手術","(B) 無症狀但合併嚴重主動脈瓣膜逆流及左心室射出比率< 50%，需要手術","(C) 嚴重主動脈瓣膜逆流且合併三條冠狀動脈疾病，需要手術","(D) 無症狀但合併主動脈瓣膜逆流、左心室射出比率> 50%及end-diastolic dimention < 70 mm，需要手術"],"answer":3,"image":""},{"id":"md5-106-1-27","subject":"md5","topic":"胸腔外科","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"肺癌手術後，死亡原因最常見的是：","options":["(A) 肺炎併敗血症（pneumonia with sepsis）","(B) 心衰竭（heart failure）","(C) 腎衰竭（renal failure）","(D) 肝衰竭（hepatic failure）"],"answer":0,"image":""},{"id":"md5-106-1-28","subject":"md5","topic":"胸腔外科","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"下列何者不是支氣管擴張症做單純肺葉切除手術適應症？","options":["(A) 病人內科治療失敗合併反覆肺炎","(B) 反覆咳血影響正常生活","(C) 雙側嚴重支氣管擴張症","(D) 侷限型單肺葉支氣管擴張症"],"answer":2,"image":""},{"id":"md5-106-1-29","subject":"md5","topic":"胸腔外科","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"下列有關咳血之敘述，何者正確？","options":["(A) 大量咳血一般被定義為24小時內，出血超過300 mL","(B) 就診斷和治療而言，硬式支氣管鏡較軟式支氣管鏡為佳","(C) 血管攝影檢查一定要做","(D) 血管栓塞術對於出血控制通常無效"],"answer":1,"image":""},{"id":"md5-106-1-30","subject":"md5","topic":"胸腔外科","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"關於原發性氣胸（primary pneumothorax）的敘述，何者錯誤？","options":["(A) 診斷可由病史、理學檢查及X光確定","(B) CT routine不需要","(C) 慢性阻塞肺病（COPD）引起的氣胸為續發性（secondary）氣胸","(D) 插胸管是絕對需要的"],"answer":3,"image":""},{"id":"md5-106-1-31","subject":"md5","topic":"消化器外科","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"下列那一種肝臟良性腫瘤，有較高之惡性轉變的可能性，建議手術切除？","options":["(A) cyst","(B) adenoma","(C) focal nodular hyperplasia","(D) hemangioma"],"answer":1,"image":""},{"id":"md5-106-1-32","subject":"md5","topic":"消化器外科","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"王先生因為腹膜炎接受手術，術中發現空腸、迴腸及右側結腸呈現缺血壞死現象，下列何者是最可能的診斷？","options":["(A) superior mesenteric artery thrombosis","(B) inferior mesenteric artery embolism","(C) superior mesenteric vein thrombosis","(D) non-occlusive mesentery ischemia"],"answer":0,"image":""},{"id":"md5-106-1-33","subject":"md5","topic":"消化器外科","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"下列有關肝膿瘍之敘述，何者正確？","options":["(A) 大部分的肝膿瘍發生在右肝","(B) 大部分的肝膿瘍都是單一致病菌引起","(C) 最常見的致病菌為Staphylococcus aureus","(D) 80～90%病人可以從血液培養出致病菌"],"answer":0,"image":""},{"id":"md5-106-1-34","subject":"md5","topic":"消化器外科","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"下列關於疝氣之敘述，何者錯誤？","options":["(A) 股疝氣（femoral hernia）及間接型腹股溝疝氣（indirect type inguinal hernia）都以右側為主","(B) 股疝氣最易造成腸子壞死（20%），故應在初次診斷時就接受手術治療","(C) 切口疝氣（incisional hernia）都可以直接縫合（primary closure），即使疝氣洞口大於5公分也不需要使用人工網膜（prosthetic material）來縫合","(D) 肥胖及腹部手術術後傷口感染都能造成切口疝氣（incisional hernia）的發生率增加"],"answer":2,"image":""},{"id":"md5-106-1-35","subject":"md5","topic":"消化器外科","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"根據first-order kinetics，喝完200毫升開水多久後，胃裡一半的水會排空至十二指腸？","options":["(A) 5分鐘","(B) 12分鐘","(C) 20分鐘","(D) 35分鐘"],"answer":1,"image":""},{"id":"md5-106-1-36","subject":"md5","topic":"消化器外科","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"進行期胃癌之肉眼觀察形態有四種。下列敘述何者錯誤？","options":["(A) type II，潰瘍外觀其邊緣隆起與周邊之黏膜界限清晰","(B) type III，潰瘍外觀其邊緣隆起與周邊黏膜界限不清","(C) type IV，胃壁瀰漫性浸潤無明顯之隆起或潰瘍","(D) 臺灣以type II較多"],"answer":3,"image":""},{"id":"md5-106-1-37","subject":"md5","topic":"消化器外科","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"李先生因為解黑便三天，且清晨開始有吐血的情形而被送至急診處。需要及早照會外科手術治療的適應症，下列何者錯誤？","options":["(A) 胃鏡檢查結果為改良強生分類第五型（modified Johnson classification V）胃潰瘍","(B) 年齡大於六十歲","(C) 十二指腸潰瘍直徑大於二公分","(D) 潰瘍底部有可見血管"],"answer":0,"image":""},{"id":"md5-106-1-38","subject":"md5","topic":"消化器外科","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"對於無法手術的轉移性胰臟內分泌瘤病患，可使用的治療中，何者正確？","options":["(A) hypergastrinemia可以diazoxide治療","(B) 對於gastrinoma引起的腸胃道急性出血，使用proton pump inhibitors是無效的","(C) 儘可能以手術切除metastatic islet cell carcinoma（cytoreduction surgery）後，肝臟轉移的部分可以肝動脈栓塞來治療","(D) 轉移到骨骼的metastatic islet cell carcinoma還是可以考慮以手術切除之"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第38題一律給分 (原公告答案 C)"},{"id":"md5-106-1-39","subject":"md5","topic":"消化器外科","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"26歲男性因體重120公斤至減重中心求診，他身高172公分，下列關於減重手術的說明何者錯誤？","options":["(A) 限制型術式（restrictive procedures）減重效果較吸收不良型術式（malabsorptive procedures）低","(B) 限制型術式（restrictive procedures）的術後併發症及死亡率較吸收不良型術式（malabsorptive procedures）低","(C) 吸收不良型術式（malabsorptive procedures）手術後，術前合併症（comorbidity）的治癒率較限制型術式（restrictive procedures）高","(D) 限制型術式（restrictive procedures）的手術適應症body mass index值較吸收不良型術式（malabsorptive procedures）低"],"answer":3,"image":""},{"id":"md5-106-1-40","subject":"md5","topic":"消化器外科","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"下列有關膽管癌之敘述，何者錯誤？","options":["(A) 根據發生位置可分為肝內、肝門處與遠端膽管癌，而最好發的位置是肝內膽管癌","(B) 超過90%遠端或肝門處膽管癌病患之臨床表現為阻塞性黃疸","(C) 肝門處膽管癌在電腦斷層掃描檢查中不易看到腫瘤，反而是看到肝內膽管擴大與變小的膽囊","(D) 對於Bismuth分類type I & II肝門處膽管癌若無肝門處血管侵犯，可考慮局部腫瘤切除，並利用空腸作膽道重建（hepaticojejunostomy）"],"answer":0,"image":""},{"id":"md5-106-1-41","subject":"md5","topic":"消化器外科","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"一位53歲男性，以往健康良好，最近逐漸出現黃疸症狀，糞便呈淺色，尿液茶褐色。病患以往沒有膽道結石病史。理學檢查顯示患者腹部無痛覺，沒有硬塊，膽囊亦觸摸不到。實驗室血液數據顯示總膽管色素：9.8 mg/dL，直接膽紅素：7.6 mg/dL，prothrombin time INR：1.79，ALT：141 U/L，AST：147 U/L，澱粉酶：130 U/L，脂肪酶：86 U/L，alkaline-P：469 U/L。腹部超音波顯示肝內肝管擴大，膽囊正常。則下列何者與病患最可能的疾病診斷不符？","options":["(A) 腹部電腦斷層顯示總膽管明顯擴大","(B) 病患的腫瘤為腺癌，生長速度緩慢","(C) 膽道感染不常見","(D) 經皮穿肝膽道攝影比內視鏡逆行性膽道攝影的診斷價值為高"],"answer":0,"image":""},{"id":"md5-106-1-42","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"54歲男性因嚴重高血壓合併低血鉀症多次來急診室處理，初步診斷疑有hyperaldosteronism，手術前的病灶定位以何者之敏感性（sensitivity）最高？","options":["(A) 超音波掃描","(B) 電腦斷層掃描","(C) 鉈掃描（thallium-201 scan）","(D) 血管造影術"],"answer":1,"image":""},{"id":"md5-106-1-43","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"根據美國國家衛生院的研究，胰島素瘤（insulinoma）的手術前定位以下列何者最為精確？","options":["(A) 手術前核磁共振檢查","(B) 手術前血管造影術","(C) 手術前以鈣劑動脈注射刺激試驗","(D) 手術中超音波掃描"],"answer":2,"image":""},{"id":"md5-106-1-44","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"關於甲狀腺濾泡癌（follicular carcinoma），何者錯誤？","options":["(A) 較多為多發性（multifoci）","(B) 有被膜侵犯","(C) 有血管侵犯","(D) 較少淋巴轉移"],"answer":0,"image":""},{"id":"md5-106-1-45","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"35歲未哺乳的女性病人，最近發現左側乳頭有血樣分泌物（bloody discharge），觸診發現乳暈下兩點鐘方向有硬塊，下列敘述何者錯誤？","options":["(A) 應安排乳房攝影、乳房超音波檢查","(B) 可安排乳管攝影（ductography）檢查","(C) 測量血液中CEA、CA 15-3濃度以排除乳癌可能性","(D) 應儘快安排手術切除"],"answer":[2,3],"image":"","answer_note":"更正:第45題答Ｃ、Ｄ給分"},{"id":"md5-106-1-46","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"三發性副甲狀腺機能亢進（tertiary hyperparathyroidism），何者正確？","options":["(A) 為腎移植後一年，鈣、副甲狀腺素持續升高，應手術治療","(B) 骨疼痛、皮膚癢不嚴重，應手術治療","(C) 骨密度未下降（T>-2.5），應手術治療","(D) 不作全切除也不易再發"],"answer":0,"image":""},{"id":"md5-106-1-47","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"下列有關乳房腫瘤細針穿刺（fine needle aspiration）檢查之敘述，何者錯誤？","options":["(A) 用16或18號針頭（16 or 18 gauge needle）","(B) 不需局部麻醉","(C) 可區分實質腫瘤或囊腫（solid tumor or cyst）","(D) 若發現有癌細胞（carcinoma cell )仍需作切片檢查（tumor biopsy）"],"answer":0,"image":""},{"id":"md5-106-1-48","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"25歲女性，左乳外上側，離乳暈3公分，約1公分×1公分腫瘤，經粗針切片是浸潤性管道癌（infiltrating ductal carcinoma），女性荷爾蒙接受器（estrogen receptor）陽性，黃體素荷爾蒙接受器（progesterone receptor）陽性，HER-2/neu陽性，下列何者是最適合的建議？","options":["(A) 左乳房全切除手術","(B) 左外側乳房部分切除","(C) 左外側乳房部分切除加上前哨淋巴結切除術","(D) 荷爾蒙治療即可，不需要手術"],"answer":2,"image":""},{"id":"md5-106-1-49","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"乳房改良性根除性切除術中，需避免傷害下列那些神經？①胸背神經（thoracodorsal nerve） ②長胸神經（long thoracic nerve） ③內乳神經（internal mammary nerve） ④膈神經（phrenic nerve)","options":["(A) ①②③","(B) 僅②③","(C) ③④","(D) ①④"],"answer":0,"image":""},{"id":"md5-106-1-50","subject":"md5","topic":"小兒外科","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"一個月大的男嬰餵奶後出現有噴射性的嘔吐現象，其吐出物中不含膽汁。理學檢查在上腹部可摸到一類似橄欖狀的腫塊（olive mass），最可能的診斷為：","options":["(A) 膽道囊腫（choledochal cyst）","(B) 腸套疊（intussusception）","(C) 嬰兒型幽門肥厚狹窄（infantile hypertrophic pyloric stenosis）","(D) 巨大結腸症（megacolon）"],"answer":2,"image":""},{"id":"md5-106-1-51","subject":"md5","topic":"小兒外科","meta":"106年第1次第51題","year":106,"session":1,"number":51,"question":"梅克耳憩室（Meckel's diverticulum）所造成的下消化道出血，可利用下列何者做診斷？①99mTc-pertechnetate放射線同位素檢查 ②腹部超音波檢查 ③腹腔鏡探查 ④下消化道鋇劑攝影 ⑤大腸鏡檢查","options":["(A) ①③","(B) ②⑤","(C) ④⑤","(D) ②④"],"answer":0,"image":""},{"id":"md5-106-1-52","subject":"md5","topic":"小兒外科","meta":"106年第1次第52題","year":106,"session":1,"number":52,"question":"兒童威爾氏腫瘤（Wilm’s tumor）最容易發生轉移的是下列何種器官？","options":["(A) 腦部","(B) 肺臟","(C) 膀胱","(D) 骨骼"],"answer":1,"image":""},{"id":"md5-106-1-53","subject":"md5","topic":"小兒外科","meta":"106年第1次第53題","year":106,"session":1,"number":53,"question":"下列有關Meckel’s diverticulum之敘述，何者錯誤？","options":["(A) 通常是由vitelline duct退化而成","(B) 是造成小孩下消化道出血的原因之一","(C) 通常長在mesenteric border","(D) 掉入腹股溝疝氣袋內時，又稱為Littre’s hernia"],"answer":2,"image":""},{"id":"md5-106-1-54","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"106年第1次第54題","year":106,"session":1,"number":54,"question":"一位35歲男性患者因持續右側腹痛就醫，經下消化道攝影發現升結腸有一蘋果核（apple core）般的病灶，下列何者是不需要的檢查？","options":["(A) 大腸鏡切片檢查（colonoscopic biopsy）","(B) 電腦斷層（CT scan）","(C) 癌胚胎抗原（CEA）","(D) 甲型胎兒蛋白（AFP）"],"answer":3,"image":""},{"id":"md5-106-1-55","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"106年第1次第55題","year":106,"session":1,"number":55,"question":"下列有關結腸扭結（colonic volvulus）的敘述，何者錯誤？","options":["(A) 乙狀結腸是最常發生的部位","(B) 盲腸（cecum）扭結危險因子包括食物纖維的大量攝取、精神藥物的服用及腹部手術的既往史","(C) 盲腸（cecum）扭結應先嘗試大腸鏡還原再施行常規手術","(D) 盲腸（cecum）扭結常合併部份或全部升結腸的扭轉"],"answer":2,"image":""},{"id":"md5-106-1-56","subject":"md5","topic":"神經外科","meta":"106年第1次第56題","year":106,"session":1,"number":56,"question":"一位35歲男性發生車禍受傷，造成頸部疼痛、無法行走。經送往急診室，初步理學檢查顯示生命跡象穩定，意識清楚，右側上下肢肌力為5分，但痛覺和溫度感覺喪失，左側上下肢肌力為0分，但溫痛感覺正常，電腦斷層影像顯示第四頸椎骨折、神經壓迫。則此患者最有可能是下列何種脊髓損傷？","options":["(A) 前側脊髓症候群（anterior cord syndrome）","(B) 布朗賽卡氏症候群（Brown-Séquard syndrome）","(C) 中央脊髓症候群（central cord syndrome）","(D) 後側脊髓症候群（posterior cord syndrome）"],"answer":1,"image":""},{"id":"md5-106-1-57","subject":"md5","topic":"骨科-關節重建","meta":"106年第1次第57題","year":106,"session":1,"number":57,"question":"下列各種組織中，何者不是以第二型膠原蛋白（type II collagen）為主要組成成分？","options":["(A) 關節面的透明軟骨（hyaline cartilage）","(B) 膝關節內的半月板（meniscus）","(C) 脊椎椎間盤的髓核（nucleus pulposus）","(D) 脊椎椎間盤與椎體相鄰的終板（endplate）"],"answer":1,"image":""},{"id":"md5-106-1-58","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"106年第1次第58題","year":106,"session":1,"number":58,"question":"下列何種骨折最易造成股骨頭部壞死？","options":["(A) 股骨幹粉碎性骨折（femoral shaft comminuted fracture）","(B) 股骨轉子間骨折（femoral intertrochanteric fracture）","(C) 股骨轉子下骨折（femoral subtrochanteric fracture）","(D) 移位性股骨頸骨折（displaced femoral neck fracture）"],"answer":3,"image":""},{"id":"md5-106-1-59","subject":"md5","topic":"骨科-關節重建","meta":"106年第1次第59題","year":106,"session":1,"number":59,"question":"在施行初次全膝人工關節置換術時，則下列何組織在術中必須被切除？","options":["(A) 前十字韌帶（anterior cruciate ligament）","(B) 髕骨肌腱（patellar tendon）","(C) 內側副韌帶（medial collateral ligament）","(D) 外側副韌帶（lateral collateral ligament）"],"answer":0,"image":""},{"id":"md5-106-1-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"106年第1次第60題","year":106,"session":1,"number":60,"question":"有關骨骼巨大細胞瘤（giant cell tumor of bone）的敘述，下列何者正確？","options":["(A) 最常好發於10歲以下幼童的長骨骨幹，很少侵犯到骨骺（epiphysis）","(B) 最常見的X光發現是一個成骨性（osteoblastic）之破壞性病灶，且常有明顯的骨膜反應（periosteal reaction）","(C) 最常用的治療方式是廣泛切除（wide excision）手術","(D) 為避免局部復發（local recurrence），往往手術中需合併輔助器材，如高速磨鑽（high-speed burr）清除腫瘤或滑水泥填充等"],"answer":3,"image":""},{"id":"md5-106-1-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"106年第1次第61題","year":106,"session":1,"number":61,"question":"下列腦性麻痺（cerebral palsy）類型中，發生脊柱側彎（scoliosis）機率最低者為：","options":["(A) 四肢麻痺（quadriplegia）","(B) 半身麻痺（hemiplegia）","(C) 雙下肢麻痺（diplegia）","(D) 兩下肢加一上肢麻痺（triplegia）"],"answer":2,"image":""},{"id":"md5-106-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"106年第1次第62題","year":106,"session":1,"number":62,"question":"2歲男孩因右上肢活動受限，被父母帶來求診，右肘部的X光檢查結果如附圖，該男孩右上肢活動受限最嚴重的是下列何種動作？","options":["(A) 前臂旋後（forearm supination）","(B) 上臂外旋（arm external rotation）","(C) 手肘彎曲（elbow flexion）","(D) 手腕彎曲（wrist flexion）"],"answer":0,"image":"md5-106-1-62.jpeg"},{"id":"md5-106-1-63","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"106年第1次第63題","year":106,"session":1,"number":63,"question":"有關脊椎滑脫症（spondylolisthesis）引起疼痛、滑脫惡化及身體變形的危險因子，下列何者除外？","options":["(A) 年紀較輕","(B) 男性病人","(C) 反覆發作","(D) 大腿後側肌群過緊"],"answer":1,"image":""},{"id":"md5-106-1-64","subject":"md5","topic":"泌尿-結石與感染","meta":"106年第1次第64題","year":106,"session":1,"number":64,"question":"有關尿路結石形成之敘述，下列何者錯誤？","options":["(A) 形成尿酸結石（uric acid stone）的最重要因素是酸性的尿液（low urine pH）","(B) 感染性結石（infection stone）在酸性尿液（low urine pH）中較易形成","(C) 成年男性腎結石發生率較成年女性高","(D) 尿路結石的發生率與體重和身體質量比（BMI）有關"],"answer":1,"image":""},{"id":"md5-106-1-65","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第1次第65題","year":106,"session":1,"number":65,"question":"因車禍造成的膀胱破裂，以下何者正確？","options":["(A) 腹膜外膀胱破裂（extraperitoneal bladder rupture）的手術原則，是直接以腹膜外探查再進行縫合，而不須要腹膜內探查","(B) 骨盆骨折的病患，約有15%合併有膀胱或尿道受傷","(C) 腹膜內膀胱破裂（intraperitoneal bladder rupture）的手術原則，是以腹膜外探查並且進行膀胱傷口縫合，而不須要打開腹膜探查","(D) 腹膜外膀胱破裂（extraperitoneal bladder rupture）之膀胱攝影（cystography）可發現顯影劑分布在腸道之間"],"answer":1,"image":""},{"id":"md5-106-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"106年第1次第66題","year":106,"session":1,"number":66,"question":"有一位35歲運動員於健檢中，發現右腎邊緣區域有一個3.5公分的凸出實質腫瘤（不含脂肪），下列何種處置較適當？","options":["(A) 施行radical nephrectomy","(B) 施行細針穿刺切片進行診斷","(C) 施行partial nephrectomy","(D) 使用口服標靶藥物治療"],"answer":2,"image":""},{"id":"md5-106-1-67","subject":"md5","topic":"泌尿-腫瘤","meta":"106年第1次第67題","year":106,"session":1,"number":67,"question":"一位85歲血尿患者被診斷出膀胱原位癌（carcinoma in situ，CIS），若患者拒絕進行radical cystectomy，則下列何種膀胱內藥物灌注治療最能有效控制此症？","options":["(A) Bacillus Calmette-Guerin（BCG）","(B) mitomycin C","(C) doxorubicin","(D) gemcitabine"],"answer":0,"image":""},{"id":"md5-106-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"106年第1次第68題","year":106,"session":1,"number":68,"question":"薦髓傷害（sacral spinal cord injury）常發生的尿動力檢查異常是：","options":["(A) 逼尿肌過度反射（detrusor hyperreflexia）","(B) 逼尿肌無反射（detrusor areflexia）","(C) 逼尿肌尿道外括約肌共濟失調（detrusor- external sphincter dyssynergia）","(D) 低順應性（low compliance）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第68題一律給分。 (原公告答案 B)"},{"id":"md5-106-1-69","subject":"md5","topic":"泌尿-結石與感染","meta":"106年第1次第69題","year":106,"session":1,"number":69,"question":"有關急性細菌性前列腺炎之敘述，下列何者錯誤？","options":["(A) 通常細菌是由尿道進入或是因為感染的尿液回流至前列腺小管（prostatic ducts）造成","(B) 大人較常見，但是很少見於青春期前的男孩","(C) 為了取得急性期時之細菌培養，要進行前列腺按摩，再將解出之尿液或前列腺液送細菌培養","(D) 急性期時尿中及血液中之白血球常會上升"],"answer":2,"image":""},{"id":"md5-106-1-70","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"106年第1次第70題","year":106,"session":1,"number":70,"question":"有關勃起功能障礙的敘述，下列何者正確？","options":["(A) 每位病人應接受夜間陰莖勃起試驗（nocturnal penile tumescence test）","(B) 要補充男性荷爾蒙","(C) 第一線檢查應使用彩色都卜勒超音波","(D) 高血脂、糖尿病及高血壓會引起海綿體血管內皮細胞功能失調"],"answer":3,"image":""},{"id":"md5-106-1-71","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"106年第1次第71題","year":106,"session":1,"number":71,"question":"下列何者是女性假性陰陽人（female pseudohermaphroditism）最常見的原因？","options":["(A) 先天腎上腺增生（congenital adrenal hyperplasia）","(B) 母親懷孕時服用男性荷爾蒙","(C) Klinefelter's syndrome","(D) Turner's syndrome"],"answer":0,"image":""},{"id":"md5-106-1-72","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"106年第1次第72題","year":106,"session":1,"number":72,"question":"75歲男性，副甲狀腺素血液濃度上升，腹部X光檢查如附圖，其脊椎骨的變化為何？","options":["(A) renal osteodystrophy","(B) ankylosing spondylitis","(C) metastasis","(D) osteomyelitis"],"answer":0,"image":"md5-106-1-72.jpeg"},{"id":"md5-106-1-73","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第1次第73題","year":106,"session":1,"number":73,"question":"中年男性車禍傷患主訴上腹部劇痛，血壓呈現穩定狀態。電腦斷層檢查如附圖。箭頭所指之異常最可能是下列那一項初診斷？","options":["(A) liver laceration","(B) colon laceration","(C) pancreas laceration","(D) mesentery laceration"],"answer":2,"image":"md5-106-1-73.jpeg"},{"id":"md5-106-1-74","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"106年第1次第74題","year":106,"session":1,"number":74,"question":"27歲男性病人發生車禍造成右手疼痛，手部X光片如附圖，最正確的診斷為？","options":["(A) mallet fracture","(B) boxer's fracture","(C) Bennett fracture","(D) Colles fracture"],"answer":1,"image":"md5-106-1-74.jpeg"},{"id":"md5-106-1-75","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"106年第1次第75題","year":106,"session":1,"number":75,"question":"四肢的骨折常伴隨其它損傷，下列合併損傷有那些是正確的？①肩胛骨骨折伴隨肺部挫傷②腰椎骨折伴隨腹內損傷③膝關節脫臼伴隨股動脈損傷④跟骨骨折伴隨脊椎骨折","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":3,"image":""},{"id":"md5-106-1-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第1次第76題","year":106,"session":1,"number":76,"question":"下列何項檢查工具，在沒有尿道受損跡象時，是診斷膀胱破裂的黃金標準（golden standard）？","options":["(A) 泌尿道系統超音波","(B) 逆行性膀胱造影","(C) 順行性膀胱造影（靜脈腎盂造影）","(D) 加顯影劑之腹部電腦斷層"],"answer":1,"image":""},{"id":"md5-106-1-77","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"106年第1次第77題","year":106,"session":1,"number":77,"question":"一位27歲的男性，因手肘關節部位疼痛而來求診，經病史詢問及身體檢查發現，懷疑為肱骨外上髁炎（lateral epicondylitis），下列何者錯誤？","options":["(A) 肱骨外上髁是前臂、手腕、以及手指的伸肌（extensor）肌腱附著處（origin）","(B) 肱骨外上髁炎又稱為高爾夫球肘（golfer's elbow）","(C) 身體檢查可以發現肱骨外上髁處有壓痛","(D) 病患作前臂伸展（extension）及外旋（supination）抗阻力的動作時會有疼痛"],"answer":1,"image":""},{"id":"md5-106-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"106年第1次第78題","year":106,"session":1,"number":78,"question":"罹患糖尿病10餘年的林老太太最近不小心腳部受了傷，傷口一直沒有癒合，在診所換藥1個多星期傷口仍然沒有起色，因此診所醫師建議林老太太到醫院住院治療。住院後被診斷為蜂窩性組織炎，經過抗生素以及傷口換藥治療，傷口並沒有進步，反而有擴大的趨勢，醫師建議林老太太應該要進行清創治療，但林老太太聽到要開刀就有點害怕，拒絕了清創治療的建議。又經過1個多星期，連小腿都出現嚴重紅腫的狀況，醫師建議林老太太需要進行截肢手術，否則傷口繼續擴大，恐怕有生命危險。林老太太考慮了很久，只答應願意接受清創手術，但不想接受截肢手術。手術中，醫師為了傷口將來的癒合，幫林老太太進行了截肢手術。依照現行法規，你認為醫師的做法是否正確？","options":["(A) 正確，醫師是為了搶救林老太太的生命，因此雖然違反了她的意願，但符合她的最佳利益","(B) 正確，醫師依照醫療常規，進行了必要的截肢手術","(C) 不正確，林老太太明確地表明了不想接受截肢手術，依照安寧緩和醫療條例，應該尊重其意願","(D) 不正確，林老太太明確表明了不想接受截肢手術，而該手術也並非緊急手術，依此醫師不應該違反其意願而進行截肢手術"],"answer":3,"image":""},{"id":"md5-106-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"106年第1次第79題","year":106,"session":1,"number":79,"question":"6歲的小明因為車禍頭部外傷，急救回來後即依賴呼吸器，在加護病房治療1週後，現在情況惡化，瞳孔放大且出現尿崩現象，血壓靠著升壓劑維持在100/54 mmHg左右，可能已經腦死，家屬仍處於極度悲傷的階段。你若身為加護病房醫師，下列何者處置不適當？","options":["(A) 照會神經科醫師進行腦死評估","(B) 若血壓不穩定，醫師不能擅自停止升壓藥","(C) 徵詢家屬器官捐贈之意願","(D) 逕行移除呼吸器並轉出加護病房"],"answer":3,"image":""},{"id":"md5-106-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"106年第1次第80題","year":106,"session":1,"number":80,"question":"45歲膽囊炎切除後的男性病人，回到病房後，主治醫師發現術後追蹤的腹部X光片，有紗布殘留。下列敘述何者錯誤？","options":["(A) 向病人隱瞞醫療上發生的錯誤，可能會削弱大眾對於醫學的信賴","(B) 當病人受到醫療傷害時，他們有權尋求適度的矯正或賠償","(C) 為提升醫療品質，減少醫療錯誤的發生，應建立懲罰性的醫療錯誤通報制度","(D) 醫師應盡力不要以自我辯護或推諉卸責的方式進行告知"],"answer":2,"image":""},{"id":"md5-106-2-1","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"對於calcineurin inhibitors的敘述，下列何者正確？","options":["(A) tacrolimus（FK-506）和sirolimus都屬於calcineurin inhibitors，都作用在FK binding protein之上","(B) cyclosporine會有禿頭（alopecia）和牙齦增生（gingival hypertrophy）的副作用","(C) FK-506所引起的糖尿病有時候會在停藥之後恢復","(D) FK-506和cyclosporine都屬於腎臟移植術後用藥，不會有腎毒性的副作用"],"answer":2,"image":""},{"id":"md5-106-2-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"外傷病人的眼睛受痛刺激時會睜開，對刺激無言語反應（no response），對痛的刺激只有退縮反應（withdrawal）。昏迷指數（Glasgow coma scale, GCS）為何？","options":["(A) 8","(B) 9","(C) 10","(D) 7"],"answer":3,"image":""},{"id":"md5-106-2-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"下列與大量輸血相關的敘述，何者錯誤？","options":["(A) 大量輸血時，常規性給予碳酸氫鹽（bicarbonate）可以防止輸血後鹼中毒（alkalosis）","(B) 檸檬酸鹽血液製品（citrated blood products）的大量輸血，會導致鈣離子濃度短暫下降","(C) 大量輸血後會發生稀釋性血小板減少症（thrombocytopenia）","(D) 使用非新鮮的血液製品大量輸血時，有可能發生高鉀血症（hyperkalemia）"],"answer":0,"image":""},{"id":"md5-106-2-4","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"下列有關營養補充的敘述，何者錯誤？","options":["(A) 腸胃道有功能時應儘可能使用腸道餵食（enteral feeding）","(B) 從鼻胃管餵食時，為了防止餵食物反流和吸入，病人上半身應保持在90° 的坐姿","(C) 最常做的鼻胃管灌食是在開始時以10至20毫升／小時灌食，每4至6小時檢查胃殘留量，再決定是否增加灌食量","(D) 使用胃造瘻或空腸造瘻灌食的病人，可能會有肉芽組織在造瘻處過度積聚的情形"],"answer":1,"image":""},{"id":"md5-106-2-5","subject":"md5","topic":"神經外科","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"Pilocytic astrocytoma屬於WHO classification system of glioma中的：","options":["(A) Grade 1","(B) Grade 2","(C) Grade 3","(D) Grade 4"],"answer":0,"image":""},{"id":"md5-106-2-6","subject":"md5","topic":"神經外科","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"下列關於原發性腦瘤（primary brain tumor）的敘述，何者錯誤？","options":["(A) glioma中，惡性度最高的是glioblastoma multiforme（GBM）","(B) ependymoma好發於老年人","(C) medulloblastoma是孩童primary brain tumor最常見的種類","(D) medulloblastoma可能隨著CSF轉移至中樞神經系統的其他位置"],"answer":[1,2],"image":"","answer_note":"更正:第6題答Ｂ、Ｃ給分"},{"id":"md5-106-2-7","subject":"md5","topic":"神經外科","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"下列關於腰椎椎間盤突出（HIVD）的敘述，何者正確？","options":["(A) 發生位置多在椎間盤的後外側（posterolateral）","(B) 最常見的發生部位為腰椎第1-2節（L1-2）的椎間盤","(C) 位於腰椎第4-5節（L4-5）發生的HIVD通常會壓迫L4的神經根（nerve root）","(D) 所有的HIVD都一定需要手術處理"],"answer":0,"image":""},{"id":"md5-106-2-8","subject":"md5","topic":"神經外科","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"下列有關脊髓空洞症（syringomyelia）的敘述，何者錯誤？","options":["(A) 症狀類似中央脊髓症候群（central cord syndrome）","(B) 感覺喪失以本體感覺（proprioceptive）為主，痛及觸覺正常","(C) 上肢較下肢無力","(D) 核磁共振掃描（MRI）是檢查選擇之一"],"answer":1,"image":""},{"id":"md5-106-2-9","subject":"md5","topic":"神經外科","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"最常見的單一顱骨縫合過早（single-suture craniosynostosis）是何種？","options":["(A) 冠狀縫（coronal）","(B) 人字縫（lambdoid）","(C) 矢狀縫（sagittal）","(D) 蝶顳縫（sphenozygomatic）"],"answer":2,"image":""},{"id":"md5-106-2-10","subject":"md5","topic":"整形重建外科","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"關於下圖類型的病人，下列敘述那些是正確的？①約5000個活嬰可能會出現一個 ②可能有14%的病人伴隨其他先天性的畸型 ③病人後續的照顧需要多科專業的合作，包含整形外科、耳鼻喉科、小兒科、牙科、口腔外科、語言師、營養師、精神科醫師、社工等 ④通常建議嘴唇在3個月修復，上顎於12個月修復 ⑤若伴隨小耳症或耳朵缺失建議在7歲左右開始重建","options":["(A) ①②③④","(B) ②③④⑤","(C) ①③⑤","(D) ①④⑤"],"answer":[0,1,2,3],"image":"md5-106-2-10.jpeg","answer_note":"送分:第10題答Ａ、Ｂ、Ｃ、Ｄ給分 (原公告答案 B)"},{"id":"md5-106-2-11","subject":"md5","topic":"整形重建外科","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"軸式皮瓣（axial pattern flap）的血液循環來自：","options":["(A) 皮動脈及靜脈（cutaneous artery and vein）","(B) 只靠組織液之滲透供應其所需之營養","(C) 靠肌肉之血管（myocutaneous perforators）","(D) 只靠真皮之微血管（subdermal plexus）"],"answer":[0,2],"image":"","answer_note":"更正:第11題答Ａ、Ｃ給分"},{"id":"md5-106-2-12","subject":"md5","topic":"整形重建外科","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"關於臉部縫合技巧與如何減少疤痕增生之敘述，下列何者錯誤？","options":["(A) 臉部皮膚之切口（incision）須經詳細計畫與設計，不可任意切割傷口","(B) 臉部皮膚之切口須與皮膚鬆弛線（relax skin tension line）儘量平行","(C) 臉部皮膚之切口須儘量與皺紋方向垂直切開","(D) 臉部傷口之縫合需消除皮下死腔（dead space），使用較細之縫線縫合傷口"],"answer":2,"image":""},{"id":"md5-106-2-13","subject":"md5","topic":"心臟血管外科","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"下列有關靜脈竇型（sinus venosus）心房中隔缺損（atrial septal defect，ASD）之敍述，何者錯誤？","options":["(A) 常合併肺靜脈回流異常","(B) 缺損的位置，有時是在心房中隔底部接近下腔靜脈開口","(C) 手術修補時，一般需使用布塊（patch）修補","(D) 可以使用導管手術來關閉缺損"],"answer":3,"image":""},{"id":"md5-106-2-14","subject":"md5","topic":"心臟血管外科","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"下列關於心臟瓣膜置換手術中，置換瓣膜（prosthetic valve）的選擇，何者正確？①計畫生育之年輕女性患者可選擇機械型瓣膜（mechanical prosthesis） ②年齡大於70歲患者可選擇生物組織型瓣膜（bioprosthesis） ③血友病患者可選擇機械型瓣膜 ④尿毒症患者且須長期血液透析，可選擇組織型瓣膜","options":["(A) ①②③","(B) 僅①③","(C) ②④","(D) 僅④"],"answer":2,"image":""},{"id":"md5-106-2-15","subject":"md5","topic":"心臟血管外科","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"肺動脈瓣閉鎖合併心室中隔缺損（pulmonary atresia with ventricular septal defect）的病人，在接受初步手術時，所謂的單一化（unifocalization）是要將下列那些血管聚集在一起以準備第二階段手術之用？ ①自體的肺動脈（native pulmonary artery） ②主要的主動脈至肺動脈側枝循環（major aortopulmonary collateral arteries） ③自體的肺靜脈（native pulmonary vein） ④左冠狀動脈主支（left main coronary artery）","options":["(A) ①②","(B) ①③","(C) ②③","(D) ①④"],"answer":0,"image":""},{"id":"md5-106-2-16","subject":"md5","topic":"心臟血管外科","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"下列有關冠狀動脈疾病病人之處置，何者錯誤？","options":["(A) 三條冠狀動脈疾病之糖尿病病人接受冠狀動脈繞道手術，比接受支架置放術具有較好的長期存活","(B) 多條血管冠狀動脈疾病病人的治療方面，經皮冠狀動脈處置（percutaneous coronary intervention）與冠狀動脈繞道手術皆比藥物治療有顯著的生存利益","(C) 高嚴重性冠狀動脈疾病病人若以經皮冠狀動脈處置治療，其再處置率較接受冠狀動脈繞道手術者為高","(D) 具有高風險的特徵（例如：糖尿病、左心室功能異常、腎功能異常、年老、慢性肺病、周邊動脈疾病）的多條血管冠狀動脈疾病病人接受冠狀動脈繞道手術比接受經皮冠狀動脈處置具有較差的長期存活率"],"answer":3,"image":""},{"id":"md5-106-2-17","subject":"md5","topic":"胸腔外科","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"下列有關胸腺瘤（thymoma）之Masaoka staging之敘述，何者錯誤？","options":["(A) Stage IVa：胸腔外轉移","(B) Stage I：腫瘤之capsule完整，無capsule invasion","(C) Stage II為capsule invasion","(D) Masaoka Stage III為macroscopic invasion至周圍的器官，如心包膜、大血管或肺"],"answer":0,"image":""},{"id":"md5-106-2-18","subject":"md5","topic":"胸腔外科","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"氣管分岔處（carina）在胸部X光所在的高度約相應於脊椎那一個部位？","options":["(A) C6","(B) T1-2","(C) T4-5","(D) L2-3"],"answer":2,"image":""},{"id":"md5-106-2-19","subject":"md5","topic":"胸腔外科","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"有關肺癌的描述，下列何者正確？①adenocarcinoma是最常見的細胞型 ②squamous cell carcinoma的發生與抽菸最有關聯 ③squamous cell carcinoma常位於靠近肺門中央的位置 ④小細胞肺癌常可以經由手術切除得到治療","options":["(A) ①③④","(B) ①②③","(C) ①②④","(D) ②③④"],"answer":1,"image":""},{"id":"md5-106-2-20","subject":"md5","topic":"消化器外科","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"對於胃食道逆流疾病（gastroesophageal reflux disease）的外科手術適應症，何者錯誤？","options":["(A) 以proton pump inhibitor（PPI）治療無效的病人","(B) 預期proton pump inhibitor（PPI）治療會超過5年的病人","(C) 病人合併有嚴重ulcer","(D) 病人有Barrett's mucosa"],"answer":1,"image":""},{"id":"md5-106-2-21","subject":"md5","topic":"胸腔外科","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"關於胸腺瘤的敘述，下列何者錯誤？","options":["(A) 前上縱隔腔最常見的縱隔腔腫瘤","(B) 第二期的胸腺瘤開刀切除後，常須加上放射治療","(C) cisplatin的化療效果對其治療效果不佳","(D) 大部分重肌無力症（myasthenia gravis）無合併胸腺瘤"],"answer":2,"image":""},{"id":"md5-106-2-22","subject":"md5","topic":"消化器外科","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"一位63歲男性到門診主訴發現皮膚泛黃已三週，尿液呈深褐色，最近有灰白色大便，無腹部疼痛及不適，食慾稍差。下列何種檢查能快速做鑑別診斷？","options":["(A) 抽血驗B型、C型肝炎","(B) 測血中總膽紅素/直接型膽紅素指數","(C) 腹部超音波檢查","(D) 腹部電腦斷層檢查"],"answer":2,"image":""},{"id":"md5-106-2-23","subject":"md5","topic":"消化器外科","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"下圖是一位肝癌病人的電腦斷層攝影，根據Couinaud等所提出，依照門脈分枝的肝臟解剖學分葉，則腫瘤位於肝臟的那一個小葉？","options":["(A) 第Ⅱ分葉","(B) 第Ⅳ分葉","(C) 第Ⅵ分葉","(D) 第Ⅷ分葉"],"answer":1,"image":"md5-106-2-23.jpeg"},{"id":"md5-106-2-24","subject":"md5","topic":"消化器外科","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"下列有關疝氣（hernia）的敘述，何者錯誤？","options":["(A) 75%的疝氣發生在腹股溝區域（inguinal region）","(B) 以腹股溝疝氣（inguinal hernia）而言，三分之二屬於間接型疝氣（indirect hernia）","(C) 以腹股溝疝氣發生率而言，女性多於男性","(D) 以股疝氣（femoral hernia）發生率而言，女性多於男性"],"answer":2,"image":""},{"id":"md5-106-2-25","subject":"md5","topic":"消化器外科","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"下列有關急性腹症（acute abdomen）之敘述，何者錯誤？","options":["(A) 身體檢查發現肚臍周圍瘀青（periumbilical bruising）稱為Courvoisier’s sign","(B) 急性膽囊炎（acute cholecystitis）之轉移痛(referred pain）會轉移至右胸","(C) 消化性潰瘍穿孔（perforated peptic ulcer）之轉移痛(referred pain）會轉移至右側腰部","(D) mesenteric thrombosis or embolism引起之急性腹症需立刻施行手術"],"answer":0,"image":""},{"id":"md5-106-2-26","subject":"md5","topic":"消化器外科","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"影響胃排空（gastric empty）速率的因素，下列何者錯誤？","options":["(A) 熱量含量","(B) 營養成分","(C) 鹽分含量","(D) 食物固態或液態"],"answer":2,"image":""},{"id":"md5-106-2-27","subject":"md5","topic":"消化器外科","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"關於嚴重diabetic gastroparesis的手術治療方式，下列何者最不適當？","options":["(A) 胃切除","(B) 胃造口","(C) 空腸造口","(D) 胰臟移植"],"answer":0,"image":""},{"id":"md5-106-2-28","subject":"md5","topic":"消化器外科","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"下列有關胃腸間質瘤（gastrointestinal stromal tumors，GIST）之敘述，何者正確？","options":["(A) 發生部位以大腸的比率最高，迴腸其次，胃最少見","(B) 約80%的胃腸間質瘤會表現k-ras抗原","(C) 約40%的胃腸間質瘤在診斷時已經有淋巴腺轉移","(D) 對於轉移或無法手術切除的胃腸間質瘤，使用imatinib mesylate標靶治療的效果良好"],"answer":3,"image":""},{"id":"md5-106-2-29","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"一名84歲男性，因四天未解ъ，出現腹脹、陣發性腹痛等症૑而被送到急診。病患先前有慢性便秘病史，沒有接受過腹部手術，腹部X光檢查可看到明顯脹大之乙狀結腸，有bent inner tube sign。生命徵象穩定，理學檢查腹部有輕微壓痛，但無腹膜炎症狀，無腹股溝疝氣，下列初步處置何者最਺想？","options":["(A) 立即剖腹探查","(B) 胃鏡檢查","(C) 乙狀結腸鏡檢查並減壓","(D) 腹部超音波檢查"],"answer":2,"image":""},{"id":"md5-106-2-30","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"52歲女性病人診斷有甲狀腺乳突癌（papillary carcinoma），術前臨床分期為T3N1aMx，下列何種術式為最佳選擇？","options":["(A) 甲狀腺全切除術","(B) 甲狀腺全切除術及頸部第六區淋巴廓清術","(C) 甲狀腺全切除術及頸部第四、五、六區淋巴廓清術","(D) 甲狀腺全切除術及頸部第二、三、四、五、六區淋巴廓清術"],"answer":1,"image":""},{"id":"md5-106-2-31","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"下列何者不是因胚胎發育異常造成的甲狀腺組織位置變異？","options":["(A) 舌後甲狀腺（lingual thyroid）","(B) 異位性甲狀腺（ectopic thyroid）","(C) 迷路甲狀腺（lateral aberrant thyroid）","(D) 甲狀腺舌骨囊腫（thyroglossal duct cyst）"],"answer":2,"image":""},{"id":"md5-106-2-32","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"下列有關甲狀腺舌管囊腫（thyroglossal duct cyst）之敘述，何者錯誤？","options":["(A) 生長在頸部中央","(B) 不會發生乳突癌","(C) 有時會有細菌感染","(D) 手術時要將舌骨中央切除"],"answer":1,"image":""},{"id":"md5-106-2-33","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"下列有關乳房MRI檢查之敘述，何者錯誤？","options":["(A) 對於ductal carcinoma in situ（DCIS）之敏感度( sensitivity )可達90%","(B) 特異性( specificity)屬中等( moderate )而已","(C) 對於occult breast cancer之病人為相當有用的檢查","(D) 對於高風險( high risk )病人可作為篩檢( screening )檢查"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第33題一律給分 (原公告答案 A)"},{"id":"md5-106-2-34","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"乳癌病患接受改良式根治性乳房切除術（modified radical mastectomy）後，發生肩胛畸形（winged scapula deformity），表示下列何神經受損？","options":["(A) 胸背神經（thoracodorsal nerve）","(B) 長胸神經（long thoracic nerve）","(C) 內胸神經（medial pectoral nerve）","(D) 肋間臂神經（intercostal brachial nerve）"],"answer":1,"image":""},{"id":"md5-106-2-35","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"乳房X光攝影之篩檢報告為breast imaging reporting and data system（BI-RADS）category 0，下列的處置何者最適當？","options":["(A) 一年後再追蹤","(B) 直接手術切片","(C) 細胞針刺檢查","(D) 加做乳房超音波"],"answer":3,"image":""},{"id":"md5-106-2-36","subject":"md5","topic":"內分泌與乳房外科","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"有關乳癌危險因子之敘述，下列何者錯誤？","options":["(A) 母親或姊妹曾患乳癌者，罹患危險性較高","(B) 家族史或個人病史有子宮頸癌者，罹患危險性較高","(C) 家族史或個人病史有卵巢癌者，罹患危險性較高","(D) 初經早或停經晚者罹患危險性較高"],"answer":1,"image":""},{"id":"md5-106-2-37","subject":"md5","topic":"小兒外科","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"有關食道閉鎖（esophageal atresia）常合併的畸型，下列何者錯誤？","options":["(A) 肛門直腸異常（anorectal malformation）","(B) 腎臟及橈骨異常（renal or radius malformation）","(C) 小腸閉鎖（intestinal atresia）","(D) 脊柱缺損（vertebral defects）"],"answer":2,"image":""},{"id":"md5-106-2-38","subject":"md5","topic":"小兒外科","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"一個三週大的男嬰，因嘔吐而做了一些檢查；下列檢查結果，何者會發生在嬰兒型幽門肥厚狹窄（infantile hypertrophic pyloric stenosis）①腹部X光影像顯示有“double-bubble sign” ②腹部超音波發現胃幽門肌肉的厚度超過0.4公分 ③上消化道攝影（upper GI series）有string sign ④上腹部摸到一個像橄欖的腫塊（olive mass）","options":["(A) ①③④","(B) ①②④","(C) ②③④","(D) 僅①③"],"answer":2,"image":""},{"id":"md5-106-2-39","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"在HNPCC（hereditary nonpolyposis colorectal cancer）患者中，最常見的腸道外腫瘤為何？","options":["(A) 膀胱癌","(B) 胃癌","(C) 子宮內膜癌","(D) 卵巢癌"],"answer":2,"image":""},{"id":"md5-106-2-40","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"有關大腸pseudo-obstruction的描述，下列何者錯誤？","options":["(A) 又稱為Ogilvie’s syndrome，是在西元1948被提出的診斷","(B) 臨床上常見的大腸pseudo-obstruction原因以secondary為主，主要和合併使用嗎啡類止痛藥、甲狀腺機能異常、糖尿病、腎毒症等因素有關","(C) 治療方式可以考慮利用大腸鏡做診斷和減壓，不過要小心慎選病患，若懷疑大腸壞死就不可以施行","(D) 藥物治療可以考慮neostigmine，不過要小心病患施打藥物後會有bradycardia，需要仔細觀察心率變化，和準備dopamine作為緊急解毒劑"],"answer":3,"image":""},{"id":"md5-106-2-41","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"關於抑癌基因APC gene（adenomatous polyposis coli gene）的敘述，何者錯誤？","options":["(A) 只要APC gene突變就能產生大腸直腸癌","(B) 是家族性大腸息肉症的成因","(C) 是顯性遺傳","(D) 家族性大腸息肉症是大腸直腸癌的高危險群"],"answer":0,"image":""},{"id":"md5-106-2-42","subject":"md5","topic":"消化器外科","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"下列有關superior mesenteric artery（SMA）syndrome的敘述，何者錯誤？","options":["(A) 又名Wilkie’s syndrome","(B) 指duodenum 3rd portion被SMA壓迫","(C) 較易發生於年輕女性","(D) 較易發生於肥胖者"],"answer":3,"image":""},{"id":"md5-106-2-43","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"一位40歲女性因為升結腸癌接受右半結腸根除性手術，術後48小時高燒不退。請依此回答下列3題：下列何者是最可能的原因？","options":["(A) 肺炎（pneumonia）","(B) 吻合處滲漏（anastomotic site leakage）","(C) 肺部膨脹不全（lung atelectasis）","(D) 傷口感染（surgical wound infection）"],"answer":2,"image":""},{"id":"md5-106-2-44","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"下列何者是最合適的處理方法？","options":["(A) 做血液培養後給予廣效型抗生素","(B) 馬上進行剖腹探查去修補破洞","(C) 請病患深呼吸，並加強拍痰和咳痰","(D) 把傷口打開清創"],"answer":2,"image":""},{"id":"md5-106-2-45","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"病患經過處理之後狀況逐漸改善，不幸的是，在術後五天之後又再度高燒不退，下列處置何者錯誤？","options":["(A) 血球檢查、胸部X光、尿液分析和血液培養","(B) 若懷疑是導管相關感染，拔掉導管同時並給予vancomycin或是linezolid","(C) 假如懷疑是心內膜炎（endocarditis），至少要給予抗生素四到六週","(D) 若是嚴重的敗血症或是免疫抑制（immunosuppression）的病人，抗生素藥效須涵蓋gram-positive cocci和fungus"],"answer":[1,3],"image":"","answer_note":"更正:第45題答Ｂ、Ｄ給分"},{"id":"md5-106-2-46","subject":"md5","topic":"神經外科","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"20歲林同學，上課中突然意識昏迷被送急診，經一系列檢查如下圖。請依此回答下列3題：林同學可能診斷為何？","options":["(A) 高血壓腦出血（hypertensive intracranial hemorrhage）","(B) 蜘蛛膜下腔出血（subarachnoid hemorrhage）","(C) 動靜脈畸形破裂出血（arteriovenous malformation rupture）","(D) 類澱粉血管病變（amyloid angiopathy)"],"answer":2,"image":"md5-106-2-46.jpeg"},{"id":"md5-106-2-47","subject":"md5","topic":"神經外科","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"下列何項評估最能預測林同學的預後？","options":["(A) Spetzler-Martin grading system","(B) Hunt-Hess scale","(C) Fischer scale","(D) World Federation of Neurosurgical Societies classification"],"answer":0,"image":""},{"id":"md5-106-2-48","subject":"md5","topic":"神經外科","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"若林同學病灶大小為4公分，下列何項處置最為適當？","options":["(A) 立體定位放射手術（stereotactic radiosurgery）","(B) 放射線治療（radiotherapy）","(C) 僅以血管栓塞治療（endovascular embolization）即可","(D) 手術完全切除"],"answer":3,"image":""},{"id":"md5-106-2-49","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"下圖是一位80歲的病人，體重60公斤，因洗澡跌倒被熱水燙傷，意識清醒下送往急診。請依此回答下列3題：下列敘述那些正確？①建立輸液管道 ②此為1～2度燙傷 ③2～3度燙傷 ④18%體表面積受傷 ⑤9%體表面積受傷","options":["(A) ①②④","(B) ①②⑤","(C) ①③④","(D) ②③⑤"],"answer":2,"image":"md5-106-2-49.jpeg"},{"id":"md5-106-2-50","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"承上題，依Parkland formula，下列敘述何者正確？","options":["(A) 輸液前8小時給crystalloid溶液4320 mL","(B) 輸液前12小時給crystalloid溶液4320 mL","(C) 輸液前8小時給crystalloid溶液2160 mL","(D) 輸液前12小時給crystalloid溶液2160 mL"],"answer":2,"image":""},{"id":"md5-106-2-51","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第2次第51題","year":106,"session":2,"number":51,"question":"承上題，若依Curreri formula，則病人一天所需的能量為多少Kcal？","options":["(A) 1500 kcal","(B) 1860 kcal","(C) 2220 kcal","(D) 3000 kcal"],"answer":2,"image":""},{"id":"md5-106-2-52","subject":"md5","topic":"消化器外科","meta":"106年第2次第52題","year":106,"session":2,"number":52,"question":"一位50歲男性有十二指腸潰瘍的病史，但服藥不正常，最近因業務繁忙，老覺得上腹部疼痛。今天早晨一陣大痛後，忽然不痛了，但腹部腫漲。來到急診室，其最可能的臆診為何？","options":["(A) 急性膽囊炎","(B) 急性肝炎","(C) 膽囊破裂","(D) 十二指腸潰瘍穿孔"],"answer":3,"image":""},{"id":"md5-106-2-53","subject":"md5","topic":"消化器外科","meta":"106年第2次第53題","year":106,"session":2,"number":53,"question":"承上題，何種簡單檢查，即可做診斷？","options":["(A) 口服水溶劑對比劑檢查（oral water soluble contrast medium study）","(B) 內視鏡檢查","(C) 腹部超音波","(D) 胸部X光檢查"],"answer":3,"image":""},{"id":"md5-106-2-54","subject":"md5","topic":"小兒外科","meta":"106年第2次第54題","year":106,"session":2,"number":54,"question":"一個剛出生五天的嬰兒，有腹部腫脹（abdominal distention）和延遲性胎便排出（delayed meconium passage），下消化鋇劑攝影顯示如下：此病人最可能的診斷為何？","options":["(A) 胎便栓塞症候群（meconium plug syndrome）","(B) 細小左結腸症（small left colon syndrome）","(C) 巨結腸症（Hirschsprung's disease）","(D) 直腸閉鎖症（rectal atresia）"],"answer":2,"image":"md5-106-2-54.jpeg"},{"id":"md5-106-2-55","subject":"md5","topic":"小兒外科","meta":"106年第2次第55題","year":106,"session":2,"number":55,"question":"承上題，上述疾病的手術治療方法，下列何者錯誤？","options":["(A) Soave氏法","(B) Ramstedt氏法","(C) Duhamel氏法","(D) Swenson氏法"],"answer":1,"image":""},{"id":"md5-106-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"106年第2次第56題","year":106,"session":2,"number":56,"question":"一位22歲女性抱怨左膝疼痛3個月，問診時發現夜間疼痛加劇。身體檢查發現明顯局部壓痛，觸診時發現有組織腫塊。膝部X光片如下，此病患最有可能的診斷為：","options":["(A) 單純性骨囊腫（simple bone cyst）","(B) 骨肉瘤（osteosarcoma）","(C) 纖維性發育不全（fibrous dysplasia）","(D) 骨軟骨瘤（osteochondroma）"],"answer":1,"image":"md5-106-2-56.jpeg"},{"id":"md5-106-2-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"106年第2次第57題","year":106,"session":2,"number":57,"question":"關於遠端肱骨骨折（distal humeral fracture）之敘述，下列何者錯誤？","options":["(A) 健康成年人的移位性遠端肱骨的關節內骨折（displaced distal humeral intra-articular fracture）採用保守治療，其功能預後（functional outcome）不佳，故目前多建議手術治療","(B) 若使用後側入路（posterior approach）進行手術治療時，不需例行性地找出並保護尺神經（ulnar nerve）","(C) 對於較複雜的骨折，除了使用X光檢查之外，可輔以三度空間重建的電腦斷層掃描（computerized tomography with three-dimensional reconstruction）協助判讀骨折型態","(D) 對健康情況不良的老年人而言，若對於肘關節的功能需求不高時，則不論其遠端肱骨骨折的型態為何，皆可考慮保守治療"],"answer":[1,3],"image":"","answer_note":"更正:第57題答Ｂ、Ｄ給分"},{"id":"md5-106-2-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"106年第2次第58題","year":106,"session":2,"number":58,"question":"有關痙攣雙下肢型（spastic diplegia）腦性麻痺（cerebral palsy）之敘述，下列何者錯誤？","options":["(A) 大部分病童能走路","(B) 通常較晚才開始走路","(C) 若到7歲還不能走路，則日後能走路的機會變少","(D) 智能發展遲緩常會影響走路的能力"],"answer":3,"image":""},{"id":"md5-106-2-59","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"106年第2次第59題","year":106,"session":2,"number":59,"question":"50歲的男性，有肝癌病史。約在兩天前，突然發生嚴重的背痛且無法行走，磁振造影（MRI）檢查顯示在第十二胸椎出現腫瘤轉移，且有嚴重神經壓迫情形。病患亦被醫師告知有馬尾症候群（cauda equina syndrome）。下列何者不是馬尾症候群的典型症狀？","options":["(A) 大小便失禁或滯留","(B) 下肢深層肌腱反射（deep tendon reflex）增強","(C) 肛門周圍麻木","(D) 下肢無力"],"answer":1,"image":""},{"id":"md5-106-2-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"106年第2次第60題","year":106,"session":2,"number":60,"question":"關於脊椎的爆裂性骨折（burst fracture）之敘述，下列何者正確？","options":["(A) 發生機轉與脊椎的Chance氏骨折相同","(B) 容易發生在骨質疏鬆症的病人","(C) 脊椎體塌陷大於50%為不穩定骨折","(D) 與脊椎的壓迫性骨折（compression fracture）相比，較少發生神經損傷"],"answer":[1,2],"image":"","answer_note":"更正:第60題答Ｂ、Ｃ給分"},{"id":"md5-106-2-61","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"106年第2次第61題","year":106,"session":2,"number":61,"question":"有關急性肌腔室症候群（acute compartment syndrome）之敘述，下列何者錯誤？","options":["(A) 組織缺血（ischemia）常導致疼痛","(B) 施與被動式伸展時會疼痛（pain on passive stretch）與休息時會疼痛（rest pain）對診斷之敏感性（sensitivity）及特異性（specificity）差不多","(C) 神經缺血（ischemia）常導致感覺異常（paresthesia）及感覺遲鈍（hypoesthesia）","(D) 如果發現周邊脈搏（peripheral pulse）還存在，幾乎可以排除其可能性"],"answer":3,"image":""},{"id":"md5-106-2-62","subject":"md5","topic":"整形重建外科","meta":"106年第2次第62題","year":106,"session":2,"number":62,"question":"一位50歲左右的男性，雙手因無名指、小指屈曲攣縮影響功能來求診，手掌可摸到纖維性索條（fibrous cord）及變厚的皮膚，但無麻痺現象，下列何者正確？","options":["(A) 可能是正中神經麻痺（median nerve palsy）","(B) 手術無法治癒","(C) 好發於女性","(D) 可能是尺神經麻痺（ulnar nerve palsy）"],"answer":1,"image":""},{"id":"md5-106-2-63","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"106年第2次第63題","year":106,"session":2,"number":63,"question":"有關各種抗生素作用機轉的敘述，下列何者正確？","options":["(A) cephalosporins是抑制細菌細胞壁的合成與發展","(B) vancomycin是抑制細菌蛋白質的合成","(C) rifampin是抑制細菌去氧核醣核酸（DNA）的合成","(D) quinolones是抑制細菌核糖核酸（RNA）的合成"],"answer":0,"image":""},{"id":"md5-106-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"106年第2次第64題","year":106,"session":2,"number":64,"question":"Penicillamine常用來治療下列何種結石？","options":["(A) 草酸鈣結石（calcium oxalate stone）","(B) 尿酸結石（uric acid stone）","(C) 腎石灰沈著症（nephrocalcinosis）","(D) 胱氨酸結石（cystine stone）"],"answer":3,"image":""},{"id":"md5-106-2-65","subject":"md5","topic":"泌尿-腫瘤","meta":"106年第2次第65題","year":106,"session":2,"number":65,"question":"前列腺特定抗原（PSA）在不同的年齡層，有不一樣的正常值範圍，下列敘述何者錯誤？","options":["(A) 40～49歲，PSA正常值範圍是0.0～2.5 ng/mL","(B) 50～59歲，PSA正常值範圍是0.0～4.0 ng/mL","(C) 60～69歲，PSA正常值範圍是0.0～4.5 ng/mL","(D) 70～79歲，PSA正常值範圍是0.0～6.5 ng/mL"],"answer":1,"image":""},{"id":"md5-106-2-66","subject":"md5","topic":"泌尿-腫瘤","meta":"106年第2次第66題","year":106,"session":2,"number":66,"question":"下列何種癌症基因與「侵犯型」膀胱癌較無關連？","options":["(A) p16","(B) p21","(C) p53","(D) Rb gene"],"answer":0,"image":""},{"id":"md5-106-2-67","subject":"md5","topic":"泌尿-腫瘤","meta":"106年第2次第67題","year":106,"session":2,"number":67,"question":"下列有關前列腺癌之敘述，何者錯誤？","options":["(A) 多攝食含lycopene、selenium、Omega-3 fatty acid及vitamin E的食物，具有保護作用，比較不會產生前列腺癌","(B) 增加動物性脂肪或紅色肉類的攝取量會增加前列腺癌之發生","(C) 增加vitamin D及鈣之攝取會減低前列腺癌之發生","(D) 多吃魚肉或植物性食物可以減低前列腺癌發生"],"answer":2,"image":""},{"id":"md5-106-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"106年第2次第68題","year":106,"session":2,"number":68,"question":"下列有關良性前列腺肥大接受經尿道前列腺切除手術治療，產生TUR syndrome的敘述，何者錯誤？","options":["(A) 病人會有nausea、vomiting、confusion、hypertension、bradycardia、visual disturbance等症狀","(B) 主要是因手術時間太久，病人吸收太多之hypotonic irrigation solution所致","(C) 治療方法是應立即停止手術，給予病人利尿劑、normal saline或hypertonic saline","(D) TUR syndrome發生時，病人正處於hypervolemic及hypernatremic狀態"],"answer":3,"image":""},{"id":"md5-106-2-69","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"106年第2次第69題","year":106,"session":2,"number":69,"question":"有關生殖內分泌的描述，下列何者為非？","options":["(A) 男性荷爾蒙是由Leydig cells所分泌","(B) 男性荷爾蒙的分泌是受濾泡刺激激素FSH（follicle stimulating hormone）調控","(C) 腦下垂體性腺激素（pituitary gonadotropins）的分泌是受GnRH（gonadotropin releasing hormone）的調控","(D) 腦下垂體性腺激素的分泌也受男性荷爾蒙的負迴饋控制"],"answer":1,"image":""},{"id":"md5-106-2-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"106年第2次第70題","year":106,"session":2,"number":70,"question":"有關成人型多囊腎（adult polycystic kidney）的敘述，下列何者錯誤？","options":["(A) 是末期腎衰竭的原因之一","(B) 經常合併有肝囊腫（hepatic cysts）","(C) 症狀常在30至50歲之間才變得明顯","(D) 多數病人屬於退化性疾病，與遺傳無關"],"answer":3,"image":""},{"id":"md5-106-2-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"106年第2次第71題","year":106,"session":2,"number":71,"question":"一位30歲無精蟲的病人，兩側睪丸長徑約1 cm，血清中FSH、LH及testosterone都低於正常值，則最適當的檢查或治療為何？","options":["(A) 卵細胞質內精蟲注射（ICSI）","(B) 先做睪丸切片看有無精蟲","(C) HCG + recombinant FSH注射治療","(D) testosterone補充療法"],"answer":[2,3],"image":"","answer_note":"更正:第71題答Ｃ、Ｄ給分。"},{"id":"md5-106-2-72","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"106年第2次第72題","year":106,"session":2,"number":72,"question":"病人主訴右下腹逐漸悶痛、腹脹、反胃一整天。腹部電腦斷層檢查呈現如附圖。箭號所指之異常最符合下列那一項初診斷？","options":["(A) cecal diverticulitis","(B) acute appendicitis","(C) mesenteric adenitis","(D) colon cancer"],"answer":1,"image":"md5-106-2-72.jpeg"},{"id":"md5-106-2-73","subject":"md5","topic":"消化器外科","meta":"106年第2次第73題","year":106,"session":2,"number":73,"question":"65歲林先生，近日來感覺疲倦、食慾減退、皮膚發黃。血液檢查肝功能異常、CA-199值升高。醫師為他做CT檢查，影像如圖示。林先生最可能患了什麼病？","options":["(A) 肝內膽管癌（intrahepatic cholangiocarcinoma）","(B) 肝細胞癌（hepatocellular carcinoma）","(C) 胃癌（gastric cancer）","(D) 胰臟頭癌（pancreatic head cancer）"],"answer":3,"image":"md5-106-2-73.jpeg"},{"id":"md5-106-2-74","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"106年第2次第74題","year":106,"session":2,"number":74,"question":"15歲男生因鼠蹊部疼痛跛行而求診，其青蛙姿勢X光如圖示，則最可能診斷為何？","options":["(A) 肌肉拉傷","(B) 股骨頭近端生長板滑脫症","(C) 腹股溝疝氣","(D) 外陰部挫傷"],"answer":1,"image":"md5-106-2-74.jpeg"},{"id":"md5-106-2-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第2次第75題","year":106,"session":2,"number":75,"question":"一位70歲老先生沒繫妥安全帶，開小轎車撞上電線桿，顏面直接撞擊前面擋風玻璃，到達急診時顏面嚴重腫脹，口腔內有血絲，主訴頭部疼痛，下列敘述何者錯誤？","options":["(A) 治療老年外傷的傷患，病患的評估順序與一般外傷病患相同","(B) 老年人如有頭部外傷，症狀常延遲出現","(C) 隨著年齡增加，老年人的生理代償功能降低","(D) 老年人外傷的預後，與罹患之慢性病無關"],"answer":3,"image":""},{"id":"md5-106-2-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第2次第76題","year":106,"session":2,"number":76,"question":"當你接收到一位嚴重創傷已插有氣管內管插管（endotracheal tube）的轉診病人時，於下列所有情況都需懷疑有氣管插管誤入食道（esophageal intubation），那項除外？","options":["(A) end-tidal CO值近乎零2","(B) 擠甦醒球(bag-valve-mask)時聽不到呼吸聲","(C) 聽得見胃有雜聲（borborygmus）","(D) 可見到氣管內管內有霧氣進出"],"answer":3,"image":""},{"id":"md5-106-2-77","subject":"md5","topic":"外科-休克創傷傷口","meta":"106年第2次第77題","year":106,"session":2,"number":77,"question":"一位4歲女童被時速60公里機車撞擊，摔離5公尺之遠，送到急診時主訴腹痛，血壓68/40 mmHg，心跳每分鐘200下，女童體重20公斤，何種輸液最恰當？","options":["(A) 生理食鹽水800 ml加上400 ml全血","(B) 生理食鹽水800 ml加上200 ml全血","(C) 生理食鹽水200 ml重複3次，加上100 ml全血","(D) 生理食鹽水400 ml重複3次，加上200 ml全血"],"answer":3,"image":""},{"id":"md5-106-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"106年第2次第78題","year":106,"session":2,"number":78,"question":"小玉是17歲女學生，與已離婚的媽媽同住，親子關係良好。不幸地家裡發生火災，小玉因為逃生不及，被消防員救出時，全身皮膚有90%的燒燙傷，她媽媽傷心欲絕，在燒傷加護病房外等候，經歷3次清創，看到女兒全身包裹紗布處在鎮靜止痛的無意識狀態，主治醫師向她說明這麼大面積燒傷的感染與敗血症機會及死亡率很高。第4次要再進手術房清創時，媽媽拒絕進一步手術治療，因為她說女兒最愛漂亮，如果看到自己現在的樣子，一定寧可死了算了，於是簽署DNR（不予急救）。下列處置何者不恰當？","options":["(A) 應評估小玉行為能力，若判定有行為能力，則不能因應母親要求不予急救","(B) 不論決策者為媽媽或是小玉本人，都應考量此決策是否符合小玉之最大醫療利益","(C) 因為小玉沒有完全行為能力，可由媽媽決定不予急救","(D) 持續地與小玉媽媽溝通，確認她了解不予急救的意涵與可能後果"],"answer":2,"image":""},{"id":"md5-106-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"106年第2次第79題","year":106,"session":2,"number":79,"question":"下列何者不是構成知情同意（informed consent）的要素？","options":["(A) 隱私（privacy）","(B) 告知（disclosure）","(C) 決定能力（capacity）","(D) 自願（voluntariness）"],"answer":0,"image":""},{"id":"md5-106-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"106年第2次第80題","year":106,"session":2,"number":80,"question":"一位65歲女性病患因為血便，到胃腸科門診求診。經問診及理學檢查後，醫師建議進行大腸鏡檢查，也告知大腸鏡檢查的相關風險，經病患同意後進行大腸鏡檢查。大腸鏡發現乙狀結腸處有1.5公分大小瘜肉，黏膜呈不規則狀，有接觸性出血，懷疑可能為大腸癌。醫師當場切除該大型瘜肉，並在切除處用金屬夾，做出血或穿孔的預防性處理，手術進行順利。病患回家後，隔天開始覺得腹痛、胃口變差、噁心感。到急診就醫，發現大腸穿孔。下列關於醫師是否有醫療過失的相關敘述，何者最為正確？","options":["(A) 該醫師僅告知大腸鏡檢查的相關風險，並未告知大腸瘜肉切除的相關風險，已經明顯違反了醫師的告知義務","(B) 大腸鏡檢查以及大腸鏡合併瘜肉切除術，兩者本來都有大腸穿孔之相關風險，兩者風險種類一致，因此無需再特別告知大腸穿孔之風險","(C) 大腸鏡檢查與大腸合併瘜肉切除術，都一樣有大腸穿孔之風險，但兩者風險程度有別，如果大腸鏡檢查前，可以分別告知不同的風險會比較妥當，但是否有違反告知義務，應該具體檢視個案相關事實加以認定","(D) 該大腸瘜肉切除術，係有利於病患的最佳利益，可以直接加以切除，無需病患同意"],"answer":2,"image":""},{"id":"md5-107-1-1","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"下列與腹部腔室症候群（abdominal compartment syndrome）相關的症狀，何者錯誤？","options":["(A) 腹內壓突然增加","(B) 小便量減少","(C) 缺氧（hypoxia）","(D) 血壓正常"],"answer":3,"image":""},{"id":"md5-107-1-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"外傷病人使用各種輸液及血液製品來復甦急救，其目的在於使人體各個組織都能得到充足組織灌流（tissue perfusion）。尿液的排出量為一客觀實用之定量指標，則下列何者為正確指標？","options":["(A) 成人大於1毫升／公斤（體重）／小時，小孩大於0.5毫升／公斤（體重）／小時","(B) 成人大於0.5毫升／公斤（體重）／小時，小孩大於1毫升／公斤（體重）／小時","(C) 成人大於1毫升／公斤（體重）／小時，小孩大於1毫升／公斤（體重）／小時","(D) 成人大於0.5毫升／公斤（體重）／小時，小孩大於0.5毫升／公斤（體重）／小時"],"answer":1,"image":""},{"id":"md5-107-1-3","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"下列何者不是器官移植之後使用的抗排斥藥物？","options":["(A) basiliximab","(B) rabbit antithymocyte globulin","(C) tacrolimus","(D) valacyclovir"],"answer":3,"image":""},{"id":"md5-107-1-4","subject":"md5","topic":"胸腔外科","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"下列何者不是脫離呼吸器（weaning from ventilator）的條件？","options":["(A) 呼吸速率 < 25 / minute","(B) 動脈血氧氣分壓（PaO）> 70 mmHg（FiO 40%）22","(C) 潮氣量（tidal volume）5～6 mL/kg","(D) 每分鐘通氣量（minute ventilation）> 9 L / minute"],"answer":3,"image":""},{"id":"md5-107-1-5","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"外傷病人有下列何種情況時不做腹部電腦斷層攝影檢查（abdominal computed tomography）？","options":["(A) 腹部鈍挫傷（abdominal blunt trauma）","(B) 評估是否有胰臟受傷","(C) 身體評估無法判斷腹部是否受傷","(D) 病人血壓為65〜72 mmHg，脈搏為108〜112 /分鐘，呼吸20〜25 /分鐘"],"answer":3,"image":""},{"id":"md5-107-1-6","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"下列何者是治療麻醉氣體引起的惡性高溫（malignant hyperthermia）最主要的藥物？","options":["(A) propranolol","(B) dantrolene","(C) doxazosin","(D) nifedipine"],"answer":1,"image":""},{"id":"md5-107-1-7","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"下列有關微量元素（trace element）的敘述何者錯誤？","options":["(A) beriberi disease是因為缺乏硒（selemuim）","(B) 缺乏鋅（zinc）會造成禿頭（alopecia）","(C) 接受過胃切除的病患容易缺乏鐵（iron）","(D) 缺乏vitamin D會造成骨質疏鬆（osteoporosis）"],"answer":0,"image":""},{"id":"md5-107-1-8","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"低血容性休克（hypovolemic shock）是下列那一個情形？中心靜脈壓動脈壓心輸出量混合靜脈血氧飽和度A ↓ ↓ ↓ ↓ B ↑ ↓ ↓ ↓ C ↑ ↓ ↓ ↑ D ↑ ↑ ↑ ↓ 中心靜脈壓（central venous pressure），動脈壓（arterial blood pressure），心輸出量（cardiac output），混合靜脈血氧飽和度（mixed venous oxygenation saturation）","options":["(A) A","(B) B","(C) C","(D) D"],"answer":0,"image":"md5-107-1-8.jpeg"},{"id":"md5-107-1-9","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"28歲工人，工作時搬運重物滑倒撞及肩膀，腋下瘀青腫脹疼痛，發現手臂麻木且無力抬高。經X光檢查後並無骨折或脫臼情形。此病患最有可能是下列那一條神經受傷？","options":["(A) 正中神經（median nerve）","(B) 尺神經（ulnar nerve）","(C) 橈神經（radial nerve）","(D) 臂神經叢（brachial plexus）"],"answer":3,"image":""},{"id":"md5-107-1-10","subject":"md5","topic":"神經外科","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"下列有關顱內動靜脈畸形（arteriovenous malformation, AVM）的敘述，何者錯誤？","options":["(A) AVM的組成包括灌流的動脈，引流的靜脈，交通動靜脈的微血管","(B) AVM常出現的症狀包括有出血、癲癇及局部缺血","(C) 雖然CT及MRI可以診斷，但最好的診斷工具為顱內四條血管的血管攝影（four –vessels cerebral angiography）","(D) AVM 24小時內再出血的機率比動脈瘤低"],"answer":0,"image":""},{"id":"md5-107-1-11","subject":"md5","topic":"神經外科","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"下列關於glioblastoma multiforme的治療，何者正確？","options":["(A) 不論接受何種治療，病患都有良好的預後","(B) 手術切除加術後放射線治療及化學治療是目前效果最佳的治療方式","(C) 若可手術切除，可不做術後放射線治療及化學治療","(D) 腫瘤可與周邊正常組織清楚區分，容易手術完全切除"],"answer":1,"image":""},{"id":"md5-107-1-12","subject":"md5","topic":"神經外科","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"對於頭部外傷的病人，下列何種方法降低腦壓的效果最差？","options":["(A) 頭抬高30度","(B) 使用mannitol或glycerol等藥物","(C) hypoventilation","(D) craniectomy"],"answer":2,"image":""},{"id":"md5-107-1-13","subject":"md5","topic":"神經外科","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"下列有關脊髓腫瘤之敘述，何者錯誤？","options":["(A) 髓膜外（extradural）的腫瘤往往是良性的","(B) 髓膜內（intradural）、脊髓外（extramedullary）的腫瘤以meningioma及schwannoma最常見","(C) 脊髓內（intramedullary）腫瘤以astrocytoma最常見","(D) 脊髓惡性腫瘤的預後不良"],"answer":0,"image":""},{"id":"md5-107-1-14","subject":"md5","topic":"神經外科","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"40歲男性病患發現有兩側顳葉偏盲（bitemporal hemianopsia）症狀，泌乳激素值為49 ng/mL（prolactin level of 49 ng/mL），磁振造影檢查（MRI）如下列圖示，對此病灶最佳治療選擇為何？","options":["(A) bromocriptine藥物治療","(B) 先投與bromocriptine藥物治療，隨後手術治療","(C) 放射治療（radiation therapy）","(D) 手術治療"],"answer":3,"image":"md5-107-1-14.jpeg"},{"id":"md5-107-1-15","subject":"md5","topic":"整形重建外科","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"嚴重的眼瞼下垂（ptosis）應採取下列那一種手術方式比較適合？","options":["(A) 筋膜懸吊（fascial sling）","(B) 提瞼肌切除（levator resection）","(C) 提瞼肌懸吊（levator plication）","(D) 提瞼肌前移（levator advancement）"],"answer":0,"image":""},{"id":"md5-107-1-16","subject":"md5","topic":"整形重建外科","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"一位60歲男性患者因車禍被送來醫院，經理學檢查發現於左下肢小腿遠端1/3處，有一約10公分直徑缺損，從傷口上可見到脛骨及肌腱外露現象（如下圖），X光檢查也呈現骨折狀況，病人的其他身體檢查及實驗室檢查都正常。根據「重建選項」（reconstructive options）的建議，下列何種重建方式是第一選擇？","options":["(A) 部分層皮植皮術（split-thickness skin graft）","(B) 局部前移皮膚皮瓣（local advanced skin flap）","(C) 局部肌皮瓣（regional muscle flap）","(D) 游離皮瓣移植（free tissue transfer）"],"answer":3,"image":"md5-107-1-16.jpeg"},{"id":"md5-107-1-17","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"40歲健康工人於密閉工廠工作時遭遇火警，逃生通道卻又被雜物堵塞。此工人經過一段時間搬離雜物才脫離火場。現場濃煙密布，他吸入不少煙霧；加上他的臉被燻黑、鼻毛及前額毛髮又被燒焦、兩側上肢也被燒傷，因而來急診求診。關於他的傷勢及醫療處置，下列敘述何者錯誤？","options":["(A) 此病患有可能遭受肺部吸入性灼傷（inhalation injury）","(B) 因為此傷患沒有聲音沙啞（hoarseness）、哮喘（wheezing）、或含碳渣痰液（carbonaceous sputum），胸部X光也沒有異常因此不應該立即進行支氣管鏡或氣管插管等侵入性診治。","(C) 臨床研究顯示，液體限制（fluid restriction）無法預防吸入性灼傷引起的肺水腫","(D) 在後續的治療上，除非有證據顯示肺臟感染，不建議一開始就給予預防性抗生素"],"answer":1,"image":""},{"id":"md5-107-1-18","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"病人都希望表皮腫瘤切除時留下的疤痕不明顯，下列的切痕設計那一個較不能達到良好的結果？","options":["(A) A","(B) B","(C) C","(D) D"],"answer":0,"image":"md5-107-1-18.jpeg"},{"id":"md5-107-1-19","subject":"md5","topic":"心臟血管外科","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"下圖45歲男性，急性冠狀動脈阻塞導至心因性休克，緊急做完冠狀動脈繞道手術後，心臟收縮能力不好，因此放上了主動脈氣球幫浦及葉克膜氧合器，送往加護病房觀察，左腳六個小時後發現有鼓脹的情形，下列敘述何者錯誤？①肢端的脈搏先確認 ②有可能血液中肌酸激酶（CK）會提高 ③可以量測腔室的壓力，若大於20 mmHg可能要作筋膜切開手術 ④小腿有五個腔室：anterior、deep posterior、superficial posterior、lateral和medial","options":["(A) 僅①②","(B) ②③","(C) ③④","(D) ①②④"],"answer":2,"image":"md5-107-1-19.jpeg"},{"id":"md5-107-1-20","subject":"md5","topic":"整形重建外科","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"傷口重建的原則及方法有①skin graft ②myocutaneous flap ③free flap ④linear closure ⑤skin flap，重建的思考順序是：","options":["(A) ①②③④⑤","(B) ④⑤①③②","(C) ④①⑤②③","(D) ④⑤③①②"],"answer":2,"image":""},{"id":"md5-107-1-21","subject":"md5","topic":"心臟血管外科","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"何種類型的心房中膈缺損（atrial septal defect）最常合併部份肺靜脈回流異常（partial abnormal pulmonary venous return）？","options":["(A) primum type","(B) secondum type","(C) sinus venosus type","(D) coronary septal defect type"],"answer":2,"image":""},{"id":"md5-107-1-22","subject":"md5","topic":"心臟血管外科","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"下列有關原發性心臟內腫瘤之敘述，何者錯誤？","options":["(A) 原發性心臟內腫瘤約25%為良性，約75%為惡性","(B) 成人最常見原發性良性心臟內腫瘤為myxoma","(C) 15歲以下孩童最常見原發性良性心臟內腫瘤為rhabdomyoma","(D) 即便是原發性良性心臟內腫瘤，一旦有心衰竭、栓塞症狀及感染心內膜炎，便要考慮手術治療"],"answer":0,"image":""},{"id":"md5-107-1-23","subject":"md5","topic":"心臟血管外科","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"下列有關主動脈剝離（aortic dissection）之敘述，何者錯誤？","options":["(A) 主動脈剝離病人往往合併有高血壓或主動脈瓣膜疾病","(B) 診斷的方式包含主動脈攝影、食道超音波、電腦斷層或核磁共振，診斷的sensitivity及specificity皆有80%以上","(C) 凡是急性升主動脈剝離（acute type A aortic dissection），需要馬上接受手術治療","(D) 在type A或type B主動脈剝離產生的器官灌注不良（mal-perfusion syndrome）中，以腦部及腸道最常見"],"answer":3,"image":""},{"id":"md5-107-1-24","subject":"md5","topic":"心臟血管外科","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"一位56歲男性病人因胸悶住院。他有糖尿病、高血壓、與抽菸史。冠狀動脈血管攝影檢查顯示左冠狀動脈主幹85% 狹窄、左前降支80%狹窄、左回旋支77%狹窄、右冠狀動脈90%狹窄。下列敘述何者正確？①依冠狀動脈血管攝影檢查前家屬之決定，立即裝置塗藥支架（drug-eluting stent） ②冠狀動脈血管攝影檢查時，經與家屬商量後，立即裝置裸金支架（bared-metal stent） ③裝置支架前，不須請心臟外科醫師向病人及其家屬解釋冠狀動脈繞道手術之優缺點 ④裝置支架時，手術室須準備好，以便可立即進行緊急手術","options":["(A) ①②③","(B) 僅①③","(C) ②④","(D) 僅④"],"answer":3,"image":""},{"id":"md5-107-1-25","subject":"md5","topic":"心臟血管外科","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"下列關於不停跳冠狀動脈繞道手術（off-pump coronary artery bypass grafting）的敘述，何者正確？①須使用heparin ②人工心肺機不需待命 ③不須降低體溫 ④不會引發腦中風","options":["(A) ①②③","(B) 僅①③","(C) ②④","(D) 僅④"],"answer":1,"image":""},{"id":"md5-107-1-26","subject":"md5","topic":"胸腔外科","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"下列何者為肺部切除手術前最重要的檢查？","options":["(A) total lung capacity","(B) vital capacity","(C) forced expiratory volume in 1 second（FEV）1","(D) expiratory reserve volume"],"answer":2,"image":""},{"id":"md5-107-1-27","subject":"md5","topic":"胸腔外科","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"最常見的原發氣管內惡性腫瘤為：","options":["(A) adenocarcinoma","(B) squamous cell carcinoma","(C) small cell carcinoma","(D) carcinoid tumor"],"answer":1,"image":""},{"id":"md5-107-1-28","subject":"md5","topic":"胸腔外科","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"有關氣管食道瘻管的臨床表現，下列何者較不常見？","options":["(A) 大量的氣管分泌物的產生","(B) 呼吸音可聽到stridor","(C) X光常可見到胃脹氣的現象","(D) 易伴隨呼吸道或肺部感染"],"answer":1,"image":""},{"id":"md5-107-1-29","subject":"md5","topic":"胸腔外科","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"有關於hiatal hernia之描述，下列何者正確？","options":["(A) sliding hiatal hernia（type I）常伴隨胃酸逆流之症狀","(B) paraesophageal hiatal hernia指的是腹部的大腸、小腸等herniation to the chest","(C) paraesophageal hiatal hernia與sliding hiatal hernia是不同的兩種情形，不會同時出現","(D) 絕大部分的sliding hiatal hernia須接受手術治療"],"answer":0,"image":""},{"id":"md5-107-1-30","subject":"md5","topic":"消化器外科","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"下列何者為肺最常見的良性腫瘤？","options":["(A) lipoma","(B) leiomyoma","(C) hamartoma","(D) papilloma"],"answer":2,"image":""},{"id":"md5-107-1-31","subject":"md5","topic":"消化器外科","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"關於胃癌之敘述，下列何者錯誤？","options":["(A) Borrmann第三型胃癌（Borrmann type 3）是指潰瘍型胃癌合併胃壁侵犯（ulcerating lesions with infiltration into gastric wall）","(B) 腸型（intestinal type）胃癌較常為分化良好胃癌（well differentiated），且轉移方式較常為血液轉移（hematogenous spread）","(C) 瀰漫型（diffuse-type）胃癌在高發生率區域較腸型（intestinal-type）胃癌為多，且預後較差","(D) APC（adenomatous polyposis coli）gene mutation（基因突變）較常發生在腸型（intestinal type）胃癌"],"answer":2,"image":""},{"id":"md5-107-1-32","subject":"md5","topic":"消化器外科","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"一位50歲男性；最近二週，尿液變深、灰白便、身體發癢、皮膚逐漸變黃，因此到院檢查。身體診察發現鞏膜變黃，下肢無水腫，其CT影像上可見胰臟頭部有4公分左右腫瘤合併總膽管及胰管擴大，針對此病患安排下列處置何者最不適當？","options":["(A) 安排血管攝影栓塞","(B) 測定CEA，CA19-9","(C) 進行ERCP（endoscopic retrograde cholangiopancreatography）或EUS（endoscopic ultrasonography）合併切片","(D) 進行核磁共振膽胰攝影（MRCP）"],"answer":0,"image":""},{"id":"md5-107-1-33","subject":"md5","topic":"消化器外科","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"下列何種癌症一般不以胰頭十二指腸切除術（pancreaticoduodenectomy，Whipple's resection）來處理？","options":["(A) 十二指壺腹部癌症（ampulla vater cancer）","(B) 胰臟鈎部癌症（pancreatic uncinate cancer）","(C) 膽囊癌（gall bladder cancer）","(D) 遠端膽管癌（distal common bile duct cancer）"],"answer":2,"image":""},{"id":"md5-107-1-34","subject":"md5","topic":"消化器外科","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"造成減重手術Roux-en-Y gastric bypass術後死亡（mortality）的原因，下列敘述何者錯誤？","options":["(A) 術後30天的死亡率約0.3%～0.5%","(B) 女性病人也是危險因子（risk factor）之一","(C) 肺動脈栓塞是常見的因子之一","(D) 心臟病變（cardiac event）是常見因子之一"],"answer":1,"image":""},{"id":"md5-107-1-35","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"17歲男性，早上起床時覺得肚臍周圍悶悶的不舒服，整天食慾不振，到了晚上腹痛轉移到右下腹，有輕微發燒到38.3度，理學檢查顯示局部右下疼痛，沒有反彈痛，則這個男孩最可能的診斷是？","options":["(A) 大腸癌破裂","(B) 急性闌尾炎","(C) 急性憩室炎","(D) 腸套疊"],"answer":1,"image":""},{"id":"md5-107-1-36","subject":"md5","topic":"消化器外科","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"一位51歲男性，30年前即被診斷為B型肝炎帶原者。病患以往身體無其他不適，每天喝酒（高梁酒約100～ 150 c.c.）。最近一個月陸續有腹痛、嘔吐及下痢。到醫院門診時，生命跡象正常，但眼膜有些黃疸（jaundice），則下一步最不需要何種檢查？","options":["(A) 血清胎兒蛋白指數（α-fetoprotein）","(B) 血清梅毒檢查","(C) 凝血時間檢查","(D) 肝功能"],"answer":1,"image":""},{"id":"md5-107-1-37","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"有關多發性內分泌贅瘤症候群（multiple endocrine neoplasia，MEN）的敘述，下列何者錯誤？","options":["(A) MEN 1包含副甲狀腺機能亢進（hyperparathyroidism）","(B) MEN 2A包含甲狀腺髓質癌（medullary thyroid carcinoma）","(C) MEN 2B包含甲狀腺髓質癌（medullary thyroid carcinoma）","(D) MEN 2C包含嗜鉻細胞瘤（pheochromocytoma）"],"answer":3,"image":""},{"id":"md5-107-1-38","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"胰島素瘤（insulinoma）的臨床診斷為Whipple triad，即：","options":["(A) 低血糖症狀、血糖低於50 mg/dL及有服用糖尿病藥物史","(B) 低血糖症狀、血糖低於50 mg/dL及口服葡萄糖後可改善症狀","(C) 低血糖症狀、血糖低於50 mg/dL及靜脈注射葡萄糖後可改善症狀","(D) 低血糖症狀、血糖低於50 mg/dL及有使用胰島素注射史"],"answer":[1,2],"image":"","answer_note":"更正:第38題答Ｂ、Ｃ給分"},{"id":"md5-107-1-39","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"放射碘（radioiodine）治療應施行於分化明確甲狀腺癌（well-differentiated thyroid carcinoma），何者錯誤？","options":["(A) 所有III、IV期病人","(B) 所有II期45歲以下病人","(C) 大部分II期45歲以上病人","(D) I期病人"],"answer":3,"image":""},{"id":"md5-107-1-40","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"70歲男性右乳暈下發現腫塊、疼痛，下列何項檢查最不需要？","options":["(A) 胸部X光","(B) 乳房超音波","(C) 男性荷爾蒙檢驗","(D) 細針抽取細胞檢查"],"answer":0,"image":""},{"id":"md5-107-1-41","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"20歲年輕女性，左乳外側觸摸到一粒1公分×1公分，表面平滑可移動之乳房腫瘤，最適合的診斷工具為何？","options":["(A) 胸部X光攝影","(B) 乳房X光攝影","(C) 乳房超音波","(D) 全身麻醉手術切除"],"answer":2,"image":""},{"id":"md5-107-1-42","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"乳癌最常見轉移部位為下列何者？","options":["(A) 腦部","(B) 骨骼","(C) 肺部","(D) 肝臟"],"answer":1,"image":""},{"id":"md5-107-1-43","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"陳女士48歲，右側乳房發現有3公分大小的腫瘤，經粗針穿刺證實為侵犯性乳管癌，右鎖骨上同時有1.5公分大小的淋巴結，細針穿刺發現癌細胞，安排後續影像檢查，下列何者不適宜？","options":["(A) 正子攝影( PET )","(B) 骨骼掃描( bone scan )","(C) 肺臟超音波( lung sonography )","(D) 肝臟超音波( liver sonography )"],"answer":2,"image":""},{"id":"md5-107-1-44","subject":"md5","topic":"小兒外科","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"下列那些疾病好發在左側？①精索靜脈曲張（varicocele） ②腹裂（gastroschisis） ③隱睪症（undescended testis） ④ Bochdalek型先天性橫膈膜疝氣（Congential diaphragmatic hernia, Bochdalek type）","options":["(A) ①②","(B) ①③","(C) ②④","(D) ①④"],"answer":3,"image":""},{"id":"md5-107-1-45","subject":"md5","topic":"胸腔外科","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"關於肺外型游離肺（extra-pulmonary sequestration）的敘述，下列何者錯誤？","options":["(A) 其血液供應來自體循環","(B) 與支氣管有相通及氣體交流","(C) 大部分發生在肺下葉","(D) 較常見於左肺"],"answer":1,"image":""},{"id":"md5-107-1-46","subject":"md5","topic":"小兒外科","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"關於先天性肛門直腸異常（anorectal anomalies），下列何者型態之病患的排便功能預後較佳？","options":["(A) 無肛症併直腸尿道瘻管（imperforate anus with rectourethral fistula）","(B) 無肛症併直腸陰道瘻管（imperforate auns with rectovaginal fistula）","(C) 無肛症併直腸會陰瘻管（imperforate anus with rectoperineal fistula）","(D) 泄殖腔畸型（cloacal malformation）"],"answer":2,"image":""},{"id":"md5-107-1-47","subject":"md5","topic":"小兒外科","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"一個食道閉鎖（esophageal atresia）的新生兒，腹部X光顯示沒有腸氣的存在，下列何者發生率較高？","options":["(A) 食道閉鎖併遠端氣管食道瘻管","(B) 食道閉鎖併近端氣管食道瘻管","(C) 食道閉鎖無合併氣管食道瘻管","(D) 食道閉鎖併近端遠端氣管食道瘻管"],"answer":2,"image":""},{"id":"md5-107-1-48","subject":"md5","topic":"小兒外科","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"有關先天性膽道閉鎖症（biliary atresia）的敘述，下列何者錯誤？","options":["(A) 病人有持續性的黃疸","(B) 大便呈灰白色（clay color）","(C) 多數病患接受葛西氏手術（Kasai’s operation）後預後良好，不需肝臟移植","(D) 診斷時需先排除新生兒肝炎（neonatal hepatis）的可能性"],"answer":2,"image":""},{"id":"md5-107-1-49","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"下列有關在進行常規（elective）大腸手術前，術前準備工作有新的觀念和看法，何者錯誤？","options":["(A) 進行bowel preparation時，有些病患會接受抗生素治療降低腸內菌量；大腸最常見的細菌是厭氧的Bacteroides","(B) 有證據顯示術前施打抗生素，必須在劃刀前30分鐘內施打；若手術時間過長，需要每隔4小時再補抗生素劑量，可以有效降低傷口發生感染的機會","(C) 若是臨床上考慮進行mechanical bowel cleansing，針對腎臟功能不佳的患者，選擇sodium phosphate類的灌腸劑，相對polyethylene glycol solution，較少發生嚴重電解質不平衡的情形","(D) 近幾年關於fast track surgery的研究發現，常規長時間讓病患術前禁食，對於腸胃道排空功能正常患者，反而會有腸黏膜萎縮進而增加感染的機會"],"answer":2,"image":""},{"id":"md5-107-1-50","subject":"md5","topic":"消化器外科","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"一位55歲男性，因上腹劇痛被家人送到急診治療，病患2年前曾因胃癌接受胃次全切除（subtotal gastrectomy and B II anastomosis），理學檢查發現上腹有壓痛情形，但沒有muscle guarding and 3 rebounding pain，抽血檢查發現：WBC：12,000 / mm，Alk-P：95 U / L，rGT：75 U/L，total Bilirubin：3.5 mg/dL，Amylase：1,054 U/L，Lipase：7,000 U/L，電腦斷層如下，則可能的診斷為何？","options":["(A) 胰臟炎（pancreatitis）","(B) 腸阻塞（intestinal obstruction）","(C) 缺血性腸壞死（ischemic bowel）","(D) 輸入腸端症候群（afferent loop syndrome）"],"answer":3,"image":"md5-107-1-50.jpeg"},{"id":"md5-107-1-51","subject":"md5","topic":"消化器外科","meta":"107年第1次第51題","year":107,"session":1,"number":51,"question":"承上題，下列何種處置方式可行？","options":["(A) 經驗性抗生素治療","(B) 血管攝影檢查","(C) 胃鏡檢查","(D) 剖腹探查"],"answer":3,"image":""},{"id":"md5-107-1-52","subject":"md5","topic":"消化器外科","meta":"107年第1次第52題","year":107,"session":1,"number":52,"question":"60歲肥胖男性病患，曾接受闌尾切除，體檢時曾得知膽結石，但無明顯症狀，有喝酒習慣。5天前因聚餐3後，突發整個上腹部有壓痛，發燒（39°C）、血中白血球18,000 / mm，N/L= 83%/16%；黃疸值（total bilirubin 5.6 mg/dL），則應做那項進一步的處置？","options":["(A) 備血、輸血","(B) 安排緊急腹部剖腹手術","(C) 安排血管攝影檢查以及血管栓塞處置","(D) 安排腹部超音波"],"answer":3,"image":""},{"id":"md5-107-1-53","subject":"md5","topic":"消化器外科","meta":"107年第1次第53題","year":107,"session":1,"number":53,"question":"承上題，影像學顯示有膽囊結石，後腹腔有一1.5公分胰臟囊腫，則下列何者為最可能之診斷？","options":["(A) 急性闌尾炎（acute appendicitis）","(B) 膽源性胰臟炎（biliary pancreatitis）","(C) 急性肝炎（acute hepatitis）","(D) 腸阻塞（intestinal obstruction）"],"answer":1,"image":""},{"id":"md5-107-1-54","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"107年第1次第54題","year":107,"session":1,"number":54,"question":"一位60歲女性因解血便致心跳加速且血壓下降，經檢查發現出血的位置在升結腸如圖所示，則最可能的診斷為何？","options":["(A) 大腸癌出血","(B) 大腸憩室出血","(C) 潰瘍性腸炎（ulcerative colitis）","(D) 克隆氏症（Crohn's disease）"],"answer":1,"image":"md5-107-1-54.jpeg"},{"id":"md5-107-1-55","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"107年第1次第55題","year":107,"session":1,"number":55,"question":"承上題，上述疾病的治療何者較不恰當？","options":["(A) 抗生素治療","(B) 大腸鏡下進行止血","(C) 血管攝影並栓塞","(D) 保守治療無效的情形下，安排手術治療"],"answer":0,"image":""},{"id":"md5-107-1-56","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"107年第1次第56題","year":107,"session":1,"number":56,"question":"一位45歲健康成年男性，行走時遭汽車撞擊，左膝腫痛變形，送至急診後左膝X光檢查結果如下圖。關於此種骨折之敘述，下列何者錯誤？","options":["(A) 若骨折型態較複雜，術前計畫時應作進一步的影像檢查。目前公認磁振造影（MRI）檢查比電腦斷層掃描（CT）檢查更能精準研判骨折型態","(B) 可能合併副韌帶（collateral ligaments）、半月板（menisci）或十字韌帶（cruciate ligaments）的傷害","(C) 可能造成急性肌腔室症候群（acute compartment syndrome），需密切觀察肌腔室壓力（compartment pressure）及周邊循環情形是否良好","(D) 創傷後關節炎（post-traumatic arthritis）是手術後的晚期併發症（late complications）之一，可能導因於手術後關節面不平整（joint incongruity）"],"answer":0,"image":"md5-107-1-56.jpeg"},{"id":"md5-107-1-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"107年第1次第57題","year":107,"session":1,"number":57,"question":"一位79歲女性兩星期前不慎滑倒，造成下背痛，無法起立。現在背痛已漸改善，且可用四腳拐杖輔助走路。X光檢查顯示第二腰椎壓迫性骨折（compression fracture），椎體高度喪失約20%，腰椎前凸（lordosis）仍保持，沒有椎莖破壞（pedicle destruction）。下列何者是病患現在最適當的治療？","options":["(A) 背架保護加止痛藥物保守治療","(B) 經皮椎體成型手術（percutaneous vertebroplasty）治療","(C) 第一腰椎至第三腰椎後位骨釘固定骨融合手術治療","(D) 椎板切除（laminectomy）神經減壓，加第一腰椎至第三腰椎骨釘固定治療"],"answer":0,"image":""},{"id":"md5-107-1-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第1次第58題","year":107,"session":1,"number":58,"question":"有關髖關節生長性發育不良（developmental dysplasia of the hip）之敘述，下列何者錯誤？","options":["(A) 超音波檢查雖然提供更正確的診斷，但身體檢查仍是最主要的診斷方法","(B) 利用Barlow test可檢查出可被脫位的髖關節","(C) 斜頸是危險因子之一，對有斜頸的新生兒應進行篩檢","(D) Ortolani test以內展（adduction）動作來檢查出髖關節可被脫臼出去"],"answer":3,"image":""},{"id":"md5-107-1-59","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第1次第59題","year":107,"session":1,"number":59,"question":"有關良性骨病灶影像學上之發現的敘述，下列何者正確？","options":["(A) 侵犯到脊椎椎體之嗜伊紅球性肉芽腫（eosinophilic granuloma）的X光片中，常可見到椎體扁平（vertebra plana）的變形","(B) 骨樣骨瘤（osteoid osteoma）在電腦斷層檢查的中心病灶，大於2公分者居多","(C) 纖維性發育不良（fibrous dysplasia）常發生在肱骨（humerus）近端，X光有類似牧羊人拐杖（shepherd’s crook）的變形","(D) 單純性骨囊腫（simple bone cyst）的磁振造影（MRI）檢查，幾乎都可見到流體液平面（fluid-fluid level）的影像"],"answer":0,"image":""},{"id":"md5-107-1-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第1次第60題","year":107,"session":1,"number":60,"question":"有一位選手接受馬拉松長距離訓練兩星期，發生右小腿疼痛，下列敘述何者錯誤？","options":["(A) X光可能沒有異常發現","(B) 骨骼同位素掃描（bone scan）可能有異常發現","(C) 骨骼同位素掃描比磁振造影（MRI）的特異性（specificity）低","(D) 骨骼同位素掃描常用來研判預後及骨折癒合"],"answer":3,"image":""},{"id":"md5-107-1-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第1次第61題","year":107,"session":1,"number":61,"question":"一位媽媽在門診抱怨騎機車等紅燈時，會因拇指、食指、中指麻木而必須甩手，晚上睡覺時也會麻到醒來施予按摩，下列敘述何者正確？","options":["(A) 嚴重時會造成拇對掌肌（opponens pollicis）肌肉萎縮","(B) 掌側屈腕（volar flexion of the wrist）往往會改善症狀","(C) 頸椎椎間盤突出是主因","(D) 一定要及早手術治療"],"answer":0,"image":""},{"id":"md5-107-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第1次第62題","year":107,"session":1,"number":62,"question":"有關兒童背痛症之敘述，下列何者錯誤？","options":["(A) 病毒感染是經常伴隨發生的因素之一","(B) 在學齡前的兒童極為常見","(C) 當合併出現皮膚病變，如痣、異常長毛或色素沈澱時，須考慮可能有椎管閉合不全症（spinal dysraphism）","(D) 當C反應性蛋白（C-reactive protein）異常時，須考慮細菌感染、類風濕疾病與腫瘤等"],"answer":1,"image":""},{"id":"md5-107-1-63","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第1次第63題","year":107,"session":1,"number":63,"question":"有關佝僂病（rickets）及骨軟化病（osteomalacia）的敘述，下列何者錯誤？","options":["(A) 皆是生長板（growth plate）中增生區（proliferative zone）之骨礦物化（bone mineralization）失敗所導致","(B) 血清中副甲狀腺素（parathyroid hormone）及鹼性磷酸酶（alkaline phosphatase）都會升高","(C) 負荷重量的長骨之X光片影像中，皆可常見Looser氏轉型區（Looser's transformation zone）的變化","(D) 確切的診斷依據皆是骨活體組織切片"],"answer":[0,1],"image":"","answer_note":"更正:第63題答Ａ、Ｂ給分"},{"id":"md5-107-1-64","subject":"md5","topic":"泌尿-腫瘤","meta":"107年第1次第64題","year":107,"session":1,"number":64,"question":"治療腎臟結石時，下列何者是選擇使用體外震波碎石、輸尿管鏡或經皮穿腎取石手術的最重要因素？","options":["(A) 體型","(B) 結石成分","(C) 結石大小及數目","(D) 結石位置"],"answer":2,"image":""},{"id":"md5-107-1-65","subject":"md5","topic":"泌尿-腫瘤","meta":"107年第1次第65題","year":107,"session":1,"number":65,"question":"有關前列腺癌之敘述，下列何者錯誤？","options":["(A) 每年PSA升高超過0.75 ng/mL者，潛伏癌症之機率增高","(B) 經直腸超音波檢查比指診更能精確定出局部腫瘤期別","(C) 格里森分數（Gleason score）高於7分者較易發生癌症進展","(D) 腫瘤侵犯至貯精囊時屬T3a期"],"answer":[1,3],"image":"","answer_note":"更正:第65題答Ｂ、Ｄ給分。"},{"id":"md5-107-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"107年第1次第66題","year":107,"session":1,"number":66,"question":"關於testicular tumor之敘述，下列何者錯誤？","options":["(A) 以germ cell tumor為主，約占90～95%的primary testicular tumor","(B) 隱睪症患側常見之睪丸癌為精原細胞癌（seminoma）","(C) 治療前先做切片確定診斷","(D) 多數睪丸腫瘤經淋巴轉移，且匯集至腎門附近的淋巴結"],"answer":2,"image":""},{"id":"md5-107-1-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"107年第1次第67題","year":107,"session":1,"number":67,"question":"大的腎臟癌施行姑息性血管栓塞所發生的症狀包括腰痛、發燒及白血球增加一般會持續幾天？","options":["(A) 1天","(B) 3天","(C) 7天","(D) 10天"],"answer":1,"image":""},{"id":"md5-107-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"107年第1次第68題","year":107,"session":1,"number":68,"question":"下列何者不會引起膀胱逼尿肌膨脹不良（poor detrusor distensibility）？","options":["(A) 前列腺良性肥大接受經尿道前列腺切除手術","(B) 放射治療造成detrusor fibrosis而失去膨脹能力","(C) 間質性膀胱炎（interstitial cystitis）","(D) 直腸癌接受low anterior resection手術治療"],"answer":0,"image":""},{"id":"md5-107-1-69","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"107年第1次第69題","year":107,"session":1,"number":69,"question":"排尿膀胱尿道造影檢查（voiding cystourethrography）發現病人有一側顯影劑由膀胱逆流至輸尿管和腎盂，並且有輕微的腎盂擴張，這種膀胱輸尿管尿液逆流為第幾度？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"image":""},{"id":"md5-107-1-70","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"107年第1次第70題","year":107,"session":1,"number":70,"question":"勃起功能障礙（erectile dysfunction）最常見的原因是？","options":["(A) 精神因素（psychogenic factor）","(B) 荷爾蒙因素（hormonal factor）","(C) 動脈因素（arterial factor）","(D) 混合因素（mixed factors）"],"answer":3,"image":""},{"id":"md5-107-1-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"107年第1次第71題","year":107,"session":1,"number":71,"question":"30歲林先生，結婚已一年不孕。在不孕症門診發現精液量很少（< 1 cc），下列何者最不可能為其病因？","options":["(A) 射精管阻塞","(B) 早洩","(C) 逆行性射精","(D) 睪固酮低下症"],"answer":1,"image":""},{"id":"md5-107-1-72","subject":"md5","topic":"泌尿-腫瘤","meta":"107年第1次第72題","year":107,"session":1,"number":72,"question":"病人主訴右側腰部悶痛，血液中白血球數目正常，超音波檢查發現右側腎臟腫塊，電腦斷層檢查如附圖，下列何種診斷最正確？","options":["(A) renal cell carcinoma","(B) urothelial cell carcinoma","(C) renal angiomyolipoma","(D) xanthogranulomatous pyelonephritis"],"answer":2,"image":"md5-107-1-72.jpeg"},{"id":"md5-107-1-73","subject":"md5","topic":"胸腔外科","meta":"107年第1次第73題","year":107,"session":1,"number":73,"question":"胸降主動脈損傷，胸部X-ray影像學徵象，下列何者較少見？","options":["(A) 主動脈邊界模糊（blurring of the aortic contour）","(B) 氣管偏向左邊（tracheal shift to the left）","(C) 血胸（hemothorax）","(D) 縱隔腔寬度增加（widening of the mediastinum）"],"answer":1,"image":""},{"id":"md5-107-1-74","subject":"md5","topic":"消化器外科","meta":"107年第1次第74題","year":107,"session":1,"number":74,"question":"55歲男性病人在肝臟超音波追蹤時發現陰影，安排三相式（pre-contrast, arterial phase, venous phase）電腦斷層掃描如圖示。根據Couinaud肝臟分葉法，該病灶位置為何？","options":["(A) S5","(B) S6","(C) S7","(D) S8"],"answer":0,"image":"md5-107-1-74.jpeg"},{"id":"md5-107-1-75","subject":"md5","topic":"胸腔外科","meta":"107年第1次第75題","year":107,"session":1,"number":75,"question":"下列有關外傷性窒息（traumatic asphyxia）的敘述，何者錯誤？","options":["(A) 因胸部（chest）受到擠壓所致，其典型症狀有結膜下出血、頭、頸部發紺","(B) 常發生在胸部遭受重物壓迫的病人","(C) 其相關傷害，無需積極治療","(D) 肇因於上腔靜脈壓力突然增加"],"answer":2,"image":""},{"id":"md5-107-1-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第1次第76題","year":107,"session":1,"number":76,"question":"一位28歲年輕人，胸部遭受槍擊造成血胸（hemothorax）合併休克，胸管引流出800 ml血液後，血壓恢復為116/78 mmHg，心跳96下/分鐘，幾分鐘後血壓下降為86/68 mmHg，心跳136下/分鐘，下列處置何者優先？","options":["(A) 立即氣管插管","(B) 緊急開胸手術","(C) 立即輸血","(D) 重新評估病人"],"answer":3,"image":""},{"id":"md5-107-1-77","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"107年第1次第77題","year":107,"session":1,"number":77,"question":"外傷患者發現左小腿有骨折且持續腫脹，下列臨床判斷何者錯誤？","options":["(A) 有可能發生腔室症候群（compartment syndrome）","(B) 腔室症候群的典型症狀包括疼痛、腫脹、麻痺及感覺異常等","(C) 疼痛腫脹是最早出現的症狀","(D) 肢體遠端摸到脈搏時，表示腔室症候群還沒產生"],"answer":3,"image":""},{"id":"md5-107-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"107年第1次第78題","year":107,"session":1,"number":78,"question":"醫療資源之分配，有一種評估方式是依照「調整品質後存活人年」（Quality Adjusted Life Years，簡寫QALYs）來計算。如果將一個人完全健康之存活1年定義為1QALY，則有疾病之存活1年將少於1QALY。若強調資源使用之效率，則使用同樣的醫療成本，能產生最大的QALY增加量的醫療行為，則是最有效率的醫療行為。然而，下列那些敘述是採用此種資源分配方式可能產生之倫理問題？①老年人因為存活年數較短，比較分配不到資源 ②殘障者之生活品質較不佳，可能比較分配不到資源 ③QALY的概念可以充分實現「拯救他人的義務」（duty to rescue）④注意QALY總產量，比較不注意QALY會累積在那些人身上","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":3,"image":""},{"id":"md5-107-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"107年第1次第79題","year":107,"session":1,"number":79,"question":"白先生是64歲的成功商人，過去樂觀開朗，社交與體能十分活躍，他太太約一年前因罹癌過世，他從此鬱鬱寡歡，與唯一的兒子媳婦同住。最近兩個月來他體重減輕，更發生血尿而前來求診。你是他的泌尿科主治醫師，因此替他安排膀胱鏡與切片門診手術，1週後的病理報告證明為膀胱癌。他與兒子一同走進診間，在支開白先生後，白先生的兒子知道病情後說：「醫師拜託不要向我爸爸宣告他得了癌症，他受不了這個打擊的。請你告訴他是膀胱發炎，多給他點希望吧！」儘管你向兒子解釋告知病情的必要，他仍堅持；你該如何處理？","options":["(A) 依照兒子的要求隱瞞白先生","(B) 如果病人直接向你詢問，表示希望知道結果，應把病情告知他","(C) 病患自己發現病情惡化時告知","(D) 交付倫理委員會決定處理方式"],"answer":1,"image":""},{"id":"md5-107-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"107年第1次第80題","year":107,"session":1,"number":80,"question":"陶先生是一位45歲的雜貨店老闆，5年前因為肝硬化接受肝臟移植，術後因為腹內膿瘍反覆的敗血性休克，在5個月前的一次休克後，陶先生因為敗血性血栓造成大腦多處栓塞性中風變成植物人。這次又因為發燒，敗血性休克，從護理之家送到急診，你是照顧他的一般外科醫師，家屬希望你盡一切努力救他，需要急救時就急救，必要時送入加護病房治療；你該如何處理最適當？","options":["(A) 醫療資源有限，應避免使用在植物人身上，可請家屬帶他回家","(B) 當醫師判定為無效醫療時，應告知家屬你的專業決定，嘗試與家屬達成治療的共識","(C) 一律遵照家屬意見，收入加護病房，給予後線抗生素及升壓藥治療","(D) 當醫師判定為無效醫療時，應告知家屬你的專業決定，不需要與家屬討論"],"answer":1,"image":""},{"id":"md5-107-2-1","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"aspiration pneumonia對於年長病人而言，是常見的術後合併症；下列對於aspiration pneumonia的敘述，何者錯誤？","options":["(A) 術後aspiration pneumonia發生機率，隨著年齡增加而增加，80歲以上病患的發生率是18至29歲病患的9至10倍","(B) 放nasogastric tube (NG tube)是胃腸道手術前常做的步驟，不會增加aspiration pneumonia的發生機率","(C) 維持年長病患30度至45度upright positioning，可減少aspiration pneumonia的發生機率","(D) 管路進食（tube feeding）前，先評估胃腸道功能或監測gastric residual volume，亦可減少aspiration pneumonia的發生機率"],"answer":1,"image":""},{"id":"md5-107-2-2","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"有關腎臟移植後發生急性排斥的機轉，下列敘述何者錯誤？","options":["(A) 當供體抗原呈現細胞（antigen-presenting cell）上的抗原與受體T細胞上的T細胞接受器結合後，經由細胞內訊息傳遞，活化T細胞核內的轉錄因子，使得受體T細胞活化並產生第二介白素（interleukin-2），此為第一信號（signal 1）","(B) 當供體抗原呈現細胞（antigen-presenting cell）上的CD40與受體T細胞上的CD154接受器結合後會促進T細胞接受器共同刺激因子CD80及CD86與受體T細胞上的CD25接受器結合，然後經由細胞內訊息傳遞，活化T細胞核內的轉錄因子，使得受體T細胞活化並再產生CD154及第二介白素接受器α鏈於細胞膜上，此為第二信號（signal 2）","(C) 第二介白素會與受體T細胞上的第二介白素接受器結合後，可經由活化哺乳動物雷帕黴素靶（mammalian target of rapamycin）途徑，使得受體T細胞進行細胞分裂，此為第三信號（signal 3）","(D) 除了受體T細胞活化後會造成移植腎臟發生急性排斥外，受體B細胞亦會經由與供體人類白血球抗原的作用而活化，產生抗體引起急性排斥現象"],"answer":1,"image":""},{"id":"md5-107-2-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"有關乳酸林格氏液（lactated Ringer's solution）組成成分，下列何者正確？","options":["(A) 鈉離子130 mEq/L","(B) 鉀離子3 mEq/L","(C) 鈣離子4 mEq/L","(D) 乳酸24 mEq/L"],"answer":0,"image":""},{"id":"md5-107-2-4","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"有關傷口感染之描述，下列何者錯誤？","options":["(A) 傷口感染的病因包括細菌因素，局部傷口因素，病人因素","(B) 清潔傷口術後產生感染的機率為百分之三以下","(C) 預防性抗生素乃使用於清潔傷口之手術","(D) 正常人發生外傷時，每公克組織上的細菌數目大於105個才會造成感染"],"answer":2,"image":""},{"id":"md5-107-2-5","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"一位病人因為單純性闌尾炎（simple appendicitis）接受闌尾切除術，術中並無腸內容物外漏，屬於下列何種手術傷口分類？","options":["(A) clean","(B) clean-contaminated","(C) contaminated","(D) dirty and infected"],"answer":1,"image":""},{"id":"md5-107-2-6","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"成人急性大量失血2000毫升（ml）以上時，下列何者不是臨床常見之表徵？","options":["(A) 意識焦慮（anxious）及錯亂（confused）","(B) Pulse pressure上升","(C) Blood pressure下降","(D) 尿量減少"],"answer":1,"image":""},{"id":"md5-107-2-7","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"有關腹部腔室症候群（abdominal compartment syndrome）之敘述，下列何者錯誤？","options":["(A) 為腹壓上升導致多發器官機能受影響的狀態，一般腹腔手術打開時能緩解","(B) 膀胱內壓力在35 mmHg以上時，需要積極減壓，否則會有機能受損的可能","(C) 太晚減壓，死亡率可能高達七成","(D) 腹腔壓力的表現可由下腔靜脈壓力來表示最為準確"],"answer":[0,3],"image":"","answer_note":"更正:第7題答Ａ、Ｄ給分"},{"id":"md5-107-2-8","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"相較於靜脈營養，腸道營養對手術病人營養支持之好處，下列何者錯誤？","options":["(A) 吃進去的多醣（polysaccharides）在大腸會被細菌發酵（bacterial fermentation），以維持腸道正常菌落","(B) 嚴重血流動力學不穩定（marked hemodynamic instability）的病人適合給與腸道營養","(C) 有較好的腸胃道免疫功能（gastrointestinal immunity）","(D) 可以維持腸胃屏障功能（gastrointestinal barrier function）"],"answer":1,"image":""},{"id":"md5-107-2-9","subject":"md5","topic":"神經外科","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"下列何者最不可能出現在毛毛樣血管疾病（moyamoya disease）？","options":["(A) 雙側顱內內頸動脈狹窄","(B) 腦部出現煙霧狀血管","(C) 顱內血管母細胞瘤（hemangioblastoma）","(D) 顱內動脈瘤"],"answer":2,"image":""},{"id":"md5-107-2-10","subject":"md5","topic":"神經外科","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"45歲男性，於首次癲癇發作後被送到急診。核磁共振檢查發現右側額葉有一直徑約4公分，T1 hypo-intense及T2 flair hyper-intense，無明顯對比劑顯影之腫瘤。安排手術切除後，病理切片腫瘤細胞呈現”fried egg pattern”，進一步分析結果發現此腫瘤有1p/19q co-deletion，此腫瘤之最可能的診斷為：","options":["(A) 腦膜瘤（meningioma）","(B) 髓母細胞瘤（medulloblastoma）","(C) 畸胎瘤（teratoma）","(D) 寡樹突神經膠細胞瘤（oligodendroglioma）"],"answer":3,"image":""},{"id":"md5-107-2-11","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"有關頸椎退化性疾病之手術敘述，下列何者錯誤？","options":["(A) 頸椎脊髓病變（cervical myelopathy）產生症狀，即需手術治療","(B) 急性神經根壓迫，可先保守治療","(C) 老年人接受後側椎弓切除術，日後很容易產生脊柱後凸變形","(D) 前頸椎手術可能傷到recurrent laryngeal nerve"],"answer":2,"image":""},{"id":"md5-107-2-12","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"負壓輔助傷口治療（negative pressure-assisted wound therapy, NPWT）是傷口治療方法之一，下列敘述何者錯誤？","options":["(A) NPWT可以改善傷口微環境（microenvironment），可促進傷口癒合","(B) NPWT利用機器反覆壓縮放鬆（compression and relaxation）的原理，刺激傷口組織，可增加生長因子的釋放","(C) NPWT可適用於多種開放性傷口","(D) NPWT治療，不會改變傷口的面積"],"answer":3,"image":""},{"id":"md5-107-2-13","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"根據Curreri formula，一個50公斤的病人，燒傷面積達70﹪體表面積，一天所需的卡洛里（calorie）約多少大卡（Kcal）？","options":["(A) 3,050","(B) 3,650","(C) 4,050","(D) 4,550"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第13題一律給分 (原公告答案 C)"},{"id":"md5-107-2-14","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"關於電擊傷（electrical burns），下列敘述何者正確？","options":["(A) 電流在進入身體後，會走在身體組織中電阻最低的部分，通常是皮膚","(B) 神經是一個電阻相對高的器官，通常較少受到影響","(C) 肌肉受傷後，會釋放出肌蛋白（myoglobulin），會因此造成急性腎損傷（acute kidney injury）","(D) 高壓電電傷，因電壓大，因此較少穿透到深部組織，較少造成深部組織傷害，與家庭用電器產生之電傷相比，較容易誘發心律不整"],"answer":2,"image":""},{"id":"md5-107-2-15","subject":"md5","topic":"整形重建外科","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"植皮依據取皮的厚度有分為全層皮膚移植（full-thickness skin graft）及部分層皮膚移植（split-thickness skin graft），下列何者屬於全層皮膚移植的特性？","options":["(A) 較少的初級收縮（primary contraction）","(B) 較容易存活（graft survival）","(C) 較多的後期收縮（secondary contraction）","(D) 較好的美觀結果"],"answer":3,"image":""},{"id":"md5-107-2-16","subject":"md5","topic":"整形重建外科","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"一位58歲長期在太陽下工作的工人鼻尖出現了一個不會疼痛的硬塊，身體檢查為一個8mm在皮膚表層不會移動的突起腫塊，表面是發亮蠟狀，並可看到表淺的末梢血管擴張現象，而且腫塊突起處有一小潰瘍，經切片證實為皮膚癌，最可能為下列何者？","options":["(A) 基底細胞癌（basal cell carcinoma）","(B) ੬狀細胞癌（squamous cell carcinoma）","(C) ࢦ性黑色素細胞瘤（malignant melanoma）","(D) 默克細胞癌（Merkel cell carcinoma）"],"answer":0,"image":""},{"id":"md5-107-2-17","subject":"md5","topic":"整形重建外科","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"有關顏面外傷與骨折（facial trauma & fracture）的處置，下列敘述何者錯誤？","options":["(A) 前額骨骨折（forehead fracture)要考慮前額竇及顱底是否傷害","(B) 如果有嚴重鼻眼篩（nasal-orbitoethmoid）或顱底骨折應給予鼻氣管插管（nasotracheal intubation）維持呼吸道通暢","(C) 上下頷顎骨骨折病人並不一定要做氣管切開術（tracheostomy），用氣管內管（endotracheal tube）也可維持呼吸道通暢","(D) 下頜骨骨折（mandibular fracture）的處理，強調穩定的內固定及咬合的穩定"],"answer":1,"image":""},{"id":"md5-107-2-18","subject":"md5","topic":"心臟血管外科","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"有關嚴重二尖瓣膜逆流（severe mitral regurgitation）之敘述，下列何者錯誤？","options":["(A) 在急性嚴重二尖瓣膜逆流併心臟衰竭時，應考慮提早接受手術治療","(B) 在有症狀之慢性原發性嚴重二尖瓣膜逆流（primary mitral regurgitation）之病患，藥物治療只能改善症狀，無法改變長期預後","(C) 慢性原發性嚴重二尖瓣膜逆流（primary mitral regurgitation）之外科治療，以長期預後而言，瓣膜置換優於瓣膜修補","(D) 對於功能性嚴重二尖瓣膜逆流（functional mitral regurgitation），因屬於左心室功能問題，即使接受外科瓣膜手術後，其預後仍然比原發性二尖瓣膜逆流手術後結果差"],"answer":2,"image":""},{"id":"md5-107-2-19","subject":"md5","topic":"心臟血管外科","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"有關二尖瓣嚴重狹窄（severe mitral stenosis）之治療，下列何者錯誤？","options":["(A) 有無徵狀的嚴重二尖瓣狹窄（mitral stenosis）都應該接受介入性的手術治療","(B) 嚴重的二尖瓣狹窄大都以風濕性心臟病（rheumatic heart disease）為主","(C) 利用體外循環之下行二尖瓣膜連合處切開術（open mitral commissurotomy, OMC）是手術選項之一","(D) 當無法實行二尖瓣膜連合處切開術時，二尖瓣膜置換手術（mitral valve replacement）也是外科治療選項之一"],"answer":0,"image":""},{"id":"md5-107-2-20","subject":"md5","topic":"心臟血管外科","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"50歲男性病患主訴，有高血壓病史，未接受規則性之治療，3星期前有突發性撕裂性背痛至今仍舊無法緩解。電腦斷層顯示如下圖，下列診斷及治療何者錯誤？","options":["(A) 其主動脈剝離由降主動脈至腹主動脈，但入口位於降主動脈近端處，診斷為史丹佛B型主動脈剝離（Stanford type B）","(B) 需考慮手術治療","(C) 症狀發生超過14天，屬於慢性主動脈剝離","(D) 雖腔內血管修補術式（TEVAR）發展迅速，但手術仍以傳統開胸置換手術為主"],"answer":3,"image":"md5-107-2-20.jpeg"},{"id":"md5-107-2-21","subject":"md5","topic":"心臟血管外科","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"心臟手術時使用的人工心肺機包含下列那些裝置？①熱交換器（heat exchanger） ②主動脈鉗夾（aortic clamp） ③幫浦（pump） ④氧合器（oxygenator）","options":["(A) ①②③","(B) ②③④","(C) ①②④","(D) ①③④"],"answer":3,"image":""},{"id":"md5-107-2-22","subject":"md5","topic":"心臟血管外科","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"一位58歲男性因急性胸痛，伴隨冷汗來急診求助，當下安排之檢查，下列何者較不適當？","options":["(A) 胸部電腦斷層","(B) 抽血測心肌酵素","(C) 運動心電圖","(D) 心導管冠狀動脈攝影"],"answer":2,"image":""},{"id":"md5-107-2-23","subject":"md5","topic":"心臟血管外科","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"下列何種先天性心臟病，現今仍完全無法以心導管方法（如封堵器occluder或線圈coil）治療？","options":["(A) 肌肉型之心室中隔缺損（muscular type ventricular septal defect）","(B) 心房中隔缺損（atrial septal defect）","(C) 開放性動脈導管（patent ductus arteriosus）","(D) 完全型之心內膜墊異常（endocardial cushion defect, complete form）"],"answer":3,"image":""},{"id":"md5-107-2-24","subject":"md5","topic":"胸腔外科","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"關於縱膈腔腫瘤之臨床症狀及診斷，下列敘述何者錯誤？","options":["(A) 臨床症狀取決於腫瘤位置，大小及惡性程度","(B) 可能會有霍納氏症候群（Horner syndrome）發生","(C) 胸腺瘤可能有重症肌無力症狀","(D) 超過三分之二的病患會有症狀發現"],"answer":3,"image":""},{"id":"md5-107-2-25","subject":"md5","topic":"胸腔外科","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"關於乳糜胸之敘述，何者正確？","options":["(A) 最常發生在左側胸腔","(B) 最常因為腫瘤造成乳糜胸","(C) 不管乳糜胸引流量多寡，結紮胸管手術是治療乳糜胸唯一方式","(D) 假性乳糜胸通常由於類風濕肋膜炎或結核所致"],"answer":3,"image":""},{"id":"md5-107-2-26","subject":"md5","topic":"胸腔外科","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"關於Achalasia之敘述，下列何者錯誤？","options":["(A) 現在的理論是支配lower esophageal sphincter之神經受損所致","(B) 長時間最易引起esophageal adenocarcinoma","(C) 典型症狀為吞嚥困難、食物逆流及體重減輕","(D) 其外科治療主要為esophagomyotomy"],"answer":1,"image":""},{"id":"md5-107-2-27","subject":"md5","topic":"胸腔外科","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"下列對於單一肺結節（solitary pulmonary nodule, SPN）的敘述，何者錯誤？","options":["(A) 肺部內小於2公分的無症狀腫塊（an asymptomatic mass within the lung parenchyma that is less than 2cm）","(B) 小於50%是惡性（less than 50% are malignant）","(C) 單一肺結節若具有良性鈣化特徵，通常不需手術治療（patient with benign pattern of calcification doesn't need resection of SPN）","(D) 有些單一肺結節無法用楔狀切除（a wedge resection for SPN may not be always possible）"],"answer":0,"image":""},{"id":"md5-107-2-28","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"張先生胸部遭受撞擊，若突然併發有急性創傷後呼吸不足（pulmonary insufficiency）症狀，下列何者是最常見的原因？","options":["(A) 肺挫傷","(B) 氣胸","(C) 肋骨骨折","(D) 成人呼吸窘迫症（ARDS）"],"answer":1,"image":""},{"id":"md5-107-2-29","subject":"md5","topic":"消化器外科","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"張奶奶已經76歲了，B型肝炎帶原多年，這次被診所醫師發現肝臟有三顆腫瘤，合併有甲型胎兒蛋白（AFP）上升，懷疑是肝癌而住院。抽血報告如下。若考慮為患者進行手術，下列何項措施最不恰當？Hb Platelet PT aPTT張奶奶10.2 40 16.2 36.4正常值13.5-17 138-353 9.4-12.5 26-38單位g/dL 10^3/mL sec sec","options":["(A) 肝癌嚴重，應逕行開刀","(B) 血小板過低，須矯正之","(C) 肝臟手術易出血，要預先準備packed RBC","(D) PT異常，必須先矯正coagulopathy"],"answer":0,"image":"md5-107-2-29.jpeg"},{"id":"md5-107-2-30","subject":"md5","topic":"消化器外科","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"闌尾炎為常見之急性腹症，下列敘述何者不合宜？","options":["(A) 急性闌尾炎為最常見的腹部急症，常好發於老年人及兒童","(B) 麥氏點（McBurney's point)為右下腹髂前上棘（anterior superior iliac spine）與肚臍連線外三分之一處","(C) 對於沒有發生併發症的急性闌尾炎可以考慮非手術治療，但目前仍以闌尾切除為標準治療","(D) 約有1%的病患為闌尾惡性腫瘤，所以仍須作最後的病理檢查"],"answer":0,"image":""},{"id":"md5-107-2-31","subject":"md5","topic":"消化器外科","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"下列對於胰臟癌之敘述，何者並不適合？","options":["(A) 胰臟癌好發於胰臟體部，其次為頭和迴溝處（uncinate process）或胰尾；預後與診斷時的腫瘤分期最有關聯","(B) 多層次細切片的電腦斷層為最符合效益的診斷工具，可以幫忙診斷是否有轉移及能否手術","(C) 和其他壺腹周遭惡性腫瘤相比，胰臟癌的預後普遍較同期別的惡性腫瘤為差","(D) 診斷性腹腔鏡可以協助確定是否有腹膜轉移或惡性腹水，對於不確定是否可以切除的病患，建議進行"],"answer":0,"image":""},{"id":"md5-107-2-32","subject":"md5","topic":"消化器外科","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"下列何者不是胃繞道減重手術（Roux-en-Y gastric bypass）長期術後常見的合併症？","options":["(A) 邊緣性潰瘍（marginal ulcer）","(B) 鐵吸收不良（iron deficiency）","(C) 膽汁逆行性食道炎（bile reflux esophagitis）","(D) 腹腔內腸疝氣（internal hernia）"],"answer":2,"image":""},{"id":"md5-107-2-33","subject":"md5","topic":"消化器外科","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"有關切除大量小腸後的短腸症（short bowel syndrome），下列敘述何者錯誤？","options":["(A) 切除少於50%的小腸，人體通常多可承受，而不致出現吸收不良的短腸症","(B) 迴盲瓣若有保存，則較不易出現短腸症","(C) 切除空腸（jejunum）比切除迴腸（ileum）較易出現短腸症","(D) 小腸移植是嚴重短腸症的治療選項之一"],"answer":2,"image":""},{"id":"md5-107-2-34","subject":"md5","topic":"消化器外科","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"膽鹽在那一段腸道會被再吸收，進入腸肝循環（enterohepatic circulation)？","options":["(A) 十二指腸（duodenum）","(B) 空腸（jejunum）","(C) 迴腸（ileum）","(D) 結腸（colon）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第34題答Ａ、Ｂ、Ｃ、Ｄ給分 (原公告答案 C)"},{"id":"md5-107-2-35","subject":"md5","topic":"消化器外科","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"胰十二指腸切除手術（Whipple operation）切除的部分包含下列何者？①胰頭（pancreatic head） ②脾臟（spleen） ③總膽管下端（distal common bile duct） ④十二指腸（duodenum） ⑤腹腔幹（celiac trunk）","options":["(A) ①②③","(B) ①③⑤","(C) ②④⑤","(D) ①③④"],"answer":3,"image":""},{"id":"md5-107-2-36","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"下列關於甲狀腺手術可能造成的nerve injury，何者錯誤？","options":["(A) 若傷及recurrent laryngeal nerve，會導致聲帶麻痺","(B) 若傷及external branch of superior laryngeal nerve，會導致發高音困難","(C) 手術不易傷及internal branch of superior laryngeal nerve","(D) 若傷及cervical sympathetic trunk，會導致Wermer's syndrome"],"answer":3,"image":""},{"id":"md5-107-2-37","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"一位女性體檢時，意外發現有高血鈣，進一步檢查證實為原發性副甲狀腺功能亢進（primary hyperparathyroidism），根據目前的治療指引，有些原發性副甲狀腺功能亢進患者即使無臨床症狀亦建議應接受手術，但下列何者除外？","options":["(A) 骨密度檢查T-score小於-2.5","(B) 肌酸酐廓清率（creatinine clearance）小於60 mL/min","(C) 血鈣超過正常值上限1.0 mg/dL以上","(D) 年齡大於60歲"],"answer":3,"image":""},{"id":"md5-107-2-38","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"一位50歲男性因急性心臟衰竭住院，入院時收縮壓為200 mmHg，檢查發現右腎上腺有一5公分腫瘤，臨床醫師懷疑為嗜鉻細胞瘤（pheochromocytoma），下列敘述何者正確？","options":["(A) 收集24小時尿液檢驗兒茶酚胺（catecholamines）和香草扁桃酸（vanillylmandelic acid）來診斷，有很好的特異度（specificity），但敏感度（sensitivity）並不高","(B) 須功能性影像檢查決定腫瘤範圍時，以碘-131碘代膽固醇（131I-iodocholesterol）NP-59掃描為佳","(C) 腎上腺手術前準備藥物，以長效型bisoprolol為首選","(D) 嗜鉻細胞瘤昔稱10%腫瘤，但如今已知約有三分之一的嗜鉻細胞瘤有遺傳性基因突變，例如有SDHB（succinate dehydrogenase B）突變者惡性機會較低"],"answer":0,"image":""},{"id":"md5-107-2-39","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"BRCA 1的基因變異與下列何種乳癌型態最相關？","options":["(A) 管腔A型（luminal A）","(B) 管腔B型（luminal B）","(C) 類基底型（basal-like）","(D) HER-2過度表現型（HER-2 type）"],"answer":2,"image":""},{"id":"md5-107-2-40","subject":"md5","topic":"內分泌與乳房外科","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"針對患有乳癌的病人，做病史及理學檢查的評估，以決定是否為高危險病患時，下列何項不必列入考慮？","options":["(A) 停經在55歲之後","(B) 未產婦（nulliparity）","(C) 曾有甲狀腺病史","(D) 初經小於12歲"],"answer":2,"image":""},{"id":"md5-107-2-41","subject":"md5","topic":"整形重建外科","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"關於身體組織皮瓣移植用來作為乳癌病患手術的重建，下列何者錯誤？","options":["(A) 闊背肌皮瓣（latissimus dorsi）因為解剖位置相近的關係最常被使用","(B) 闊背肌皮瓣可以合併義乳進行重建","(C) 現今手術的技術成熟，大部分的病患可以在手術切除腫瘤，立即進行重建手術","(D) 自體組織皮瓣因為供血的關係，可能有組織壞死（necrosis）的問題"],"answer":0,"image":""},{"id":"md5-107-2-42","subject":"md5","topic":"消化器外科","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"有關膽道囊腫，下列敘述何者錯誤？","options":["(A) 依Todani分類囊腫型態一共分為五大型","(B) 病人典型的三個症狀是腹痛、黃疸與右上腹摸到腫塊","(C) 手術與否端視病人是否有症狀，無症狀者不必手術","(D) 如果進行手術是做囊腫切除與Roux-en-Y肝管空腸吻合"],"answer":[2,3],"image":"","answer_note":"更正:第42題答Ｃ、Ｄ給分"},{"id":"md5-107-2-43","subject":"md5","topic":"小兒外科","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"一名個9個月大嬰兒因突發性右側陰囊腫大來急診，經臆斷可能是嵌閉性腹股溝疝氣、睪丸扭轉、睪丸或副睪發炎、或急性陰囊水腫。下列敘述何者錯誤？","options":["(A) 可做陰囊超音波檢查幫助鑑別診斷","(B) 如果是睪丸扭轉，應儘速在扭轉後6小時內手術，約有90%可成功恢復血流","(C) 如果是嵌閉性腹股溝疝氣，無論多久，應儘速在急診就徒手復位","(D) 急性陰囊水腫可以觀察，不用急著手術"],"answer":2,"image":""},{"id":"md5-107-2-44","subject":"md5","topic":"小兒外科","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"下圖為一個足月的新生女嬰，檢查發現其薦尾椎有一個巨大的腫瘤，下列敘述何者錯誤？","options":["(A) 最可能的診斷為薦尾椎畸胎瘤（sacrococcygeal teratoma）","(B) 不論在懷孕過程或是嬰兒出生之後，都要嚴密觀察嬰兒有無因為此巨大腫瘤產生的盜血現象（tumor- induced vascular steal syndrome）","(C) 需再進一步的安排影像學檢查，如CT或MRI等，以了解除了外部看到的範圍之外，向內延伸到骨盆腔的範圍有多大","(D) 手術的原則是要將腫瘤完全切除，過程中要避免傷害到肛門直腸及周邊的正常結構，並將尾骨保留"],"answer":3,"image":"md5-107-2-44.jpeg"},{"id":"md5-107-2-45","subject":"md5","topic":"小兒外科","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"一名5歲大的女童因為頸部中線腫塊，經檢查為甲狀舌骨囊腫（thyroglossal duct cyst）。有關其手術方式（Sistrunk procedure）之描述，下列何者最正確？","options":["(A) 切除囊腫及舌骨中段","(B) 切除囊腫、舌骨中段及相連至舌底部之管道","(C) 切除囊腫、甲狀腺及相連至舌底部之管道","(D) 切除囊腫、舌骨中段及甲狀腺"],"answer":1,"image":""},{"id":"md5-107-2-46","subject":"md5","topic":"小兒外科","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"關於先天性肺部呼吸道畸形（congenital pulmonary airway malformation）的治療，下列何者比較正確？","options":["(A) 新生兒胸部X光發現右上肺葉有大囊泡狀病灶，出生後即因呼吸衰竭插管治療，應緊急進行開胸手術","(B) 新生兒產前懷疑右下肺葉有實質狀病灶，出生後呼吸平穩，應立即接受肺部電腦斷層檢查","(C) 新生兒產前懷疑左上肺葉有小囊泡狀病灶，於出生後6個月大時接受電腦斷層確診，應於2歲之後再手術","(D) 3個月大男嬰因呼吸急促，經X光及電腦斷層檢查發現左下肺葉多囊泡狀病灶，應安排磁振造影（MRI）確定血管走向"],"answer":0,"image":""},{"id":"md5-107-2-47","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"一名3歲15公斤的男童從6層樓跌落送來急診，生命徵象為心跳160下／分、血壓70/30 mmHg、呼吸30下／ 分，適當的急救輸液給法為何？","options":["(A) 血漿替代液（Gelofusine）一次300毫升快速滴注，給與一次後若沒有反應即輸血","(B) 新鮮冷凍血漿（fresh frozen plasma）一次300毫升快速滴注，給與一次後若沒有反應即輸紅血球濃厚液（packed RBC）","(C) 林格氏液（Ringer's solution）一次150毫升快速滴注，給與兩次後若沒有反應即輸血","(D) 生理食鹽水（normal saline）一次300毫升快速滴注，給與兩次後若沒有反應即輸血"],"answer":3,"image":""},{"id":"md5-107-2-48","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"15歲男孩因排黏液血便求診，詢問其家族史發現他的父親、叔叔及姑姑皆有大腸息肉或癌症病史，內視鏡發現其大腸約有數百個大小息肉，下列相關敘述何者正確？①致病成因為mismatch repair基因遺傳性突變 ② 基因突變位於5q21 ③為顯性遺傳（autosomal dominance） ④此類病人大於50%之比率沒有家族史","options":["(A) 僅①③","(B) ①②③④","(C) 僅①②④","(D) 僅②③"],"answer":3,"image":""},{"id":"md5-107-2-49","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"有關大腸直腸癌的化學治療準則，下列敘述何者錯誤？","options":["(A) StageⅠ病人術後不需使用術後輔助性化療","(B) 5-fluorouracil-based（5- FU）regimen被建議可用於stageⅡ併有poor prognostic indicator的病人","(C) FOLFOX regimen可延長stageⅢ病患存活率","(D) Stage Ⅳ病人RAS mutation對於Anti-EGFR治療有好處"],"answer":3,"image":""},{"id":"md5-107-2-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"有關大腸憩室炎（diverticulitis disease）的敘述，下列何者錯誤？","options":["(A) 評估大腸憩室炎的嚴重程度，目前較建議的診斷工具是電腦斷層","(B) 急性大腸憩室炎臨床上可粗略分為非複雜性及複雜性；非複雜性（uncomplicated）可以採保守治療方式","(C) 可建議大腸憩室炎患者在症狀改善後的4～6週接受大腸鏡檢查，藉此確診大腸憩室及排除大腸惡性腫瘤或大腸發炎性疾病之可能性","(D) 一旦患者發生過大腸憩室炎，就必須建議患者接受常規部分大腸切除，以預防下次大腸憩室炎的發作"],"answer":3,"image":""},{"id":"md5-107-2-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"107年第2次第51題","year":107,"session":2,"number":51,"question":"下列關於微創手術施行大腸切除的敘述，何者錯誤？","options":["(A) 腹腔鏡輔助大腸切除手術相較於開腹手術，能減少術後疼痛","(B) 腹腔鏡輔助大腸切除手術產生腸繫膜內疝氣（mesenteric internal hernia）的比率約只有1%","(C) 腹腔鏡輔助大腸切除手術施行大腸切除後，一定要手術關閉腸繫膜缺損（mesenteric defect）","(D) 最常見腸繫膜內疝氣的位置在迴腸結（ileocolic junction）附近"],"answer":2,"image":""},{"id":"md5-107-2-52","subject":"md5","topic":"消化器外科","meta":"107年第2次第52題","year":107,"session":2,"number":52,"question":"下列何者不是腹腔鏡腹股溝疝氣修補手術（laparoscopic inguinal hernia repair）之優點？","options":["(A) 能在腹膜前腔（preperitoneal space）放置大片人工網膜","(B) 較容易以人工網膜覆蓋肌恥骨孔（myopectineal orifice）","(C) 相較於傳統修補手術，有明顯較低的復發率","(D) 適合治療雙側疝氣或復發性疝氣"],"answer":2,"image":""},{"id":"md5-107-2-53","subject":"md5","topic":"消化器外科","meta":"107年第2次第53題","year":107,"session":2,"number":53,"question":"相對於開腹手術，施行腹腔鏡闌尾切除手術（laparoscopic appendectomy）的優點不包括下列何者？","options":["(A) 減少住院天數","(B) 縮短手術時間","(C) 便於發現腹腔內其他可能疾病","(D) 較低傷口感染率"],"answer":1,"image":""},{"id":"md5-107-2-54","subject":"md5","topic":"神經外科","meta":"107年第2次第54題","year":107,"session":2,"number":54,"question":"一糖尿病中年婦女，突然頭部劇痛、左眼瞼下垂、複視、瞳孔放大，來急診求治，神智清楚，腦部電腦斷層如附圖，下列處置何者最恰當？","options":["(A) 住院，馬上安排腦部血管攝影","(B) 抽血密切注意血糖的變化","(C) 住院，檢驗是否有重症肌無力（myasthenia gravis）","(D) 安排腦部核磁共振，再決定是否要住院"],"answer":0,"image":"md5-107-2-54.jpeg"},{"id":"md5-107-2-55","subject":"md5","topic":"神經外科","meta":"107年第2次第55題","year":107,"session":2,"number":55,"question":"承上題，下列何者是最可能的診斷？","options":["(A) 重症肌無力","(B) 糖尿病神經病變","(C) 後交通動脈瘤破裂","(D) 前交通動脈瘤破裂"],"answer":2,"image":""},{"id":"md5-107-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第2次第56題","year":107,"session":2,"number":56,"question":"有關多發性骨髓瘤（multiple myeloma）的敘述，下列何者錯誤？","options":["(A) 病理組織下可發現惡性漿細胞（plasma cell）","(B) X光檢查在頭骨及骨盆可發現多發性鑿孔狀（punched out）骨破壞病灶","(C) 可用骨骼同位素掃描（bone scan）來診斷是否為單一或多發的骨骼侵犯","(D) 已有幹細胞移植成功治療病患的病例"],"answer":2,"image":""},{"id":"md5-107-2-57","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第2次第57題","year":107,"session":2,"number":57,"question":"一位40歲男性發生車禍，造成背部嚴重疼痛。胸腰椎側面X光（lateral view）發現第十一胸椎骨折，且在前後向X光（AP view）發現其雙側椎莖距離（interpedicular distance）變寬。依照X光檢查的發現，下列何者是第十一胸椎的最適當診斷？","options":["(A) 爆裂性骨折（burst fracture）","(B) 壓迫性骨折（compression fracture）","(C) 彎曲牽開性骨折（flexion-distraction fracture）","(D) 骨折脫位（fracture dislocation）"],"answer":[0,2],"image":"","answer_note":"更正:第57題答Ａ、Ｃ給分"},{"id":"md5-107-2-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第2次第58題","year":107,"session":2,"number":58,"question":"針對先天性脊柱側彎（congenital scoliosis）的成因分類中，下列何者彎曲度變大的速度最快、預後最差？","options":["(A) 全分離型半脊椎畸形（free hemivertebra）","(B) 嵌入型半脊椎畸形（incarcerated hemivertebra）","(C) 單側未分段脊節（unilateral unsegmented bar）","(D) 單側未分段脊節加上對側半脊椎畸形（unilateral and unsegmented bar with contralateral hemivertebra）"],"answer":3,"image":""},{"id":"md5-107-2-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"107年第2次第59題","year":107,"session":2,"number":59,"question":"下列那一條肌肉不屬於肩關節旋轉肌袖群（rotator cuff）？","options":["(A) 肩胛下肌（subscapularis）","(B) 岡下肌（infraspinatus）","(C) 岡上肌（supraspinatus）","(D) 大圓肌（teres major）"],"answer":3,"image":""},{"id":"md5-107-2-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第2次第60題","year":107,"session":2,"number":60,"question":"有關手部屈指肌腱斷裂之治療原則，下列何者錯誤？","options":["(A) 儘量於7天內進行肌腱縫合手術","(B) 六週後幾乎不可能進行直接縫合手術","(C) 若合併指動脈損傷，必須先做動脈吻合，然後再縫合肌腱","(D) 病人術後之復健對功能恢復非常重要"],"answer":2,"image":""},{"id":"md5-107-2-61","subject":"md5","topic":"骨科-關節重建","meta":"107年第2次第61題","year":107,"session":2,"number":61,"question":"下列何者不是骨質疏鬆症（osteoporosis）的危險因子？","options":["(A) 酒精過度飲用","(B) 吸菸","(C) 身體質量指數（body mass index）介於22～24公斤／平方公尺","(D) 父母親有髖部骨折史"],"answer":2,"image":""},{"id":"md5-107-2-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"107年第2次第62題","year":107,"session":2,"number":62,"question":"4歲小美由床上跌落，由於右肘的疼痛及腫脹，父母帶她來急診求診，並接受右肘部的X光檢查，由此X光影像，顯示此女童發生了何種骨折？","options":["(A) 肱骨髁上骨折（humeral supracondylar fracture）","(B) 肱骨外髁骨折（humeral lateral condyle fracture）","(C) 肱骨內上髁骨折（humeral medial epicondyle fracture）","(D) 尺骨鷹嘴突骨折（ulnar olecranon fracture）"],"answer":1,"image":"md5-107-2-62.jpeg"},{"id":"md5-107-2-63","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"107年第2次第63題","year":107,"session":2,"number":63,"question":"承上題，針對小美，下列何者是最佳治療？","options":["(A) 冰敷及肩帶固定治療（ice packing and shoulder sling immobilization）","(B) 徒手復位及支架固定治療（closed reduction and bracing）","(C) 徒手復位及石膏固定治療（closed reduction and casting）","(D) 手術復位及鋼針固定治療（open reduction and pinning）"],"answer":3,"image":""},{"id":"md5-107-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"107年第2次第64題","year":107,"session":2,"number":64,"question":"一位建築工地工人在工作中由二樓摔到地面，骨盆著地，被緊急送往醫院。病人血壓穩定，心跳快速，下腹疼痛併尿滯留，下列何者錯誤？","options":["(A) 病人之尿道開口有血時，必須要排除尿道受傷的可能","(B) 骨盆骨折常併有膜部尿道（membranous urethra）受傷","(C) 膜部尿道（membranous urethra）受傷後，肛門指診時，前列腺可能會移位","(D) 跨騎受傷（straddle injury）時，膜部尿道（membranous urethra）容易受傷"],"answer":3,"image":""},{"id":"md5-107-2-65","subject":"md5","topic":"泌尿-腫瘤","meta":"107年第2次第65題","year":107,"session":2,"number":65,"question":"有關家族性腎細胞癌（familial renal cell carcinoma）之敘述，下列何者錯誤？","options":["(A) von Hippel-Lindau disease和familial papillary renal cell carcinoma是較常見的臨床疾病","(B) 亮細胞型腎細胞癌（clear cell renal cell carcinoma）為常見的腎臟癌類型","(C) von Hippel-Lindau disease主要臨床表現有腎細胞癌，嗜鉻細胞瘤（pheochromocytoma），視網膜血管胚細胞瘤（retinal hemangioblastoma）等","(D) von Hippel-Lindau disease的病人好發於70歲，約有一半會發生腎細胞癌，有時會有雙側腎臟侵犯"],"answer":3,"image":""},{"id":"md5-107-2-66","subject":"md5","topic":"泌尿-腫瘤","meta":"107年第2次第66題","year":107,"session":2,"number":66,"question":"一位70歲男性膀胱癌病人，接受經尿道膀胱腫瘤切除術（TUR-BT），術中發現只有1個約1公分之腫瘤，病理切片是移形細胞癌（transitional cell carcinoma）grade I，期別是Ta，下列手術後處置何者正確？","options":["(A) 需要接受膀胱內卡介苗（BCG）灌注輔助治療","(B) 需要接受膀胱內化學藥物灌注輔助治療","(C) 不需要接受任何膀胱內化學藥物或BCG灌注輔助治療","(D) 需要接受放射輔助治療"],"answer":[1,2],"image":"","answer_note":"更正:第66題答Ｂ、Ｃ給分。"},{"id":"md5-107-2-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"107年第2次第67題","year":107,"session":2,"number":67,"question":"中風病人最常見的排尿障礙為何？","options":["(A) 膀胱無收縮力","(B) 膀胱頸功能阻塞","(C) 尿道外括約肌共濟失調","(D) 逼尿肌反射亢進"],"answer":3,"image":""},{"id":"md5-107-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"107年第2次第68題","year":107,"session":2,"number":68,"question":"對一位C5～C6完全性脊髓損傷導致逼尿肌尿道外括約肌共濟失調（detrusor sphincter dyssynergia，DSD）的病人，下列何種處置不合適？","options":["(A) 間歇性導尿以定時排空膀胱","(B) 口服抗膽鹼藥物以降低膀胱內壓","(C) 當測得漏尿壓力為20 cmH2O時，可以進行尿道外括約肌切開術（sphincterotomy）以保護腎臟","(D) 置放尿道支架（urethral stent）以方便排空膀胱"],"answer":2,"image":""},{"id":"md5-107-2-69","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"107年第2次第69題","year":107,"session":2,"number":69,"question":"有關磷酸二酯酶（phosphodiesterase）抑制劑，治療男性勃起功能障礙的機轉，下列何者正確？","options":["(A) Sildenafil（Viagra）主要作用是抑制磷酸二酯酶第6及11型","(B) 磷酸二酯酶第5型促使環磷酸腺苷（cAMP）代謝為5'環磷酸腺苷（5'AMP）","(C) 可直接引發勃起機制","(D) 不能與硝酸鹽藥物（nitrates）同時服用"],"answer":3,"image":""},{"id":"md5-107-2-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"107年第2次第70題","year":107,"session":2,"number":70,"question":"有關小孩包皮的敘述，下列何者正確？","options":["(A) 為了預防癌症，減少尿路感染，最好每位小孩都施行包皮環切術","(B) 在3歲時，大約90%未接受包皮手術的小孩都可以有自然包皮退下的機會","(C) 包皮手術簡單安全，因此不會造成任何併發症","(D) 使用類固醇局部塗抹，無法有效使包皮環變鬆而自然退下"],"answer":1,"image":""},{"id":"md5-107-2-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"107年第2次第71題","year":107,"session":2,"number":71,"question":"下列有關夜間陰莖膨脹測驗（nocturnal penile tumescence）結果的判讀，何者錯誤？","options":["(A) 健康男人一晚有三至五次勃起","(B) 勃起多發生在快速動眼期（rapid eye movement stage）","(C) 如果一個病人整晚都無勃起現象，即為器官性陽痿","(D) 勃起硬度達90%以上，持續一小時，即可診斷為器官性勃起功能正常"],"answer":2,"image":""},{"id":"md5-107-2-72","subject":"md5","topic":"消化器外科","meta":"107年第2次第72題","year":107,"session":2,"number":72,"question":"關於食道癌（esophageal carcinoma），下列何者錯誤？","options":["(A) 95%為腺癌（adenocarcinoma）","(B) 可分為腫塊型、潰瘍型及浸潤型","(C) 早期病灶呈小型斑塊或表淺不規則潰瘍","(D) Plummer-Vinson氏症候群病患，發生食道癌之機率較常人高"],"answer":0,"image":""},{"id":"md5-107-2-73","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"107年第2次第73題","year":107,"session":2,"number":73,"question":"32歲男性病人右下腹痛2天，來到急診，身體檢查有明顯局部壓痛，白血球在正常值內但略偏高，C-reactive protein上升。未注射顯影劑的電腦斷層如圖示，下列何項診斷最有可能？","options":["(A) epiploic appendagitis","(B) acute ileus","(C) ascending colon intusussception","(D) colon cancer with perforation"],"answer":0,"image":"md5-107-2-73.jpeg"},{"id":"md5-107-2-74","subject":"md5","topic":"神經外科","meta":"107年第2次第74題","year":107,"session":2,"number":74,"question":"34歲男性，車禍外傷，劇烈頭痛，意識混亂，CT影像圖A可見左臉頰腫脹，根據圖B箭頭所指的是：","options":["(A) contusion parenchymal hemorrhage","(B) traumatic subarachnoid hemorrhage（SAH）","(C) thin layer acute subdural hematoma（SDH）","(D) traumatic pneumoencephalus"],"answer":1,"image":"md5-107-2-74.jpeg"},{"id":"md5-107-2-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"107年第2次第75題","year":107,"session":2,"number":75,"question":"一位32歲女性，體重60 kg，騎機車不慎被貨車撞到造成腹內出血，送至急診時初步檢查為心縮壓（systolic blood pressure）正常，但脈搏壓（pulse pressure）明顯下降，且心跳112下/分，尿量20-30 ml/hour。此病人約流失多少血液？","options":["(A) 500 ml","(B) 700-1100 ml","(C) 1300-1700 ml","(D) 1900-2300 ml"],"answer":1,"image":""},{"id":"md5-107-2-76","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"107年第2次第76題","year":107,"session":2,"number":76,"question":"闌尾炎術後最常發生的併發症為何？","options":["(A) 肺炎","(B) 尿道感染","(C) 腸皮下瘻管","(D) 皮下和腹腔內的感染"],"answer":3,"image":""},{"id":"md5-107-2-77","subject":"md5","topic":"胸腔外科","meta":"107年第2次第77題","year":107,"session":2,"number":77,"question":"一位30歲的男性工人從6公尺高的鷹架墜落，身體檢查顯示收縮壓120 mmHg，右胸有明顯的連迦胸（flail chest），嚴重的呼吸窘迫（severe respiratory distress），右胸呼吸聲音稍微降低，叩診時則左右兩側類似。給予非再呼吸型面罩氧氣15 L/min後，其動脈氣體分析為pH：7.47，PaO2：65 mmHg，PaCO2：28 mmHg；下列何者最可能解釋他的異常動脈氣體分析之原因？","options":["(A) 疼痛","(B) 合併腹部創傷","(C) 心包膜積血","(D) 肺挫傷"],"answer":3,"image":""},{"id":"md5-107-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"107年第2次第78題","year":107,"session":2,"number":78,"question":"某醫院因為經營困難，要購買新的碎石機卻缺乏經費，於是鼓勵該院的泌尿科醫師投資買機器，醫院的說詞是醫師如果對業績有信心，投資機器也會賺錢，是醫院和醫師雙贏，這樣作法的潛在倫理問題是為何？","options":["(A) 會有利益衝突的問題","(B) 會有健保核刪的問題","(C) 會有執業執照的問題","(D) 會有輻射防護的問題"],"answer":0,"image":""},{"id":"md5-107-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"107年第2次第79題","year":107,"session":2,"number":79,"question":"有關醫療錯誤的告知，下列敘述何者錯誤？","options":["(A) 通常對醫師而言，坦承自己的醫療錯誤是一件困難的事","(B) 最好是率先告知醫療錯誤，不要等病人問了再說","(C) 對於病人或家屬強烈的情緒反應，要有心理準備","(D) 只要承認醫療錯誤，就等於有醫療過失"],"answer":3,"image":""},{"id":"md5-107-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"107年第2次第80題","year":107,"session":2,"number":80,"question":"一位84歲男性病患於幾年前罹患腦中風之後，長期臥床，常常有呼吸道感染或泌尿道感染。最近幾天病患開始出現發燒及腹瀉等現象。於急診經檢查確定為偽黏膜性大腸炎，醫師開始使用抗生素治療，但治療幾天後，症狀一直沒有具體改善。這時家屬詢問國外研究顯示，偽黏膜性大腸炎可以使用糞便移植治療，不知道醫師是否會考慮這種治療？經查詢相關文獻，發現該文獻的證據等級為Ib，證據等級相當高，但該療法並非台灣對於偽黏膜性大腸炎的常規治療。下列敘述，何者錯誤？","options":["(A) 依據實證醫學的理念，應該依據最新最好的證據來治療患者。本案中，既然該文獻的證據等級為Ib，屬於證據等級很高的文獻，可依照此治療方式來治療患者","(B) 雖然該文獻證據等級很高，但並沒有本土相關文獻的證據，該文獻的結果是否可以應用於國內的患者，容有疑慮，應該有更多本土證據支持後，才較為可信","(C) 不論證據等級高低，只要是新的治療方法，都必須經過衛生福利部核准後，進行人體試驗加以檢驗其治療效果以及治療相關安全性之後，才能應用於臨床患者","(D) 臨床上，醫師有遵從醫療常規來治療病患的義務。但並沒有遵從最新最好的證據等級之文獻來治療患者的義務"],"answer":0,"image":""},{"id":"md5-108-1-1","subject":"md5","topic":"消化器外科","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"⼀位63歲男性到⾨診主訴發現⽪膚泛黃已三週，尿液呈深褐⾊，最近有灰⽩⾊⼤便，無腹部疼痛及不適，食慾稍差。此病患住院後經影像學檢查，診斷為肝⾨處膽管癌（perihilar cholangiocarcinoma），腫瘤侷限於總肝管（common hepatic duct），在Bismuth-Corlette分類是屬於？","options":["(A) Type I","(B) Type II","(C) Type III","(D) Type IV"],"answer":0,"image":""},{"id":"md5-108-1-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"外傷評分系統（Injury Severity Score, ISS）是對外傷病患嚴重度評估常⽤的評分⽅式；下列對於外傷評分系統的敘述何者錯誤？","options":["(A) Abbreviated Injury Scale（AIS），於1971年提出，將受傷部位嚴重程度，分為從第1級（minimal severity）⾄第6級（presumably fatal）","(B) Injury Severity Score（ISS）是⼀種⽣理性評分系統（physiological scoring system）","(C) ISS分數區域為1分⾄75分，minor injury是指ISS<9分","(D) Glasgow Coma Scale（GCS）能評量外傷病患意識狀態，分數區域為3分⾄15分"],"answer":1,"image":""},{"id":"md5-108-1-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"對於beside surgical procedure的敘述，下列何者錯誤？","options":["(A) bedside surgical procedure可針對選擇性的critically ill patients進⾏⼿術處理，優點為降低運輸危急病患⾄ ⼿術室的危險，⼿術排程安排較有彈性，並可降低醫療費⽤","(B) bedside laparotomy通常應⽤於abdominal compartment syndrome，尤其當intra-abdominal pressure達到grade Ⅲ以上（21mmHg）時，可考慮做此項⼿術，以減低腹內壓","(C) percutaneous dilatational tracheostomy (PDT)對於critically ill patients with prolonged mechanical intubation，是簡單安全的⼿術，其peri-procedure mortality rate <0.1%","(D) percutaneous endoscopic gastrostomy (PEG)是針對high risk aspiration, inability to swallow, gastric outlet obstruction的critically ill patients,可提供安全快速的腸道管路路徑，灌食營養品"],"answer":3,"image":""},{"id":"md5-108-1-4","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"下列何者不是⼿術部位感染（surgical site infection）的危險因⼦（risk factors）？","options":["(A) 癌症病患接受⼿術","(B) 病患是否⻑期吸菸","(C) 術中是否輸⾎","(D) ⼿術時間⻑短"],"answer":0,"image":""},{"id":"md5-108-1-5","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"急診⾯對⼀位發燒病⼈，⾎壓75/40 mmHg，⼼跳105/min，⼼功能指標（cardiac index）下降，但中央靜脈壓⼒（central venous pressure）上升，最有可能診斷為何？","options":["(A) ⼼因性休克","(B) 敗⾎性休克","(C) 低⾎容積休克","(D) 神經性休克"],"answer":0,"image":""},{"id":"md5-108-1-6","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"器官移植是⼈類外科醫學⼀個重要突破，下列敘述何者錯誤？","options":["(A) 歷史上最早完成的器官移植為腎臟移植","(B) ⼼臟移植比肝臟移植更早完成","(C) ⼤多數的胰臟移植時常會合併腎臟移植⼀起進⾏","(D) 超急性排斥發⽣於移植後數⼗分鐘到數⼩時，是因為接受者體內抗體攻擊捐贈器官上的⾎型相關抗原或⼈ 類⽩⾎球抗原所致"],"answer":1,"image":""},{"id":"md5-108-1-7","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"⼤多數的癌症會經由淋巴管轉移（lymphatic metastasis），因此淋巴結廓清⼿術是惡性腫瘤⼿術的重要步驟。下列何種惡性腫瘤因很少有淋巴結轉移（< 5%），所以不需常規進⾏淋巴結廓清⼿術？","options":["(A) 胃癌","(B) 軟組織⾁瘤","(C) ⼤腸癌","(D) 胰臟癌"],"answer":1,"image":""},{"id":"md5-108-1-8","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"⻑期禁食後再重新給與營養時，為避免造成再餵食症後群（refeeding syndrome），於早期餵食時，應注意下列那些離⼦的補充？","options":["(A) 鉀、磷、鎂","(B) 鈉、磷、鈣","(C) 鉀、磷、鈣","(D) 鉀、鈉、鎂"],"answer":0,"image":""},{"id":"md5-108-1-9","subject":"md5","topic":"神經外科","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"下列何者較少出現在Neurofibromatosis type I的病⼈？","options":["(A) 家族顯性遺傳","(B) 雙側聽神經瘤","(C) ⽪膚咖啡⽜奶斑（Café-au-lait macules）","(D) 脊椎發育異常"],"answer":1,"image":""},{"id":"md5-108-1-10","subject":"md5","topic":"神經外科","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"傳統預防腦動脈瘤破裂出⾎後的腦⾎管痙攣（cerebral vasospasm）有所謂的”Triple-H” therapy，下列何者不包含於Triple-H？","options":["(A) hypervolemia","(B) hypertension","(C) hemodilution","(D) hyperventilation"],"answer":3,"image":""},{"id":"md5-108-1-11","subject":"md5","topic":"神經外科","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"有關腦下垂體泌乳素瘤（prolactinoma）的描述，下列何者正確？","options":["(A) 腫瘤通常直徑⼤於3公分","(B) ⾎中泌乳素（prolactin）濃度通常>150 ng/mL","(C) ⼿術是第⼀線主要治療⽅法","(D) 直徑<1公分通常⽤立體定位放射線⼿術（SRS）治療"],"answer":1,"image":""},{"id":"md5-108-1-12","subject":"md5","topic":"神經外科","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"有關腦部神經膠質瘤（glioma）之敘述，下列何者錯誤？","options":["(A) ⼩腦⽑細胞星形細胞瘤（pilocytic astrocytoma）主要治療⽅法為切片後放射線治療","(B) 寡樹突神經膠細胞瘤（oligodendroglioma）主要治療⽅式為儘量切除後化療","(C) 多形性神經膠質⺟細胞瘤（glioblastoma multiforme）為最常⾒之神經膠質瘤","(D) 多形性神經膠質⺟細胞瘤（glioblastoma multiforme）治療⽅法為盡可能完全切除加上放射線治療與temozolomide化療"],"answer":0,"image":""},{"id":"md5-108-1-13","subject":"md5","topic":"神經外科","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"有關三叉神經痛的敘述，下列何者錯誤？","options":["(A) 可能源⾃於多發性硬化症（multiple sclerosis）","(B) 可能因良性或惡性腫瘤造成","(C) 最常發⽣原因是superior cerebellar artery壓到三叉神經之腦幹端","(D) 開腦⼿術將⾎管與神經墊開是第⼀線治療⽅式"],"answer":3,"image":""},{"id":"md5-108-1-14","subject":"md5","topic":"整形重建外科","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"對於⼿部燒傷的治療，下列敘述何者錯誤？","options":["(A) 傷⼝儘早癒合，是避免攣縮最好的⽅式","(B) 需要使⽤副⽊（splint），以維持掌指關節伸展（MP joint extension）及指間關節伸展（IP joint extension）","(C) 維持⼿部功能姿勢（functional position），是為了避免伸展肌腱攣縮（extensor tendon contracture）","(D) 拇指應維持在外展（abduction）的位置"],"answer":1,"image":""},{"id":"md5-108-1-15","subject":"md5","topic":"整形重建外科","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"下列何者是造成傷⼝攣縮（wound contracture）的主要細胞？","options":["(A) T-淋巴球（T-lymphocyte）","(B) B-淋巴球（B-lymphocyte）","(C) 巨噬細胞（macrophage）","(D) 肌纖維⺟細胞（myofibroblast）"],"answer":3,"image":""},{"id":"md5-108-1-16","subject":"md5","topic":"整形重建外科","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"關於⽪膚移植（skin graft）的敘述，下列何者正確?","options":["(A) ⾎漿浸潤（plasmatic circulation）是指在術後的72⼩時後，移植的⽪膚（grafted skin）將直接吸收養分","(B) 屍⽪（cadaveric skin）覆蓋是屬於異種（xenograft）移植","(C) 常⾒的⼿術失敗原因包括⾎腫、感染，但移植⽪膚因位移產⽣缺失（loss）情況並不多⾒","(D) 移植⽪膚的真⽪愈厚，愈不會產⽣傷⼝疤痕攣縮（scar contracture）"],"answer":3,"image":""},{"id":"md5-108-1-17","subject":"md5","topic":"整形重建外科","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"在處理⼀個困難的傷⼝時，我們常以肌⾁⽪瓣（muscle flap）來重建缺損，根據Mathes & Nahai的分類，以下敘述何者正確？","options":["(A) 臀⼤肌（gluteus maximus）和腹直肌（rectus abdominis）⽪瓣都屬於type II","(B) 闊背肌（latissimus dorsi）由單⼀⾎管莖供應，屬於type I","(C) 適合取較⼤肌⾁來重建缺損的是屬於type I、III、V","(D) 股薄肌（gracilis）是屬於type IV，所以只能取⼀⼩部分肌⾁來重建缺損"],"answer":2,"image":""},{"id":"md5-108-1-18","subject":"md5","topic":"整形重建外科","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"關於各種不同的⽣物⼯程⽪膚替代物（bioengineered skin substitutes）的優點與缺點，下列敘述何者錯誤？","options":["(A) 培養的異體⾓質細胞（allogeneic keratinocyte graft）有傷⼝覆蓋與促進癒合的優點","(B) 培養的異體⾓質細胞（allogeneic keratinocyte graft）缺點是脆弱且無法避免傷⼝攣縮","(C) ⽣物⼯程真⽪替代物（bioengineered dermal replacement）⼤部分只能當作暫時性的傷⼝覆蓋","(D) ⽣物⼯程真⽪替代物（bioengineered dermal replacement）優點是具有優異的引導上⽪化（re- epithelialization）的能⼒"],"answer":3,"image":""},{"id":"md5-108-1-19","subject":"md5","topic":"整形重建外科","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"有關兔唇顎裂（cleft lip and palate）的敘述，下列何者錯誤？","options":["(A) 兔唇顎裂是最常⾒的顏⾯先天異常（anomaly）","(B) 發⽣的原因有家族病史傾向，跟懷孕期間使⽤藥物、感染或吸菸也有關","(C) 嚴重完整型唇顎裂（complete cleft lip/palate）可能導致吸入性肺炎，所以應該提早於3～6周進⾏⼿術","(D) 顎裂矯正⼿術的併發症最常⾒的是瘻管（fistula），其次是無法完全矯正語⾔發⾳和腭咽不全（velopharyngeal insufficiency）"],"answer":2,"image":""},{"id":"md5-108-1-20","subject":"md5","topic":"心臟血管外科","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"根據美國⼼臟協會（American Heart Association）及美國⼼臟學院（American College of Cardiology）對冠狀動脈繞道⼿術之指引，下列何種狀況下接受冠狀動脈繞道⼿術，對延⻑壽命⽽⾔不是第⼀級建議（class I recommendation）？","options":["(A) 僅單純⼀條嚴重阻塞（⼤於75%）且發⽣在左前降冠狀動脈近端（LAD proximal）區域","(B) 左主幹冠狀動脈（left main）嚴重阻塞（⼤於60%）","(C) 三條⾎管阻塞合併有左前降冠狀動脈近端（LAD proximal）嚴重阻塞（⼤於75%）","(D) ⼆條⾎管阻塞包括左前降冠狀動脈近端（LAD proximal）嚴重阻塞（⼤於75%）"],"answer":0,"image":""},{"id":"md5-108-1-21","subject":"md5","topic":"心臟血管外科","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"下列有關急性主動脈剝離（aortic dissection）之描述，何者正確？","options":["(A) 急性主動脈剝離最佳診斷⼯具是⼼臟超⾳波（cardiac echocardiography）或是核磁共振攝影（magnetic resonance imaging）","(B) 急性主動脈剝離發⽣的機制⼤都是內膜層有⼀個破⼝（intimal tear），通常是在主動脈壁外層（adventitia）及中層（media）中間形成⼀假腔（false lumen）","(C) 發⽣急性主動脈剝離最常⾒的症狀為胸痛，非常類似冠狀動脈疾病的壓迫性胸痛，⼆者並不容易區別","(D) 發⽣急性主動脈剝離的病⼈，⼤多都以胸痛為主要症狀，並不會引起其他器官的⾎流不⾜（malperfusion）"],"answer":1,"image":""},{"id":"md5-108-1-22","subject":"md5","topic":"心臟血管外科","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"動脈瘤形成的危險因素不包括下列何者？","options":["(A) ⾼年齡","(B) 男性","(C) ⾼⾎脂","(D) 糖尿病"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第22題一律給分。 (原公告答案 D)"},{"id":"md5-108-1-23","subject":"md5","topic":"心臟血管外科","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"有關⼼臟瓣膜⼿術後，服⽤抗凝⾎劑（warfarin）下列何者錯誤？","options":["(A) 機械性瓣膜（mechanical valve）置換後，建議需⻑期服⽤抗凝⾎劑","(B) 作⽤於凝⾎瀑狀途徑（coagulation cascade factor II,VII, IX, X）","(C) 可以經凝⾎酶原時間（prothrombin time）或國際標準化比值（international normalized ratio, INR）監測，追蹤調整使⽤劑量","(D) 機械性瓣膜（mechanical valve）置換後，調整藥物劑量使國際標準化比值（international normalized ratio, INR）於正常值即可"],"answer":3,"image":""},{"id":"md5-108-1-24","subject":"md5","topic":"心臟血管外科","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"下列情況何者可以暫不考慮放置下腔靜脈過濾器（vena cava filter）？","options":["(A) ⾸次急性之肺動脈栓塞","(B) 深部靜脈栓塞，且不適合使⽤抗凝⾎劑","(C) 深部靜脈栓塞，且有慢性肺栓塞，並已造成肺⾼壓","(D) 在⾜量之抗凝⾎劑治療下，仍反復多次靜脈栓塞"],"answer":0,"image":""},{"id":"md5-108-1-25","subject":"md5","topic":"心臟血管外科","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"對周邊⾎管阻塞的治療，下列何者並不適當？","options":["(A) 照光（phototherapy）","(B) 控制⾼⾎壓，給與⼄型阻斷劑","(C) 控制糖尿病","(D) 以導管⽅式打通⾎管"],"answer":0,"image":""},{"id":"md5-108-1-26","subject":"md5","topic":"胸腔外科","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"關於肋膜積液（pleural effusion）的敘述，下列何者正確？","options":["(A) 漏出液（transudate）常在肺炎或病毒感染時發⽣","(B) 滲出液（exudate）通常是清澈，蛋⽩質含量較低的液體","(C) 滲出液（exudate）是肋膜液的LDH比上⾎清的LDH比值⼩於0.6","(D) 若因肺炎產⽣之肋膜積液，此液體之葡萄糖濃度通常下降，且⼩於60mg/dL"],"answer":3,"image":""},{"id":"md5-108-1-27","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"下列何者不是創傷初級評估中，會有立即⽣命危險之傷害？","options":["(A) ⼼包膜填塞症（cardiac tamponade）","(B) ⾃發性氣胸（spontaneous pneumothorax）","(C) 氣道阻塞（airway obstruction）","(D) 連枷胸（flail chest）併肺挫傷（pulmonary contusion）"],"answer":1,"image":""},{"id":"md5-108-1-28","subject":"md5","topic":"胸腔外科","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"肺癌⼿術後最常⾒的死亡原因為何？","options":["(A) 肺炎合併敗⾎症（pneumonia with sepsis）","(B) ⼼律不整（arrhythmia）","(C) 腎臟衰竭（renal failure）","(D) 中風（stroke）"],"answer":0,"image":""},{"id":"md5-108-1-29","subject":"md5","topic":"胸腔外科","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"處理縱膈腔⽣殖細胞瘤，抽⾎檢查胎兒球蛋⽩（alpha fetal protein）及絨⽑膜激素（beta-HCG），下列之敘述何者錯誤？","options":["(A) 精原細胞瘤（seminoma）的⾎清胎兒球蛋⽩及絨⽑膜激素指數顯著昇⾼","(B) 此⼆項檢查可作為精原細胞瘤（seminoma）及非精原細胞瘤（nonseminomatous germ cell tumor）的鑑別診斷根據","(C) 此⼆項檢查可評估化學治療的效果","(D) 定期偵測此⼆項指數可早期發現腫瘤的復發"],"answer":0,"image":""},{"id":"md5-108-1-30","subject":"md5","topic":"胸腔外科","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"52歲的陳先⽣因肺癌作右下肺葉切除後，術後照顧時需注意的最常⾒併發症是：","options":["(A) 痰積存導致肺泡萎陷（atelectasis）","(B) ⽪下氣腫（subcutaneous emphysema）","(C) 膿胸（empyema）","(D) ⽀氣管胸膜腔瘻管（bronchopleural fistula）"],"answer":0,"image":""},{"id":"md5-108-1-31","subject":"md5","topic":"消化器外科","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"胃底折疊術（fundoplication）不是下列那⼀個疾病⼿術中的⼀個術式？","options":["(A) 食管裂孔疝氣（hiatal hernia）","(B) 胃食道逆流（gastro-esophageal reflux）","(C) ⾎管環（vascular ring）","(D) 賁⾨弛緩不能症（achalasia）"],"answer":2,"image":""},{"id":"md5-108-1-32","subject":"md5","topic":"消化器外科","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"關於Zollinger-Ellison syndrome的敘述，下列何者錯誤？","options":["(A) 病因為胃泌細胞瘤（gastrinoma）⼤量分泌胃泌激素後，造成胃酸分泌過量","(B) 70～90%的腫瘤會分布於總膽管、胃與胰臟頸及胰臟體之間","(C) 必須排除有無第⼀型多發性內分泌腫瘤症候群（MEN I）的可能，因為有四分之⼀的患者會合併有MEN I，只單純治療胃泌細胞瘤（gastrinoma）並不周全","(D) 病⼈會有淋巴及肝臟轉移之風險，所以應將這個腫瘤視為惡性腫瘤"],"answer":1,"image":""},{"id":"md5-108-1-33","subject":"md5","topic":"消化器外科","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"下列關於脾臟⼿術的敘述何者錯誤？","options":["(A) 由於脾臟為造⾎系統及免疫系統的⼀環，最常需要進⾏脾臟切除的原因是因為紫斑症（idiopathic thrombocytopenic purpura）","(B) 紫斑症於脾臟切除⼿術後的預後極佳，對於患者⽽⾔，是最具時間效率的⼀項治療","(C) ⼿術前⼀週應該要接受肺炎鏈球菌疫苗注射，因為有⼩於5%的病患會於脾臟切除⼿術術後嚴重感染（overwhelming postsplenectomy infection）","(D) 脾臟⼿術後常⾒的併發症為肺部塌陷、出⾎及胰臟發炎"],"answer":0,"image":""},{"id":"md5-108-1-34","subject":"md5","topic":"消化器外科","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"肝臟⼿術中，常⽤pringle maneuver來控制並減少出⾎量，下列何結構並未包含在其中？","options":["(A) common hepatic artery","(B) portal vein","(C) common bile duct","(D) hepatic artery proper"],"answer":0,"image":""},{"id":"md5-108-1-35","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"神經內分泌腫瘤發⽣肝轉移時，下列那⼀個情況最不適合選擇肝臟切除⼿術？","options":["(A) 可切除95%以上的肝臟腫瘤體積","(B) ⻑效體抑素作⽤類似物（long-acting somatostatin analogues）治療無效","(C) 有明顯神經內分泌症狀","(D) 病⼈的肝功能為Child-Pugh class B"],"answer":3,"image":""},{"id":"md5-108-1-36","subject":"md5","topic":"消化器外科","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"有關急性膽囊炎及Murphy sign，下列敘述何者正確？①急性膽囊炎常合併黃疸現象②為急性膽囊炎的pathognomonic sign ③深度按壓右胸下的上腹部時，會讓深吸氣突然停⽌④深度按壓右胸下的上腹部時，會讓深呼氣突然停⽌ ⑤急性膽囊炎⼤部分可藉由保守性非⼿術療法獲得緩解","options":["(A) ①②③","(B) ①②④","(C) ②③⑤","(D) ②④⑤"],"answer":2,"image":""},{"id":"md5-108-1-37","subject":"md5","topic":"消化器外科","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"下列何種胰臟囊狀病灶（pancreatic cystic lesion）好發於女性？①漿液性囊狀腺瘤（serous cystadenoma）②胰管內乳突黏液性腫瘤（intraductal papillary mucinous tumor）③實體偽乳突腫瘤（solid-pseudopapillary tumor）④黏液性囊狀腺瘤（mucinous cystic neoplasm）⑤假性囊腫（pseudocyst）","options":["(A) ①②④","(B) ①③④","(C) ①④⑤","(D) ②③⑤"],"answer":1,"image":""},{"id":"md5-108-1-38","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"下列關於medullary thyroid carcinoma的敘述，何者錯誤？","options":["(A) 源⾃於parafollicular或C cells","(B) 約80%的medullary carcinoma與MEN 2A或MEN 2B有關","(C) 可分泌calcitonin，亦可能分泌carcinoembryonic antigen（CEA）","(D) 若同時合併pheochromocytoma，則必須先處理pheochromocytoma"],"answer":1,"image":""},{"id":"md5-108-1-39","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"48歲男性，患有multiple endocrine neoplasia type 1（MEN type 1）合併hyperparathyroidism，於10年前接受副甲狀腺切除⼿術，之後⾎鈣及iPTH皆正常，惟最近追蹤抽⾎檢查顯⽰：iPTH為132 pg/mL，⾎鈣為10.8 mg/dL，則最適宜的診斷為：","options":["(A) secondary hyperparathyroidism","(B) tertiary hyperparathyroidism","(C) persistent hyperparathyroidism","(D) recurrent hyperparathyroidism"],"answer":3,"image":""},{"id":"md5-108-1-40","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"下列關於thyroid storm治療的敘述，何者錯誤？","options":["(A) Lugol's iodine含有⼤量的碘，應避免使⽤","(B) ß-blockers可減少peripheral T4 to T3 conversion","(C) propylthiouracil（PTU）可減少peripheral conversion of T4 to T3","(D) 應給予氧氣及靜脈輸液補充"],"answer":0,"image":""},{"id":"md5-108-1-41","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"乳房原位癌患者必須接受全乳房切除，下列何者除外？","options":["(A) ⾸次局部乳房切除無法有乾淨邊緣（clear margin）","(B) 瀰漫性乳管內鈣化點","(C) 患者強烈無意願保留乳房","(D) 患者無法接受放射線治療"],"answer":0,"image":""},{"id":"md5-108-1-42","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"比較同⼀期別的乳癌，下列何種乳癌組織型態預後最好？","options":["(A) medullary carcinoma","(B) mucinous carcinoma","(C) metaplastic carcinoma","(D) infiltrating ductal carcinoma"],"answer":1,"image":""},{"id":"md5-108-1-43","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"關於乳癌的影像檢查包括超⾳波、乳房攝影及核磁共振，下列敘述何者錯誤？","options":["(A) breast imaging reporting and data system（BI-RADS）⽤以評估惡性可能，其中第⼀類BI-RADS，代表沒有任何病灶","(B) BI-RADS 3代表病灶出現，可能為良性，需短期追蹤","(C) BI-RADS 5代表病灶出現，⽽且已經證實為乳癌","(D) 核磁共振（MRI）適⽤於腋下淋巴乳癌轉移，其原發病灶不明（unknown primary tumor）或佩吉特⽒病（Paget disease）"],"answer":2,"image":""},{"id":"md5-108-1-44","subject":"md5","topic":"小兒外科","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"有關無肛症（imperforate anus）之敘述，下列何者正確？①低位無肛症，⼀般是直接做肛⾨直腸成形⼿術 ②⾼位無肛症都是先做⼤腸造⼝，等幾個⽉後再做肛⾨直腸成形⼿術③容易合併的先天性異常包括脊柱、 ⼼臟、食道及泌尿系統④⾼位無肛症最常合併直腸膀胱瘻管⑤出⽣後要儘快照側⾯的腹部X光片來決定分型","options":["(A) ①②③④⑤","(B) 僅①②④⑤","(C) 僅①③④⑤","(D) 僅①②③"],"answer":3,"image":""},{"id":"md5-108-1-45","subject":"md5","topic":"小兒外科","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"有關尿道下裂（hypospadias）之敘述，下列何者錯誤？","options":["(A) 是依據尿道開⼝位置來分型","(B) ⼿術矯正年齡最好是學齡前約6歲，以免兒童⼼理受到影響","(C) 嚴重的尿道下裂，多需要取周圍的⽪瓣來做尿道重建","(D) 常合併有陰莖彎曲（chordee），尤其是尿道開⼝在近端的類型"],"answer":1,"image":""},{"id":"md5-108-1-46","subject":"md5","topic":"小兒外科","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"下列有關腹股溝疝氣（inguinal hernia）與⼩兒陰囊⽔腫（hydrocele）之敘述，何者錯誤？","options":["(A) ⼩兒的腹股溝疝氣⼤多是間接型的腹股溝疝氣。疝氣囊的形成是因為在胎兒時期的鞘狀突（processus vaginalis）沒有閉合⽽造成的","(B) 疝氣的⼿術治療可在內環（internal ring）的位置做疝氣囊⾼位結紮術（high ligation）","(C) ⼩兒的腹股溝疝氣與陰囊⽔腫，其形成的原因及過程完全不同，故治療的⽅式也不⼀樣","(D) ⼀個本來沒有陰囊⽔腫的⼩男⽣突然出現陰囊⽔腫時，要仔細辨別是否與睪丸腫瘤、創傷、扭轉或副睪炎有關。若有懷疑時，可安排陰囊超⾳波檢查"],"answer":2,"image":""},{"id":"md5-108-1-47","subject":"md5","topic":"小兒外科","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"神經⺟細胞瘤（neuroblastoma）是兒童顱外最常⾒的實質性腫瘤，下列對於神經⺟細胞瘤的敘述，何者錯誤？","options":["(A) 神經⺟細胞瘤源⾃於神經嵴細胞（neural crest cells），是交感神經系統的惡性腫瘤","(B) ⼤約有65%的神經⺟細胞瘤是發⽣在腹部，其中多數位於腎上腺髓質（adrenal medulla），其他在頸部、胸部及骨盆腔亦有病例報告","(C) 當懷疑⼩兒罹患神經⺟細胞瘤時，須收集24⼩時尿液檢測其中的兒苯酚氨（catecholamine）或其代謝產物（例如：dopamine, homovanillic acid, vanillylmandelic acid），通常會發現數據下降","(D) 碘-131核⼦醫學掃描（碘-131 MIBG scan）不但可以⽤來偵測神經⺟細胞瘤的存在及其是否已有轉移，也可⽤來監測神經⺟細胞瘤在接受治療後的反應及其是否有復發跡象"],"answer":2,"image":""},{"id":"md5-108-1-48","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"使⽤全靜脈營養（TPN）之後產⽣膽汁鬱積（cholestasis），下列何者是最理想的治療⽅法？","options":["(A) 增加脂肪乳劑施打","(B) 增加脂溶性維⽣素的補充量","(C) 使⽤中鏈三酸⽢油酯（medium-chain triglyceride）的配⽅","(D) 儘可能恢復腸道營養"],"answer":3,"image":""},{"id":"md5-108-1-49","subject":"md5","topic":"小兒外科","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"滿⽉嬰兒若於餵食後呈現噴射狀嘔吐，須懷疑幽⾨肥厚性狹窄（hypertrophic pyloric stenosis），下列有關檢查及治療之敘述，何者最正確？","options":["(A) 確定診斷可借助腹部觸診發現右上腹橄欖狀硬塊、腹部超⾳波或上消化道攝影","(B) 平躺腹部X光檢查可發現雙氣泡徵象（double bubble sign）","(C) 嬰兒幽⾨肥厚性狹窄因屬腸胃道阻塞之⼀，通常屬於外科急症（surgical emergency）","(D) ⼿術治療⽬前以幽⾨成形⼿術（pyloroplasty）為主"],"answer":0,"image":""},{"id":"md5-108-1-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"62歲男性有⾼⾎壓病史，但不規則服藥，因左下腹痛兩天來到急診，發燒38.5℃，⾎壓90/60 mmHg，⼼跳每分鐘110次，理學檢查左下腹明顯有壓痛硬塊，肛⾨指診出現黏液⾎便，抽⾎結果⽩⾎球22,000/μL，⾎紅素9.7 g/dL。依據前述情況，其最不適宜的檢查為：","options":["(A) ⼤腸鏡（colonoscopy）","(B) 電腦斷層（CT）","(C) 胸部X光（CXR）","(D) 左側躺腹部X光（left lateral decubitus）"],"answer":0,"image":""},{"id":"md5-108-1-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"108年第1次第51題","year":108,"session":1,"number":51,"question":"有關colon diverticular disease，下列敘述何者錯誤？","options":["(A) ⼀般⽽⾔，最常發⽣於sigmoid及descending colon，因colon lumen較窄。但在亞洲，較常發⽣於right colon及cecum","(B) abdominal CT是診斷acute diverticulitis的標準","(C) 對於Hinchey classification stageⅢ之diverticulitis with perforation，需進⾏⼿術治療","(D) complicated diverticulitis最常發⽣fistula的器官為膀胱，且女多於男"],"answer":3,"image":""},{"id":"md5-108-1-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"108年第1次第52題","year":108,"session":1,"number":52,"question":"下列關於痔瘡（hemorrhoids）的敘述，何者正確？","options":["(A) 痔瘡為黏膜下的⾎管組織增⽣，⼜可稱為肛⾨靜脈曲張","(B) ⽬前認為痔瘡功能為協助肛⾨⼝的關閉及節制排便","(C) 因痔瘡有可能會發展成惡性腫瘤，⼀旦發現痔瘡須⾺上積極處理","(D) 如在診間發現患者有⾎栓性外痔瘡，可以在診間考慮使⽤痔瘡結紮術"],"answer":1,"image":""},{"id":"md5-108-1-53","subject":"md5","topic":"消化器外科","meta":"108年第1次第53題","year":108,"session":1,"number":53,"question":"正確分辨Calot's triangle是降低腹腔鏡膽囊切除⼿術併發症的重要關鍵，其構成邊界不含下列何項？","options":["(A) 總肝管（common hepatic duct）","(B) 膽囊管（cystic duct）","(C) 膽囊動脈（cystic artery）","(D) 肝臟邊緣（liver edge）"],"answer":2,"image":""},{"id":"md5-108-1-54","subject":"md5","topic":"消化器外科","meta":"108年第1次第54題","year":108,"session":1,"number":54,"question":"下列有關腹腔鏡⼿術之敘述，何者錯誤？","options":["(A) 腹腔鏡⼿術以全⾝⿇醉進⾏為佳","(B) 對後腹膜腔的器官或需要從腹膜外（extraperitoneal space）進入腹腔時，有時需要⽤氣球撐開術（balloon dissection）來打開第⼀個洞","(C) 腹腔外的內視鏡⼿術（extraperitoneal endosurgery）可做⼿術的空間較⼩，且會增加腸沾粘的機會","(D) 以⼿輔助的腹腔鏡⼿術（hand-assisted laparoscopic surgery）被認為可以降低外科醫師轉換到腹腔鏡的學習曲線，也可減少改為傳統⼿術的機會"],"answer":2,"image":""},{"id":"md5-108-1-55","subject":"md5","topic":"消化器外科","meta":"108年第1次第55題","year":108,"session":1,"number":55,"question":"有關單⼀切⼝腹腔鏡⼿術（single-incision laparoscopic surgery, SILS）的敘述，下列何者錯誤？","options":["(A) 擁擠的套管（trocar）擺設及缺乏左右⼿操作的⾓度","(B) 比起傳統腹腔鏡⼿術，單⼀切⼝腹腔鏡⼿術器械操作較不易撞擊且⼿術視野較寬廣","(C) ⼿術中由單⼀切⼝腹腔鏡膽囊⼿術轉換成傳統腹腔鏡膽囊切除⼿術的比率（conversion rate）文獻報告約為0～24%","(D) 最常⾒的併發症為腹內膿瘍及傷⼝感染"],"answer":1,"image":""},{"id":"md5-108-1-56","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"108年第1次第56題","year":108,"session":1,"number":56,"question":"急性肌腔室症候群（acute compartment syndrome）是骨科急症之⼀，若未即時進⾏減壓⼿術，將導致組織缺⾎及壞死。關於急性肌腔室症候群之敘述，下列何者錯誤？","options":["(A) 骨折是最常⾒的原因","(B) 受到創傷後，⼤腿遠比⼩腿容易發⽣","(C) 即使患側肢體的周邊脈搏搏動（peripheral pulse）及微⾎管回流（capillary return）正常，仍不可排除","(D) 疼痛常是最早出現的症狀"],"answer":1,"image":""},{"id":"md5-108-1-57","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第1次第57題","year":108,"session":1,"number":57,"question":"65歲的女性，早上因椎管狹窄症接受腰椎⼿術。在恢復室時，雙側下肢的運動和感覺神經功能正常。當天晚上約⼗⼀點時，主訴下背開⼑處脹痛及下肢酸⿇無⼒。檢查發現開⼑處有滲⾎，術後傷⼝引流管總量只有50毫升。雙側⾜部背屈及趾背屈⼒量為0分。有關病情之敘述，下列何者正確？","options":["(A) 先繼續觀察⼀天，若症狀仍無改善時，再安排進⼀步脊髓造影（myelography）檢查","(B) 應懷疑可能是在⼿術進⾏中神經已受到損傷⽽造成下肢無⼒，應解釋並告知病患及家屬","(C) 應懷疑發⽣術後脊髓硬膜上⾎腫（hematoma），造成神經受壓迫⽽導致下肢無⼒，應儘速安排⼿術清除⾎ 腫","(D) 應懷疑發⽣術後急性傷⼝感染，產⽣脊髓硬膜上膿瘍，造成神經受壓迫下肢無⼒，應儘速安排⼿術清創"],"answer":2,"image":""},{"id":"md5-108-1-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第1次第58題","year":108,"session":1,"number":58,"question":"有關良性骨病灶及其相關治療的敘述，下列何者錯誤？","options":["(A) 單純性骨囊腫（simple bone cyst）的治療包括：追蹤觀察、限制活動、病灶內類固醇注射、病灶內刮除及骨移植（bone grafting）","(B) 動脈瘤性骨囊腫（aneurysmal bone cyst）的治療包括：活體組織切片（biopsy）加以確診、刮除（curettage）及骨移植（bone grafting）","(C) 骨樣骨瘤（osteoid osteoma）的局部疼痛，可⽤非類固醇抗發炎藥物（nonsteroidal anti-inflammatory drugs）來緩解","(D) 侵犯到脊椎體之嗜伊紅球性⾁芽腫（eosinophilic granuloma），需要執⾏開放性刮除⼿術（open curettage）"],"answer":3,"image":""},{"id":"md5-108-1-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"108年第1次第59題","year":108,"session":1,"number":59,"question":"有關Lisfranc⽒損傷（Lisfranc injury）的敘述，下列何者錯誤？","options":["(A) 屬於跗蹠關節損傷（tarso-metatarsal joint injury）","(B) Lisfranc⽒韌帶位於第⼆楔狀骨（cuneiform）及第⼀蹠骨（metatarsus）之間","(C) ⾜部前後相位（anteroposterior view）的X光檢查，若發現第⼀和第⼆蹠骨基底部的距離增⼤時，須⾼度懷疑此種傷害","(D) ⾜部斜相位（oblique view）的X光檢查，若發現第四蹠骨與骰骨（cuboid）內緣不在同⼀連線，須⾼度懷疑此種傷害"],"answer":1,"image":""},{"id":"md5-108-1-60","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"108年第1次第60題","year":108,"session":1,"number":60,"question":"有位橄欖球選⼿在比賽時，因膝關節受傷被送到急診室，檢查時發現膝關節腫脹變形，當回顧比賽錄影帶時，發現受傷機轉是膝部發⽣過度伸展（hyperextension）合併內翻機轉（varus mechanism），下列處置何者錯誤？","options":["(A) ⾺上送到⼿術房進⾏⼿術，因為有可能膝關節脫⾅（knee dislocation）","(B) ⾺上施⾏普通X光檢查（plain X-ray），因為要評估相對位置","(C) ⾺上評估⾎管，因為有⾼比例⾎管受傷（vascular injury）","(D) 持續評估是否有肌腔室症候群（compartment syndrome），避免嚴重併發症"],"answer":0,"image":""},{"id":"md5-108-1-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第1次第61題","year":108,"session":1,"number":61,"question":"⾎管能夠直接穿過股骨頸⽣⻑板，供應股骨頭的⾎流之年齡層為：","options":["(A) 18個⽉以內","(B) 2歲⾄3歲","(C) 5歲⾄8歲","(D) 10歲以後"],"answer":0,"image":""},{"id":"md5-108-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第1次第62題","year":108,"session":1,"number":62,"question":"有關先天性扳機拇指（congenital trigger thumb）的敘述，下列何者錯誤？","options":["(A) 通常在A2滑⾞（pulley）處可觸摸到結節（nodule）","(B) 年紀⼩於九個⽉⼤的病患，常有⾃癒的可能","(C) ⼤部分病例沒有家族史","(D) 通常沒有發炎反應"],"answer":0,"image":""},{"id":"md5-108-1-63","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第1次第63題","year":108,"session":1,"number":63,"question":"有關Paget⽒變形性骨炎（Paget's disease of bone）的敘述，下列何者正確？","options":["(A) 病灶的骨吸收（resorption）明顯增強，⽽骨⽣成（formation）明顯降低","(B) 可能與細菌感染（bacterial infection）有關","(C) 尚未接受治療的患者，⾎清中鹼性磷酸酶（alkaline phosphatase）會顯著升⾼","(D) 尚未接受治療的患者，尿液中羥基脯胺酸（hydroxyproline）會顯著降低"],"answer":2,"image":""},{"id":"md5-108-1-64","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"108年第1次第64題","year":108,"session":1,"number":64,"question":"當⼀側輸尿管完全阻塞時會產⽣代償現象之敘述，下列何者錯誤？","options":["(A) 急性期時該側腎⾎流增加","(B) 急性期時該側腎⼩球過濾率上升","(C) Felsen 2003年的研究給予實驗動物L-arginine可以增加腎⾎流與輸尿管壓⼒","(D) 當阻塞解除時，可能會有多尿現象"],"answer":1,"image":""},{"id":"md5-108-1-65","subject":"md5","topic":"泌尿-結石與感染","meta":"108年第1次第65題","year":108,"session":1,"number":65,"question":"有關struvite stone的敘述，下列何者錯誤？","options":["(A) 主要成分為鎂（magnesium）、磷酸鹽（phosphate）及氨鹽（ammonium）","(B) 通常以鹿⾓結⽯（staghorn stone）呈現","(C) 病⼈的尿液pH值⼤多⾼於7.2，⽽⼤量利尿無法預防struvite stone之形成","(D) 多是感染性結⽯，主要以抗⽣素治療"],"answer":3,"image":""},{"id":"md5-108-1-66","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第1次第66題","year":108,"session":1,"number":66,"question":"有關成⼈之pheochromocytoma之敘述，下列何者錯誤？","options":["(A) 10%為兩側、10%為惡性、10%不⻑於腎上腺內（extra-adrenal）","(B) 10%發⽣於multiple endocrine neoplasia（MEN）type II之病⼈","(C) 診斷時測量尿液中之metanephrine或catecholamine比vanillylmandelic acid（VMA）更有效","(D) NP-59核醫檢查⽤來定位pheochromocytoma腫瘤位置"],"answer":3,"image":""},{"id":"md5-108-1-67","subject":"md5","topic":"泌尿-腫瘤","meta":"108年第1次第67題","year":108,"session":1,"number":67,"question":"有關前列腺癌治療的敘述，下列何者錯誤？","options":["(A) 早期前列腺癌，若病⼈有10年以上之預期壽命，可以作⼿術切除，放射線治療或荷爾蒙治療，三者之治療效果及預後相當","(B) 轉移性前列腺癌以荷爾蒙治療為主，其中luteinizing hormone releasing hormone（LHRH）agonist在治療效果上，與睪丸切除相當，兩者擇⼀即可","(C) 剛診斷的低容量（low volume）轉移性前列腺癌病⼈，不會有立即的致命危險，平均仍有約3年之存活期","(D) 前列腺癌之⼿術⽅式中，經尿道前列腺刮除術（transurethral resection of the prostate）並非前列腺癌的根除⼿術"],"answer":0,"image":""},{"id":"md5-108-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"108年第1次第68題","year":108,"session":1,"number":68,"question":"⼀位75歲男性5年前診斷前列腺肥⼤已接受藥物治療，兩星期前因感冒⾃⾏到藥局拿藥，最近覺得排尿困難、頻頻上廁所，且有尿失禁，⾝體檢查發現下腹部腫脹，其最可能之診斷是：","options":["(A) 溢出性尿失禁（overflow incontinence）","(B) 完全尿失禁（total incontinence）","(C) 急迫性尿失禁（urge incontinence）","(D) 應⼒性尿失禁（stress incontinence）"],"answer":0,"image":""},{"id":"md5-108-1-69","subject":"md5","topic":"神經外科","meta":"108年第1次第69題","year":108,"session":1,"number":69,"question":"有關⾃主神經反射異常（autonomic dysreflexia，AD）的敘述，下列何者錯誤？","options":["(A) 經常發⽣於脊髓損傷部位⾼於T6～T8以上的病⼈","(B) 病⼈會有低⾎壓","(C) 病⼈會有頭痛及患部以上潮紅","(D) 男性病⼈常併有尿道平滑肌共濟失調（dyssynergia）"],"answer":1,"image":""},{"id":"md5-108-1-70","subject":"md5","topic":"泌尿-結石與感染","meta":"108年第1次第70題","year":108,"session":1,"number":70,"question":"⼀位50歲女性病⼈，無重⼤病史，因為過去12⼩時有發⾼燒、畏寒及腰痛，因此到急診就診，腎臟超⾳波顯3 ⽰腎臟並無結⽯或⽔腫，尿液中⽩⾎球為>100/HPF，但無紅⾎球（<2/HPF），⾎中⽩⾎球達18,000/mm，病⼈在兩週前曾有頻尿及排尿灼熱感，但排尿症狀已經消失，下列何者錯誤？","options":["(A) ⼤腸桿菌（E. coli）是最常⾒的致病菌","(B) 理學檢查可能發現肋骨脊柱三⾓（costo-vertebral angle）有敲痛感（knocking pain）","(C) 通常需要做電腦斷層或靜脈腎盂攝影，進⼀步確定診斷","(D) 如果沒有敗⾎症（septicemia）之症狀，可以考慮投予廣效性⼝服抗⽣素治療10～14天"],"answer":2,"image":""},{"id":"md5-108-1-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"108年第1次第71題","year":108,"session":1,"number":71,"question":"有關兒童尿床（nocturnal enuresis）的敘述，下列何者錯誤？","options":["(A) 續發性尿床（secondary enuresis）的⼩孩應考慮有無尿路感染的可能","(B) 夜間多尿症（nocturnal polyuria）也是可能的原因之⼀","(C) 可以使⽤⾎管增壓素（vasopressin）治療","(D) 藥物治療無效的⼩孩，通常會有較⼤的夜間膀胱容量"],"answer":3,"image":""},{"id":"md5-108-1-72","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第1次第72題","year":108,"session":1,"number":72,"question":"40歲男性病⼈因上腹部不適，上腹部超⾳波檢查發現右腎上⽅腫瘤如圖，最可能的診斷為何？","options":["(A) adrenal myelolipoma","(B) adrenal pheochromocytoma","(C) adrenal cortical adenoma","(D) adrenal cortical carcinoma"],"answer":0,"image":"md5-108-1-72.jpeg"},{"id":"md5-108-1-73","subject":"md5","topic":"消化器外科","meta":"108年第1次第73題","year":108,"session":1,"number":73,"question":"20歲男性因急性腹痛、⾼燒求診，接受對比劑注射後之電腦斷層掃描檢查如圖，最可能之診斷為何？","options":["(A) 急性闌尾炎","(B) ⼤腸憩室炎","(C) 尿路結⽯","(D) 胰臟炎"],"answer":0,"image":"md5-108-1-73.jpeg"},{"id":"md5-108-1-74","subject":"md5","topic":"小兒外科","meta":"108年第1次第74題","year":108,"session":1,"number":74,"question":"關於先天性氣管食道瘻管（congenital tracheoesophageal fistula），下列何者錯誤？","options":["(A) 可分為五型，其中最常⾒者為“H”狀氣管食道瘻管","(B) X光影像檢查可區別有無食道閉鎖","(C) 閉鎖之食道，可經由插入之胃管打轉證實","(D) 病患常合併有吸入性肺炎，或其他骨骼、消化道等先天異常"],"answer":0,"image":""},{"id":"md5-108-1-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第1次第75題","year":108,"session":1,"number":75,"question":"⼀位46歲男性，胸部遭攻擊造成⾎胸合併休克，胸管引流出700 ml⾎液後，⾎壓為118/82 mmHg，⼼跳90下/分，幾分鐘後⾎壓下降為84/62 mmHg，⼼跳126下/分，下列處置何者最優先？","options":["(A) 立即氣管插管","(B) 緊急開胸","(C) 立即輸⾎","(D) 重新評估病⼈"],"answer":3,"image":""},{"id":"md5-108-1-76","subject":"md5","topic":"神經外科","meta":"108年第1次第76題","year":108,"session":1,"number":76,"question":"有關老年⼈外傷處置的敘述，下列何者錯誤？","options":["(A) 老年⼈發⽣硬腦膜下出⾎（subdural hemorrhage）的機率比硬腦膜上出⾎（epidural hemorrhage）機會⾼","(B) 必要時，應及早輸⾎","(C) 胸部挫傷時，發⽣院內感染的機率比年輕⼈⾼","(D) ⽣命徵象變化容易預測"],"answer":3,"image":""},{"id":"md5-108-1-77","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"108年第1次第77題","year":108,"session":1,"number":77,"question":"35歲男性，騎機⾞上班不慎在⼗字路⼝發⽣⾞禍，醫師檢查發現他的右⼿橈骨開放性骨折，傷⼝ ⻑5公分，沒有壓碎也沒有軟組織流失，他的開放性骨折的等級(Grade)為下列何者？","options":["(A) I","(B) II","(C) IIIA","(D) IIIB"],"answer":1,"image":""},{"id":"md5-108-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"108年第1次第78題","year":108,"session":1,"number":78,"question":"張先⽣是⼀位⽊⼯，和妻⼦住在⼀起，每天都會抽⼀包菸且下班後會喝⼀點酒。有⼀次暈倒⼜很快醒來，檢查後發現他有左側頸動脈明顯狹窄，腦⾎管攝影發現狹窄⾼達90%。⾎管外科主治醫師建議他做頸動脈內膜刮除術或置放⽀架等治療，但告知張先⽣接受⼿術有立即死亡或中風的風險，張先⽣對⼿術感到遲疑，並說他再6個⽉就可以領到全部退休⾦；下列何種作法較適當？","options":["(A) 和張先⽣充分討論後，先給予內科藥物治療，並安排戒菸計畫及定期追蹤","(B) 臨床不需考慮治療疾病以外的事，張先⽣的退休⾦不該影響你的醫療決策","(C) 張先⽣可能受到疾病的壓⼒無法做正確的判斷，應聯絡其家屬討論治療⽅向","(D) 先安排⼿術爭取治療時效性，進開⼑房再向張先⽣解釋此⼿術的風險即可"],"answer":0,"image":""},{"id":"md5-108-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"108年第1次第79題","year":108,"session":1,"number":79,"question":"80歲的蘇老先⽣因在家跌倒，右側肱骨骨折，送到醫院急診。在急診時發現他過去病史包括洗腎5年，7年前做過冠狀動脈繞道⼿術，⼼臟科醫師評估起來有較⾼的⼿術風險，但他疼痛難耐，什麼解釋都不想聽，只想趕快接受⼿術治療肱骨骨折。他也不在乎他的家⼈意⾒，反正他就是要接受⼿術，此時主⼑醫師覺得有必要向他解釋清楚，何者最適當？","options":["(A) 把風險告知蘇老先⽣的家⼈，依照家⼈的意願來判斷是否⼿術","(B) 不管蘇老先⽣聽不聽，跟他解釋過就算盡到義務，再按照他的意願接受⼿術","(C) 評估蘇老先⽣的決定能⼒，若有決定能⼒，在他簽署同意書後遵照他的意願","(D) 若蘇老先⽣無決定能⼒，經你的判斷⼿術符合病⼈最⼤利益，給予蘇老先⽣簽署同意書後可進⾏⼿術"],"answer":2,"image":""},{"id":"md5-108-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"108年第1次第80題","year":108,"session":1,"number":80,"question":"黃先⽣5年前接受張醫師⼤腸癌⼿術切除後，於今年發現疑似轉移性肺部病灶。在回顧過去的胸部Ｘ光報告時，發現2年前即有異常病灶出現，⽽當時張醫師並未注意到。此時張醫師應該如何處理？①為避免造成醫療糾紛及訴訟，應隱瞞此⼀事件，立即開始治療病患即可②立刻向病患說明並表達歉意③檢討作業流程，避免事件再次發⽣④將病患轉診腫瘤科醫師，由其向病患解釋","options":["(A) ①③④","(B) ①④","(C) ②④","(D) ②③"],"answer":3,"image":""},{"id":"md5-108-2-1","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"外傷死亡之病人，在外傷發生後那一個時段，死亡人數最多？","options":["(A) 0～15 minutes","(B) 1～24 hours","(C) 3～7 days","(D) 7～30 days"],"answer":0,"image":""},{"id":"md5-108-2-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"頸部受傷的病人接受頸部探查手術的適應症，下列何者錯誤？","options":["(A) 頸部血腫一直擴大","(B) 頸部出現皮下氣腫","(C) 喘鳴（stridor）","(D) 脈搏增快"],"answer":3,"image":""},{"id":"md5-108-2-3","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"人類因為感染或外傷可引發全身性發炎反應症候群（systemic inflammatory response syndrome, SIRS），其臨床表現含：①體溫＞38°C，或 ≤ 36°C②心率 ≥ 90／分③呼吸速率 ≥ 20／分，或PaCO ≤ 32毫米汞柱，或需2要機械式通氣（mechanical ventilation）④白血球 ≥ 12,000／微升(μL)，或 ≤ 4,000／微升(μL)，或band forms ≥ 10%。若病患要被診斷為全身性發炎反應症候群，至少須合乎上列幾種條件？","options":["(A) 一種","(B) 二種","(C) 三種","(D) 四種"],"answer":1,"image":""},{"id":"md5-108-2-4","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"對於慢性不癒合傷口的敘述，下列何者錯誤？","options":["(A) 最常見的原因是傷口感染","(B) 放射線的暴露會造成內皮細胞（endothelial cell）的傷害和endarteritis，導致組織萎縮，纖維化和癒合延緩","(C) Vitamin B缺乏會妨礙單核細胞的活化和fibronectin沉積，然後影響細胞的黏著和妨礙TGF-β receptors 12","(D) 糖尿病會影響傷口癒合的每一個步驟"],"answer":2,"image":""},{"id":"md5-108-2-5","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"52歲男性病人在手術後抽血檢查發現血清鈉離子（serum sodium ion）的濃度為117 mEq/L。下列敘述何者正確？","options":["(A) 此病人除了疼痛之外，沒有其他症狀","(B) 此病人的低鈉血症（hyponatremia）歸類為中度低鈉血症（moderate hyponatremia）","(C) 無症狀病人以含鈉輸液治療時，其輸液注射的速率應使增加的血清鈉離子濃度不超過0.5 mEq/L/hr，一天不超過8～12 mEq/L","(D) 可以觀察其病情，不必採取其他的治療"],"answer":2,"image":""},{"id":"md5-108-2-6","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"下列那一種胺基酸是腸黏膜細胞（enterocytes）之能量來源？","options":["(A) histidine","(B) glutamine","(C) valine","(D) alanine"],"answer":1,"image":""},{"id":"md5-108-2-7","subject":"md5","topic":"神經外科","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"Dandy-Walker malformation是屬於一種小兒先天性水腦症，下列何者最早產生擴大現象？","options":["(A) 第三腦室（3rd ventricle）","(B) 第四腦室（4th ventricle）","(C) 大腦導水管（aqueduct）","(D) 側腦室（lateral ventricle）"],"answer":1,"image":""},{"id":"md5-108-2-8","subject":"md5","topic":"神經外科","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"有關嬰兒搖晃症（shaken baby syndrome）之敘述，下列何者錯誤？","options":["(A) 常跟虐兒（child abuse）有關，有時需要社工介入","(B) 臨床上可做眼底檢查發現視網膜有出血現象（retinal hemorrhage）","(C) 電腦斷層掃描可見急性硬膜下血腫（acute subdural hematoma）","(D) 外觀上很容易發現異常"],"answer":3,"image":""},{"id":"md5-108-2-9","subject":"md5","topic":"神經外科","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"常壓性水腦症（normal pressure hydrocephalus, NPH）經過腦室引流手術後，最容易改善的症狀是下列何者？","options":["(A) 尿失禁","(B) 痴呆","(C) 步態不穩","(D) 半身無力"],"answer":[0,2],"image":"","answer_note":"更正:第9題答Ａ、Ｃ給分。"},{"id":"md5-108-2-10","subject":"md5","topic":"神經外科","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"聽神經瘤（acoustic neuroma）最好發於下列那一條顱神經？","options":["(A) 顏面神經（facial nerve）","(B) 耳蝸神經（cochlear nerve）","(C) 前庭神經（vestibular nerve）","(D) 舌咽神經（glossopharyngeal nerve）"],"answer":2,"image":""},{"id":"md5-108-2-11","subject":"md5","topic":"醫學倫理與法規","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"有關腦死判定（brain death），下列何者不是臨床要件（clinical criteria）？","options":["(A) 患者需處於深度昏迷（deep coma），且對語言（verbal stimulation）及疼痛（pain stimulation）刺激無反應","(B) 患者有自發性呼吸（spontaneous respiration）","(C) 患者喪失腦幹反射（brain stem reflex）","(D) 患者無自主性活動（spontaneous movement）或自主性姿態（spontaneous posturing）"],"answer":1,"image":""},{"id":"md5-108-2-12","subject":"md5","topic":"整形重建外科","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"一位20歲女性割腕自殺被送至急診室時，左手腕掌面橈側有約3公分橫向刀口，神經學檢查發現手掌五指可伸直及併指，但無法彎曲握拳，且手指腹面有麻木感，則此病人最可能為下列那一條神經受損？","options":["(A) 橈神經（radial nerve）","(B) 指神經（digital nerve）","(C) 正中神經（median nerve）","(D) 尺神經（ulnar nerve）"],"answer":2,"image":""},{"id":"md5-108-2-13","subject":"md5","topic":"整形重建外科","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"王媽媽的左手中指在彎曲及伸直的交替動作中，肌腱在掌指關節處基部摸到結節（nodule），且有時會產生聲響，影響手指活動，王媽媽得了什麼疾病 ?","options":["(A) 鎚狀指（mallet finger）","(B) 扳機指（trigger finger）","(C) 狹窄性肌腱滑膜炎（de Quervain tenosynovitis）","(D) 手部鈕扣畸形（bontonniere deformity）"],"answer":1,"image":""},{"id":"md5-108-2-14","subject":"md5","topic":"整形重建外科","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"下列有關乳房重建（breast reconstruction）之敘述，何者錯誤？","options":["(A) 根蒂式橫式腹直肌皮瓣（pedicled transverse rectus abdominis myocutaneous, TRAM flaps）比游離式橫式腹直肌皮瓣（free TRAM flaps）較容易有脂肪壞死及腹部無力","(B) 淺下腹動脈皮瓣（superficial inferior epigastric artery flaps）可以不用犧牲腹直肌","(C) 深下腹動脈穿通支皮瓣（deep inferior epigastric artery perforator flaps）不需要肌肉內剝離（intramuscular dissection）","(D) 游離皮瓣的recipient vessels通常可以接在胸背動靜脈（thoracodorsal artery and vein）或內乳動靜脈（internal mammary artery and vein）"],"answer":2,"image":""},{"id":"md5-108-2-15","subject":"md5","topic":"整形重建外科","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"下列有關眼瞼下垂（ptosis）的敘述，何者錯誤？","options":["(A) 眼輪匝肌（orbicularis oculi muscle）、苗勒氏肌（Müller's muscle）和提眼瞼肌（levator palpebrae muscle）為控制我們眼瞼開合的主要肌肉","(B) 眼瞼下垂可分為先天和後天，其中後天的又可根據機轉分為神經性（neurogenic）、肌肉性（myogenic）或外傷性（traumatic）","(C) 霍納氏症候群（Horner's syndrome）屬於後天性眼瞼下垂，其為肌肉性機轉（myogenic mechanism）","(D) 根據嚴重程度可分為輕度、中度和重度，而額肌筋膜懸吊術（frontalis muscle fascial sling technique）就是用在重度眼瞼下垂的術式"],"answer":2,"image":""},{"id":"md5-108-2-16","subject":"md5","topic":"整形重建外科","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"關於電傷（electrical injury），下列敘述何者正確？","options":["(A) 電流通過體內時，因為血管的電阻最低，所以是電流傳導的主要組織，也因此血管承受最多傷害","(B) 傳導大量電流的血管受傷後，可能造成血管栓塞（thrombosis）","(C) 電傷若造成大範圍肌肉傷害，這些肌肉所釋放的肌球素（myoglobin）會引發阻塞性腎病變（obstructive nephropathy），治療這樣的傷患需要大量輸液，維持傷患的尿量在每公斤每小時1毫升（mL/kg/hr）左右","(D) 低電壓（low-voltage）電傷的傷患，30%左右在受傷後數個月至數年間可能罹患白內障（cataract）或神經系統缺陷（neurologic deficits）"],"answer":1,"image":""},{"id":"md5-108-2-17","subject":"md5","topic":"整形重建外科","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"35歲男性病人因騎機車車禍而頭部受傷，送至急診室，經檢查無顱內出血情形，主要症狀為右側頭皮裂傷（avulsion injury）和傷口出血，下列敘述何者錯誤？","options":["(A) 頭皮可分為皮膚、皮下組織（subcutaneous tissue）、腱膜（galea aponeurotica）、疏鬆蜂窩組織（loose areolar tissue）和顱骨膜（pericranium）五層","(B) 若病患於急診留觀期間，傷口持續出血不止，最好的方法為加壓止血合併輸血治療","(C) 2若有頭皮缺損範圍較大（4～8 cm），無法直接縫合者，除了局部皮瓣外，可以考慮使用組織擴張器（tissue expander）","(D) 2若有頭皮缺損範圍較大（8～10 cm），考慮使用游離皮瓣顯微重建手術治療"],"answer":1,"image":""},{"id":"md5-108-2-18","subject":"md5","topic":"心臟血管外科","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"下列何者為主動脈氣球幫浦（intra-aortic balloon pump）的最佳使用時機？","options":["(A) 急性升主動脈剝離合併急性重度主動脈瓣逆流","(B) 升主動脈瘤合併慢性重度主動脈瓣逆流","(C) 二尖瓣腱索斷裂合併急性重度二尖瓣逆流","(D) 感染性腹主動脈瘤合併敗血性休克"],"answer":2,"image":""},{"id":"md5-108-2-19","subject":"md5","topic":"心臟血管外科","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"一位65歲男性病人因左前胸痛至急診室求診，下列敘述何者正確？①急性主動脈剝離為鑑別診斷之一② 若診斷急性B型主動脈剝離，可考慮以主動脈內血管支架（endovascular aortic graft）治療③若診斷急性心肌梗塞，須考慮經皮冠狀動脈處置（percutaneous coronary intervention）④若診斷急性心肌梗塞，須立即執行冠狀動脈繞道術","options":["(A) ①②③","(B) ①③④","(C) 僅②④","(D) 僅④"],"answer":0,"image":""},{"id":"md5-108-2-20","subject":"md5","topic":"消化器外科","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"下列何種檢查為診斷食道弛緩不能（achalasia）的golden standard？","options":["(A) double-contrast esophagography","(B) 上消化道內視鏡檢查（upper gastrointestinal endoscopy）","(C) 食道壓測試（manometry）","(D) ambulatory 24-hour pH monitoring"],"answer":2,"image":""},{"id":"md5-108-2-21","subject":"md5","topic":"胸腔外科","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"關於肋膜積液，下列敘述何者錯誤？","options":["(A) 多數惡性肋膜積液為exudate","(B) 轉移性乳癌及肺癌最常造成惡性肋膜積液","(C) 利用胸腔鏡手術引流同時亦有診斷的效果","(D) 肋膜黏連術（pleurodesis）對治療肋膜積液無效"],"answer":3,"image":""},{"id":"md5-108-2-22","subject":"md5","topic":"胸腔外科","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"對於肺癌手術，下列何者不是必要的檢查？","options":["(A) 肺功能檢查","(B) 正子攝影（positron emission tomography, PET）檢查","(C) 腦血管攝影檢查","(D) 胸部CT檢查"],"answer":2,"image":""},{"id":"md5-108-2-23","subject":"md5","topic":"胸腔外科","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"關於縱膈腔生殖細胞瘤（germ cell tumor）的敘述，下列何者錯誤？","options":["(A) teratoma最常見","(B) seminoma病人的抽血檢查可見α-fetoprotein升高","(C) nonseminomatous tumor病人的抽血檢查可見β-HCG的升高","(D) seminoma對放射治療比nonseminomatous tumor有效應"],"answer":1,"image":""},{"id":"md5-108-2-24","subject":"md5","topic":"消化器外科","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"王先生因為持續性腹痛而至醫院急診處就診，根據他的描述，剛開始腹痛是在肚臍周圍，幾小時後症狀加劇且腹痛位置變成右下腹，王先生之後接受手術治療，證實是急性闌尾炎。則這種型態的腹痛應為下列何者？","options":["(A) 投射性疼痛（referred pain）","(B) 由臟器性疼痛（visceral pain）轉變為腹壁性疼痛（parietal pain）","(C) 由腹壁性疼痛（parietal pain）轉變成臟器性疼痛（visceral pain）","(D) 慢性疼痛（chronic pain）"],"answer":1,"image":""},{"id":"md5-108-2-25","subject":"md5","topic":"消化器外科","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"關於胃癌的手術治療，下列何者錯誤？","options":["(A) 手術的切除邊緣（resection margin）最好距離胃癌腫瘤（cancer mass）至少5～6公分","(B) 次全胃切除併邊緣無癌細胞（subtotal gastrectomy with negative margin）對於遠端胃癌（distal gastric cancer）是適當的","(C) 對於胃癌之淋巴腺廓清術（lymphadenectomy），NCCN（National Comprehensive Cancer Network）建議D2切除（D2 resection）（至少15個淋巴結）","(D) 胃癌的手術治療中，脾切除（splenectomy）是常規的步驟"],"answer":3,"image":""},{"id":"md5-108-2-26","subject":"md5","topic":"消化器外科","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"有關肝性腦病變（hepatic encephalopathy）的敘述，下列何者錯誤？","options":["(A) 臨床症狀可以是行為改變或手部顫動（flapping tremor）","(B) 應多吃高蛋白食物以補充體力","(C) 常因胃腸道出血而誘發","(D) 血中氨（ammonia）濃度常升高"],"answer":1,"image":""},{"id":"md5-108-2-27","subject":"md5","topic":"消化器外科","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"有關小腸功能之敘述，下列何者錯誤？","options":["(A) 製造分泌somatostatin","(B) 製造分泌histamine","(C) 製造分泌cholecystokinin","(D) 製造分泌secretin"],"answer":1,"image":""},{"id":"md5-108-2-28","subject":"md5","topic":"消化器外科","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"有關小腸腫瘤之敘述，下列何者錯誤？","options":["(A) 腺癌發生的部位以十二指腸和上端空腸較多，遠端空腸或迴腸就較少","(B) 若小腸癌發生在十二指腸以外，術前的正確診斷率只有50%左右","(C) 手術完全切除才較有機會治癒，化學治療和放射治療效果至目前結果都不好","(D) 若剖腹進去發現已有腸繫膜轉移，因預後很差，就算病患有出血或腸阻塞，也完全不用做palliative surgery"],"answer":3,"image":""},{"id":"md5-108-2-29","subject":"md5","topic":"消化器外科","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"下列有關切口性疝氣（incisional hernia）之敘述，何者錯誤？","options":["(A) 源自過去腹部手術傷口張力太大或癒合不良","(B) 術後傷口感染為原因之一","(C) 外科手術是唯一有效的治療辦法","(D) 一定要用人工膜（mesh）來修補缺口"],"answer":3,"image":""},{"id":"md5-108-2-30","subject":"md5","topic":"消化器外科","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"一位45歲自小罹患慢性B型肝炎的男性病患，主訴一個多月前覺得右上腹疼痛，有時疼痛會延伸到右邊的肩膀。最近一週至門診追蹤腹部超音波顯示有多顆肝臟腫瘤，分別是一顆2.2公分大小在S2的位置，和另一顆6.6公分大小在S5的位置，有觀察到低迴音（hypoechoic）的腫塊。進一步安排腹部電腦斷層之後，發現在相同位置有同樣大小的腫塊，並且已經侵犯到右側肝門靜脈。其他部位的腹部超音波和電腦斷層結果皆屬正常。抽血結果發現胎兒蛋白值（AFP）為230 ng/mL，AST 53 U/L，ALT 68 U/L。則這位病人最可能的診斷為何？","options":["(A) liver abscess with necrosis","(B) hepatocellular carcinoma with portal vein thrombosis","(C) multiple cavernous hemangioma","(D) acute-on-chronic hepatitis"],"answer":1,"image":""},{"id":"md5-108-2-31","subject":"md5","topic":"消化器外科","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"59歲男性因腹脹求診，電腦斷層檢查如圖一，該病人接受腹腔鏡切除手術，手術標本如圖二，下列何者正確？","options":["(A) 該腫瘤位於肝的caudate lobe","(B) 該腫瘤造成左肝管阻塞","(C) 該腫瘤屬於全實心腫瘤（solid mass）","(D) 該腫瘤屬於肝膿瘍"],"answer":1,"image":"md5-108-2-31.jpeg"},{"id":"md5-108-2-32","subject":"md5","topic":"消化器外科","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"下列關於胰臟神經內分泌腫瘤之敘述，何者錯誤？","options":["(A) 胰臟功能性神經內分泌腫瘤以胰島素瘤（insulinoma）最多","(B) insulinoma的Whipple's triad診斷包括：低血糖，因低血糖出現的症狀及給與葡萄糖後症狀立刻緩解三項","(C) insulinoma大部分是hypovascularity。在contrast enhanced CT下，易形成完全低顯影的腫塊影像","(D) 發生率男、女性差不多"],"answer":2,"image":""},{"id":"md5-108-2-33","subject":"md5","topic":"消化器外科","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"對於肝硬化的敘述，下列何者錯誤？","options":["(A) 經頸靜脈肝內門體靜脈分流術TIPS（transjugular intrahepatic portosystemic shunt）會使得肝性腦病變（hepatic encephalopathy）的機會增加","(B) 預防肝硬化所引起的食道靜脈瘤的首選藥物為非選擇性α-blockers","(C) 不論是否伴隨著出血，末期肝衰竭病患都需考慮肝臟移植","(D) 食道靜脈瘤出血處置需要外科介入的情況，包含內視鏡處理失敗，胃靜脈瘤出血和TIPS治療失敗"],"answer":1,"image":""},{"id":"md5-108-2-34","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"下列何者在甲狀腺全切除術後，不適合接受碘-131治療？","options":["(A) 甲狀腺乳突癌papillary carcinoma（T1N1aM0）","(B) 甲狀腺濾泡癌follicular carcinoma（T1N1aM0）","(C) 甲狀腺髓質癌medullary carcinoma（T1N1aM0）","(D) 甲狀腺何氏細胞癌Hürthle cell carcinoma（T1N1aM0）"],"answer":2,"image":""},{"id":"md5-108-2-35","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"下列有關前哨淋巴結切片術（sentinel lymph node biopsy）的敘述，何者錯誤？","options":["(A) 可減少腋下淋巴廓清（axillary lymph node dissection）造成手臂淋巴水腫的發生","(B) 外科醫師執行前哨淋巴結切片術之經驗中，前百例若有偽陰性，不應再執行前哨淋巴結切片術","(C) 乳房全切除（total mastectomy）者亦可做前哨淋巴結切片術","(D) 理學檢查若摸到腋下淋巴結者，不適合做前哨淋巴結切片術"],"answer":1,"image":""},{"id":"md5-108-2-36","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"10歲女童右側乳暈下摸到約2公分大小的硬塊，略有壓痛，下列敘述何者錯誤？","options":["(A) 最可能為prepubertal gynecomastia","(B) 左側乳房可能不久亦會出現對稱硬塊","(C) 觀察追蹤（follow-up）即可","(D) 安排乳房切片（biopsy）"],"answer":3,"image":""},{"id":"md5-108-2-37","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"一位45歲女性接受篩檢乳房攝影( screening mammography )，發現有聚集微細鈣化( clustered microcalcification )屬BI-RADS Ⅳ，乳房觸診未發現有硬塊，下列處置何者不宜？","options":["(A) 安排定位切片手術( wire-localized surgical excision )","(B) 安排立體定位粗針穿刺( stereotactic core needle biopsy )","(C) 三至六個月後再追蹤乳房攝影","(D) 安排乳房超音波檢查，確認有無乳房腫瘤存在"],"answer":2,"image":""},{"id":"md5-108-2-38","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"下列有關乳房Paget disease之敘述，何者錯誤？","options":["(A) 一種由乳管內乳癌（intraductal carcinoma）生成之乳癌","(B) 原始病灶在乳暈","(C) 乳頭及乳暈皮膚呈濕疹樣（eczematous eruption）或牛皮疹（psoriatic rash）","(D) 需切片檢查以鑑別診斷皮膚病變"],"answer":1,"image":""},{"id":"md5-108-2-39","subject":"md5","topic":"小兒外科","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"一體重約2200克之肛門閉鎖（imperforate anus）女嬰，出生後3小時發現有發紺，呼吸急促，嘴角不時有泡沫狀透明唾液流出（如下圖），其最可能合併什麼問題？","options":["(A) 十二指腸閉鎖（duodenal atresia）","(B) 肥厚性幽門狹窄（hypertrophic pyloric stenosis）","(C) 食道閉鎖（esophageal atresia）","(D) 橫膈膜疝氣（diaphragmatic hernia）"],"answer":2,"image":"md5-108-2-39.jpeg"},{"id":"md5-108-2-40","subject":"md5","topic":"小兒外科","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"關於兒童肌性斜頸症（torticollis），下列敘述何者正確？①為胸鎖乳突肌纖維化所引起②臉部向患側旋轉受限制③對側臉部發育不良④皆須手術治療","options":["(A) ②④","(B) ①③④","(C) 僅①②","(D) ①②③"],"answer":2,"image":""},{"id":"md5-108-2-41","subject":"md5","topic":"小兒外科","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"Ladd procedure是下列何種疾病的手術方法?","options":["(A) 小腸閉鎖（intestinal atresia）","(B) 十二指腸閉鎖（duodenal atresia）","(C) 巨大結腸症（Hirschsprung's disease）","(D) 腸扭轉異常（anomalies of intestinal rotation）"],"answer":3,"image":""},{"id":"md5-108-2-42","subject":"md5","topic":"小兒外科","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"下列何者是兒童惡性橫紋肌肉瘤（rhabdomyosarcoma）較不好發的部位？","options":["(A) 頭頸部","(B) 四肢","(C) 腸胃道","(D) 泌尿道系統"],"answer":2,"image":""},{"id":"md5-108-2-43","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"有關隱睪症（cryptorchidism）的敘述，下列何者錯誤？","options":["(A) 可能合併腹股溝疝氣","(B) 手術以睪丸固定術（orchidopexy）為主","(C) 未經治療的隱睪症病患日後有可能造成不孕","(D) 手術的時機為學齡後"],"answer":3,"image":""},{"id":"md5-108-2-44","subject":"md5","topic":"消化器外科","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"陳奶奶今年75歲，胃手術後長期右上腹疼痛，但陳奶奶並不以為意，有天突然腹脹、噁心嘔吐到急診就診，腹部X光（如下圖）檢查發現右下方有一顆radiopaque（箭頭處）的mass，下列何項診斷最符合陳奶奶的臨床表現？","options":["(A) 異物形成的bezoar","(B) gallstone ileus","(C) 尿道結石","(D) 骨盆腔鈣化腫瘤"],"answer":1,"image":"md5-108-2-44.jpeg"},{"id":"md5-108-2-45","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"primary hyperparathyroidism造成的併發症中，下列何者無關？","options":["(A) osteoporosis, osteopenia","(B) tetany","(C) depression, anxiety","(D) kidney stone"],"answer":1,"image":""},{"id":"md5-108-2-46","subject":"md5","topic":"內分泌與乳房外科","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"下列關於甲狀腺手術前的照護，何者錯誤？","options":["(A) Graves' disease病人，手術前給予Lugol's iodine solution","(B) hyperthyroidism病人，先給予抗甲狀腺藥物","(C) 常規手術應給予預防性抗生素","(D) 聲音嘶啞的病人，手術前應做laryngoscopy"],"answer":2,"image":""},{"id":"md5-108-2-47","subject":"md5","topic":"神經外科","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"一位路倒病人被救護車送到急診室時發現眼睛僅對痛有反應，會發出嗯嗯啊啊的呻吟，四肢呈現不正常的彎曲（abnormal flexion），病人的昏迷指數（Glasgow coma scale）是幾分？","options":["(A) 6","(B) 7","(C) 8","(D) 9"],"answer":1,"image":""},{"id":"md5-108-2-48","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"承上題，在急救過程當中需要中央靜脈導管給與大量的靜脈輸液，下列何者不是最常使用的血管？","options":["(A) 內頸靜脈（internal jugular vein）","(B) 股靜脈（femoral vein）","(C) 頭靜脈（cephalic vein）","(D) 鎖骨下靜脈（subclavian vein）"],"answer":2,"image":""},{"id":"md5-108-2-49","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"70歲老先生因中風長期臥床，在他的薦骨部有一面積10×8公分深可見骨的褥瘡（pressure sore）（如下圖），造成褥瘡的最主要原因是：","options":["(A) 摩擦（friction）","(B) 壓力（pressure）","(C) 剪力（shearing force）","(D) 傷口衛生照顧不良（poor hygiene）"],"answer":1,"image":"md5-108-2-49.jpeg"},{"id":"md5-108-2-50","subject":"md5","topic":"整形重建外科","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"承上題，在清創手術治療後，下列何種皮瓣最適宜覆蓋此處褥瘡傷口？","options":["(A) 臀大肌肌皮瓣（gluteus maximus myocutaneous flap）","(B) 張闊筋膜肌皮瓣（tensor fascia latae myocutaneous flap）","(C) 闊背肌肌皮瓣（latissimus dorsi myocutaneous flap）","(D) 腹直肌肌皮瓣（rectus abdominis myocutaneous flap)"],"answer":0,"image":""},{"id":"md5-108-2-51","subject":"md5","topic":"心臟血管外科","meta":"108年第2次第51題","year":108,"session":2,"number":51,"question":"一位2星期大的男嬰，出生時體重3000 gm，Apgar score 8至9分，身體檢查並沒有發現異常現象。幾天前，開始有呼吸急促及發紺的現象，急送某醫學中心。經心臟超音波檢查發現病人有肺動脈瓣閉鎖的現象，經投予前列腺素靜脈注射，病人的發紺改善了。請依此回答下列3題：改善的原因為何？","options":["(A) 肺動脈瓣打開，改善肺動脈血流","(B) 開放性動脈導管再度打開，改善肺動脈血流","(C) 經由心房中隔缺損，肺動脈血流增加","(D) 經由體動脈至肺動脈之側枝循環，增加肺動脈血流"],"answer":1,"image":""},{"id":"md5-108-2-52","subject":"md5","topic":"心臟血管外科","meta":"108年第2次第52題","year":108,"session":2,"number":52,"question":"在考慮進一步手術治療方式前，再仔細作超音波檢查，發現他的右心室發育不良，沒有心室中隔缺損，右心室竇（sinusoid）與左冠狀動脈有相通，作心導管檢查，右心室攝影時，顯影劑在心縮期，可進入左冠狀動脈，且看到左主冠狀動脈出口有狹窄。綜合這些檢查結果，那一種手術治療的方式最佳？","options":["(A) 肺動脈瓣切開術","(B) Blalock-Taussig分流術","(C) 利用體外循環幫忙，作跨肺動脈環部布塊（transannular patch）來擴大右心室出口徑","(D) 肺動脈瓣切開術加Blalock-Taussig分流術"],"answer":1,"image":""},{"id":"md5-108-2-53","subject":"md5","topic":"心臟血管外科","meta":"108年第2次第53題","year":108,"session":2,"number":53,"question":"依此病人心臟狀態，他最後的手術矯正方式，可以朝著那個方向進行？","options":["(A) 維持兩個心室之修補方式（two-ventricular repair）","(B) 只要肺動脈瓣置換就可","(C) 單心室之修補方式（single ventricular repair），即全腔靜脈肺動脈吻合術（total cavopulmonary connection，TCPC）","(D) 只要三尖瓣置換就可"],"answer":2,"image":""},{"id":"md5-108-2-54","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"108年第2次第54題","year":108,"session":2,"number":54,"question":"一位58歲婦女，因下腹部悶痛且大便次數頻繁至大腸直腸外科門診，下列何者不是門診須立刻安排的檢查項目？","options":["(A) 腹部理學檢查","(B) 肛門指診","(C) 陰道指診","(D) 電腦斷層"],"answer":3,"image":""},{"id":"md5-108-2-55","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"108年第2次第55題","year":108,"session":2,"number":55,"question":"承上題，經檢查後發現糞便內混有血跡，直腸無異常，下列何者是後續最適當之檢查項目？","options":["(A) 電腦斷層掃描","(B) 大腸鋇劑X光攝影檢查","(C) 大腸鏡纖維內視鏡檢查","(D) 腹部超音波檢查"],"answer":2,"image":""},{"id":"md5-108-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第2次第56題","year":108,"session":2,"number":56,"question":"有關惡性骨腫瘤的敘述，下列何者最正確？","options":["(A) Enneking stage IIB是指高惡性度，同一腔室內的病灶（intra-compartmental lesion）","(B) 目前惡性骨肉瘤（osteosarcoma）的標準治療，是先切除腫瘤，再輔以術後放射治療，以避免局部復發","(C) 惡性軟骨瘤（chondrosarcoma）的治療主要是手術切除病灶","(D) 肢體保留手術與截肢手術相比，局部腫瘤復發率較高，同時接受肢體保留手術患者存活率較低"],"answer":2,"image":""},{"id":"md5-108-2-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"108年第2次第57題","year":108,"session":2,"number":57,"question":"一位32歲男性左股骨幹骨折（femoral shaft fracture），手術後2年半，仍時常感到左大腿疼痛，無法負重行走，其X光檢查結果如下圖。下列敘述何者錯誤？","options":["(A) 可能造成骨折不癒合（nonunion）因素包括受傷時合併嚴重軟組織傷害、感染、骨折固定不夠穩定、營養不良、吸煙、長期使用類固醇等","(B) 骨折的手術治療，應盡量將骨折斷端的軟組織從骨頭上剝離（excessive soft tissue stripping from bone），以充分檢視骨折斷端並對齊固定，可減少骨折不癒合（nonunion）的發生","(C) 此病例的診斷為增生性不癒合（hypertrophic nonunion），常因為骨折固定的穩定度不足而造成","(D) 此病例可採用更換較大的骨髓內釘（intramedullary nail）及骨移植（bone grafting）進行治療"],"answer":1,"image":"md5-108-2-57.jpeg"},{"id":"md5-108-2-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第2次第58題","year":108,"session":2,"number":58,"question":"俗稱「媽媽手」的腕部肌腱炎，稱作DeQuervain氏症，是腕部六個伸肌腱腔室（compartment）中最靠橈側的第一腔室內的肌腱發炎。這包括下列那一條肌腱？","options":["(A) 橈側伸腕短肌腱（extensor carpi radialis brevis tendon）","(B) 橈側伸腕長肌腱（extensor carpi radialis longus tendon）","(C) 拇指伸展長肌腱（extensor pollicis longus tendon）","(D) 拇指外展長肌腱（abductor pollicis longus tendon）"],"answer":3,"image":""},{"id":"md5-108-2-59","subject":"md5","topic":"骨科-關節重建","meta":"108年第2次第59題","year":108,"session":2,"number":59,"question":"若以後方入路（posterior approach）方式施行全髖人工關節置換術（total hip replacement），則下列何肌肉必須被切斷？","options":["(A) 臀中肌（gluteus medius muscle）","(B) 臀小肌（gluteus minimus muscle）","(C) 上孖肌（superior gemellus muscle）","(D) 股外肌（vastus lateralis muscle）"],"answer":2,"image":""},{"id":"md5-108-2-60","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"108年第2次第60題","year":108,"session":2,"number":60,"question":"一位36歲女性因車禍跌倒時，右臂受到直接撞擊，造成右前臂腫痛及變形，經X光檢查發現遠端橈骨骨折併遠端橈尺骨關節脫位，此病患最可能的診斷為何？","options":["(A) Galeazzi氏骨折","(B) Smith氏骨折","(C) Monteggia氏骨折","(D) Essex-Lopresti氏骨折"],"answer":0,"image":""},{"id":"md5-108-2-61","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"108年第2次第61題","year":108,"session":2,"number":61,"question":"有關肘關節駭人的傷害三合組（terrible triad injuries of the elbow），下列何者除外？","options":["(A) 鳥喙狀骨骨折（coronoid fracture）","(B) 橈骨頭部骨折（radial head fracture）","(C) 肱骨髁上骨折（supracondylar fracture of humerus）","(D) 肘關節脫臼（elbow dislocation）"],"answer":2,"image":""},{"id":"md5-108-2-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第2次第62題","year":108,"session":2,"number":62,"question":"下列那一種疾病不是兒童足踝疾病的名稱？","options":["(A) Köhler氏病變（Köhler disease）","(B) Freiberg氏病變（Freiberg infarction）","(C) Panner氏病變（Panner disease）","(D) Sever式病變（Sever disease）"],"answer":2,"image":""},{"id":"md5-108-2-63","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第2次第63題","year":108,"session":2,"number":63,"question":"依據Denis的分類，下列何處胸腰椎受傷（thoracolumbar injuries）會被認為不穩定？","options":["(A) 前柱（anterior column）","(B) 中柱（middle column）","(C) 後柱（posterior column）","(D) 胸腰椎交界處（thoracolumbar junction）"],"answer":1,"image":""},{"id":"md5-108-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"108年第2次第64題","year":108,"session":2,"number":64,"question":"下列何者不是抑制尿路結石形成的因子（inhibitor）？","options":["(A) 鎂（magnesium）","(B) 硫酸（sulfate）","(C) 檸檬酸（citrate）","(D) 鈉（sodium）"],"answer":3,"image":""},{"id":"md5-108-2-65","subject":"md5","topic":"泌尿-腫瘤","meta":"108年第2次第65題","year":108,"session":2,"number":65,"question":"有關腎細胞癌（renal cell carcinoma）所引起全身性臨床症狀，下列何者錯誤？","options":["(A) paraneoplastic syndrome會發生在大約20%腎細胞癌之病人","(B) paraneoplastic syndrome最常表現的全身性症候群是紅血球沉澱速率（ESR）升高","(C) paraneoplastic syndrome最常發生的臨床症狀是高鈣血症，其次是高血壓","(D) 高血鈣症發生率可高達13%，其原因係paraneoplastic phenomena或骨轉移造成之骨質溶解"],"answer":2,"image":""},{"id":"md5-108-2-66","subject":"md5","topic":"泌尿-腫瘤","meta":"108年第2次第66題","year":108,"session":2,"number":66,"question":"下列有關根除性膀胱切除術（radical cystectomy）的敘述，何者錯誤？","options":["(A) 經膀胱內藥物灌注後仍反覆復發的high grade膀胱癌或膀胱原位癌（carcinoma in situ）患者，建議要施行此類手術","(B) 術前不必停止服用aspirin","(C) 腿部深層靜脈血栓可能於術後發生","(D) 手術的死亡率約為1～3%"],"answer":1,"image":""},{"id":"md5-108-2-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"108年第2次第67題","year":108,"session":2,"number":67,"question":"下列有關良性前列腺肥大（BPH）的敘述，何者錯誤？","options":["(A) BPH是源自前列腺之transition zone（TZ）","(B) 顯微鏡下BPH係由stroma及上皮細胞所組成，而stroma中之平滑肌則是由α-1交感神經所支配為主","(C) BPH的體積大小與血液中之free testosterone及estrogen均成正相關","(D) BPH所引起的下泌尿道阻塞症狀與肛門指診時其體積大小成正相關"],"answer":3,"image":""},{"id":"md5-108-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"108年第2次第68題","year":108,"session":2,"number":68,"question":"關於膀胱儲尿期的神經系統作用，下列敘述何者錯誤？","options":["(A) 膀胱漲尿的訊號是經由骨盆神經（pelvic nerve）傳至中樞神經系統","(B) 由橋腦儲尿中樞（pontine storage center）發出的訊號是經由骨盆神經（pelvic nerve）傳至尿道外括約肌","(C) 交感神經訊號增強，且經由下腹神經（hypogastric nerve）傳至膀胱","(D) 膀胱滿漲的訊號可刺激脊髓反射作用稱為防護反射（guarding reflex），可增加禁尿的功能"],"answer":1,"image":""},{"id":"md5-108-2-69","subject":"md5","topic":"泌尿-結石與感染","meta":"108年第2次第69題","year":108,"session":2,"number":69,"question":"一位58歲女性病人，因為2天前開始頻尿、小便灼熱感、小腹覺得有輕微脹痛感，有時覺得尿不太出來，今天開始出現血尿，沒有血塊，則下列何者錯誤？","options":["(A) 最可能的診斷是急性細菌性膀胱炎","(B) 絕大多數社區型感染之病原菌是大腸桿菌（E. coli）","(C) 應該安排膀胱鏡檢查","(D) 在門診很常見，典型的病例並不一定要做尿液細菌培養"],"answer":2,"image":""},{"id":"md5-108-2-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"108年第2次第70題","year":108,"session":2,"number":70,"question":"下列何者是腎臟移植受腎者的絕對禁忌症？ ①完全治癒之子宮頸癌病人②慢性藥物成癮、習慣性藥物濫用的患者③無法遵守藥囑（non- compliance）④活動性或是尚未治癒之慢性感染，如慢性活動性肝炎（chronic active hepatitis）或肝衰竭病人","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":2,"image":""},{"id":"md5-108-2-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"108年第2次第71題","year":108,"session":2,"number":71,"question":"一位35歲不孕男性病患，精液檢查發現無精蟲，血中FSH、LH及testosterone較低，且病人嗅覺異常，最可能之診斷為：","options":["(A) hyperprolactinemia","(B) Kallmann syndrome","(C) Klinefelter's syndrome","(D) XYY syndrome"],"answer":1,"image":""},{"id":"md5-108-2-72","subject":"md5","topic":"泌尿-腫瘤","meta":"108年第2次第72題","year":108,"session":2,"number":72,"question":"一名5天前做過右側腎臟切片的病人主訴血尿，右側腎動脈血管攝影檢查呈現如附圖。下列那一項初診斷最正確？","options":["(A) ureteral stone","(B) pseudoaneurysm and arteriovenous fistula","(C) fibromuscular dysplasia","(D) post-biopsy pyelonephritis"],"answer":1,"image":"md5-108-2-72.jpeg"},{"id":"md5-108-2-73","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第2次第73題","year":108,"session":2,"number":73,"question":"病人主訴左上腹部疼痛和發燒，血液中白血球數目增加。電腦斷層檢查呈現如附圖。下列那一項初診斷最正確？","options":["(A) spleen abscess","(B) left psoas muscle abscess","(C) colon diverticulitis","(D) peripancreatic abscess"],"answer":0,"image":"md5-108-2-73.jpeg"},{"id":"md5-108-2-74","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"108年第2次第74題","year":108,"session":2,"number":74,"question":"3歲小男生走路搖搖擺擺，步態不穩，髖關節X光檢查如附圖，最可能的診斷為何？","options":["(A) Legg-Calvé-Perthes disease","(B) slipped femoral capital epiphysis","(C) developmental dysplasia of the hip（DDH）","(D) osteochondrosis"],"answer":2,"image":"md5-108-2-74.jpeg"},{"id":"md5-108-2-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"108年第2次第75題","year":108,"session":2,"number":75,"question":"一輛校車和卡車對撞後，引起爆炸和火燒車，車內一位6歲男孩被送到急診室，他的眉毛、鼻毛被燒焦，且臉和頸部有大約12% body surface area（BSA）的燒傷，他的聲音沙啞、呼吸快淺，血紅素氧飽合度為70%。此時下列處置何者第一優先？","options":["(A) 動脈氣體分析（arterial blood gas）","(B) 胸部X光","(C) 給予靜脈輸液","(D) 實行氣管內管插管（endotracheal intubation）"],"answer":3,"image":""},{"id":"md5-108-2-76","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"108年第2次第76題","year":108,"session":2,"number":76,"question":"21歲男性打籃球時，跳投後不慎跌倒右手著地，右前臂明顯腫脹，X光檢查顯示尺骨近端骨折合併橈骨頭脫位，此種骨折稱為：","options":["(A) Colles fracture","(B) Chauffeur's fracture","(C) Galeazzi's fracture","(D) Monteggia's fracture"],"answer":3,"image":""},{"id":"md5-108-2-77","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"108年第2次第77題","year":108,"session":2,"number":77,"question":"有關膀胱尿道逆流（vesicoureteral reflux）發生原因的敘述，下列何者錯誤？","options":["(A) 小孩有尿道感染時容易發生","(B) 膀胱三角肌無力（trigonal weakness）","(C) 完全尿道複製（complete ureteral duplication）","(D) 前膀胱頸局部切除（wedge resection of the anterior vesical neck）"],"answer":3,"image":""},{"id":"md5-108-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"108年第2次第78題","year":108,"session":2,"number":78,"question":"12歲的蔡小弟弟因為騎腳踏車受傷，傷及大動脈而大量出血，經救護車送來醫院的時候，血壓已經開始下降。急診室的賴醫師打算先幫他大量輸血，穩定生命徵兆後，再進行後續相關手術。經打電話跟蔡小弟弟的父母親聯絡後，蔡小弟弟的父母親基於宗教理由，堅持不能幫蔡小弟弟輸血，只能使用代用血漿。賴醫師向其父母親解釋代用血漿並無法完全取代血液，蔡小弟弟的情況，如果沒有輸血，恐怕會有生命危險，但其父母親仍然堅持不能輸血。此時賴醫師應該如何處理？","options":["(A) 不幫蔡小弟弟輸血，因為賴醫師已經充分解釋輸血以及代用血漿的差異，其父母親仍然堅持使用代用血漿時，應該充分尊重蔡小弟弟父母的決定","(B) 不幫蔡小弟弟輸血，因為蔡小弟弟未成年，而其父母親為其法定代理人，應該尊重蔡小弟弟父母的決定","(C) 幫蔡小弟弟輸血，因為蔡小弟弟的血壓已經開始下降，為了搶救其生命，毋需與父母溝通","(D) 幫蔡小弟弟輸血，因為蔡小弟弟父母親的決定，違反蔡小弟弟的最佳利益構成法定代理權之濫用，所以不應採納"],"answer":3,"image":""},{"id":"md5-108-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"108年第2次第79題","year":108,"session":2,"number":79,"question":"一位35歲的病人接受子宮肌瘤切除手術，術後6週回診時發現骨盆腔膿瘍而再次手術，取出一塊大紗布，術後醫師的處理方式，下列那一個的方式是最不適當的？","options":["(A) 要求開刀房的護理長負起責任","(B) 主動通報院內病人安全委員會","(C) 誠懇與病人討論當時開刀的實況","(D) 爭取減免第2次手術的費用"],"answer":0,"image":""},{"id":"md5-108-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"108年第2次第80題","year":108,"session":2,"number":80,"question":"陳醫師是一位很有名的骨科醫師，因龐大的病人服務量，陳醫師得到很高的薪水，並為醫院創造很可觀的業績。王醫師是陳醫師的同事，發現陳醫師為創造業績不擇手段的事證，執行沒有適應症的手術。但因為陳醫師對待病人非常親切，在勸病人接受手術上非常有說服力，而且沒有醫療糾紛；王醫師與陳醫師談過後，並未見其改善。此時王醫師如何處理最適當？","options":["(A) 置之不理","(B) 私下向媒體舉發","(C) 攜帶相關資料向主管（主任、倫理委員會）檢舉","(D) 再找其他同事與陳醫師談"],"answer":2,"image":""},{"id":"md5-109-1-1","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"下列何者屬於Class II major histocompatibility complex（MHC）molecules？","options":["(A) HLA-A","(B) HLA-B","(C) HLA-C","(D) HLA-DR"],"answer":3,"image":""},{"id":"md5-109-1-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"手術部位感染（surgical site infection）與手術時傷口分級息息相關。當病患無其他內科史或合併症，且手術傷口屬於第四級，其手術傷口應如何處置才正確？","options":["(A) 直接縫合","(B) 大量食鹽水清洗傷口後，直接縫合","(C) 給與局部抗生素後，直接縫合","(D) 採延遲縫合或二度縫合（delayed closure or secondary intention closure）"],"answer":3,"image":""},{"id":"md5-109-1-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"下列敘述，何者正確？","options":["(A) 抗生素可以預防尿路感染（urinary tract infection）","(B) 抗生素可以預防中央靜脈導管（central venous catheter）相關的血流感染","(C) 手術前避免在遠離手術部位之處發生感染，可以防止發生手術部位感染（surgical site infections）","(D) 營養不良的病人若在營養風險篩檢時營養不良分數（nutritional risk screening maluntrition score）得到5分，在手術前不需要矯正"],"answer":2,"image":""},{"id":"md5-109-1-4","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"對於腹內壓增加所造成的生理反應，下列何者錯誤？","options":["(A) 腎臟血流減少","(B) 中央靜脈壓力減少","(C) 心跳增加","(D) 肋膜內（intrapleural）壓力增加"],"answer":1,"image":""},{"id":"md5-109-1-5","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"對於腹腔腔室症候群（abdominal compartment syndrome）的敘述，下列何者錯誤？","options":["(A) 腹腔腔室症候群通常發生在多重創傷和加護病房的病患","(B) 放置鼻胃管是間接測量腹內壓的主要方法","(C) 正常的腹內壓大概是5 mmHg，壓力大於12 mmHg會造成呼吸困難，壓力到達25 mmHg會造成下腔靜脈（inferior vena cava）和門靜脈（portal vein）的壓迫","(D) 決定是否開刀的因素除了腹內高壓以外，和腹內高壓相關的器官衰竭也是重要考慮因素"],"answer":1,"image":""},{"id":"md5-109-1-6","subject":"md5","topic":"消化器外科","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"下列何種減重手術術式不是單純的restrictive type surgery？","options":["(A) 可調式胃束帶手術（adjustable gastric banding（AGB））","(B) 縱式胃隔間術（vertical banded gastroplasty（VBG））","(C) 袖狀胃切除術（sleeve gastrectomy（SG））","(D) 膽胰繞道併十二指腸反轉（biliopancreatic diversion（BPD）with duodenal switch（DS））"],"answer":3,"image":""},{"id":"md5-109-1-7","subject":"md5","topic":"神經外科","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"30歲少婦，婚後6年來並無節育計畫，但未曾懷孕，月經時有時無，突然出現頭痛、視力模糊且看東西有黑影，身體檢查發現眼球活動正常，但視野有兩顳側半盲，根據上述發現最有可能的診斷為何？","options":["(A) 顱咽瘤（craniopharyngioma）","(B) 腦下垂體腦瘤出血（pituitary apoplexy）","(C) 矢狀竇旁腦膜瘤（parasagittal meningioma）","(D) 聽神經瘤（acoustic neuroma）"],"answer":1,"image":""},{"id":"md5-109-1-8","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"腰椎椎間盤突出，90%發生在那個地方？","options":["(A) L1-2 and L2-3","(B) L2-3 and L3-4","(C) L3-4 and L4-5","(D) L4-5 and L5-S1"],"answer":3,"image":""},{"id":"md5-109-1-9","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"脊椎轉移性腫瘤中最常轉移的位置為：","options":["(A) 頸椎","(B) 胸椎","(C) 腰椎","(D) 薦椎"],"answer":1,"image":""},{"id":"md5-109-1-10","subject":"md5","topic":"神經外科","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"下列何者不是常見的intradural extramedullary spinal tumor的種類？","options":["(A) meningioma","(B) schwannoma","(C) neurofibroma","(D) anaplastic astrocytoma"],"answer":3,"image":""},{"id":"md5-109-1-11","subject":"md5","topic":"神經外科","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"下列何種處置不建議用來降低腦壓（intracranial pressure）？","options":["(A) 頭抬高30度","(B) 過度換氣（hyperventilation）使二氧化碳分壓（PaCO）降低到20 mmHg 2","(C) 低溫（hypothermia）治療","(D) 腦室引流腦脊髓液（ventricular CSF drainage）"],"answer":1,"image":""},{"id":"md5-109-1-12","subject":"md5","topic":"整形重建外科","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"下列有關skin graft之敘述，何者錯誤？","options":["(A) skin graft的存活需要經過plasmatic circulation、organization and revascularization","(B) 最常見手術失敗的原因是hematoma or seroma accumulation、infection and movement","(C) graft dermis越厚愈會contracture","(D) plasmatic circulation是指在術後48小時內graft直接吸收養分"],"answer":2,"image":""},{"id":"md5-109-1-13","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"關於化學性灼傷（chemical burn），下列敘述何者錯誤？","options":["(A) 所有的化學性灼傷都應該立即除去患處衣物並大量沖水","(B) 嚴重酸性化學灼傷若引起血中酸鹼值異常及呼吸困難，可能需要氣管內插管及使用呼吸機（ventilator）協助呼吸","(C) 氫氟酸（hydrofluoric acid）灼傷應立即以2.5%葡萄糖酸鈣凝膠（calcium gluconate gel）局部患處治療","(D) 水泥灼傷是酸性化學灼傷"],"answer":[0,2,3],"image":"","answer_note":"更正:第13題答Ａ、Ｃ、Ｄ給分。"},{"id":"md5-109-1-14","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"de Quervain disease為那一個手腕背側伸肌腱腔室的狹窄性腱鞘炎？","options":["(A) 第一個","(B) 第二個","(C) 第三個","(D) 第五個"],"answer":0,"image":""},{"id":"md5-109-1-15","subject":"md5","topic":"整形重建外科","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"一位小朋友左眼遭棒球擊中，眼眶部位立即腫大，結膜下出血，左眼球無法向上移動，下列敘述何者錯誤？","options":["(A) 小朋友可能有眼眶下緣骨折（infra-orbital rim fracture）","(B) 小朋友可能有眼眶底部骨折（orbital floor fracture）","(C) 左眼球無法向上移動是因為上直肌卡在眼眶底部骨折","(D) 小朋友需要接受眼眶電腦斷層檢查（orbital CT）"],"answer":2,"image":""},{"id":"md5-109-1-16","subject":"md5","topic":"整形重建外科","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"25歲男性病人因騎機車車禍而顏面部受傷，主要症狀為右側鼻翼撕裂傷（avulsion injury）、流鼻血（epistaxis）和腫痛，送至急診室，下列敘述何者錯誤？","options":["(A) 要高度懷疑可能有鼻骨骨折的發生，可安排X-ray檢查","(B) 經會診耳鼻喉科醫師，發現右側鼻中膈有血腫情形（septal hematoma），應保守治療，待其自行吸收","(C) 鼻部主要組成可分為皮膚覆蓋（skin cover）、結構支撐（structural support）及黏膜內襯（mucosal lining），治療時可以根據缺損的範圍，做不同的重建考量","(D) 鼻唇皮瓣（nasolabial flaps）和前額旁正中皮瓣（paramedian forehead flaps）為鼻部重建時，最常用的兩種局部皮瓣"],"answer":1,"image":""},{"id":"md5-109-1-17","subject":"md5","topic":"整形重建外科","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"有關顯微手術的目的，下列敘述何者錯誤？","options":["(A) 為了轉移遠處的組織（distant tissue）到組織缺損的部位來做重建","(B) 為了修補血管之傷害或缺損（vascular injury or vascular defects）","(C) 可修補周圍神經（peripheral nerves）","(D) 顯微手術通常是用來修補小面積的組織缺損"],"answer":3,"image":""},{"id":"md5-109-1-18","subject":"md5","topic":"心臟血管外科","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"在先天性心臟病的完全矯正，有時需使用帶有瓣膜的同種異體移植物（homograft of pulmonary artery or aorta, valved）來銜接右心室至肺動脈，下列那些先天性心臟病之完全矯正可能需要用到此移植物？①動脈幹症（truncus arteriosus） ②肺靜脈回流完全異常③肺動脈瓣閉鎖合併心室中隔缺損④主動脈窄縮症","options":["(A) ①②","(B) ①③","(C) ②③","(D) ①④"],"answer":1,"image":""},{"id":"md5-109-1-19","subject":"md5","topic":"心臟血管外科","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"一位60歲男性病人因急性心肌梗塞住院。一星期後，病人突然呼吸較喘，流冷汗；身體檢查顯示胸骨左側有新的心縮期雜音、血壓65/50毫米汞柱（mmHg）、肺動脈壓60/40毫米汞柱、中心靜脈壓（CVP）30毫米汞柱，但意識清楚。下列敘述何者錯誤？①診斷為心室中隔破裂②不須裝置主動脈內氣球幫浦③須緊急手術，但若病人書面拒絕手術，則不可強行手術④若病人意識不清楚，也聯絡不到家屬，經初步治療略有改善，則不可立即手術","options":["(A) ①②③","(B) 僅①③","(C) ②④","(D) 僅②"],"answer":3,"image":""},{"id":"md5-109-1-20","subject":"md5","topic":"胸腔外科","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"一個無先天異常或後天重大肺感染疾病的患者，接受肺葉切除手術後，其術後肺功能將受到一定程度的損傷，在無特殊其他肺疾病的情形下，下列那個肺葉切除後對其術後肺功能的影響最小？","options":["(A) 右肺上葉","(B) 右肺中葉","(C) 左肺上葉","(D) 左肺下葉"],"answer":1,"image":""},{"id":"md5-109-1-21","subject":"md5","topic":"胸腔外科","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"對於食道破裂（esophageal perforation）的敘述，下列何者錯誤？","options":["(A) 食道破裂超過一天才被診斷，死亡率常超過50%","(B) 患者頸部及胸部常有皮下氣腫（subcutaneous emphysema）的情形","(C) 手術治療食道破裂是非必要的","(D) 患者常合併膿胸和急性縱膈腔炎"],"answer":2,"image":""},{"id":"md5-109-1-22","subject":"md5","topic":"消化器外科","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"下列有關肝細胞癌（hepatocellular carcinoma）之敘述，何者錯誤？","options":["(A) 肝細胞癌是最常見的原發性肝惡性腫瘤，好發於東南亞與非洲","(B) 肝細胞癌好發於男性，男女比約2 : 1～8 : 1","(C) 約有10%肝細胞癌會產生伴腫瘤症候群（paraneoplastic syndrome），如高血鈣、低血糖與紅血球增生症","(D) 目前已知的治療方式至少包括手術、射頻燒灼（radiofrequency ablation）、酒精注射、經動脈栓塞與標靶治療"],"answer":2,"image":""},{"id":"md5-109-1-23","subject":"md5","topic":"消化器外科","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"幽門螺旋桿菌（Helicobacter pylori）感染是產生胃癌最重要的危險因子。在1994年被國際癌症研究署（IARC）歸類為：","options":["(A) 第一類致癌物質（group I carcinogen）","(B) 第二類致癌物質（group II carcinogen）","(C) 第三類致癌物質（group III carcinogen）","(D) 第四類致癌物質（group IV carcinogen）"],"answer":0,"image":""},{"id":"md5-109-1-24","subject":"md5","topic":"消化器外科","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"病房有一因胃癌接受次全胃切除及Billroth-II reconstruction的病人，開始進食後，抱怨進食20～30分鐘後會有噁心（nausea）、心悸（palpitation）、冒汗及腹瀉等症狀，檢查生命跡象後發覺有心搏過速（tachycardia）的情形，最有可能的診斷為何？","options":["(A) 輸入環症候群（afferent loop syndrome）","(B) 輸出環症候群（efferent loop syndrome）","(C) 傾倒症候群（dumping syndrome）","(D) 急躁性腸道症候群（irritable bowel syndrome）"],"answer":2,"image":""},{"id":"md5-109-1-25","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"吳太太於例行性胃內視鏡健康檢查時發現有1公分大小的胃息肉，下列何者需進行息肉切除？","options":["(A) 切片病理報告為增生性息肉（hyperplastic polyp）","(B) 切片病理報告為腺瘤（adenomatous polyp）","(C) 切片病理報告為缺陷瘤（hamartoma）","(D) 切片病理報告為異位瘤（heterotopic polyp）"],"answer":1,"image":""},{"id":"md5-109-1-26","subject":"md5","topic":"消化器外科","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"診斷胃癌最好的方法為何？","options":["(A) 內視鏡","(B) 腹部超音波","(C) 腹部電腦斷層","(D) 上消化道攝影"],"answer":0,"image":""},{"id":"md5-109-1-27","subject":"md5","topic":"消化器外科","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"有關消化性潰瘍手術的適應症，下列何者錯誤？","options":["(A) 藥物治療無效","(B) 潰瘍出血併出血性休克","(C) 幽門螺旋桿菌（Helicobacter pylori）感染","(D) 穿孔"],"answer":2,"image":""},{"id":"md5-109-1-28","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"關於胰島素瘤（insulinoma）之敘述，下列何者錯誤？","options":["(A) 是最常見的胰臟內分泌腫瘤","(B) 大多為惡性的胰臟內分泌腫瘤","(C) 診斷insulinoma重要的臨床症狀是Whipple's triad，包括低血糖的症狀、當時測得的血糖濃度偏低，及給予靜脈注射葡萄糖液可以減輕低血糖的症狀","(D) 定位insulinoma的影像學工具包括有腹部電腦斷層及磁振造影"],"answer":1,"image":""},{"id":"md5-109-1-29","subject":"md5","topic":"消化器外科","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"對於急性胰臟炎（acute pancreatitis）的可能併發症（complications），下列敘述何者錯誤?","options":["(A) 低血容合併急性腎衰竭（hypovolemia with acute renal failure）","(B) 低血氧合併成人呼吸窘迫症（hypoxemia with adult respiratory distress syndrome）","(C) 高鈣血症合併抽搐（hypercalcemia with seizure）","(D) 血管栓塞合併小腸缺血症（vascular thrombosis with ischemic bowel disease）"],"answer":2,"image":""},{"id":"md5-109-1-30","subject":"md5","topic":"消化器外科","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"有關膽囊結石之敘述，何者錯誤？","options":["(A) 長期禁食或使用全靜脈營養治療之病患與膽囊結石之形成有相關性","(B) 膽囊結石可分為色素結石與膽固醇結石兩大類","(C) 膽囊結石的併發症包括急性膽囊炎、膽石性胰臟炎、腸阻塞","(D) 膽石性急性膽囊炎採取以腹腔鏡膽囊切除手術治療為絕對禁忌症"],"answer":3,"image":""},{"id":"md5-109-1-31","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"分化良好甲狀腺癌的手術選擇中，有關甲狀腺全切除術，下列敘述何者錯誤？","options":["(A) 能減少副甲狀腺功能低下及喉返神經受傷等併發症","(B) 手術後可用甲狀腺球蛋白做為標記追蹤","(C) 可增加手術後碘-131（iodine-131）治療效果","(D) 需終生服用甲狀腺素"],"answer":0,"image":""},{"id":"md5-109-1-32","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"甲狀腺風暴（thyroid storm）不宜給與何種治療？","options":["(A) beta抑制劑（beta blockers）","(B) amiodarone","(C) 腎上腺皮質素（corticosteroids）","(D) propylthiouracil"],"answer":1,"image":""},{"id":"md5-109-1-33","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"下列甲狀腺結節（thyroid nodule）的檢查，應不優先考慮何者？","options":["(A) 超音波及細針穿刺細胞檢查","(B) 胸骨下甲狀腺瘤作CT或MRI","(C) 正子攝影檢查","(D) 甲狀腺核醫掃描（scanning）用於濾泡瘤且甲狀腺刺激素（TSH）低者"],"answer":2,"image":""},{"id":"md5-109-1-34","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"下列何者是乳癌病理組織報告中，做為判斷輔助性化學治療（chemotherapy）的必要因子？①腫瘤大小② 淋巴轉移③位置④荷爾蒙接受器陽陰性","options":["(A) ①②③","(B) ①③④","(C) ①②④","(D) ②③④"],"answer":2,"image":""},{"id":"md5-109-1-35","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"婦人在乳房摸到一腫塊，下列敘述何者錯誤？","options":["(A) 皮膚凹陷（skin dimpling）較腫瘤硬度對乳癌的陽性預測值高","(B) 若無皮膚凹陷（skin dimpling），即可排除乳癌可能","(C) 若腋下摸到淋巴結則乳癌可能性增高","(D) 皮膚凹陷（skin dimpling）的發生與Cooper’s ligament有關"],"answer":1,"image":""},{"id":"md5-109-1-36","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"腋下淋巴結廓清時，若遭切斷，會造成上臂內側麻木或疼痛的神經為何？","options":["(A) long thoracic nerve","(B) thoracodorsal nerve","(C) intercostobrachial nerve","(D) medial pectoral nerve"],"answer":2,"image":""},{"id":"md5-109-1-37","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"45歲女性，乳房摸到腫塊，下列處置何者較恰當？","options":["(A) 理學檢查若正常，不需其他檢查，安排半年再追蹤","(B) 不需其他檢查，即刻安排手術切除切片","(C) 先安排乳房超音波檢查","(D) 抽血檢驗CA15-3"],"answer":2,"image":""},{"id":"md5-109-1-38","subject":"md5","topic":"小兒外科","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"一名剛出生的男嬰，其腹部X光的影像顯示有double-bubble sign，最可能的診斷為何？","options":["(A) 幽門狹窄（pyloric stenosis）","(B) 十二指腸閉鎖（duodenal atresia）","(C) 小腸閉鎖（intestinal atresia）","(D) 肛門閉鎖（imperforate anus）"],"answer":1,"image":""},{"id":"md5-109-1-39","subject":"md5","topic":"小兒外科","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"新生兒出生後數小時被發現吐出泡沫唾液且上腹部有微脹的現象，下列何項診斷最有可能？","options":["(A) 十二指腸閉鎖（duodenal atresia）","(B) 食道閉鎖合併遠端氣管食道瘻管（esophageal atresia with distal tracheoesophageal fistula）","(C) 中腸扭結（midgut volvulus）","(D) 橫膈膜疝氣（diaphragmatic hernia）"],"answer":1,"image":""},{"id":"md5-109-1-40","subject":"md5","topic":"小兒外科","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"新生兒畸胎瘤(teratoma)最好發的部位在下列何處?","options":["(A) 睪丸（testis）","(B) 卵巢（ovary）","(C) 縱隔腔部（mediastinal region）","(D) 薦尾椎部（sacrococcygeal region）"],"answer":3,"image":""},{"id":"md5-109-1-41","subject":"md5","topic":"小兒外科","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"關於兒童腸套疊（intussusception）的敘述，下列何者錯誤？","options":["(A) 好發的年齡為三個月到兩歲","(B) 大多數病人都需要手術治療","(C) 好發部位在迴腸盲腸部（ileocecal region）","(D) 若診斷時已有腹膜炎的現象，則以手術治療較為恰當"],"answer":1,"image":""},{"id":"md5-109-1-42","subject":"md5","topic":"小兒外科","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"有關早產兒壞死性腸炎（necrotizing enterocolitis），下列的處置方式何者錯誤？","options":["(A) 馬上禁食且行口胃管（orogastric tube）減壓","(B) 需使用廣效性抗生素","(C) 所有病患均需接受手術治療","(D) 需補充水分及電解質"],"answer":2,"image":""},{"id":"md5-109-1-43","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"下列關於發炎性腸疾（inflammatory bowel disease）的敘述，何者錯誤？","options":["(A) 相較於北歐及美國，亞洲地區的發生率較高","(B) 潰瘍性結腸炎（ulcerative colitis）的發炎浸潤多在黏膜層及黏膜下層，持續發炎的結果會造成纖維化；在長期持續發炎的病例，黏膜也可能發生惡性病變","(C) 克隆氏症（Crohn’s disease）為一慢性、全壁式（transmural）的發炎性疾病，可侵犯由口至肛門的任何部位","(D) 發炎性腸疾患者還可以併發其他的病症，主要包括虹膜炎、鞏膜炎、關節炎、皮膚病變、膽管及膽管周圍炎等"],"answer":0,"image":""},{"id":"md5-109-1-44","subject":"md5","topic":"消化器外科","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"24歲男子噁心及肚臍周圍不適隨後感到右下腹痛而至急診求診，腹部X-ray如圖所示，下列何者為較可能的診斷？","options":["(A) 急性膽囊炎","(B) 急性闌尾炎","(C) 乙狀結腸憩室炎","(D) 消化性潰瘍"],"answer":1,"image":"md5-109-1-44.jpeg"},{"id":"md5-109-1-45","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"直腸癌接受total mesorectal excision之治療不會有下列那一項結果？","options":["(A) 性無能的發生機率會增高","(B) 病患長期預後較佳","(C) 局部復發率會減少","(D) 膀胱功能異常會減少"],"answer":0,"image":""},{"id":"md5-109-1-46","subject":"md5","topic":"神經外科","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"下列關於intramedullary spinal cord tumor的敘述，何者錯誤？","options":["(A) intramedullary spinal cord tumor約占所有spinal tumor的5%","(B) primary intramedullary spinal cord lymphoma相當罕見","(C) 最常見的intramedullary spinal cord tumor為轉移性腫瘤","(D) 黏液乳突狀室管膜瘤（myxopapillary ependymoma）較常長在腰椎處"],"answer":2,"image":""},{"id":"md5-109-1-47","subject":"md5","topic":"心臟血管外科","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"下列病人何者不適合做心臟移植？","options":["(A) 嚴重且反覆的心臟衰竭症狀，且左心室射出率（ejection fraction, LVEF）<20%","(B) 嚴重心肌缺血無法以傳統冠狀動脈繞道手術治療者","(C) 心臟衰竭已使用葉克膜（ECMO）等心臟輔助器，且無法斷離者","(D) 複雜的先天性心臟病，可以用傳統手術矯正者"],"answer":3,"image":""},{"id":"md5-109-1-48","subject":"md5","topic":"消化器外科","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"下列那一個構造不是triangle of Calot的邊界？","options":["(A) 右肝下緣","(B) 總肝管（common hepatic duct）","(C) 膽囊管（cystic duct）","(D) 右門靜脈（right portal vein）"],"answer":3,"image":""},{"id":"md5-109-1-49","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"一位洗腎病人血液中的鉀離子6.2 mmol/L，心電圖中會觀察到下列何種現象？","options":["(A) tall T-waves","(B) depressed T-waves and U-waves","(C) ST-T elevation","(D) QRS shortening"],"answer":0,"image":""},{"id":"md5-109-1-50","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"承上題，對於急性高鉀血症的處置，下列何者效果最慢？","options":["(A) 靜脈注射50 mL的D50W和10 units的短效胰島素（regular insulin），並嚴密監測血糖","(B) 靜脈注射10 mL的10%氯化鈣（calcium chloride）或是10 mL的10%葡萄糖酸鈣（calcium gluconate）","(C) 靜脈注射50～100 mEq的碳酸氫鈉（sodium bicarbonate）","(D) 給與腸胃道的potassium-binding resins"],"answer":3,"image":""},{"id":"md5-109-1-51","subject":"md5","topic":"小兒外科","meta":"109年第1次第51題","year":109,"session":1,"number":51,"question":"一個4個月大的女嬰，母親是高齡產婦，女嬰出生時並無發紺現象，出生體重2500 gm，一個月後嬰兒呈現呼吸急促，食慾不佳，有盜汗現象，經醫師檢查，呼吸及心跳速率皆增加，胸骨左側可聽到心縮期雜音，肝臟也有腫大現象。心臟超音波檢查發現有左至右的分流，肺動脈壓增高，經投予藥物治療數星期之後，臨床症狀改善有限，且體重只有3500 gm，醫師建議手術治療。請依此回答下列3題：下列那些手術方式對此病患有幫助？①Blalock-Taussig分流手術 ②完全矯正（total correction）③肺動脈環縮術（PA banding）④肺動脈瓣切開術","options":["(A) ①②","(B) ②③","(C) ①④","(D) ①③"],"answer":1,"image":""},{"id":"md5-109-1-52","subject":"md5","topic":"心臟血管外科","meta":"109年第1次第52題","year":109,"session":1,"number":52,"question":"若病人沒有接受手術。數年之後，病人呈發紺現象，經超音波檢查發現有右至左的分流現象，會造成此現象主要的原因為何？","options":["(A) 肺動脈血管壁硬化，使肺動脈血管阻力增加","(B) 心室中隔缺損變小，肺動脈血流減少","(C) 肺靜脈血管開口變狹窄，使肺動脈血管阻力增加","(D) 三尖瓣逆流，使肺動脈血流減少"],"answer":0,"image":""},{"id":"md5-109-1-53","subject":"md5","topic":"心臟血管外科","meta":"109年第1次第53題","year":109,"session":1,"number":53,"question":"病人父母問目前若無接受手術治療，未來可能須進行何種手術治療？","options":["(A) 心室中隔缺損擴大術","(B) 心肺移植術","(C) 三尖瓣置換術","(D) 肺靜脈血管氣球擴張術"],"answer":1,"image":""},{"id":"md5-109-1-54","subject":"md5","topic":"胸腔外科","meta":"109年第1次第54題","year":109,"session":1,"number":54,"question":"關於胸腔出口症候群（thoracic outlet syndrome）的敘述，下列何者錯誤？","options":["(A) 多由鎖骨下血管或此區臂神經叢受壓迫而引起","(B) 症狀多由神經壓迫引起","(C) 中年男性病患較多","(D) 治療可先採保守非手術方法"],"answer":2,"image":""},{"id":"md5-109-1-55","subject":"md5","topic":"胸腔外科","meta":"109年第1次第55題","year":109,"session":1,"number":55,"question":"承上題，下列何者不是檢查胸腔出口症候群的方法？","options":["(A) Adson（scalene）test","(B) Halsted（costoclavicular）test","(C) Wright（hyperabduction）test","(D) Breath test"],"answer":3,"image":""},{"id":"md5-109-1-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第1次第56題","year":109,"session":1,"number":56,"question":"有關骨生成（bone-forming）腫瘤之敘述，下列何者最正確？","options":["(A) 診斷骨肉瘤（osteosarcoma）時，有部分病患同時會被診斷出肺轉移","(B) 骨軟骨瘤（osteochondroma）因有惡性變化的可能，故均須接受手術切除","(C) 骨母細胞瘤（osteoblastoma）引起的疼痛可藉藥物緩解，因此不須手術","(D) 骨樣骨瘤（osteoid osteoma）好發於關節及長骨骨骺（epiphysis）"],"answer":0,"image":""},{"id":"md5-109-1-57","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第1次第57題","year":109,"session":1,"number":57,"question":"一位36歲男性，在車禍中造成頸部疼痛及雙側四肢無力、感覺異常，電腦斷層影像檢查之軸向影像（axial images）顯示在第六、七頸椎處出現雙腔影像（double-lumen sign）。依照此檢查結果，下列何者是第六、七頸椎的最適當診斷？","options":["(A) 壓迫性骨折（compression fracture）","(B) 爆裂性骨折（burst fracture）","(C) 小面關節骨折（facet fracture）","(D) 脫位（dislocation）"],"answer":3,"image":""},{"id":"md5-109-1-58","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"109年第1次第58題","year":109,"session":1,"number":58,"question":"20歲的張同學騎機車時，正面撞擊停在路邊的車子，結果右膝撞擊機車的前檔板。當天該膝關節並未明顯腫脹，急診室拍的X光片也顯示沒有骨折；雖然膝關節活動有些疼痛，但是大致上還能行走。一個月後，右膝已經幾乎不再疼痛，不過他發現走路時右膝有時會有瞬間無法支撐體重、忽然軟弱無力的感覺；尤其走下樓梯時最為困擾，他很害怕會從樓梯上滾下來。張同學最有可能發生了：","options":["(A) 前十字韌帶（anterior cruciate ligament）斷裂","(B) 後十字韌帶（posterior cruciate ligament）斷裂","(C) 髕骨半脫位（patellar subluxation）","(D) 內側副韌帶（medial collateral ligament）斷裂"],"answer":1,"image":""},{"id":"md5-109-1-59","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第1次第59題","year":109,"session":1,"number":59,"question":"橈骨近端（proximal radius）靠近肘關節附近，例如橈骨頸發生骨折時，最可能合併那一條神經的傷害？","options":["(A) 前骨間神經（anterior interosseous nerve）","(B) 後骨間神經（posterior interosseous nerve）","(C) 尺神經（ulnar nerve）","(D) 淺橈神經（superficial radial nerve）"],"answer":1,"image":""},{"id":"md5-109-1-60","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"109年第1次第60題","year":109,"session":1,"number":60,"question":"一位55歲的女性，有肺癌病史。兩天前突然發生背痛，但生命跡象穩定，大小便功能及四肢神經功能正常。脊椎X光及磁振造影檢查結果疑似第二腰椎轉移性腫瘤，但無明顯神經壓迫。下列敘述何者錯誤？","options":["(A) 可以安排骨骼同位素掃描（bone scan）檢查，幫忙診斷是否有其他骨骼部位的轉移","(B) 可以安排電腦斷層導引活體組織切片檢查（CT-guided biopsy），幫忙確定是否為腫瘤轉移","(C) 若確定是轉移性腫瘤，應建議患者馬上接受脊椎固定、椎板切除神經減壓手術，來治療其背痛及預防神經壓迫受損","(D) 轉移性脊椎腫瘤的手術目的，主要是改善患者疼痛及生活品質，對其原發腫瘤的病情控制及存活時間，並無太大直接影響"],"answer":2,"image":""},{"id":"md5-109-1-61","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"109年第1次第61題","year":109,"session":1,"number":61,"question":"一位30歲男性搭乘計程車前座，發生車禍後送至急診，身體檢查時左下肢呈現肢體變短，左髖關節屈曲、內收及內旋轉的外觀，最有可能之初步診斷為何？","options":["(A) 髖關節前位脫臼","(B) 髖關節後位脫臼","(C) 股骨頸骨折","(D) 股骨轉子間骨折"],"answer":1,"image":""},{"id":"md5-109-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第1次第62題","year":109,"session":1,"number":62,"question":"根據Catterall的研究認為，兒童的股骨頭部缺血性壞死症（Legg- Calvé -Perthes disease）預後不好的徵象中，下列何者除外？","options":["(A) 在股骨頭部的外側X光通過性增加（radiolucency in lateral femoral head）","(B) 股骨頭部的生長板呈水平向（horizontal growth plate）","(C) 發病時的年紀較輕（小於5歲）","(D) 股骨頭部的壞死範圍達80%"],"answer":2,"image":""},{"id":"md5-109-1-63","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"109年第1次第63題","year":109,"session":1,"number":63,"question":"有關痛風（gout）的敘述，下列何者正確？","options":["(A) 在急性發作時，血清中尿酸（uric acid）值一定增高","(B) 急性發作時，使用非類固醇消炎藥（NSAIDs）或秋水仙素（colchicine）治療","(C) 長期高尿酸血症的患者，常可見到半月軟骨（meniscus）發生軟骨鈣質沉著病（chondrocalcinosis）","(D) 偏光顯微鏡（polarized light microscope）檢查關節液，可見到陽性雙折射（positively birefringent）特性的針狀結晶體"],"answer":1,"image":""},{"id":"md5-109-1-64","subject":"md5","topic":"泌尿-結石與感染","meta":"109年第1次第64題","year":109,"session":1,"number":64,"question":"形成含鈣腎結石（calcium nephrolithiasis）最常見的原因有那些？①尿中鈣離子濃度增加②尿中尿酸濃度上升③尿中草酸鹽（oxalate）濃度上升④尿中檸檬酸鹽（citrate）濃度上升","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":0,"image":""},{"id":"md5-109-1-65","subject":"md5","topic":"泌尿-腫瘤","meta":"109年第1次第65題","year":109,"session":1,"number":65,"question":"下列有關腎上腺腫瘤之敘述，何者錯誤？","options":["(A) 具有功能或大於五公分之腎上腺腫瘤均應手術切除","(B) 利用腹腔鏡方式切除是目前較好的處理方法，術後疼痛少且恢復迅速","(C) 目前腎上腺腫瘤大部份是因其他原因實施影像檢查時意外發現","(D) 腎上腺腫瘤經檢查如果發現其不具功能，就不需手術切除"],"answer":3,"image":""},{"id":"md5-109-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"109年第1次第66題","year":109,"session":1,"number":66,"question":"有關睪丸腫瘤之敘述，下列何者錯誤？","options":["(A) 睪丸惡性腫瘤最常見者為germ cell tumor","(B) 續發性睪丸惡性腫瘤最常見為lymphoma","(C) α-胎兒蛋白（AFP）於pure seminoma不會升高","(D) 早期seminoma之治療以化療為主"],"answer":3,"image":""},{"id":"md5-109-1-67","subject":"md5","topic":"泌尿-腫瘤","meta":"109年第1次第67題","year":109,"session":1,"number":67,"question":"最常轉移到膀胱之癌症為：","options":["(A) 黑色素瘤","(B) 淋巴瘤","(C) 胃癌","(D) 乳癌"],"answer":0,"image":""},{"id":"md5-109-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"109年第1次第68題","year":109,"session":1,"number":68,"question":"下列何者不會造成flaccid neuropathic bladder？","options":["(A) S2-S4 spinal cord受傷","(B) 頸椎受傷（cervical spine injury）且有quadriplegia","(C) Myelodysplasia造成anterior horn cell無法正常發育","(D) Poliovirus感染並破壞anterior horn cell of spinal cord"],"answer":1,"image":""},{"id":"md5-109-1-69","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"109年第1次第69題","year":109,"session":1,"number":69,"question":"有關間質性膀胱炎（interstitial cystitis）之敘述，下列何者錯誤？","options":["(A) 通常發生於40歲以上的女性","(B) 通常病人的尿液常規檢查會出現血尿及膿尿","(C) 常見的症狀是頻尿、夜尿、急尿、及恥骨上疼痛","(D) 症狀通常是在膀胱脹尿時引起，因此膀胱容積逐漸縮小，病人變得相當頻尿"],"answer":1,"image":""},{"id":"md5-109-1-70","subject":"md5","topic":"泌尿-結石與感染","meta":"109年第1次第70題","year":109,"session":1,"number":70,"question":"有關反覆性尿路感染的敘述，下列何者正確？","options":["(A) 反覆性尿路感染的女孩，一定會有尿路系統解剖學上的異常","(B) 反覆性尿路感染的女孩，常會有憋尿、少喝水的習慣以及便秘","(C) 如果沒有發燒症狀，尿路感染並不需要治療","(D) 膀胱輸尿管尿液逆流，並不是造成反覆性尿路感染的原因"],"answer":1,"image":""},{"id":"md5-109-1-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"109年第1次第71題","year":109,"session":1,"number":71,"question":"一位50歲男性前列腺癌病人接受前列腺根除手術，術後無法勃起，最可能受損的神經是：","options":["(A) 骨盆腔神經叢（pelvic plexus）","(B) 海綿體神經（cavernous nerve）","(C) 陰部神經（pudendal nerve）","(D) 腹下神經（hypogastric nerve）"],"answer":1,"image":""},{"id":"md5-109-1-72","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第1次第72題","year":109,"session":1,"number":72,"question":"58歲女性已切除子宮及卵巢，另患有骨盆腔惡性肉瘤，並接受手術及放射治療，主訴最近下背痛，X光及核醫骨掃描如附圖，最可能的診斷為何？","options":["(A) bone metastasis","(B) insufficiency fracture","(C) local tumor recurrence","(D) degenerative spine disease"],"answer":1,"image":"md5-109-1-72.jpeg"},{"id":"md5-109-1-73","subject":"md5","topic":"泌尿-結石與感染","meta":"109年第1次第73題","year":109,"session":1,"number":73,"question":"33歲男性因陣發性腹痛而求醫，患者體溫正常、生命徵象穩定，患者接受對比劑注射前（pre-contrast）的電腦斷層掃描檢查如圖，下列診斷何者最恰當？","options":["(A) 急性盲腸炎","(B) 腸胃炎","(C) 腎結石","(D) 膽囊炎"],"answer":2,"image":"md5-109-1-73.jpeg"},{"id":"md5-109-1-74","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第1次第74題","year":109,"session":1,"number":74,"question":"13歲男國中生最近覺得右腳膝蓋附近偶爾隱隱作痛，且疼痛的時間越來越長，晚上睡覺時症狀也很明顯，附圖為下肢X光攝影，最可能的診斷為何？","options":["(A) fibrous dysplasia","(B) aneurysmal bone cyst","(C) osteogenic sarcoma","(D) eosinophilic granuloma"],"answer":2,"image":"md5-109-1-74.jpeg"},{"id":"md5-109-1-75","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"109年第1次第75題","year":109,"session":1,"number":75,"question":"65歲男性看門診，主訴三天前大便有血絲，醫師做肛診檢查未發現有血跡，下列有關醫師的說法何者最適當？","options":["(A) 下消化道出血比上消化道出血具有生命危險性","(B) 年紀大不是上消化道出血的危險因子","(C) 大多數急性消化道出血不會自動停止流血","(D) 下消化道出血可能來自空腸（jejunum）"],"answer":3,"image":""},{"id":"md5-109-1-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第1次第76題","year":109,"session":1,"number":76,"question":"腹部受傷機轉不同，可能有不同器官傷害，且受傷頻率不一，路人甲發生車禍造成腹部鈍傷（blunt injury）和路人乙腹部遭受槍擊傷（gunshot injury）時，他們最常受傷的器官分別是：","options":["(A) 鈍傷時為脾臟；槍擊傷時是肝臟","(B) 鈍傷時為肝臟；槍擊傷時是脾臟","(C) 鈍傷時為脾臟；槍擊傷時是小腸","(D) 鈍傷時為小腸；槍擊傷時是胰臟"],"answer":2,"image":""},{"id":"md5-109-1-77","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第1次第77題","year":109,"session":1,"number":77,"question":"下列那一項檢查對腹部鈍傷最具特異性（specificity）？","options":["(A) 腹部X光","(B) 腹部超音波","(C) 診斷性腹腔灌洗法","(D) 腹部電腦斷層掃描"],"answer":3,"image":""},{"id":"md5-109-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"109年第1次第78題","year":109,"session":1,"number":78,"question":"某醫院最近引進一家不同廠商的外科耗材，但在不到3個月便把這項耗材剔除，原因是醫院發現，該耗材用量異常增加，因為廠商私下付給使用該耗材的醫師每件500元。下列何者非為本案例中可能涉及的倫理議題？","options":["(A) 損及醫病互信","(B) 違反病人隱私","(C) 造成醫療資源浪費","(D) 存有利益衝突"],"answer":1,"image":""},{"id":"md5-109-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"109年第1次第79題","year":109,"session":1,"number":79,"question":"簡先生是一位30歲的男性，曾經做過警衛，但目前是自由業。3年前因缺血性腸炎接受大量小腸切除，術後因為短腸症裝了希克曼氏導管長期接受全靜脈營養。對於日復一日照顧導管接點滴的工作及長年來無法正常進食感到非常厭煩。這次因為發燒，導管相關血液感染住院，最近幾天病患曾多次告訴照顧他的醫師，經過長時間的思考，他不想再活下去，他要停止目前的治療並拒絕繼續接受全靜脈營養。他說若不能正常由口進食，病患的生命就沒有任何意義，同時他已經與家人討論過這件事，他的家人雖然於心不忍，但卻似乎已經接受且同意他的想法；下列何種作法最不適當？","options":["(A) 尊重簡先生的意願，不繼續給予全靜脈營養","(B) 會診精神科評估病人的心智並且探究原因","(C) 為避免病人死亡，不論如何需繼續治療","(D) 和病人討論各種治療之選項，尊重他的選擇"],"answer":2,"image":""},{"id":"md5-109-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"109年第1次第80題","year":109,"session":1,"number":80,"question":"34歲的葉小姐是位老師，身體健康無特殊病史，近日因為右側鼠蹊部腫脹來門診，經診斷為腹股溝疝氣，醫師向葉小姐建議進行疝氣修補術治療，在解釋病情及手術細節後，葉小姐卻要求術後要補充白蛋白，因為她聽說白蛋白對腹部手術術後恢復有幫助，但醫師的專業判斷認為並不需要，此情境下，如何處理較適當？","options":["(A) 經過專業判斷不需要補充白蛋白，與病人多溝通後婉拒病人的要求，不給與術後白蛋白補充","(B) 答應病人補充白蛋白，且以健保支付","(C) 即使判斷補充白蛋白不是恰當的醫療處置，但是病人要求了，補充之也無傷大雅","(D) 補充白蛋白是醫療專業判斷，由醫師決定即可，不需再與病人溝通"],"answer":0,"image":""},{"id":"md5-109-2-1","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"下列有關零期乳癌（carcinoma in situ）的敘述，何者錯誤？","options":["(A) 常伴隨有顯微鈣化（microcalcifications）","(B) 較易有多發性病兆（multifocal lesions）","(C) 手術治療包含level II腋下淋巴廓清（axillary lymph node dissection up to level II）","(D) 手術切除後不需化學藥物治療"],"answer":2,"image":""},{"id":"md5-109-2-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"頸部穿刺傷（Neck Penetrating Injury）是一項會致命的傷害，下列對於Zones of The Neck敘述，何者錯誤？","options":["(A) The most accessible surgical zone是Zone II","(B) Zone II範圍從cricoid cartilage往上至the angle of mandible","(C) Zone I範圍從the angle of mandible至skull base","(D) Zone III範圍包含大血管，不容易以手術方式進去處理"],"answer":2,"image":""},{"id":"md5-109-2-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"病患手術前有使用vitamin K antagonist（VKA），例如warfarin，會增加手術中出血的機會；一般在elective surgery前，建議先停藥5天以上，讓international normalized ratio（INR）上限低於多少以下，再進行手術？","options":["(A) 2.0","(B) 1.8","(C) 1.5","(D) 1.2"],"answer":2,"image":""},{"id":"md5-109-2-4","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"大量出血或休克的病患，容易造成所謂lethal triad，下列何者不屬於lethal triad？","options":["(A) arrhythmia","(B) acidosis","(C) hypothermia","(D) coagulopathy"],"answer":0,"image":""},{"id":"md5-109-2-5","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"surgical site infection（SSI）是術後常見的合併症，對於傷口的分類及其SSI的發生率敘述，下列何者錯誤？","options":["(A) clean wound: no hollow viscus entered, primary wound closure; SSI發生率：0.1～0.3%","(B) clean-contaminated wound: hollow viscus entered but controlled; SSI發生率：5～8%","(C) contaminated wound: uncontrolled spillage from viscus; SSI發生率：20～25%","(D) dirty wound: untreated, uncontrolled spillage from viscus; SSI發生率：30～40%"],"answer":0,"image":""},{"id":"md5-109-2-6","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"有關傷口癒合過程的敘述，下列何者錯誤？","options":["(A) 組織受傷後首先進入發炎期（inflammatory phase），在此時期因血小板凝集後產生血管擴張物質，而導致血管管壁滲透力增加，增加血漿滲入細胞外組織，同時產生趨化因子（chemokine），使得發炎細胞如中性白血球移往受傷組織","(B) 於增生期（proliferative phase）時，大部分的纖維母細胞（fibroblast）會經由巨噬細胞產生的趨化作用，自受傷處以外的組織隨血液循環運送至受傷部位，並於受傷組織中合成膠原蛋白（collagen）","(C) 肌纖維母細胞（myofibroblast）於組織受傷後約6天形成，主要功能為分泌 α-平滑肌肌動蛋白（α-smooth muscle actin）並形成應力纖維（stress fiber），於成熟期（maturation phase）負責傷口攣縮現象","(D) 於傷口癒合過程中發生的基質（matrix）合成，第三型膠原蛋白較第一型膠原蛋白較早形成"],"answer":1,"image":""},{"id":"md5-109-2-7","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"根據流行病學之研究，吸菸與下列何種癌症無關？","options":["(A) 膀胱癌","(B) 食道癌","(C) 胰臟癌","(D) 大腸癌"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第7題一律給分 (原公告答案 D)"},{"id":"md5-109-2-8","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"關於開腹手術後，引流管中消化液流失的相關注意事項，下列何者錯誤？","options":["(A) 胃液每天分泌約達1,000～2,000毫升，大量流失可能引起鉀離子缺乏","(B) 腸液為每天分泌最多之消化液，大量流失可能造成酸血症","(C) - 膽汁每天分泌約達300～800毫升，其中的碳酸氫離子（HCO3）濃度比腸液、胰液還高","(D) 胰液呈透明狀，為鹼性消化液，每天分泌約達600～800毫升"],"answer":2,"image":""},{"id":"md5-109-2-9","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"器官移植病人通常需要長期使用抗排斥藥物，下列關於抗排斥藥物敘述何者正確？","options":["(A) cyclosporin跟tacrolimus不同之處，主要是cyclosporin會抑制IL-2合成，而tacrolimus不會","(B) 器官急性排斥時，以前主要使用藥物為類固醇，目前已經很少用","(C) 使用cyclosporin時，和葡萄柚汁會有交互作用，此時可以考慮改成tacrolimus","(D) cyclosporin以及FK-506均具有腎毒性"],"answer":3,"image":""},{"id":"md5-109-2-10","subject":"md5","topic":"神經外科","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"下列對於意識不清之頭部外傷患者的處置何者錯誤？","options":["(A) 評估意識狀況（GCS）、瞳孔大小及對光反射","(B) 評估生命徵象及有無其他associated injury","(C) 在生命徵象穩定後安排頭部電腦斷層檢查有無顱內出血","(D) 應先給與低劑量抗癲癇藥（therapeutic trial of anticonvulsant agents），24小時後再停藥"],"answer":3,"image":""},{"id":"md5-109-2-11","subject":"md5","topic":"神經外科","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"下列關於脈絡叢乳突狀瘤（choroid plexus papilloma）之敘述，何者錯誤？","options":["(A) 可發生於小孩及成人","(B) 嬰兒期發生率較高","(C) 在成人脈絡叢乳突狀瘤最常發生在側腦室（lateral ventricle）","(D) 若脈絡叢乳突狀瘤長在側腦室，可能造成軀體半癱（hemiparesis）"],"answer":2,"image":""},{"id":"md5-109-2-12","subject":"md5","topic":"神經外科","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"小腦扁桃體下垂5mm至頸椎脊椎腔且合併有脊髓空洞症（syringomyelia），但沒有合併脊柱裂（spinal bifida）或水腦（hydrocephalus），應該歸屬下列何種異常？","options":["(A) Chiari I malformation","(B) Chiari II malformation","(C) Dandy-Walker syndrome","(D) myelomeningocele"],"answer":0,"image":""},{"id":"md5-109-2-13","subject":"md5","topic":"神經外科","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"關於腦膿瘍的敘述，下列何者正確？","options":["(A) 通常成因為細菌經由血液循環進入腦內而產生","(B) 最好發族群是老年人","(C) 若神經學症狀在數小時內急遽惡化，最可能是膿瘍破至腦室或蜘蛛膜下腔位置","(D) 影像上最常表現出額葉腦表面的cystic lesion with contrast enhancement"],"answer":2,"image":""},{"id":"md5-109-2-14","subject":"md5","topic":"神經外科","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"藥物無法有效控制之癲癇，經檢查顯示腦部不正常放電點可能在右側顳葉，則下列何項手術之治癒率最高？","options":["(A) anterior temporal lobectomy","(B) multiple subpial resection","(C) corpus callosotomy","(D) vagus nerve stimulation"],"answer":0,"image":""},{"id":"md5-109-2-15","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"病人前臂有刺傷，並發現有後骨間神經受損（posterior interosseous nerve injury）時，下列何者不會產生肌肉無力？","options":["(A) 外展拇長肌（abductor pollicis longus）","(B) 橈側伸腕長肌（extensor carpi radialis longus）","(C) 伸拇長肌（extensor pollicis longus）","(D) 伸指肌群（extensor digitorum communis）"],"answer":1,"image":""},{"id":"md5-109-2-16","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"關於糖尿病足（diabetic foot）的敘述，下列何者錯誤？","options":["(A) 糖尿病足併骨髓炎的X-ray特徵，會比臨床症狀晚1週出現","(B) 核磁共振檢查（magnetic resonance imaging, MRI）可以早期診斷骨髓炎","(C) 骨骼掃描（bone scan）對於骨髓炎的診斷有幫忙","(D) 糖尿病足是截肢最常見的原因"],"answer":0,"image":""},{"id":"md5-109-2-17","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"下列何者位於手腕背側第5個伸展區間（extensor compartment）？","options":["(A) 伸食指肌（extensor indicis proprius）","(B) 伸拇指肌（extensor pollicis longus）","(C) 尺腕伸肌（extensor carpi ulnaris）","(D) 小指伸肌（extensor digiti minimi）"],"answer":3,"image":""},{"id":"md5-109-2-18","subject":"md5","topic":"整形重建外科","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"有關身體各部位拆線的時機（timing for suture removal），下列何者最適當？","options":["(A) 頭皮（scalp）：12～14 days","(B) 眼皮（eyelid）：5～7 days","(C) 背部（back）：5～7 days","(D) 手部（hand）：5～7 days"],"answer":1,"image":""},{"id":"md5-109-2-19","subject":"md5","topic":"整形重建外科","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"60歲孫先生因頭皮上快速增生的病灶（如下圖）而求醫，臨床診斷為惡性黑色素細胞瘤（malignant melanoma）。以下敘述何者正確？","options":["(A) 此病灶之分型屬於結節型黑色素細胞瘤（nodular melanoma）","(B) 此分型可能發生在身上除了手跟腳以外的所有部位皮膚上","(C) 絕不可進行部分病灶切片（incisional biopsy），以免腫瘤擴散","(D) 放射治療與手術有一樣的存活率"],"answer":1,"image":"md5-109-2-19.jpeg"},{"id":"md5-109-2-20","subject":"md5","topic":"整形重建外科","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"有關乳房重建的各種方式中，下列敘述何者錯誤？","options":["(A) 根據統計，義乳重建（implant-based reconstruction）是多數人的選擇","(B) 放射治療容易導致重建乳房的纖維化或脂肪壞死（fat necrosis）","(C) 闊背肌皮瓣（LD flap）對於小乳房是不錯的選擇","(D) 橫式腹直肌肌皮瓣（TRAM flaps）與深下腹穿通支皮瓣（DIEP flaps）都可以得到很好的乳房重建外觀，但是DIEP皮瓣有較高比例會腹部疝氣（hernia）"],"answer":3,"image":""},{"id":"md5-109-2-21","subject":"md5","topic":"心臟血管外科","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"下列開心手術中所使用的體外循環技術（extracorporeal perfusion），何者錯誤？","options":["(A) 在啟動體外循環之前必須施打肝素（heparin）約300～400 units/kg，以使activated clotting time（ACT）能大於450秒","(B) 2在正常的體溫下，一般體循環機必須提供每分鐘每平方公尺2.4升心輸出量（2.4 L/min/m），體溫下降10℃，則體內氧氣消耗量可減少50%左右","(C) 因體外循環技術可以提供心臟外科醫師一個幾近無血乾淨的手術環境，以便能從事各種瓣膜手術、冠狀動脈手術及大血管手術；因此使用體外循環技術時間是沒有限制的","(D) 體外循環技術仍有一些潛在的副作用，會導致病患的凝血機能異常、全身性的發炎反應、或終端器官因大血栓（macroembolism）或小血栓（microembolism）而造成功能不良"],"answer":2,"image":""},{"id":"md5-109-2-22","subject":"md5","topic":"心臟血管外科","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"下列對正常心臟瓣膜外科解剖學之敘述，何者錯誤？","options":["(A) 主動脈瓣膜（aortic valve）及肺動脈瓣膜（pulmonary valve）都是由3片半月型之葉片所組成","(B) 僧帽瓣膜（mitral valve）是由前葉（anterior leaflet）及後葉（posterior leaflet）所組成","(C) 柯克三角地帶（Koch triangle）是在施行三尖瓣膜修補或置換手術必須縫合之處，以減少側漏且不必擔心房室傳導異常","(D) 在接近僧帽瓣膜（mitral valve）後葉之下緣處，有左迴旋冠狀動脈（left circumflex artery）經過"],"answer":2,"image":""},{"id":"md5-109-2-23","subject":"md5","topic":"心臟血管外科","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"主動脈剝離（aortic dissection）DeBakey type II，其剝離侵犯範圍主要是下圖那一部分之主動脈？","options":["(A) I","(B) II","(C) III","(D) IV"],"answer":0,"image":"md5-109-2-23.jpeg"},{"id":"md5-109-2-24","subject":"md5","topic":"心臟血管外科","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"冠狀動脈繞道手術所使用的自體繞道管道（conduit）如下：①內乳動脈 ②大隱靜脈 ③橈動脈，若以10年通暢率相互比較，則下列何者正確？","options":["(A) ①＞③＞②","(B) ②＞①＞③","(C) ②＞③＞①","(D) ③＞②＞①"],"answer":0,"image":""},{"id":"md5-109-2-25","subject":"md5","topic":"心臟血管外科","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"68歲男性因心肌梗塞來急診，呈現休克狀態並經插管緊急處置，聽診時發現有一第四度收縮期雜音（Grade 4/6 systolic murmur），且伴隨有肺水腫（pulmonary edema），經心導管攝影為左前降枝（LAD）90%狹窄，迴旋枝（LCX）有85%狹窄，下列處置何者錯誤？","options":["(A) 應該再進行心臟超音波檢查","(B) 可以考慮放置主動脈幫浦（IABP）","(C) 因病人狀況差，必須使用不停跳冠狀動脈繞道術，以減少合併症之產生","(D) 此情況為ACC/AHA準則之Class I之冠狀動脈繞道術適應症"],"answer":2,"image":""},{"id":"md5-109-2-26","subject":"md5","topic":"心臟血管外科","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"下列對末期性心臟衰竭之治療何者錯誤？","options":["(A) HeartMate II左心室輔助器可以用於移植前之支持（bridge），亦可以做終極置放（destination therapy）","(B) 根據STITCH試驗研究，冠狀動脈繞道術加上左心室成型術（surgical ventricular restoration）相較於單純之冠狀動脈繞道術，可以改善心衰竭病患之症狀及存活率","(C) HeartWare亦是一種左心室輔助器，亦可用於長期之移植前之支持（bridge to transplant）","(D) 全人工心臟（total artificial heart）亦是治療心臟衰竭方法之一，可用於移植前之支持"],"answer":1,"image":""},{"id":"md5-109-2-27","subject":"md5","topic":"胸腔外科","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"下列何種胸壁腫瘤，在血液檢驗中，通常不會有異常發現？","options":["(A) 漿細胞瘤（plasmacytoma）","(B) 骨纖維發育不良（fibrous dysplasia）","(C) 骨肉瘤（osteosarcoma）","(D) Ewing氏肉瘤（Ewing's sarcoma）"],"answer":1,"image":""},{"id":"md5-109-2-28","subject":"md5","topic":"胸腔外科","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"關於縱膈腔生殖細胞性瘤（germ cell tumor）之敘述，下列何者正確？","options":["(A) 縱膈腔生殖細胞性瘤（germ cell tumor）最常發生在65歲以上病人","(B) 有三分之一的病人是精母細胞瘤（seminoma）","(C) 精母細胞瘤（seminoma）在抽血檢驗中，常會有較高的胎兒蛋白（AFP）及人類絨毛膜激素（hCG）","(D) 經皮穿刺抽吸檢驗（FNA）是不須血液檢驗結果，最安全、最快速及最正確得到診斷的方式"],"answer":1,"image":""},{"id":"md5-109-2-29","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"對一體重60公斤的成人而言，關於出血性休克的分期，何者正確？","options":["(A) 第一期小便輸出量：5～15ml/h","(B) 第二期呼吸速率：14～20次/min","(C) 第三期出血量約占全身血量：30%～40%","(D) 第四期心跳速率約100～120次/min"],"answer":2,"image":""},{"id":"md5-109-2-30","subject":"md5","topic":"胸腔外科","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"張力性氣胸（tension pneumothorax）和心包膜填塞症（cardiac tamponade）的理學檢查差別在於何者？","options":["(A) 兩側呼吸聲不一致","(B) 兩側外頸靜脈鼓張不一致","(C) 心音變小","(D) 血壓下降"],"answer":0,"image":""},{"id":"md5-109-2-31","subject":"md5","topic":"胸腔外科","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"有關肺部手術之術前評估，以下何者錯誤？","options":["(A) FEV1小於60% predicted時，可能會增加術後pulmonary morbidity","(B) 在obstructive disease時，FEV1/FVC ratio值會上升","(C) diffusion capacity for CO (DLCO) level小於40～50﹪時，會增加手術之危險性","(D) maximal O2 consumption (VO2 max)小於11～15 mL/kg/min時，會增加手術之morbidity與mortality rate"],"answer":1,"image":""},{"id":"md5-109-2-32","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"下列有關腹內壓力（intra-abdominal pressure）的敘述，何者錯誤？","options":["(A) 不正常的腹內壓力上升會導致腹內器官血液循環減慢並且影響心臟回流壓力，對於呼吸器官的影響則不明顯","(B) 肥胖會讓腹內壓力上升","(C) 腹內高壓（abdominal hypertension）分為4級，第1、2級可以保守治療；第3、4級病患則需要手術介入","(D) 高於25 mmHg易形成腹內腔室症候群（abdominal compartment syndrome），需進行手術減壓"],"answer":0,"image":""},{"id":"md5-109-2-33","subject":"md5","topic":"消化器外科","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"2李先生35歲，BMI（body mass index）: 43kg/m，過去一年努力藉由保守方法減重但效果不彰，本身亦有第二型糖尿病，且糖化血紅素（HbA1C）指數為8.5%，胃鏡檢查發現胃食道逆流程度為Los Angeles Grade C。李先生決定接受代謝減重手術治療，下列何種手術最為適合？","options":["(A) 胃底摺疊術（Nissen fundoplication）","(B) 胃繞道手術（Roux-en-Y gastric bypass）","(C) 垂直胃隔間術（vertical banded gastroplasty）","(D) 迷走神經截斷術（vagotomy）"],"answer":1,"image":""},{"id":"md5-109-2-34","subject":"md5","topic":"消化器外科","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"下列關於早期胃癌（early gastric cancer）的描述，何者錯誤？","options":["(A) 若侵犯至黏膜下層，則不算早期胃癌","(B) 約10%的早期胃癌，已有淋巴轉移","(C) 淋巴結轉移與否，並不在早期胃癌的定義中","(D) 約70%的早期胃癌細胞分化為well differentiated"],"answer":0,"image":""},{"id":"md5-109-2-35","subject":"md5","topic":"消化器外科","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"一位49歲男性B型肝炎帶原者，到門診時意識清楚，其抽血檢查顯示WBC: 4.16 K/μL; ALT: 59 U/L; BIL(T/D): 2.52/0.65 mg/dL; Alb: 4.3 g/dL; ALP: 100 U/L ; Cre: 0.8 mg/dL; α-fetoprotein: 42.2 ng/ml; ICG(15): 46.9%; PT (INR): 12.1 sec (1.12)。電腦斷層顯示一2公分腫瘤在第四小葉（Couinaud segment Ⅳ）下緣，沒有發現腹水。此人的肝功能的Child-Pugh score為幾分？","options":["(A) 5","(B) 6","(C) 7","(D) 8"],"answer":1,"image":""},{"id":"md5-109-2-36","subject":"md5","topic":"消化器外科","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"現今引發肝內細菌性膿瘍最常見的原因是：","options":["(A) 闌尾炎","(B) 上腸繫膜動脈阻塞造成的小腸壞死","(C) 膽道感染","(D) 外傷"],"answer":2,"image":""},{"id":"md5-109-2-37","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"甲狀腺乳突癌合併多處頸部淋巴結及肺部轉移，下列敘述何者正確？","options":["(A) 首選治療為全身性化療，以paclitaxel效果最佳","(B) 預後極差，大部分病人於診斷後一年內死亡","(C) 可給予口服抗甲狀腺藥物methimazole以抑制腫瘤細胞生長","(D) 甲狀腺全切除手術及術後放射性碘（I-131）為治療選項之一"],"answer":3,"image":""},{"id":"md5-109-2-38","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"一位血液透析患者因續發性副甲狀腺功能亢進（secondary hyperparathyroidism）被轉介至外科門診就醫，下列何種情況應建議該患者接受副甲狀腺切除手術？","options":["(A) 22血液鈣磷乘積（calcium-phosphate product）45 mg/dL","(B) 抽血測得副甲狀腺素（parathyroid hormone）200 pg/mL","(C) 抽血測得維生素D 25(OH)D濃度40 nmol/L（相當於16 ng/mL）","(D) 下肢有數處疼痛的缺血性皮膚壞死（calciphylaxis）"],"answer":3,"image":""},{"id":"md5-109-2-39","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"一位50歲高血壓男性接受電腦斷層檢查時，意外發現左腎上腺有一2公分腫瘤，內部均勻、邊界清楚、且為低密度性腫瘤，臨床醫師懷疑為腎上腺腺瘤（adenoma）合併原發性高醛固酮症（primary hyperaldosteronism），下列敘述何者錯誤？","options":["(A) 初步篩檢可測血液中醛固酮／腎素比例（aldosterone-to-renin ratio）","(B) 要確認原發性高醛固酮症診斷，可利用靜脈生理食鹽水輸注（intravenous saline loading）試驗","(C) 要區分是單側腎上腺腺瘤或雙側腎上腺增生，除電腦斷層外，40歲以下患者建議常規接受腎上腺靜脈取樣（adrenal vein sampling）檢查","(D) 如果原發性高醛固酮症的患者手術前有合併低血鉀症，腎上腺切除手術後血鉀會很快恢復正常"],"answer":2,"image":""},{"id":"md5-109-2-40","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"一位44歲未停經婦女，因左側乳房腫塊就診，粗針穿刺確診是infiltrating ductal carcinoma，ER:90%，PR：90%，HER-2(1+)，下列相關敘述何者正確？","options":["(A) 是最常見的乳癌，約占侵襲性乳癌疾病的50%～70%","(B) 最適合的抗荷爾蒙藥物是芳香環抑制劑（aromatase inhibitor）","(C) 術後需要使用標靶藥物，目前臨床試驗顯示雙標靶有益處","(D) 術後病理報告是腫瘤1.2公分，前哨淋巴結無轉移，並無遠端轉移，則術後病理TNM stage是cT1bN0M0"],"answer":0,"image":""},{"id":"md5-109-2-41","subject":"md5","topic":"內分泌與乳房外科","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"一位45歲女性，接受乳癌篩檢後，因右側乳房有異常，接受病灶穿刺病理檢查證實是侵襲性乳癌。有關下一步的治療，下列敘述何者正確？","options":["(A) 接受乳房全切除手術及前哨淋巴結切片術後，若接受立即重建，會降低存活率以及增加患側局部復發率","(B) 選擇乳房全切除手術或是乳房保留手術加上術後乳房放射線治療，兩者的長期存活率並無顯著差異","(C) 若選擇乳房保留手術，為提高存活率，腫瘤切除邊緣（margin）必須大於2 mm","(D) 乳房保留手術加上腫瘤邊緣乾淨（clear margin）相對於乳房全切除手術，其同側局部復發率並無差別"],"answer":1,"image":""},{"id":"md5-109-2-42","subject":"md5","topic":"小兒外科","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"30天大的新生兒來到健兒門診，發現其眼白比較黃，經詢問得知其大便顏色偏粉筆白（clay-colored stool），疑是膽道閉鎖。下列那一個檢查是診斷膽道閉鎖的黃金標準（gold standard）？","options":["(A) 病毒血清檢查，包括弓漿蟲、德國麻疹病毒、巨細胞病毒、疱疹病毒等與B型肝炎的檢查","(B) 腹部超音波檢查","(C) hepatobiliary iminodiacetic acid（HIDA）scintigraphy檢查","(D) 肝臟切片檢查"],"answer":3,"image":""},{"id":"md5-109-2-43","subject":"md5","topic":"泌尿-結石與感染","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"一名4個月大的女嬰發燒到39℃，身體檢查並無上呼吸道感染，尿液檢查則發現有白血球增加的現象，符合泌尿道感染的診斷。在住院施打抗生素與補充水分之後，她的燒很快就退了，超音波檢查發現有輕微右側水腎的現象。該女嬰於1個月前也曾發生泌尿道感染，下列那一個檢查應最優先進行？","options":["(A) 腹部電腦斷層檢查（abdominal CT）","(B) 腹部核磁共振檢查（abdominal MRI）","(C) 膀胱輸尿管逆流攝影（VCUG）","(D) 靜脈腎盂造影（IVP）"],"answer":2,"image":""},{"id":"md5-109-2-44","subject":"md5","topic":"小兒外科","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"一名33週的早產兒，出生後生命徵象穩定，但在第一次餵奶時發現有咳嗽、嗆到、發紺的狀況，且伴隨著大量口水流出；當試著置入胃管時，發現無法放至胃部，因此新生兒科醫師安排食道鋇劑攝影如圖。針對上述情況，下列相關敘述何者錯誤？","options":["(A) 該患兒必定伴隨著食道氣管瘻管（tracheoesophageal fistula）","(B) 該患兒很可能身體有其他的異常，因此一定要再檢查其他器官系統有無異常","(C) 該患兒之疾病以Gross type C最常見","(D) 若沒有其他更緊急的狀況，患兒應儘速接受手術治療"],"answer":3,"image":"md5-109-2-44.jpeg","answer_note":"更正:第44題答Ｄ給分。 (原公告答案 A)"},{"id":"md5-109-2-45","subject":"md5","topic":"小兒外科","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"臍膨出（omphalocele）及腹裂畸形（gastroschisis）是新生兒先天性腹壁缺損的兩種常見形式。下列敘述何者錯誤？","options":["(A) 臍膨出的病人，會有一層包膜包覆膨出的臟器，而腹裂畸形則無","(B) 臍膨出的病人比較可能有腸道發育的問題；而腹裂畸形的病人則約50%伴有腸道以外之其他器官系統的變異","(C) 臍膨出的病人腹壁缺損通常在腹部中線","(D) 腹裂畸形的腹壁缺損處通常在肚臍的右側"],"answer":1,"image":""},{"id":"md5-109-2-46","subject":"md5","topic":"小兒外科","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"下列4個未合併其他疾病的病人接受手術，何者最需開立預防性抗生素？","options":["(A) 5個月大女生，預計接受雙側腹股溝疝氣手術","(B) 1歲大男生，預計接受左側睪丸固定手術","(C) 12歲大男生，預計接受漏斗胸矯正板置入手術（Nuss procedure）","(D) 3歲大女生，預計接受左側頸部淋巴管瘤切除手術"],"answer":2,"image":""},{"id":"md5-109-2-47","subject":"md5","topic":"小兒外科","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"一名7歲大的男童因為頸部淋巴結腫大被父母帶來兒童外科門診，下列那個情況最可能需要做手術切片？","options":["(A) 數個0.5公分大，位於前頸部淋巴結","(B) 單一2公分大，位於左鎖骨上淋巴結（supraclavicular）","(C) 單一0.8公分大，位於左耳後淋巴結","(D) 數個0.5公分大，位於右枕骨區淋巴結"],"answer":1,"image":""},{"id":"md5-109-2-48","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"下列何者為結腸憩室炎（diverticulitis）必須手術的適應症？①破裂造成腹膜炎（free perforation with peritonitis） ②形成局部2公分膿瘍（localized abscess）無腹膜炎 ③形成結腸膀胱瘻管（colovesical fistula） ④造成貧血、血紅素9.9","options":["(A) 僅①②③","(B) 僅①③","(C) 僅②④","(D) ①②③④"],"answer":1,"image":""},{"id":"md5-109-2-49","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"比較Ulcerative colitis及Crohn's colitis，下列敘述何者錯誤？","options":["(A) gross appearance : Ulcerative colitis較多有thickened colon wall","(B) microscopic appearance : Crohn's colitis常有lymphoid aggregates","(C) clinical features : Ulcerative colitis較常有血便","(D) operative treatment : Crohn's colitis是ileal pouch的contraindication"],"answer":0,"image":""},{"id":"md5-109-2-50","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"下列關於骨盆底肌肉群（the muscles of pelvic floor）的敘述，何者錯誤？","options":["(A) 又稱為提肛門肌（levator ani），由恥骨尾骨肌（pubococcygeus muscle）、恥骨直腸肌（puborectalis muscle）及梨狀肌（piriformis muscle）共同組合而成","(B) 平時由骨盆底肌肉群維持一定的張力，支撐著骨盆腔內的器官，同時與肛門括約肌一起協調控制著排便行為","(C) 恥骨直腸肌（puborectalis muscle）為U字型的橫紋肌，放鬆時會使肛門直腸角度拉直（anorectal angle straightens），藉此使糞便下降以利排便","(D) 若骨盆底肌肉群有功能上的障礙，可能會產生排便異常問題"],"answer":0,"image":""},{"id":"md5-109-2-51","subject":"md5","topic":"消化器外科","meta":"109年第2次第51題","year":109,"session":2,"number":51,"question":"關於總膽管結石（CBD stone）之敘述，何者正確？","options":["(A) 治療方式之一為內視鏡逆行性膽胰管攝影術（ERCP）取出總膽管結石","(B) 只有不到50%總膽管結石能以內視鏡逆行性膽胰管攝影術（ERCP）取出","(C) 施行內視鏡逆行性膽胰管攝影術（ERCP）取出總膽管結石後，年輕人復發總膽管結石的機會比老人高","(D) 應優先考慮腹腔鏡膽囊切除及總膽管探查手術"],"answer":0,"image":""},{"id":"md5-109-2-52","subject":"md5","topic":"消化器外科","meta":"109年第2次第52題","year":109,"session":2,"number":52,"question":"關於單一切口腹腔鏡手術（single-incision laparoscopic surgery）的設備與對外科醫師操作的益處描述，下列何者錯誤？","options":["(A) 細長的器械可以減少內部及外部操作的撞擊","(B) 較細長的器械有利手術範圍的操作","(C) 較小直徑的鏡頭對於手術操作空間無幫助","(D) 高解析鏡頭能提升手術中的視野"],"answer":2,"image":""},{"id":"md5-109-2-53","subject":"md5","topic":"消化器外科","meta":"109年第2次第53題","year":109,"session":2,"number":53,"question":"下列何者不是達文西機械手臂手術（robotic surgery）的優點？","options":["(A) 符合人體力學的手術操作台","(B) 立體影像","(C) 影像去顫功能（tremor elimination）","(D) 不需要床邊助手（bedside assistant）"],"answer":3,"image":""},{"id":"md5-109-2-54","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第2次第54題","year":109,"session":2,"number":54,"question":"65歲男性病患因胰頭癌接受胰十二指腸切除手術，於術後第7天正常進食，但腹內引流量突然從50 ml/day增加至800ml/day，且引流液從透明血水變成乳白色混濁液，除此之外病人並無發燒及任何不適；請問下列何者之診斷較為可能？","options":["(A) 胰液滲漏（pancreatic leak）","(B) 腹內膿瘍（intra-abdominal abscess）","(C) 乳糜液滲漏（chyle leak）","(D) 膽汁滲漏（bile leak）"],"answer":2,"image":""},{"id":"md5-109-2-55","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第2次第55題","year":109,"session":2,"number":55,"question":"承上題，下列引流液之檢查結果，何者可符合上題之診斷？①細菌培養通常為陽性 ②澱粉酶高（high amylase level in drain） ③三酸甘油脂（triglyceride）低（<100 mg/dL），及膽固醇（cholesterol）高 ④三酸甘油脂（triglyceride）高（>110 mg/dL），及膽固醇（cholesterol）低 ⑤淋巴球（lymphocyte）比率高，及中性白血球（neutrophil）比率低","options":["(A) ④⑤","(B) ①②","(C) ①③","(D) ②③"],"answer":0,"image":""},{"id":"md5-109-2-56","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第2次第56題","year":109,"session":2,"number":56,"question":"一位25歲女性，從高處跌落，造成頸部疼痛及四肢癱瘓，但意識清楚，四肢無冰冷現象。電腦斷層影像檢查發現第五頸椎骨折神經壓迫。此時病患心搏速率：60次/分、血壓：75/55毫米汞柱。關於病患現在血壓狀況，下列何者是最適當的診斷？","options":["(A) 過敏性休克（anaphylactic shock）","(B) 失血性休克（hypovolemic shock）","(C) 神經性休克（neurogenic shock）","(D) 心因性休克（cardiogenic shock）"],"answer":2,"image":""},{"id":"md5-109-2-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"109年第2次第57題","year":109,"session":2,"number":57,"question":"22歲的陳同學喜歡打籃球。一日下午，他跳起投籃時恰好被隊友撞了一下，落地時左腳單腳著地沒站穩而跌倒。他忍痛爬了起來，發現並沒有外傷；剛才摔下去時左膝內部隱約有「啪」一聲響，但是勉強還能走動。當天傍晚，他發現膝關節鼓脹起來。他立刻搭車到醫院急診處，醫師從他的膝關節內抽出了約60毫升的暗紅血液。陳同學最可能的傷況是：","options":["(A) 股四頭肌腱（quadriceps tendon）斷裂","(B) 前十字韌帶（anterior cruciate ligament）斷裂","(C) 髕骨韌帶（patellar tendon）斷裂","(D) 髕骨前滑囊炎（prepatellar bursitis）"],"answer":1,"image":""},{"id":"md5-109-2-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第2次第58題","year":109,"session":2,"number":58,"question":"有關佩吉特氏病（Paget's disease）的敘述，下列何者最正確？","options":["(A) 病理機轉主要是因為骨生成增高及骨吸收降低","(B) 病理檢查可以發現粗大的骨小樑、不規則的編織骨（woven bone）與骨泥線（cement lines）","(C) 與正常人相比，尿中pyridinoline和deoxypyridinoline偏低","(D) 可給予連續副甲狀腺素注射治療"],"answer":1,"image":""},{"id":"md5-109-2-59","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第2次第59題","year":109,"session":2,"number":59,"question":"有關單一性骨軟骨瘤（solitary osteochondroma）及多發性遺傳性外生骨贅（multiple hereditary exostoses）的敘述，下列何者最正確？","options":["(A) 多發性遺傳性外生骨贅具有自體隱性遺傳的特性，且外顯率（penetrance）很低","(B) 莖狀（stalk type）型態的單一性骨軟骨瘤，突出的軟骨帽（cartilage cap）朝向其相鄰近關節方向生長","(C) 當發生於骨盆或肩胛骨等軀幹部位的扁平骨時，惡性化轉型（malignant transformation）的機會較高","(D) 應該在骨骼生長發育成熟前，執行腫瘤切除手術，防止日後發生壓迫神經或肢體變形等現象"],"answer":2,"image":""},{"id":"md5-109-2-60","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"109年第2次第60題","year":109,"session":2,"number":60,"question":"關於踝部骨折的X光三種相位檢查，下列何者最不適當？","options":["(A) 需包含前後相位（anteroposterior view），側相位（lateral view）及Mortise氏相位（Mortise view）","(B) Mortise氏相位最有助於判斷距骨向外側移位（talar lateral shift）","(C) 前後相位最有助於判斷跟骨骨折","(D) 側相位最有助於判斷後踝骨折"],"answer":2,"image":""},{"id":"md5-109-2-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第2次第61題","year":109,"session":2,"number":61,"question":"下列那種骨骼病變中，黏多醣症（mucopolysaccharidoses）的病童最少發生？","options":["(A) 鎖骨變寬（broad clavicle）","(B) 卵圓形的脊椎體（ovoid vertebral body）","(C) 髖臼發育不良（acetabular dysplasia）","(D) 髖內翻（coxa vara）"],"answer":3,"image":""},{"id":"md5-109-2-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第2次第62題","year":109,"session":2,"number":62,"question":"有關於肘隧道症候群（cubital tunnel syndrome）的敘述，下列何者最不適當？","options":["(A) 壓迫尺神經所致","(B) 靠近小指和無名指半邊之手掌麻痺","(C) 磁振造影是最常用的檢查","(D) 晚期會有爪手（claw hand）的現象"],"answer":2,"image":""},{"id":"md5-109-2-63","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"109年第2次第63題","year":109,"session":2,"number":63,"question":"有關青春期自發性脊椎側彎（adolescent idiopathic scoliosis）之敘述，下列何者最正確？","options":["(A) 在側彎角度約10度時，女性的發生率約為男性的10倍","(B) 側彎的胸部凸側（convex side）通常是在右側","(C) 腸骨鈣化中心（Risser sign of iliac apophysis ossification），通常從前下腸骨脊（antero-inferior iliac spine）先開始出現","(D) 年紀愈大才發病者，側彎角度容易惡化"],"answer":1,"image":""},{"id":"md5-109-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"109年第2次第64題","year":109,"session":2,"number":64,"question":"由飲食獲得草酸（oxalate）占所有尿液中排出草酸的比率為何？","options":["(A) 1～5%","(B) 10～15%","(C) 40～50%","(D) 80～90%"],"answer":1,"image":""},{"id":"md5-109-2-65","subject":"md5","topic":"泌尿-腫瘤","meta":"109年第2次第65題","year":109,"session":2,"number":65,"question":"下列有關睪丸腫瘤的敘述，何者錯誤？","options":["(A) 精原細胞瘤（seminoma）是原發睪丸癌最常見的生殖細胞腫瘤","(B) 7～10%的睪丸腫瘤發生在隱睪症病人","(C) 小學時將隱睪症的睪丸手術固定於陰囊（orchidopexy）可以減少睪丸癌的發生","(D) 懷孕中婦女使用女性荷爾蒙會增加胎兒發生睪丸腫瘤的機會"],"answer":2,"image":""},{"id":"md5-109-2-66","subject":"md5","topic":"泌尿-腫瘤","meta":"109年第2次第66題","year":109,"session":2,"number":66,"question":"有關於前列腺癌的敘述，下列何者錯誤？","options":["(A) 血清前列腺特定抗原（prostate-specific antigen）對偵測癌症淋巴轉移較電腦斷層為佳","(B) 一般來說，血清前列腺特定抗原值愈高則預後愈差","(C) 前列腺癌之骨骼轉移較內臟轉移常見，70%至90%的病人死亡時都有骨骼轉移","(D) 前列腺癌之骨骼轉移最常見於脊椎及骨盆"],"answer":0,"image":""},{"id":"md5-109-2-67","subject":"md5","topic":"泌尿-腫瘤","meta":"109年第2次第67題","year":109,"session":2,"number":67,"question":"腎臟癌發生Stauffer syndrome之原因可能來自產生過多之何種因子？","options":["(A) tumor necrosis factor（TNF）","(B) interferon（INF）","(C) epidermal growth factor（EGF）","(D) granulocyte-macrophage colony stimulating factor（GMCSF）"],"answer":3,"image":""},{"id":"md5-109-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"109年第2次第68題","year":109,"session":2,"number":68,"question":"有關利用5-alpha reductase inhibitor治療良性前列腺肥大之敘述，下列何者錯誤？","options":["(A) 可藉由阻斷testosterone轉變成dihydrotestosterone（DHT），抑制前列腺之腺體上皮細胞生長，進而使其體積縮小","(B) 須持續使用6個月以上，才能發揮最大療效","(C) 當藥物治療達到最大療效時，可以使前列腺體積縮小20%，且病人血清中之prostate-specific antigen（PSA）亦會減少將近50%","(D) 不論前列腺體積大或小均有療效"],"answer":3,"image":""},{"id":"md5-109-2-69","subject":"md5","topic":"泌尿-結石與感染","meta":"109年第2次第69題","year":109,"session":2,"number":69,"question":"有關急性細菌性副睪丸炎之敘述，下列何者錯誤？","options":["(A) 絕大多數病人會出現陰囊腫大、疼痛，理學檢查可能無法分辨睪丸及副睪丸","(B) 年輕男性之急性細菌性副睪丸炎通常與糖尿病有關","(C) 若是發生在小男孩，要檢查是否有先天性解剖構造異常，如膀胱輸尿管尿液逆流或異位性輸尿管開口","(D) 若形成膿瘍，則通常需要進行開刀引流"],"answer":1,"image":""},{"id":"md5-109-2-70","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"109年第2次第70題","year":109,"session":2,"number":70,"question":"下列何者臨床症狀與高齡男性之低睪固酮無關？","options":["(A) 性慾減退（decreased libido）","(B) 海綿體靜脈溢漏（venous leakage）","(C) 骨質疏鬆（osteoporosis）","(D) 肥胖（obesity）"],"answer":1,"image":""},{"id":"md5-109-2-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"109年第2次第71題","year":109,"session":2,"number":71,"question":"下列有關睪丸生理之敘述，何者正確？","options":["(A) luteinizing hormone（LH）作用在Sertoli細胞","(B) follicle-stimulating hormone（FSH）作用在Leydig細胞","(C) testosterone是由睪丸中Leydig細胞產生","(D) 精液中fructose是由前列腺產生"],"answer":2,"image":""},{"id":"md5-109-2-72","subject":"md5","topic":"消化器外科","meta":"109年第2次第72題","year":109,"session":2,"number":72,"question":"長期洗腎病患突然解血便，在急診室曾發生休克，緊急血管攝影檢查（下腸繫膜動脈，inferior mesenteric artery），如圖，箭號所指之腸出血最可能源自下列那一條血管？","options":["(A) internal pudendal artery","(B) superior rectal artery","(C) inferior gluteal artery","(D) superior vesical artery"],"answer":1,"image":"md5-109-2-72.jpeg"},{"id":"md5-109-2-73","subject":"md5","topic":"泌尿-腫瘤","meta":"109年第2次第73題","year":109,"session":2,"number":73,"question":"50歲男性病人主訴最近肉眼可見血尿。下圖為靜脈注射尿路Ｘ光攝影（intravenous urography）。最可能的診斷為何？","options":["(A) renal cell carcinoma","(B) renal lymphoma","(C) renal urothelial cell carcinoma","(D) renal angiomyolipoma"],"answer":2,"image":"md5-109-2-73.jpeg"},{"id":"md5-109-2-74","subject":"md5","topic":"消化器外科","meta":"109年第2次第74題","year":109,"session":2,"number":74,"question":"55歲男性病人在肝臟超音波追蹤時發現陰影，安排三相式（pre-contrast, arterial phase, venous phase）電腦斷層掃描如圖示，抽血結果肝功能正常，胎兒蛋白（α-FP）正常，下列何項診斷最有可能？","options":["(A) hepatic hemangioma","(B) hepatocellular carcinoma","(C) hepatic cyst","(D) hepatic cholangiocarcinoma"],"answer":1,"image":"md5-109-2-74.jpeg"},{"id":"md5-109-2-75","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"109年第2次第75題","year":109,"session":2,"number":75,"question":"病態性肥胖（morbid obesity）病人接受減肥手術後，下列敘述何者最正確？","options":["(A) 胃繞道減肥手術（Roux-en-Y gastric bypass），出院後一週因為噁心、嘔吐至急診，若為腸阻塞造成的，不會出現膽汁嘔吐物","(B) 手術後產生併發症，通常與外科醫師技術無明顯關係","(C) 手術後產生吻合口潰瘍（stomal ulcer），通常是在手術後3～5天內產生","(D) 胃繞道減肥手術（Roux-en-Y gastric bypass）最常發生的併發症是傾食症候群（dumping syndrome），會在開始進食後產生"],"answer":3,"image":""},{"id":"md5-109-2-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"109年第2次第76題","year":109,"session":2,"number":76,"question":"28歲懷孕34週婦女走路時被機車撞倒，經救護車送急診時主訴下腹痛合併陰道出血，生命徵象如下：體溫36.9℃，心跳120/min，呼吸24/min，血壓80/40 mmHg。關於此病人的描述，下列何者最正確？","options":["(A) 陰道分泌物若pH值為7，代表病人之羊膜破裂（amniotic membrane rupture）","(B) 病人須立即執行骨盆檢查來排除前置胎盤（placenta previa）的可能性","(C) 此休克婦女應採取左側抬高的臥姿，避免壓迫下腔靜脈","(D) 病人不適合執行腹部或骨盆腔電腦斷層檢查，避免輻射線對胎兒造成傷害"],"answer":0,"image":""},{"id":"md5-109-2-77","subject":"md5","topic":"神經外科","meta":"109年第2次第77題","year":109,"session":2,"number":77,"question":"25歲男性因頭部外傷送至急診，檢查時瞳孔對光反應遲鈍，給予疼痛刺激時會張開眼睛，發出他人無法了解的聲音，右手臂變形對疼痛刺激無反應，左手對疼痛刺激會用手撥開，則此病人的格拉斯哥昏迷指數（Glasgow Coma Scale）分數為何？","options":["(A) 7","(B) 8","(C) 9","(D) 10"],"answer":2,"image":""},{"id":"md5-109-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"109年第2次第78題","year":109,"session":2,"number":78,"question":"30歲未婚成年男性病人，經西方墨點法（western blot）確診為愛滋病，病人的同居女友就在門診外，下列敘述何者正確？①若病人同意，醫師可以告知其同居女友 ②若病人不同意，醫師仍應立即告知其同居女友 ③醫師有法定通報主管機關的義務 ④若病人明知感染，隱瞞再與他人進行危險性行為，而導致他人感染，是會有法律責任的","options":["(A) ①②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":2,"image":""},{"id":"md5-109-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"109年第2次第79題","year":109,"session":2,"number":79,"question":"2 30歲肥胖（身體質量指數40 kg/m）具決定能力的未婚男性，罹患高血壓、高血脂、糖尿病，經內科治療減肥無效，與醫師討論手術的可行性，經醫師說明後同意接受外科治療，但病人表示不願意告知父母，經溝通仍無法說服病人。下列何者是最適當的方法？","options":["(A) 等病人同意告知父母後再開刀","(B) 私下取得病人父母同意後再開刀","(C) 尊重病人本人的決定，在病歷上敘明即可","(D) 尊重病人本人的決定，病人進手術室後再通知父母"],"answer":2,"image":""},{"id":"md5-109-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"109年第2次第80題","year":109,"session":2,"number":80,"question":"74歲的老先生，於醫院接受自費的全身健康檢查，胃鏡檢查發現有胃潰瘍，其後於門診追蹤時，該病患曾多次詢問醫師是否應該進行胃鏡切片檢查，但醫師僅建議先行服用胃潰瘍藥物，4個月後再做胃鏡追蹤。但胃鏡檢查3個月後，該病患的體重開始下降，胃鏡及切片檢查發現該病患罹患胃腺細胞癌，病患接受了手術及化學治療，仍然不幸於1年後死亡。該案進入訴訟程序，醫院所提供的病歷紀錄中，比家屬於偵查程序中影印的病歷紀錄多出了「病患拒絕切片檢查、病患想先吃藥」等敘述，法院認定該敘述無效，判決醫師未及時向患者充分解釋切片檢查之必要性以及不檢查之危險性，而判決被告醫師有所過失。下列敘述，何者錯誤？","options":["(A) 醫療糾紛發生後，醫師本來就應該補充病歷記錄。本案中，法官並不能因為醫師補充病歷記錄，就認為該紀錄無效，因而判決醫師敗訴","(B) 醫療糾紛發生後，醫師雖然可以補充病歷記錄，但應該在補充記錄的地方，加註補充記錄當時的年、月、日。以免法官認為該補充記錄之相關記錄，為事後所偽造或變造之病歷，從而認定該敘述無效","(C) 醫療糾紛發生後，醫師如果所補充記錄之病歷，並非事實，在刑法上，會涉及相關業務文書登載不實罪","(D) 醫療糾紛發生後，醫師如果所補充記錄之病歷，並非事實，在民法上，可能會負擔相關舉證妨礙的不利益，從而負起舉證責任"],"answer":0,"image":""},{"id":"md5-110-1-1","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"目前對於重大外傷病患的處理，大都依據Damage Control Principles；針對這種處理策略的敘述，下列何者錯誤？","options":["(A) 外傷病患出現的lethal triad包括hypotension, hypothermia, metabolic acidosis","(B) 手術策略為積極復甦處置（aggressive resuscitation），快速止血處理（quickly managing bleeding），腸道破裂快速縫合或局部切掉但不接回，及胸腹部開刀傷口暫時性關閉（temporary closure）","(C) 軍方於戰場處理的經驗，建議resuscitation時，Packed RBC, FFP及platelet應使用1：1：1的比例","(D) 最近的文獻，亦有Tranexamic acid(TXA)應用在Damage Control Principles中"],"answer":0,"image":""},{"id":"md5-110-1-2","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"39歲男性，有本態性高血壓、高脂血症、糖尿病及肝功能異常等病史並接受藥物控制，因病態性肥胖接受腹腔鏡袖狀胃切除手術（sleeve gastrectomy）。術前病人體重130公斤，身體質量指數（body mass index）為42 2 .4kg/m，血壓146/70 mmHg，心跳72次/分，呼吸16次/分。術後4小時病人主訴呼吸困難，意識呈焦慮狀態，當時血壓120/95 mmHg、心跳117次/分、呼吸26次/分，給與氧氣3公升/分，使用後，動脈血氧飽和度可達100%。此時病人最有可能的診斷為何？","options":["(A) 急性肺栓塞（acute pulmonary embolism）","(B) 急性心肌梗塞（acute myocardial infarction）","(C) 急性失血（acute blood loss）","(D) 急性疼痛（acute pain）"],"answer":2,"image":""},{"id":"md5-110-1-3","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"器官移植病患初期常使用高劑量的類固醇，下列敘述何者錯誤？","options":["(A) 長期合併類固醇使用仍是移植病患標準的給藥模式","(B) 副作用的產生是dose dependent","(C) 急性排斥往往需要高劑量類固醇注射治療","(D) 類固醇初期高劑量使用會產生全身水腫情形"],"answer":0,"image":""},{"id":"md5-110-1-4","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"有關人類惡性腫瘤之描述，下列何者錯誤？","options":["(A) 惡性腫瘤最常轉移的位置之一為肺臟及肋膜","(B) 尿中Bence Jones protein是淋巴癌的腫瘤生物指標（tumor biomarker）","(C) 手術切除肺臟、肝臟或腦部的單一轉移病灶，有機會延長病人存活率","(D) 血液中癌胚蛋白（carcinoembryonic antigen, CEA）的敏感及專一性並不佳，但可做為手術後追蹤腫瘤復發的參考"],"answer":1,"image":""},{"id":"md5-110-1-5","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"術後48至72小時內發燒較常見的原因是：","options":["(A) 傷口發炎（wound infection）","(B) 腹內膿瘍（intra-abdominal abscess）","(C) 肺泡塌陷（atelectasis）","(D) 尿道感染（urinary tract infection）"],"answer":2,"image":""},{"id":"md5-110-1-6","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"營養支持對於外科重症的病人極為重要，下列何者最接近正常體重病人一天的基礎能量消耗（basal energy expenditure）？","options":["(A) 10～15 Kcal x BW（Kg）","(B) 15～20 Kcal x BW（Kg）","(C) 25～30 Kcal x BW（Kg）","(D) 30～35 Kcal x BW（Kg）"],"answer":2,"image":""},{"id":"md5-110-1-7","subject":"md5","topic":"神經外科","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"下列何者不是常壓性水腦（normal pressure hydrocephalus）臨床的三樣典型表徵（triad）？","options":["(A) 失智（dementia）","(B) 步態不穩（gait ataxia）","(C) 尿失禁（urinary incontinence）","(D) 肢體顫抖（tremor）"],"answer":3,"image":""},{"id":"md5-110-1-8","subject":"md5","topic":"神經外科","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"下列關於腦膜瘤（Meningioma）的敘述，何者錯誤？","options":["(A) 腫瘤細胞源自於硬腦膜（Dura）","(B) 有可能從良性變為惡性（malignant transformation）","(C) 有可能導致周圍骨增生（hyperostosis）","(D) 有可能侵犯進入周圍的靜脈竇（venous sinus）"],"answer":0,"image":""},{"id":"md5-110-1-9","subject":"md5","topic":"神經外科","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"三叉神經痛最常因那一條血管壓迫而造成？","options":["(A) 前小腦下動脈（anterior inferior cerebellar artery）","(B) 後小腦下動脈（posterior inferior cerebellar artery）","(C) 小腦上動脈（superior cerebellar artery）","(D) 前脈絡膜動脈（anterior choroidal artery）"],"answer":2,"image":""},{"id":"md5-110-1-10","subject":"md5","topic":"神經外科","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"有關腰椎退化神經病變，下列敘述何者錯誤？","options":["(A) 腰椎椎間盤突出（lumbar disc herniation）最常發生在L3-4或L4-5處","(B) 腰椎退化椎管狹窄常導因於後側小關節或黃韌帶變大、變厚，造成神經椎孔狹小，神經壓迫","(C) 間歇性跛行可藉由暫時坐下而使症狀緩解","(D) 踝反射降低所代表的通常是S1神經根壓迫"],"answer":0,"image":""},{"id":"md5-110-1-11","subject":"md5","topic":"整形重建外科","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"依據Mathes and Nahai對肌肉皮瓣（muscle flaps）血管供應做分類，下列那一型較少用來做顯微組織移植的肌肉皮瓣？","options":["(A) 第一型","(B) 第二型","(C) 第三型","(D) 第四型"],"answer":3,"image":""},{"id":"md5-110-1-12","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"在大面積燒燙傷治療中，充分的體液復甦（fluid resuscitation）是避免休克的重要治療。對於30歲、70公斤的男性燒燙傷病人，二度及三度傷口共占體表面積（TBSA）40%，下列處置何者最不適當？","options":["(A) 建立靜脈管線（IV line）開始體液復甦（fluid resuscitation），並插尿管監測尿量","(B) 如果按照Parkland formula靜脈輸液是給與lactated Ringer solution，從700cc/hr開始給與","(C) 尿量須維持在35 cc/hr以上","(D) 給與lactated Ringer solution 2小時後，尿量突然變少，可再給與albumin，從0.5ml / Kg / % TBSA burn area開始給與"],"answer":3,"image":""},{"id":"md5-110-1-13","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"請選擇出急性傷口癒合過程（wound healing）正確的順序：①重塑期（remodeling） ②增生期（proliferation） ③成熟期（maturation） ④發炎期（inflammation） ⑤凝血（coagulation）","options":["(A) ①→②→③→④→⑤","(B) ④→⑤→③→②→①","(C) ⑤→④→①→②→③","(D) ⑤→④→②→③→①"],"answer":3,"image":""},{"id":"md5-110-1-14","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"傷口癒合的機轉中，下列何者最先出現並扮演啟動癒合的角色？","options":["(A) 血小板（platelet）","(B) 紅血球（RBC）","(C) 巨噬細胞（macrophage）","(D) 膠原蛋白（collagen）"],"answer":0,"image":""},{"id":"md5-110-1-15","subject":"md5","topic":"整形重建外科","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"有關皮膚惡性腫瘤的敘述，下列何者正確？","options":["(A) Kaposi's sarcoma跟人類腺病毒（adeno virus）相關，好發於年輕人或免疫不全的人","(B) 皮纖維肉瘤（dermatofibrosarcoma protuberans）是一種低度惡性的皮膚癌，手術切除是主要治療，無需做淋巴的摘除","(C) 惡性纖維組織瘤（malignant fibrous histiocytoma）好發於老年人，治療方法是手術切除即可，且很少轉移","(D) 血管性肉瘤（angiosarcoma）是相對良性的腫瘤，好發於頭頸區域，手術切除是主要治療"],"answer":1,"image":""},{"id":"md5-110-1-16","subject":"md5","topic":"心臟血管外科","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"下列那些先天性心臟病若不及時手術，可能會發生所謂的Eisenmenger syndrome，最後需要心肺移植？①肺動脈瓣狹窄②心室中隔缺損③動脈幹症（truncus arteriosus）④開放性動脈導管","options":["(A) 僅①②","(B) 僅①③","(C) ①②③","(D) ②③④"],"answer":3,"image":""},{"id":"md5-110-1-17","subject":"md5","topic":"心臟血管外科","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"在急性主動脈剝離（aortic dissection）的治療上，下列敘述何者錯誤？","options":["(A) 在高度懷疑為主動脈剝離之情形下，可先實行降低心跳及控制血壓之藥物治療（anti-pulse therapy and blood pressure control）","(B) 對急性史丹佛A型（Stanford type A）之主動脈剝離病患，應考慮進行緊急主動脈置換手術","(C) 對急性史丹佛B型（Stanford type B）之主動脈剝離合併有器官供血不足（malperfusion）之病患，應立即考慮介入性血管內主動脈支架術（endovascular treatment）之可能性","(D) 對於急性史丹佛A型（Stanford type A）之主動脈剝離合併有器官供血不足的病患，與無器官供血不足者，兩者之預後相同"],"answer":3,"image":""},{"id":"md5-110-1-18","subject":"md5","topic":"心臟血管外科","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"有關心臟手術時使用人工心肺機之敘述，下列何者錯誤？","options":["(A) 可以升降體溫","(B) 合併心臟麻痺液（cardioplegia）使用，可以讓心臟完全停止跳動","(C) 氧合器（oxygenator）可以暫時取代肺臟功能","(D) 不會引發全身發炎反應症候群（systemic inflammatory response syndrome, SIRS）"],"answer":3,"image":""},{"id":"md5-110-1-19","subject":"md5","topic":"心臟血管外科","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"68歲農婦因右手輕微無力伴隨下肢輕微水腫來診，經診斷為二尖瓣狹窄（mitral stenosis），超音波顯示為心2房顫動（atrial fibrillation）且瓣膜開口為1.35 cm，過去有右側膿胸且經開胸治療之病史，下列敘述或處置何者正確？①中風之故，不應給與抗凝血劑，如warfarin ②應建議進行心導管檢查 ③進行瓣膜手術，且可同時進行迷宮手術（Cox-Maze procedure） ④可選擇胸腔鏡或小傷口內視鏡進行手術","options":["(A) 僅①④","(B) ②③④","(C) ①②③","(D) 僅②③"],"answer":3,"image":""},{"id":"md5-110-1-20","subject":"md5","topic":"心臟血管外科","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"下列對冠狀動脈繞道術（coronary artery bypass grafting, CABG）之描述何者錯誤？","options":["(A) 不使用心肺機之不停跳術式（off-pump coronary artery bypass）比傳統之停跳之術式，在各項研究皆顯示可以減少發炎指數，即有更好之長期通暢率","(B) 如果病人是70歲女性，其三條冠狀血管皆有80到90%狹窄，且有糖尿病，冠狀動脈繞道術應該是首選之治療","(C) 對長期通暢率而言，內乳動脈遠佳於大隱靜脈，術後用藥可建議阿斯匹靈、乙型阻斷劑、抗心律不整藥物、降血脂藥物","(D) 術後可能之合併症含心包膜填充、出血、腦病變、腎衰竭、縱膈腔炎等"],"answer":0,"image":""},{"id":"md5-110-1-21","subject":"md5","topic":"胸腔外科","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"關於胸腺瘤之敘述，何者正確？","options":["(A) 手術是主要治療成功的方法，即使切除上腔靜脈再重建，預後也比較好","(B) 10%～50%的重症肌無力病人會發現胸腺瘤","(C) 胸腺瘤不是胸腺癌，不會有上腔靜脈症候群（SVC Syndrome）發生","(D) 胸腺瘤分期是根據Masaoka staging，第4a期是指有淋巴轉移"],"answer":0,"image":""},{"id":"md5-110-1-22","subject":"md5","topic":"胸腔外科","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"病人需要進行肺葉切除手術，下列關於肺功能的檢測敘述何者正確？","options":["(A) FEV1為術後肺容積的最常用指標，一般要大於40%才能做肺葉切除","(B) FEV1數據不足時，估算預期術後FEV1（ppo-FEV1）在20～30%以上應可以安全進行手術","(C) DLCO小於80%會增加手術風險","(D) DLCO小於50%應加測運動心肺功能檢查，因為運動心肺功能檢查較準確"],"answer":3,"image":""},{"id":"md5-110-1-23","subject":"md5","topic":"胸腔外科","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"有關於縱膈腔疾病的敘述，下列何者錯誤？","options":["(A) 精原性生殖細胞瘤（seminomatous germ cell tumor）常分泌AFP（α-fetoprotein）或β-hCG（human chorionic gonadotropin），為放療有效（radiosensitive）","(B) 大人和小孩的縱膈腔腫瘤好發種類不同，小孩常是神經性腫瘤（neurogenic tumor）","(C) 縱膈腔腫瘤經由手術移除後再輔助治療，其預後會比直接對大腫瘤做化放療有效","(D) 小顆的胸腺瘤合併有重症肌無力時，應盡早手術切除"],"answer":0,"image":""},{"id":"md5-110-1-24","subject":"md5","topic":"消化器外科","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"下列關於Barrett esophagus之敘述，何者錯誤？","options":["(A) 是一種intestinal metaplasia","(B) 如其長度超過3 cm，稱為long segment","(C) 需要biopsy作確診","(D) 以後變成squamous cell carcinoma之機率是一般人的40倍"],"answer":3,"image":""},{"id":"md5-110-1-25","subject":"md5","topic":"消化器外科","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"有關胃食道逆流之治療，下列何者較不適當？","options":["(A) lifestyle modification加上proton pump inhibitor（PPI）為第一線治療","(B) 如內科治療已到極限而仍有症狀，則外科手術建議介入","(C) 很長期使用proton pump inhibitor（PPI）有引起carcinoid tumor之可能","(D) Nissen fundoplication是partial fundoplication的一種"],"answer":3,"image":""},{"id":"md5-110-1-26","subject":"md5","topic":"胸腔外科","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"下列有關乳糜胸（chylothorax）的敘述，何者錯誤？","options":["(A) 左頸部／鎖骨上（supraclavicular）淋巴結廓清手術是原因之一","(B) 常從左側胸腔手術處理","(C) 保守治療需持續1～2週","(D) 手術治療常以結紮橫膈膜上乳糜管（thoracic duct）為主"],"answer":1,"image":""},{"id":"md5-110-1-27","subject":"md5","topic":"消化器外科","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"一位48歲男性，最近兩個月吞嚥困難、食慾減低、體重減輕5公斤，同時有聲音沙啞現象至門診求診，下列那一項檢查最不恰當？","options":["(A) 內視鏡超音波（endoscopic ultrasound）","(B) 內視鏡逆行性膽道胰管攝影（ERCP）","(C) 電腦斷層（CT）","(D) 食道攝影（esophagography）"],"answer":1,"image":""},{"id":"md5-110-1-28","subject":"md5","topic":"消化器外科","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"下列有關膽管細胞癌（cholangiocarcinoma）的敘述，何者錯誤？","options":["(A) 從十二指腸壺腹處（Ampulla of Vater）到肝內膽管都有可能發生，其中又以在肝門分支處的膽道癌（Klatskin tumor）最常見","(B) 根據最近的文獻顯示，肝內膽管細胞癌可能跟病毒感染、非酒精性脂肪肝、肝硬化及糖尿病有相關性","(C) 完整切除是肝內膽管細胞癌治療的準則，一般而言，可開刀的比例約可達60%","(D) 文獻指出，膽道癌對於化學治療效果很好，但對放射治療的效果並不明確"],"answer":3,"image":""},{"id":"md5-110-1-29","subject":"md5","topic":"消化器外科","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"下列有關急性胰臟炎的敘述，何者錯誤？","options":["(A) 造成急性胰臟炎的危險因子有膽結石，酒精、藥物、自體免疫及經內視鏡逆行性膽道胰臟攝影（ERCP）","(B) 評估疾病嚴重程度的方式有Ranson prognostic criteria、APACHE II分數及電腦斷層嚴重度指數（CT severity index）","(C) 若有胰臟及周邊組織壞死但無感染證據，仍須給與抗生素，避免壞死進一步變成感染性壞死或是膿瘍形成","(D) 在有胰臟周圍液體堆積中的5%～15%的病患會產生胰臟偽囊腫（pancreatic pseudocyst），急性胰臟炎也會造成鄰近器官出血、感染、器官壓迫及腸道阻塞等併發症"],"answer":2,"image":""},{"id":"md5-110-1-30","subject":"md5","topic":"消化器外科","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"有關gastric lymphoma的敘述，下列何者正確？","options":["(A) primary lymphoma在消化道中，最常出現在胃部，且多為T-cell type","(B) gastric lymphoma的治療主流仍是以手術切除為優先考慮","(C) gastric low-grade MALT lymphoma的致病機轉與幽門桿菌（H. pylori）有關","(D) 此疾病對化學治療的反應不佳"],"answer":2,"image":""},{"id":"md5-110-1-31","subject":"md5","topic":"消化器外科","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"下列何種靜脈曲張現象與門靜脈高壓最為無關？","options":["(A) 胃、食道靜脈曲張（esophagogastric varices）","(B) 精索靜脈曲張（varicocele）","(C) 上腹靜脈系統曲張（epigastric venous system）","(D) 痔瘡靜脈叢曲張（hemorrhoidal venous plexus）"],"answer":1,"image":""},{"id":"md5-110-1-32","subject":"md5","topic":"消化器外科","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"膽囊切除時發現總膽管被電燒刀切除了3公分長度，造成膽汁滲漏，如附圖。下列那一個處置最為恰當？","options":["(A) 將受傷的膽管（①和③）清除乾淨，銜接兩端剩餘的膽管（①和③銜接），由銜接的傷口處放置T型管作為支架","(B) 將受傷的膽管（①和③）清除乾淨，銜接兩端剩餘的膽管（①和③銜接），由銜接處下方的總膽管（③）放置T型管作為支架","(C) 將受傷的膽管①清除乾淨，以腸道銜接肝臟側剩餘的膽管①，並縫合③的斷端","(D) 將不慎切除的膽管②清除乾淨，重新橋接回原處（①-②-③銜接），並由此段膽管②放置T型管作為支架"],"answer":2,"image":"md5-110-1-32.jpeg"},{"id":"md5-110-1-33","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"胰臟移植後，導致病人死亡最常見的原因為：","options":["(A) 心血管疾病","(B) 感染","(C) 惡性腫瘤","(D) 器官排斥"],"answer":0,"image":""},{"id":"md5-110-1-34","subject":"md5","topic":"消化器外科","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"下列有關胰臟炎之敘述，何者正確？①急性胰臟炎70～80%原因為膽道結石及酗酒 ②慢性胰臟炎70～80% 原因為酗酒 ③急性胰臟炎大部分（約90%）應以外科治療 ④血液澱粉酶素（amylase）高低可預測急性胰臟炎的嚴重度 ⑤慢性胰臟炎合併糖尿病即應考慮外科治療","options":["(A) ①②","(B) ③⑤","(C) ④⑤","(D) ①③"],"answer":0,"image":""},{"id":"md5-110-1-35","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"在乳癌診治中，腋下淋巴腺分為三區（level），其中第二區（level II）位於：","options":["(A) thoracic dorsi動脈之外側","(B) thoracic dorsi動脈之內側","(C) 小胸肌上方者","(D) 小胸肌下方者"],"answer":3,"image":""},{"id":"md5-110-1-36","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"乳癌治療進行乳房保留手術的適應症，下列何者錯誤？","options":["(A) 病人因肺部疾病無法接受放射線治療，則不能選擇乳房保留手術","(B) 經由外科醫師評估，比較腫瘤相對於乳房大小，經局部切除後，可能影響乳房外觀，則不建議選擇乳房保留手術","(C) 若手術當中，前哨淋巴結有乳癌細胞轉移，則不能選擇乳房保留手術","(D) 若病灶為多發性且在不同象限，則不能選擇乳房保留手術"],"answer":2,"image":""},{"id":"md5-110-1-37","subject":"md5","topic":"整形重建外科","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"對於以義乳方式進行乳房重建（implant based breast reconstruction）的敘述，下列何者錯誤？","options":["(A) 此重建方式在雙側乳房外觀的對稱性方面效果比自體皮瓣好","(B) 近期要接受輔助放射線治療的病患，應評估其適用性","(C) 因為義乳植入，其外觀並不會隨時間改變，病患的滿意度在五年後仍高達90%","(D) 義乳植入適用於無法維持長時間麻醉的病患"],"answer":2,"image":""},{"id":"md5-110-1-38","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"一名6個月的小女嬰，肛門周圍七點鐘方向紅腫，被診斷為肛門周圍膿瘍，治療後有改善；但此情形反反覆覆直到1歲，媽媽發現小女嬰的肛門雖然不腫了，但七點鐘方向離肛門口1公分處有一個小洞，每次擠壓會流出一些分泌物。下列敘述何者最正確？","options":["(A) 是肛裂（anal fissure），抹藥就會好","(B) 肛門瘻管（anal fistula），瘻管會繞道由六點鐘方向匯入直腸","(C) 肛門瘻管（anal fistula），瘻管會直接由七點鐘方向匯入直腸","(D) 發生原因是久坐或肝門脈高壓"],"answer":2,"image":""},{"id":"md5-110-1-39","subject":"md5","topic":"小兒外科","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"一名12歲大30公斤重的女童因為右上腹痛來到門診，她過去無特殊病史，理學檢查發現她的右上腹有壓痛，超音波檢查發現膽囊有結石，下列敘述何者錯誤？","options":["(A) 對孩童而言，大部分的結石是膽固醇結石（cholesterol stone）","(B) 與肥胖無關","(C) 可以做紅血球脆性測驗","(D) 有症狀者應切除膽囊"],"answer":0,"image":""},{"id":"md5-110-1-40","subject":"md5","topic":"小兒外科","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"下列何者非幼兒常見的頸部腫瘤？","options":["(A) 畸胎瘤（teratoma）","(B) 囊狀水瘤（cystic hygroma）","(C) 鰓裂囊腫（branchial cleft cyst）","(D) 甲狀舌骨囊腫（thyroglossal duct cyst）"],"answer":0,"image":""},{"id":"md5-110-1-41","subject":"md5","topic":"小兒外科","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"一個剛滿月的男嬰，在新生兒健檢的時候，小兒科醫師發現他的右側陰囊內摸不到睪丸，故將他轉診到小兒外科醫師門診。小兒外科醫師為男嬰做身體檢查，發現在external ring的位置可以觸診到尚未降下的睪丸，且此睪丸無法下拉至陰囊。於是，男嬰的媽媽提出了許多問題，下列那一個回答不適合？","options":["(A) 問：怎麼辦，小寶貝的睪丸會不會有機會繼續往下降？答：在六個月至一歲之前，都還是可能有機會繼續往下降。但是過了六個月至一歲若還沒降下來，可能就沒什麼機會了","(B) 問：如果小寶貝的睪丸一直都沒有下降的跡象，那要怎麼辦？答：我們通常會觀察到六個月至一歲大之間，若發現睪丸沒有下降的情形，就要安排手術治療將睪丸固定在陰囊","(C) 問：如果不開刀，讓睪丸一直在上面，會怎麼樣嗎？答：那這個睪丸可能會隨著年紀增大漸漸的萎縮","(D) 問：醫師還要再為小寶貝安排什麼檢查嗎？答：我們需要再安排一個核磁共振檢查，來確認睪丸的位置及目前的大小"],"answer":3,"image":""},{"id":"md5-110-1-42","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"一名12歲45公斤重的男童，因為急性闌尾炎接受腹腔鏡闌尾切除手術，下列何者是比較適當的點滴輸液？","options":["(A) 每24小時給與2,000毫升輸液，其中內含5%葡萄糖，0.45%氯化鈉，20毫當量／升（mEq/liter）鉀離子","(B) 每24小時給與1,500毫升林格氏液（Ringer's solution）","(C) 每24小時給與1,500毫升代用血漿（Gelofusine）","(D) 每24小時給與2,000毫升0.9%生理食鹽水（normal saline）"],"answer":0,"image":""},{"id":"md5-110-1-43","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"關於肛門裂傷（anal fissure）的敘述，下列何者錯誤？","options":["(A) 肛門裂傷簡稱肛裂，是齒狀線和肛門緣之間的上皮受傷，多半發生在肛門的正後方或正前方","(B) 因為肛裂部位聚集著敏感的感覺神經，所以傷口雖小但有如刺骨般的疼痛","(C) 慢性肛裂是因硬便及肛裂的惡性循環導致肛門潰瘍","(D) 80%～90%的患者需要手術治療"],"answer":3,"image":""},{"id":"md5-110-1-44","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"依據Hinchey classification描述大腸憩室炎（colon diverticulitis）嚴重度的分類，若發生generalized purulent peritonitis的情況是屬於下列那一個stage？","options":["(A) stage IV","(B) stage III","(C) stage II","(D) stage I"],"answer":1,"image":""},{"id":"md5-110-1-45","subject":"md5","topic":"心臟血管外科","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"病患接受腹主動脈瘤修補手術後3天發生左下腹痛、血便，其最可能原因為何？","options":["(A) 偽膜性腸炎（pseudomembranous colitis）","(B) 潰瘍性腸炎（ulcerative colitis）","(C) 結腸憩室炎（diverticulitis）","(D) 缺血性腸炎（ischemic colitis）"],"answer":3,"image":""},{"id":"md5-110-1-46","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"有關大腸息肉的敘述，下列何者錯誤？","options":["(A) 大腸息肉經過許多基因的變異，可能長成大腸癌","(B) 腺性息肉越大，癌化的機率越高","(C) villous adenoma較tubular adenoma癌化的機率高","(D) 大腸息肉轉化成大腸癌的時間約需1～2年"],"answer":3,"image":""},{"id":"md5-110-1-47","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"對年長病患而言，使用腹腔鏡手術切除大腸腫瘤，相較於開腹手術切除大腸腫瘤之優點，不包含下列何項？","options":["(A) 減少心肺併發症","(B) 減少手術期間（peri-operative period）關於大腸切除的併發症及死亡率","(C) 傷口較小","(D) 腹腔鏡手術與開腹手術的腫瘤清除率（oncologic clearance）相當"],"answer":1,"image":""},{"id":"md5-110-1-48","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"全腹膜外疝氣修補手術（total extraperitoneal approach）的手術過程不需要執行下列何項？","options":["(A) 結紮股皮神經側枝（lateral femoral cutaneous nerve）","(B) 復位腹股溝疝氣囊","(C) 從恥骨聯合分離Cooper's ligament","(D) 手術範圍側邊需剝離至髂骨前上棘（anterior superior iliac spine）"],"answer":0,"image":""},{"id":"md5-110-1-49","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"在急診室，一位30歲70公斤男性，主訴約60分鐘前左上腹部被刀刺傷，傷口疼痛，生命徵候：心跳105/分、血壓110/95 mmHg、呼吸22/分，病人略顯焦慮，身體檢查發現左上腹部2公分傷口，四肢濕冷。預估該病人體內出血量最可能為下列何者？","options":["(A) 500 c.c.","(B) 1,000 c.c.","(C) 1,700 c.c.","(D) 2,500 c.c."],"answer":1,"image":""},{"id":"md5-110-1-50","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"承上題，病人經過20分鐘的初步處理突然意識不清，生命徵象：心跳145/分、血壓60/45 mmHg、呼吸32/分，下列何項處置不適當？","options":["(A) 插上氣管內管以維持呼吸道暢通","(B) 準備緊急手術以控制出血","(C) 緊急輸血及使用升壓劑，以維持收縮壓在120 mmHg","(D) 此時輸液除血液製品外，以lactated Ringer's溶液或生理食鹽水為主"],"answer":2,"image":""},{"id":"md5-110-1-51","subject":"md5","topic":"神經外科","meta":"110年第1次第51題","year":110,"session":1,"number":51,"question":"一名30歲男性，車禍後不省人事，送至醫院急診，此時已經恢復意識但發現左手腳無力，右側麻痛，仔細檢查後確定左手前臂尚可彎曲但難以抓握或伸直，右手腳對溫度和痛覺較不敏感。對於此病人的相關問題，下列敘述何者正確？","options":["(A) 絕大多數的脊椎損傷位於腰椎","(B) C6的傷害一定會造成立即的呼吸衰竭","(C) central cord syndrome對下肢的影響大過上肢","(D) 對於脊髓損傷核磁共振檢查優於電腦斷層檢查"],"answer":3,"image":""},{"id":"md5-110-1-52","subject":"md5","topic":"神經外科","meta":"110年第1次第52題","year":110,"session":1,"number":52,"question":"承上題，此病人最可能的診斷是：","options":["(A) Brown-Séquard syndrome","(B) central cord syndrome","(C) thalamic hemorrhage","(D) left humerus fracture"],"answer":0,"image":""},{"id":"md5-110-1-53","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第1次第53題","year":110,"session":1,"number":53,"question":"一位60歲女性到門診就醫，主訴頸部摸到腫塊，理學檢查發現左側甲狀腺有一2公分大小結節。請依前述情形回答以下3題。有些合併症狀會使臨床醫師較易懷疑此甲狀腺腫瘤為惡性，但下列何者除外？","options":["(A) 聲音沙啞","(B) 心悸","(C) 吞嚥困難","(D) 頸部淋巴腺腫大"],"answer":1,"image":""},{"id":"md5-110-1-54","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第1次第54題","year":110,"session":1,"number":54,"question":"頸部超音波證實左側甲狀腺有一實心腫瘤，甲狀腺細針穿刺細胞學檢查顯示為濾泡型腫瘤（follicular neoplasm）。根據2009年版Bethesda甲狀腺細胞學診斷系統，該腫瘤為惡性的機率大約多少？","options":["(A) 5～15%","(B) 15～30%","(C) 60～75%","(D) 97～99%"],"answer":1,"image":""},{"id":"md5-110-1-55","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第1次第55題","year":110,"session":1,"number":55,"question":"經與外科醫師討論後，患者接受左側甲狀腺切除手術，病理檢查證實為濾泡變異型乳突癌（follicular variant of papillary thyroid cancer）。下列何者不會影響患者的病理分期（TNM stage）？","options":["(A) 年齡","(B) 性別","(C) 侵犯甲狀腺旁肌肉","(D) 腫瘤大小"],"answer":1,"image":""},{"id":"md5-110-1-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第1次第56題","year":110,"session":1,"number":56,"question":"有關腎衰竭病患會造成腎性骨發育不全（renal osteodystrophy）之敘述，下列何者最不適當？","options":["(A) 腎絲球功能不良會使血磷值過低","(B) 活性維生素D的製造減少","(C) 血鈣過低導致次發性副甲狀腺機能亢進","(D) 副甲狀腺機能亢進導致骨吸收（bone resorption）增強，可能導致骨骼出現褐色瘤（brown tumor）"],"answer":0,"image":""},{"id":"md5-110-1-57","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第1次第57題","year":110,"session":1,"number":57,"question":"有關軟骨肉瘤（chondrosarcoma）的敘述，下列何者最正確？","options":["(A) 好發在10～20歲的青少年","(B) 原發性軟骨肉瘤（primary chondrosarcoma）生長速度較慢，X光檢查常可見到Codman氏三角骨膜反應（Codman triangle periosteal reaction）","(C) 正確惡性度分級常需要綜合臨床症狀、放射線學及組織病理學等三方證據","(D) 原發性軟骨肉瘤（primary chondrosarcoma）的治療流程為：術前放射治療（radiotherapy）及廣泛性腫瘤切除"],"answer":2,"image":""},{"id":"md5-110-1-58","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"110年第1次第58題","year":110,"session":1,"number":58,"question":"關於橈骨頭部骨折（radial head fracture）之敘述，下列何者最不適當？","options":["(A) 多數的受傷機轉是跌倒時手肘伸直手掌撐地（fall onto the outstretched hand）造成","(B) 若未合併韌帶損傷或其他骨折，則大部分單純橈骨頭部骨折（isolated radial head fracture）可採用保守治療","(C) 骨折後若前臂旋後（supination）和旋前（pronation）的範圍受限，即符合手術治療的適應症","(D) 合併關節內的骨折塊或游離小體（loose bodies）時，可採保守治療"],"answer":3,"image":""},{"id":"md5-110-1-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"110年第1次第59題","year":110,"session":1,"number":59,"question":"關於石膏（casting）及副木（splinting）固定的原則，下列敘述何者最適當？","options":["(A) 嚴重足踝扭傷使用副木固定時，應將足踝固定在蹠屈30度（30 degrees of plantar flexion），以獲得最佳固定效果","(B) 某病患足踝骨折後以石膏固定，兩天後抱怨石膏固定處有疼痛情形。此時為避免骨折移位，不可立刻拆除石膏，應密切觀察患部一週，若仍持續疼痛，始可拆除石膏檢視患部","(C) 治療遠端橈骨骨折（distal radial fracture）時，若擔心受傷初期軟組織腫脹過於嚴重，可先使用背側副木（dorsal slab or splint）固定，待一至二週消腫後，再換成石膏固定","(D) 使用石膏固定時，應將石膏材料浸泡在攝氏60度以上的熱水中，不可使用室溫的水，以避免石膏硬化的時間過久，影響骨折復位的固定"],"answer":2,"image":""},{"id":"md5-110-1-60","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"110年第1次第60題","year":110,"session":1,"number":60,"question":"有關肩關節的前側不穩定性之不安測試（apprehension test）的敘述，下列何者最不適當？","options":["(A) 病人可採平躺或坐姿方式進行檢查","(B) 病人平躺時，檢查者宜站在病人側方","(C) 病人採坐姿時，檢查者宜站在病人後方","(D) 測試時，將肩關節從外展（abduction）90度及旋轉0度（neutral rotation），往內旋（internal rotation）做到最大極限"],"answer":3,"image":""},{"id":"md5-110-1-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第1次第61題","year":110,"session":1,"number":61,"question":"有關兒童的股骨頭骨骺滑移（slipped capital femoral epiphysis）的敘述，下列何者最適當？","options":["(A) 通常好發於學齡前兒童","(B) 兩側發生機率約75%","(C) 骨骼年齡通常比生理年齡早熟","(D) 通常與荷爾蒙或內分泌異常有關"],"answer":3,"image":""},{"id":"md5-110-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第1次第62題","year":110,"session":1,"number":62,"question":"跌倒時若手臂伸直且手掌直接著地，因而導致腕骨（carpal bone）骨折且腕部的橈側疼痛，其骨折最常見的是下列何者？","options":["(A) 月狀骨（lunate）","(B) 舟狀骨（scaphoid）","(C) 大多角骨（trapezium）","(D) 小多角骨（trapezoid）"],"answer":1,"image":""},{"id":"md5-110-1-63","subject":"md5","topic":"神經外科","meta":"110年第1次第63題","year":110,"session":1,"number":63,"question":"一位55歲女性走路步態穩定，主訴近半年來頸部疼痛，且會延伸到右肩三角肌（deltoid muscle）的部位。檢查發現將手臂舉過頭及維持外展（abduction）姿勢時會減輕疼痛，但將頭後仰及轉向右側時會引發疼痛。下列敘述何者最適當？","options":["(A) 具有明顯的上運動神經元徵象（upper motor neuron sign）","(B) 主要因右肩旋轉肌袖（rotator cuff）及三角肌肌腱發炎引起疼痛","(C) 主要因頸椎神經根受到壓迫引起疼痛","(D) 大部分無法單純靠止痛消炎藥物及復健治療改善症狀"],"answer":2,"image":""},{"id":"md5-110-1-64","subject":"md5","topic":"泌尿-結石與感染","meta":"110年第1次第64題","year":110,"session":1,"number":64,"question":"一位懷孕十週的30歲女士因為急性腹痛就診，尿液檢查呈現顯微性血尿以及尿路感染，超音波檢查發現左腎中度積水，疑似左輸尿管結石造成阻塞以及感染，則下列何種治療最不適宜？","options":["(A) 施行經皮腎臟造瘻（percutaneous nephrostomy, PCN）引流","(B) 施行雙J導管放置（double-J ureteral stent）處置","(C) 即刻施行輸尿管鏡檢查以及雷射碎石手術或體外震波碎石術","(D) 補充液體並觀察症狀以及追蹤腎積水嚴重度"],"answer":2,"image":""},{"id":"md5-110-1-65","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第1次第65題","year":110,"session":1,"number":65,"question":"下列有關腎上腺瘤（adrenal tumor）之敘述，何者錯誤？","options":["(A) Cushing's syndrome與過量分泌cortisol有關，大多數發生於bilateral adrenocortical hyperplasia","(B) 病人接受雙側腎上腺切除（bilateral adrenalectomy）術後，不需補充cortisol","(C) mitotane可以用來治療腎上腺癌","(D) Cushing's syndrome常有高血壓及肥胖"],"answer":1,"image":""},{"id":"md5-110-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"110年第1次第66題","year":110,"session":1,"number":66,"question":"有關晚期腎細胞癌新發展之生物醫療製劑，下列敘述何者錯誤？","options":["(A) Tyrosine kinase活性與腎細胞癌von Hippel-Lindau基因突變有關","(B) Sunitinib、bevacizumab、sorafenib為VEGF，PDGF血管新生因子之抑制劑","(C) VEGF抑制劑之最主要副作用為甲狀腺功能低下","(D) Temsirolimus為VEGF路徑中mTOR之抑制劑"],"answer":2,"image":""},{"id":"md5-110-1-67","subject":"md5","topic":"泌尿-腫瘤","meta":"110年第1次第67題","year":110,"session":1,"number":67,"question":"李先生65歲，最近健康檢查發現前列腺特定抗原（prostate-specific antigen）值為10.5 ng/mL，游離型PSA比值為15%，肛門指檢並沒有摸到任何前列腺硬結節，經直腸超音波檢查發現前列腺有一低回音病灶（hypoechoic lesion），下列建議何者最適當？","options":["(A) 先觀察一年後再檢查PSA","(B) 建議進行前列腺根除手術（radical prostatectomy）","(C) 安排經直腸超音波導引前列腺切片檢查","(D) 立刻開始給與荷爾蒙治療"],"answer":2,"image":""},{"id":"md5-110-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"110年第1次第68題","year":110,"session":1,"number":68,"question":"分布在人類膀胱逼尿肌（detrusor muscle）的蕈毒素受體亞型（muscarinic receptor subtype）主要是：","options":["(A) M1 and M2","(B) M2 and M3","(C) M1 and M3","(D) M1 and M4"],"answer":1,"image":""},{"id":"md5-110-1-69","subject":"md5","topic":"泌尿-結石與感染","meta":"110年第1次第69題","year":110,"session":1,"number":69,"question":"急性單純膀胱炎（acute uncomplicated cystitis）最不會出現下列那一項症狀？","options":["(A) 頻尿與急尿","(B) 血尿","(C) 解尿灼熱與疼痛","(D) 發燒"],"answer":3,"image":""},{"id":"md5-110-1-70","subject":"md5","topic":"泌尿-結石與感染","meta":"110年第1次第70題","year":110,"session":1,"number":70,"question":"一位45歲男性因左側腰痛，發燒到39度，至急診求診。電腦斷層掃描發現左側上1/3輸尿管有一1cm結石，合併腎積水，右腎正常。病人尿量減少，血壓偏低（95/65 mmHg），血液白血球19,500/cumm，CRP值16 mg/dL。急診醫師立即抽血及收集尿液做細菌培養，給與靜脈輸液及抗生素治療。下列後續處置何者較適當？","options":["(A) 立即進行左側輸尿管鏡碎石手術","(B) 立即安排左側經皮腎臟引流","(C) 繼續使用抗生素保守治療","(D) 給與利尿劑促進排尿及排石"],"answer":1,"image":""},{"id":"md5-110-1-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"110年第1次第71題","year":110,"session":1,"number":71,"question":"治療勃起功能障礙的病人，必須注意使用PDE5 inhibitors的禁忌，下列何種狀況的病人可以安全使用PDE5 inhibitors？","options":["(A) 最近6個月發生心肌梗塞","(B) 嚴重肝功能損傷達Child-Pugh C者","(C) 大動脈狹窄（aortic stenosis）","(D) 服用rifampin的病人"],"answer":3,"image":""},{"id":"md5-110-1-72","subject":"md5","topic":"泌尿-腫瘤","meta":"110年第1次第72題","year":110,"session":1,"number":72,"question":"45歲女性病人接受年度健康檢查，發現左腎腫瘤，下圖為注射對比劑之腎臟電腦斷層攝影（computed tomography of kidneys），最可能之診斷為何？","options":["(A) renal cell carcinoma","(B) renal lymphoma","(C) renal urothelial carcinoma","(D) renal angiomyolipoma"],"answer":3,"image":"md5-110-1-72.jpeg"},{"id":"md5-110-1-73","subject":"md5","topic":"心臟血管外科","meta":"110年第1次第73題","year":110,"session":1,"number":73,"question":"50歲男性至急診就醫，主訴突發性胸痛持續逾半小時，胸部電腦斷層影像如附圖，正確診斷為：","options":["(A) Stanford A型主動脈內皮血腫（Stanford Type A intramural hematoma）","(B) Stanford B型主動脈內皮血腫（Stanford Type B intramural hematoma）","(C) Stanford B型主動脈剝離（Stanford Type B aortic dissection）","(D) DeBakey第三型主動脈剝離（DeBakey Type III aortic dissection）"],"answer":0,"image":"md5-110-1-73.jpeg"},{"id":"md5-110-1-74","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第1次第74題","year":110,"session":1,"number":74,"question":"23歲男性無特殊病史，近二個月來，他覺得舉重物時右髖部附近會痛，附圖為X光攝影，最可能的診斷為何？","options":["(A) fibrous dysplasia","(B) chondroblastoma","(C) osteogenic sarcoma","(D) eosinophilic granuloma"],"answer":0,"image":"md5-110-1-74.jpeg"},{"id":"md5-110-1-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第1次第75題","year":110,"session":1,"number":75,"question":"45歲男性因機車車禍被送至急診，病人主訴後頸、腹部及右下肢疼痛。身體檢查發現雙手感覺麻木、上腹部大片瘀青、右大腿5公分撕裂傷滲血、右小腿外觀變形，應優先執行下列何種處置？","options":["(A) 帶上頸圈","(B) 安排腹部電腦斷層","(C) 傷口加壓止血","(D) 副木固定右小腿"],"answer":0,"image":""},{"id":"md5-110-1-76","subject":"md5","topic":"泌尿-腫瘤","meta":"110年第1次第76題","year":110,"session":1,"number":76,"question":"有關血尿的敘述，下列何者最正確？","options":["(A) 兒童的血尿常見原因是腎絲球腎炎","(B) 良性的前列腺肥大不會造成血尿","(C) 血尿最常見的原因是腎或泌尿道腫瘤","(D) 無痛的血尿常見於泌尿道感染"],"answer":0,"image":""},{"id":"md5-110-1-77","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"110年第1次第77題","year":110,"session":1,"number":77,"question":"一位65歲女性，因下頷骨脫位（mandible dislocation）至急診求治，下列敘述何者錯誤？","options":["(A) 脫位型態以前脫位（anterior dislocation）最常見","(B) 診斷是以臨床症狀為主","(C) 復位後只要病人能立即闔上嘴巴，通常無須再安排X光攝影追蹤","(D) 於急診復位後常無法恢復進食"],"answer":3,"image":""},{"id":"md5-110-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"110年第1次第78題","year":110,"session":1,"number":78,"question":"近年來，家庭暴力頻傳，外科醫師常常會遇到疑似的病例，根據家庭暴力防治法之規定，下列何者錯誤？","options":["(A) 醫事人員在執行職務時知有疑似家庭暴力情事者，應立即通報當地主管機關，至遲不得逾24小時","(B) 通報疑似家庭暴力情事者，是警察的責任，跟醫師無關","(C) 醫療機構對於家庭暴力之被害人，不得無故拒絕診療及開立驗傷診斷書","(D) 醫事人員為防治家庭暴力行為或保護家庭暴力被害人之權益，有受到身體或精神上不法侵害之虞者，得請求警察機關提供必要之協助"],"answer":1,"image":""},{"id":"md5-110-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"110年第1次第79題","year":110,"session":1,"number":79,"question":"歐陽先生是一位70歲男性，膝下無子女，平時在家中照顧患有重度失智症的妻子，最近因為嚴重頭痛來院檢查，發現自己有一中腦動脈之動脈瘤。你是一位神經外科醫師，你建議他開刀夾除動脈瘤，但也告訴他手術有死亡的風險。歐陽先生決定先不手術，回去想一想再說。沒想到就在一週後，他因為動脈瘤出血昏迷被送到急診室，若不緊急手術歐陽先生必會死亡，但是卻無法聯絡到任何家屬以諮詢意見，如何處理最適當？","options":["(A) 歐陽先生先前已拒絕手術了，因此不應該施行緊急手術","(B) 不管歐陽先生事前有沒有聲明拒絕緊急手術，依照你的專業判斷該做手術就該進行手術","(C) 在沒有聯絡到家屬，歐陽先生此時也無行為能力，之前又決定先不手術的情況下，最好不要開刀","(D) 歐陽先生先前雖拒絕手術，是因為他沒有考量過緊急狀況，所以歐陽先生先前沒拒絕緊急手術的話，應施行手術"],"answer":3,"image":""},{"id":"md5-110-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"110年第1次第80題","year":110,"session":1,"number":80,"question":"某成年男患者急性右側胸痛被送到急診室，症狀及檢查結果均明確顯示是小範圍自發性氣胸。患者意識清醒，生命徵兆穩定，但拒絕插胸管減壓引流或住院觀察，堅持要回家。此時醫生應該：","options":["(A) 行使醫生自主權，為治病救人避免發生意外，強行把患者留院觀察","(B) 尊重病患自主權，仍應盡力勸導患者住院，無效時，請他辦好相關手續後再准其離院","(C) 尊重病患自主權，同意病患回家","(D) 尊重病患自主權，但應盡力勸導患者住院，勸導無效時行使干涉權"],"answer":1,"image":""},{"id":"md5-110-2-1","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"對於人類白血球組織抗原（human leukocyte antigen, HLA）的描述，下列何者正確？①HLA antigens位在人類第九對染色體的短臂上 ②HLA完全相同的腎臟移植可以得到比較好的預後 ③HLA-DP，HLA-DQ和HLA- DR是屬於第二型主要組織相容性複合體（major histocompatibility complex, MHC） ④第一型主要組織相容性複合體（MHC Class I主要是表現在B淋巴球（lymphocytes），樹突細胞（dendritic cells），內皮細胞（endothelial cells）和活化的（activated）T細胞 ⑤ HLA敏化作用（sensitization）會因為懷孕，輸血和曾經接受過移植而產生","options":["(A) ②③④","(B) ①③④","(C) ②③⑤","(D) ①②⑤"],"answer":2,"image":""},{"id":"md5-110-2-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"針對外傷病患的初始評估（initial assessment），首先會進行primary survey；下列對於primary survey的敘述，何者錯誤？","options":["(A) 第一步驟是呼吸道（airway）暢通的檢查，操作時須同時注意cervical spine protection","(B) 在做breathing檢查時，如懷疑有tension pneumothorax發生時，例如頸部氣管偏向正常側，患側聽不到呼吸聲（breathing sound），則必須照一張胸部X光片，確定診斷後，再插胸管引流","(C) 在做circulation評估時，可用腹部超音波檢查，迅速detect intra-peritoneal bleeding","(D) 在做disability及exposure，要評估病患的Glasgow Coma Scale（GCS）及可能存在的hypothermia"],"answer":1,"image":""},{"id":"md5-110-2-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"54歲男性，體重65公斤，因直腸癌接受根治性直腸全切除併大腸肛門吻合術及迴腸造瘻術，術後恢復良好，於術後第三天開始由口進食。但術後第八天主訴全身倦怠無力，理學檢查發現血壓90/40 mmHg，心跳100次/分，o呼吸16次/分，體溫36.5Ｃ，每日尿量為800毫升，每日迴腸造口排出量約3,000毫升。生化檢查發現血中鈉離子125 mEq/L、鉀離子2.5 mEq/L，全血血球計數為白血球15,000 /μL、血紅素8.0 g/dL、血小板150,000/μL。此時造成病人倦怠感最有可能的原因為何？","options":["(A) 腎上腺功能不全合併電解質不平衡","(B) 急性失血合併低血壓","(C) 腹腔內感染合併輕微敗血症","(D) 大量體液自迴腸造口流失而致電解質不平衡"],"answer":3,"image":""},{"id":"md5-110-2-4","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"腎臟移植後一個月內，何種感染較少發生？","options":["(A) B型肝炎活化","(B) 傷口感染","(C) 泌尿道感染","(D) 隱球菌感染（cryptooccal infection）"],"answer":3,"image":""},{"id":"md5-110-2-5","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"傷口癒合過程中，下列細胞出現於傷口的先後順序（time course）何者正確？","options":["(A) neutrophil→macrophage→fibroblast→lymphocyte","(B) neutrophil→fibroblast→lymphocyte→macrophage","(C) macrophage→lymphocyte→fibroblast→neutrophil","(D) lymphocyte→fibroblast→neutrophil→macrophage"],"answer":0,"image":""},{"id":"md5-110-2-6","subject":"md5","topic":"整形重建外科","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"有關瘢痕瘤（Keloid），下列敘述何者錯誤？","options":["(A) 較易發生在臉部、低於鎖骨的軀幹部及下肢","(B) 較常發生在皮膚顏色較深的人種例如非裔美國人、亞洲人及拉丁裔人","(C) 其盛行率約15%～20%","(D) 目前仍無法預防，不論內科或外科療法效果皆不彰"],"answer":0,"image":""},{"id":"md5-110-2-7","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"根據美國創傷外科學會分級（American Association for the Surgery of Trauma grading scales），下列對於肝臟創傷的分級何者錯誤？","options":["(A) 裂傷深度1公分以內，肝包膜下血腫覆蓋達面積10%以下為第一級","(B) 裂傷深度3公分以上為第三級","(C) 整個肝葉都為包膜下血腫覆蓋，可能為第五級","(D) 總共分五級"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第7題一律給分。 (原公告答案 D)"},{"id":"md5-110-2-8","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"下列何項關於人體器官移植的陳述是錯誤的？","options":["(A) 器官移植術後的排斥主要是跟人類白血球抗原（human leukocyte antigen）有關，此抗原基因在第六對染色體上","(B) 器官移植術後的超急性排斥（hyperacute rejection）主要和捐贈者體內已存在抗體（preformed antibody）有關","(C) 同種識別（allorecognition）可經由直接或間接路徑（direct or indirect pathway）發生，都是經由T細胞（T- cell）活化造成","(D) 器官移植術後的急性排斥（acute rejection）依機轉主要分為細胞型排斥（cellular rejection）和體液型排斥（humoral rejection）"],"answer":1,"image":""},{"id":"md5-110-2-9","subject":"md5","topic":"神經外科","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"關於intraspinal tumors的敘述，下列何者正確？","options":["(A) 最常見的extradural tumor為metastatic tumor","(B) 最常見的intradural extramedullary tumor為metastatic tumor","(C) 最常見的intramedullary tumor為metastatic tumor","(D) 最常見的intramedullary tumor為meningioma"],"answer":0,"image":""},{"id":"md5-110-2-10","subject":"md5","topic":"神經外科","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"脈絡叢乳頭狀瘤（choroid plexus papillomas）造成腦室擴大（ventricular enlargement）的原因，不包括下列何者？","options":["(A) 腫瘤長大（tumor growth）","(B) 後脈絡叢血管被腫瘤壓迫（posterior choroid artery compression by tumor）","(C) 腦脊髓液過度製造（excessive production of CSF）","(D) 出血造成蜘蛛膜炎以致減少腦脊髓液吸收（decreased absorption of CSF from hemorrhage-induced arachnoiditis）"],"answer":1,"image":""},{"id":"md5-110-2-11","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"下列關於吊頸骨折（Hangman's fracture）之敘述何者正確？","options":["(A) 第一頸椎側體（lateral mass）爆裂性骨折（bursting fracture）","(B) 第二頸椎關節小面（pars interarticularis fracture）骨折移位","(C) 第三、四頸椎伸張性損傷","(D) 雙側性關節面鎖住（locked facet）"],"answer":1,"image":""},{"id":"md5-110-2-12","subject":"md5","topic":"整形重建外科","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"關於燒傷病人焦痂切開術（escharotomy）之敘述，何者錯誤？","options":["(A) 肢體的整圈全層燒燙傷，是手術的適應症","(B) 胸廓的全層燒燙傷，造成呼吸困難，是手術的適應症","(C) 焦痂切開術（escharotomy）需將筋膜切開","(D) 緊急時可以在一般病房病床邊進行（bedside procedure）"],"answer":2,"image":""},{"id":"md5-110-2-13","subject":"md5","topic":"整形重建外科","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"關於手部先天性併指症（syndactyly）的敘述，何者錯誤？","options":["(A) 可單獨發生，也有可能合併其他症候群，如Poland syndrome","(B) 最常受影響的手指，是拇指與食指之併指","(C) 手指的成形在胚胎發育過程中，牽涉細胞凋亡（apoptosis）和BMP-4（bone morphogenic protein）","(D) 對於完全型併指（complete syndactyly）之指蹼（webspace）的重建，背側苜蓿葉型皮瓣（dorsal clover leaf flap），是一種實用的選擇"],"answer":1,"image":""},{"id":"md5-110-2-14","subject":"md5","topic":"整形重建外科","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"下列何種情況最不適合斷指重接（replantation）手術？","options":["(A) 拇指（thumb）截斷","(B) 單一手指的多段（multiple level）截斷","(C) 幼兒斷指","(D) 單一手指的遠端指節（distal phalanx）截斷"],"answer":1,"image":""},{"id":"md5-110-2-15","subject":"md5","topic":"整形重建外科","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"下半身麻痺的病人坐在輪椅上，常有機會發生坐骨部壓瘡，在坐姿時坐骨隆凸部位受到多少壓力及最少持續多久壓力時間較容易開始發生壓瘡？","options":["(A) 60 mmHg，0.5小時以上","(B) 60 mmHg，1小時以上","(C) 30 mmHg，0.5小時以上","(D) 30 mmHg，1小時以上"],"answer":1,"image":""},{"id":"md5-110-2-16","subject":"md5","topic":"整形重建外科","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"22歲的王同學是八仙塵爆的燒傷患者，這次來門診求助主要是因為手腕背側的帶狀疤痕攣縮影響彎曲活動，醫師建議施予simple Z-plasty疤痕鬆懈手術（如附圖），如果術後預計比原先增加75%的延展長度，應設計多少角度的simple Z-plasty？","options":["(A) Simple 30°-angle Z-plasty","(B) Simple 45°-angle Z-plasty","(C) Simple 60°-angle Z-plasty","(D) Simple 90°-angle Z-plasty"],"answer":2,"image":"md5-110-2-16.jpeg"},{"id":"md5-110-2-17","subject":"md5","topic":"心臟血管外科","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"下列那一條血管不適合做為冠狀動脈繞道手術（coronary artery bypass grafting）之繞道管道（conduit）？","options":["(A) 股動脈（femoral artery）","(B) 內乳動脈（internal mammary artery）或稱內胸動脈（internal thoracic artery）","(C) 大隱靜脈（greater saphenous vein）","(D) 橈動脈（radial artery）"],"answer":0,"image":""},{"id":"md5-110-2-18","subject":"md5","topic":"心臟血管外科","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"下列何者不是嚴重主動脈瓣閉鎖不全（severe aortic insufficiency）之手術適應症？","options":["(A) 急性嚴重主動脈瓣閉鎖不全（acute severe aortic insufficiency）併有休克之病患","(B) 有症狀之慢性嚴重主動脈瓣閉鎖不全（chronic severe aortic insufficiency），不論有無心臟功能不全","(C) 無症狀之慢性嚴重主動脈瓣閉鎖不全（chronic severe aortic insufficiency），且左心室末期收縮直徑（LVESD）30mm之病患","(D) 無症狀之慢性嚴重主動脈瓣閉鎖不全（chronic severe aortic insufficiency），且有左心室功能不全，左心室射出率低於50%"],"answer":2,"image":""},{"id":"md5-110-2-19","subject":"md5","topic":"心臟血管外科","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"78歲男性抽菸且合併高血壓，糖尿病病史，接受都卜勒分段血壓（Dopper segmental pressure）檢查之結果如附圖。則下列敘述何者錯誤？","options":["(A) 間歇性跛行或潰瘍不癒合以左下肢為主","(B) 狹窄之可能部位位於左側腸骨動脈或股動脈","(C) 雙側下肢血管，左側足背動脈脈搏觸診較右側微弱","(D) 如需進行膝下繞道手術時，以聚四氟乙烯（polytetrafluoroethylene, PTFE）人工血管植入為主"],"answer":3,"image":"md5-110-2-19.jpeg"},{"id":"md5-110-2-20","subject":"md5","topic":"小兒外科","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"有關單一心室先天性心臟病之敘述，下列何者錯誤？","options":["(A) 左心室發育不全症候群（hypoplastic left heart syndrome）和三尖瓣發育不全（tricuspid atresia）皆適合行Fontan術式","(B) Bidirectional Glenn shunt可以是Fontan術式之階段手術，一般建議在第一階段手術後3至6個月左右施行","(C) 進行Bidirectional Glenn shunt術式時，保留動脈到肺動脈之分流，可增加血氧濃度，且可提高單心室之長期存活率","(D) Norwood術式是單一心室之第一階段術式，可以採用心室到肺動脈之分流來取代主動脈到肺動脈之分流"],"answer":2,"image":""},{"id":"md5-110-2-21","subject":"md5","topic":"心臟血管外科","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"下列先天性心臟病，何者不是發紺性（cyanotic heart disease）心臟病？","options":["(A) 法洛氏四重症（tetralogy of Fallot）","(B) 大動脈轉位（transposition of great arteries）","(C) 肺動脈吊索（pulmonary artery sling）","(D) 三尖瓣發育不全（tricuspid atresia）"],"answer":2,"image":""},{"id":"md5-110-2-22","subject":"md5","topic":"胸腔外科","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"關於惡性肋膜積液（pleural effusion）的敘述，何者正確？","options":["(A) 在女性中，最常因為乳癌產生惡性肋膜積液","(B) 引流惡性肋膜積液是必要的，而且可以提升病人存活率","(C) 如果因為肺癌腫瘤產生的肋膜積液，不論惡性或良性，皆不適合手術治療","(D) 如果惡性肋膜積液經引流，仍有大量積液，可以考慮肋膜沾黏術，其中以滑石粉（talc）沾黏效果最差"],"answer":0,"image":""},{"id":"md5-110-2-23","subject":"md5","topic":"胸腔外科","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"關於先天性肺部疾病，下列敘述何者錯誤？","options":["(A) 支氣管囊腫（bronchogenic cyst）無症狀不需要手術切除","(B) 肺葉肺氣腫（lobar emphysema）為最常切除的肺部先天性囊腫疾病","(C) 肺內游離肺（intralobar pulmonary sequestration）常發於下肺葉，血液回流到肺靜脈","(D) 肺血管吊索（pulmonary vascular sling）常伴有喘鳴發生"],"answer":0,"image":""},{"id":"md5-110-2-24","subject":"md5","topic":"胸腔外科","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"關於肺癌檢查的敘述，下列何者正確？","options":["(A) 肺癌患者均應例行性接受腦部MRI檢查","(B) 鱗狀細胞癌比腺癌容易由痰液細胞學檢驗出來","(C) 肺部低密度電腦斷層檢查，無法減少高危險群的肺癌死亡率","(D) 正子攝影檢查為癌症篩檢的良好替代方法"],"answer":1,"image":""},{"id":"md5-110-2-25","subject":"md5","topic":"消化器外科","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"有關食道疾病的敘述，下列何者正確？","options":["(A) Zenker憩室（Zenker diverticulum）主要以測壓機（manometry）診斷","(B) 中段食道憩室（midesophageal diverticula）主要為位於右側的真性憩室（true diverticulum）","(C) 胃食道逆流的胃底折疊術（fundoplication）應做360度的包埋，效果較佳","(D) 食道腐蝕性傷害在無胃鏡檢查下，應立即放置鼻胃管引流"],"answer":1,"image":""},{"id":"md5-110-2-26","subject":"md5","topic":"消化器外科","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"下列關於食道穿孔之敘述，何者不適當？","options":["(A) 一般建議，先以食道鏡檢查作為優先診斷工具","(B) 如經證實，則馬上給予適當治療不可延誤","(C) 如穿孔發生在12小時內，則可考慮修補縫合","(D) 情況不佳的年長患者，可考慮stenting"],"answer":0,"image":""},{"id":"md5-110-2-27","subject":"md5","topic":"胸腔外科","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"下列縱膈腔腫瘤相關症狀，何者錯誤？","options":["(A) neurofibroma - von Recklinghausen's disease","(B) carcinoid - carcinoid syndrome","(C) thymoma - myasthenia gravis","(D) thymoma - vertebral anomalies"],"answer":3,"image":""},{"id":"md5-110-2-28","subject":"md5","topic":"消化器外科","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"下列何者不是常見化膿性肝膿瘍之致病原因？","options":["(A) 膽道疾病","(B) 經肝門靜脈血流感染","(C) 經肝動脈感染（菌血症）","(D) 腫瘤內細胞壞死"],"answer":3,"image":""},{"id":"md5-110-2-29","subject":"md5","topic":"消化器外科","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"肝切除術後，下列何者不是病患術後照料應該注意的事項？","options":["(A) 術後若腹水流失嚴重，不宜限制病患水分及鹽分的輸入","(B) 術後數日視情況給與白蛋白製劑及新鮮冷凍血漿","(C) 術後數小時內體溫低，宜用加溫床維持體溫","(D) 術後血糖會降低居多，宜注意維持適當血糖濃度"],"answer":0,"image":""},{"id":"md5-110-2-30","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"病人接受幽門保留式胰十二指腸切除手術，術中失血量為1000 ml，術後當天在恢復室內記錄該病人的引流管流出鮮紅色的液體，流量為200 mL/小時，持續4小時，血紅素從13 mg/dL降至8 mg/dL。同時病人的血壓從130/80 mmHg降至90/60 mmHg。下一步應如何處置？","options":["(A) 立即執行剖腹止血","(B) 給與2000 ml colloid輸液維持病人生命徵象","(C) 檢查病人的血液中凝血時間並輸紅血球及新鮮血漿","(D) 給與病人輸全血"],"answer":0,"image":""},{"id":"md5-110-2-31","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"一位82歲男性病人，過去病史包括有高血壓、糖尿病、鬱血性心衰竭、心律不整（atrial fibrillation）、升結腸癌手術後；因為心肌梗塞（myocardial infarction）作過心導管並放了2根支架。在心臟內科住院時，發現病人腹部手術的傷口有一可回復性之腹壁疝氣（reducible ventral hernia），下列處置何者正確？","options":["(A) 腹壁疝氣手術必須於全身麻醉下施行，但因為已經讓心臟內科醫師照顧很好，可以不用請麻醉科醫師評估病人狀況","(B) 檢視病人目前用藥並不重要，可以不用停止使用抗凝劑","(C) 腹部手術前後致死的原因，絕對與心血管疾病都無關","(D) 待心肌梗塞發生6個月後再考慮手術"],"answer":3,"image":""},{"id":"md5-110-2-32","subject":"md5","topic":"消化器外科","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"下列有關小腸的敘述，何者錯誤？","options":["(A) 具有消化、吸收、內分泌的功能，且為體內重要的免疫器官","(B) 腸道阻塞會因外因性、內因性跟管腔內的病因所造成。最常見的原因是術後沾黏","(C) 腸胃道基質瘤（gastrointestinal stromal tumor）是從腸道的間質組織生出，為小腸最常見的惡性腫瘤，容易復發並轉移","(D) 腸胃道基質瘤不常經由淋巴轉移，所以在針對腸胃道基質瘤進行手術時，不需要特別進行淋巴廓清手術"],"answer":2,"image":""},{"id":"md5-110-2-33","subject":"md5","topic":"消化器外科","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"膽結石是膽囊及膽道最常見的問題，下列有關膽結石的敘述何者正確？","options":["(A) 大部分膽結石是沒有症狀的，但是考慮到手術的進步及其可能引發的併發症，只要診斷有膽結石，應該就要建議病人接受手術治療","(B) 膽結石引發的急性膽囊炎，主要是因為膽囊管被阻塞而引發的後續發炎，可以藉由超音波確診，其診斷敏感性可達八成以上，特異性可達九成以上","(C) 若膽結石掉落到總膽管後，就不需要擔心，因石頭一定會自然排除，症狀會得到緩解","(D) 目前進行手術大部分是利用腹腔鏡進行膽囊切除，而此手術最常見的併發症為術中膽囊破裂導致結石掉落腹腔造成反覆感染"],"answer":1,"image":""},{"id":"md5-110-2-34","subject":"md5","topic":"消化器外科","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"下列何項荷爾蒙不是由胃的細胞（gastric cell）分泌？","options":["(A) somatostatin","(B) gastrin-releasing peptide","(C) adiponectin","(D) ghrelin"],"answer":2,"image":""},{"id":"md5-110-2-35","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"下列何者是目前胰臟移植手術的適應症？","options":["(A) 第一型糖尿病，血糖控制穩定","(B) 第二型糖尿病，服用口服降血糖藥控制且合併腎衰竭","(C) 第一型糖尿病合併腎衰竭","(D) 第一型糖尿病，尚未產生糖尿病合併症"],"answer":2,"image":""},{"id":"md5-110-2-36","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"下列何者不是供應甲狀腺血液之動脈？","options":["(A) 上甲狀腺動脈（superior thyroid artery）","(B) 中甲狀腺動脈（middle thyroid artery）","(C) 下甲狀腺動脈（inferior thyroid artery）","(D) 最下甲狀腺動脈（thyroidea ima artery）"],"answer":1,"image":""},{"id":"md5-110-2-37","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"一位35歲女性被診斷出患有原發性副甲狀腺功能亢進（primary hyperparathyroidism），24小時尿液的鈣排出量為450 mg/day，頸部超音波發現甲狀腺有一2公分大結節，血液中抑鈣素（calcitonin）明顯升高，臨床上應懷疑為下列何項遺傳性疾病？","options":["(A) multiple endocrine neoplasia type 1","(B) multiple endocrine neoplasia type 2A","(C) familial hypocalciuric hypercalcemia","(D) hereditary hyperparathyroidism-jaw tumor syndrome"],"answer":1,"image":""},{"id":"md5-110-2-38","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"有關乳房超音波（ultrasonography）與乳房X光攝影（mammography）的比較，下列敘述何者錯誤？","options":["(A) 乳房超音波較mammography易偵測到microcalcifications","(B) mammography sensitivity在50歲以下的婦女較50歲以上婦女差","(C) 婦女乳腺緻密者（dense breast），mammography sensitivity差","(D) 50歲以上無症狀健康婦女的乳癌篩檢應做mammography"],"answer":0,"image":""},{"id":"md5-110-2-39","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"無症狀婦女乳房X光攝影（mammography）篩檢看到不確定性質叢聚顯微鈣化（clustered microcalcifications），影像醫師判斷惡性可能性至少超過2%，為BI-RADS category 4，超音波檢查正常，為BI-RADS category 1，下列相關敘述何者正確？","options":["(A) 應建議病人切片","(B) 因超音波檢查正常，所以不需要切片","(C) 切片為癌症可能性小於1%","(D) 若切片證實是癌症，通常是infiltrating ductal carcinoma"],"answer":0,"image":""},{"id":"md5-110-2-40","subject":"md5","topic":"內分泌與乳房外科","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"有關乳癌手術及輔助治療，下列敘述何者錯誤？","options":["(A) 乳房根治切除術（radical mastectomy）是現今乳癌治療的基礎，強調大範圍根治清除，在1970年代是重要的治療方式","(B) 乳房保留手術（breast-conserving therapy）經過臨床試驗證實可以有統計意義的增加存活率（overall and disease-free survival）","(C) 乳房保留手術，若切除腫瘤的切面邊緣有殘留的癌組織會增加局部復發率（local recurrence）","(D) 放射治療是乳癌治療的選項之一，病患有嚴重肺部疾病者（severe pulmonary disease），放射治療並不適合"],"answer":1,"image":""},{"id":"md5-110-2-41","subject":"md5","topic":"整形重建外科","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"有關乳房重建方式的敘述，下列何者錯誤？","options":["(A) 義乳植入是雙側乳房重建手術的適應症之一","(B) 義乳植入其優點在維持雙側對稱，其缺點在無法維持自然下垂的外觀（natural ptosis）","(C) 闊背肌皮瓣可以提供較寬厚的組織覆蓋，適用於乳房較大的重建手術","(D) 腹直肌皮瓣手術對先前曾做腹部手術的病患，是相對禁忌症"],"answer":2,"image":""},{"id":"md5-110-2-42","subject":"md5","topic":"小兒外科","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"一名2歲大的小朋友因為腹痛來到急診室，生化檢查發現他有升高的澱粉酶（amylase），腹部超音波檢查發現他的肝內膽管與總膽管擴大。診斷可能是膽道囊腫（choledochal cyst）。下列相關敘述何者正確？①type IV的膽道囊腫 ②type V的膽道囊腫 ③應該待胰臟炎緩解後即安排手術切除囊腫 ④應該等到6歲再做手術切除囊腫 ⑤囊腫發生的假說是因為胰液反流導致膽管發炎擴大","options":["(A) ①③⑤","(B) ②③","(C) ②④⑤","(D) ①④⑤"],"answer":0,"image":""},{"id":"md5-110-2-43","subject":"md5","topic":"小兒外科","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"一位5歲男孩因為發燒來到急診，理學檢查並無上呼吸道感染，但有左後背敲痛感，尿液檢查發現有白血球增高現象，腎臟超音波發現有嚴重水腎現象伴隨腎臟皮質變薄的現象，輸尿管無脹大，後續的尿液逆流攝影（VCUG）發現他沒有膀胱輸尿管逆流。下列敘述何者正確？①可能是腎盂輸尿管狹窄併發腎盂腎炎 ②可能是輸尿管膀胱狹窄併發腎盂腎炎 ③可以再加做腎臟核醫掃描（DTPA with Lasix）的檢查協助判斷 ④手術方式有兩種，一種是從膀胱外重新植入輸尿管，一種是從膀胱內重新植入輸尿管（reimplantation） ⑤先用抗生素治療就好，除非反覆性感染才需要手術","options":["(A) 僅①⑤","(B) ②③④","(C) 僅①③","(D) ①③⑤"],"answer":2,"image":""},{"id":"md5-110-2-44","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"一名13.5公斤的幼兒，在接受腸胃道手術後暫時禁食。試問他每日的輸液量至少要達到多少mL？","options":["(A) 900","(B) 1,050","(C) 1,175","(D) 2,700"],"answer":2,"image":""},{"id":"md5-110-2-45","subject":"md5","topic":"小兒外科","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"一個懷孕28周的準媽媽，在接受例行的產前超音波檢查，由婦產科醫師檢查出：在胎兒的右肺出現了泡泡狀的病灶。而在此之前，準媽媽與寶寶的檢查，都未出現特別的異狀。婦產科醫師再安排了更詳盡的胎兒檢查，推斷此胎兒患有「先天性肺呼吸道畸形（CPAMs, congenital pulmonary airway malformations）」。於是，婦產科醫師將準媽媽轉介到小兒外科醫師的門診，希望小兒外科醫師跟準媽媽解釋，寶寶在出生之後，寶寶可能需要接受的治療。下列是小兒外科醫師跟著急的準媽媽的病解，何者最不適當？","options":["(A) 先天性肺呼吸道畸形（CPAMs）是一種在正常肺部組織中生長出的多囊結構腫塊。這種多囊腫塊，通常會侷限在某一側的肺部或是某一塊肺葉","(B) 有可能會發生胎兒窘迫","(C) 此病灶並無轉為惡性腫瘤的可能","(D) 如果在懷孕的過程及出生之後，病兒均沒有特別的症狀，我們可以先監控觀察，等到約六個月大前，再考慮進行手術將其病灶切除。但少數的病例在出生後就出現呼吸窘迫的現象，此時就要進行緊急手術將其肺部的病灶切除"],"answer":2,"image":""},{"id":"md5-110-2-46","subject":"md5","topic":"小兒外科","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"腸道旋轉不良（intestinal malrotation）可能造成腸道扭轉（intestinal volvulus），下列那一個敘述對手術所需的步驟最正確？","options":["(A) 解除腸道扭轉，分離升結腸、盲腸（cecum）與十二指腸之沾黏，切除闌尾","(B) 解除腸道扭轉，將升結腸及降結腸固定在腹壁避免容易扭轉，增寬小腸腸繫膜根部避免容易扭轉，切除闌尾","(C) 解除腸道扭轉，分離升結腸、盲腸（cecum）與十二指腸之沾黏，增寬小腸腸繫膜根部避免容易扭轉，切除闌尾","(D) 解除腸道扭轉，分離升結腸、盲腸（cecum）與十二指腸之沾黏，將升結腸及降結腸固定在腹壁避免容易扭轉，切除闌尾"],"answer":2,"image":""},{"id":"md5-110-2-47","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"關於大腸直腸癌的敘述，下列何者錯誤？","options":["(A) 年齡是大腸直腸癌的重要風險因子，約九成的病例是50歲以上的民眾","(B) 約八成的大腸直腸癌是偶發性的，兩成發生於有結腸癌家族病史","(C) 大腸直腸癌好發於多攝食動物性脂肪且少攝食纖維的民眾","(D) 肥胖及久坐的生活方式會減少大腸直腸癌的發生率"],"answer":3,"image":""},{"id":"md5-110-2-48","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"35歲女性解便後，肛門口外出現疼痛腫塊，第二天至門診檢查，確定為1.5公分栓塞外痔，以下何者可以為適當的治療？①局部手術切除（excision） ②局部手術切開（incision） ③溫水坐浴，局部治療（local treatment） ④硬化劑注射（sclerotherapy）","options":["(A) ①③","(B) 僅②④","(C) ①②④","(D) ②③"],"answer":0,"image":""},{"id":"md5-110-2-49","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"有關大腸直腸的解剖構造，下列敘述何者錯誤？","options":["(A) base of appendix位於cecum taeniae coli的聚合處","(B) 在手術中可藉由發現fold of treves，進而發現appendix","(C) rectum沒有taeniae coli，也沒有epiploic appendices","(D) sigmoid colon wall比descending colon薄，所以sigmoid colon較常發生perforation"],"answer":3,"image":""},{"id":"md5-110-2-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"有關潰瘍性結腸炎及克隆氏症（Crohn's disease）之比較，下列何者正確？","options":["(A) 潰瘍性結腸炎有可能產生小腸病灶，克隆氏症則不會有小腸病灶","(B) 克隆氏症較易形成肛門瘻管或腸道瘻管","(C) 在腸道外表徵（extraintestinal manifestations）方面，相較於潰瘍性結腸炎，克隆氏症較易有原發性硬化性膽管炎（primary sclerosing cholangitis, PSC）","(D) 抽菸不會增加克隆氏症復發的機率"],"answer":1,"image":""},{"id":"md5-110-2-51","subject":"md5","topic":"消化器外科","meta":"110年第2次第51題","year":110,"session":2,"number":51,"question":"下列有關腹腔鏡手術的敘述何者錯誤？","options":["(A) 氣體栓塞（air emboli）在腹腔鏡手術中並不常見","(B) 非充氣式的腹腔鏡手術（gasless laparoscopic surgery），撐開器（lift device）的使用對於手術視野的呈現（exposure）及可運作空間上比傳統充氣式腹腔鏡手術更佳","(C) 接受腹腔鏡手術後的免疫抑制反應（immune suppression）較傳統手術少","(D) 接受腹腔鏡手術後血清中的皮質醇（cortisol）濃度較傳統開腹手術後為高"],"answer":1,"image":""},{"id":"md5-110-2-52","subject":"md5","topic":"消化器外科","meta":"110年第2次第52題","year":110,"session":2,"number":52,"question":"關於多孔腹腔鏡手術（multi-port laparoscopic surgery）其port擺位，下列何者錯誤？","options":["(A) 手術醫師雙手的trocar至少相隔10公分為佳","(B) 鏡頭的trocar位於手術醫師雙手間且稍微遠離手術目標為宜","(C) 理想狀況下，手術醫師雙手的trocar和鏡頭的trocar應呈現一等腰三角形","(D) 手術醫師在操作時，常常需以雙手交叉的方式（crossed hands fashion）進行"],"answer":3,"image":""},{"id":"md5-110-2-53","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第2次第53題","year":110,"session":2,"number":53,"question":"45歲陳太太是工廠包裝員，近年來在拇指、食指及中指的分布區域有紅腫、疼痛、麻木及刺痛現象，晚上睡覺時會被痛醒，甩手後症狀會改善。請依此回答下列3題：陳太太可能的診斷為何？","options":["(A) 腕隧道症候群（carpal tunnel syndrome）","(B) 肘隧道症候群（cubital tunnel syndrome）","(C) 頸神經根病變（cervical radiculopathy）","(D) 脊髓病變（myelopathy）"],"answer":0,"image":""},{"id":"md5-110-2-54","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第2次第54題","year":110,"session":2,"number":54,"question":"陳太太會發生這種症狀是因為工作過度造成那一神經的壓迫？","options":["(A) 尺神經（ulnar nerve）","(B) 正中神經（median nerve）","(C) 脊髓（spinal cord）","(D) C4神經根（C4 nerve root）"],"answer":1,"image":""},{"id":"md5-110-2-55","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第2次第55題","year":110,"session":2,"number":55,"question":"在門診中，下列何種檢查呈陽性反應可以幫助確診？","options":["(A) 深部肌腱反射呈現過度反射（deep tendon reflex hyperreflexia）","(B) 肘部彎曲測試（elbow flexion test）","(C) 手腕彎曲測試（Phalen's test）","(D) 椎間孔擠壓測試（Spurling test）"],"answer":2,"image":""},{"id":"md5-110-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第2次第56題","year":110,"session":2,"number":56,"question":"下列關於骨肉瘤（osteosarcoma）的敘述，何者最不適當？","options":["(A) 經大量放射線暴露（radiation exposure）之後，有可能出現放射線誘發的骨肉瘤（radiation-induced osteosarcoma）","(B) 骨膜骨肉瘤（periosteal osteosarcoma）在影像檢查常會看到stuck-on appearance","(C) 動脈瘤性骨囊腫（aneurysmal bone cyst）影像呈現上易與微血管擴張性骨肉瘤（telangiectatic osteosarcoma）混淆診斷","(D) 骨旁骨肉瘤（parosteal osteosarcoma）為低度惡性，最適當的治療方法是手術切除"],"answer":1,"image":""},{"id":"md5-110-2-57","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第2次第57題","year":110,"session":2,"number":57,"question":"一位30歲男性在大地震倒塌的大樓內被救援人員尋獲，發現雙側下肢有嚴重的壓砸傷及變形，並有休克現象，下列敘述何者最不適當？","options":["(A) 臨床檢查有腔室症候群的症候時，應及早進行筋膜切開手術，不必等腔室壓力測量的結果","(B) 當懷疑有橫紋肌溶解症時，應限制水分的攝取，以免造成嚴重肺積水","(C) 腔室症候群的診斷有所謂的5 P's，其中以疼痛為最重要的症候","(D) 腔室內壓力正常值應低於10毫米汞柱，若超過30毫米汞柱以上就要懷疑有腔室症候群"],"answer":1,"image":""},{"id":"md5-110-2-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第2次第58題","year":110,"session":2,"number":58,"question":"Bennett fracture是拇指的掌指骨折併關節脫臼，最可能由下列那一條肌腱牽拉所造成？","options":["(A) 橈側伸腕短肌腱（extensor carpi radialis brevis tendon）","(B) 橈側伸腕長肌腱（extensor carpi radialis longus tendon）","(C) 伸拇長肌腱（extensor pollicis longus tendon）","(D) 外展拇長肌腱（abductor pollicis longus tendon）"],"answer":3,"image":""},{"id":"md5-110-2-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"110年第2次第59題","year":110,"session":2,"number":59,"question":"下列有關肩關節不穩定度的檢查，何者正確？","options":["(A) Jahnke test用來檢查anterior instability","(B) apprehension test用來檢查posterior instability","(C) sulcus test用來檢查anterior instability","(D) Kim test用來檢查posterior instability"],"answer":3,"image":""},{"id":"md5-110-2-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第2次第60題","year":110,"session":2,"number":60,"question":"新生兒先天性脛骨假關節（congenital pseudarthrosis of the tibia），最可能發生下列那一種方向的先天性小腿彎曲變形（bowing deformity），且容易骨折？","options":["(A) 前內側（anteromedial）","(B) 前外側（anterolateral）","(C) 後內側（posteromedial）","(D) 後外側（posterolateral）"],"answer":1,"image":""},{"id":"md5-110-2-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第2次第61題","year":110,"session":2,"number":61,"question":"病人手腕橈骨莖凸附近疼痛，懷疑是de Quervain氏症，通常可用下列何種身體診察（physical examination）來診斷？","options":["(A) Phalen maneuver","(B) Finkelstein test","(C) Watson test","(D) Allen test"],"answer":1,"image":""},{"id":"md5-110-2-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"110年第2次第62題","year":110,"session":2,"number":62,"question":"有關腰椎神經根（lumbar spinal root）所支配的肌肉及動作，下列敘述何者最不適當？","options":["(A) 股四頭肌（quadriceps）主要是由第三及第四腰椎神經根支配，其主要的動作是膝關節伸展（knee extension）","(B) 脛骨前肌（tibialis anterior）主要是由第四及第五腰椎神經根支配，其主要的動作是踝關節背屈（ankle dorsiflexion）","(C) 腓骨長／短肌（peroneus longus / brevis）主要是由第五腰椎及第一薦椎神經根支配，其主要的動作是踝關節外翻（ankle eversion）","(D) 伸趾長肌（extensor hallucis longus）主要是由第一薦椎神經根支配，其主要的動作是大趾伸展（great toe extension）"],"answer":3,"image":""},{"id":"md5-110-2-63","subject":"md5","topic":"骨科-關節重建","meta":"110年第2次第63題","year":110,"session":2,"number":63,"question":"有關下肢關節的身體診察，下列敘述何者最適當？","options":["(A) Trendelenburg sign陽性時，是指病人用健側站立時會產生的徵象","(B) Thomas test是用來檢查Achilles tendon是否斷裂","(C) posterior sagging sign是用來檢查前十字韌帶是否斷裂","(D) Apley test是用來檢查膝關節半月狀軟骨是否破裂"],"answer":3,"image":""},{"id":"md5-110-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"110年第2次第64題","year":110,"session":2,"number":64,"question":"當患者有1.5公分合併症狀之腎臟結石，且一年前有放置冠狀動脈塗藥支架病史，現仍持續服用抗凝血藥時，其最適當的治療選擇為何？","options":["(A) 體外震波碎石術（extracorporeal shock wave lithotripsy）","(B) 軟式輸尿管鏡碎石術（flexible ureteroscopic lithotripsy）","(C) 經皮腎造瘻截石術（percutaneous nephrolithotripsy）","(D) 腎盂截石術（pyelolithotomy）"],"answer":1,"image":""},{"id":"md5-110-2-65","subject":"md5","topic":"泌尿-腫瘤","meta":"110年第2次第65題","year":110,"session":2,"number":65,"question":"下列有關膀胱癌的敘述，何者最適當？","options":["(A) 腺癌（adenocarcinoma）是最常見的膀胱腫瘤","(B) 鱗狀上皮細胞癌（squamous cell carcinoma）與慢性發炎無關","(C) 膀胱癌是泌尿上皮最少發生腫瘤的部位","(D) 一部分的膀胱癌會呈現膀胱刺激症狀（vesical irritability）"],"answer":3,"image":""},{"id":"md5-110-2-66","subject":"md5","topic":"泌尿-腫瘤","meta":"110年第2次第66題","year":110,"session":2,"number":66,"question":"一位60歲女性主訴無痛血尿，經輸尿管鏡切片發現左腎盂有高惡性度尿路上皮癌（high grade urothelial carcinoma），沒有轉移，兩側腎臟功能正常，下列何者是最適當的治療？","options":["(A) 軟式輸尿管鏡及雷射腫瘤切除手術","(B) 左腎臟輸尿管及膀胱袖口切除手術","(C) 經皮腎臟鏡腫瘤切除手術","(D) 放射線治療"],"answer":1,"image":""},{"id":"md5-110-2-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"110年第2次第67題","year":110,"session":2,"number":67,"question":"下列有關良性前列腺增生（benign prostatic hyperplasia）的藥物治療，何者最不恰當？","options":["(A) 國際前列腺症狀評分（International prostate symptom score）輕微（評分為0～7）者，通常建議注意觀察即可，不須給藥","(B) α1-腎上腺素受體阻斷劑可以有效改善良性前列腺增生病人主觀和客觀的下泌尿道症狀","(C) 選擇性α1-腎上腺素受體阻斷劑主要是作用在α1d-腎上腺素受體","(D) α1-腎上腺素受體阻斷劑可能的副作用包括姿態性低血壓、頭暈、疲倦、逆行性射精、鼻炎和頭痛"],"answer":2,"image":""},{"id":"md5-110-2-68","subject":"md5","topic":"神經外科","meta":"110年第2次第68題","year":110,"session":2,"number":68,"question":"脊髓損傷在何處較會產生自主神經反射異常（autonomic dysreflexia）？","options":["(A) 薦髓2～4節","(B) 腰髓2～4節","(C) 胸髓10～12節","(D) 胸髓6～8節"],"answer":3,"image":""},{"id":"md5-110-2-69","subject":"md5","topic":"泌尿-結石與感染","meta":"110年第2次第69題","year":110,"session":2,"number":69,"question":"尿路感染完成第一次抗生素治療後，仍持續存在菌尿症稱為Unresolved bacteriuria，下列那一個原因最常見？","options":["(A) 細菌對治療之抗生素有抗藥性","(B) 兩種不同致病菌同時存在，且抗生素感受性不同","(C) 氮血症（azotemia）","(D) 因濫用止痛藥引起的腎臟乳突壞死（papillary necrosis）"],"answer":0,"image":""},{"id":"md5-110-2-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"110年第2次第70題","year":110,"session":2,"number":70,"question":"下列有關兒童尿路感染的敘述何者正確？","options":["(A) 一歲以內的男孩發生尿路感染的機會較女孩為低","(B) 造成尿路感染的來源通常是肛門糞便經由會陰部往前至尿道周圍的菌落","(C) 兒童的腎盂腎炎並不會造成腎臟結疤","(D) 年紀較大之兒童不會有較高的尿路感染機率"],"answer":1,"image":""},{"id":"md5-110-2-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"110年第2次第71題","year":110,"session":2,"number":71,"question":"Sildenafil是治療勃起功能障礙的藥物，下列敘述何者正確？","options":["(A) 可增加大腦的促進勃起訊息（proerectile signaling）","(B) 作用機轉是促進cyclic guanosine monophosphate（cGMP）之分解","(C) 病人有服用硝酸鹽（nitrate）時不可合併使用","(D) 主要作用是抑制phosphodiesterase-6（PDE6）"],"answer":2,"image":""},{"id":"md5-110-2-72","subject":"md5","topic":"消化器外科","meta":"110年第2次第72題","year":110,"session":2,"number":72,"question":"一主訴腹部急性劇痛而且身體虛弱的病人求診。仰臥胸部X光檢查和側臥腹部X光檢查（cross-table, decubitus view）呈現如二附圖。下列那一項初診斷最正確？","options":["(A) gas-forming liver abscess","(B) perforated peptic ulcer","(C) acute cholecystitis","(D) right pneumothorax"],"answer":1,"image":"md5-110-2-72.jpeg"},{"id":"md5-110-2-73","subject":"md5","topic":"胸腔外科","meta":"110年第2次第73題","year":110,"session":2,"number":73,"question":"有關下圖的敘述，下列何者錯誤？","options":["(A) 為有靜脈注射含碘顯影劑之冠狀重組之電腦斷層攝影圖","(B) 有呈現心室中隔","(C) 有呈現下行主動脈","(D) 右下胸有腫塊，有呈現肝靜脈"],"answer":2,"image":"md5-110-2-73.jpeg"},{"id":"md5-110-2-74","subject":"md5","topic":"消化器外科","meta":"110年第2次第74題","year":110,"session":2,"number":74,"question":"64歲女性，因急性右上腹部劇痛，掛急診求醫，腹部CT和血管攝影影像如附圖，則最可能的診斷為下列何者？","options":["(A) 肝膿瘍","(B) 分布不均脂肪肝","(C) 肝細胞癌破裂","(D) 肝血管瘤破裂"],"answer":2,"image":"md5-110-2-74.jpeg"},{"id":"md5-110-2-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第2次第75題","year":110,"session":2,"number":75,"question":"Compartment syndrome表現的5個P不包括下列何者？","options":["(A) painless","(B) paresthesia","(C) pulselessness","(D) pressure"],"answer":0,"image":""},{"id":"md5-110-2-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第2次第76題","year":110,"session":2,"number":76,"question":"關於動物咬傷的緊急處置，下列敘述何者最不適當？","options":["(A) 立即縫合傷口會增加傷口感染的機率","(B) 臉部的單純表淺撕裂傷可考慮立即縫合","(C) 高感染風險的傷口應開立抗生素，並建議3日後門診複查","(D) 貓咬傷的傷口感染機率比狗咬傷高"],"answer":2,"image":""},{"id":"md5-110-2-77","subject":"md5","topic":"外科-休克創傷傷口","meta":"110年第2次第77題","year":110,"session":2,"number":77,"question":"31歲女性，下班後駕車不幸在交叉口和公車相撞，身體檢查發現意識混亂，生命徵象穩定，腹壁上有一橫向帶狀瘀青，腰椎X光影像發現有L1 Chance fracture，病人何種器官最可能受傷？","options":["(A) 胃","(B) 脾臟","(C) 橫結腸","(D) 十二指腸"],"answer":3,"image":""},{"id":"md5-110-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"110年第2次第78題","year":110,"session":2,"number":78,"question":"78歲乳癌併肺臟、肝臟、骨轉移的女性病人，先生過世，有1子3女，由長子負擔所有的生活費。某日病人昏迷路倒被送至急診室，經醫師插管急救後轉送病房，4位子女來到病房後，長子要求拔管，其餘3個女兒表示反對。下列處理方式，何者最適當？","options":["(A) 成人子女間，順位相同，醫師應儘量與子女溝通或召開家族會議取得共識","(B) 當然由長子決定，因其年齡最大","(C) 應採多數決，以3個女兒的決定為主","(D) 由長子決定，因母親所有的生活費均由其負擔，當然有優先決定權"],"answer":0,"image":""},{"id":"md5-110-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"110年第2次第79題","year":110,"session":2,"number":79,"question":"一名路倒的老人，在昏迷中由路人送到醫院急診，身上並無任何相關的身分證明文件，也無法得知確切的受傷時間。當時病患雖已失去意識，但仍有心跳及血壓，不過昏迷指數只有3分，插管後安排電腦斷層掃描，結果發現瀰漫性的顱內出血，與神經外科醫師討論後認為預後極差，暫無手術必要，因此轉入外科加護病房治療。到加護病房後，病人情況突然惡化，血壓及心跳下降，隨即心跳停止，因無法確認身分所以無從聯絡家屬。此時應如何處理最適當？","options":["(A) 急救至家屬出現","(B) 按照合理的急救時間急救30分鐘至1小時，即停止","(C) 找到家屬，但家屬說趕來醫院需要2小時左右，因此需延長急救時間到2小時","(D) 不必急救"],"answer":1,"image":""},{"id":"md5-110-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"110年第2次第80題","year":110,"session":2,"number":80,"question":"依據醫療法中手術前說明的相關規定，下列敘述何者錯誤？","options":["(A) 說明需由具醫師身分者為之","(B) 說明的對象為病人或其法定代理人、配偶、親屬或關係人","(C) 說明的內容包括手術原因、手術成功率或可能發生之併發症及危險","(D) 經其同意，簽具手術同意書及麻醉同意書，始得為之。但情況緊急者，不在此限"],"answer":0,"image":""},{"id":"md5-111-1-1","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"下列敘述，何者正確？","options":["(A) 病人從上消化道或腹瀉大量流失碳酸氫鹽（bicarbonate）時，會造成鹼血症（alkalemia）","(B) 醫源性呼吸性酸中毒（iatrogenic respiratory acidosis）常見的原因之一是氣管插管後的呼吸器過度機械性通氣（mechanical ventilation）","(C) 敗血性休克（septic shock）病人會有代謝性鹼中毒（metabolic alkalosis）","(D) 快速靜脈輸注大量等張氯化鈉溶液（isotonic sodium chloride solutions）時，會發生代謝性酸血症（metabolic acidemia）"],"answer":3,"image":""},{"id":"md5-111-1-2","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"絞刑骨折（hangman's fracture）是指下列何者？","options":["(A) disruption of C1 ring in multiple locations ; blow-out ring","(B) odontoid fracture, type II : through base","(C) odontoid fracture, type I : tip of odontoid","(D) bilateral C2 pedicles with spondylolisthesis"],"answer":3,"image":""},{"id":"md5-111-1-3","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"在臺灣，目前下列何者不適合作為腦死器官的捐贈者？","options":["(A) 血清中B型肝炎病毒（hepatitis B virus）表面抗原陽性之腦死病人","(B) 血清中巨細胞病毒（cytomegalovirus）抗體陽性之腦死病人","(C) 血清中人類嗜T淋巴球病毒（human T-lymphotropic virus）抗體陽性之腦死病人","(D) 血清中弓漿蟲（toxoplasma）抗體陽性之腦死病人"],"answer":2,"image":""},{"id":"md5-111-1-4","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"一位53歲女性駕駛小轎車與對側高速來車相撞，立刻被緊急送至第一級（Level I）創傷中心急救。到院時意識狀態清楚，主訴兩側胸部及腹部疼痛、兩側手腕及左下肢劇痛。理學檢查發現血壓80/50 mmHg、心跳115次/ 分、呼吸20次/分，給與氧氣5公升/分鐘使用後，動脈血氧飽和度可達98%；另左胸呼吸音減低，腹部微脹有明顯瀰漫性壓痛，雙側手腕變形及左股骨開放性骨折。經快速大量輸液治療後血壓上升至100/55 mmHg，故安排緊急全身顯影電腦斷層，結果如附圖。病人送回急救區後發現意識模糊，但對深痛刺激有反應，生命徵象為血壓60/40 mmHg、心跳125次/分、呼吸20次/分，動脈血氧飽和度無法偵測。下列何種醫療處置較為適當？","options":["(A) 再次給予快速大量輸液後立即再安排一次腦部電腦斷層","(B) 立即雙側肋膜胸管置入並密切觀察","(C) 立即送病人至手術室接受緊急開胸及主動脈修補術","(D) 立即送病人至手術室接受緊急剖腹探查"],"answer":3,"image":"md5-111-1-4.jpeg"},{"id":"md5-111-1-5","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"下列何項不是肝臟移植之適應症？","options":["(A) primary biliary cirrhosis","(B) hepatocellular carcinoma","(C) biliary atresia","(D) liver cirrhosis due to heart failure"],"answer":3,"image":""},{"id":"md5-111-1-6","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"下列何者並非術後發生低血鈉症（hyponatremia）時的常見症狀？","options":["(A) 頭痛","(B) 心跳加速","(C) 噁心嘔吐","(D) 虛弱疲乏"],"answer":1,"image":""},{"id":"md5-111-1-7","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"車禍現場發現一受傷中年男性病人，中等身材，身下一灘血面積約0.2平方公尺，病人心跳每分鐘125下，脈搏微弱，血壓為75/40 mmHg，意識清醒但呈現混亂，該病人最可能的失血量為下列何者？","options":["(A) ＜500 mL","(B) 800 mL","(C) 1,800 mL","(D) 3,000 mL"],"answer":2,"image":""},{"id":"md5-111-1-8","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"面對一位胸腔穿刺傷的病患，下列那些狀況須考慮手術探查治療？①一置入胸管立刻流出1,500 mL鮮血 ②超音波顯示有心包填塞（pericardial tamponade） ③開放式氣胸 ④兩側胸腔皆疑似受傷 ⑤胸管內除血液外同時有少量氣體溢出","options":["(A) ①②④","(B) ③④⑤","(C) ①②③","(D) ①②⑤"],"answer":2,"image":""},{"id":"md5-111-1-9","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"59歲無特定病史男性，被診斷罹患無遠處轉移的結腸癌，手術後病理結果為pT3N1。以目前的治療指引應建議病人接受下列何項治療？","options":["(A) 追蹤","(B) oxaliplatin為主的化學治療（FOLFOX）","(C) irinotecan為主的化學治療（FOLFIRI）","(D) 須加上標靶藥物（VEGF或EGFR inhibitor）"],"answer":1,"image":""},{"id":"md5-111-1-10","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"有關大腸直腸的胚胎發育，下列敘述何者錯誤？","options":["(A) 前腸衍生結構（foregut-derived structures）的主要血液供應來源為腹腔動脈（celiac artery）","(B) 中腸衍生結構（midgut-derived structures）是從近端空腸（proximal jejunum）到遠端橫結腸（distal transverse colon）","(C) 肛門內括約肌（internal anal sphincter）是從直腸（rectum）的環形肌肉層（circular muscle layer）延伸形成","(D) 約在胚胎發育第6週，泌尿生殖膈（urogenital septum）往尾部移行（caudal migration）而分隔開消化道及生殖泌尿道"],"answer":1,"image":""},{"id":"md5-111-1-11","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"有關大腸直腸的生理敘述，下列何者錯誤？","options":["(A) colonic microflora可幫助維持epithelial integrity及nutritive function","(B) Bacteroides species約占大腸細菌的三分之二","(C) colonic microflora幫助人體行urea recycling，有助於liver failure之病人","(D) 2大腸吸收面積約900 cm，可幫忙再吸收大量水分"],"answer":2,"image":""},{"id":"md5-111-1-12","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"一位40歲男性至急診就診主訴解血便兩日，到院時意識清楚，體溫為攝氏36.5度，心跳每分鐘120次，呼吸次數每分鐘26次，血壓90/56 mmHg。有關後續處置，下列何者較不適宜？","options":["(A) 完整的病史詢問及目前用藥諮詢，應包含患者過去有無接受過大腸鏡息肉切除或目前正在服用抗凝血劑等；理學檢查應包含肛門檢查","(B) 建立輸液管路並給與輸液，行血型配對及相關血液檢查","(C) 可考慮幫患者置放鼻胃管或是安排上消化道鏡檢查","(D) 告知患者相關手術風險，聯絡手術室準備行緊急手術止血"],"answer":3,"image":""},{"id":"md5-111-1-13","subject":"md5","topic":"消化器外科","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"有關腹腔鏡闌尾切除手術，下列敘述何者錯誤？","options":["(A) 年長病患比年輕病患有較高比例改為開腹手術","(B) 年長病患比年輕病患有較高手術相關併發症","(C) 年長病患比年輕病患有較高的感染相關併發症","(D) 年長病患比年輕病患有較高機會發現複雜闌尾炎或其他病理表現"],"answer":2,"image":""},{"id":"md5-111-1-14","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"關於自然孔洞手術（natural orifice transluminal endoscopic surgery, NOTES）的敘述，下列何者錯誤？","options":["(A) 自然孔洞手術（NOTES）在技術上會比傳統內視鏡手術增加醫師的心理壓力且學習曲線較長","(B) 經口內視鏡食道肌肉切開手術（POEM）可以減少腹部創傷及減少對食道胃接合處（gastroesophageal junction）的破壞","(C) 自然孔洞手術（NOTES）從臨床手術上顯示傷口較少、疼痛較少及失能較少等優點","(D) 於肛門距離（anal verge）大於25公分的腫瘤仍可藉由經肛門內視鏡手術（TEMS）予以切除治療"],"answer":3,"image":""},{"id":"md5-111-1-15","subject":"md5","topic":"神經外科","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"關於腦動脈瘤破裂出血後的腦血管痙攣（cerebral vasospasm），下列敘述何者錯誤？","options":["(A) 好發於腦動脈瘤破裂出血後的1～5天","(B) Hunt and Hess clinical grading scale越高，發生腦血管痙攣的機會越高","(C) CT上基底腦池的出血量越多，發生腦血管痙攣的機會越高","(D) 可以用hemodynamic augmentation的方式治療腦血管痙攣"],"answer":0,"image":""},{"id":"md5-111-1-16","subject":"md5","topic":"神經外科","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"29歲女性因為騎摩托車發生車禍導致頭部外傷住院，入院診斷是右側硬腦膜下出血（subdural hemorrhage）。因為血塊厚度為0.2公分，而且昏迷指數14分，所以僅用降腦壓藥（mannitol）控制腦部水腫。深夜11點時病房護理師報告值班醫師病人癲癇發作，當值班醫師趕到時病人已經持續抽搐3分鐘。下列敘述何者錯誤？","options":["(A) 病人雙眼可能偏向右側（forced eye deviation to right）","(B) 這時考慮使用的第一線藥物是propofol","(C) 如果給與第一線藥物1分鐘後癲癇仍持續發作，則考慮給與第二線用藥","(D) 如果癲癇持續5分鐘以上，則要考慮插管予以完全鎮靜"],"answer":1,"image":""},{"id":"md5-111-1-17","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"下列受壓性神經病變（entrapment neuropathy）與相關神經之組合，何者錯誤？","options":["(A) 橫腕韌帶（transverse carpal ligament）－正中神經（median nerve）","(B) 蓋用氏隧道（Guyon's canal）－橈神經（radial nerve）","(C) 腓骨頭（fibular head）－腓神經（peroneal nerve）","(D) 踝管（tarsal tunnel）－脛神經（tibial nerve）"],"answer":1,"image":""},{"id":"md5-111-1-18","subject":"md5","topic":"神經外科","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"頭部外傷患者被送至加護病房，因意識不清給與裝置腦壓監視器，今測得其血壓為150/90 mmHg，顱內壓為25 mmHg，則其腦灌流壓（cerebral perfusion pressure, CPP）為多少mmHg？","options":["(A) 105","(B) 95","(C) 90","(D) 85"],"answer":3,"image":""},{"id":"md5-111-1-19","subject":"md5","topic":"神經外科","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"下列那種疾病常屬於後天發生的？","options":["(A) 動靜脈畸形（arteriovenous malformation）","(B) 毛細血管擴張（capillary telangiectasia）","(C) 腦部漿果動脈瘤（cerebral berry aneurysm）","(D) 腦部靜脈異常（venous anomaly）"],"answer":2,"image":""},{"id":"md5-111-1-20","subject":"md5","topic":"神經外科","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"有關腦脊髓液之敘述，下列何者錯誤？","options":["(A) 由脈絡叢（choroid plexus）產生","(B) 產生速率約為0.66 mL/kg/hr（40 c.c./hr）","(C) 少部分會進到脊髓腔循環","(D) 由蜘蛛膜絨毛（arachnoid villi）吸收"],"answer":1,"image":""},{"id":"md5-111-1-21","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"關於燒燙傷的傷口感染，下列敘述何者正確？","options":["(A) 全身性預防性抗生素的使用，極為重要","(B) 初期的感染菌株，多為革蘭氏（Gram stain）陰性菌","(C) 初期的傷口，需要使用有強穿透力的抗生素藥膏，如磺胺銀（silver sulfadiazine）藥膏，以穿透焦痂","(D) 磺胺米隆（mafenide acetate 11%）藥膏，可能造成代謝性酸中毒"],"answer":3,"image":""},{"id":"md5-111-1-22","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"肉芽組織（granulation tissue）不包含下列何種細胞？","options":["(A) 纖維母細胞（fibroblast）","(B) 巨噬細胞（macrophage）","(C) 淋巴細胞（lymphocyte）","(D) 血管內皮細胞（endothelial cells）"],"answer":2,"image":""},{"id":"md5-111-1-23","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"關於腕隧道症候群（carpal tunnel syndrome）下列何者正確？","options":["(A) 伸展動作會加重症狀","(B) 手術方式是切斷腕橫韌帶（transverse carpal ligament）","(C) 手術患者一定會有魚際肌（thenar muscle）的萎縮","(D) 手術無效才改以副木治療"],"answer":1,"image":""},{"id":"md5-111-1-24","subject":"md5","topic":"整形重建外科","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"下列關於皮膚移植（skin graft）之敘述，何者錯誤？","options":["(A) 部分皮膚移植（split thickness skin graft）取皮時也會包含部分真皮層","(B) 全層皮膚移植（full thickness skin graft）取皮時應包含全部的真皮層","(C) 全層皮膚移植（full thickness skin graft）較不容易產生次發攣縮（secondary contracture）","(D) 頭皮生長快速，毛囊豐富，所以是理想的全層皮膚移植（full thickness skin graft）供皮區"],"answer":3,"image":""},{"id":"md5-111-1-25","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"24歲男性騎機車自摔，造成顏面外傷（facial trauma）出血，被送到急診處理。有關顏面外傷的處置，下列敘述何者錯誤？","options":["(A) 要先評估是否有大出血或顱內出血","(B) 生命威脅的大出血，是指3單位（unit）以上的失血或血比容（Hct）小於29%","(C) 一旦X光片確認有顏面骨骨折，應立即手術復位及固定","(D) 若撞及眼眶可能導致全盲及視神經壓迫或眼壓升高"],"answer":2,"image":""},{"id":"md5-111-1-26","subject":"md5","topic":"心臟血管外科","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"下列對瓣膜（主動脈瓣或二尖瓣）置換之敘述，何者錯誤？","options":["(A) 置換機械性瓣膜（mechanical valve）之患者，一般建議需終身使用抗凝血藥物（warfarin）","(B) 機械性瓣膜（mechanical valve）比生物組織性瓣膜（bioprosthetic valve）有較長之使用期限","(C) 置換生物組織性瓣膜（bioprosthetic valve）之患者，建議術後3個月內必須使用抗凝血藥物（warfarin）","(D) 因生物組織性瓣膜（bioprosthetic valve）多從牛或豬等動物取得，術後必須終身使用抗排斥藥物（immunosuppressants），以免發生排斥現象"],"answer":3,"image":""},{"id":"md5-111-1-27","subject":"md5","topic":"心臟血管外科","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"有關無幫浦不停跳冠狀動脈繞道手術（off-pump coronary artery bypass grafting, OPCAB）之敘述，下列何者錯誤？","options":["(A) 是實行冠狀動脈繞道手術（coronary artery bypass grafting）的手術選項之一","(B) 理論上因無幫浦輔助下施行手術，所以包括傳統開心手術中之術後流血、神經認知功能不全、血栓栓塞、體液堆積及各器官暫時性的功能不全等各項併發症都可能減到最低的程度","(C) 因為可能發生之併發症較on-pump beating-heart bypass少，因此全世界大部分的冠狀動脈繞道手術，都採取off-pump coronary artery bypass grafting","(D) 在全世界大規模的研究中，OPCAB一年的存活率與再次需要介入性治療的機率，與有幫浦且停跳的冠狀動脈繞道手術比較起來，並未顯現其優越性"],"answer":2,"image":""},{"id":"md5-111-1-28","subject":"md5","topic":"心臟血管外科","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"將主動脈分為五大部分，如附圖，則主動脈內氣球幫浦（intra-aortic balloon pump, IABP）置入後，球囊（intra-aortic balloon）最佳位置應於：","options":["(A) I","(B) II","(C) III","(D) IV"],"answer":2,"image":"md5-111-1-28.jpeg"},{"id":"md5-111-1-29","subject":"md5","topic":"心臟血管外科","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"80歲男性抽菸且合併高血壓、糖尿病病史，接受頸動脈血管攝影檢查之結果如附圖。則下列敘述何者錯誤？","options":["(A) 診斷為外頸動脈（external carotid artery）狹窄","(B) 聽診時不一定聽得到頸動脈雜音（carotid bruit）","(C) 突發性狹窄同側暫時性失明（amaurosis fugax）為可能臨床表現之一","(D) 如接受頸動脈內膜摘除術（carotid endarterectomy），對有同側中風病史者，術後皆擁有較佳的防止再度中風效果"],"answer":0,"image":"md5-111-1-29.jpeg"},{"id":"md5-111-1-30","subject":"md5","topic":"心臟血管外科","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"對剛出生之新生兒，下列何種病情無法用前列腺素E1（prostaglandin E1）暫時緩解臨床血氧下降（desaturation）及發紺（cyanosis）之危況，必須立即手術？","options":["(A) 左心室發育不全症候群（hypoplastic left heart syndrome）","(B) 嚴重發紺之法洛氏四重症（cyanotic episode in tetralogy of Fallot）","(C) 嚴重阻塞之心下型全肺靜脈回流異常（obstructed infracardiac type total anomalous pulmonary venous return）","(D) 大動脈轉位合併心室中隔缺損（transposition of great arteries with ventricular septal defect）"],"answer":2,"image":""},{"id":"md5-111-1-31","subject":"md5","topic":"胸腔外科","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"關於縱隔腔炎之敘述，何者錯誤？","options":["(A) 急性縱隔腔炎可因齒齦發炎導致","(B) 慢性縱隔腔炎常無法藉由手術治療，手術只是診斷用途或緩解併發症狀","(C) 硬化性或纖維性縱隔腔炎（sclerosing or fibrosing mediastinitis），常因慢性淋巴結發炎造成，如肺結核等引起","(D) 急性縱隔腔炎常因情況危急，生命徵象不穩定，給與抗生素治療即可改善，不需冒手術風險"],"answer":3,"image":""},{"id":"md5-111-1-32","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"一位25歲年輕人和人爭吵，對方拿出水果刀刺向他的心窩，送至急診室，呈現休克狀況，醫師理學檢查發現劍突上方有1公分之傷口，兩側外頸靜脈鼓張，兩側呼吸聲一致，以下處置，那一項不適合？","options":["(A) 立即做心臟超音波，以診斷是否有心包膜填塞症（cardiac tamponade）","(B) 考慮做心包膜腔穿刺術（pericardiocentesis）","(C) 若病人血壓已經量不出來，考慮立即開胸術（thoracotomy）","(D) 安排移動式胸部X光照射（portable chest X-ray）"],"answer":3,"image":""},{"id":"md5-111-1-33","subject":"md5","topic":"胸腔外科","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"關於肺癌手術的敘述，下列何者正確？","options":["(A) 早期的小細胞肺癌也不應該手術","(B) 對於早期stage IIB之前的肺癌，手術後不需要再加做化療","(C) 對於局部切除無法診斷的肺腫瘤，有時須做肺葉切除","(D) 有腦部轉移就不該做肺部腫瘤切除"],"answer":2,"image":""},{"id":"md5-111-1-34","subject":"md5","topic":"消化器外科","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"下列何種術式非用於治療胃食道逆流？","options":["(A) Nissen fundoplication","(B) Toupet fundoplication","(C) Kocher fundoplication","(D) Dor fundoplication"],"answer":2,"image":""},{"id":"md5-111-1-35","subject":"md5","topic":"消化器外科","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"關於食道癌最新（stage、classification）之T，下列何者錯誤？","options":["(A) Tis；high-grade dysplasia","(B) T1；tumor invades muscularis propria","(C) T3；tumor invades adventitia","(D) T4b；tumor invades trachea or aorta"],"answer":1,"image":""},{"id":"md5-111-1-36","subject":"md5","topic":"消化器外科","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"下列何者非構成lower esophageal sphincter之解剖構造？","options":["(A) intrinsic musculature of distal esophagus","(B) intra-abdominal pressure","(C) sling fibers of the gastric cardia","(D) crura of the diaphragm"],"answer":1,"image":""},{"id":"md5-111-1-37","subject":"md5","topic":"消化器外科","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"對於何時應懷疑有胰臟癌（pancreatic cancer）的存在，下列敘述何者錯誤？","options":["(A) 不明原因之體重減輕或長期腹部悶痛","(B) 沒有糖尿病家族史，而在50歲後發生糖尿病或莫名發生不易控制的高血糖","(C) 不明原因之老人胰臟炎","(D) 身體檢查有Murphy's sign時"],"answer":3,"image":""},{"id":"md5-111-1-38","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"王先生56歲，預計2天後接受胰臟癌手術。作為外科手術隊的成員，你詢問王先生有無服用任何可能導致出血的藥物或草藥。得知王先生6個月前接受心臟手術，仍然在服用Plavix（clopidogrel）、aspirin、Norvasc（amlodipine）及Inderal來控制心臟術後的病情。另患者術前檢測的PT和aPTT值均在正常範圍內，你下一步要做什麼術前準備？","options":["(A) 繼續準備2天後的手術，為手術準備新鮮血漿及紅血球","(B) 繼續準備2天後的手術，停止服用aspirin及Plavix（clopidogrel）","(C) 繼續準備2天後的手術，停止服用aspirin及Plavix（clopidogrel），並在術前給與低分子量肝素","(D) 告知主治醫師並暫停預定之手術"],"answer":3,"image":""},{"id":"md5-111-1-39","subject":"md5","topic":"消化器外科","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"一名25歲的女性患者主訴右下腹疼痛，下列那一項病史對鑑別診斷病因幫助最少？","options":["(A) 月經週期及最近的性生活史","(B) 有無發燒、關節炎或腹部手術史","(C) 胃腸症狀的時間順序","(D) 有無藥物過敏史"],"answer":3,"image":""},{"id":"md5-111-1-40","subject":"md5","topic":"消化器外科","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"有關細菌性肝臟膿瘍的敘述，下列何者正確？","options":["(A) 最常見的原因為肝動脈血液感染","(B) 在西方國家，主要是因為膽道惡性腫瘤造成阻塞合併感染；而在亞洲，則是以肝內結石造成的膽道感染為最主要的原因","(C) 外傷也會造成肝內膿瘍，主要是因為血塊或是壞死的組織沒有吸收造成的緣故，通常在受傷的3天內，病患發生突然的高燒不止，就需要進行鑑別診斷","(D) 超音波是主要的診斷工具。在超音波下，膿瘍為圓形或是卵圓形的高回音（hyperechoic）病徵，其診斷敏感性可以達到80-95%。唯獨對於某些不易判讀的解剖位置如肝頂（dome）不易確診"],"answer":1,"image":""},{"id":"md5-111-1-41","subject":"md5","topic":"消化器外科","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"下列何種胃部變化與胃癌的癌前變化關聯最大？","options":["(A) hyperplastic polyp","(B) chronic ulcer","(C) atrophic gastritis","(D) aberrant pancreas"],"answer":2,"image":""},{"id":"md5-111-1-42","subject":"md5","topic":"消化器外科","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"陳先生40歲，持續出現胸悶、夜咳的現象，心臟及肺部檢查並無異常，胃鏡發現嚴重的胃食道逆流（gastroesophageal reflux），切片檢查已出現Barrett's esophagus現象，但無裂口疝氣（hiatal hernia）。食道動力檢查並無異常，經過proton pump inhibitor口服藥物治療後，症狀並未緩解。下列選項中，何者是接下來較合適的治療方式？","options":["(A) Heller esophageal myotomy","(B) sleeve gastrectomy","(C) biliopancreatic diversion","(D) Nissen fundoplication"],"answer":3,"image":""},{"id":"md5-111-1-43","subject":"md5","topic":"消化器外科","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"急性胃、食道靜脈瘤出血，經藥物及內視鏡治療後仍持續出血，此時選擇以下外科治療，何者最不適當？","options":["(A) 經頸靜脈肝內門體靜脈支架分流術（transjugular intrahepatic portosystemic shunt, TIPS）","(B) 遠端脾靜脈腎靜脈分流術（Warren shunt）","(C) 脾臟切除（splenectomy）","(D) 肝臟移植（liver transplantation）"],"answer":2,"image":""},{"id":"md5-111-1-44","subject":"md5","topic":"消化器外科","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"下列何種肝臟良性病灶最容易發生自發性出血，並有轉變成惡性腫瘤的可能性？","options":["(A) 肝細胞腺瘤（liver cell adenoma）","(B) 肝血管瘤（hemangioma）","(C) 肝臟局部增生性結節（focal nodular hyperplasia）","(D) 肝臟單純囊腫（simple cyst）"],"answer":0,"image":""},{"id":"md5-111-1-45","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"依據TNM分類，對分化良好甲狀腺癌的存活率，下列何者影響力最弱？","options":["(A) 腫瘤大小","(B) 術前甲狀腺功能高低","(C) 遠處轉移","(D) 年齡"],"answer":1,"image":""},{"id":"md5-111-1-46","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"甲狀腺手術後發生呼吸困難，下列原因何者最不可能？","options":["(A) 術後血腫（hematoma）壓迫氣管","(B) 手術傷及雙側recurrent laryngeal nerve","(C) 甲狀腺功能低下（hypothyroidism）導致氣管mucosa edema","(D) 困難插管造成laryngeal edema"],"answer":2,"image":""},{"id":"md5-111-1-47","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"一位60歲男性因腹痛數月就醫檢查，發現胰臟中段有一3公分腫瘤，手術切除後病理診斷為胰臟神經內分泌腫瘤（pancreatic neuroendocrine tumor），下列敘述何者錯誤？","options":["(A) 若腫瘤的insulin免疫染色呈陽性，又可稱為insulinoma","(B) 分泌glucagon的腫瘤可能會有特殊的皮膚病變（necrolytic migrating erythema）","(C) 若Ki-67指數大於20%，病理分級為high grade","(D) 不論神經內分泌腫瘤是否為功能性，皆可利用測量血液中chromogranin A濃度協助診斷與追蹤"],"answer":0,"image":""},{"id":"md5-111-1-48","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"關於乳房Paget disease之敘述，下列何者正確？","options":["(A) 為乳頭皮膚病，治療以類固醇為主","(B) 為乳頭癌前期病變，局部切除即可","(C) 為早期癌病灶之乳頭侵犯，即使有合併腫瘤也少見有腋下淋巴結轉移","(D) 為癌病灶之乳頭侵犯，常會有腋下淋巴結轉移"],"answer":3,"image":""},{"id":"md5-111-1-49","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"張女士的乳房攝影報告為BI-RADS category 4A，表示：","options":["(A) 需要再做其他影像學檢查","(B) 懷疑有惡性腫瘤","(C) 正常表現","(D) 或許是良性，需要6個月內再追蹤"],"answer":1,"image":""},{"id":"md5-111-1-50","subject":"md5","topic":"整形重建外科","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"關於腹直肌皮瓣transverse rectus abdominis myocutaneous（TRAM）flap，下列敘述何者錯誤？","options":["(A) 腹直肌皮瓣是常用的重建方式之一，可以提供全乳房重建","(B) 其相對禁忌症為肥胖、先前腹部手術","(C) 抽菸、喝酒對腹直肌皮瓣手術並無影響","(D) 使用此皮瓣重建後，需適當時間恢復後才能劇烈運動"],"answer":2,"image":""},{"id":"md5-111-1-51","subject":"md5","topic":"小兒外科","meta":"111年第1次第51題","year":111,"session":1,"number":51,"question":"有關隱睪症（cryptorchidism），下列敘述何者錯誤？","options":["(A) 手術的時機點是出生後6個月到1歲","(B) 經由觸診及超音波檢查均未發現睪丸的病人即是先天睪丸萎縮","(C) 患側發生睪丸癌的機率比一般人高，做睪丸固定手術後，也不會降低睪丸癌發生的機率","(D) 睪丸手術固定後，不孕的機率仍比正常男性高"],"answer":1,"image":""},{"id":"md5-111-1-52","subject":"md5","topic":"小兒外科","meta":"111年第1次第52題","year":111,"session":1,"number":52,"question":"小兒並非成人的縮體，所以對於需要接受手術的新生兒，更需嚴密評估及監測其生理狀況。下列對於新生兒的生理描述及評估，何者錯誤？","options":["(A) 新生兒的組織灌流量（tissue perfusion）可由微血管回填充時間（capillary refill time）來監測。若時間超過2秒，則表示其組織灌流量不足","(B) 新生兒的肺部發育尚未完全，出生後肺部仍會持續發育出新生的終末細支氣管（terminal bronchioles）及肺泡（alveoli），而此過程會持續到約8個月大。而在早產的新生兒，不成熟的肺功能常是導致其死亡的重要原因","(C) 新生兒有較大的單位體重表面積與水分無感流失（insensible fluid losses），因此保暖十分重要","(D) 新生兒在失溫後，會以「非顫抖性生熱（nonshivering thermogenesis）」的方式來產熱，導致代謝率及耗氧量大增，時間一長便會造成血灌流量不足及酸血症"],"answer":1,"image":""},{"id":"md5-111-1-53","subject":"md5","topic":"小兒外科","meta":"111年第1次第53題","year":111,"session":1,"number":53,"question":"一名3個月大的女嬰，媽媽發現女嬰的頭總是轉向右邊，所以被帶來小兒外科門診。下列敘述何者錯誤？","options":["(A) 最有可能是女嬰有先天性斜頸","(B) 觀察女嬰的臨床表現，可得知其左側頸部肌肉有異常","(C) 在跟媽媽解說完女嬰的情況後，首先應安排女嬰接受物理治療，以鬆解有纖維化狀況的患側肌肉","(D) 主要是頸部斜方肌纖維化所造成"],"answer":3,"image":""},{"id":"md5-111-1-54","subject":"md5","topic":"小兒外科","meta":"111年第1次第54題","year":111,"session":1,"number":54,"question":"對於先天性橫膈膜疝氣（congenital diaphragmatic hernia）的治療，下列何者最適當？","options":["(A) 胎兒修補橫膈膜疝氣手術具有良好預後","(B) 患有先天性橫膈膜疝氣之新生兒，應於出生後1天內接受修補手術，增加存活機率","(C) 患有先天性橫膈膜疝氣之新生兒，應使用經面罩式陽壓呼吸，避免因氣管插管造成之併發症","(D) 應於出生後置放胃管，減少腸胃脹氣對肺部的壓力"],"answer":3,"image":""},{"id":"md5-111-1-55","subject":"md5","topic":"小兒外科","meta":"111年第1次第55題","year":111,"session":1,"number":55,"question":"在先天性腹壁缺損中，腹裂（gastroschisis）較少合併其他器官的先天性異常，下列何者在腹裂的病人中較常見？","options":["(A) 先天性心臟病","(B) 染色體異常","(C) 小腸閉鎖","(D) 食道閉鎖"],"answer":2,"image":""},{"id":"md5-111-1-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第1次第56題","year":111,"session":1,"number":56,"question":"下列關於軟組織腫瘤（soft tissue tumor）的敘述，何者最不適當？","options":["(A) 腹腔外硬纖維瘤（extraabdominal desmoid tumors），又稱侵襲性纖維瘤病（aggressive fibromatosis）","(B) 多發性神經纖維瘤（neurofibromatosis），又稱von Recklinghausen disease","(C) 滑膜肉瘤（synovial sarcoma）是第二常見的軟組織肉瘤（soft-tissue sarcoma）","(D) 惡性周圍神經鞘瘤（malignant peripheral nerve sheath tumor）源自多病灶的第1型多發性神經纖維瘤（neurofibromatosis type 1），比源自良性的單獨神經纖維瘤（solitary neurofibroma）來得多"],"answer":2,"image":""},{"id":"md5-111-1-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"111年第1次第57題","year":111,"session":1,"number":57,"question":"有關骨盆骨折（pelvic fracture）之敘述，下列何者最不適當？","options":["(A) 大部分的骨盆骨折是穩定骨折，保守治療即可得到很好的療效","(B) 病人可能會伴隨有神經損傷","(C) 許多病人可能發生大腿的腔室症候群（compartment syndrome）","(D) 不穩定的骨盆骨折治療後，病人可能會有下背痛的後遺症"],"answer":2,"image":""},{"id":"md5-111-1-58","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"111年第1次第58題","year":111,"session":1,"number":58,"question":"關於下肢骨折分類及手術的敘述，下列何者最不適當？","options":["(A) 根據Lauge-Hansen分類法，造成腳踝骨折常見的機轉為旋後–外旋型（supination-external rotation）","(B) 在Schatzker分類法中，第一型是脛骨平台（tibial plateau）向外側及向下位移的單純劈裂（pure cleavage），較常見於年輕人","(C) 使用張力帶鋼絲術（tension band wiring）治療骨折時，是將骨折處的擠壓力（compressive force）轉換為牽引力或剪力（distracting or shear force）","(D) 股骨頸骨折的Garden分類法是根據位移的程度；而Pauwels分類法則根據骨折線（fracture line）跟水平面的交角"],"answer":2,"image":""},{"id":"md5-111-1-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"111年第1次第59題","year":111,"session":1,"number":59,"question":"一位45歲男性與別人比賽臂力時肩膀出現劇痛，上臂肌力減弱，產生卜派的上臂形狀（Popeye appearance of the arm），其最可能的診斷是下列何者？","options":["(A) 肱二頭肌長頭肌腱（long head of the biceps tendon）斷裂","(B) 肱二頭肌短頭肌腱（short head of the biceps tendon）斷裂","(C) 肱三頭肌長頭肌腱（long head of the triceps tendon）斷裂","(D) 肱三頭肌短頭肌腱（short head of the triceps tendon）斷裂"],"answer":0,"image":""},{"id":"md5-111-1-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第1次第60題","year":111,"session":1,"number":60,"question":"下列何者最不適合用來檢查兒童的發展性髖關節發育不良（developmental dysplasia of the hip）？","options":["(A) Patrick sign","(B) Galezzi sign","(C) Ortolani maneuver","(D) Barlow maneuver"],"answer":0,"image":""},{"id":"md5-111-1-61","subject":"md5","topic":"骨科-關節重建","meta":"111年第1次第61題","year":111,"session":1,"number":61,"question":"六十多歲退休的王太太十多年前手腕曾經受傷，手腕旋轉長期出現疼痛，經檢查發現遠端橈尺骨關節有嚴重關節炎。下列何種手術最不適當？","options":["(A) Darrach procedure","(B) hemi-resection arthroplasty","(C) Adam procedure","(D) Sauvé-Kapandji procedure"],"answer":2,"image":""},{"id":"md5-111-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第1次第62題","year":111,"session":1,"number":62,"question":"有關化膿性脊椎感染（pyogenic spinal infection），下列敘述何者最不適當？","options":["(A) 最常發生於腰椎，胸椎次之","(B) 最常見之致病菌為金黃色葡萄球菌（Staphylococcus aureus）","(C) 成人的致病機轉主要為血行性（hematogenous）感染椎間盤（intervertebral disc），再蔓延至上、下椎體（vertebral body）造成骨髓炎（osteomyelitis）","(D) 手術適應症包括非手術治療無效、鑑別致病性微生物、有神經功能缺失（neurologic deficit）或脊椎不穩定（spinal instability）"],"answer":2,"image":""},{"id":"md5-111-1-63","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第1次第63題","year":111,"session":1,"number":63,"question":"一位13歲國一女生在新生入學體檢發現Adams forward bending test陽性，而轉介至骨科門診。全脊椎Ｘ光檢查發現腰椎側彎，Cobb角度45度，突向左側，Risser stage 2，初經發生在小學六年級。下列治療方法何者最適當？","options":["(A) 觀察，且須每四個月定期追蹤一次X光","(B) 背架治療，且須每四個月定期追蹤一次X光","(C) 後方側彎矯正、內固定及後側骨融合術（posterior correction, instrumentation and posterior fusion）","(D) 因病人尚有骨骼生長的空間，故在施行後方側彎矯正、內固定及後側骨融合術（posterior correction, instrumentation and posterior fusion）時，須同時施行前側椎體間骨融合（anterior interbody fusion）來預防曲軸現象（crankshaft phenomenon），以免術後角度惡化"],"answer":2,"image":""},{"id":"md5-111-1-64","subject":"md5","topic":"泌尿-結石與感染","meta":"111年第1次第64題","year":111,"session":1,"number":64,"question":"下列何種物質不是尿路結石形成的促進劑（promoter）？","options":["(A) 基質（matrix）","(B) 草酸（oxalate）","(C) 尿酸（uric acid）","(D) 鎂（magnesium）"],"answer":3,"image":""},{"id":"md5-111-1-65","subject":"md5","topic":"泌尿-腫瘤","meta":"111年第1次第65題","year":111,"session":1,"number":65,"question":"下列有關肌肉侵犯型膀胱癌的敘述，何者最正確？","options":["(A) 約10%病人接受膀胱根除術後，會發生轉移","(B) 標準治療是直接施行膀胱根除手術（radical cystectomy）","(C) 合併水腎（hydronephrosis）時，預後較差","(D) 腎臟功能不好，施行膀胱根除手術時應作原位膀胱（orthotopic neobladder）重建"],"answer":2,"image":""},{"id":"md5-111-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"111年第1次第66題","year":111,"session":1,"number":66,"question":"下列有關睪丸癌的敘述，何者錯誤？","options":["(A) 隱睪症男性發生睪丸癌機率較高","(B) 以生殖細胞瘤（germ cell tumor）居多","(C) 絨毛膜癌（choriocarcinoma）較容易轉移","(D) 精原細胞瘤（seminoma）最常見沿著腹股溝及骨盆腔淋巴腺轉移"],"answer":3,"image":""},{"id":"md5-111-1-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"111年第1次第67題","year":111,"session":1,"number":67,"question":"張先生因為最近頻尿、夜尿及急尿等症狀來看診，肛門指診發現前列腺肥大，下列何項檢查最不須要立即進行？","options":["(A) 血清肌酸酐（serum creatinine）","(B) 腎臟超音波","(C) 尿液常規檢查","(D) 前列腺特定抗原（PSA）"],"answer":[0,1],"image":"","answer_note":"更正:第67題，答Ａ或Ｂ或AB者均給分。。"},{"id":"md5-111-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"111年第1次第68題","year":111,"session":1,"number":68,"question":"下列那個部位之脊髓（spinal cord）完全損傷不會造成逼尿肌反射亢進？","options":["(A) 頸髓第五到七節","(B) 胸髓第四到七節","(C) 腰髓第三、四節","(D) 薦髓第二到四節"],"answer":3,"image":""},{"id":"md5-111-1-69","subject":"md5","topic":"泌尿-結石與感染","meta":"111年第1次第69題","year":111,"session":1,"number":69,"question":"關於血尿的病人，下列何者從病史就可以判斷最可能是由尿路感染所引起？","options":["(A) 75歲男性近一個月出現陣發性無痛血尿","(B) 39歲男性左腰急性絞痛（colic pain），合併血尿","(C) 80歲女性兩週內陣發性無痛性血尿，合併血塊排出","(D) 25歲女性突發性血尿，小便疼痛，合併小腹酸痛、急尿與頻尿"],"answer":3,"image":""},{"id":"md5-111-1-70","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"111年第1次第70題","year":111,"session":1,"number":70,"question":"急性睪丸疼痛有可能是急性副睪炎或是睪丸扭轉（testicular torsion），在進行身體診察時，下列敘述何者錯誤？","options":["(A) 將患側睪丸捧起，症狀緩解者較可能是睪丸扭轉","(B) 檢查時接觸患處，溫度較高的較可能是急性副睪炎","(C) 患側提睪反射（cremasteric reflex）消失者較可能是睪丸扭轉","(D) 合併發燒的較可能是急性副睪炎"],"answer":0,"image":""},{"id":"md5-111-1-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"111年第1次第71題","year":111,"session":1,"number":71,"question":"男性勃起功能障礙，需要做血管功能之評估時，可以使用Duplex Ultrasound做診斷。下列有關這項檢查之敘述何者錯誤？","options":["(A) 在陰莖海綿體內注射前列腺素E1，使其充血再做檢查","(B) Resistive index（RI）可以判斷靜脈閉鎖是否正常","(C) 最佳之靜脈閉鎖狀況，其RI值應小於0.9","(D) cavernous artery的peak systolic velocity是判斷動脈正常的指標"],"answer":2,"image":""},{"id":"md5-111-1-72","subject":"md5","topic":"消化器外科","meta":"111年第1次第72題","year":111,"session":1,"number":72,"question":"23歲男性，主訴吞嚥困難與經常性吸入性肺炎，上消化道鋇劑攝影檢查如下圖，最有可能的診斷為：","options":["(A) achalasia","(B) gastroesophageal reflux disease（GERD）","(C) gastric lymphoma","(D) hiatal hernia"],"answer":0,"image":"md5-111-1-72.jpeg"},{"id":"md5-111-1-73","subject":"md5","topic":"消化器外科","meta":"111年第1次第73題","year":111,"session":1,"number":73,"question":"下圖為右上腹部超音波掃描圖，最可能的診斷為：","options":["(A) 產氣性膽囊炎","(B) 產氣性肝膿瘍","(C) 膽囊癌","(D) 膽囊結石"],"answer":3,"image":"md5-111-1-73.jpeg"},{"id":"md5-111-1-74","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"111年第1次第74題","year":111,"session":1,"number":74,"question":"下圖為中年男性所呈現的後腹膜腔腫瘤，最不可能的診斷為：","options":["(A) 淋巴瘤","(B) 源自多形惡性神經膠質瘤（glioblastoma）之轉移腫瘤","(C) 未分化多形性肉瘤（undifferentiated pleomorphic sarcoma）","(D) 精細胞瘤（seminoma）"],"answer":1,"image":"md5-111-1-74.jpeg"},{"id":"md5-111-1-75","subject":"md5","topic":"神經外科","meta":"111年第1次第75題","year":111,"session":1,"number":75,"question":"65歲男性有頸椎退化病史，因跌倒引起頸部疼痛而送醫。到急診時發現四肢無力合併痛覺與溫度感覺異常，上肢的症狀比下肢嚴重，最有可能的診斷為何？","options":["(A) 前脊髓症候群（anterior cord syndrome）","(B) 中心脊髓症候群（central cord syndrome）","(C) 脊髓半切症候群（Brown-Séquard syndrome）","(D) 馬尾症候群（cauda equina syndrome）"],"answer":1,"image":""},{"id":"md5-111-1-76","subject":"md5","topic":"神經外科","meta":"111年第1次第76題","year":111,"session":1,"number":76,"question":"65歲男性過去病史有攝護腺癌合併脊椎轉移，因急性雙下肢疼痛無力2天與大小便失禁而就診。檢查發現雙下肢肌肉力量無法抵抗重力，膀胱尿液滯留600毫升，則此病人的下一步處置，何者最適當？","options":["(A) 給與morphine止痛之後再評估病人肌肉力量","(B) 安排脊椎電腦斷層檢查","(C) 安排脊椎核磁共振","(D) 給與dexamethasone"],"answer":3,"image":""},{"id":"md5-111-1-77","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第1次第77題","year":111,"session":1,"number":77,"question":"腔室症候群須靠下列那個條件來確定診斷？","options":["(A) 腔室內壓力＞30 mmHg","(B) 血清肌酸酐濃度＞2 mg/dL","(C) 血清鉀離子濃度＞6.0 mmol/L","(D) 血清肌酸激酶濃度（CPK）＞1000 IU/L"],"answer":0,"image":""},{"id":"md5-111-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"111年第1次第78題","year":111,"session":1,"number":78,"question":"王先生是一位38歲的生意人，已婚並育有一兒一女，因為肛門膿瘍住院準備接受切開引流手術。在理學檢查的過程中，發現病患左手臂有幾處像卡波希氏肉瘤的紅紫色斑塊，在醫師幾經詢問之下，王先生承認有幾次嫖妓經驗且沒有安全防護措施，檢查後證實為AIDS早期患者，王先生哀求醫師不要告知他的太太，他發誓會保護太太免於傳染，並說這是他的隱私權。根據我國法令，醫師應該如何處理？","options":["(A) 將案例通報到主管機關，並告知他太太","(B) 考量自己安全起見，婉拒為王先生治療","(C) 將案例通報到主管機關，但不主動告知他太太","(D) 尊重病人隱私，不通報主管機關也對太太保密"],"answer":2,"image":""},{"id":"md5-111-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"111年第1次第79題","year":111,"session":1,"number":79,"question":"王先生因為車禍造成肝臟破裂大出血，送到急診室時生命徵象已呈不穩。病歷上記載王先生兩年前曾因肺癌接受左下肺葉切除手術。由於宗教因素當時病歷上已簽署在任何狀況下都拒絶接受輸血治療。所幸上次手術一切順利並不需輸血。然而這次因大量失血造成出血性休克需緊急手術；王先生的太太請求主刀醫師盡一切努力救治他，必要時也同意為王先生輸血，她願意負起所有責任。此時醫師應如何處理？","options":["(A) 請太太簽名，表示由她負起所有輸血的責任後就開始輸血治療","(B) 請公正第三者見證下，由太太簽名後再輸血","(C) 盡一切努力醫治王先生，但不輸血","(D) 為王先生最大利益著想，盡一切努力治療，包括輸血在內"],"answer":2,"image":""},{"id":"md5-111-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"111年第1次第80題","year":111,"session":1,"number":80,"question":"臨床上在處理利益衝突（conflict of interest）的方式，不包括下列何者？","options":["(A) 公開揭露","(B) 交付倫理委員會審議","(C) 明文禁止或處罰","(D) 建立賠償機制"],"answer":3,"image":""},{"id":"md5-111-2-1","subject":"md5","topic":"神經外科","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"有關行走中跌倒後的病人，若腦部電腦斷層檢查發現顱內出血，下列敘述何者正確？","options":["(A) 右側頭部著地造成顱內出血，通常僅右側的腦部會受傷","(B) 硬腦膜上出血常因靜脈血管斷裂造成","(C) 與老人相比較，小孩較容易有硬腦膜下出血的情形","(D) 若腦部電腦斷層發現出血處在basal ganglia或是小腦部位，病人的出血較可能是屬於高血壓造成的出血性腦中風而非車禍造成"],"answer":3,"image":""},{"id":"md5-111-2-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"張力性氣胸（tension pneumothorax）與心包膜積血都可能合併頸靜脈鼓脹，下列何者最能幫助鑑別診斷？","options":["(A) 胸部是否有呼吸聲","(B) 肋骨是否有骨折","(C) 心音是否清晰","(D) 心跳是否加速"],"answer":0,"image":""},{"id":"md5-111-2-3","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"有關新興癌症分子生物標靶治療（target therapy）的原理，下列敘述何者錯誤？","options":["(A) 治療myeloma可針對Bcr-Abl基因","(B) 治療colorectal cancer可針對epidermal growth factor receptor（EGFR）","(C) 治療breast cancer可針對human epidermal growth factor receptor 2（HER2）","(D) 治療renal cell carcinoma可針對vascular endothelial growth factor（VEGF）"],"answer":0,"image":""},{"id":"md5-111-2-4","subject":"md5","topic":"消化器外科","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"下列何者不是胰臟癌的危險因子？","options":["(A) 抽菸","(B) Peutz-Jeghers syndrome","(C) 遺傳性胰臟炎","(D) 縮胃手術"],"answer":3,"image":""},{"id":"md5-111-2-5","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"高壓氧（hyperbaric oxygen therapy）為一有效改善組織缺氧之療法，應用於傷口組織缺氧治療最主要之先決條件為何？","options":["(A) 病人本身多重合併症需獲得良好控制","(B) 確認傷口標的物本身之血液循環暢通","(C) 傷口細菌培養不能有感染狀況","(D) 傷口縫合必須堅固以防崩裂"],"answer":1,"image":""},{"id":"md5-111-2-6","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"有關腎臟移植後使用免疫抑制劑的感染副作用，下列敘述何者最不恰當？","options":["(A) 可於術後預防性使用acyclovir或valgancyclovir，以降低術後巨細胞病毒（cytomegalovirus）感染機率","(B) 因使用免疫抑制劑導致免疫力低下後所致的多瘤病毒相關性腎病（polyomavirus-associated nephropathy）會導致移植腎功能喪失","(C) 長期使用免疫抑制劑會增加病毒活化機會，導致移植後癌症的發生率升高","(D) 移植後淋巴增生性病變（posttransplantation lymphoproliferative disorder）的成因，與人類乳突病毒（human papillomavirus）活化有關"],"answer":3,"image":""},{"id":"md5-111-2-7","subject":"md5","topic":"消化器外科","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"下列何者是發生胃癌的高風險因素？","options":["(A) 高脂高蛋白的飲食","(B) 含氯的飲用水","(C) 低社經階層（low socioeconomic classs）人士","(D) 女性病人"],"answer":2,"image":""},{"id":"md5-111-2-8","subject":"md5","topic":"神經外科","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"有關生殖細胞瘤（germinoma）之敘述述，下列何者錯誤？","options":["(A) 占primary CNS tumor約1～2 %","(B) 90%以上發生於20歲前","(C) 50%長在pineal region","(D) 在pineal region的germinoma：男女發發生比例為1：1"],"answer":3,"image":""},{"id":"md5-111-2-9","subject":"md5","topic":"神經外科","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"有關兒童腦幹膠質瘤（pediatric brainsttem glioma）之敘述，下列何者錯誤？","options":["(A) 占兒童腦瘤比例約10～20%","(B) pontine glioma的存活率較midbrain gglioma好","(C) tectal gliomas常以水腦症表現","(D) pontine gliomas常以multiple cranial nnerve palsies表現"],"answer":1,"image":""},{"id":"md5-111-2-10","subject":"md5","topic":"神經外科","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"一位70歲男性，於晚飯後劇烈頭痛頭頭暈及噁心嘔吐，被家人送來急診，電腦斷層層檢查結果如圖，下列敘述何者錯誤？","options":["(A) 須立即進行手術移除顱內血塊，否則則會有生命危險","(B) 可能是動靜脈畸形出血","(C) 可能是類澱粉血管病變（amyloid anngiopathy）出血","(D) 可能是一個轉移性腫瘤出血"],"answer":0,"image":"md5-111-2-10.jpeg"},{"id":"md5-111-2-11","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"下列關於頸椎退化性疾病的治療敘述述，何者最不適當？","options":["(A) 急性頸椎神經根病變，通常先以保守守治療（包括休息、復健和藥物治療），可以以改善大部分症狀","(B) 如果病人保守治療後，症狀仍未改善善，則須考慮手術治療","(C) 以手術治療後，病人肩頸疼痛症狀和和神經症狀都能全部改善，可回到原本生活和和工作","(D) 前位椎間盤切除減壓手術，術後病人人可能發生聲音沙啞、喝水容易嗆到、和吞嚥嚥困難的風險"],"answer":2,"image":""},{"id":"md5-111-2-12","subject":"md5","topic":"神經外科","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"關於Chiari I herniation的敘述，下列何何者錯誤？","options":["(A) 延髓（medulla）向下疝出，超出foramen magnum位置","(B) 可能產生四肢麻木、無力情形","(C) 可能產生脊髓空洞症（syringomyelia）","(D) 可藉由切除枕骨下骨（suboccipital craniectomy）與第一頸椎椎弓來治療"],"answer":0,"image":""},{"id":"md5-111-2-13","subject":"md5","topic":"神經外科","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"車禍後一個星期，病人發現右眼突出、泛紅、眼睛疼痛、視力減弱，抽血確定無感染，下列敘述何者正確？","options":["(A) 總頸動脈分支處受傷，血栓向遠端移行導致","(B) 常因頸椎過度旋轉導致","(C) 通常是產生低流速（low flow）的動靜脈瘻管所致","(D) 往往不用開刀，而藉由血管介入治療"],"answer":3,"image":""},{"id":"md5-111-2-14","subject":"md5","topic":"整形重建外科","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"顯微組織皮瓣（microvascular free flaps）移植後的術後照護，下列敘述何者錯誤？","options":["(A) 使用抗凝血藥物肝素（heparin）可減少血管栓塞，因而顯著增加皮瓣存活率，已是常規顯微手術必用藥物","(B) 大部分的皮瓣移植後栓塞發生在術後48小時內，這段時間內只要及早發現，救回皮瓣（flap salvage）的機會較高","(C) 皮瓣是否存活，一般可以觀察其皮膚顏色變化、微血管充盈時間（capillary refilling time）和針刺後血流的顏色來協助判別","(D) 血管縫合太鬆導致中膜（tunica media）外露，也是造成術後栓塞的原因"],"answer":0,"image":""},{"id":"md5-111-2-15","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"有關手部曲屈肌腱損傷（flexor tendon injuries）下列敘述何者正確？ћ可以劃分為五區 ќ第一、二、四區的肌腱有滑膜鞘（synovial sheath）包覆 ѝ沒有paratendon的區域，受傷後癒合速度比較快 ў腕隧道（carpal tunnel）屬於第四區","options":["(A) 僅ћў","(B) 僅ћѝў","(C) 僅ћќў","(D) ћќѝў"],"answer":2,"image":""},{"id":"md5-111-2-16","subject":"md5","topic":"整形重建外科","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"有關唇顎裂修復手術之時間表，下列何者錯誤？","options":["(A) 出生後1～2個月可接受唇黏合術（lip adhesion）","(B) 出生後3～6個月可接受唇及初步鼻修復術（lip and primary nose repair）","(C) 出生後10～12個月可接受顎修復術（palate repair）","(D) 5歲前可接受唇或鼻修正術（lip or nose revision）"],"answer":3,"image":""},{"id":"md5-111-2-17","subject":"md5","topic":"整形重建外科","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"20歲女性，右側臉頰患有先天性微血管畸形（capillary malformation），俗稱葡萄酒色斑（port wine stain），治療上選擇下列何種雷射最為適合？","options":["(A) 銣雅鉻雷射（Nd:YAG laser）","(B) 二氧化碳雷射（CO2 laser）","(C) 脈衝式染料雷射（pulsed-dye laser）","(D) 紅寶石雷射（ruby laser）"],"answer":2,"image":""},{"id":"md5-111-2-18","subject":"md5","topic":"整形重建外科","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"最容易造成皮膚移植（skin graft）失敗是在那一期？","options":["(A) 浸潤期（imbibition）","(B) 黏合期（inosculation）","(C) 血管再生期（revascularization）","(D) 增生期（proliferation）"],"answer":1,"image":""},{"id":"md5-111-2-19","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"有關乳癌切除後的乳房重建（breast reconstruction），下列敘述何者錯誤？","options":["(A) 每位患者都有重建的權利，醫師應該盡告知義務提供病患選擇","(B) 使用義乳乳房重建（implant-based reconstruction）並不會影響腫瘤復發的偵測","(C) 為了得到最好結果（best outcome），乳房重建常常需要多步驟的手術","(D) 延遲重建（delayed reconstruction）是指乳癌得到控制後再進行重建，經常需要等2年"],"answer":3,"image":""},{"id":"md5-111-2-20","subject":"md5","topic":"心臟血管外科","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"有關主動脈瓣置換手術的適應症，下列何者最不適當？","options":["(A) 有症狀的嚴重主動脈瓣狹窄之病人，可進行主動脈瓣置換手術","(B) 中度主動脈瓣狹窄（moderate aortic stenosis）合併冠狀動脈阻塞需進行繞道手術之病人，可進行主動脈瓣置換手術","(C) 無症狀的嚴重主動脈瓣狹窄合併左心室收縮功能＜50%之病人，可進行主動脈瓣置換手術","(D) 為預防猝死，在無症狀的嚴重主動脈瓣狹窄之病人，可進行主動脈瓣置換手術"],"answer":3,"image":""},{"id":"md5-111-2-21","subject":"md5","topic":"心臟血管外科","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"關於主動脈瘤（aortic aneurysm），下列敘述何者正確？","options":["(A) 依組織完整性可分為真動脈瘤（true aneurysm）及假性動脈瘤（pseudoaneurysm），定義為aortic wall tissue是否完整，兩者的手術適應症是相同的","(B) 感染是形成動脈瘤的原因之一，常被稱為mycotic aneurysm，最常見的感染源為fungus","(C) 不管是open或endovascular repair of thoracoabdominal aneurysm，cerebrospinal fluid drainage皆有脊髓保護效果","(D) 對於直徑3公分的主動脈瘤應持續於門診追蹤，若病人無出現新的症狀，應每三個月密集行追蹤影像檢查"],"answer":2,"image":""},{"id":"md5-111-2-22","subject":"md5","topic":"心臟血管外科","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"有關深層靜脈栓塞（deep vein thrombosis），下列敘述何者錯誤？","options":["(A) 危險因子包括年齡、惡性腫瘤、先前手術及靜脈栓塞病史","(B) Virchow's triad可解釋靜脈栓塞的可能成因","(C) protein C、protein S及antithrombin III的缺少也是常見成因","(D) May-Thurner syndrome常為靜脈血栓的併發症"],"answer":3,"image":""},{"id":"md5-111-2-23","subject":"md5","topic":"心臟血管外科","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"有關主動脈瓣或二尖瓣狹窄之敘述，下列何者錯誤？2","options":["(A) 主動脈瓣開口小於1 cm，且走路會喘，可建議置換2","(B) 二尖瓣開口小於1.5 cm，使用二尖瓣氣球擴張成效不佳，應該建議置換","(C) 現在對主動脈瓣及二尖瓣狹窄皆有成熟且經核准之經導管置換瓣膜技術，以減少手術風險","(D) 主動脈瓣狹窄比二尖瓣狹窄惡化進展快，猝死死亡率也高"],"answer":2,"image":""},{"id":"md5-111-2-24","subject":"md5","topic":"心臟血管外科","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"50歲男性，因喘及腳腫兩個月入院，心臟超音波檢查有左心房右心房擴大，左心功能55%，中心靜脈壓為22 mmHg，肺壓為40/20 mmHg，導管壓力曲線有“square-root sign”，且電腦斷層顯示其心包膜厚度有5 mm，下列何者為最可能之診斷？","options":["(A) 右心衰竭，併左心衰竭","(B) 縮窄性心包膜炎（constrictive pericarditis）","(C) 限縮性心肌病變（restrictive cardiomyopathy）","(D) 肥厚性心肌病變（hypertrophic cardiomyopathy）"],"answer":1,"image":""},{"id":"md5-111-2-25","subject":"md5","topic":"消化器外科","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"當診斷出食道破裂，下列處理原則何者最不適當？","options":["(A) 清除致污物（contamination）","(B) 廣泛引流，控制感染源頭","(C) 延遲性發現之食道破裂，仍應先修補食道破裂處，比置放引流管重要","(D) 早期腸道灌食，營養補充"],"answer":2,"image":""},{"id":"md5-111-2-26","subject":"md5","topic":"消化器外科","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"關於巴瑞特氏食道炎（Barrett esophagus），下列敘述何者正確？","options":["(A) 主要是因胃食道逆流，使得鱗狀上皮細胞往胃內生長產生之病變","(B) 比一般人多40倍罹患食道鱗狀上皮細胞癌機會","(C) 反覆發生巴瑞特氏食道炎的病人，經長時間藥物治療無效，可考慮實施胃之抗逆流手術，改善症狀","(D) 沒有阻塞吞嚥困難（dysphagia）之症狀"],"answer":2,"image":""},{"id":"md5-111-2-27","subject":"md5","topic":"胸腔外科","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"肺腺癌原位癌（adenocarcinoma in situ）之病理診斷為下列何種型態？","options":["(A) 腺泡型（acinar）","(B) 伏壁型（lepidic）","(C) 固體型（solid）","(D) 乳頭型（papillary）"],"answer":1,"image":""},{"id":"md5-111-2-28","subject":"md5","topic":"胸腔外科","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"有關腺樣囊狀癌（adenoid cystic carcinoma）之敘述，下列何者正確？","options":["(A) 生長緩慢","(B) 大部分不會影響氣管（trachea）","(C) 很少發生喘鳴（stridor）","(D) 大多數病患診斷時已有遠端轉移，因此治療以化學治療為主"],"answer":0,"image":""},{"id":"md5-111-2-29","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"關於頸部及胸部外傷，下列敘述何者正確？","options":["(A) 頸部穿刺傷常傷及氣管，食道在其後側不易受傷，故不需檢查","(B) 若發生胸部穿刺傷，穿刺物留在胸壁層，要先移除後再送醫院處理","(C) 若發生胸部鈍傷無外表瘀青挫傷跡象，則無氣血胸的可能","(D) 若有皮下氣腫及縱隔腔氣腫則要考慮食道或氣管受傷"],"answer":3,"image":""},{"id":"md5-111-2-30","subject":"md5","topic":"胸腔外科","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"下列有關primary mediastinal cyst，何者錯誤？","options":["(A) 多半沒有症狀","(B) Bronchogenic cyst最為常見，常和支氣管相互連通","(C) Pericardial cyst易發生於右側cardiophrenic angle","(D) Enteric cyst通常生長於食道旁"],"answer":1,"image":""},{"id":"md5-111-2-31","subject":"md5","topic":"消化器外科","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"脾臟（spleen）可視為人類最大的淋巴器官，具有調節免疫系統的功能，下列對於脾臟切除（splenectomy）的敘述何者錯誤？","options":["(A) 嚴重肝硬化的病患經常合併血小板減少（thrombocytopenia），必須切除脾臟以提升血小板數目改善病患預後","(B) 外傷及手術當中醫源性的脾臟損傷是脾臟切除最常見的原因","(C) 脾臟切除後有較高風險遭受莢膜形細菌感染，如肺炎鏈球菌（Streptococcus pneumoniae）","(D) 兒童脾臟切除之後併發猛爆型感染症（overwhelming postsplenectomy infection）的風險比成人高"],"answer":0,"image":""},{"id":"md5-111-2-32","subject":"md5","topic":"消化器外科","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"短腸症（short bowel syndrome）為大量切除小腸之後的長期併發症。下列何者不是短腸症發生的危險因子（risk factors）？","options":["(A) 空腸切除（jejunal resection）200公分","(B) 未保留迴盲瓣（ileocecal valve）","(C) 合併全結腸切除（total colectomy）","(D) 克隆氏症（Crohn's disease）"],"answer":0,"image":""},{"id":"md5-111-2-33","subject":"md5","topic":"消化器外科","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"關於肝臟小葉（lobule）的敘述，下列何者正確？","options":["(A) 每一個功能單位由8～12個終端肝門三合體（portal triad）圍繞一中央小靜脈構成","(B) 肝臟小葉中可分成3帶，其中zone 1因為較缺乏養分與氧氣，容易因為毒素或缺血而產生壞死","(C) 肝竇狀隙（sinusoid）的內皮細胞與肝細胞間的間隙稱為space of Disse，肝細胞藉由擴散作用交換物質，並不產生微絨毛（microvilli）構造","(D) 肝臟星狀細胞（stellate cells）又稱Ito cells，存在於space of Disse，主要功能之一為儲存維生素Ａ"],"answer":3,"image":""},{"id":"md5-111-2-34","subject":"md5","topic":"消化器外科","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"關於肝臟分葉，下列敘述何者最恰當？","options":["(A) 從鐮狀韌帶（falciform ligament）分界","(B) 尾葉（caudate lobe）屬右肝","(C) 肝部（sector）以肝動脈走向為界","(D) 所謂Cantlie's line，係指膽囊窩至下腔靜脈的連線"],"answer":3,"image":""},{"id":"md5-111-2-35","subject":"md5","topic":"消化器外科","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"有關小腸腫瘤，下列敘述何者最恰當？","options":["(A) 良性腫瘤最常見為脂肪瘤，通常無症狀","(B) 最常見的惡性腫瘤為腺癌，好發於迴腸","(C) 類癌（carcinoid）易合併類癌症後群（carcinoid syndrome），若能手術切除治療，應儘量切除完全","(D) 基質瘤（gastrointestinal stromal tumor）的預後，主要視癌細胞分裂情況而定，與腫瘤大小無關"],"answer":2,"image":""},{"id":"md5-111-2-36","subject":"md5","topic":"消化器外科","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"下列有關胃惡性腫瘤的敘述，何者錯誤？","options":["(A) 為求正確TNM分期，胃癌手術中至少需取出16顆淋巴結","(B) AJCC在西元1997年，將胃癌的TNM分期系統中的N分期由淋巴結轉移的位置改為淋巴結轉移數目決定","(C) 3公分的胃底（gastric fundus）基質瘤（gastrointestinal stromal tumor, GIST）的標準治療是胃局部切除加上淋巴結廓清術","(D) 胃的low-grade MALT（mucosa-associated lymphoid tissue）lymphoma可用根除幽門螺旋桿菌來治療，約75%病人可達到緩解（remission）"],"answer":2,"image":""},{"id":"md5-111-2-37","subject":"md5","topic":"消化器外科","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"65歲女性因急性上腹痛及背痛至急診室就醫，經初步檢查可能診斷為膽結石引起急性胰臟炎，實習醫學生想用Ranson prognostic criteria評估嚴重度，下列何者不是評估的項目？","options":["(A) age","(B) blood glucose level","(C) total bilirubin level","(D) white blood cell count"],"answer":2,"image":""},{"id":"md5-111-2-38","subject":"md5","topic":"消化器外科","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"病態性肥胖病患接受胃繞道手術（Roux-en-Y gastric bypass），手術後正餐進食20至30分鐘後，會有胃脹、嘔吐且伴隨有頭暈、心悸與冒汗等症狀。依前述，下列何者正確？","options":["(A) 此症狀需進行迷走神經切除手術（truncal vagotomy）矯正","(B) 此症狀可藉由調整飲食習慣來改善","(C) 此症狀大部分需要藥物治療如Sandostatin（octreotide）以有效改善症狀","(D) 此症狀大部分需要手術治療，以減緩胃排空速率"],"answer":1,"image":""},{"id":"md5-111-2-39","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"一位55歲女性罹患高血壓多年，經saline loading test確診為原發性多醛酮症（primary hyperaldosteronism），為了排除是bilateral adrenal hyperplasia，下列定位檢查何者較不適當？","options":["(A) thin-cut adrenal computed tomography（CT）scan 131","(B) I-6β-iodomethyl noriodocholesterol scintigraphy（NP-59）","(C) selective adrenal vein sampling","(D) metaiodobenzylguanidine（MIBG）scan"],"answer":3,"image":""},{"id":"md5-111-2-40","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"一位60歲男性有腎結石病史，近日因聲音沙啞就醫，理學檢查發現頸部有一腫塊，抽血發現血鈣高達14.5 mg/dL及parathyroid hormone（PTH）525 pg/mL，最有可能的診斷為？","options":["(A) sarcoidosis","(B) parathyroid cancer","(C) secondary hyperparathyroidism","(D) parathyromatosis"],"answer":1,"image":""},{"id":"md5-111-2-41","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"一位65歲男性發現右頸部有一硬塊，頸部超音波檢查如附圖，細針穿刺細胞學檢查顯示為甲狀腺乳突癌（papillary thyroid cancer），根據超音波圖像，此甲狀腺癌可能合併下列何者特性？","options":["(A) lateral neck lymph node metastasis","(B) extrathyroidal extension","(C) tracheal invasion","(D) esophageal invasion"],"answer":1,"image":"md5-111-2-41.jpeg"},{"id":"md5-111-2-42","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"下列有關乳房病變之敘述，何者錯誤？","options":["(A) 乳房影像檢查沒看到腫瘤，但單側腋下淋巴有癌轉移要先排除乳癌的可能性","(B) 乳房皮膚有橘子皮變化和Cooper's ligament invasion有關","(C) 乳頭有濕疹性變化要排除Paget's disease的可能性","(D) 乳癌觸診摸到硬的腫塊是因desmoplastic reaction"],"answer":1,"image":""},{"id":"md5-111-2-43","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"關於乳癌之術後放射線治療，下列敘述何者最不適當？","options":["(A) 乳管原位癌（DCIS）之病患行乳房保留手術後，建議接受全乳放射線治療，可減少50%的癌症復發率","(B) 侵襲性乳癌病人若接受乳房保留手術則需放射線治療，但若病患年齡大於70歲、腫瘤≦T1、ER+且淋巴結無移轉，仍可考慮免除放射線治療","(C) 侵襲性乳癌病人若接受全乳切除手術則通常不需放射線治療，但淋巴結轉移較多顆或腫瘤大小超過5公分者仍需考慮","(D) 接受乳房保留手術之侵襲性乳癌，若病患年齡小於60歲，可以化學治療取代放射線治療"],"answer":3,"image":""},{"id":"md5-111-2-44","subject":"md5","topic":"內分泌與乳房外科","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"有關乳癌的荷爾蒙治療，下列敘述何者最不適當？","options":["(A) 停經前婦女不應直接選用芳香環酶抑制劑（aromatase inhibitor）","(B) 若女性荷爾蒙受體（estrogen receptor）為陽性，則即使黃體素受體（progesterone receptor）為陰性，仍可使用抗荷爾蒙藥物治療","(C) 停經後婦女不應選用泰莫西芬（tamoxifen）","(D) 若病患同時需化學藥物治療，則抗荷爾蒙藥物多於化療結束後才開始"],"answer":2,"image":""},{"id":"md5-111-2-45","subject":"md5","topic":"小兒外科","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"一男嬰出生後發現為無肛症（anorectal malformation），旋即被送至加護病房，兒童外科醫師立即被照會至現場診視，所見會陰部如圖所示，下列敘述何者正確？ћ本病患為高位無肛症，可能合併泌尿生殖道異常 ќ若腹脹或嘔吐應置放胃管 ѝ應檢查脊柱是否異常 ў應立即安排手術做腸造口","options":["(A) 僅ћў","(B) 僅ќѝ","(C) 僅ћќѝ","(D) 僅ќѝў"],"answer":1,"image":"md5-111-2-45.jpeg"},{"id":"md5-111-2-46","subject":"md5","topic":"小兒外科","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"有關先天性橫膈膜疝氣（congenital diaphragmatic hernia），下列敘述何者正確？","options":["(A) 常見為橫膈膜前內（anteromedial）側缺損，又稱Bochdalek hernia","(B) 腹部臟器經橫膈膜缺損滑入胸腔，只造成同側肺葉發育不良","(C) 目前治療的策略為出生後立即修補缺損，以減少肺部壓迫","(D) 療程中，肺動脈高壓為必須預防或積極處置的問題"],"answer":3,"image":""},{"id":"md5-111-2-47","subject":"md5","topic":"小兒外科","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"有關隱睪症之敘述，下列何者錯誤？","options":["(A) 未下降之睪丸可能在幼兒6個月大時就產生了組織及型態上之變化","(B) 未下降之睪丸其間質細胞（即萊氏細胞，Leydig cells）可能發生萎縮、輸精小管半徑減少及精蟲生成受損","(C) 一般建議之睪丸固定手術（orchidopexy）時機最好在2歲之後","(D) 睪丸固定手術後可及早偵測到睪丸癌變"],"answer":2,"image":""},{"id":"md5-111-2-48","subject":"md5","topic":"小兒外科","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"幼兒及兒童最常見之顱外實質腫瘤為下列何者？","options":["(A) 神經母細胞瘤（neuroblastoma）","(B) 腎母細胞瘤（nephroblastoma）","(C) 肝母細胞瘤（hepatoblastoma）","(D) 睪丸畸胎瘤（testicular teratoma）"],"answer":0,"image":""},{"id":"md5-111-2-49","subject":"md5","topic":"小兒外科","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"先天性橫膈疝氣（congenital diaphragmatic hernia）當需要使用葉克膜體外維生系統（ECMO）時，下列何種情況使用ECMO治療最可能預後不佳？","options":["(A) 心臟超音波正常","(B) 體重1.7公斤","(C) 妊娠週數（gestational age）36週","(D) 出現氣胸（pneumothorax）"],"answer":1,"image":""},{"id":"md5-111-2-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"潰瘍性大腸炎（ulcerative colitis）手術的適應症，下列何者錯誤？","options":["(A) 猛爆性腸炎（fulminant colitis）且藥物治療無效","(B) 每日腹瀉5次","(C) 毒性巨結腸症（toxic megacolon）","(D) 病理切片出現細胞分化不良的病灶"],"answer":1,"image":""},{"id":"md5-111-2-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"111年第2次第51題","year":111,"session":2,"number":51,"question":"下列那一段結腸或直腸（colon and rectum）並未附著於後腹腔（retroperitoneum）？","options":["(A) 升結腸","(B) 降結腸","(C) 橫結腸","(D) 直腸"],"answer":2,"image":""},{"id":"md5-111-2-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"111年第2次第52題","year":111,"session":2,"number":52,"question":"有關hereditary nonpolyposis colon cancer，下列敘述何者錯誤？","options":["(A) 為autosomal dominant disease","(B) 與mismatch repair基因缺損相關","(C) 須在20歲前進行預防性手術","(D) MSH6的缺損和子宮內膜癌相關"],"answer":2,"image":""},{"id":"md5-111-2-53","subject":"md5","topic":"消化器外科","meta":"111年第2次第53題","year":111,"session":2,"number":53,"question":"考慮腹腔鏡修補腹股溝疝氣（inguinal hernia）的方法時，常用的技術包括腹腔鏡全腹膜外疝氣修補術（totally extraperitoneal approach, TEP）與經腹腔腹膜前網片修補術（transabdominal preperitoneal approach, TAPP），下列有關此二種修補術之敘述何者錯誤？","options":["(A) TEP與TAPP疝氣修補術方法和技術的主要區別在於進入腹膜前間隙的順序","(B) 使用TEP可以更快地進行腹膜前解剖，並將腹膜內臟損害的潛在風險降到最低","(C) 和TEP相比較，使用TAPP手術操作空間較為有限","(D) 在超過1,000名患者的實證醫學證據分析（cochrane review）中，TAPP與TEP修補的疝氣復發率沒有差異"],"answer":2,"image":""},{"id":"md5-111-2-54","subject":"md5","topic":"消化器外科","meta":"111年第2次第54題","year":111,"session":2,"number":54,"question":"減肥手術大多使用腹腔鏡方式操作，其治療原理包含限制性（restrictive）手術和吸收不良（malabsorptive）手術。關於減肥手術的治療原理及結果，下列何者正確？ћ胃袖狀切除手術（laparoscopic sleeve gastrectomy, LSG）主要為吸收不良手術 ќ胃繞道引流手術（Roux-en-Y）為限制性手術和吸收不良手術 ѝ膽胰繞道手術（biliopancreatic diversion, BPD）為吸收不良及輕度限制手術 ў垂直帶狀胃成形術（vertical banded gastroplasty）因為手術死亡率高已被放棄 џ膽胰繞道手術（BPD）有助於減少十二指腸開關手術（duodenal switch, DS）後邊緣性潰瘍（marginal ulcer）的發生","options":["(A) ћќѝ","(B) ѝўџ","(C) 僅ќѝ","(D) 僅ўџ"],"answer":2,"image":""},{"id":"md5-111-2-55","subject":"md5","topic":"消化器外科","meta":"111年第2次第55題","year":111,"session":2,"number":55,"question":"下列有關單一切口腹腔鏡手術（single-incision laparoscopic surgery）效益之敘述，下列何者錯誤？","options":["(A) 多通道的端口（multichannel port）較適合置放在經肚臍（intraumbilical）的位置，但特別手術亦可經肚臍外置放（extraumbilical approach）","(B) 臨床上進行單一切口手術，有時需要增加額外的端口（extra ports）","(C) 可以應用縫合（suture）技巧來當作牽引法","(D) 單一切口傷口縫合應使用不可吸收線材進行連續或間斷縫合法"],"answer":3,"image":""},{"id":"md5-111-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第2次第56題","year":111,"session":2,"number":56,"question":"下列關於惡性軟骨肉瘤（chondrosarcoma）的敘述，何者最適當？","options":["(A) 惡性軟骨肉瘤常見於骨盆，10～20歲的青少年","(B) 惡性軟骨肉瘤的mesenchymal chondrosarcoma，常見於epiphysis of the proximal femur","(C) 惡性軟骨肉瘤對化療及放療敏感，手術切除為次要治療方法","(D) 骨軟骨瘤（osteochondroma）的cartilage cap若追蹤時發現厚度＞2cm，需注意評估secondary chondrosarcoma"],"answer":3,"image":""},{"id":"md5-111-2-57","subject":"md5","topic":"外科-休克創傷傷口","meta":"111年第2次第57題","year":111,"session":2,"number":57,"question":"25歲男性騎車被卡車輾壓受傷，在急診室血壓90/50 mmHg，脈搏110次／分，呼吸急促，腹部鼓脹，生殖器尿道口有血跡，雙側下肢不等長，下列敘述與處置何者最不適當？","options":["(A) 應確保呼吸道通暢，並儘速建立大管徑靜脈導管，給與大量靜脈輸液及輸血治療","(B) 應排除氣血胸、腹腔內出血急症，儘速安排腹部超音波及diagnostic peritoneal lavage","(C) 要懷疑合併骨盆骨折及關節脫臼，可能有後腹膜腔出血，及早使用骨盆加壓帶（pelvic binder）","(D) 應立即放置導尿管（Foley catheter），確保並有效監控靜脈輸液量及電解質平衡"],"answer":3,"image":""},{"id":"md5-111-2-58","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"111年第2次第58題","year":111,"session":2,"number":58,"question":"下列關於髖臼解剖構造及損傷後相關關檢查的敘述，何者最適當？","options":["(A) 髖臼是由三向放射狀軟骨（triradiatee cartilage）組成，並由透明軟骨（hyaline cartillage）所覆蓋","(B) 兩種骨盆斜位照（oblique views）藉藉由朝向或遠離患側傾斜60度拍攝，補骨盆正正位前後照（AP view）的不足之處","(C) 內斜位照（internal oblique view / obtuurator view）可展現後柱（posterior column），包含坐骨棘（ischial spine）與髖臼前壁（anterior wall of the acetaabulum）","(D) 外斜位照（external oblique view / iliaac view）可展現前柱（anterior column）及髖臼後緣（posterior lip of the acetabulum）"],"answer":0,"image":""},{"id":"md5-111-2-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"111年第2次第59題","year":111,"session":2,"number":59,"question":"下列肌肉與造成骨盆及髖部撕除性骨骨折（avulsion fracture）的組合，何者最不適當？","options":["(A) 腹部肌肉（abdominal muscle）與髂嵴嵴（iliac crest）","(B) 股直肌（rectus femoris）與髂前上棘棘（anterior superior iliac spine）","(C) 繩肌（hamstring muscle）與坐骨結節節（ischial tuberosity）","(D) 髂腰肌（iliopsoas）與股骨小轉子（（lesser trochanter of the femur）"],"answer":1,"image":""},{"id":"md5-111-2-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第2次第60題","year":111,"session":2,"number":60,"question":"在新生兒大腿內側發現不對稱的皮膚膚皺褶（asymmetric skin fold）時，下列何種檢查查或徵象最不相關？","options":["(A) Galeazzi氏徵象（Galeazzi sign）","(B) Barlow氏檢查（Barlow test）","(C) Patrick氏檢查（Patrick test）","(D) Ortolani氏檢查（Ortolani test）"],"answer":2,"image":""},{"id":"md5-111-2-61","subject":"md5","topic":"神經外科","meta":"111年第2次第61題","year":111,"session":2,"number":61,"question":"陳先生是個上班族，發現右手無名指指尺側及小指在講電話一段時間後有麻木的狀況況，且小指屈指深肌比較無力，發生此神經壓迫症狀的位置最常常在下列何處？","options":["(A) Guyon tunnel","(B) arcade of Struthers","(C) carpal tunnel","(D) arcade of Frohse"],"answer":1,"image":""},{"id":"md5-111-2-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"111年第2次第62題","year":111,"session":2,"number":62,"question":"有關椎間盤突出症（HIVD）之敘述，，下列何者最不適當？","options":["(A) protrusion、extrusion和sequestration三種突出中，protrusion type是最常見的類型","(B) 通常需要手術治療才可以將神經減壓壓，進而解除神經痛以達到最佳的療效","(C) 有症狀及徵象時，磁振造影（MRI））是診斷椎間盤突出症最佳的檢查","(D) 術後感染（infection）、硬膜撕裂（（dural tear）、神經根損傷（nerve root injury）及及復發性椎間盤突出症（recurrent HIVD）是最常見的術後併併發症"],"answer":1,"image":""},{"id":"md5-111-2-63","subject":"md5","topic":"骨科-關節重建","meta":"111年第2次第63題","year":111,"session":2,"number":63,"question":"一位25歲的年輕男性因為車禍，X光光檢查如圖所示，下列敘述與處置何者最適當？","options":["(A) 根據Garden氏分類，屬於stage II不完全骨折（incomplete fracture）","(B) 建議施行雙極式人工半髖關節置換術（bipolar hemiarthroplasty）","(C) 發生股骨頭缺血壞死以及骨折不癒合的機率很高，手術前應該先做bone scan評估","(D) X光片顯示Shenton line不連續，代表骨折移位的程度較大"],"answer":3,"image":"md5-111-2-63.jpeg"},{"id":"md5-111-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"111年第2次第64題","year":111,"session":2,"number":64,"question":"接受體外震波碎石術（extracorporeal shock wave lithotripsy）治療時，下列何者不是禁忌症（contraindications）？","options":["(A) 肥胖的病人","(B) 未經治療的凝血功能異常","(C) 病人的結石附近有嚴重的骨骼畸形","(D) 病人的結石附近有動脈血管瘤（arterial aneurysm）"],"answer":0,"image":""},{"id":"md5-111-2-65","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"111年第2次第65題","year":111,"session":2,"number":65,"question":"一位70歲男性主訴最近一個月排尿困難、頻尿、夜尿三次，就醫時發現血清前列腺特定抗原（PSA）為7.2 ng/mL，尿液檢查發現WBC 50-60/HPF，肛門指診顯示前列腺為4.5×4公分，軟硬度正常沒有硬塊，沒有壓痛，下一步最適當的處置為何？","options":["(A) 檢查游離型前列腺特定抗原（free PSA）","(B) 安排前列腺多變項核磁共振檢查（multiparametric MRI）","(C) 經直腸超音波導引前列腺切片（TRUS guided prostate biopsy）","(D) 先給與抗生素治療"],"answer":3,"image":""},{"id":"md5-111-2-66","subject":"md5","topic":"泌尿-腫瘤","meta":"111年第2次第66題","year":111,"session":2,"number":66,"question":"一位50歲女性，於塑膠工廠工作，主訴無痛性血尿，沒有頻尿，解出的尿液整段都是紅的，並有條狀的血塊，肌酸酐（creatinine）是3.0 mg/dL，下列敘述何者最適當？","options":["(A) 血尿的出處最可能是膀胱","(B) 尿液細胞學檢查的敏感性（sensitivity）高","(C) 安排注射顯影劑電腦斷層尿路攝影（CT urography）","(D) 安排逆行性腎盂攝影（retrograde pyelography）"],"answer":3,"image":""},{"id":"md5-111-2-67","subject":"md5","topic":"小兒外科","meta":"111年第2次第67題","year":111,"session":2,"number":67,"question":"下列有關威爾姆氏腫瘤（Wilms tumor）之敘述，何者錯誤？","options":["(A) 占兒童腫瘤約5%","(B) 約10%病人合併有先天發育不良","(C) 與WT2基因表現有關","(D) 最常轉移到肺臟及肝臟"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第67題，一律給分。。 (原公告答案 C)"},{"id":"md5-111-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"111年第2次第68題","year":111,"session":2,"number":68,"question":"支配尿道外括約肌（external urethral sphincter）的神經是：","options":["(A) 骨盆神經（pelvic nerve）","(B) 下腹神經（hypogastric nerve）","(C) 閉孔神經（obturator nerve）","(D) 會陰神經（pudendal nerve）"],"answer":3,"image":""},{"id":"md5-111-2-69","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"111年第2次第69題","year":111,"session":2,"number":69,"question":"下列有關精索靜脈曲張之敘述何者錯誤？","options":["(A) 為最常見可手術矯正之男性不孕症病因","(B) 不孕症男性診斷出精索靜脈曲張之比例約40%","(C) 罹患此症者精液分析結果常可發現精蟲數量、型態與活動力異常","(D) 使用經皮血管攝影及栓塞內精索靜脈的治療成功率最高"],"answer":3,"image":""},{"id":"md5-111-2-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"111年第2次第70題","year":111,"session":2,"number":70,"question":"下列何者先天性泌尿道異常，最不會引起腎積水（hydronephrosis）？","options":["(A) 後尿道瓣膜（posterior urethral valve）","(B) 輸尿管腎盂接合處阻塞（ureteropelvic junction obstruction）","(C) 輸尿管複製（duplicated ureter）","(D) 尿道下裂（hypospadias）"],"answer":3,"image":""},{"id":"md5-111-2-71","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"111年第2次第71題","year":111,"session":2,"number":71,"question":"一位5歲的男孩出生時即有脊髓膜膨出症（meningomyelocele）、尿失禁及排尿困難，兩側腎臟輕度積水，膀胱尿道排尿攝影發現右側有第一度膀胱輸尿管尿液逆流，下列何種處置不適合？","options":["(A) 間歇性清潔導尿以排空膀胱","(B) 可考慮給與抗膽鹼藥物以減少尿失禁","(C) 定期進行尿路動力學檢查，以偵測膀胱及尿道功能","(D) 儘早施行輸尿管重建手術，以減少尿路感染的發生"],"answer":3,"image":""},{"id":"md5-111-2-72","subject":"md5","topic":"心臟血管外科","meta":"111年第2次第72題","year":111,"session":2,"number":72,"question":"35歲男性病人，主訴持續一星期的單側下肢腫脹，但無發燒症狀。雙側下肢靜脈注射顯影劑電腦斷層影像如圖所示，下列關於病況的敘述何者最恰當？","options":["(A) 腫脹的下肢是在右側","(B) 大部分這類病患都需要緊急開刀","(C) 對這種疾病而言，超音波並不適合做為診斷工具","(D) 如果不做適當處置，病患接下來可能會有呼吸困難的症狀"],"answer":3,"image":"md5-111-2-72.jpeg"},{"id":"md5-111-2-73","subject":"md5","topic":"消化器外科","meta":"111年第2次第73題","year":111,"session":2,"number":73,"question":"慢性胰臟炎的鈣化表現（calcifications of the chronic pancreatitis），下列敘述何者最不恰當？","options":["(A) 會出現斑駁鈣化（spotted or mottled calcification）","(B) 在腰椎第一節和第二節的高度，鈣化以水平方向分布","(C) 慢性胰臟炎的鈣化在Ｘ光影像上幾乎都清晰可見","(D) 相較於Ｘ光影像，電腦斷層影像較容易辨識鈣化"],"answer":2,"image":""},{"id":"md5-111-2-74","subject":"md5","topic":"胸腔外科","meta":"111年第2次第74題","year":111,"session":2,"number":74,"question":"關於胸腔的轉移性惡性腫瘤，下列敘述何者最恰當？","options":["(A) 幾乎都會合併縱隔及肺門淋巴結轉移且腫大","(B) 基本上轉移至肺部的病灶絕大部分都呈多角型且邊緣不規則，而呈現球型且邊緣平滑者很少見","(C) 肋膜轉移大部分都是單一結節且極少產生肋膜積液","(D) 攝護腺癌轉移至肋骨可為成骨性病灶（osteoblastic lesion）"],"answer":3,"image":""},{"id":"md5-111-2-75","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"111年第2次第75題","year":111,"session":2,"number":75,"question":"有關腹腔鏡（laparoscopy）手術的併發症中，下列何者最不適當？","options":["(A) 腹腔鏡手術時所造成的腹部積氣（pneumoperitoneum），可能造成心律不整","(B) 可能造成二氧化碳栓塞（carbon dioxide embolization）","(C) 套管針（trocar）置放不當，可能造成腸道或其他腹內臟器傷害","(D) 腹腔鏡手術所造成的腹壁小傷口，不會造成腹壁或切口疝氣（incisional hernia）"],"answer":3,"image":""},{"id":"md5-111-2-76","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"111年第2次第76題","year":111,"session":2,"number":76,"question":"一位51歲病人，接受右肝切除手術後的壓力反應（stress response），包括代謝率改變、發炎介質產生及內分泌變化等等，下列敘述何者錯誤？","options":["(A) 術後病人的能量消耗可以比基礎代謝率低20%","(B) cortisol, epinephrine及glucagon增加","(C) alanine被肝臟代謝，作為腸道及免疫系統之主要能量來源","(D) 呼吸商數（respiratory quotient）會下降"],"answer":2,"image":""},{"id":"md5-111-2-77","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"111年第2次第77題","year":111,"session":2,"number":77,"question":"24歲男性，腹痛三天後才就醫，醫師發現他右下腹痛得最厲害，診斷為闌尾炎，須接受手術，這位病人手術後最常發生的併發症為下列何者？","options":["(A) 肺炎","(B) 腸阻塞","(C) 腸皮下瘻管","(D) 手術部位感染"],"answer":3,"image":""},{"id":"md5-111-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"111年第2次第78題","year":111,"session":2,"number":78,"question":"26歲男性病人，發生嚴重車禍，導致病人頭部創傷重度昏迷，病人腦部電腦斷層結果顯示右側顱內有大量硬腦膜下出血，導致嚴重腦幹壓迫有急迫生命危險，要儘快幫病人做緊急開顱減壓手術，病人才有比較好的存活機率，不過開刀病人也可能會死，但卻沒有找到病人家屬，以告知手術治療的必要性與高度不確定的手術結果。醫師是否應該為其進行手術？","options":["(A) 不應該。沒有同意書不應手術","(B) 不應該。沒有家屬在場不應手術","(C) 應該。反正不動手術也可能會死","(D) 應該。情況緊急者，以病人生命為優先考量"],"answer":3,"image":""},{"id":"md5-111-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"111年第2次第79題","year":111,"session":2,"number":79,"question":"李先生因為車禍，肝臟脾臟嚴重破裂大量出血，送到急診時已呈休克，意識昏迷，必須立即接受剖腹探查止血，但119人員發現他的口袋裡有一張紙條寫著因為是耶和華見證會會員，他本人任何狀況下都拒絕輸血，並附有簽名。但是跟在李先生旁邊的太太卻哀求著：「醫師，請你盡一切力量救他，請為他開刀，一切後果由我負責。」醫師知道如果開刀，因為紓解腹壓，一定會大量出血，不輸血一定會死亡，下列何種處理方式較恰當？","options":["(A) 請李太太簽字，表示由她負起一切責任，然後就替李先生輸血開刀","(B) 救人要緊，盡一切力量救治，包括手術與輸血治療","(C) 答應他太太，輸血手術治療，事後再騙李先生沒有輸血","(D) 盡一切力量救治，但不施行輸血治療"],"answer":3,"image":""},{"id":"md5-111-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"111年第2次第80題","year":111,"session":2,"number":80,"question":"A醫師是一位熱心教學的乳房外科醫師，為指導住院醫師正確之身體檢查技巧，A醫師利用病患在麻醉後失去意識時，進行理學檢查之臨床教學。下列何者正確？","options":["(A) 一定要病人知情同意後才能用於教學","(B) 現實狀況下，這是不得已的選擇","(C) 只要有女性護理同仁陪同就可","(D) 臨床教學時，只能觸摸有病變的那一側"],"answer":0,"image":""},{"id":"md5-112-1-1","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"一位外傷病人被送到急診急救，若決定病人需要緊急輸血，但又不清楚病人的血型時，下列敘述何者最恰當？","options":["(A) 可以輸O型的全血","(B) 可以輸O型的紅血球","(C) 可以輸O型的血漿","(D) 不可以馬上輸血，應等到血型清楚以後再輸同血型的血品"],"answer":1,"image":""},{"id":"md5-112-1-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"有關胸部外傷，下列敘述何者錯誤？","options":["(A) 低部位肋骨骨折的病人（例如9th-12th ribs fracture）應考慮做腹部電腦斷層檢查，評估腹內是否有其他器官受傷","(B) 小孩未發育完成，因此比起成年人，小孩的肋骨較容易因為鈍傷而造成骨折","(C) 有氣胸的小孩與成年人做比較，小孩容易發展成張力性氣胸","(D) 患者即使有少量的氣胸（氣胸量＜10%），若需要轉院時，仍應放置胸管"],"answer":1,"image":""},{"id":"md5-112-1-3","subject":"md5","topic":"消化器外科","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"病人接受胰頭十二指腸切除手術之後，需進行消化道之重建，最容易造成術後滲漏的吻合處為下列何者？","options":["(A) 胃部空腸吻合","(B) 膽管空腸吻合","(C) 胰體空腸吻合","(D) 各吻合處滲漏之機率沒有太大的差異"],"answer":2,"image":""},{"id":"md5-112-1-4","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"下列有關肝細胞癌的Barcelona Clinic Liver Cancer（BCLC）臨床分期和治療之相關敘述，何者錯誤？","options":["(A) 臨床分期分成stage 0、A、B、C、D","(B) 分期依據包括腫瘤大小、Child score及performance status等","(C) chemoembolization為一種curative treatment","(D) 對於BCLC stage C的晚期患者來說，可以考慮使用標靶藥物如sorafenib"],"answer":2,"image":""},{"id":"md5-112-1-5","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"下列何者不是理想傷口敷料的特性？","options":["(A) 防止微生物通透","(B) 創造乾燥清爽環境","(C) 提供機械性保護","(D) 易於操作"],"answer":1,"image":""},{"id":"md5-112-1-6","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"下列何者為腎臟移植的絕對禁忌症？","options":["(A) 開放性肺結核病的末期腎衰竭病人","(B) 愛滋病帶原者接受定期治療，且病情穩定的末期腎衰竭病人","(C) 年齡超過70歲的末期腎衰竭病人","(D) 大腸癌接受治療後，超過五年無復發的末期腎衰竭病人"],"answer":0,"image":""},{"id":"md5-112-1-7","subject":"md5","topic":"消化器外科","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"關於盲環症候群（blind loop syndrome）的病人，下列敘述何者最不恰當？","options":["(A) 容易發生脂肪瀉（steatorrhea）","(B) 應補充維他命B12","(C) 腸胃道中細菌過度孳生所致","(D) 容易發生小紅血球貧血（microcytic anemia）"],"answer":3,"image":""},{"id":"md5-112-1-8","subject":"md5","topic":"神經外科","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"腦部星狀細胞瘤（astrocytoma），WHO腫瘤分級：I～IV，下列相關之敘述何者正確？","options":["(A) grade I與II屬低惡性度","(B) grade III與IV屬高惡性，統稱glioblastoma multiforme（GBM）","(C) 預後極差，在診斷後，grade I～IV median survival都不超過3年","(D) 切除手術會造成神經損傷，故以化學治療及放射線治療為主"],"answer":0,"image":""},{"id":"md5-112-1-9","subject":"md5","topic":"神經外科","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"一位68歲男性於早上被家人發現臥於床上叫不醒，枕頭與嘴邊有嘔吐物，送來急診時昏迷指數為E1V1M4，血壓196/103 mmHg，心跳72/min，電腦斷層檢查如圖，下列敘述何者正確？","options":["(A) 病人來到急診時會以半側肢體無力表現","(B) 為維持腦部血管灌流充足，不可以降血壓","(C) 應為外傷造成的出血，應懷疑家人是否有謊報病史","(D) 病人的高血壓、冠狀動脈心臟病病史與這次的出血有相關性"],"answer":3,"image":"md5-112-1-9.jpeg"},{"id":"md5-112-1-10","subject":"md5","topic":"神經外科","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"承上題，有關這位病人的治療處置，下列何者錯誤？","options":["(A) 可能有合併阻塞性水腦症，需做腦室外引流","(B) 僅需保守治療給與類固醇降低腦腫脹即可，不需要手術移除血塊","(C) 若出血惡化，進一步擴大，可能會壓迫腦幹造成猝死","(D) 此為常見自發性出血區域之一"],"answer":1,"image":""},{"id":"md5-112-1-11","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"關於腰椎退化性病變造成神經管狹窄，甚至造成椎體滑脫的敘述，下列何者最適當？","options":["(A) 典型的症狀為長期嚴重的下背痛，無法走遠、騎腳踏車和久坐","(B) 症狀會隨著病患站立和挺起腰椎（extension）而得到緩解","(C) 如為第五腰椎pars interarticularis退化性斷裂，可能造成腰椎第4～5節滑脫併椎管狹窄","(D) 可先以保守治療為主，如果症狀沒有改善，甚至神經症狀加劇，或有小便困難情形，則需住院手術治療"],"answer":3,"image":""},{"id":"md5-112-1-12","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"關於脊椎Jefferson fracture，下列敘述何者正確？","options":["(A) 主要是第一頸椎受到前屈外力（flexion）所導致","(B) 大部分會造成嚴重的神經功能損傷","(C) 必須經頸椎核磁共振檢查才能診斷","(D) 如合併韌帶斷裂，可造成第一、二頸椎不穩定脫位"],"answer":3,"image":""},{"id":"md5-112-1-13","subject":"md5","topic":"神經外科","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"頭骨骨裂病患，下列何種情形須馬上手術？","options":["(A) 顳骨骨折導致顏面神經麻痺","(B) 前顱窩骨折導致腦脊髓液鼻漏","(C) 顳骨骨折導致腦脊髓液鼻漏","(D) 腦實質出血35 mL，造成電腦斷層中線偏移大於1 cm，合併神智改變"],"answer":3,"image":""},{"id":"md5-112-1-14","subject":"md5","topic":"整形重建外科","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"有關先天性黑色素細胞痣（congenital melanocytic nevus, CMN）的敘述，下列何者正確？①20～49.9 cm為大型（large）CMN，＞50 cm為巨大（giant）CMN ②大型和巨大CMN發展成黑色素細胞瘤的機率比小型CMN還高 ③ 大型和巨大CMN患者有較高的機會在腦膜有黑色素細胞異常增生（leptomeningeal involvement），可藉由MRI作診斷 ④ 小型CMN如果發展出黑色素細胞瘤，多發生在青春期後","options":["(A) 僅①③","(B) 僅②④","(C) 僅①②④","(D) ①②③④"],"answer":3,"image":""},{"id":"md5-112-1-15","subject":"md5","topic":"整形重建外科","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"有關顯微組織皮瓣（microvascular free flaps），下列敘述何者錯誤？","options":["(A) 肌肉可以忍受的熱缺血時間（warm ischemia time）為4～6小時","(B) 不論是end-to-end或end-to-side的動脈接合方式，血液成功流通的機率其實差不多","(C) 當兩條血管粗細不一樣時，end-to-side anastomoses是一個合適的解決方式","(D) 為了預防皮瓣移植過程中發生vasospasm，可將血管的外膜（tunica adventitia）剝除以降低交感神經影響"],"answer":0,"image":""},{"id":"md5-112-1-16","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"下列手部掌內肌群（intrinsic muscles），何者不是由正中神經（median nerve）所支配？","options":["(A) abductor pollicis brevis","(B) adductor pollicis","(C) flexor pollicis brevis","(D) opponens pollicis"],"answer":1,"image":""},{"id":"md5-112-1-17","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"關於唾液腺腫瘤（salivary gland tumor），下列敘述何者錯誤？","options":["(A) 唾液腺腫瘤（salivary gland tumor）相對少見，在頭頸部癌總數占＜2%","(B) 大多數唾液腺腫瘤（salivary gland tumor）發生在腮腺（parotid gland），其中以多形性腺瘤（pleomorphic adenomas）為最常見之良性腫瘤","(C) 腺樣囊狀癌（adenoid cystic carcinoma）病理切片下若為tubular pattern則預後較差","(D) 黏液表皮樣癌（mucoepidermoid carcinoma）為最常見之唾液腺惡性腫瘤，high grade多為epidermoid type；low grade多為mucinous type"],"answer":2,"image":""},{"id":"md5-112-1-18","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"照片顯示之乳房病灶，最有可能為下列何種疾病？","options":["(A) Mondor's disease","(B) Paget's disease","(C) duct ectasia","(D) acute mastitis"],"answer":1,"image":"md5-112-1-18.jpeg"},{"id":"md5-112-1-19","subject":"md5","topic":"心臟血管外科","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"關於心臟手術中使用的體外循環（cardiopulmonary bypass），下列敘述何者錯誤？","options":["(A) 常見的動脈管路置放位置包含升主動脈、無名動脈、腋動脈或股動脈","(B) 2當體溫下降至20℃時，體外循環機需提供至少2.4 L/min/m的流量","(C) 可能產生的負面影響包含全身性發炎反應、栓塞、凝血路徑影響、周邊器官功能不足（end-organ dysfunction）等","(D) 當心臟停跳，血液循環完全依靠體外循環時，呼吸器即可完全暫停"],"answer":1,"image":""},{"id":"md5-112-1-20","subject":"md5","topic":"心臟血管外科","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"在一些下肢深層靜脈栓塞（deep venous thrombosis, DVT）的病人，須放置下腔靜脈過濾器（IVC filter），但下列何者不需要？","options":["(A) 慢性下腔靜脈完全阻塞","(B) 有絕對禁忌症無法使用抗凝血劑","(C) 在足夠的抗凝血劑劑量下仍復發DVT","(D) 慢性肺栓塞合併肺高壓"],"answer":0,"image":""},{"id":"md5-112-1-21","subject":"md5","topic":"心臟血管外科","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"下肢動脈阻塞疾病的Fontaine分類，下列何者正確？","options":["(A) 組織喪失（tissue loss）為stage I","(B) 壞死（gangrene）為stage II","(C) ischemic rest pain為stage III","(D) claudication為stage IV"],"answer":2,"image":""},{"id":"md5-112-1-22","subject":"md5","topic":"心臟血管外科","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"馬凡氏症（Marfan syndrome）是因體內何蛋白質異常造成？","options":["(A) elastin","(B) metalloproteinase","(C) collagen","(D) fibrillin"],"answer":3,"image":""},{"id":"md5-112-1-23","subject":"md5","topic":"胸腔外科","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"有關全肺靜脈異常（total anomalous pulmonary venous connection, TAPVC）之敘述，何者錯誤？","options":["(A) 手術治療infracardiac type與supracardiac type TAPVC時，建議保留垂直靜脈（vertical vein），不截紥或不截斷","(B) 不論是否有阻塞之單純TAPVC，應建議手術矯正","(C) 無縫之修復法（sutureless repair）適合用於全肺靜脈異常術後再狹窄之病患","(D) 心導管（cardiac catheterization）之檢查已經是非必要之檢查"],"answer":0,"image":""},{"id":"md5-112-1-24","subject":"md5","topic":"心臟血管外科","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"最常合併主動脈脫垂或逆流的心室中隔缺損為下列何者？","options":["(A) 小的（＜3 mm）perimembranous type（type II）","(B) 大的（＞5 mm）perimembranous type（type II）","(C) subarterial type（type I）","(D) muscular type"],"answer":2,"image":""},{"id":"md5-112-1-25","subject":"md5","topic":"消化器外科","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"關於胃食道逆流（gastroesophageal reflux disease, GERD），下列敘述何者正確？","options":["(A) 微創內視鏡手術進步，傷害小，因此胃食道逆流以手術為最優先最佳之選擇","(B) 胃食道逆流也可能會使病人產生氣喘症狀","(C) heartburn常見於心肌梗塞病人，很少發生在胃食道逆流病人身上","(D) 胃食道逆流與食道弛緩症（achalasia）一樣，發生時間長久後，會有巨大食道（megaesophagus）產生"],"answer":1,"image":""},{"id":"md5-112-1-26","subject":"md5","topic":"消化器外科","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"關於食道癌之敘述，下列何者錯誤？","options":["(A) 胃食道鏡切片為確認食道癌診斷之工具","(B) 使用鋇劑食道攝影檢查時，發現有鳥嘴徵象（bird's beak sign），為食道癌之診斷標準","(C) 對於早期食道癌，胃食道鏡黏膜切除（endoscopic mucosal resection, EMR），除了可以獲得標本外，也可知腫瘤侵犯深度","(D) 即使被鋇劑食道攝影診斷為食道蠕動問題，只要病人有吞嚥困難問題，仍應安排胃食道鏡檢查"],"answer":1,"image":""},{"id":"md5-112-1-27","subject":"md5","topic":"胸腔外科","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"關於肺腺癌（adenocarcinoma）之敘述，下列何者錯誤？","options":["(A) 是肺癌中最常見的組織型態（histologic type）","(B) 好發於支氣管上皮（bronchial epithelium）的mucus-producing cells","(C) 大多位在周邊（peripherally located）","(D) 與肺鱗狀上皮細胞癌（squamous cell carcinoma）相比，較不易轉移至腦部"],"answer":3,"image":""},{"id":"md5-112-1-28","subject":"md5","topic":"胸腔外科","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"有關類癌（carcinoid）之敘述，下列何者錯誤？","options":["(A) 典型類癌（typical carcinoid）預後最佳","(B) 類癌症後群（carcinoid syndrome）於典型類癌（typical carcinoid）很常見","(C) 非典型類癌（atypical carcinoid）可能產生遠端轉移","(D) 治療方式以手術切除為主"],"answer":1,"image":""},{"id":"md5-112-1-29","subject":"md5","topic":"胸腔外科","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"有關肺臟外傷之外科介入，下列敘述何者正確？","options":["(A) 為了止血進行肺部穿刺傷縫合時，術中或術後可能會發生空氣栓塞甚至死亡","(B) 肺臟外傷病患行pneumonectomy可增加存活率","(C) pulmonary tractotomy無法提供有效的止血，所以建議直接行pneumonectomy","(D) 為了有效控制出血，pneumonectomy為最常用的術式"],"answer":0,"image":""},{"id":"md5-112-1-30","subject":"md5","topic":"胸腔外科","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"有關成人縱隔腔腫瘤，下列敘述何者錯誤？","options":["(A) benign teratoma若無法完全切除，只進行部分切除以緩解症狀，也鮮少復發","(B) 後縱隔腫瘤常為neurogenic tumor","(C) 化學治療及放射治療通常對seminoma效果良好","(D) 縱隔惡性生殖細胞瘤的發生率沒有性別差異"],"answer":3,"image":""},{"id":"md5-112-1-31","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"肝臟移植被認為是治療肝硬化合併肝細胞癌（hepatocellular carcinoma）病患的有效治療方法，下列肝細胞癌患者的腫瘤狀態何者較不建議接受肝臟移植治療？﹝Child-Turcotte-Pugh score簡稱CTP score﹞","options":["(A) 50歲男性，B型肝炎患者，CTP score=8，兩顆腫瘤2.0 cm與2.5 cm分別位於segment III和segment VII，無肝外轉移及大血管侵犯","(B) 60歲女性，C型肝炎患者，CTP score=10，單顆腫瘤4.5 cm位於segment VIII，無肝外轉移及大血管侵犯","(C) 58歲男性，C型肝炎患者，CTP score=7，三顆腫瘤1.0 cm、2.0 cm與1.0cm分別位於segment II、segment V和segment VII，無肝外轉移及大血管侵犯","(D) 40歲男性，B型肝炎患者，CTP score=5，單顆腫瘤2.0 cm位於segment II，無肝外轉移及大血管侵犯"],"answer":3,"image":""},{"id":"md5-112-1-32","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"關於轉移性肝臟惡性腫瘤（metastatic liver tumor），下列敘述何者錯誤？","options":["(A) 最常見的轉移性肝臟腫瘤來自大腸直腸癌（colorectal cancer）","(B) 近50%～60%的大腸直腸癌（colorectal cancer）患者包括新診斷或術後追蹤，在其一生中會出現肝臟轉移","(C) 基於化學藥物治療的發展及肝臟手術的精進，肝臟切除腫瘤已經成為治療大腸直腸癌肝臟轉移的標準治療","(D) 多發性的大腸直腸癌肝臟轉移，既使接受手術治療預後也不好，只能以化學藥物治療"],"answer":3,"image":""},{"id":"md5-112-1-33","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"胰臟移植（pancreas transplantation）可以重建胰島素（insulin）的血糖代謝且可以改善糖尿病患者的生活品質，下列何種類別的胰臟移植相較其他類別，移植比例最高而且移植後病患整體預後也最好？","options":["(A) 糖尿病患者合併腎衰竭尿毒症同時接受胰臟及腎臟移植（simultaneous pancreas and kidney transplant, SPK）","(B) 糖尿病患者合併腎衰竭尿毒症接受過腎臟移植之後再接受胰臟移植（pancreas after kidney transplant, PAK）治療糖尿病","(C) 糖尿病患者未合併尿毒症，但血糖不易控制接受胰臟移植（pancreas transplant alone, PTA）改善生活品質","(D) 糖尿病患者合併腎衰竭尿毒症先接受胰臟移植（pancreas before kidney transplant, PBK）之後再等待腎臟移植"],"answer":0,"image":""},{"id":"md5-112-1-34","subject":"md5","topic":"消化器外科","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"下列對於胰臟內分泌瘤的敘述何者錯誤?","options":["(A) insulinoma是最常見的胰臟內分泌瘤，其主要症狀為Whipple triad，包含symptomatic fasting hypoglycemia, serum glucose level < 50 mg/dL, relief of symptoms with the administration of glucose","(B) 70-90% insulinoma發生於Passaro's triangle，此區的範圍是由junction of the cystic duct and common bile duct, the 2nd and 3rd portion of the duodenum和the neck and body of the pancreas組成的三角區域","(C) Zollinger-Ellison syndrome是由gastrinoma所引起，主要症狀為abdominal pain, peptic ulcer disease和severe esophagitis","(D) 90%的insulinoma是sporadic，而10% 的insulinoma與multiple endocrine neoplasia type I（MEN I）syndrome相關"],"answer":1,"image":""},{"id":"md5-112-1-35","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"有關小腸瘻管（intestinal fistula）的敘述，下列何者正確？","options":["(A) 大部分的腸皮膚瘻管（enterocutaneous fistula）是因為醫療過程造成的，且通常在術後2個星期發生","(B) 影響自發性閉合的因素有營養不良、癌症、瘻管遠端阻塞、瘻管管道過長（＞2 cm）、滲出量過高、瘻管管道上皮化等","(C) 奧曲肽（octreotide）對於滲出量過高的小腸瘻管有輔助作用，可以減少住院時間、瘻管閉合時間以及瘻管閉合率","(D) 大部分外科醫師在考慮瘻管手術前先採保守治療2～3個月，因大部分可自發性閉合的瘻管在5個星期內會閉合，且先保守治療之後手術的成功率較高，併發症較少"],"answer":3,"image":""},{"id":"md5-112-1-36","subject":"md5","topic":"消化器外科","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"有關膽道惡性腫瘤的敘述，下列何者最恰當？","options":["(A) 膽囊癌主要發生在男性且絕大部分都有膽結石","(B) 膽囊癌若沒有穿透肌肉層（T1），除了單純膽囊切除外，最好也要清除淋巴結","(C) 遠端膽管癌預後平均比肝門膽管癌（Klatskin tumor）差","(D) 膽管癌儘管手術進步也變得積極，但預後仍不佳"],"answer":3,"image":""},{"id":"md5-112-1-37","subject":"md5","topic":"消化器外科","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"蔡先生50歲，二十幾年前曾因胃潰瘍穿孔接受部分胃切除及胃空腸吻合手術（Billroth II），昨日午餐後上腹痛約3小時後吐出約500 mL苦苦的液體腹痛隨即改善，晚餐時再次感到腹部悶痛但沒有嘔吐，夜裡因腹痛加劇至急診室就醫，血液檢查發現血中澱粉酶上升，下列何者為最可能的診斷？","options":["(A) 胃潰瘍穿孔（perforated gastric ulcer）","(B) 傾倒症候群（dumping syndrome）","(C) 輸入環症候群（afferent loop syndrome）","(D) 急性闌尾炎（acute appendicitis）"],"answer":2,"image":""},{"id":"md5-112-1-38","subject":"md5","topic":"消化器外科","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"胃部的各種細胞中，下列何者粒線體（mitochondria）含量最高？","options":["(A) chief cell","(B) parietal cell","(C) argentaffin cell","(D) mucous cell"],"answer":1,"image":""},{"id":"md5-112-1-39","subject":"md5","topic":"消化器外科","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"一位45歲女性，因頻繁盜汗與昏厥被診斷懷疑有insulinoma，下列敘述何者較不適當？","options":["(A) 抽血可發現insulin升高，但C-peptide極低","(B) 儘管症狀明顯，insulinoma平均腫瘤大小一般小於2公分","(C) 合併multiple endocrine neoplasia type 1的insulinoma有較高的惡性機會","(D) 無法切除的轉移進展性insulinoma，可考慮everolimus治療"],"answer":0,"image":""},{"id":"md5-112-1-40","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"一位30歲男性，被診斷出罹患3公分大小的甲狀腺乳突癌（papillary thyroid cancer），合併level IV淋巴腺轉移及肺部轉移，根據目前TNM分期第八版，此位男性之癌症分期應屬第幾期？","options":["(A) stage I","(B) stage II","(C) stage III","(D) stage IV"],"answer":1,"image":""},{"id":"md5-112-1-41","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"一位64歲女性病患有二十年高血壓病史，定期服用calcium channel blocker及ACE inhibitor，最近血壓164/96 ++ mmHg，urine VMA 4.2 mg/24 hours，Na 135 mEq/L，K 2.2 mEq/L，BUN 14 mg/dL，creatinine 0.8 mg/dL，經停藥4週，給與三天高鹽飲食，血清aldosterone 32.2 ng/dL及plasma renin activity 0.20 ng/mL/hour，電腦斷層3掃描結果發現右腎上腺有一個1.5×1.2×1.0 cm腫塊，左腎上腺無明顯腫瘤。下列相關之敘述何者最不適當？","options":["(A) 安排經腹腔進行腹腔鏡右腎上腺切除術","(B) 安排經後腹腔進行腹腔鏡右腎上腺切除術","(C) 若病患手術後血壓仍高可使用spironolactone控制血壓","(D) 術後百分之九十血壓恢復正常，不需再服用任何高血壓藥物"],"answer":3,"image":""},{"id":"md5-112-1-42","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"如圖mammogram所示，下列敘述何者錯誤？","options":["(A) 圖(a)是coarse calcification，診斷BI-RADS category 2","(B) 圖(b)看到linear microcalcifications，診斷是BI-RADS category 4","(C) 圖(a)在超音波若看不到，即可不必安排mammography-guided biopsy","(D) 圖(b)在超音波若看不到，即可不必安排mammography-guided biopsy"],"answer":3,"image":"md5-112-1-42.jpeg"},{"id":"md5-112-1-43","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"有關乳癌的axillary lymph node staging，下列敘述何者錯誤？","options":["(A) 手術後確認診斷ductal carcinoma in situ（DCIS），不需sentinel lymph node biopsy（SLNB）","(B) 術前診斷ductal carcinoma in situ（DCIS）預計全乳房切除，不應做sentinel lymph node biopsy（SLNB）","(C) invasive cancer預計做乳房保留手術併術後放射線治療和化學治療，若有2顆metastatic sentinel nodes，可以不必做axillary lymph node dissection（ALND）","(D) invasive carcinoma做乳房全切除，發現1顆metastatic sentinel lymph node，應做axillary lymph node dissection（ALND）"],"answer":1,"image":""},{"id":"md5-112-1-44","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"小美被診斷出三陰性乳癌第二期，手術後醫師建議她接受化學藥物治療，其中包含小紅莓類（anthracycline）及紫杉醇類（taxane）藥物。關於這些藥物的副作用描述，下列何者最恰當？","options":["(A) 紫杉醇類（taxane）藥物具心毒性，使用前應安排檢查評估心臟功能","(B) 使用小紅莓類（anthracycline）藥物可能造成白血球低下，平均白血球在使用此化療後的第10～14天降至最低，之後逐漸回升","(C) 小美在化療期間抱怨手腳刺麻泛紅及下肢水腫，這些副作用較有可能是小紅莓所造成","(D) 3若小美接受紫杉醇後第10天測得嗜中性白血球（absolute neutrophil count, ANC）降至900/mm，即使無症狀仍建議施打白血球生長素（granulocyte colony stimulating factor, G-CSF）"],"answer":1,"image":""},{"id":"md5-112-1-45","subject":"md5","topic":"小兒外科","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"有關隱睪症（cryptorchidism），下列敘述何者正確？","options":["(A) 直接觸診陰囊，沒有發現睪丸，即確診為隱睪症","(B) 兩歲後未矯正的隱睪側睪丸，精子生成即受損","(C) 隱睪側睪丸手術固定後，病患生育力即可恢復正常","(D) 睪丸手術固定即可降低患側睪丸癌風險"],"answer":1,"image":""},{"id":"md5-112-1-46","subject":"md5","topic":"消化器外科","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"傳統及腹腔鏡鼠蹊疝氣術後短期之併發症最常見的為：","options":["(A) 疼痛","(B) 泌尿道感染或睪丸炎","(C) 傷口感染","(D) 復發"],"answer":0,"image":""},{"id":"md5-112-1-47","subject":"md5","topic":"小兒外科","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"一新生女嬰出生即發現尾骶部一突出且破裂之腫瘤（如圖所示），下列敘述何者錯誤？","options":["(A) 腫瘤較大時可能會將肛門或會陰往前擠壓變形，部分病人會合併肛門直腸異常","(B) 產前可能之併發症有polyhydraminos、urinary obstruction、fetal hydrops等","(C) 產前可由超音波診斷，一般在懷孕週數30週之前或出生後2個月後診斷者預後較佳","(D) 標準治療方法為手術切除"],"answer":2,"image":"md5-112-1-47.jpeg"},{"id":"md5-112-1-48","subject":"md5","topic":"小兒外科","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"原本無異狀的10天大男嬰突然出現膽汁性嘔吐，影像學檢查如圖所示，最有可能的診斷是：","options":["(A) 中腸旋轉不全合併扭轉（malrotation and midgut volvulus）","(B) 十二指腸閉鎖（duodenal atresia）","(C) 肥厚性幽門狹窄（hypertrophic pyloric stenosis）","(D) 上腸繫膜動脈徵候群（superior mesenteric artery syndrome）"],"answer":0,"image":"md5-112-1-48.jpeg"},{"id":"md5-112-1-49","subject":"md5","topic":"小兒外科","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"承上題，下列何項檢查對確定診斷最不恰當？","options":["(A) 超音波（ultrasound examination）","(B) 上消化道攝影（upper GI contrast series）","(C) 鋇劑灌腸（barium enema）","(D) 血管攝影（angiography）"],"answer":3,"image":""},{"id":"md5-112-1-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"關於發炎性腸道疾病（inflammatory bowel disease），下列敘述何者錯誤？","options":["(A) 潰瘍性的結腸炎（ulcerative colitis）如藥物治療效果不佳可安排手術治療","(B) 潰瘍性的結腸炎（ulcerative colitis）手術包括全結腸直腸切除併迴腸造口手術（total proctocolectomy with ileostomy）","(C) 克隆氏症（Crohn's disease）的治療以切除發炎部分腸段為主","(D) 克隆氏症（Crohn's disease）引起之腸皮瘻管（enterocutaneous fistula）可以接受手術治療"],"answer":2,"image":""},{"id":"md5-112-1-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"112年第1次第51題","year":112,"session":1,"number":51,"question":"43歲乙狀結腸癌病患，接受乙狀結腸切除手術後第五天，從引流管流出白色液體，最可能的原因為何？","options":["(A) 腸吻合處滲漏","(B) 手術中造成輸尿管受傷","(C) 乳糜液外滲","(D) 手術中殘留血塊，形成膿瘍"],"answer":2,"image":""},{"id":"md5-112-1-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"112年第1次第52題","year":112,"session":1,"number":52,"question":"肛管（anal canal）的感覺（sensory）神經支配源自於下列何者？","options":["(A) obturator nerve","(B) femoral nerve","(C) pudendal nerve","(D) sciatic nerve"],"answer":2,"image":""},{"id":"md5-112-1-53","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"112年第1次第53題","year":112,"session":1,"number":53,"question":"外科手術面對懷孕的患者承受複雜的臨床挑戰。在美國，每年估計有1%～2%的孕婦需要進行必須的外科手術，下列何者為正確觀念？①腹腔鏡輔助的手術方式，目前已不再被視為孕婦手術的禁忌症 ②腹腔鏡手術的大多數適應症是與妊娠無關的常見疾病，例如急性闌尾炎、有症狀的膽石症或外傷 ③懷孕期間進行腹腔鏡檢查的主要風險包括子宮損傷、子宮血流減少、胎兒酸中毒以及腹腔內壓力升高引起的早產 ④腹腔鏡手術相對於傳統剖腹手術在妊娠中的優點是減少子宮損傷和移動 ⑤腹腔鏡手術相對於傳統剖腹手術，傷口感染和切口疝氣（incisional hernia）的發生率更低","options":["(A) 僅①③⑤","(B) 僅①②④","(C) 僅②③④⑤","(D) ①②③④⑤"],"answer":3,"image":""},{"id":"md5-112-1-54","subject":"md5","topic":"消化器外科","meta":"112年第1次第54題","year":112,"session":1,"number":54,"question":"微創手術（minimally invasive surgery）已可用於脾臟切除手術，下列敘述何者錯誤？","options":["(A) 腹腔鏡脾切除手術是切除脾臟的首選方法，其手術安全性和傳統開腹脾切除手術並無差別","(B) 大約90%的患者可以完成腹腔鏡脾切除手術，腹腔鏡脾切除手術失敗轉換成開腹脾切除手術主要原因是由於術中出血、缺乏手術經驗、沾黏、巨大的脾腫大和肥胖","(C) 腹腔鏡脾切除手術不需要考慮門靜脈高壓的問題","(D) 腹腔鏡脾切除手術可以在患者處於仰臥或側臥的情況下進行"],"answer":2,"image":""},{"id":"md5-112-1-55","subject":"md5","topic":"消化器外科","meta":"112年第1次第55題","year":112,"session":1,"number":55,"question":"下列有關腹腔鏡手術的敘述，何者錯誤？","options":["(A) 氣血栓（air emboli）在腹腔鏡手術中極為罕見","(B) 在腹腔鏡手術中，使用撐開器（lift device）對於手術視野的呈現（exposure）及可運作空間上比氣腹（pneumoperitoneum）要更佳","(C) 在腹腔鏡手術下的免疫抑制反應（immune suppression）比傳統手術較少","(D) 在腹腔鏡手術下的皮質素（cortisol）濃度比傳統手術較高"],"answer":1,"image":""},{"id":"md5-112-1-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第1次第56題","year":112,"session":1,"number":56,"question":"下列關於良性骨腫瘤的敘述，何者最適當？","options":["(A) 軟骨母細胞瘤（chondroblastoma）為最常見的良性骨腫瘤","(B) multiple enchondromatosis又稱為Maffucci syndrome","(C) chondromyxoid fibroma常見於脛骨近端骨骺（epiphysis）","(D) multiple exostosis可能是自體顯性遺傳疾病"],"answer":3,"image":""},{"id":"md5-112-1-57","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第1次第57題","year":112,"session":1,"number":57,"question":"下列關於椎齒突骨折（odontoid fracture）的敘述，何者最不適當？","options":["(A) 軸向切面的電腦斷層（CT scan with axial sectioning）可能會忽略水平方向的骨折線（horizontal fracture line）","(B) Anderson and D'Alonzo分類中，第一型為最常見，指的是椎齒突的基底（base）骨折","(C) Anderson and D'Alonzo分類中，第二型骨折有高不癒合率（nonunion rate），尤其是在顯著位移或患者年紀較大時","(D) Anderson and D'Alonzo分類中，第三型骨折血循較佳，癒合率較高，處理以保守治療為主"],"answer":1,"image":""},{"id":"md5-112-1-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第1次第58題","year":112,"session":1,"number":58,"question":"有關前臂腔室症候群（compartment syndrome）之敘述，下列何者最不適當？","options":["(A) 腔室症候群引發Volkmann ischemic contracture時，患部遠端的intrinsic muscle不可能有正常的功能","(B) 做被動式伸展動作時會疼痛，為腔室症候群最為敏感的身體診察（physical examination）","(C) 神經缺血通常會導致感覺異常","(D) 即使周邊脈搏還存在，仍無法排除其可能性"],"answer":0,"image":""},{"id":"md5-112-1-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"112年第1次第59題","year":112,"session":1,"number":59,"question":"職業籃球選手於比賽中上籃投球後跌坐在地上，被診斷出髕骨肌腱斷裂（patellar tendon rupture），下列敘述何者最不適當？","options":["(A) 通常發生的年齡小於40歲","(B) 病人無法主動將膝蓋伸直","(C) 膝蓋骨的位置會比正常來得更低位（patella baja）","(D) 肌腱斷端修補後應該利用鐵絲將髕骨與脛骨作固定"],"answer":2,"image":""},{"id":"md5-112-1-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第1次第60題","year":112,"session":1,"number":60,"question":"一位7歲小朋友被發現單側股骨頭缺血性壞死，估計至成年時長短腳可能達到1.5～3.5公分，下列治療方式何者最適當？","options":["(A) 可在短肢穿著墊高的鞋子（shoe lift）","(B) 可在長肢進行生長板抑制手術（epiphysiodesis）","(C) 可在長肢進行股骨縮短手術（femoral shortening）","(D) 可在短肢進行骨延長術（bone lengthening）"],"answer":0,"image":""},{"id":"md5-112-1-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第1次第61題","year":112,"session":1,"number":61,"question":"成人扳機指（trigger finger）是那一滑車（pulley）發生狹窄性腱鞘炎（stenosing tenosynovitis）？","options":["(A) A1","(B) C2","(C) A2","(D) C1"],"answer":0,"image":""},{"id":"md5-112-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第1次第62題","year":112,"session":1,"number":62,"question":"有關椎間盤退化疾病（degenerative disc disease），下列敘述何者最不適當？","options":["(A) 大部分椎間盤退化會引起背痛，可用磁振造影來判讀疼痛的椎間盤","(B) 椎間盤退化會使椎間盤脫水、高度降低，並且會改變它的機械特性（mechanical properties）","(C) 椎間盤退化造成的背痛會因身體屈曲（flexion）而加劇，且因坐姿會造成椎間盤內壓力增加而加重疼痛，且疼痛可能會輻射至臀部、大腿或腹股溝","(D) 椎間盤退化疾病的治療效果較其他脊椎病變的治療效果為差，若須手術治療，常合併脊椎融合術（spinal fusion）"],"answer":0,"image":""},{"id":"md5-112-1-63","subject":"md5","topic":"骨科-關節重建","meta":"112年第1次第63題","year":112,"session":1,"number":63,"question":"有關人工關節的材質，下列敘述何者最不適當？","options":["(A) 鋯合金（zirconium alloy）可被用做人工關節的材料","(B) 超高分子量聚乙烯（ultrahigh-molecular-weight polyethylene）是常見的人工關節介面","(C) 鈦合金（titanium alloy）很適合做為人工髖關節股骨頭的材料","(D) 鈷鉻鉬合金（cobalt chromium alloy）可以用來做為人工關節的磨耗介面"],"answer":2,"image":""},{"id":"md5-112-1-64","subject":"md5","topic":"泌尿-結石與感染","meta":"112年第1次第64題","year":112,"session":1,"number":64,"question":"下列有關尿路結石的敘述，何者錯誤？","options":["(A) 檸檬酸（citrate）是結石形成的抑制劑","(B) 磷酸銨鎂（struvite）結石如不處理可能造成腎臟功能喪失","(C) Randall's plaque與胱氨酸（cystine）結石形成有關","(D) 尿酸結石病人的尿液偏酸"],"answer":2,"image":""},{"id":"md5-112-1-65","subject":"md5","topic":"泌尿-腫瘤","meta":"112年第1次第65題","year":112,"session":1,"number":65,"question":"一位70歲男性，因頻尿及憋不住尿有半年之久，檢查發現有顯微性血尿，靜脈尿路攝影（IVU）正常，膀胱鏡檢查發現膀胱後壁有一紅色扁平病灶，經尿道膀胱腫瘤切除（TURBT）後，病理報告為泌尿上皮原位癌（carcinoma in situ），下列何者是最適當的治療？","options":["(A) 膀胱灌注卡介苗（BCG）","(B) 再次施行經尿道膀胱腫瘤切除（TURBT）","(C) 膀胱根除手術","(D) 給與新輔助全身性化學治療（gemcitabine及cisplatin）"],"answer":0,"image":""},{"id":"md5-112-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"112年第1次第66題","year":112,"session":1,"number":66,"question":"下列有關陰莖癌的敘述，何者錯誤？","options":["(A) 基底細胞癌（basal cell carcinoma）是最常見的腫瘤","(B) 與人類乳突狀病毒（HPV）有關","(C) Queyrat紅斑病（erythroplasia of Queyrat）是陰莖原位癌（carcinoma in situ）","(D) 初期傳播常沿著腹股溝及骨盆腔淋巴轉移"],"answer":0,"image":""},{"id":"md5-112-1-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"112年第1次第67題","year":112,"session":1,"number":67,"question":"下列有關良性前列腺增生（benign prostatic hyperplasia）的檢查，何者最不恰當？","options":["(A) 肛門指診測量出的前列腺大小與下泌尿道症狀的嚴重程度成正相關","(B) 肛門指診如果檢測到前列腺硬塊，則有癌症的可能性，應該做進一步評估","(C) 以肛門指診檢測前列腺癌的敏感度（sensitivity）不高，約只有40～50%","(D) 肛門指診常會低估前列腺的大小"],"answer":0,"image":""},{"id":"md5-112-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"112年第1次第68題","year":112,"session":1,"number":68,"question":"一位60歲男性3個月前中風，主訴頻尿、急尿、憋不住尿，引起下泌尿道症候最可能的機轉是：","options":["(A) 源自膀胱本身因素導致無法儲存尿液","(B) 源自膀胱出口因素導致無法儲存尿液","(C) 源自膀胱本身因素導致無法排空尿液","(D) 源自膀胱出口因素導致無法排空尿液"],"answer":0,"image":""},{"id":"md5-112-1-69","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"112年第1次第69題","year":112,"session":1,"number":69,"question":"一位30歲男性因早洩（premature ejaculation）求診，身體診察發現兩側睪丸發育正常，抽血檢驗生殖相關荷爾蒙都在正常範圍。醫師處方口服藥物dapoxetine，服用後射精時間延長。關於這種藥物，下列敘述何者正確？","options":["(A) 會增加腦中dopamine的濃度","(B) 會增加腦中serotonin的濃度","(C) 會增加腦中testosterone的濃度","(D) 會減少周邊神經突觸acetylcholine的分泌"],"answer":1,"image":""},{"id":"md5-112-1-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"112年第1次第70題","year":112,"session":1,"number":70,"question":"腎臟移植前是否給與接受者（recipient）抗體誘導療法（antibody induction therapy），通常需檢視接受者是否有確定的免疫危險因素（immunologic risk factors）。下列何者不是腎臟移植前用來評估接受者的免疫危險因素？","options":["(A) 患有全身性紅斑狼瘡","(B) ABO血型不相容","(C) 嗜伊紅白血球（eosinophil）過高","(D) 先前輸血導致的人類白血球抗原（human leukocyte antigen, HLA）抗體升高"],"answer":2,"image":""},{"id":"md5-112-1-71","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"112年第1次第71題","year":112,"session":1,"number":71,"question":"腎移植受贈者在移植手術前，下列何種情況不需將原本腎臟切除（native nephrectomy）？","options":["(A) 腎腫瘤","(B) 有症狀的多囊腎（polycystic kidneys）","(C) 因腎結石導致反覆腎盂腎炎（recurrent pyelonephritis）","(D) 高血壓但可以藥物控制"],"answer":3,"image":""},{"id":"md5-112-1-72","subject":"md5","topic":"消化器外科","meta":"112年第1次第72題","year":112,"session":1,"number":72,"question":"關於急性胰臟炎之晚期併發症（late complication），下列何者最少見？","options":["(A) 胰管阻塞（pancreatic duct obstruction）","(B) 後腹腔膿瘍（retroperitoneal abscess）","(C) 肝動脈假性動脈瘤（hepatic artery pseudoaneurysm）","(D) 假性囊腫形成（pseudocyst formation）"],"answer":2,"image":""},{"id":"md5-112-1-73","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"112年第1次第73題","year":112,"session":1,"number":73,"question":"20歲男性病人因車禍左髖關節腫痛。圖為本次就診之左髖關節X光攝影及電腦斷層影像。最可能的診斷為何？","options":["(A) anterior hip fracture-dislocation","(B) posterior hip fracture-dislocation","(C) heterotopic ossification following dislocation","(D) avascular necrosis of femoral head"],"answer":1,"image":"md5-112-1-73.jpeg"},{"id":"md5-112-1-74","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第1次第74題","year":112,"session":1,"number":74,"question":"一名成年男性病人車禍後主訴下腹部疼痛和血尿，逆行性膀胱攝影檢查呈現如附圖。下列有關膀胱的初診斷何者最恰當？","options":["(A) ureter rupture","(B) intraperitoneal rupture of the urinary bladder","(C) pseudodiverticulum of the urinary bladder","(D) prostate gland hypertrophy"],"answer":1,"image":"md5-112-1-74.jpeg"},{"id":"md5-112-1-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第1次第75題","year":112,"session":1,"number":75,"question":"關於動物咬傷與第一線抗生素治療的配對，下列敘述何者最不適當？","options":["(A) 貓咬傷：amoxicillin-clavulanate","(B) 猴子咬傷：fluoroquinolone","(C) 海水魚咬傷：fluoroquinolone","(D) 狗咬傷：amoxicillin-clavulanate"],"answer":1,"image":""},{"id":"md5-112-1-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第1次第76題","year":112,"session":1,"number":76,"question":"40歲行人被汽車撞擊後送到急診，檢查發現脾臟破裂、腹內出血，心跳130/min，呼吸20/min，血壓80/46 mmHg，Base deficit -8mEq/L，下列敘述何者錯誤？","options":["(A) 病人至少是第三級出血","(B) 若需啟動大量輸血，建議的比例為紅血球：血漿：血小板＝1：1：1","(C) 若需緊急輸packed RBC，可選用O型紅血球","(D) 若需緊急輸FFP，可選用O型血漿"],"answer":3,"image":""},{"id":"md5-112-1-77","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"112年第1次第77題","year":112,"session":1,"number":77,"question":"一位51歲男性，大腸腫瘤病人術後食慾不佳，造成電解質不平衡，下列那一種電解質不平衡最容易造成腸阻塞（ileus）？","options":["(A) 高血鈣","(B) 低血鉀","(C) 高血鉀","(D) 低血鈣"],"answer":1,"image":""},{"id":"md5-112-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"112年第1次第78題","year":112,"session":1,"number":78,"question":"湯醫師受到藥廠邀請，到宜蘭礁溪參加一場學術研討會並擔任講師。為避免利益衝突，依據衛生福利部95年9月8日所公告的「醫師與廠商間關係」守則，下列敘述何者正確？①學術時間應達總時間的三分之二以上 ② 擔任講師的湯醫師可收取適當的演講費 ③湯醫師在會議中所發表的資料應符合科學實證原則，並應平衡論述 ④參與會議的其他醫師，若接受藥廠餽贈，不可收受金錢，但可收受禮券","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":0,"image":""},{"id":"md5-112-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"112年第1次第79題","year":112,"session":1,"number":79,"question":"吳先生今年82歲，太太及其子女均已過世，目前與長孫同住。日前因咳血不適入院檢查，診斷為早期肺癌。臨床醫師和長孫討論病情後，考慮到手術後可能的併發症，不建議吳先生進行手術。因此在跟吳生生解釋病情時，臨床醫師強調手術後的疼痛及嚴重之併發症，再加上長孫在旁的說明，使得吳先生決定不手術而接受化學治療。在這個說明病情的過程中，吳先生的醫療決策主要受到下列何種因素之影響？","options":["(A) 心理脅迫（coercion）","(B) 不正當之操控（manipulation）","(C) 外力約束（force）","(D) 內在因素的妥協（compromise）"],"answer":1,"image":""},{"id":"md5-112-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"112年第1次第80題","year":112,"session":1,"number":80,"question":"當醫院僅剩下一台呼吸器可用的情況下，有兩位患者同時有需要使用這台呼吸器，一位是20歲的男性患者，因為車禍受重傷而被送進醫院；另外一位是89歲的老太太，已經長期中風臥床許久，這次是因為肺炎合併呼吸衰竭而住院。下列關於醫療資源分配的相關敘述，何者最適當？","options":["(A) 抽籤決定誰有權利使用呼吸器","(B) 依據申請呼吸器的順序","(C) 評估其使用呼吸器後之預後情況","(D) 醫師可自由決定優先順序"],"answer":2,"image":""},{"id":"md5-112-2-1","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"一位生命跡象不穩定的出血外傷病人到達急診室時，若決定啟動大量輸血的流程（massive transfusion protocol），有關各種血品的使用單位比例以下列何者有最好的臨床結果？","options":["(A) 血漿：血小板：紅血球為1單位：1單位：4單位","(B) 血漿：血小板：紅血球為1單位：1單位：3單位","(C) 血漿：血小板：紅血球為1單位：1單位：2單位","(D) 血漿：血小板：紅血球為1單位：1單位：1單位"],"answer":[2,3],"image":"","answer_note":"更正:第1題答Ｃ或Ｄ者均給分"},{"id":"md5-112-2-2","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"肺水腫為手術後的肺部併發症之一，下列何種狀況較不容易造成肺水腫？","options":["(A) 胰臟炎","(B) 體液容積過量","(C) 急性左心衰竭","(D) 高血壓"],"answer":3,"image":""},{"id":"md5-112-2-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"困難梭狀芽孢桿菌感染症（Clostridioides difficile infection）是抗生素相關性腹瀉常見的原因，與腹部手術後之恢復過程息息相關，下列敘述何者錯誤？","options":["(A) 症狀會出現水瀉、血便、發燒","(B) 診斷可從糞便的困難梭狀桿菌毒素試驗檢出陽性或是藉由大腸鏡進行切片檢查","(C) 治療需停止目前使用之抗生素，並使用廣效性抗革蘭氏陰性菌抗生素","(D) 腹瀉會導致電解質及水分的不平衡，需補充水分及電解質"],"answer":2,"image":""},{"id":"md5-112-2-4","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"造成傷口癒合延遲的最常見原因為：","options":["(A) 傷口感染","(B) 縫合技巧不佳","(C) 傷口流血","(D) 病人本身之合併症"],"answer":0,"image":""},{"id":"md5-112-2-5","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"下列何種狀況，不符合「手術部位感染（surgical site infection）」之定義？","options":["(A) 77歲女性，消化性潰瘍穿孔術後，因呼吸衰竭持續使用呼吸器，於術後第21天發生肺炎與敗血症","(B) 45歲男性，長期肝硬化與糖尿病，於接受未置入人工網膜之疝氣修補手術28天後，癒合不良產生分泌物與膿瘍","(C) 69歲男性，接受膝關節置換手術11個月後，傷口出現紅腫，皮下穿刺之組織液細菌培養呈現陽性反應","(D) 82歲女性，接受經腹腔鏡部分胃切除手術，腹部傷口正常，然而於術後第6天出現劇烈腹痛與發燒，電腦斷層發現腸胃道吻合處有膿瘍形成"],"answer":0,"image":""},{"id":"md5-112-2-6","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"臨床上用以評估肝臟疾病的嚴重程度時會使用所謂的「末期肝臟疾病模型」分數（Model for End-Stage Liver Disease score, MELD score）來評分肝臟移植優先順位。下列何者不是計算MELD score的重要參數？","options":["(A) 血清總膽紅素（total bilirubin）","(B) 白血球計數（white blood cell count）","(C) 血清肌酐酸（creatinine）","(D) 凝血酶原時間國際標準化比值（international normalized ratio, INR）"],"answer":1,"image":""},{"id":"md5-112-2-7","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"對於燒傷病人的淨體重損失（loss of lean body mass）相關合併症的發生，下列敘述何者最恰當？","options":["(A) 淨體重損失10%，增加延緩傷口癒合機率","(B) 淨體重損失20%，會開始增加降低免疫機能（immune dysfunction）的風險","(C) 淨體重損失30%，會開始增加肺炎及壓瘡（pressure sore）的風險","(D) 淨體重損失40%，會開始增加脆弱性骨折的風險"],"answer":2,"image":""},{"id":"md5-112-2-8","subject":"md5","topic":"神經外科","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"有關腦下垂體（pituitary）腫瘤治療，下列何者不是以手術切除為第一優先？","options":["(A) 促腎上腺皮質素瘤（ACTH secreting tumor）","(B) 生長激素瘤（growth homone secreting tumor）","(C) 甲狀腺刺激素瘤（TSH secreting tumor）","(D) 泌乳激素瘤（prolactinoma）"],"answer":3,"image":""},{"id":"md5-112-2-9","subject":"md5","topic":"神經外科","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"有關出血性腦中風後之照護，下列何者錯誤？","options":["(A) 血糖控制小於180 mg/dL","(B) 血壓控制，收縮壓小於140～160 mmHg","(C) 注意壓瘡","(D) 一定要投與預防癲癇用藥"],"answer":3,"image":""},{"id":"md5-112-2-10","subject":"md5","topic":"神經外科","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"有關附圖之電腦斷層血管攝影影像，下列敘述何者正確？","options":["(A) 建議服用抗血小板藥物，防止血栓產生進一步造成腦血管梗塞","(B) 此為顱內動脈瘤好發的位置之一","(C) 此影像顯示為中大腦動脈動脈瘤","(D) 影像中可以看出此動脈瘤已破裂"],"answer":1,"image":"md5-112-2-10.jpeg"},{"id":"md5-112-2-11","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"下列關於急性腰椎椎間盤突出疾病的敘述，何者最不適當？","options":["(A) 大部分腰椎椎間盤突出發生在L4-5和L5-S1 level，少部分在L3-4 level","(B) 主要病因爲長期腰椎損傷，如前傾彎腰和負重物等","(C) 主要症狀為下背痛和急性下肢神經病變，以下肢神經根疼痛為主要症狀","(D) 如數日後疼痛緩解，下肢麻木感取代部分疼痛，則表示神經根病變有緩解"],"answer":3,"image":""},{"id":"md5-112-2-12","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"A three-column model被用來作為胸腰椎骨折嚴重度的分類。下列選項關於middle column的組成，何者正確？","options":["(A) 椎體全部，後縱走韌帶","(B) 後半部椎體，後縱走韌帶","(C) 後半部椎體，後縱走韌帶，椎莖","(D) 後縱走韌帶，椎莖，椎關節"],"answer":1,"image":""},{"id":"md5-112-2-13","subject":"md5","topic":"神經外科","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"有關第二級腦震盪的敘述，下列何者錯誤？","options":["(A) 頭部外傷後失去意識一段時間，即屬於第二級腦震盪","(B) 受傷後1～2週容易再度受傷，應避免劇烈撞擊型運動","(C) 這類病人容易有失憶症狀","(D) 受傷後1～2週容易有記憶障礙或頭痛症狀"],"answer":0,"image":""},{"id":"md5-112-2-14","subject":"md5","topic":"整形重建外科","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"有關血管腫瘤和血管畸形，下列何者錯誤？①有一半比例的血管瘤（hemangioma）在一歲前會完全消失 ② 硬化劑注射（sclerotherapy）是治療動靜脈畸形（arteriovenous malformation）的最好方法 ③血管腫瘤（vascular tumors）是因為內皮細胞異常增生，血管畸形（vascular malformations）是動靜脈或淋巴系統異常發展 ④微血管畸形與動靜脈畸形不同，會隨著年紀增長而萎縮變小，甚至消失","options":["(A) 僅①③","(B) ②③","(C) ①②④","(D) ①③④"],"answer":2,"image":""},{"id":"md5-112-2-15","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"球狀血管瘤（glomus tumor）最常見於下列那個位置？","options":["(A) 髖關節","(B) 手肘","(C) 手指","(D) 頭頸部"],"answer":2,"image":""},{"id":"md5-112-2-16","subject":"md5","topic":"整形重建外科","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"根據Mathes-Nahai classification，下列各種肌肉皮瓣及其所屬類型配對，何者錯誤？","options":["(A) type I：比目魚肌（gastrocnemius）","(B) type II：股薄肌（gracilis）","(C) type III：胸大肌（pectoralis major）","(D) type IV：縫匠肌（sartorius）"],"answer":[0,2],"image":"","answer_note":"更正:第16題答Ａ或Ｃ者均給分"},{"id":"md5-112-2-17","subject":"md5","topic":"整形重建外科","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"拉皮手術後合併使用輔助性去除臉上細紋最適合用下列何種消融式雷射（ablative laser）？","options":["(A) 銣雅鉻雷射（Nd:YAG laser）","(B) 脈衝式染料雷射（pulsed dye laser）","(C) 分段式二氧化碳雷射（fractional CO2 laser）","(D) 紅寶石雷射（ruby laser）"],"answer":2,"image":""},{"id":"md5-112-2-18","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"關於男性女乳症（gynecomastia），下列敘述何者錯誤？","options":["(A) 藥物的作用可能導致男性女乳症的發生，如spironolactone等","(B) 一般而言，男性女乳症是一種良性的男性乳房組織增生，與罹患乳癌風險較無關聯","(C) 生理性男性女乳症在新生兒期（neonatal period）、青春期（adolescence）及晚年期（senescence）皆可發生","(D) 男性女乳症會發現在Klinefelter's syndrome的病患，且與罹患乳癌風險較無關聯"],"answer":3,"image":""},{"id":"md5-112-2-19","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"王同學和同學在KTV歡唱，突然電線走火引起火災。包廂內沙發地毯燃燒，煙霧瀰漫。王同學逃出現場後被送往醫院，發現面部燻黑，有水泡，雙上肢及下肢燒傷。此時如果你是值班外科醫師處理王同學，下列何項錯誤？","options":["(A) 懷疑有吸入性灼傷應照胸部X光，無法確認時再做胸部電腦斷層（CT scan）","(B) 嚴重燒傷（severe burn），主要死因之一為吸入性灼傷","(C) 上呼吸道有水腫時，即使病人意識清楚，仍要考慮插管治療的必要性","(D) 不建議使用預防性抗生素，除非肺部出現感染現象"],"answer":0,"image":""},{"id":"md5-112-2-20","subject":"md5","topic":"心臟血管外科","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"主動脈剝離是一項廣為人知的急症，關於其敘述下列何者錯誤？","options":["(A) 當剝離範圍包含主動脈根部（aortic root）時，可能造成急性主動脈瓣閉鎖不全","(B) 主動脈剝離依照Stanford的分類，是以intima tear的位置分為type A及type B，type A是指破口位於升主動脈（ascending aorta），type B則是破口位於降主動脈","(C) acute type A aortic dissection須接受緊急開胸手術修補，最主要是為了防止急性升主動脈破裂","(D) acute type B aortic dissection若無合併灌流不足症候群，可先使用藥物控制血壓"],"answer":1,"image":""},{"id":"md5-112-2-21","subject":"md5","topic":"心臟血管外科","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"有關血管腔内治療腹主動脈瘤（endovascular treatment of abdominal aortic aneurysm）發生滲漏（endoleak）的敘述，下列何者錯誤？","options":["(A) 第一型發生在支架血管近端的接觸區","(B) 第二型發生在暢通的腰動脈或是下腸繫膜動脈回流造成","(C) 第三型發生在支架血管遠端的接觸區","(D) 第四型因為支架血管的織物孔洞而造成"],"answer":2,"image":""},{"id":"md5-112-2-22","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"65歲男子，以血管重建術治療急性下肢缺血2小時後，下肢發生劇烈疼痛。檢查發現小腿肌肉緊繃，且被動彎曲時產生劇烈疼痛；足部無脈搏，但有杜卜勒訊號（positive ultrasound signal）。關於此病人，下列何種情形最不可能發生？","options":["(A) 高血鉀","(B) 高血鈣","(C) 肌酸磷酸激酶濃度上升","(D) 肌紅蛋白尿（myoglobinuria）"],"answer":1,"image":""},{"id":"md5-112-2-23","subject":"md5","topic":"心臟血管外科","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"有關心房中隔（atrial septal defect, ASD）之敘述，下列何者錯誤？","options":["(A) 在年齡大於40歲病人的心房中隔缺損，心導管檢查是高度建議的","(B) 有心房中隔缺損且固定之肺動脈阻力過高（大於12 Wood units）之病患，不可以將其缺損關閉","(C) 在有ASD with inferior sinus venosus type的病患，常併有二尖瓣逆流（mitral regurgitation）","(D) 在青春期前的女性，不適合使用右前側開胸術（anterolateral thoracotomy）來修補"],"answer":2,"image":""},{"id":"md5-112-2-24","subject":"md5","topic":"心臟血管外科","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"一個8個月大的男嬰，因主動脈瓣狹窄（aortic stenosis）診斷入院，因呼吸喘而插管，左心室到主動脈壓力差為60 mmHg，下列建議之治療方式何者最不適合？","options":["(A) 氣球擴張術（balloon valvuloplasty）","(B) 直視下主動脈瓣膜切開術（surgical valvotomy）","(C) 機械瓣膜置換術（mechanical valve replacement）","(D) 肺動脈瓣轉至主動脈之手術（Ross procedure）"],"answer":2,"image":""},{"id":"md5-112-2-25","subject":"md5","topic":"胸腔外科","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"關於食道憩室（diverticula）之敘述，下列何者錯誤？","options":["(A) 食道憩室（diverticula）有三種常見形式：咽食道憩室（Zenker diverticula）、氣管旁食道憩室及橫膈上食道憩室（epiphrenic diverticula）","(B) 咽食道憩室（Zenker diverticula）為真憩室（true diverticula），憩室含黏膜層、黏膜下層及肌肉層","(C) 咽食道憩室（Zenker diverticula）為所有食道憩室最常見","(D) 橫膈上食道憩室（epiphrenic diverticula）為壓出型憩室（pulsion diverticula），也是偽憩室（false diverticula）"],"answer":1,"image":""},{"id":"md5-112-2-26","subject":"md5","topic":"胸腔外科","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"關於肺鱗狀上皮細胞癌（squamous cell carcinoma）之敘述，下列何者正確？","options":["(A) 大多與抽菸無關","(B) 大多位在周邊（peripherally located）","(C) 較易發生中央壞死（central necrosis）及開洞化（cavitation）","(D) 與肺腺癌（adenocarcinoma）相比，較早發生轉移"],"answer":2,"image":""},{"id":"md5-112-2-27","subject":"md5","topic":"胸腔外科","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"有關肺膿瘍（lung abcess）之敘述，下列何者為錯誤？","options":["(A) 肺膿瘍破裂可能造成氣胸（pneumothorax）","(B) 為肺部局部感染，與葡萄球菌菌血症（Staphylococcus bacteremia）無關","(C) 胸部X光或胸部斷層掃描可能發現肺膿瘍（lung abcess）空腔中有氣液平面（air-fluid level）","(D) 大部分病人以抗生素治療即能痊癒"],"answer":1,"image":""},{"id":"md5-112-2-28","subject":"md5","topic":"胸腔外科","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"下列何者不是惡性肋膜積液（malignant pleural effusion）常見的成因？","options":["(A) 肺腺癌","(B) 淋巴瘤","(C) 間皮瘤（mesothelioma）","(D) 黑色素瘤"],"answer":3,"image":""},{"id":"md5-112-2-29","subject":"md5","topic":"胸腔外科","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"有關胸腔穿刺傷之外科適應症，下列何者較不適當？","options":["(A) 心包膜填塞（pericardial tamponade）","(B) 食道破裂（esophageal perforation）","(C) 胸管放置術後馬上引流出500 mL合併生命跡象回穩","(D) 氣胸合併持續漏氣及肺部塌陷或通氣不足"],"answer":2,"image":""},{"id":"md5-112-2-30","subject":"md5","topic":"消化器外科","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"有關Zollinger-Ellison syndrome的敘述，下列何者錯誤？","options":["(A) 導因於神經內分泌瘤gastrinoma異常分泌gastrin所造成","(B) 約20%的病患會合併multiple endocrine neoplasia type II（MEN II），可以藉由手術切除治癒","(C) 約80%的gastrinoma位於gastrinoma triangle，但因腫瘤通常較小而不易於手術前定位","(D) 有將近60%的gastrinoma為惡性的，且常合併淋巴結、肝臟或其他遠端轉移"],"answer":1,"image":""},{"id":"md5-112-2-31","subject":"md5","topic":"消化器外科","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"關於膽囊癌（gallbladder cancer），下列敘述何者正確？","options":["(A) 大部分的病患都是經由腹腔鏡膽囊切除偶然發現診斷的","(B) 整體膽囊癌的預後相當好，5年存活率可高達80%","(C) 膽結石是膽囊癌最重要的危險因子，近85%的膽囊癌患者伴隨有膽結石","(D) 膽囊癌侵犯深度為T2的腫瘤，因尚未穿透漿膜，術後只需追蹤即可，不必進行擴大根除手術"],"answer":2,"image":""},{"id":"md5-112-2-32","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"關於腸皮瘻管（enterocutaneous fistula），下列敘述何者正確？","options":["(A) 多肇因於惡性腫瘤的侵犯","(B) 每日腸液引流量小於500 mL為low-output fistula","(C) fistula tract＜2 cm的瘻管大多會自行關閉","(D) 超過半數（＞50%）的病患可採保守治療，使瘻管自行關閉"],"answer":3,"image":""},{"id":"md5-112-2-33","subject":"md5","topic":"消化器外科","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"關於胰臟癌（pancreatic ductal adenocarcinoma）的敘述，下列何者錯誤？","options":["(A) 遺傳性胰臟癌與PRSS1、STK11、CDKN2A及BRCA2等基因突變有關","(B) 腫瘤發生於胰臟頭部，表現症狀最多的是黃疸，若發生於胰臟體部和尾部，則以疼痛和體重減輕居多","(C) 發生於胰臟頭部的胰臟癌，約三分之一的病人出現膽囊腫大（palpable distended gallbladder），稱為Courvoisier sign","(D) 手術前施行endoscopic retrograde cholangio-pancreatography（ERCP）做膽道減壓，可減少手術後傷口感染"],"answer":3,"image":""},{"id":"md5-112-2-34","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"有關胰臟胰島素瘤（insulinoma）的敘述，下列何者正確？","options":["(A) 最常見的胰臟內分泌腫瘤，通常臨床表現包括有症狀的空腹低血糖、有記載的血清葡萄糖值＜50 mg/mL以及葡萄糖的給與可以緩解症狀，此又稱Charcot's triad","(B) 實驗室檢查除了血糖低、胰島素高外，C-peptide上升可以幫助診斷胰島素瘤而非外來胰島素或降血糖藥引起的低血糖症","(C) 與其他胰臟內分泌腫瘤不同在於其是多發性為主且大多數為良性","(D) 大多數為偶發性（sporadic）而與遺傳無關，但合併第一型多發性內分泌腺瘤（multiple endocrine neoplasia type 1, MEN-1）的病患較多單發性但復發率較高"],"answer":1,"image":""},{"id":"md5-112-2-35","subject":"md5","topic":"消化器外科","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"有關肝臟的腺瘤（adenoma）和局部的小節增生（focal nodular hyperplasia, FNH），下列敘述何者最恰當？","options":["(A) 相較之下FNH跟口服避孕藥較有關","(B) 腺瘤較有機會自發性出血，且有機會轉變為惡性","(C) 在核磁共振及電腦斷層下，兩者不易區分","(D) 兩者皆建議手術治療"],"answer":1,"image":""},{"id":"md5-112-2-36","subject":"md5","topic":"消化器外科","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"有關肝臟手術時常用的Pringle maneuver，下列敘述何者最恰當？","options":["(A) 主要係夾住肝動脈、肝靜脈、門脈靜脈","(B) 一般夾15分鐘，放鬆5分鐘","(C) 對肝功能較差者，使用此方式會比選擇性半肝夾緊方式更適合","(D) 此方式與連續血管夾緊方式對術後肝功能及缺血再灌注傷害並無差異"],"answer":1,"image":""},{"id":"md5-112-2-37","subject":"md5","topic":"消化器外科","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"肥胖是文明病，影響人們的身體健康及生活品質，下列關於肥胖手術之敘述何者最恰當？","options":["(A) 近年來，減重手術以採行袖狀胃切除手術（sleeve gastrectomy）方式較為普遍","(B) 代謝手術主要治療的糖尿病類型為type I","(C) 手術方式主要有：限制性、吸收不良及合併型，一般以限制性手術術後較需要補充維他命","(D) 術後3天內有腸道滲漏之併發症，大部分病患採保守治療即可"],"answer":0,"image":""},{"id":"md5-112-2-38","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"一位45歲女性發現左頸部有一腫塊，頸部超音波顯示有一2公分實心（solid）甲狀腺結節，細針穿刺細胞學檢查依Bethesda criteria分類，診斷為nondiagnostic，下列何項進一步處置最為適當？","options":["(A) 重做細針穿刺細胞學檢查","(B) 放射性碘治療（radioactive iodine therapy）","(C) 左側甲狀腺葉切除","(D) 6個月後超音波追蹤檢查"],"answer":0,"image":""},{"id":"md5-112-2-39","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"一位62歲女性病患曾因右側腎上腺嗜鉻細胞瘤（pheochromocytoma）接受右側腎上腺切除手術，術後因左側甲狀腺髓質癌（medullary thyroid carcinoma）接受全甲狀腺切除。下列何者不是適當的追蹤檢查及處置？","options":["(A) 定期檢驗血中鈣、磷、副甲狀腺素以排除原發性副甲狀腺亢進","(B) 定時檢驗血中CEA及calcitonin以排除甲狀腺髓質癌再復發","(C) 131假使CEA及calcitonin有增高，應安排全身放射碘檢查（I whole body scan）以定位甲狀腺髓質癌再復發位置","(D) 定時檢驗尿中VMA及腹部電腦斷層以排除腎上腺嗜鉻細胞瘤再復發"],"answer":2,"image":""},{"id":"md5-112-2-40","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"承上題，因上述這位病患確診為第二型多發性內分泌瘤（MEN 2），她的家人檢查結果：妹妹亦罹患甲狀腺髓質癌，女兒罹患腎上腺嗜鉻細胞瘤。她女兒有個2歲的兒子。下列有關追查這位男童是否亦可能罹患甲狀腺髓質癌，何者最適宜？","options":["(A) 定時檢驗血中thyroglobulin","(B) 檢驗RET proto-oncogene有無基因突變","(C) 定時利用頸超音波檢查以發現甲狀腺腫瘤","(D) 定時檢驗血中CEA及calcitonin"],"answer":1,"image":""},{"id":"md5-112-2-41","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"有關乳房腫瘤切片方式，下列何者最不恰當？","options":["(A) 粗針切片（core needle biopsy）也是一種incisional biopsy","(B) vacuum-assisted biopsy較一般粗針切片（core needle biopsy）可取得更多檢體，偽陰性可能較低","(C) 手術前做粗針切片（core needle biopsy），可以分辨in situ（non-invasive）cancer與invasive cancer，以決定要不要做腋下淋巴切片","(D) 手術前做細針穿刺細胞學檢查（fine needle aspiration cytology），若是惡性，即可切除全乳房"],"answer":3,"image":""},{"id":"md5-112-2-42","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"有關乳房腫瘤在乳房超音波（ultrasound）的惡性特徵，何者最不常見？","options":["(A) 高度大於寬度之形狀（taller than wide shape）","(B) 角狀邊緣（angular margin）","(C) 病灶後回音加強（posterior wall enhancement）","(D) 低音波回音性（hypoechoic echogenicity）"],"answer":2,"image":""},{"id":"md5-112-2-43","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"下列何種化療藥物最不常使用於乳癌病患？","options":["(A) doxorubicin","(B) docetaxel","(C) etoposide","(D) epirubicin"],"answer":2,"image":""},{"id":"md5-112-2-44","subject":"md5","topic":"小兒外科","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"小兒外科特有的先天性疾病，其外科治療術式常會依首創者姓名而命名，下列組合何者錯誤？","options":["(A) 腸道旋轉不良（malrotation）；Ladd procedure","(B) 鰓裂遺跡（branchial cleft remnant）；Sistrunk operation","(C) 巨腸症（Hirschsprung's disease）；Soave procedure","(D) 無肛症（anorectal malformation）；Peña operation"],"answer":1,"image":""},{"id":"md5-112-2-45","subject":"md5","topic":"小兒外科","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"關於新生兒食道閉鎖併氣管食道瘻管，有多種評估系統可以預測其預後，下列何項臨床因子與其預後較無相關？","options":["(A) 出生體重","(B) 有無其他重大先天異常，特別是心臟問題","(C) 手術矯正的時機","(D) 肺部狀況"],"answer":2,"image":""},{"id":"md5-112-2-46","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"2個月大男嬰因發高燒入院治療，檢查發現泌尿道感染合併菌血症及腦膜炎，經抗生素治療3天後發燒逐漸緩解，腎臟超音波發現兩側水腎，遂安排voiding cystourethrogram，檢查結果如圖所示，應診斷為：","options":["(A) 雙側膀胱輸尿管逆流（bilateral vesicoureteral reflux），grade II","(B) 雙側膀胱輸尿管逆流（bilateral vesicoureteral reflux），grade III","(C) 雙側膀胱輸尿管逆流（bilateral vesicoureteral reflux），grade IV","(D) 雙側膀胱輸尿管逆流（bilateral vesicoureteral reflux），grade V"],"answer":3,"image":"md5-112-2-46.jpeg"},{"id":"md5-112-2-47","subject":"md5","topic":"小兒外科","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"下列有關腹裂畸形（gastroschisis）與臍膨出（omphalocele）的比較，何者最不適當？","options":["(A) 臍膨出較易合併染色體異常","(B) 臍膨出的腹壁缺口通常比腹裂畸形大","(C) 臍膨出需要的靜脈輸液通常比腹裂畸形多","(D) 臍膨出較易合併其他先天性異常"],"answer":2,"image":""},{"id":"md5-112-2-48","subject":"md5","topic":"小兒外科","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"先天性巨腸症（Hirschsprung's disease）的診斷是靠直腸切片檢查（rectal biopsy），下列何者病理染色最不適用？","options":["(A) PAS染色法（periodic acid-Schiff staining）","(B) 蘇木素–伊紅染色（hematoxylin and eosin staining）","(C) 鈣視網膜蛋白染色（calretinin immunostaining）","(D) 乙醯膽鹼酶染色（acetylcholinesterase immunostaining）"],"answer":0,"image":""},{"id":"md5-112-2-49","subject":"md5","topic":"小兒外科","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"承上題，診斷確定後，即將無神經節的腸段切除，再將有神經節的腸段拉下（如圖），與遠端肛門口做端對端接合，是下列何種術式？","options":["(A) Swenson procedure","(B) Soave procedure","(C) Duhamel procedure","(D) Sistrunk procedure"],"answer":[0,1],"image":"md5-112-2-49.jpeg","answer_note":"更正:第49題答Ａ或Ｂ者均給分"},{"id":"md5-112-2-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"74歲楊女士這一星期來左下腹疼痛越來越厲害到急診求診，其過去病史有糖尿病、高血壓病及大腸憩室炎；急診的生命徵象穩定，但體溫為38.5℃；其他的臨床症狀包括食慾變差（anorexia）、噁心（nausea）及有腹瀉（diarrhea）的情況。理學檢查發現左下腹疑似有摸到硬塊且有壓痛合併局部性的腹膜炎（localized 3 peritonitis）之情形，抽血檢查發現WBC：19,310/mm，neutrophil：86.1%，CRP：196 mg/L，腹部的電腦斷層如附圖，則最可能的診斷為何？","options":["(A) 缺血性腸壞死（ischemic bowel）","(B) 乙狀結腸腸扭轉（volvulus）","(C) 乙狀結腸憩室炎破裂併膿瘍（ruptured sigmoid diverticulitis with abscess）","(D) 空腸腸繫膜膿瘍（jejunal mesenteric abscess）"],"answer":2,"image":"md5-112-2-50.jpeg"},{"id":"md5-112-2-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"112年第2次第51題","year":112,"session":2,"number":51,"question":"下列血管，何者不是源自下腸繫膜動脈（inferior mesenteric artery）？","options":["(A) left colic artery","(B) sigmoid artery","(C) superior rectal artery","(D) middle rectal artery"],"answer":3,"image":""},{"id":"md5-112-2-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"112年第2次第52題","year":112,"session":2,"number":52,"question":"病人的大腸鏡檢查發現有hamartomatous polyps，同時又有嘴唇、口腔黏膜、手指末端的黑色素沈澱（hyperpigmentation），最可能罹患何種疾病？","options":["(A) juvenile polyposis syndrome","(B) Peutz-Jeghers syndrome","(C) Lynch syndrome","(D) familial adenomatous polyposis"],"answer":1,"image":""},{"id":"md5-112-2-53","subject":"md5","topic":"消化器外科","meta":"112年第2次第53題","year":112,"session":2,"number":53,"question":"根據目前的治療指引，關於減肥手術的適應症，下列何者錯誤？","options":["(A) 22患者BMI＞40 kg/m或BMI＞35 kg/m並有肥胖相關的合併症","(B) 患者飲食療法失敗","(C) 患者家庭會議決定","(D) 患者精神穩定，無酒精依賴或非法使用毒品"],"answer":2,"image":""},{"id":"md5-112-2-54","subject":"md5","topic":"消化器外科","meta":"112年第2次第54題","year":112,"session":2,"number":54,"question":"關於微創手術的模擬訓練（simulation training），下列敘述何者錯誤？","options":["(A) 微創手術的模擬訓練包括box trainer和虛擬實境（virtual reality, VR system），通過模擬可在安全的環境中以學習者為中心的練習來獲得技能","(B) 微創手術的模擬訓練仍無法做到深度感知，手眼協調和雙手敏捷性的訓練（depth perception, hand-eye coordination, and bimanual dexterity）","(C) 手術模擬的精神是術前手術練習的概念，以了解手術病患的解剖結構","(D) 成像技術數位化提供解剖訊息，可以在手術前生成三維VR模型來模擬手術環境"],"answer":1,"image":""},{"id":"md5-112-2-55","subject":"md5","topic":"消化器外科","meta":"112年第2次第55題","year":112,"session":2,"number":55,"question":"下列何者不是基本的腹腔鏡手術術式（basic laparoscopic surgical procedures）？","options":["(A) 腹腔鏡膽囊切除手術","(B) 腹腔鏡子宮切除手術","(C) 腹腔鏡疝氣修補手術","(D) 腹腔鏡闌尾切除手術"],"answer":1,"image":""},{"id":"md5-112-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第2次第56題","year":112,"session":2,"number":56,"question":"下列關於圓形細胞瘤（round cell tumor）的敘述，何者最不適當？","options":["(A) Ewing氏肉瘤家族（Ewing sarcoma family）大部分染色體易位為t(21:22)，導致EWS/FLI-1嵌合體（chimera）","(B) Ewing氏肉瘤（Ewing sarcoma）是放射敏感性腫瘤（radiosensitive tumor），如果手術切緣不乾淨，則術後常須使用局部照射治療","(C) 單發性的原發性骨淋巴瘤（isolated primary lymphoma of the bone）預後較好，常見的組織學類型是large cell type or mixed small and large cell type","(D) 多樣藥化療（multidrug chemotherapy）可提高原發性骨淋巴瘤（primary lymphoma of the bone）的5年生存率"],"answer":0,"image":""},{"id":"md5-112-2-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"112年第2次第57題","year":112,"session":2,"number":57,"question":"30歲男性病人左側股骨幹骨折，下午接受骨髓內鋼釘固定手術，值班時接到護理站通知病人意識模糊，皮膚點狀出血，瞳孔直徑正常，雙側等大，對光有反應，下列敘述何者最不適當？","options":["(A) 胸部X光片會出現暴風雪的外觀（\"snowstorm\" appearance）","(B) 病人可能缺氧及血小板低下","(C) 要懷疑有頭部外傷腦壓升高，應該儘速給與mannitol點滴注射降低腦壓","(D) 給與支持性治療，必要時可加上類固醇治療"],"answer":2,"image":""},{"id":"md5-112-2-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第2次第58題","year":112,"session":2,"number":58,"question":"盧先生因玩滑板不慎跌倒後，用手先去撐地板，導致大拇指變形，經X光照射後顯示骨折的形態為大拇指掌骨基底的複雜粉碎性關節內骨折（comminuted intra-articular fracture of the base of the thumb metacarpal bone），下列何者診斷最適當？","options":["(A) Rolando fracture","(B) Bennett fracture","(C) Jones fracture","(D) boxer's fracture"],"answer":0,"image":""},{"id":"md5-112-2-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"112年第2次第59題","year":112,"session":2,"number":59,"question":"一位身高175公分，20歲的大學男生，拄著二根枴杖步入診間，右膝彎曲無法伸直，無法著地用力。主訴昨天打籃球時，上籃後著地，膝部疼痛卡住，無法伸直及彎曲，右膝X光片顯示無骨折。下列診斷何者最可能？","options":["(A) 內側副韌帶斷裂（medical collateral ligament tear）","(B) 前十字韌帶拉傷（anterior cruciate ligament injury）","(C) 半月板破裂（meniscal tear）","(D) 髕骨韌帶斷裂（patellar tendon rupture）"],"answer":2,"image":""},{"id":"md5-112-2-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第2次第60題","year":112,"session":2,"number":60,"question":"下列何種兒童的骨折最容易造成Salter-Harris type II（骨骺損傷程度分型）的生長板傷害？","options":["(A) 鎖骨骨折（clavicle fracture）","(B) 近端肱骨骨折（proximal humeral fracture）","(C) 肱骨髁上骨折（supracondylar fracture of the humerus）","(D) 肱骨外髁骨折（lateral condylar fracture of the humerus）"],"answer":1,"image":""},{"id":"md5-112-2-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第2次第61題","year":112,"session":2,"number":61,"question":"一位大學生跌倒右手撐地後一個月，手腕仍持續有疼痛的感覺，觸痛的位置如圖箭頭所示，最可能是那個腕骨骨折？","options":["(A) 豆狀骨（pisiform）","(B) 舟狀骨（scaphoid）","(C) 月狀骨（lunate）","(D) 鈎狀骨（hamate）"],"answer":1,"image":"md5-112-2-61.jpeg"},{"id":"md5-112-2-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第2次第62題","year":112,"session":2,"number":62,"question":"關於脊椎狹窄（spinal stenosis），下列敘述何者最不適當？","options":["(A) 先天性的椎管狹窄是最常見的類型","(B) 狹窄可發生在椎管的中央區（central portion）、側隱窩（lateral recess）或神經孔（neuroforamen），但通常不會發生在椎根（pedicle）的位置","(C) 脊椎狹窄最常見於第四、五腰椎的節段","(D) 若病人有進行性的神經缺失（progressive neurologic deficit），手術減壓通常可以得到不錯的療效"],"answer":0,"image":""},{"id":"md5-112-2-63","subject":"md5","topic":"骨科-關節重建","meta":"112年第2次第63題","year":112,"session":2,"number":63,"question":"有關人工關節感染（prosthetic joint infection）的敘述，下列何者最不適當？","options":["(A) 只要發現sinus tract連通到關節內應高度懷疑","(B) 有些病人的CRP不會升高","(C) 關節液檢查白血球計數（WBC count）高於3,000 cells/μL仍不能確定診斷","(D) 一定要拔除人工關節，否則治療不會成功"],"answer":3,"image":""},{"id":"md5-112-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"112年第2次第64題","year":112,"session":2,"number":64,"question":"當輸尿管結石持續造成尿路阻塞後，約有三分之一的病人最短在超過多少時間後就能導致腎功能不可逆的傷害？","options":["(A) 一週","(B) 一個月","(C) 三個月","(D) 六個月"],"answer":1,"image":""},{"id":"md5-112-2-65","subject":"md5","topic":"泌尿-腫瘤","meta":"112年第2次第65題","year":112,"session":2,"number":65,"question":"腎細胞癌（renal cell carcinoma）會發生副腫瘤症候群（paraneoplastic syndromes），其症狀不包括下列何者？","options":["(A) 高血壓","(B) 肝功能異常","(C) 低血鈣","(D) 紅血球增多症"],"answer":2,"image":""},{"id":"md5-112-2-66","subject":"md5","topic":"內分泌與乳房外科","meta":"112年第2次第66題","year":112,"session":2,"number":66,"question":"下列有關成人嗜鉻細胞瘤（pheochromocytoma）之敘述，何者錯誤？","options":["(A) 10%與multiple endocrine neoplasia（MEN）type II有關","(B) 約10%發生於腎上腺（adrenal）","(C) 約10%為兩側腎上腺（adrenal）","(D) 可測量尿液中catecholamine輔助診斷"],"answer":1,"image":""},{"id":"md5-112-2-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"112年第2次第67題","year":112,"session":2,"number":67,"question":"下列何者不是良性前列腺增生（benign prostatic hyperplasia）的手術絕對適應症？","options":["(A) 因良性前列腺增生導致反覆性肉眼可見血尿","(B) 前列腺體積超過50 mL，且國際前列腺症狀評分（IPSS）超過20分","(C) 因良性前列腺增生導致反覆性尿路感染","(D) 因良性前列腺增生導致腎功能缺損"],"answer":1,"image":""},{"id":"md5-112-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"112年第2次第68題","year":112,"session":2,"number":68,"question":"下列有關經尿道前列腺切除手術（transurethral resection of the prostate, TURP）治療之敘述，何者正確？","options":["(A) 針對尿流速的改善，經尿道前列腺切除手術比其他微創療法的效果更好且更持久","(B) 經尿道前列腺切除手術與其他微創療法的住院時間長短相當","(C) 因目前設備及手術技巧進步，經尿道前列腺切除手術後不會造成尿失禁（incontinence）","(D) 手術中可能出現經尿道切除手術症候群（TUR syndrome），病人會出現噁心、嘔吐、神智不清及心跳加速等症狀"],"answer":[0,3],"image":"","answer_note":"更正:第68題答Ａ或Ｄ或AD者均給分"},{"id":"md5-112-2-69","subject":"md5","topic":"泌尿-結石與感染","meta":"112年第2次第69題","year":112,"session":2,"number":69,"question":"下列何者最不是引起尿路感染的危險因子？","options":["(A) 尿路導管","(B) 膀胱出口阻塞","(C) 神經性膀胱","(D) 尿道下裂"],"answer":3,"image":""},{"id":"md5-112-2-70","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"112年第2次第70題","year":112,"session":2,"number":70,"question":"男性性功能涵蓋勃起及射精，過程包括膀胱頸收縮、儲精囊收縮、輸精管蠕動、球海綿體肌（bulbocavernosus）收縮等，都需要完整的神經調控。下列各動作的傳導神經及其歸屬之神經屬性都正確的是：","options":["(A) 儲精囊收縮：閉孔神經（obturator nerve）；交感神經","(B) 陰莖海綿體勃起：陰莖背神經（dorsal penile nerve）；副交感神經","(C) 球海綿體肌收縮：會陰神經（pudendal nerve）；體神經","(D) 膀胱頸收縮：胃下神經（hypogastric nerve）；體神經"],"answer":2,"image":""},{"id":"md5-112-2-71","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"112年第2次第71題","year":112,"session":2,"number":71,"question":"下列有關腎臟移植前對腎臟接受者（recipient）的評估敘述，何者最不恰當？","options":["(A) 草酸沉著症（Oxalosis）通常需要合併肝腎移植治療","(B) 患有多囊腎（polycystic kidney disease）的接受者，在腎臟移植後多囊腎疾病不會復發","(C) 局部節段型腎絲球硬化（focal segmental glomerulosclerosis）在腎臟移植後仍會復發，此類病人腎臟移植預後較差","(D) 全身性紅斑性狼瘡（systemic lupus erythematosus）在腎臟移植後不會復發，此類病人腎臟移植預後較佳"],"answer":3,"image":""},{"id":"md5-112-2-72","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"112年第2次第72題","year":112,"session":2,"number":72,"question":"病人跌倒後被送到急診室，左手肘劇烈疼痛且無法活動。他的左手肘X光片側面照的影像如圖所示，下列敘述何者最恰當？","options":["(A) 可明顯發現肱骨（humerus）骨折","(B) 可明顯發現橈骨（radius）骨折","(C) 生長板（growth plate）尚未癒合","(D) 可明顯發現關節積液（joint effusion）"],"answer":3,"image":"md5-112-2-72.jpeg"},{"id":"md5-112-2-73","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第2次第73題","year":112,"session":2,"number":73,"question":"糖尿病病患主訴會陰部紅腫脹痛，血液中白血球數目增加，電腦斷層檢查呈現如圖。箭號所指之異常最可能之初診斷為下列何者？","options":["(A) inguinal hernia","(B) femoral hernia","(C) obturator hernia","(D) Fournier's gangrene"],"answer":3,"image":"md5-112-2-73.jpeg"},{"id":"md5-112-2-74","subject":"md5","topic":"消化器外科","meta":"112年第2次第74題","year":112,"session":2,"number":74,"question":"45歲女性因飯後右上腹部不適到醫院求診，腹部X光片顯示病變如圖。此病人最可能之初診斷為下列何者？","options":["(A) 膽結石（gallbladder stones）","(B) 總膽管內嵌塞結石（common bile duct impacted stones）","(C) 腎結核病（renal tuberculosis）","(D) 腎結石（renal stones）"],"answer":0,"image":"md5-112-2-74.jpeg"},{"id":"md5-112-2-75","subject":"md5","topic":"消化器外科","meta":"112年第2次第75題","year":112,"session":2,"number":75,"question":"有關傾食症候群（dumping syndrome）的敘述，下列何者最不適當？","options":["(A) 傾食症候群依據症狀發生在進食後的時間，分為早期及晚期","(B) 晚期傾食症候群發生的原因主要是反應性高血糖","(C) 早期傾食症候群可能會有腹瀉，而晚期傾食症候群不會腹瀉","(D) 胃切除手術後初期應該要嚴格限糖，含糖飲料都應避免攝取"],"answer":1,"image":""},{"id":"md5-112-2-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"112年第2次第76題","year":112,"session":2,"number":76,"question":"關於65歲以上老人外傷的敘述，下列何者最不適當？","options":["(A) 最常見的外傷原因為跌倒","(B) 外傷可能會在出血時出現正常的生命徵象","(C) 頭部外傷，出現硬腦膜上血腫（epidural hematoma）的機率比一般人高","(D) 如有使用抗凝血藥物，即使是輕度頭部外傷，仍應該安排電腦斷層檢查"],"answer":2,"image":""},{"id":"md5-112-2-77","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"112年第2次第77題","year":112,"session":2,"number":77,"question":"一位85歲男性，主訴腹脹一天，無解便，胃口差。過去有輕微腦中風，目前還可走路，有高血壓，無任何開刀史。血壓150/85 mmHg，心跳95/min，呼吸18/min，體溫36.6°C。站立姿勢的腹部X光（upright abdominal film）發現整個小腸脹大（distended loops of small bowel），觸診左側鼠蹊部有硬塊。依以上病史與X光發現，下列那一種疾病最有可能？","options":["(A) 腸套疊（intussusception）","(B) 腸沾黏（adhesions）","(C) 直腸癌（rectal cancer）","(D) 疝氣（hernia）"],"answer":3,"image":""},{"id":"md5-112-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"112年第2次第78題","year":112,"session":2,"number":78,"question":"張先生是一位85歲男性，平時需照顧家中患有重度阿茲海默症的妻子。3個月前被診斷腹部有8.5公分之主動脈瘤，外科醫師建議手術，但風險性極高。張先生不希望因手術而中斷對妻子的照顧，決定暫不手術，等以後再和醫師作討論。然而，在來不及進一步討論前，張先生即因腹痛休克被送至急診室，其收縮壓為50毫米汞柱，意識不清，無法表達意願。醫師診斷為腹主動脈破裂，若不安排緊急手術，張先生會有生命危險，然而目前無法聯繫上任何家屬，無法簽署手術同意書。依照上述情境，下列敘述何者最為適當？","options":["(A) 應尊重張先生之前拒絕手術的自主意願，不應安排緊急手術","(B) 病人因年紀大，手術風險高，將占用太多醫療資源，影響公平正義，不應安排緊急手術","(C) 基於醫療法的規定，緊急情況可排除病人的意願，以搶救生命為優先，應立刻安排緊急手術","(D) 因張先生之前沒有聲明緊急手術的情況，且手術後有機會照顧妻子，應立刻安排緊急手術"],"answer":3,"image":""},{"id":"md5-112-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"112年第2次第79題","year":112,"session":2,"number":79,"question":"30歲男性病人近日被診斷為B型肝炎合併肝癌，經移植醫師建議以活體肝臟移植治療其肝癌。其一年多前結婚的妻子希望能捐贈部分肝臟給先生。下列敘述何者最適當？","options":["(A) 因妻子與病人無血緣關係，故無資格捐贈活體器官","(B) 其妻雖為法定配偶，但須結婚滿兩年才有資格捐贈活體器官","(C) 其妻雖為法定配偶，但須有婚生子女才有資格捐贈活體器官","(D) 病人與妻子雖然只結婚一年，因近日方診斷需器官移植，妻子仍可捐贈"],"answer":3,"image":""},{"id":"md5-112-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"112年第2次第80題","year":112,"session":2,"number":80,"question":"各大醫學中心都競相發展移植醫學，但是因為器官難求，等待者眾，為了鼓勵捐贈器官，某醫學中心想了一個辦法：如果在院內發現潛在捐贈者與等待移植病人配對適合，就請病人自行接觸潛在捐贈者的家屬，除了動之以情也可以直接談價碼。這樣作法的倫理法律問題不包含下列那一項？","options":["(A) 可能會侵犯捐贈者隱私權","(B) 可能牽涉到器官買賣","(C) 可能違背公平分配的規定","(D) 可能影響健保支付"],"answer":3,"image":""},{"id":"md5-113-1-1","subject":"md5","topic":"神經外科","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"一位嚴重頭部外傷病人（GCS=7分），在第一時間的處置，下列何者最不適當？","options":["(A) 應放置氣管內管","(B) 應趕緊給與類固醇以減少受傷後引起的腦腫或腦壓上升","(C) 若有合併低血壓情形，應趕緊給與輸液穩定血壓","(D) 應使用頸圈固定病人頸部"],"answer":1,"image":""},{"id":"md5-113-1-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"在急診室針對鈍挫傷（blunt trauma）病人的評估，下列何種處置或檢查對確定診斷最無幫助？","options":["(A) 胸部的X光檢查（chest X ray）","(B) 腹部的X光檢查（abdominal film）","(C) 骨盆的X光檢查（pelvic film）","(D) 測量心跳、血壓及EKG的變化"],"answer":1,"image":""},{"id":"md5-113-1-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"有關腹部腔室症候群（abdominal compartment syndrome），下列敘述何者錯誤？","options":["(A) 腹部手術後若腹部壓力增加，將導致腹內器官灌流不足","(B) 腹部腔室症候群不會影響呼吸器的使用","(C) 腹內壓高低可由Foley catheter量測","(D) 會造成cardiac output降低"],"answer":1,"image":""},{"id":"md5-113-1-4","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"有關手術後肺坍塌（atelectasis）的敘述，下列何者錯誤？","options":["(A) 麻醉藥的使用，降低了咳嗽反射","(B) 術後肺部表面張力素的分泌下降","(C) 術後肺部的併發症以肺坍塌最常見","(D) 氣管內插管與肺坍塌無關"],"answer":3,"image":""},{"id":"md5-113-1-5","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"米蘭大學的Mazzaferro教授等人於1996年提出米蘭準則（Milan criteria），用以選擇適合的肝癌患者接受肝臟移植手術。下列何者不是米蘭準則的選擇條件？","options":["(A) 單一顆腫瘤，直徑不大於6.5公分","(B) 二至三顆腫瘤，每顆直徑皆不大於3公分","(C) 沒有肝內血管侵犯","(D) 沒有肝外轉移病灶"],"answer":0,"image":""},{"id":"md5-113-1-6","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"有關胰臟移植，下列敘述何者正確？","options":["(A) 胰臟移植不適合用來治療第一型糖尿病","(B) 胰臟移植的胰液引流方法可分為膀胱及腸道引流兩大類，目前以膀胱引流較普遍被使用","(C) 胰臟移植最常見的手術併發症為移植物的血管栓塞","(D) 胰臟移植後最常見的長期死亡原因為糖尿病復發"],"answer":2,"image":""},{"id":"md5-113-1-7","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"接受Billroth II手術的病人，常需要補充下列何種電解質？","options":["(A) 鉀（K）","(B) 鈉（Na）","(C) 鈣（Ca）","(D) 鎂（Mg）"],"answer":2,"image":""},{"id":"md5-113-1-8","subject":"md5","topic":"神經外科","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"有關腦膜瘤（meningioma），下列敘述何者正確？","options":["(A) 從硬腦膜長出來，MRI常常描述為dural-based tumor","(B) 手術切除程度（extent of resection）常使用Simpson grading scale","(C) 約有20% meningioma病人是多發性（multiple）","(D) 不管復發或原發腫瘤，radiation therapy都沒有治療的角色"],"answer":1,"image":""},{"id":"md5-113-1-9","subject":"md5","topic":"神經外科","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"WHO膠質瘤分級grade I～IV，於光學顯微鏡（light microscopy）下表現的特徵，不包括下列何者？","options":["(A) degree of cellularity","(B) pleomorphism","(C) calcification","(D) necrosis"],"answer":2,"image":""},{"id":"md5-113-1-10","subject":"md5","topic":"神經外科","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"有關評估顱內動脈瘤破裂後之預後的量表，下列何者正確？","options":["(A) Hunt and Hess scale 0分代表影像上無法判斷有無動脈瘤","(B) Fisher grading是藉由評估核磁共振影像中蜘蛛網膜下腔的出血量，預測發生腦血管痙攣的可能性","(C) World Federation of Neurological Surgeons Clinical Grading Scale數字越小預後越好","(D) Glasgow Coma Scale的分數與預後無關"],"answer":2,"image":""},{"id":"md5-113-1-11","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"某病患有頸椎狹窄之病史，遭到車禍撞擊後意識正常，神經學檢查發現肩膀以下感覺異常，雙臂甚至有刺痛感，上肢肌力1～2分，下肢肌力3～4分。依照美國脊椎損傷學會（ASIA）的分類，此一病患的ASIA impairment scale和臨床症狀，應為下列何者？","options":["(A) B級，central cord syndrome","(B) C級，anterior cord syndrome","(C) D級，central cord syndrome","(D) E級，anterior cord syndrome"],"answer":2,"image":""},{"id":"md5-113-1-12","subject":"md5","topic":"神經外科","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"下列何種情形不會造成腦壓升高？","options":["(A) 蜘蛛膜下腔出血","(B) 降低血中二氧化碳濃度","(C) 阻塞性水腦症","(D) 腦實質出血30 c.c."],"answer":1,"image":""},{"id":"md5-113-1-13","subject":"md5","topic":"神經外科","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"下列有關腦膨出（encephalocele）的敘述，何者錯誤？","options":["(A) 大部分膨出發生在頭顱中線","(B) 顱底膨出較少見","(C) 需做顱骨整型，回置膨出之腦組織","(D) 患者常合併智力障礙"],"answer":2,"image":""},{"id":"md5-113-1-14","subject":"md5","topic":"整形重建外科","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"肌肉皮瓣（muscle flap）依照血管供應肌肉的方式可分成五種類型，闊背肌肉皮瓣（latissimus dorsi muscle flap）屬於那一類型？","options":["(A) type II","(B) type III","(C) type IV","(D) type V"],"answer":3,"image":""},{"id":"md5-113-1-15","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"Gilula's arcs是指在手腕X光AP view下可畫出的弧線，用以評估腕骨的對齊狀況，該弧線共有幾條？","options":["(A) 2","(B) 3","(C) 4","(D) 5"],"answer":1,"image":""},{"id":"md5-113-1-16","subject":"md5","topic":"整形重建外科","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"於上下顎咬合不正手術，矯正後的標準以符合Angle classification系統的第幾型為最佳？","options":["(A) 第一型（class I）","(B) 第二型（class II）","(C) 第三型（class III）","(D) 第四型（class IV）"],"answer":0,"image":""},{"id":"md5-113-1-17","subject":"md5","topic":"整形重建外科","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"關於頭頸部重建，下列敘述何者錯誤？","options":["(A) 頦下皮瓣（submental flap）的供應血管源於頦下動脈（submental artery），為facial artery的分支之一，可用於口腔內部缺損重建","(B) 胸大肌肌皮瓣（pectoralis major myocutaneous flap）由內乳動脈（internal mammary artery）供應血流，可用在全喉切除術（total laryngectomy）後的下咽部重建","(C) 胸大肌肌皮瓣（pectoralis major myocutaneous flap）可應用於大血管暴露時，作為salvage reconstructive procedure","(D) 鎖骨上皮瓣（supraclavicular flap）由鎖骨上動脈（supraclavicular artery）供應，可應用於臉部或頸部外側，需要做為較薄的皮瓣時使用"],"answer":1,"image":""},{"id":"md5-113-1-18","subject":"md5","topic":"整形重建外科","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"關於乳癌切除後的乳房重建（breast reconstruction），下列何者正確？","options":["(A) 腹部穿枝皮瓣中的deep inferior epigastric perforator flap可以得到最自然與最佳觸感的乳房，也是目前最常使用的乳房重建方法","(B) 使用義乳乳房重建（implant-based reconstruction），可能的併發症包括不自然、莢膜攣縮、義乳破裂、感染等","(C) 使用自體組織游離皮瓣（free autologous tissue reconstruction）重建乳房時最好選擇腋下的胸背動脈（thoracodorsal vessel）當受區血管（recipient vessel）","(D) 義乳乳房重建（implant-based reconstruction）導致的巨大細胞淋巴瘤（BIA-ALCL）西方人比東方人少見"],"answer":1,"image":""},{"id":"md5-113-1-19","subject":"md5","topic":"心臟血管外科","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"關於冠狀動脈阻塞疾病，下列敘述何者錯誤？","options":["(A) 根據AHA/ACC guideline，戒菸對於預防冠狀動脈阻塞是class I recommendation","(B) 接受冠狀動脈繞道手術後，若無絕對禁忌症，建議儘早加上β-blocker","(C) 造成acute coronary syndrome，常見的機轉包含plaque rupture、thrombus formation","(D) 針對心臟收縮功能低下的病人，加上digoxin有足夠證據顯示助於降低死亡率"],"answer":3,"image":""},{"id":"md5-113-1-20","subject":"md5","topic":"心臟血管外科","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"關於心臟腫瘤，下列敘述何者最適當？","options":["(A) 原發性心臟腫瘤中，惡性多於良性","(B) 若為良性腫瘤且病人曾發生栓塞症狀，使用抗凝血劑治療","(C) 超過半數的心臟黏液瘤（myxoma）源自左心房的心房中隔","(D) 心臟電腦斷層（heart CT）是目前的診斷標準工具"],"answer":2,"image":""},{"id":"md5-113-1-21","subject":"md5","topic":"心臟血管外科","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"根據Crawford的胸腹主動脈瘤修復（thoracoabdominal aortic aneurysm repair）分類，從左鎖骨下動脈起至腎動脈以下之腹主動脈是屬於第幾型？","options":["(A) I","(B) II","(C) III","(D) IV"],"answer":1,"image":""},{"id":"md5-113-1-22","subject":"md5","topic":"心臟血管外科","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"下列何者為目前診斷深層靜脈栓塞（deep vein thrombosis）最常使用之工具？","options":["(A) 杜卜勒超音波（duplex ultrasound）","(B) 核磁共振（magnetic resonance venography）","(C) 靜脈攝影（venography）","(D) 阻抗容積描記術（impedance plethysmography）"],"answer":0,"image":""},{"id":"md5-113-1-23","subject":"md5","topic":"心臟血管外科","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"對於心臟瓣膜之選擇與敘述，下列何者錯誤？","options":["(A) 一般而言，大於65歲之主動脈瓣或大於70歲之二尖瓣，偏向選擇使用生物性瓣膜","(B) 在機械瓣膜置換後，要使用prothrombin time（PT）/ international normalized ratio（INR）來監控","(C) Ross手術是將肺動脈瓣取下放到主動脈位置取代主動脈瓣，因不用使用抗凝血劑，特別適合於年老病人","(D) 雖然新型的抗凝血劑（novel oral anticoagulant, NOAC）問世，如dabigatran、rivaroxaban，仍不建議使用於機械性瓣膜病患"],"answer":2,"image":""},{"id":"md5-113-1-24","subject":"md5","topic":"心臟血管外科","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"1天大之新生兒單純大動脈轉位（simple transposition of great arteries without ventricular defect），發紺，血氧約60%，下列處置何者最不合醫療常規？","options":["(A) 立即插管，給輸液","(B) 避免分流過大，停止血管擴張劑prostaglandin E1（PGE1），在2週後手術","(C) 立即送手術室行大動脈轉位手術（arterial switch operation）","(D) 可考慮送導管室進行心房中隔氣球擴張術"],"answer":1,"image":""},{"id":"md5-113-1-25","subject":"md5","topic":"消化器外科","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"關於食道淋巴分布之敘述，下列何者錯誤？","options":["(A) 食道淋巴回流，橫向引流比縱向引流多6倍，因此有腫瘤發生時，會有比較多的局部淋巴轉移","(B) 食道淋巴引流網絡，比動脈血液網絡豐富","(C) 食道淋巴引流主要在黏膜下層（submucosal layer）","(D) 頸部食道淋巴引流，很短距離就可穿出肌肉層至局部淋巴結"],"answer":0,"image":""},{"id":"md5-113-1-26","subject":"md5","topic":"消化器外科","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"關於食道弛緩症（achalasia），下列敘述何者錯誤？","options":["(A) 食道蠕動壓力測量（manometry）為標準診斷工具","(B) 有些病人發生原因與感染有關，如Chagas disease（parasitic infection with Trypanosoma cruzi）","(C) 第四期病人，食道有如巨大之大腸（megaesophagus），常需將患部之食道切除並重建","(D) 經過20年以上可能會有惡性變化，常見惡性腫瘤為腺癌（adenocarcinoma）"],"answer":3,"image":""},{"id":"md5-113-1-27","subject":"md5","topic":"胸腔外科","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"關於小細胞肺癌（small cell lung cancer）之敘述，下列何者錯誤？","options":["(A) 大多是位在中央（central located）","(B) 可以分成侷限期（limited stage）及擴展期（extensive stage）","(C) 五年存活率很差","(D) 發現時大多是以局部侵犯為主，適合手術切除"],"answer":3,"image":""},{"id":"md5-113-1-28","subject":"md5","topic":"胸腔外科","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"有關肺部過誤瘤（hamartoma）之敘述，下列何者錯誤？","options":["(A) 是肺部最常見的良性腫瘤","(B) 特徵為軟骨（cartilage）過度生長","(C) 通常發生於20～30歲之年輕女性","(D) 通常生長緩慢"],"answer":2,"image":""},{"id":"md5-113-1-29","subject":"md5","topic":"胸腔外科","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"有關乳糜胸（chylothorax）的敘述，下列何者錯誤？","options":["(A) 通常是乳白或澄清的外觀","(B) 內容物富含三酸甘油脂、乳糜微粒和嗜酸性球（eosinophils）","(C) 醫源性（iatrogenic）乳糜胸，常和胸部食道切除或縱隔腔淋巴廓清的手術有關","(D) 量少的乳糜胸，可用保守療法，像是中鏈三酸甘油脂飲食（medium-chain triglyceride diet）或是完全禁食搭配全靜脈營養"],"answer":1,"image":""},{"id":"md5-113-1-30","subject":"md5","topic":"消化器外科","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"下列何者為臨床上小腸腸道出血（small bowel bleeding）較為常見的原因？","options":["(A) small bowel tumors","(B) angiodysplasias","(C) Crohn's disease","(D) Meckel's diverticulum"],"answer":1,"image":""},{"id":"md5-113-1-31","subject":"md5","topic":"消化器外科","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"下列何項腹腔鏡減重手術是結合侷限和吸收不良減重手術（a combination of restriction and malabsorption surgery）？","options":["(A) 腹腔鏡調節式胃束帶手術（laparoscopic AGB）","(B) 腹腔鏡Roux-en-Y胃腸繞道手術（laparoscopic RYGB）","(C) 腹腔鏡垂直束帶胃成形術（laparoscopic vertical banded gastroplasty）","(D) 內視鏡胃內水球置放術（BIB）"],"answer":1,"image":""},{"id":"md5-113-1-32","subject":"md5","topic":"消化器外科","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"有關肝硬化臨床表徵的敘述，下列何者錯誤？","options":["(A) 蜘蛛狀血管瘤（spider angioma）與手掌紅斑（palmar erythema）與性荷爾蒙的代謝有關","(B) 門脈高壓造成門脈系統與臍動脈之側枝循環（collateral circulation）產生上腹部血流雜音稱為Cruveilhier-Baumgarten murmur","(C) 肝硬化會造成心輸出量增加、心跳增加以及周邊血管阻力降低","(D) 肌肉痙攣與腹水、高平均動脈壓、高血漿腎素活性有關"],"answer":3,"image":""},{"id":"md5-113-1-33","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"有關克隆氏症（Crohn's disease），下列敘述何者最恰當？","options":["(A) 是可藉由手術治癒的疾病","(B) 主要侵犯在大腸","(C) 相對好發於社經地位較高者，且抽菸是其危險因子","(D) 容易有腸道以外的症狀，且pyoderma gangrenosum和ankylosing spondylitis與腸道發炎之嚴重程度成正相關"],"answer":2,"image":""},{"id":"md5-113-1-34","subject":"md5","topic":"消化器外科","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"下列有關胃神經內分泌腫瘤（neuroendocrine tumor）的敘述，何者錯誤？","options":["(A) 胃神經內分泌腫瘤是由腸道interstitial cell of Cajal增生形成的","(B) type II胃神經內分泌腫瘤與MEN type I有關","(C) 局部的胃神經內分泌腫瘤治療以完全切除為主","(D) type III胃神經內分泌腫瘤預後最差"],"answer":0,"image":""},{"id":"md5-113-1-35","subject":"md5","topic":"消化器外科","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"張小姐35歲，因上腹痛至急診室就醫，身體診察腹部柔軟但有明顯壓痛，腹部電腦斷層發現肝臟有一顆6公分腫瘤，此腫瘤呈現peripheral enhancement with centripetal progression，另外腹腔內有少量液體。詢問病史發現病人沒有B型、C型肝炎的病史，但長期服用避孕藥，下列何者為最可能的診斷？","options":["(A) liver cell adenoma","(B) focal nodular hyperplasia","(C) hamartoma","(D) hemangioma"],"answer":0,"image":""},{"id":"md5-113-1-36","subject":"md5","topic":"消化器外科","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"急性膽管炎時常呈現典型症狀，稱之為Charcot triad，下列何者不是Charcot triad之症狀？","options":["(A) 發燒","(B) 黃疸","(C) 右上腹腫塊","(D) 右上腹痛"],"answer":2,"image":""},{"id":"md5-113-1-37","subject":"md5","topic":"消化器外科","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"關於胰臟branch duct intraductal papillary mucinous neoplasms（BD-IPMN），下列何者不是high risk features？","options":["(A) jaundice","(B) fever","(C) main pancreatic duct＞1cm","(D) enhancing mural nodule larger than 5 mm within cyst"],"answer":1,"image":""},{"id":"md5-113-1-38","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"一位60歲女性因意識改變、噁心嘔吐被送至急診，抽血發現血鈣高達15.5 mg/dL及parathyroid hormone（PTH）475 pg/mL，一開始處置下列何者最為適當？","options":["(A) continuous furosemide","(B) rehydration with normal saline","(C) emergency parathyroidectomy","(D) oral cinacalcet"],"answer":1,"image":""},{"id":"md5-113-1-39","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"一位30歲女性有Hashimoto's thyroiditis，因follicular adenoma接受甲狀腺左葉全切除手術，術後一個月抽血發現TSH 6.0 mIU/L，較正常值略為升高，free T4仍在正常範圍，儘管並無臨床症狀，某些情況下仍建議她服用甲狀腺素補充，但下列何者除外？","options":["(A) pregnancy","(B) 1.5 cm nodular goiter in the right thyroid","(C) presence of coronary heart disease","(D) presence of TSH receptor antibody"],"answer":3,"image":""},{"id":"md5-113-1-40","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"一位12歲男童因意外發現高血壓192/110 mmHg來小兒科門診，無甲狀腺癌及嗜鉻細胞瘤家族史。經檢查結3果：24小時尿VMA 24.2 mg，腹部超音波及電腦斷層掃描發現右腎上腺有一5×4×3 cm腫塊合併中央區壞死。下列處置何者最不適當？","options":["(A) 術前準備建議服用spironolactone以降血壓","(B) 建議進行腹腔鏡腎上腺摘除術","(C) 術中血壓若太高可藉由nitroprusside或phentolamine調控","(D) 術後若再犯應安排MIBG scan偵查其他病灶"],"answer":0,"image":""},{"id":"md5-113-1-41","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"下列那一乳癌病人，最不適合保留乳房？","options":["(A) 病人乳房為E罩杯，乳房腫瘤約2公分","(B) 腋下淋巴結證實有癌轉移","(C) 乳房X光攝影有多處不在同一象限（quadrant）不確定良惡性的顯微鈣化（microcalcifications）","(D) 病理檢驗為侵犯性乳癌（invasive carcinoma）"],"answer":2,"image":""},{"id":"md5-113-1-42","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"有關乳癌篩檢敘述，下列何者錯誤？","options":["(A) mammography是歐美大量篩檢最常用的工具","(B) 乳房超音波（ultrasound）有operator-dependent的問題（不同人操作可能有不同結果）較不適合做篩檢工具","(C) 50歲以上mammography篩檢效果較好，因爲mammography在緻密性乳房（dense breast）靈敏度較好","(D) 50歲以下mammography篩檢效果較差，原因之一可能是因為腫瘤進展較快速"],"answer":2,"image":""},{"id":"md5-113-1-43","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"21歲女性因右乳疼痛接受乳房超音波檢查，發現右乳有一2.3公分低回音病灶疑似纖維腺瘤（fibroadenoma），BI-RADS category 2，則下列處置何者較不考慮？","options":["(A) 半年至一年進行超音波追蹤","(B) 進一步安排乳房攝影（mammography）檢查","(C) 可考慮切片檢查","(D) 若疼痛困擾嚴重可酌量給與止痛藥物"],"answer":1,"image":""},{"id":"md5-113-1-44","subject":"md5","topic":"小兒外科","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"一幼兒因嘔吐求診，腹部Ｘ光如圖所示，下列何者為最不可能之鑑別診斷？","options":["(A) 胃蹼（gastric web）","(B) 十二指腸蹼（duodenal web）","(C) 環狀胰（annular pancreas）","(D) 腸道旋轉不良併扭轉（malrotation with volvulus）"],"answer":0,"image":"md5-113-1-44.jpeg"},{"id":"md5-113-1-45","subject":"md5","topic":"小兒外科","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"鼠蹊部疝氣（inguinal hernia）為兒童常見的外科疾病，了解疝氣腹壁解剖學相關知識對於手術執行極為重要。下列有關鼠蹊部疝氣解剖學，何者敘述正確？","options":["(A) 間接型鼠蹊疝氣（indirect inguinal hernia）經由腹壁下動脈（inferior epigastric artery）內側突出於腹壁，多發生於兒童","(B) 髂腹下神經（iliohypogastric nerve）走於精索（spermatic cord）之上，與精索一齊穿出外鼠蹊環（external inguinal ring），負責大腿內側上方的感覺","(C) 提睪肌（cremaster muscle）是由腹內斜肌（internal oblique muscle）延伸而來","(D) 睪丸動脈（testicular artery）源自內髂動脈（internal iliac artery）"],"answer":2,"image":""},{"id":"md5-113-1-46","subject":"md5","topic":"小兒外科","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"一位6個月大的幼兒過去無任何病史，因頸部胸鎖乳突肌前緣皮膚有一小開口且有分泌物（如圖所示）接受手術，最可能的診斷為何？","options":["(A) 甲狀舌管瘻管（thyroglossal duct fistula）","(B) 第二對鰓裂遺跡瘻管（second branchial remnant fistula）","(C) 淋巴結發炎（lymphadenitis）","(D) 淋巴管瘤併淋巴外漏（lymphangioma with lymphorrhea）"],"answer":1,"image":"md5-113-1-46.jpeg"},{"id":"md5-113-1-47","subject":"md5","topic":"外科-休克創傷傷口","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"媽媽抱著1歲半女童坐副駕駛座，爸爸因疲勞駕車自撞橋墩而被送至醫院急診，發現女童意識昏迷，對疼痛刺激稍微會縮手，血壓65/23 mmHg，心跳153/min，呼吸24/min，體溫36.3℃，脈搏血氧飽和度90%，目測體重約10公斤，下列敘述何者錯誤？","options":["(A) 病童昏迷指數為E1V1M4，但呼吸道暢通，且仍有自發性呼吸，可以不需插氣管內管","(B) 全身身體檢查是否有外傷或內出血，若可能並予以止血","(C) 立刻建立周邊靜脈注射並抽血檢查，先給與輸液（如：normal saline）200 mL三次後再度測量生命徵象仍未改善，應立即輸血","(D) 可行全身電腦斷層掃描，以檢查受傷情況"],"answer":0,"image":""},{"id":"md5-113-1-48","subject":"md5","topic":"外科-休克創傷傷口","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"承上題，檢查全身無明顯出血及外傷，頭部電腦斷層無頭骨骨折及顱內出血，但仍意識不清，胸腹部X光如圖所示，輸注packed RBC 100 mL後量測生命徵象，血壓114/53 mmHg，心跳163/min，呼吸28/min，體溫36.7℃，脈搏血氧飽和度90%，下列敘述何者錯誤？","options":["(A) 應持續監測昏迷指數及瞳孔大小等神經學檢查，可能需要再次進行頭部電腦斷層檢查","(B) 追蹤抽血檢查結果，持續嚴密監控生命徵象及尿量","(C) 雖無肋骨骨折，但右側可能血胸","(D) 置入胸管後馬上引流出230 mL血色引流液，應立即進行開胸手術止血"],"answer":3,"image":"md5-113-1-48.jpeg"},{"id":"md5-113-1-49","subject":"md5","topic":"小兒外科","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"有關腸套疊（intussusception）的敘述，下列何者最適當？","options":["(A) 臨床表現多半與2的法則（the rule of 2’s）有關99m","(B) 疑似病例可以行Tc-pertechnetate核醫學檢查，以確定診斷","(C) 是最常見的先天性胃腸道畸形","(D) 靜水壓力復位術（hydrostatic reduction）對於大部分單純性的腸套疊都適用"],"answer":3,"image":""},{"id":"md5-113-1-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"55歲女性於健康檢查時糞便潛血反應陽性，問診並無血便、排便習慣改變等症狀且無大腸直腸癌家族史，肛門指診及肛門鏡檢查發現內痔但沒有出血。安排大腸鏡檢查後於乙狀結腸發現一個約1公分的莖性息肉（pedunculated polyp），下列何項處理最適當？","options":["(A) 做內視鏡息肉切除（polypectomy）","(B) 只做切片再觀察","(C) 直接安排腹腔鏡前位切除（laparoscopic anterior resection）","(D) 觀察即可"],"answer":0,"image":""},{"id":"md5-113-1-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"113年第1次第51題","year":113,"session":1,"number":51,"question":"骨盆底肌肉（pelvic floor）的組成不包括下列那一群？","options":["(A) puborectalis muscle","(B) iliococcygeus muscle","(C) pubococcygeus muscle","(D) gluteus maximus muscle"],"answer":3,"image":""},{"id":"md5-113-1-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"113年第1次第52題","year":113,"session":1,"number":52,"question":"關於降結腸癌手術造成大出血，最常見的原因為：","options":["(A) 脾臟撕裂傷","(B) 上腸繫膜靜脈撕裂","(C) 下腔靜脈撕裂","(D) 主動脈撕裂"],"answer":0,"image":""},{"id":"md5-113-1-53","subject":"md5","topic":"消化器外科","meta":"113年第1次第53題","year":113,"session":1,"number":53,"question":"關於腹腔鏡與開放式闌尾切除手術（laparoscopic appendectomy versus open appendectomy）的比較，下列何者錯誤？ћ總體來說，與開放手術相比，腹腔鏡手術的併發症發生率較低 ќ開放式闌尾切除手術可以檢查整個腹膜腔，因此可排除其他腹腔內急性疾病，例如憩室炎或卵巢膿腫 ѝ不管採用何種方法，闌尾切除手術最重要的是安全地進行手術以維持病患安全 ў患者出現局部右下腹疼痛和發燒，理學及影像檢查發現可能為闌尾炎延遲發作（delayed presentation of appendicitis），此時腹腔鏡引流手術（laparoscopic drainage）因為沒有助益，不應施行","options":["(A) ћќѝ","(B) ћќў","(C) 僅ќѝ","(D) 僅ќў"],"answer":3,"image":""},{"id":"md5-113-1-54","subject":"md5","topic":"消化器外科","meta":"113年第1次第54題","year":113,"session":1,"number":54,"question":"微創手術（minimally invasive surgery）的發展改變外科手術的方式，下列敘述何者正確？ ћ相對於非急性期腹腔鏡膽囊切除術，急性膽囊炎的腹腔鏡膽囊切除術具有更長的手術時間和更高的機率因為失敗轉為開腹手術，並且具有更高的總膽管及總肝管損傷風險 ќ 大多數腹腔鏡檢查是使用CO2氣腹方式進行的，腹部壓力設定在25 mmHg ѝ鼻胃管置入可以減輕胃部壓力並增加手術視野 ў如果進行膽道造影，常用的方式為在膽囊開口切開膽囊管，然後將膽管造影導管穿過，將造影劑注入膽囊管和膽道獲得膽道攝影（cholangiogram）圖像 џ如果是急性膽囊炎在手術過程中造成膽囊破裂，應使用無菌檢體袋取回檢體及濺出的所有結石","options":["(A) 僅ћѝў","(B) 僅ќўџ","(C) ћќўџ","(D) ћѝўџ"],"answer":3,"image":""},{"id":"md5-113-1-55","subject":"md5","topic":"消化器外科","meta":"113年第1次第55題","year":113,"session":1,"number":55,"question":"關於單一切口腹腔鏡手術（single-incision laparoscopic surgery）建議的設備及對外科醫師的益處之敘述，何者錯誤？","options":["(A) 較長的器械較易接觸到手術區域（surgical field）","(B) 長短不一的器械（varied-length instruments）無法減少體外的器械碰撞（extracorporeal clashing）","(C) 高畫質的鏡頭可提供高品質影像及術內視野","(D) 較細長的器械（slimline instruments）可以減少手術內部及外部的碰撞"],"answer":1,"image":""},{"id":"md5-113-1-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第1次第56題","year":113,"session":1,"number":56,"question":"有關骨腫瘤的敘述，下列何者最適當？","options":["(A) Ollier disease是指多發性內生軟骨瘤（multiple enchondromas）合併血管瘤（hemangiomas）","(B) 軟骨母細胞瘤（chondroblastoma）好發於青少年的長骨骨骺（epiphysis）","(C) 骨巨大細胞瘤（giant cell tumor of the bone）復發率極低，手術採用病灶內刮除","(D) 單純性骨囊腫（simple bone cyst）好發於成年人的肱骨遠端"],"answer":1,"image":""},{"id":"md5-113-1-57","subject":"md5","topic":"骨科-關節重建","meta":"113年第1次第57題","year":113,"session":1,"number":57,"question":"為了改善骨科人工關節置換常規排程手術感染的發生率，下列敘述何者最適當？","options":["(A) 應適當選擇預防性（prophylactic）抗生素","(B) 預防性抗生素應在執行切開手術傷口前120分鐘開始給藥","(C) 預防性抗生素應在手術結束後72小時才能停止給藥","(D) 常規使用vancomycin或clindamycin減少手術傷口感染"],"answer":0,"image":""},{"id":"md5-113-1-58","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"113年第1次第58題","year":113,"session":1,"number":58,"question":"關於單純性肘關節脫臼（simple elbow dislocation）之敘述，下列何者最不適當？","options":["(A) 閉鎖復位（closed reduction）後，通常肘關節穩定，較少發生慢性再發性脫臼（chronic recurrent dislocation）","(B) 前向脫臼（anterior dislocation）比後向脫臼（posterior dislocation）少見","(C) 閉鎖復位（closed reduction）後，若肘關節穩定，仍需以石膏副木固定肘關節至少2個月","(D) 閉鎖復位（closed reduction）後，若肘關節不穩定，可考慮手術治療"],"answer":2,"image":""},{"id":"md5-113-1-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"113年第1次第59題","year":113,"session":1,"number":59,"question":"20歲男性，兩天前車禍時左肩受到直接撞擊，造成嚴重腫痛及瘀青，經急診X光檢查發現肱骨近端骨折，包含肱骨頸及大、小結節（tuberosity）骨折移位，皆超過1公分，下列各項手術中，何者最適當？","options":["(A) 開放性復位及內固定治療","(B) 半肩人工關節置換","(C) 閉鎖性復位及經皮鋼針固定治療","(D) 全肩人工關節置換"],"answer":0,"image":""},{"id":"md5-113-1-60","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"113年第1次第60題","year":113,"session":1,"number":60,"question":"有關膝關節前十字韌帶（anterior cruciate ligament）之敘述，下列何者最不適當？","options":["(A) 防止脛骨前方移行（anterior tibial translation）","(B) 在膝關節進行螺旋轉動復位機轉運動（screw-home mechanism）時，引導脛骨（tibia）做外旋轉（external rotation）","(C) 在膝關節伸直時（extension），後外側束（posterolateral bundle）是鬆弛的","(D) 根據其脛骨的嵌入點（tibial insertion），分為前內側束（anteromedial bundle）及後外側束（posterolateral bundle）"],"answer":2,"image":""},{"id":"md5-113-1-61","subject":"md5","topic":"整形重建外科","meta":"113年第1次第61題","year":113,"session":1,"number":61,"question":"下列手部斷指再接（replantation）的適應症，何者最不適當？","options":["(A) 拇指截肢","(B) 多指截肢","(C) 小孩的斷指","(D) 單指多段截肢"],"answer":3,"image":""},{"id":"md5-113-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第1次第62題","year":113,"session":1,"number":62,"question":"50歲的男性，患有下背痛及雙側下肢酸麻。脊椎X光檢查顯示第五腰椎椎弓斷裂、第五腰椎／第一薦椎的Meyerding第一級向前滑脫（L5 on S1 spondylolisthesis）。最可能受到壓迫的神經根為：","options":["(A) 第三腰椎神經根","(B) 第四腰椎神經根","(C) 第五腰椎神經根","(D) 第一薦椎神經根"],"answer":2,"image":""},{"id":"md5-113-1-63","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第1次第63題","year":113,"session":1,"number":63,"question":"有關兒童頸椎融合症候群（Klippel-Feil syndrome）的敘述，下列何者最適當？","options":["(A) 在受孕後第3至8週時，頸椎分節失敗（failure of segmentation）所造成","(B) 很少合併泌尿、神經、心肺系統與聽力等障礙","(C) 常見頭髮後緣線高（high posterior hairline）","(D) 常見頸部較長與頭頸活動度受限"],"answer":0,"image":""},{"id":"md5-113-1-64","subject":"md5","topic":"泌尿-結石與感染","meta":"113年第1次第64題","year":113,"session":1,"number":64,"question":"下列何者是治療腎臟完全性鹿角結石（complete renal staghorn stone）的最佳選擇？","options":["(A) 體外震波碎石術（extracorporeal shock wave lithotripsy）","(B) 輸尿管鏡碎石術（ureteroscopic lithotripsy）","(C) 經皮腎臟碎石取石手術（percutaneous nephrolithotripsy）","(D) 尿液鹼化（alkalinization of urine）"],"answer":2,"image":""},{"id":"md5-113-1-65","subject":"md5","topic":"泌尿-腫瘤","meta":"113年第1次第65題","year":113,"session":1,"number":65,"question":"一位50歲男性主訴最近一個月在包皮發現一個0.5公分的病灶，經切片證實為Ta期低惡性度鱗狀上皮細胞癌（grade 1, squamous cell carcinoma），下列何種治療最不建議？","options":["(A) 雷射燒除治療","(B) 陰莖根除手術","(C) 包皮環切手術","(D) 莫氏顯微圖像手術（Mohs micrographic surgery）"],"answer":1,"image":""},{"id":"md5-113-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"113年第1次第66題","year":113,"session":1,"number":66,"question":"下列有關轉移性腎細胞癌（metastatic renal cell carcinoma）危險因子中，何者不是International Metastatic Kidney Cancer Database Consortium的項目？","options":["(A) 體能狀態（performance status）","(B) 血液乳酸去氫酶（lactate dehydrogenase）","(C) 血色素高低（hemoglobin level）","(D) 血清鈣濃度（serum calcium level）"],"answer":1,"image":""},{"id":"md5-113-1-67","subject":"md5","topic":"泌尿-腫瘤","meta":"113年第1次第67題","year":113,"session":1,"number":67,"question":"下列有關攝護腺癌之敘述，何者錯誤？","options":["(A) 治療轉移性攝護腺癌，使用睪丸切除術或luteinizing hormone releasing hormone（LHRH）agonist效果相當","(B) 若病患有10年以上預期壽命且為早期攝護腺癌者，首先應該考慮給與賀爾蒙治療","(C) 經尿道攝護腺切除手術（transurethral resection of prostate）不是標準的攝護腺根除手術","(D) 治療轉移性攝護腺癌，使用LHRH agonist或antagonist效果相當"],"answer":1,"image":""},{"id":"md5-113-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"113年第1次第68題","year":113,"session":1,"number":68,"question":"下列有關良性前列腺增生（benign prostatic hyperplasia）的敘述，何者最不恰當？","options":["(A) 良性前列腺增生是男性最常見的良性腫瘤，其發病率與年齡有關","(B) 前列腺阻塞的症狀與年齡有關","(C) 良性前列腺增生的成因與遺傳無關","(D) 良性前列腺增生可能跟年老後體內雌激素（estrogen）濃度上升有關"],"answer":2,"image":""},{"id":"md5-113-1-69","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"113年第1次第69題","year":113,"session":1,"number":69,"question":"下列有關Peyronie's disease的敘述，何者錯誤？","options":["(A) 目前認為最可能是陰莖白膜創傷後癒合異常之疾病","(B) 會引起勃起疼痛及陰莖畸形","(C) 在高血壓族群的發生率較一般族群為高","(D) 注射Clostridial collagenase是非手術治療方式之一"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第69題一律給分 (原公告答案 C)"},{"id":"md5-113-1-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"113年第1次第70題","year":113,"session":1,"number":70,"question":"膀胱輸尿管逆流的病因可分為原發性（primary）或續發性（secondary），下列何者是原發性膀胱輸尿管逆流之原因？","options":["(A) 膀胱內壓過高","(B) 膀胱出口阻塞","(C) 膀胱輸尿管接合處（UVJ）病變","(D) 因脊神經管閉合不全（spinal dysraphism）引起的神經性膀胱"],"answer":2,"image":""},{"id":"md5-113-1-71","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"113年第1次第71題","year":113,"session":1,"number":71,"question":"對於有排尿障礙合併膀胱輸尿管尿液逆流的孩童，首先要做的是何種治療？","options":["(A) 直接進行輸尿管重建手術","(B) 直接給與輸尿管開口注射治療","(C) 先導尿以改善其下泌尿道排尿功能","(D) 直接進行膀胱擴大手術"],"answer":2,"image":""},{"id":"md5-113-1-72","subject":"md5","topic":"消化器外科","meta":"113年第1次第72題","year":113,"session":1,"number":72,"question":"肝臟鈍性創傷（blunt trauma）可能造成的傷害，下列何者最少見？","options":["(A) 肝臟撕裂傷（hepatic lacerations）","(B) 肝臟被膜下血腫（subcapsular hematomas）","(C) 肝臟實質性出血（intraparenchymal hemorrhage）","(D) 肝門靜脈栓塞（portal vein thrombosis）"],"answer":3,"image":""},{"id":"md5-113-1-73","subject":"md5","topic":"消化器外科","meta":"113年第1次第73題","year":113,"session":1,"number":73,"question":"下圖為巴德–吉亞利症候群（Budd-Chiari syndrome）病人的肝臟電腦斷層影像，此疾病是指肝臟何種結構發生阻塞？","options":["(A) 膽管（biliary duct）","(B) 門靜脈（portal vein）","(C) 肝動脈（hepatic artery）","(D) 肝靜脈（hepatic vein）"],"answer":3,"image":"md5-113-1-73.jpeg"},{"id":"md5-113-1-74","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第1次第74題","year":113,"session":1,"number":74,"question":"14歲女性病人主訴右肩痠痛約半年，肩部X光片如圖，最可能的診斷為何？","options":["(A) bone metastasis","(B) lymphoma","(C) osteogenic sarcoma","(D) chondrosarcoma"],"answer":2,"image":"md5-113-1-74.jpeg"},{"id":"md5-113-1-75","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"113年第1次第75題","year":113,"session":1,"number":75,"question":"有關接受手術後，易造成急性尿滯留（retention）的因素，下列何者最不適當？","options":["(A) 男性比女性易造成急性尿滯留","(B) 靜脈輸液過多，易造成急性尿滯留","(C) 脊椎或硬膜外麻醉，比全身麻醉易造成急性尿滯留","(D) 肛門直腸手術，比其他手術易造成急性尿滯留"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第75題一律給分 (原公告答案 A)"},{"id":"md5-113-1-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"113年第1次第76題","year":113,"session":1,"number":76,"question":"38歲女性自6米高處墜樓後送至醫學中心急診，檢傷時意識清楚，血壓87/48 mmHg，心跳142/min，經初步處置後發現骨盆骨折，超音波並未發現腹腔積液，下一步處置何者最適合？","options":["(A) 安排緊急血管攝影","(B) 會診外傷科醫師行剖腹探查手術","(C) 使用骨盆加壓帶固定（compressive pelvic maneuvers）","(D) 3小時後給與tranexamic acid"],"answer":0,"image":""},{"id":"md5-113-1-77","subject":"md5","topic":"外科-休克創傷傷口","meta":"113年第1次第77題","year":113,"session":1,"number":77,"question":"有關穿刺性肢體受傷的敘述，下列何者最正確？","options":["(A) 上肢比下肢較易發生血管受傷","(B) 神經受傷則有可能神經旁的血管也受傷，應立即照會血管相關外科醫師","(C) 肢體受傷處聽診發現有雜音，則有可能血管受傷，應立即照會血管相關外科醫師","(D) 肢體的傷口發現有血管在噴血，最好的止血方法是用器械夾住噴血血管"],"answer":2,"image":""},{"id":"md5-113-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"113年第1次第78題","year":113,"session":1,"number":78,"question":"82歲獨居男性，被里長發現仰躺在自家一樓的樓梯下，失去意識。救護車緊急將病人送至醫學中心的急診室。病人昏迷指數（Glasgow Coma Scale, GCS）E1M1V1，兩側瞳孔放大無光反射，脈搏62次／分，血壓172/106毫米汞柱，呼吸速率22次／分，血氧濃度88%。病人IC卡上註記DNR（do not resuscitate）。下列敘述何者最為合適？","options":["(A) 聯繫家屬，待家屬同意後，進行氣管內管插管","(B) 立即進行氣管內管插管","(C) 繼續觀察病人呼吸及血氧濃度變化，不需立即進行氣管內管插管","(D) 病人IC卡上註記DNR（do not resuscitate），不應進行氣管內管插管"],"answer":1,"image":""},{"id":"md5-113-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"113年第1次第79題","year":113,"session":1,"number":79,"question":"醫師有義務為病人守密，下列敘述何者最不恰當？","options":["(A) 醫師必須尊重病人隱私，除非病人或其代理人同意，或是法律有相關規定，才能將病人資訊告知第三者","(B) 為病人保密可能造成他人嚴重傷害時，醫師得未經病人同意而主動告知第三者某些關於病人的醫療資訊","(C) 當病人透露出想嚴重傷害他人的意向時，醫師應告知病人為保護可能的受害者，將不再為此訊息保密","(D) 在獲悉病人可能造成他人傷害時，為減少傷害應儘量告知病人身旁親友"],"answer":3,"image":""},{"id":"md5-113-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"113年第1次第80題","year":113,"session":1,"number":80,"question":"15歲男孩因排尿疼痛前來看診，醫師診察發現其尿道口有膿樣分泌物。經細菌抹片鑑定，診斷為淋球菌尿道炎。男孩承認曾有不安全性行為。由於是須通報之法定傳染病，建議進行HIV檢驗。男孩請求不要告知其家長。此時，下列何種處置最為恰當？","options":["(A) 不要通報，請其自費購買藥物服用","(B) 暫不通報，請其自費購買藥物服用，如HIV檢驗為陽性，就必須通報","(C) 由於其為未成年人，需有法定之監護人代為行使其權利，因此需告知其監護人","(D) 告知病人醫師有通報之義務，並且詳以解釋按時完整治療的重要"],"answer":3,"image":""},{"id":"md5-113-2-1","subject":"md5","topic":"外科-休克創傷傷口","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"有關敗血性休克（septic shock）的處置，下列何者最不適當？","options":["(A) 若病人有組織灌流不足的現象，應在前3小時內至少給與30 mL/kg的crystalloid液體","(B) 若給了適當輸液後平均動脈壓仍低於65 mmHg時，可以使用升壓劑","(C) 抗生素的給與必須等到細菌培養結果後再對菌下藥","(D) 升壓劑的使用以norepinephrine為第一選項"],"answer":2,"image":""},{"id":"md5-113-2-2","subject":"md5","topic":"胸腔外科","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"有關胸部外傷的緊急處置，下列何者正確？","options":["(A) 病人有開放性氣胸（open pneumothorax）時，應趕緊將傷口用凡士林紗布蓋住以避免漏氣，當病人有變化才考慮放置胸管","(B) 若傷口恰巧在放置胸管的位置（第五肋間與腋中線）時，可將傷口消毒後，經傷口放置胸管以減少對胸腔壁的傷害","(C) 張力性氣胸（tension pneumothorax）可能不會有頸靜脈怒張","(D) 放置胸管時，必須確定管子沿著肋骨下緣滑進，以免傷及血管或神經"],"answer":2,"image":""},{"id":"md5-113-2-3","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"手術後使用全中心靜脈營養（total parenteral nutrition, TPN）注射之病人，中心靜脈導管感染為常見之併發症，下列敘述何者最不適當？","options":["(A) 置放於股靜脈之導管感染率較高","(B) 為避免感染，中心靜脈導管放置後，須每週更換","(C) 導管相關之感染以葡萄球菌為主","(D) 使用TPN之病人若發燒時，若無其他原因，應考慮拔除導管並作細菌培養"],"answer":1,"image":""},{"id":"md5-113-2-4","subject":"md5","topic":"消化器外科","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"Klatskin tumor是指發生於下列何處之腫瘤？","options":["(A) 左右肝管匯合處","(B) 總膽管","(C) 膽囊管","(D) 十二指腸壺腹處"],"answer":0,"image":""},{"id":"md5-113-2-5","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"關於腹內感染之抗生素使用期間，下列敘述何者最恰當？","options":["(A) 外傷性腸穿孔於12小時內接受手術修補之病患，建議施打3天","(B) 未穿孔之急性闌尾炎接受闌尾切除手術後，建議連續施打3天抗生素","(C) 未穿孔之腸壞死，經切除腸道後，抗生素施打建議不超過24小時","(D) 穿孔性闌尾炎術後，抗生素須施打10天"],"answer":2,"image":""},{"id":"md5-113-2-6","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"有關使用鈣調磷酸酶抑制劑（calcineurin inhibitors）的副作用，下列敘述何者錯誤？","options":["(A) tacrolimus比cyclosporine較可能導致禿髮","(B) tacrolimus比cyclosporine較可能導致牙齦肥厚","(C) tacrolimus比cyclosporine有較高的神經毒性","(D) tacrolimus比cyclosporine有較高的移植後糖尿病發生率"],"answer":1,"image":""},{"id":"md5-113-2-7","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"下列何種微量元素缺乏，較少見於短腸症（short bowel syndrome）？","options":["(A) 鋅（Zinc）","(B) 銅（Copper）","(C) 錳（Mn）","(D) 維生素（vitamins）"],"answer":[1,2],"image":"","answer_note":"更正:第7題答Ｂ或Ｃ或BC者均給分"},{"id":"md5-113-2-8","subject":"md5","topic":"神經外科","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"因為神經影像檢查的進步，發現許多腦轉移的病例，其中最常見的腦轉移，其原發來源是：","options":["(A) 乳癌","(B) 黑色素癌","(C) 腎臟癌","(D) 肺癌"],"answer":3,"image":""},{"id":"md5-113-2-9","subject":"md5","topic":"神經外科","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"下列何種腦腫瘤的好發年齡（peak age）最小？","options":["(A) pineocytoma","(B) central neurocytoma","(C) ganglioglioma","(D) medulloblastoma"],"answer":3,"image":""},{"id":"md5-113-2-10","subject":"md5","topic":"神經外科","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"有關腦部海綿狀血管畸形（cerebral cavernous malformations），下列何者正確？","options":["(A) 診斷以血管攝影為主","(B) 以Spetzler-Martin grading system來評估腦部海綿狀血管畸形，分數越低越容易處理","(C) 一旦出血破裂常是致命的","(D) 可能產生的症狀包含癲癇"],"answer":3,"image":""},{"id":"md5-113-2-11","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"下列關於L5 root的敘述，何者正確？","options":["(A) 沿著L4椎莖（pedicle）下方，L4-5椎間盤之前出神經孔","(B) 感覺分布於大腿後外側到小腿、足踝","(C) 主管tibialis anterior力量，若有病變會有drop foot情況","(D) 若有病變，knee jerk reflex會減少"],"answer":2,"image":""},{"id":"md5-113-2-12","subject":"md5","topic":"神經外科","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"頭部外傷病人，昏迷指數13分，額葉腦出血10 c.c.，下列處置何者最不適當？","options":["(A) 預防性投與抗癲癇藥物","(B) 血中二氧化碳濃度（PCO2）維持在35～40 mmHg","(C) 開顱手術移除血塊，以降腦壓","(D) 維持收縮壓在100 mmHg以上"],"answer":2,"image":""},{"id":"md5-113-2-13","subject":"md5","topic":"神經外科","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"有關舟形頭（scaphocephaly）的敘述，下列何者正確？","options":["(A) 冠狀縫線（coronal suture）過早黏合","(B) 常合併眼球突出外觀","(C) 不常合併上頜骨發育不全（maxillary hypoplasia）","(D) 常合併水腦症"],"answer":2,"image":""},{"id":"md5-113-2-14","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"手指遠端伸直肌腱（extensor tendon of distal interphalanges）斷裂會造成何種情形？","options":["(A) mallet finger","(B) swan-neck deformity","(C) boutonnière deformity","(D) gamekeeper deformity"],"answer":0,"image":""},{"id":"md5-113-2-15","subject":"md5","topic":"整形重建外科","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"橈動脈前臂皮瓣（radial forearm flap）屬於Nahai-Mathes classification中對筋膜皮瓣（fasciocutaneous flap）的那一項分類？","options":["(A) 第A類","(B) 第B類","(C) 第C類","(D) 第D類"],"answer":1,"image":""},{"id":"md5-113-2-16","subject":"md5","topic":"整形重建外科","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"60歲郭先生，有抽菸及嚼食檳榔習慣已維持近30年，近3個月來因舌頭右側有一3 cm潰瘍性傷口無法癒合，到醫院求診，頸部淋巴檢查發現，在同側anterior belly of the digastric muscle, hyoid bone, and midline之間區域有一2 cm × 2 cm疑似淋巴結腫大。此腫塊位於頸部淋巴結之那一區域？","options":["(A) level IA","(B) level IIA","(C) level IIB","(D) level III"],"answer":0,"image":""},{"id":"md5-113-2-17","subject":"md5","topic":"整形重建外科","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"承上題，病理切片結果及相關影像學檢查顯示，證實為舌部鱗狀上皮細胞癌（squamous cell carcinoma），病灶大小為3 cm，厚度2 cm且侵犯深度為11 mm，發現在同側局部淋巴結（regional lymph node）有3顆轉移約為2 cm並且無囊外淋巴結延伸（extranodal extension），無遠端器官轉移。根據AJCC th 8指引，郭先生目前癌症分期為下列何者？","options":["(A) T3N2aM0","(B) T3N2cM0","(C) T2N2cM0","(D) T3N2bM0"],"answer":3,"image":""},{"id":"md5-113-2-18","subject":"md5","topic":"整形重建外科","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"蘇老先生四年前中風後即長期臥床，近日家屬發現其臀部有四公分傷口，經整形外科醫師診斷為壓瘡（pressure sore），建議手術治療。術中發現傷口壞死範圍深及骨頭，此褥瘡的深度分級與最好的重建方法各為何？","options":["(A) Stage II；清創後直接縫合是簡單可行的方法","(B) Stage III；清創後植皮覆蓋傷口","(C) Stage IV；清創後局部臀大肌皮瓣重建術","(D) Stage V；清創後顯微皮瓣重建術"],"answer":2,"image":""},{"id":"md5-113-2-19","subject":"md5","topic":"心臟血管外科","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"關於二尖瓣閉鎖不全，下列敘述何者錯誤？","options":["(A) 可能原因包含myxomatous degeneration、rheumatic heart disease、infective endocarditis等","(B) 聽診聽到的心雜音為pan-diastolic murmur","(C) 慢性的二尖瓣閉鎖不全，左心室會透過代償進行重塑，因此病人可能會沒有症狀","(D) 胸部X光可能發現病人有肺水腫及左心房擴大"],"answer":1,"image":""},{"id":"md5-113-2-20","subject":"md5","topic":"心臟血管外科","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"使用雙側內乳動脈（internal mammary artery）做冠狀動脈繞道手術已被證實可以增加存活率，但某些病人可能不適合，下列那一個病人最適合使用雙側內乳動脈進行繞道手術？","options":["(A) 60歲，高血壓，慢性肺阻塞疾病（COPD）使用吸入型支氣管擴張劑","(B) 2 70歲，糖化血色素（HbA1c）為6.0%，Body Mass Index（BMI）=35，eGFR=60 mL/min/1.73m","(C) 70歲，末期腎病變，雙手血壓收縮壓相差50 mmHg","(D) 90歲，糖化血色素（HbA1c）為8.0%，總膽固醇=200 mg/dL，低密度膽固醇=100 mg/dL"],"answer":0,"image":""},{"id":"md5-113-2-21","subject":"md5","topic":"心臟血管外科","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"下列何者為急性肢體缺血（acute ischemic limb）最常見之原因？","options":["(A) 頸動脈阻塞","(B) 先天性之血管異常","(C) 心臟產生之血栓","(D) 小洞性腦梗塞（lacunar infarction）"],"answer":2,"image":""},{"id":"md5-113-2-22","subject":"md5","topic":"心臟血管外科","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"腹主動脈瘤（infra-renal abdominal aortic aneurysm）開刀之適應症，下列何者最不適當？","options":["(A) 男性，過去一年腹主動脈瘤的直徑從4公分擴大到4.5公分","(B) 女性，有症狀、直徑5公分的腹主動脈瘤","(C) 男性，沒有症狀、直徑5.5公分的腹主動脈瘤","(D) 女性，直徑4.5公分的腹主動脈瘤且手術風險低"],"answer":0,"image":""},{"id":"md5-113-2-23","subject":"md5","topic":"心臟血管外科","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"1個月大女嬰，出生後診斷為完全型之心內膜墊異常（complete form, atrioventricular defect），下列敘述何者錯誤？","options":["(A) 此類病患會很快心臟衰竭，需儘早手術，對此女嬰可建議肺動脈窄縮術（pulmonary artery banding）","(B) 此病人之心臟傳導系統（conduction system）及房室結（atrioventricular node）位置與單純性之大動脈轉位（simple transposition of great arteries）一樣","(C) 此類病患與單純心房及心室中隔缺損（simple atrial defect and ventricular defect）不同，在全矯正之後，仍有可能會有二尖瓣或三尖瓣之問題","(D) 其瓣膜之異常主要是根據Rastelli classification分類，主要分A、B、C三型態"],"answer":1,"image":""},{"id":"md5-113-2-24","subject":"md5","topic":"心臟血管外科","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"在一般開心手術中，二尖瓣置換及三尖瓣手術中，心肺機體外循環建立過程，那一大血管比較少放置引流管路（cannula）？","options":["(A) 主動脈（aorta）","(B) 上腔靜腔（superior vena cava）","(C) 下腔靜脈（inferior vena cava）","(D) 肺動脈（pulmonary artery）"],"answer":3,"image":""},{"id":"md5-113-2-25","subject":"md5","topic":"胸腔外科","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"關於食道癌之敘述，下列何者正確？","options":["(A) 在美國，食道腺癌（adenocarcinoma）之近年發生率已高於食道鱗狀上皮細胞癌（squamous cell carcinoma）","(B) 食道鱗狀上皮細胞癌（squamous cell carcinoma）與巴瑞特氏食道炎（Barrett esophagus）有高度相關","(C) 食道癌最常見症狀為聲音沙啞（hoarseness）","(D) 在臺灣，喝酒、抽菸與食道腺癌（adenocarcinoma）有高度相關"],"answer":0,"image":""},{"id":"md5-113-2-26","subject":"md5","topic":"胸腔外科","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"關於食道旁疝氣（paraesophageal hernia）之敘述，下列何者正確？","options":["(A) 病人除非發生胃扭轉壞死，否則只要藥物控制即可","(B) 對於年紀大於60歲，無症狀之病人，以手術治療為主","(C) 病人發生吞嚥困難症狀比胃食道逆流症狀多","(D) 手術治療時，因胃賁門結構破壞，除將食道橫膈修補外，不需經食道壓力檢測（manometry），皆需實施胃抗逆流手術（Ｎissen fundoplication），減少胃食道逆流症狀（GERD）"],"answer":2,"image":""},{"id":"md5-113-2-27","subject":"md5","topic":"胸腔外科","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"關於乳糜胸（chylothorax）之敘述，下列何者錯誤？","options":["(A) 乳糜內含高濃度的三酸甘油脂（triglyceride）","(B) 常見於胸部淋巴結廓清術後","(C) 一開始可以保守治療，給與長鏈三酸甘油脂（long-chain triglyceride）飲食","(D) 肺部腫瘤亦可能引起乳糜胸"],"answer":2,"image":""},{"id":"md5-113-2-28","subject":"md5","topic":"胸腔外科","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"下列何種黴菌感染最常造成含有黴菌球（fungus ball）之空腔？","options":["(A) 麴菌（aspergillosis）","(B) 組織胞漿菌（histoplasmosis）","(C) 球黴菌（coccidioidomycosis）","(D) 隱孢子球菌（cryptococcosis）"],"answer":0,"image":""},{"id":"md5-113-2-29","subject":"md5","topic":"胸腔外科","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"有關thymoma，下列敘述何者錯誤？","options":["(A) 是兒童最常見的縱隔腔腫瘤","(B) 應儘量採取外科手術切除治療","(C) 可能會合併myasthenia gravis","(D) 無法立即手術切除時，以cisplatin為主之化學治療通常效果良好"],"answer":0,"image":""},{"id":"md5-113-2-30","subject":"md5","topic":"胸腔外科","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"有關縱隔腔感染，下列敘述何者錯誤？","options":["(A) Pel-Ebstein fever是典型症狀之一","(B) 容易沿結締組織擴展為大範圍嚴重感染","(C) 主要以手術引流及抗生素治療","(D) 食道穿孔易引發好氧菌、厭氧菌同步感染，最為致命"],"answer":0,"image":""},{"id":"md5-113-2-31","subject":"md5","topic":"消化器外科","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"下列關於專有名詞及其敘述，何者錯誤？","options":["(A) Whipple operation為胰十二指腸切除手術（pancreaticoduodenectomy）的統稱","(B) Klatskin tumors是指發生於肝門部位的膽道惡性腫瘤，臨床上有4種主要類型","(C) Bismuth-Corlette classification將choledochal cyst區分為5種類型","(D) Borrmann classification是用來描述胃癌腫瘤的型態，有4種類型"],"answer":2,"image":""},{"id":"md5-113-2-32","subject":"md5","topic":"消化器外科","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"有關幽門螺旋桿菌的敘述，下列何者正確？","options":["(A) 其宿主（reservoir）主要是包括人類的哺乳動物","(B) 急性感染造成非侵蝕性全胃胃炎，之後往往發展成慢性胃炎","(C) 初期炎症反應主要是T及B淋巴球的聚集","(D) 尿素分解酵素（urease）產生二氧化碳及氨（ammonia）有助幽門桿菌存活，並藉鞭毛作用侵入表皮細胞中"],"answer":1,"image":""},{"id":"md5-113-2-33","subject":"md5","topic":"消化器外科","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"有關急性膽管炎的敘述，下列何者錯誤？","options":["(A) 膽道污染細菌不合併膽道阻塞通常不會產生膽管炎","(B) 膽結石引起的膽管炎好發於年紀大的女性","(C) 發燒、上腹痛以及黃疸是典型症狀，又稱Reynold's triad","(D) 膽道留置導管患者發生無黃疸性膽管炎之危險性比較高"],"answer":2,"image":""},{"id":"md5-113-2-34","subject":"md5","topic":"消化器外科","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"有關胰臟內分泌腫瘤（pancreatic endocrine tumors, PET）的敘述，下列何者錯誤？","options":["(A) 大部分胰臟內分泌腫瘤潛在性具有不受控制的生長現象與轉移性，屬於惡性腫瘤，但組織學上並無法用來預測其生物行為（biologic behavior）","(B) 第一型多發性內分泌腺瘤（multiple endocrine neoplasm type 1, MEN-1）之病人，其胰臟內分泌腫瘤不容易達到根治性切除，但即使有轉移其預後也比胰臟管腺癌佳","(C) 嗜鉻粒蛋白A（chromogranin A, CgA）有助於轉移性胰臟內分泌腫瘤的診斷，若術後影像學檢查無明顯轉移病灶而CgA值仍高，是進行輔助性化學治療的參考，可以提高存活率","(D) 轉移性胰臟內分泌腫瘤視情況可採多方位的治療，目前局部消融治療以射頻消融（radiofrequency ablation, RFA）之類治療可輔助原發及轉移腫瘤的切除，協助病人接受姑息手術（palliative surgery）並改善症狀及存活"],"answer":2,"image":""},{"id":"md5-113-2-35","subject":"md5","topic":"消化器外科","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"有關化膿性肝膿腫（pyogenic liver abscess）的敘述，下列何者錯誤？","options":["(A) 較常發生於右側肝臟，可以是單發性或多發性，最常見菌種為革蘭氏陰性菌","(B) 電腦斷層掃描與磁振造影是敏感度高的診斷及治療儀器","(C) 經驗性抗生素治療必須涵蓋革蘭氏陰性和厭氧性細菌，經皮細針抽吸及培養（percutaneous needle aspiration and culture）提供正確使用指引，經靜脈給與抗生素至少需使用8週","(D) 由於化膿性肝膿腫相當粘稠，經皮放置導管僅對少數病患有幫助，多數病患只要藥物治療就可以改善"],"answer":1,"image":""},{"id":"md5-113-2-36","subject":"md5","topic":"消化器外科","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"有關小腸腫瘤的敘述，下列何者正確？","options":["(A) 小腸原發性惡性腫瘤很少，其中以腺癌最多，最常見於十二指腸，而CEA濃度通常只有在發生肝臟轉移時會升高","(B) 小腸類癌（carcinoid）表現比闌尾的類癌具侵襲性，約25～50%類癌發生肝臟轉移，產生腹瀉、潮紅、高血壓、心跳過速之類癌症候群（carcinoid syndrome）","(C) 原發性小腸淋巴瘤主要發生於空腸，最常見症狀為完全腸阻塞，少部分病患以腸穿孔表現","(D) 小腸的胃腸道基質瘤（GIST）發生率僅次於胃，常見於空腸而很少有淋巴結轉移，節段切除（segmental resection）是主要的手術方式"],"answer":0,"image":""},{"id":"md5-113-2-37","subject":"md5","topic":"消化器外科","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"針對胰臟漿液性囊狀腫瘤（serous cystadenomas），下列何者較適宜建議手術？","options":["(A) 有症狀","(B) 腫瘤大小超過2公分","(C) 胰管（main duct）大於0.5公分","(D) 位置在胰臟體部或尾部"],"answer":0,"image":""},{"id":"md5-113-2-38","subject":"md5","topic":"消化器外科","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"下列有關胃切除後併發症之敘述，何者最恰當？","options":["(A) Billroth I比II手術方式更易發生傾食症侯群（dumping syndrome）","(B) Billroth I比II手術方式更易發生鹼性逆流胃炎（alkaline reflux gastritis）","(C) 輸出環症候群（efferent loop syndrome）比輸入環症候群（afferent loop syndrome）更易造成膽汁嘔吐物或高胰澱粉酶現象","(D) 全胃切除需要補充維生素B12"],"answer":3,"image":""},{"id":"md5-113-2-39","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"一位55歲女性洗腎已10年，副甲狀腺亢進無法以藥物適當控制，近日抽血測得parathyroid hormone（PTH）1800 pg/mL，接受total parathyroidectomy and autotransplantation手術，下列何者術後較不會改善？","options":["(A) bone density","(B) hemoglobin levels","(C) urine output","(D) long-term survival"],"answer":2,"image":""},{"id":"md5-113-2-40","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"一位35歲男性，健檢時發現右側甲狀腺有一3公分實心（solid）結節，細針穿刺細胞學檢查依Bethesda criteria分類，診斷為suspicious for malignancy，手術接受甲狀腺右葉全切除後，病理報告診斷為noninvasive follicular thyroid neoplasm with papillary-like nuclear features（NIFTP），下列敘述何者最適當？","options":["(A) 細胞學型態接近Hürthle cell neoplasm","(B) 病理學型態為encapsulated follicular variant of papillary thyroid cancer","(C) 又稱為lateral aberrant thyroid","(D) 後續處置建議高劑量放射性碘131治療"],"answer":1,"image":""},{"id":"md5-113-2-41","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"83歲女性病患這兩年來經常在早晨餐前暈倒，進食後症狀可獲緩解。這次暈倒在路旁後被送至急診室檢查結 ++2+ 果：Na 136 mEq/L，K 2.9 mEq/L，Ca 8.6 mg/dL，blood sugar 34 mg/dL，insulin: 16.4 μIU/mL，C-peptide: 3.29 ng/mL，free T4: 1.19 ng/dL，cortisol: 13.77 μg/dL，ACTH: 19.4 pg/dL，下列敘述何者最不適當？","options":["(A) 應儘速輸注50 mL 50% glucose","(B) 病患甦醒後應安排contrast-enhanced abdominal CT以確定腫瘤位置","(C) 若經電腦斷層掃描及核磁共振掃描胰臟未發現腫瘤，可安排selective arterial calcium stimulation test","(D) 若腫瘤位於胰臟尾部，應切除85%胰臟"],"answer":3,"image":""},{"id":"md5-113-2-42","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"下列何種乳癌病人不僅應執行前哨淋巴切片（sentinel lymph node biopsy），還應做腋下淋巴廓清（axillary lymph node dissection）？","options":["(A) 侵襲性乳癌在全乳切除後發現有1顆前哨淋巴有癌轉移","(B) 原位乳癌（ductal carcinoma in situ）在全乳切除後發現前哨淋巴無癌轉移","(C) 2至5公分的侵襲性乳癌在乳房保留手術後發現前哨淋巴無癌轉移","(D) 接受乳房保留手術且手術發現有2顆前哨淋巴有癌轉移，術後預計接受全乳放射線治療及藥物治療之病人"],"answer":0,"image":""},{"id":"md5-113-2-43","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"在沒有乳癌相關家族史、無過去病史，也未出現任何症狀的婦女中，衛生福利部國民健康署推動之乳癌攝影篩檢是從幾歲開始？","options":["(A) 35歲","(B) 40歲","(C) 45歲","(D) 50歲"],"answer":2,"image":""},{"id":"md5-113-2-44","subject":"md5","topic":"內分泌與乳房外科","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"一名59歲婦女診斷乳癌並接受乳房部分切除併前哨淋巴結取樣，病理報告顯示為侵襲性乳管癌（invasive ductal carcinoma），腫瘤大小2公分，淋巴結無轉移，免疫染色為雌激素受體陽性（ER：positive）、黃體素受體陰性（PR：negative）、人類表皮生長因子受體2（HER2/neu）陽性，則建議接受下列那些治療組合？ ①化學藥物 ②抗荷爾蒙藥物 ③放射線治療 ④標靶藥物","options":["(A) 僅①②③","(B) 僅②③④","(C) 僅①③④","(D) ①②③④"],"answer":3,"image":""},{"id":"md5-113-2-45","subject":"md5","topic":"小兒外科","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"一位3個月大嬰兒因腹脹求診，據母親描述其過去約7～8天以上無解便，但尿布上常有少許滲便，經腹部Ｘ 光及下消化道攝影檢查後，其結果如圖所示，在確切診斷與治療前，下列何項後續處置對本病患較無幫助？","options":["(A) 完成相關檢查後，留置肛管（rectal tube）或直腸灌洗（rectal irrigation）","(B) 進一步腹部電腦斷層檢查","(C) 直腸切片","(D) 下消化道攝影後隔日再加照一張如附圖左圖範圍之腹部Ｘ光"],"answer":1,"image":"md5-113-2-45.jpeg"},{"id":"md5-113-2-46","subject":"md5","topic":"小兒外科","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"下列有關膽道閉鎖（biliary atresia），何者敘述正確？","options":["(A) 超音波可以看到肝內膽管擴張","(B) 內視鏡逆行性膽胰管造影術（ERCP）是目前最常用的確診工具","(C) 鑑別診斷需排除新生兒肝炎","(D) 膽道閉鎖經葛西氏（Kasai）手術後，九成以上病人皆可以治癒"],"answer":2,"image":""},{"id":"md5-113-2-47","subject":"md5","topic":"小兒外科","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"橫紋肌肉瘤（rhabdomyosarcoma）為一源自間葉組織（mesenchymal tissues）之原始軟組織瘤，有關橫紋肌肉瘤，下列敘述何者錯誤？","options":["(A) 可能發生於任何位置，最常見於頭頸部，其次為四肢和軀幹","(B) 確定診斷需在磁振造影或電腦斷層及骨髓穿刺檢查後，藉由切開性或切除性病理切片證實","(C) 以手術完全切除腫瘤為主要治療方法，若無法完全切除，可先進行化學治療或放射線治療","(D) 預後與腫瘤原發部位有關，原發於眼眶及非腦膜旁之頭頸部者，預後較差"],"answer":3,"image":""},{"id":"md5-113-2-48","subject":"md5","topic":"胸腔外科","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"Haller index或稱凹陷指數，常用於漏斗胸（pectus excavatum）的嚴重度評估，是由Dr. Haller等人在1987年所提出來的方法，圖中A為白色橫向雙箭頭線長度；B、D分別為左右兩側白色縱向雙箭頭線長度；C為中間黑色縱向雙箭頭線長度；E為中間白色縱向雙箭頭線長度，則Haller index為何？","options":["(A) A/C","(B) (B+D)/2C","(C) C/E","(D) (B+D)/A"],"answer":0,"image":"md5-113-2-48.jpeg"},{"id":"md5-113-2-49","subject":"md5","topic":"胸腔外科","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"承上題，最適當的手術治療時機為：","options":["(A) 2～5歲","(B) 6～9歲","(C) 10～14歲","(D) 大於18歲"],"answer":2,"image":""},{"id":"md5-113-2-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"有關大腸腸扭轉（volvulus），下列敘述何者正確？","options":["(A) 好發於橫結腸","(B) 有慢性便秘之年輕女性為好發族群，攝食較多的高纖飲食有助於預防其發生","(C) 未固定於後腹腔的結腸，且有較長的腸繫膜較易發生腸扭轉","(D) 在乙狀結腸腸扭轉中，腹部X光攝影可能有琴鍵徵象（keyboard sign）"],"answer":2,"image":""},{"id":"md5-113-2-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"113年第2次第51題","year":113,"session":2,"number":51,"question":"腎功能不佳的病患接受大腸鏡檢查前的清腸準備藥物，下列何者最不適合使用？","options":["(A) bisacodyl（ducolax）","(B) polyethylene glycerol","(C) enema","(D) magnesium citrate solution"],"answer":[1,3],"image":"","answer_note":"更正:第51題答Ｂ或Ｄ或BD者均給分"},{"id":"md5-113-2-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"113年第2次第52題","year":113,"session":2,"number":52,"question":"大腸癌術後病理報告顯示癌細胞侵犯至腸壁肌肉層（muscularis propria），但是未穿越過肌肉層，此時TNM Stage的T stage為何？","options":["(A) T1","(B) T2","(C) T3","(D) T4"],"answer":1,"image":""},{"id":"md5-113-2-53","subject":"md5","topic":"消化器外科","meta":"113年第2次第53題","year":113,"session":2,"number":53,"question":"儘管微創手術（minimally invasive surgery, MIS）有許多優點，相較於傳統外科手術，微創手術仍有一些具體的挑戰。下列敘述何者錯誤？","options":["(A) 將腹腔鏡器械置於外科醫生的手和目標組織之間會削弱觸覺反饋","(B) 傳統外科手術，醫生可以依靠手部感覺了解組織的質地和彈性，以評估組織的病理特徵；但在腹腔鏡手術中，外科醫生無法通過器械回饋了解這些特徵","(C) 當通過微創手術切口進行手術時，對手術器械的運動範圍的約束相對較多","(D) 進行腹腔鏡微創手術將二氧化碳導入腹腔維持12-15mmHg腹腔壓力，分隔組織結構以保持腹腔內正壓和工作空間"],"answer":1,"image":""},{"id":"md5-113-2-54","subject":"md5","topic":"消化器外科","meta":"113年第2次第54題","year":113,"session":2,"number":54,"question":"微創手術（minimally invasive surgery）的發展改變外科手術的方式，關於微創腹腔鏡胰尾切除術（laparoscopic distal pancreatectomy）、腹腔鏡和機器人胰十二指腸切除術（laparoscopic and robotic pancreaticoduodenectomy），下列敘述何者錯誤？","options":["(A) 腹腔鏡及傳統開腹胰十二指腸切除手術的比較分析發現：兩者的短期結果及併發症相近","(B) 胰十二指腸切除術是最複雜的腹腔內手術之一，要進行腹腔鏡微創手術之醫師需要肝胰膽手術和腹腔鏡手術方法的深度培訓","(C) 腹腔鏡分期術（laparoscopic staging surgery）可以發現影像檢查未發現的轉移性或局部晚期胰臟癌，減少不必要的剖腹手術","(D) 腹腔鏡胰尾切除術（laparoscopic distal pancreatectomy）對胰臟體部尾部癌的長期追蹤療效優於傳統手術"],"answer":3,"image":""},{"id":"md5-113-2-55","subject":"md5","topic":"小兒外科","meta":"113年第2次第55題","year":113,"session":2,"number":55,"question":"關於兒童的腹腔鏡手術（pediatric laparoscopy）之敘述，下列何者錯誤？","options":["(A) 腹腔鏡手術在嬰兒及幼童需使用較短（15～20 cm）且小的器械","(B) 因兒童的腹腔較小，因此使用較小的（5 mm）鏡頭亦可以提供足夠光源","(C) 氣腹壓力維持在12毫米汞柱壓力有利於手術進行","(D) 兒童的深層靜脈栓塞（DVT）發生機會低，不需要給與預防性血栓藥物"],"answer":2,"image":""},{"id":"md5-113-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第2次第56題","year":113,"session":2,"number":56,"question":"下列關於轉移性骨癌（bone metastasis）的敘述，何者最適當？","options":["(A) 常見來自大腸或子宮頸癌","(B) 最常侵犯骨盆","(C) 乳癌常產生蝕骨性病灶（osteolytic lesions）","(D) 攝護腺癌常產生成骨性轉移病灶（osteoblastic lesions）"],"answer":[2,3],"image":"","answer_note":"更正:第56題答Ｃ或Ｄ或CD者均給分"},{"id":"md5-113-2-57","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第2次第57題","year":113,"session":2,"number":57,"question":"有關頸椎損傷（cervical spine injury），下列敘述何者最適當？","options":["(A) 上頸椎損傷較下頸椎損傷容易合併脊髓損傷（spinal cord injury）","(B) 最常見的原因是車禍，緊急的治療原則：先評估A（airway）、B（breathing）、C（circulation）","(C) 中央脊髓症候群（central cord syndrome）好發於年輕人因車禍造成頸椎嚴重過度屈曲（hyperflexion），且神經功能恢復的預後並不理想","(D) 後柱脊髓症候群（posterior cord syndrome）是最常見的不完全脊髓損傷，通常發生於頸椎的伸張損傷（extension type injury）"],"answer":1,"image":""},{"id":"md5-113-2-58","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"113年第2次第58題","year":113,"session":2,"number":58,"question":"28歲橄欖球選手在比賽中發生膝關節變形脫臼，抬上擔架後膝關節就自動復位，下列敘述與處置何者最不適當？","options":["(A) 可能會合併十字韌帶、內外側副韌帶斷裂及半月板破裂，應該要安排磁振造影檢查","(B) 要注意急性血管斷裂受傷的風險","(C) 觸診dorsalis pedis及posterior tibial動脈，如果搏動正常可以排除血管受損的風險","(D) 可能造成unhappy triad，受傷的部位包括：前十字韌帶、內側副韌帶和內側半月板"],"answer":2,"image":""},{"id":"md5-113-2-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"113年第2次第59題","year":113,"session":2,"number":59,"question":"有關於生物性組織（biologic tissue）之黏彈性（viscoelasticity）特性敘述，下列何者最不適當？","options":["(A) 受力時會產生變形（deformation），受力解除後會回到原形狀（original shape）","(B) 伸展運動（stretching exercise）即利用此原理","(C) 特性包括蠕變（creep）及應力鬆弛（stress relaxation）","(D) 與受力速率相關（loading rate dependence）"],"answer":0,"image":""},{"id":"md5-113-2-60","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"113年第2次第60題","year":113,"session":2,"number":60,"question":"下列那一種骨折為一側的皮質骨斷裂，並造成另一側的皮質骨塑形變形（plastic deformation）？","options":["(A) torus（buckle）fracture","(B) greenstick fracture","(C) spiral fracture","(D) transverse fracture"],"answer":1,"image":""},{"id":"md5-113-2-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第2次第61題","year":113,"session":2,"number":61,"question":"下列那一條肌腱不在腕隧道（carpal tunnel）中？","options":["(A) flexor pollicis longus","(B) flexor digitorum superficialis of index finger","(C) flexor digitorum profundus of ring finger","(D) flexor carpi ulnaris"],"answer":3,"image":""},{"id":"md5-113-2-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"113年第2次第62題","year":113,"session":2,"number":62,"question":"有關先天性脊椎側彎（congenital scoliosis），下列敘述何者最不適當？","options":["(A) 發生原因主要是脊椎的形成失敗（failure of formation）或分節失敗（failure of segmentation）所造成","(B) 因為脊椎可屈性較大，故以背架治療可以得到良好的效果","(C) 病人有可能合併先天性心臟、腎臟及顱內缺陷","(D) 小於10歲的病人，只做後側骨融合手術時，可能會造成曲軸現象（crankshaft phenomenon）"],"answer":1,"image":""},{"id":"md5-113-2-63","subject":"md5","topic":"骨科-關節重建","meta":"113年第2次第63題","year":113,"session":2,"number":63,"question":"下列發生骨壞死的部位，何者最不常見？","options":["(A) 舟狀骨（scaphoid bone）","(B) 股骨頭（femoral head）","(C) 肱骨頭（humeral head）","(D) 跟骨（calcaneus）"],"answer":3,"image":""},{"id":"md5-113-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"113年第2次第64題","year":113,"session":2,"number":64,"question":"下列關於尿酸結石的敘述何者錯誤？","options":["(A) 因大多為放射線透光結石，在KUB檢查是不容易看到的","(B) 大多數尿酸結石的病人合併有高尿酸血症（hyperuricemia）","(C) 鹼化尿液有助於溶解尿酸結石","(D) 多喝水增加每日尿液排出量，可以減少尿酸結石的形成"],"answer":1,"image":""},{"id":"md5-113-2-65","subject":"md5","topic":"泌尿-腫瘤","meta":"113年第2次第65題","year":113,"session":2,"number":65,"question":"下列有關腎細胞癌（renal cell carcinoma）之敘述，何者錯誤？","options":["(A) 與第三對染色體（chromosome 3p）變異有關","(B) 洗腎病人罹患腎水泡者發生腎細胞癌的風險較低","(C) 最大的風險因子為抽菸","(D) Von Hippel-Lindau gene變異與腎細胞癌的發生有關"],"answer":1,"image":""},{"id":"md5-113-2-66","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"113年第2次第66題","year":113,"session":2,"number":66,"question":"用攝護腺特定抗原（PSA）檢驗輔助攝護腺癌診斷，下列何者較不會影響其數值？","options":["(A) 導尿管置放","(B) 泌尿道感染","(C) 長期使用5α-reductase inhibitor（5-ARI）","(D) 前晚食用高脂肪類食物"],"answer":3,"image":""},{"id":"md5-113-2-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"113年第2次第67題","year":113,"session":2,"number":67,"question":"下列何種治療最常用被用來處理急迫性尿失禁（urgent incontinence）？","options":["(A) 甲型交感神經阻斷劑（α-adrenoceptor blocker）","(B) 橫紋肌鬆弛劑","(C) 尿道懸吊手術","(D) 抗膽鹼藥物（antimuscarinic agents）"],"answer":3,"image":""},{"id":"md5-113-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"113年第2次第68題","year":113,"session":2,"number":68,"question":"經尿道前列腺切除手術時，由尿道口起依序會看到那些組織？","options":["(A) 尿道外括約肌→精阜→肥大的前列腺組織→膀胱頸","(B) 精阜→肥大的前列腺組織→尿道外括約肌→尿道內括約肌","(C) 陰莖段尿道→肥大的前列腺組織→尿道外括約肌→尿道內括約肌","(D) 陰莖段尿道→尿道外括約肌→膀胱頸→肥大的前列腺組織"],"answer":0,"image":""},{"id":"md5-113-2-69","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"113年第2次第69題","year":113,"session":2,"number":69,"question":"一位36歲男性因不孕症求診，其精液分析發現精子濃度、活動力、正常型態比例都低於正常值。血中睪固酮（testosterone）濃度偏低，同時亦有性慾降低及勃起功能變差的問題。為了同時改善其生殖及性功能方面的問題，下列何種治療最不建議？","options":["(A) 注射緩釋型睪固酮製劑（testosterone depot）以提升血中睪固酮濃度","(B) 口服selective estrogen receptor modulators（SERMs）製劑治療以提升血中睪固酮濃度","(C) 口服芳香酶抑制劑（aromatase inhibitor）治療以提升血中睪固酮濃度","(D) 注射人類絨毛膜性促素（human chorionic gonadotropin）以提升血中睪固酮濃度"],"answer":0,"image":""},{"id":"md5-113-2-70","subject":"md5","topic":"外科-休克創傷傷口","meta":"113年第2次第70題","year":113,"session":2,"number":70,"question":"下列有關泌尿道外傷之診斷和處理，何者最不適當？","options":["(A) 要為男性病患置放導尿管時應先檢查尿道口有無流血","(B) 應檢查腹部和生殖器是否有挫傷或皮下血腫的現象，若有時則可能合併後腹腔和骨盆腔內有深部損傷","(C) 患者若是有危及生命的傷害且血壓不穩定瀕臨休克時，應立刻接受進一步詳細的影像學檢查，再予急救","(D) 在急診室看到的所有外傷個案中，約有10%會有若干程度的泌尿生殖系統損傷"],"answer":2,"image":""},{"id":"md5-113-2-71","subject":"md5","topic":"泌尿-腫瘤","meta":"113年第2次第71題","year":113,"session":2,"number":71,"question":"一位50歲男性因攝護腺癌接受攝護腺根除手術（radical prostatectomy），為保留其勃起功能，醫師採用神經保留攝護腺根除手術時，其保留的神經是：","options":["(A) 閉孔神經（obturator nerve）","(B) 腹下神經（hypogastric nerve）","(C) 陰莖海綿體神經（cavernosal nerve）","(D) 會陰神經（pudendal nerve）"],"answer":2,"image":""},{"id":"md5-113-2-72","subject":"md5","topic":"消化器外科","meta":"113年第2次第72題","year":113,"session":2,"number":72,"question":"下列何者為浸潤性肝癌（infiltrative type hepatocellular carcinoma）最常合併之影像發現？","options":["(A) 門靜脈腫瘤栓塞（portal vein tumor thrombosis）","(B) 腫瘤破裂合併急性腹腔出血（tumor rupture with acute hemoperitoneum）","(C) 肝動脈假性動脈瘤（hepatic artery pseudoaneurysm）","(D) 主動脈旁淋巴結轉移（para-aortic lymph nodes metastases）"],"answer":0,"image":""},{"id":"md5-113-2-73","subject":"md5","topic":"消化器外科","meta":"113年第2次第73題","year":113,"session":2,"number":73,"question":"46歲女性病人主訴於月經過後下腹部疼痛，尤其右下腹部疼痛約3天，身體診察右下腹部有壓痛現象，右下腹部超音波檢查如圖，最可能的診斷為何？","options":["(A) 子宮發炎（uterus inflammation）","(B) 卵巢膿瘍（ovary abscess）","(C) 闌尾炎（appendicitis）","(D) Crohn氏症（Crohn's disease）"],"answer":2,"image":"md5-113-2-73.jpeg"},{"id":"md5-113-2-74","subject":"md5","topic":"骨科-關節重建","meta":"113年第2次第74題","year":113,"session":2,"number":74,"question":"57歲女性雙手多處關節腫痛，雙手X光檢查如附圖，最可能的診斷為何？","options":["(A) gouty arthritis","(B) osteoarthritis","(C) septic arthritis","(D) rheumatoid arthritis"],"answer":3,"image":"md5-113-2-74.jpeg"},{"id":"md5-113-2-75","subject":"md5","topic":"神經外科","meta":"113年第2次第75題","year":113,"session":2,"number":75,"question":"60歲男性因機車車禍被送至急診，病人意識模糊、大量嘔吐，身體檢查發現雙眼眶周圍瘀青（raccoon eye）且耳朵流出澄清液體，心跳110/min，呼吸20/min，血壓180/70 mmHg，血氧飽和度99%。下列何種處置最不適當？","options":["(A) 準備置放氣管內管","(B) 使用藥物（如etomidate）輔助插管","(C) 放置鼻胃管引流，減輕胃部壓力，避免持續嘔吐","(D) 安排頭部電腦斷層檢查"],"answer":2,"image":""},{"id":"md5-113-2-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"113年第2次第76題","year":113,"session":2,"number":76,"question":"嚴重外傷病人應在30分鐘內送到距離最近且適當的創傷中心，下列何者最不符合轉送標準？","options":["(A) 昏迷指數少於14分","(B) 軀幹和四肢近端的穿透性損傷","(C) 骨盆骨折","(D) 右小腿脛骨開放性骨折"],"answer":3,"image":""},{"id":"md5-113-2-77","subject":"md5","topic":"外科-休克創傷傷口","meta":"113年第2次第77題","year":113,"session":2,"number":77,"question":"下列何者不是筋膜切開術（fasciotomy）的適應症？","options":["(A) 摸不到遠端脈搏","(B) 6小時內的腔室壓力（compartment pressures）＞30 mmHg","(C) 壞死肌肉組織之清創","(D) 腔室壓力與收縮壓之間差距＞30 mmHg"],"answer":3,"image":""},{"id":"md5-113-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"113年第2次第78題","year":113,"session":2,"number":78,"question":"35歲男性病人，已婚，曾經兩次與陌生人發生不安全性行為。病人雖然目前沒有症狀，依然要求醫師安排檢查。結果HIV血液檢驗呈現陽性反應，然病人並不想告知配偶此檢驗結果。下列作法何者最合適？","options":["(A) 考量醫師對病人有守密的義務，不應對第三者揭露病人病況，包括病人的配偶","(B) 醫師擔心病人的配偶有染病的風險，應直接通知其配偶","(C) 醫師應依法通報衛生主管機關處理","(D) 拒絕繼續為病人治療，並轉介給感染科醫師"],"answer":2,"image":""},{"id":"md5-113-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"113年第2次第79題","year":113,"session":2,"number":79,"question":"開刀房緊急會診，因某科醫師在進行骨盆腔腫瘤切除手術時，不慎切斷右側輸尿管，需緊急照會泌尿科醫師協助。泌尿科醫師評估需重接輸尿管，並留置輸尿管內雙J導管。原手術醫師希望會診醫師能儘量簡單處理，不要驚動家屬。會診醫師之處理方式，下列何者最恰當？","options":["(A) 配合辦理，把手術做完，默默離開","(B) 自行前去向家屬解釋，簽署輸尿管手術相關的同意書，並告知病患體內需放置雙J導管","(C) 與原主刀醫師一同向家屬解釋手術狀況，並簽署輸尿管手術相關的同意書，且告知病患體內需放置雙J導管","(D) 施行手術後，請原手術醫師能告知病患或家屬其體內有放置雙J導管"],"answer":2,"image":""},{"id":"md5-113-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"113年第2次第80題","year":113,"session":2,"number":80,"question":"下列何者不是影響病患自主意願的外在因素？","options":["(A) 醫師提供的病情說明","(B) 醫療資訊的來源","(C) 疾病導致的疼痛感","(D) 病患親友的態度"],"answer":2,"image":""},{"id":"md5-114-1-1","subject":"md5","topic":"外科-休克創傷傷口","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"下列何者不是神經性休克的臨床表徵？","options":["(A) 血壓變低","(B) 心跳變快","(C) 回到心臟的靜脈血流量減少","(D) 病人常合併脊髓損傷"],"answer":1,"image":""},{"id":"md5-114-1-2","subject":"md5","topic":"外科-休克創傷傷口","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"兩輛轎車對撞後30分鐘，救護車送來四位病人到急診室，下列那位病人應優先處置？","options":["(A) 呈現呼吸窘迫現象，呼吸40次/分鐘","(B) 左側胸部沒有呼吸聲且無頸靜脈怒張","(C) 小腿開放性骨折，褲管浸濕了鮮血","(D) 最先被送來的病人，且一直罵三字經與恐嚇醫護人員"],"answer":0,"image":""},{"id":"md5-114-1-3","subject":"md5","topic":"消化器外科","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"為了減少腹腔鏡膽囊切除術後之併發症，須特別注意卡洛氏三角（Calot's triangle），下列何者為卡洛氏三角之組成？","options":["(A) 總膽管，右肝動脈，膽囊管","(B) 右肝管，肝臟下緣，膽囊管","(C) 總肝管，肝臟下緣，膽囊管","(D) 總膽管，肝臟下緣，腔動脈"],"answer":2,"image":""},{"id":"md5-114-1-4","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"感染來源控制（infection source control）之基本原則，下列何者錯誤？","options":["(A) 感染物質有效引流","(B) 移除感染區域之異物","(C) 感染傷口清創","(D) 強效抗生素使用"],"answer":3,"image":""},{"id":"md5-114-1-5","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"有關器官移植後癌症的發生，下列敘述何者錯誤？","options":["(A) 器官移植後最常發生的癌症為皮膚癌","(B) 器官移植後肝癌的發生與B型及C型肝炎病毒有關","(C) 器官移植後卡波西氏肉瘤（Kaposi sarcoma）的發生與人類第八型疱疹病毒（human herpesvirus 8）有關","(D) 器官移植後發生癌症時應立即停止免疫抑制劑以避免癌症惡化"],"answer":3,"image":""},{"id":"md5-114-1-6","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"下列何者不是全靜脈營養（total parenteral nutrition, TPN）的併發症？","options":["(A) 水分給太多或太少，可能造成水腫或脫水情況","(B) 可能誘發腸道阻塞","(C) 長期使用可能引起微量元素缺乏","(D) 肝功能可能變差"],"answer":1,"image":""},{"id":"md5-114-1-7","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"有關再餵食症候群（refeeding syndrome）的發生，下列何者正確？","options":["(A) 長期禁食營養不良病人（malnourished patients）再餵食時，早期常因胰島素大量分泌造成低血糖","(B) 只發生在經口進食病人","(C) 餵食前先補充麩醯胺酸（glutamine）可預防併發症","(D) 可能發生低血磷造成心律不整"],"answer":3,"image":""},{"id":"md5-114-1-8","subject":"md5","topic":"神經外科","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"有關聽神經瘤（acoustic neuroma）之敘述，下列何者正確？","options":["(A) 源自聽神經（cochlear nerve）","(B) 手術切除之併發症最常見為旁邊的第六對外展神經受傷，病人術後產生複視","(C) 以手術切除為主，radiosurgery用在手術後殘留腫瘤，很少第一線就使用","(D) 雙側acoustic neuromas常與neurofibromatosis type 2有關"],"answer":3,"image":""},{"id":"md5-114-1-9","subject":"md5","topic":"神經外科","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"有關毛毛樣血管疾病（moyamoya disease），下列敘述何者正確？","options":["(A) 成人建議以血管繞道手術治療","(B) 較少發生在亞洲人","(C) 只影響單側腦血管","(D) 阻塞以後大腦動脈為主"],"answer":0,"image":""},{"id":"md5-114-1-10","subject":"md5","topic":"神經外科","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"下列何種顱內血管異常疾病較可能是由外傷造成的？","options":["(A) 毛毛樣血管病變（moyamoya disease）","(B) 海綿狀血管畸形病變（cavernous malformation）","(C) 頸動脈–海綿竇瘻管（carotid-cavernous fistula）","(D) 微血管樣血管擴張（capillary telangiectasia）"],"answer":2,"image":""},{"id":"md5-114-1-11","subject":"md5","topic":"神經外科","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"有關脊椎狹窄（spinal stenosis）之敘述，下列何者最適當？","options":["(A) spondylosis表示脊椎構造廣泛性的退化形變和過度增生，造成脊椎狹窄（spinal stenosis）的過程","(B) 頸椎退化造成椎管內脊髓壓迫而產生脊髓病變，此一過程稱為cervical spondylolytic myelopathy","(C) 典型的脊髓病變表現為上肢肌肉無力萎縮，肌腱反射變強（hyperreflexia），但下肢本體感覺正常","(D) 脊髓病變通常為多節性，通常病患接受減壓手術治療就能夠得到立即且滿意的恢復，不需再復健治療"],"answer":0,"image":""},{"id":"md5-114-1-12","subject":"md5","topic":"神經外科","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"下列關於Hangman's fracture敘述，何者正確？","options":["(A) 主要是第二頸椎受到突然扭轉（rotation）力量所致","(B) 造成第二頸椎雙側椎關節（facet）骨折","(C) 很少發生神經功能損傷，可先以外固定方式治療","(D) 嚴重的損傷會造成第一、二頸椎脫位；不穩定時，則需做內固定手術治療"],"answer":2,"image":""},{"id":"md5-114-1-13","subject":"md5","topic":"神經外科","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"頭部外傷後，下列何種症狀，可先觀察，不一定要馬上做電腦斷層攝影？","options":["(A) 不明原因噴射式嘔吐3次","(B) 單側肢體肌力少了1分","(C) 暈眩","(D) 頭部穿刺傷"],"answer":2,"image":""},{"id":"md5-114-1-14","subject":"md5","topic":"整形重建外科","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"有關手指外觀異常，下列敘述何者錯誤？","options":["(A) swan-neck deformity：近端指關節的過度伸展和遠端指關節的過度屈曲","(B) boutonnière deformity：近端指關節的過度屈曲和遠端指關節的過度伸展","(C) gamekeeper thumb：大拇指掌指關節的橈側副韌帶受損","(D) trigger finger：手指屈肌腱狹窄性肌腱鞘炎"],"answer":2,"image":""},{"id":"md5-114-1-15","subject":"md5","topic":"整形重建外科","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"下列何者不是穿通枝皮瓣（perforator flaps）的缺點？","options":["(A) 可保留供給區肌肉及肌膜的功能","(B) 不易分離單獨的穿通枝血管","(C) 穿通枝血管分離增加手術時間","(D) 解剖學上血管部位的變異性大且血管較短小，管壁較薄"],"answer":0,"image":""},{"id":"md5-114-1-16","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"第一個異體臉部移植（facial transplantation）手術成功的案例是在那個國家？","options":["(A) 美國","(B) 英國","(C) 法國","(D) 俄羅斯"],"answer":2,"image":""},{"id":"md5-114-1-17","subject":"md5","topic":"整形重建外科","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"在抽脂手術中所使用的tumescent fluid（lidocaine 0.05% and epinephrine 1:1,000,000），lidocaine的最高安全劑量限制為：","options":["(A) 7 mg/kg","(B) 15 mg/kg","(C) 20 mg/kg","(D) 35 mg/kg"],"answer":3,"image":""},{"id":"md5-114-1-18","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"50歲女性，接受定期篩檢乳房攝影（screening mammography），回診時報告敘述breast imaging reporting and data system（BI-RADS）category：0，診間醫師該如何向病人解釋？","options":["(A) 無發現明顯異常（negative），定期追蹤即可","(B) 良性病灶（benign），需每年定期追蹤","(C) 懷疑異常（suspicious abnormality），需進一步切片檢查","(D) 需進一步安排其他影像學檢查診斷"],"answer":3,"image":""},{"id":"md5-114-1-19","subject":"md5","topic":"外科-休克創傷傷口","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"蔡女士不幸發生瓦斯氣爆燒傷，經救護車送至急診室，急診醫師檢查初步生命跡象穩定，發現燒傷水泡、脫皮範圍在整個雙側上肢、前胸及腹部深二度燒傷，於急診室測量體重為60公斤；依據 “Rule of nines”其燒傷面積為何？又根據”Parkland formula”前8小時應給與多少輸液？","options":["(A) 36%；8640 ml乳酸鹽林格氏液（Lactated Ringer's solution）","(B) 36%；4320 ml乳酸鹽林格氏液（Lactated Ringer's solution）","(C) 27%；3888 ml 5%葡萄糖液（D5W）","(D) 45%；6480 ml生理食鹽水（normal saline）"],"answer":1,"image":""},{"id":"md5-114-1-20","subject":"md5","topic":"心臟血管外科","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"下列何者不是急性冠心症後可能造成的併發症（mechanical complication）？","options":["(A) 急性主動脈瓣閉鎖不全（acute aortic regurgitation）","(B) 乳突肌斷裂合併二尖瓣逆流（papillary muscle rupture with mitral regurgitation）","(C) 心室中隔缺損（ventricular septal defect）","(D) 游離壁破裂（free wall rupture）"],"answer":0,"image":""},{"id":"md5-114-1-21","subject":"md5","topic":"心臟血管外科","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"對於有intermittent claudication之病人，其ankle-brachial index（ABI）大多為：","options":["(A) ＞1.0","(B) 0.8～1.0","(C) 0.5～0.7","(D) 0.2～0.4"],"answer":2,"image":""},{"id":"md5-114-1-22","subject":"md5","topic":"心臟血管外科","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"對於主動脈剝離（aortic dissection）病人之血壓控制，下列何項處置最不適合？","options":["(A) 靜脈注射短效乙型阻斷劑","(B) 靜脈注射甲型及乙型阻斷劑","(C) 靜脈注射乙型阻斷劑及血管擴張劑","(D) 僅使用血管擴張劑"],"answer":3,"image":""},{"id":"md5-114-1-23","subject":"md5","topic":"心臟血管外科","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"67歲男性，吸菸20年，糖尿病5年僅用口服血糖藥治療，因心肌梗塞入院，給了兩種抗血小板藥物，在主動脈幫浦（intra-aortic balloon pumping）支持下血壓80/60 mmHg，左心射出率約35%，且左主冠狀動脈有80%狹窄，左迴旋枝中段多處75%到85%狹窄，右冠狀動脈有兩處80%狹窄，下列建議何者最不適當？","options":["(A) 高度建議先行冠狀動脈繞道術（coronary artery bypass grafting）","(B) 可考慮放置更高階機械循環輔助（mechanical circulatory support），如葉克膜、心室輔助器","(C) 應該等抗血小板藥效過後，才行手術，減少出血之可能","(D) 不停跳之冠狀動脈繞道術式（off-pump CABG）與行心肺機之冠狀動脈繞道術式（on-pump CABG）相比，並無較佳之長期成果"],"answer":2,"image":""},{"id":"md5-114-1-24","subject":"md5","topic":"心臟血管外科","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"有關機械循環輔助（mechanical circulatory support）之敘述，下列何者錯誤？","options":["(A) 根據IABP-SHOCK II trial報告，主動脈幫浦（IABP）可以對心因性休克之病患，提供比只使用最佳藥物治療更好的存活率","(B) 在REMATCH trial報告中，植入型之左心室輔助器，可以對第四級心衰竭病人提供比最佳藥物治療更好的存活率","(C) 如果要選擇同時對心肺衰竭都可以支持的循環輔助，只有葉克膜（extracorporeal membrane oxygenation, ECMO）","(D) 長效型之心室輔助器（durable ventricular assist device）不但可以用來過渡到心臟移植（bridge to transplant），也被允許做為終極治療（destination therapy）"],"answer":0,"image":""},{"id":"md5-114-1-25","subject":"md5","topic":"胸腔外科","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"71歲陳先生，因吞嚥困難至醫院檢查，證實是食道鱗狀上皮細胞癌（squamous cell carcinoma），經一系列檢查，發現腫瘤侵犯食道肌肉層但未超過肌肉層，有三顆淋巴轉移，但無遠端轉移，細胞為中度分化（moderately differentiated）。根據AJCC第八版，陳先生為食道癌病理分期第幾期？","options":["(A) IB","(B) IIB","(C) IIIB","(D) IVB"],"answer":2,"image":""},{"id":"md5-114-1-26","subject":"md5","topic":"胸腔外科","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"承上題，根據食道癌之分期，接下來陳先生應接受何種治療？","options":["(A) 接受食道切除及重建手術","(B) 化學治療，然後再開刀","(C) 標靶治療","(D) 術前同時放射線治療加化學治療，然後再開刀"],"answer":3,"image":""},{"id":"md5-114-1-27","subject":"md5","topic":"胸腔外科","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"有關肺腺癌（adenocarcinoma）的組織學分型（subtype）中，下列何者之預後最佳？","options":["(A) 腺泡型（acinar）","(B) 乳頭型（papillary）","(C) 伏壁型（lepidic）","(D) 微乳頭型（micropapillary）"],"answer":2,"image":""},{"id":"md5-114-1-28","subject":"md5","topic":"胸腔外科","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"關於類肉瘤病（sarcoidosis）之敘述，下列何者正確？","options":["(A) 病患肺部多會受影響","(B) 不會導致肺纖維化","(C) 非乾酪性肉芽腫（non-caseating granuloma）只會發生在肺部和兩側肺門淋巴結","(D) 主要治療用藥為抗生素"],"answer":0,"image":""},{"id":"md5-114-1-29","subject":"md5","topic":"消化器外科","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"有關食道裂孔疝氣（esophageal hiatal hernia），下列敘述何者正確？","options":["(A) 每位病患一定會有症狀","(B) type I為paraesophageal hernia","(C) type II又稱rolling hernia","(D) type III為sliding hernia"],"answer":2,"image":""},{"id":"md5-114-1-30","subject":"md5","topic":"消化器外科","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"關於代謝及減重手術的適應症，下列何者錯誤？","options":["(A) BMI＞40或BMI＞35合併肥胖導致的合併症","(B) 無酒精依賴或使用毒品","(C) 無須精神科醫師評估，即可接受手術","(D) 65歲以上的患者若考慮手術，需要更謹慎的評估"],"answer":2,"image":""},{"id":"md5-114-1-31","subject":"md5","topic":"消化器外科","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"關於門靜脈高壓（portal hypertension）的敘述，下列何者錯誤？","options":["(A) 門靜脈高壓定義為門靜脈壓力與肝靜脈壓力差大於5 mmHg","(B) 由冠狀靜脈（coronary vein）及胃短靜脈（short gastric vein）匯入奇靜脈（azygos vein）產生之側支循環於臨床的重要性是造成胃食道靜脈曲張","(C) caput medusae是由於left portal vein和epigastric vein之間臍靜脈（umbilical vein）的再疏通（recanalization）","(D) 酒精性肝硬化（alcoholic cirrhosis）病人其門靜脈血流阻力發生之處在presinusoidal level"],"answer":3,"image":""},{"id":"md5-114-1-32","subject":"md5","topic":"消化器外科","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"有關急性闌尾炎的敘述，下列何者錯誤？","options":["(A) 除了白血球數目外，C-反應蛋白（C-reactive protein）、膽色素、前降鈣素（procalcitonin）檢測有助於預測穿孔性闌尾炎","(B) 非複雜性闌尾炎接受內科抗生素治療，約四分之一病人在一年內須接受手術治療，且有較高比率發生複雜性闌尾炎","(C) 單孔腹腔鏡手術的結果與美觀均比傳統腹腔鏡手術好","(D) 急性闌尾炎是闌尾癌最常見的表徵"],"answer":2,"image":""},{"id":"md5-114-1-33","subject":"md5","topic":"消化器外科","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"有關胃惡性腫瘤之敘述，下列何者最恰當？","options":["(A) 對於局部侵犯性胃癌，要有足夠切除範圍，此外淋巴腺的廓清術對其預後有幫助","(B) 對於原發性胃的淋巴瘤，宜先手術再化學治療","(C) 在已開發國家，雖整體胃癌發生率下降，但胃遠端的惡性腫瘤發生率卻上升","(D) 早期胃癌不會淋巴轉移"],"answer":0,"image":""},{"id":"md5-114-1-34","subject":"md5","topic":"消化器外科","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"目前較常用來評估肝臟功能的方法為Child-Pugh classification，下列何者不是評估項目？","options":["(A) bilirubin","(B) albumin","(C) partial thromboplastin time","(D) ascites"],"answer":2,"image":""},{"id":"md5-114-1-35","subject":"md5","topic":"消化器外科","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"關於Bismuth-Corlette type I近端膽管癌（proximal cholangiocarcinoma）的手術治療，下列何項處置為最不必要之手術？","options":["(A) 膽囊切除","(B) 總膽管切除","(C) 部分肝切除","(D) 肝動脈及門靜脈周圍淋巴結廓清"],"answer":2,"image":""},{"id":"md5-114-1-36","subject":"md5","topic":"消化器外科","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"關於胰臟癌的手術，下列何種情況仍適合做根除性切除？","options":["(A) 肝臟有多個轉移","(B) 腫瘤侵犯大腸","(C) 腫瘤侵犯上腸繫膜動脈（superior mesenteric artery）","(D) 腫瘤侵犯腹腔動脈（celiac artery）"],"answer":1,"image":""},{"id":"md5-114-1-37","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"下列關於短腸症候群（short bowel syndrome）的敘述，何者錯誤？","options":["(A) 短腸症候群的臨床標誌（hallmarks）包括：腹瀉（diarrhea）、液體和電解質缺乏（fluid and electrolyte deficiency）及營養不良（malnutrition）","(B) 短腸症候群早期治療目標為控制腹瀉、補充水分及電解質、儘快給與TPN","(C) 一旦可進食時，初期以高糖及高蛋白食物為主，以增加腸道吸收","(D) 食物中的脂肪通常以short-chain triglycerides為佳"],"answer":3,"image":""},{"id":"md5-114-1-38","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"一位35歲男性因multiple endocrine neoplasia type 2罹患雙側pheochromocytoma，接受雙側腎上腺切除後產生Nelson’s syndrome，下列症狀何者與Nelson’s syndrome較無關？","options":["(A) hyperpigmentation","(B) visual field defect","(C) headache","(D) hearing impairment"],"answer":3,"image":""},{"id":"md5-114-1-39","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"一位40歲女性因高血鈣被懷疑罹患primary hyperparathyroidism，因近親有高血鈣的家族史，為排除familial hypocalciuric hypercalcemia，下列何項檢查最為適當？","options":["(A) serum intact parathyroid hormone（PTH）","(B) 24-hour urine calcium","(C) sestamibi scan","(D) neck computed tomography（CT）scan"],"answer":1,"image":""},{"id":"md5-114-1-40","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"58歲男性病患曾經因罹患濾泡狀甲狀腺癌接受過全甲狀腺切除及三次放射碘治療，目前檢驗結果：131 thyroglobulin 3872.43 ng/mL，頸部超音波未發現再犯，I WBS亦未顯示再犯，FDG-PET顯示肺部及骨骼多處轉移病灶，肺部CT追蹤發現肺轉移病灶明顯增多，下列處置何者最不適當？","options":["(A) 應再予以大劑量放射碘治療","(B) 應予以sorafenib治療","(C) 應予以lenvatinib治療","(D) 胸椎骨轉移疼痛可予以緩解性放射治療"],"answer":0,"image":""},{"id":"md5-114-1-41","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"有關下列乳房疾病的處理，何者正確？","options":["(A) fibrocystic change為physiologic change，追蹤即可，不必手術","(B) core biopsy發現atypical ductal hyperplasia，應小心追蹤，不必切除病灶","(C) fibroadenoma的malignant potential高，必須手術切除","(D) malignant phyllodes tumor術後應加做輔助化學治療"],"answer":0,"image":""},{"id":"md5-114-1-42","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"進行腋下淋巴結廓清時，若下列何者受損可能導致闊背肌（latissimus dorsi）無力？","options":["(A) 外側胸神經（lateral pectoral nerve）","(B) 胸背神經（thoracodorsal nerve）","(C) 長胸神經（long thoracic nerve）","(D) 肋間臂神經（intercostobrachial nerve）"],"answer":1,"image":""},{"id":"md5-114-1-43","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"Poly ADP ribose polymerase（PARP）抑制劑用於下列何種轉移性乳癌病患最為合適？","options":["(A) ER：90%，PR：50%，HER2/neu：0，且不具BRCA1/2突變","(B) ER：0%，PR：0%，HER2/neu：0，且具BRCA1/2突變","(C) ER：0%，PR：0%，HER2/neu：3+，且Ki-67＞50%","(D) ER：90%，PR：50%，HER2/neu：3+，且Ki-67＞20%"],"answer":1,"image":""},{"id":"md5-114-1-44","subject":"md5","topic":"小兒外科","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"一新生兒接受腹部手術，術中腸道的外觀如圖所示，下列何者為此病人最可能之診斷？","options":["(A) 腸扭結（intestinal volvulus）","(B) 胎便性腹膜炎（meconium peritonitis）","(C) 壞死性腸炎（necrotizing enterocolitis）","(D) 胎便性腸阻塞（meconium ileus）"],"answer":2,"image":"md5-114-1-44.jpeg"},{"id":"md5-114-1-45","subject":"md5","topic":"小兒外科","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"承上題，對此病人所罹患之疾病，下列敘述何者錯誤？","options":["(A) 好發於迴盲瓣附近的小腸（terminal ileum），有時也會侵犯大腸","(B) 未必出現白血球增多（leukocytosis）","(C) 隨病況加重常併發血小板減少症（thrombocytopenia）","(D) 只發生在早產兒"],"answer":3,"image":""},{"id":"md5-114-1-46","subject":"md5","topic":"消化器外科","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"疝氣（hernia）係指器官或組織經由鄰近之壁層缺陷突出。腸道經由腹膜腔內之腸繫膜缺損突出稱之為下列何者？","options":["(A) 外部疝氣（external hernia）","(B) 內部疝氣（internal hernia）","(C) 鼠蹊疝氣（inguinal hernia）","(D) 腹壁疝氣（ventral hernia）"],"answer":1,"image":""},{"id":"md5-114-1-47","subject":"md5","topic":"小兒外科","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"神經母細胞瘤（neuroblastoma）約占兒童癌症10%，大多病童因診斷時多已較後期，故預後較差，但依據國際神經母細胞瘤分期系統（International Neuroblastoma Staging System）之4S分期一般則預後較佳，下列何者不屬於4S分期？","options":["(A) 一歲以下發病","(B) 限局部原發腫瘤且擴散限於皮膚","(C) 限局部原發腫瘤且擴散限於肝臟","(D) 限局部原發腫瘤且擴散限於骨頭"],"answer":3,"image":""},{"id":"md5-114-1-48","subject":"md5","topic":"小兒外科","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"下列有關先天性小腸閉鎖（jejunoileal atresia）的敘述，何者最不適當？","options":["(A) 產前超音波羊水可能正常","(B) 第IIIb型形狀呈現蘋果樹異常（apple tree deformity）","(C) 新生兒可能無法解出胎便","(D) 發生原因與腸繫膜血管的發育有關"],"answer":1,"image":""},{"id":"md5-114-1-49","subject":"md5","topic":"胸腔外科","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"下列先天性肺部異常（bronchopulmonary malformations），何者最不容易出現自發性氣胸（spontaneous pneumothorax）？","options":["(A) 先天性肺葉氣腫（congenital lobar emphysema）","(B) 支氣管源性囊腫（bronchogenic cyst）","(C) 游離肺（pulmonary sequestration）","(D) 先天性肺部呼吸道畸形（congenital pulmonary airway malformation）"],"answer":2,"image":""},{"id":"md5-114-1-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"小腸息肉症合併下列症狀（如圖），最常見的基因缺損為：","options":["(A) PTEN","(B) STK11","(C) P53","(D) APC"],"answer":1,"image":"md5-114-1-50.jpeg"},{"id":"md5-114-1-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"114年第1次第51題","year":114,"session":1,"number":51,"question":"附圖中何者屬於transsphincteric type瘻管？","options":["(A) Type 1","(B) Type 2","(C) Type 3","(D) Type 4"],"answer":1,"image":"md5-114-1-51.jpeg"},{"id":"md5-114-1-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"114年第1次第52題","year":114,"session":1,"number":52,"question":"痔瘡結紮術最適合下列何種類型的痔瘡？","options":["(A) 血栓性外痔","(B) 血栓性內痔","(C) 內外混合痔","(D) 內痔"],"answer":3,"image":""},{"id":"md5-114-1-53","subject":"md5","topic":"消化器外科","meta":"114年第1次第53題","year":114,"session":1,"number":53,"question":"在美國，每年估計有1%～2%的孕婦需要進行必須的外科手術，依據美國胃腸內視鏡外科醫生協會（The Society of American Gastrointestinal Endoscopic Surgeons）建議在懷孕期間進行腹腔鏡手術的指南，下列與腹腔鏡手術有關的準則，何者錯誤？","options":["(A) 診斷性腹腔鏡檢查法（diagnostic laparoscopy）可以考慮用於懷孕患者的急性腹腔檢查與治療","(B) 孕婦腹腔鏡檢查期間應監測術中的CO2濃度","(C) 腹腔鏡膽囊切除術是妊娠期膽囊疾病患者的首選治療方法，但只限於懷孕後期（third trimester）","(D) 懷孕期間有症狀的總膽管結石（choledocholithiasis），可以考慮用經內視鏡逆行性膽胰管攝影術（endoscopic retrograde cholangiopancreatography, ERCP）及括約肌切開取石術，合併腹腔鏡膽囊切除術處理"],"answer":2,"image":""},{"id":"md5-114-1-54","subject":"md5","topic":"消化器外科","meta":"114年第1次第54題","year":114,"session":1,"number":54,"question":"消化性潰瘍穿孔（perforated peptic ulcer）是典型的外科急症，其手術方式有腹腔鏡手術與開腹手術，下列敘述何者錯誤？","options":["(A) 消化性潰瘍穿孔也可以腹腔鏡治療，小於1厘米的穿孔通常可以用縫合方式修補穿孔，並用血流支配良好的網膜支撐","(B) 在2001年以後進行的隨機對照試驗中，腹腔鏡手術比開腹手術需更多時間","(C) 不論腹腔鏡或開腹手術，對於較大的穿孔或具有纖維化的潰瘍，皆可用血流支配良好的網膜進行修復","(D) 比較此兩種方法，腹腔鏡手術後住院時間較短，且術後感染併發症減少"],"answer":1,"image":""},{"id":"md5-114-1-55","subject":"md5","topic":"消化器外科","meta":"114年第1次第55題","year":114,"session":1,"number":55,"question":"關於內視鏡及血管內手術（endoluminal and endovascular surgery）的敘述，下列何者錯誤？","options":["(A) 良性原因引起的消化道狹窄（benign gastrointestinal stricture），比較不建議用支架（stenting）的方式治療，除非預期患者餘命不長","(B) 在膽道或泌尿道阻塞，常用塑膠支架（plastic stent）做暫時性的治療","(C) 金屬支架（metal stent）可以讓組織長進去（tissue ingrowth），進而預防支架的位移（migration），但是長久下來仍有管路阻塞之疑慮","(D) 冠狀動脈的塗藥支架（drug-eluting coronary stents）可以減少血管內皮的增生（endothelial proliferation），幫助血管的暢通且不需要抗凝血劑去預防血栓（thrombosis）"],"answer":3,"image":""},{"id":"md5-114-1-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"114年第1次第56題","year":114,"session":1,"number":56,"question":"下列關於良性骨腫瘤的敘述，何者最不適當？","options":["(A) 單純性骨囊腫（simple bone cyst）的病灶大約半數發生在肱骨近端，X光影像可見 \"fallen leaf\" sign","(B) 骨巨大細胞瘤（giant cell tumor of the bone）與調控破骨細胞形成（osteoclastogenesis）的RANK / RANKL系統失衡有關","(C) 復發的骨巨大細胞瘤（giant cell tumor of the bone）有80%的機率會轉移到肺部","(D) 許多腫瘤的病理組織裡會出現巨大細胞（giant cells）"],"answer":2,"image":""},{"id":"md5-114-1-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"114年第1次第57題","year":114,"session":1,"number":57,"question":"20歲男性足球比賽中間被絆倒，足部受傷時是在內翻（inversion）及蹠屈（plantar flexion）的姿勢，急診室檢查發現足踝瘀青腫脹，下列敘述何者最不適當？","options":["(A) 可能造成外側足部韌帶的受傷，最常受傷的是anterior talofibular ligament","(B) 可能造成內側三角韌帶（deltoid ligament）的撕除性骨折（avulsion fracture）","(C) 可能造成雙踝骨折（bimalleolar fracture）或三踝骨折（trimalleolar fracture）","(D) 可能造成脛腓骨聯合（syndesmosis）的受傷，造成關節不穩定"],"answer":1,"image":""},{"id":"md5-114-1-58","subject":"md5","topic":"整形重建外科","meta":"114年第1次第58題","year":114,"session":1,"number":58,"question":"關於斷指的處理，下列敘述何者最適當？","options":["(A) 斷指需先用浸泡濕潤的開水紗布包著，並放入夾鏈袋子裡","(B) 斷指送醫時直接放在夾鏈袋子裡","(C) 斷指送醫時直接浸泡在低溫無菌水的夾鏈袋子裡","(D) 病人斷指處出血最好用紗布加壓止血"],"answer":3,"image":""},{"id":"md5-114-1-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"114年第1次第59題","year":114,"session":1,"number":59,"question":"下列何者最不容易導致髕骨脫臼（patellar dislocation）？","options":["(A) 高位髕骨（patella alta）","(B) 膝反屈（genu recurvatum）","(C) 較小的Q角度（Q angle）","(D) 髕骨活動度過大（patellar hypermobility）"],"answer":2,"image":""},{"id":"md5-114-1-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"114年第1次第60題","year":114,"session":1,"number":60,"question":"一位11歲小朋友，身高150公分，體重80公斤，近兩星期覺得走路有困難，無法上下樓梯，兩側的髖關節都覺得僵硬疼痛，無法翹腳而且走路跛行，下列的疾病診斷中那一項最有可能？","options":["(A) 髖關節發育不良（developmental dysplasia of the hip）","(B) 股骨頭骨骺滑脫症（slipped capital femoral epiphysis）","(C) Osgood-Schlatter氏疾病（Osgood-Schlatter disease）","(D) Blount氏疾病（Blount disease）"],"answer":1,"image":""},{"id":"md5-114-1-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"114年第1次第61題","year":114,"session":1,"number":61,"question":"下列何者不是手部的掌內肌群（intrinsic muscle）？","options":["(A) dorsal interossei","(B) lumbricals","(C) flexor digitorum profundus","(D) hypothenar muscle"],"answer":2,"image":""},{"id":"md5-114-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"114年第1次第62題","year":114,"session":1,"number":62,"question":"有關頸椎後縱韌帶骨化症（ossification of the posterior longitudinal ligament），下列敘述何者最不適當？","options":["(A) 好發於亞洲人，且男性較多","(B) 最常見於頸椎第四、五、六節（C4, C5, C6）","(C) 常會合併其他脊椎問題，例如廣泛性特發骨質增生症（diffuse idiopathic skeletal hyperostosis）、脊椎關節退化（spondylosis）及僵直性脊椎炎（ankylosing spondylitis）","(D) 為了解除脊髓神經壓迫，應施行手術減壓才會有神經功能的進步"],"answer":3,"image":""},{"id":"md5-114-1-63","subject":"md5","topic":"骨科-關節重建","meta":"114年第1次第63題","year":114,"session":1,"number":63,"question":"有關骨水泥（bone cement : methyl methacrylate）的敘述，下列何者最適當？","options":["(A) 可以像黏膠一樣將人工關節黏在骨關節上","(B) 一般分裝成粉劑與水劑，瓶裝水劑是polymer，儲存時要避光","(C) 其聚合反應（polymerization）是一種吸熱反應","(D) 可能併發症是monomer或血栓導致，嚴重時會休克、心臟停止"],"answer":3,"image":""},{"id":"md5-114-1-64","subject":"md5","topic":"外科-休克創傷傷口","meta":"114年第1次第64題","year":114,"session":1,"number":64,"question":"下列有關腎臟外傷（renal injury）的敘述，何者錯誤？","options":["(A) 腎臟被膜下血腫（subcapsular hematoma）是最常見的腎臟外傷","(B) 腎實質1公分裂傷，同時併有尿液滲出（extravasation）時，其腎臟外傷分類屬於第3度腎臟外傷","(C) 腎臟血管性高血壓（renal vascular hypertension）是屬於腎臟外傷後晚期發生的併發症之一","(D) 尿性囊腫（urinoma）為腎盂裂傷而沒有手術修補時容易發生的併發症之一"],"answer":1,"image":""},{"id":"md5-114-1-65","subject":"md5","topic":"泌尿-腫瘤","meta":"114年第1次第65題","year":114,"session":1,"number":65,"question":"65歲抽菸男性，主訴最近半年反覆性無痛血尿，靜脈尿路攝影（IVU）發現膀胱左側有一2公分陰影，膀胱鏡發現膀胱腫瘤。在診斷腫瘤侵犯深度方面，下列何者最準確？","options":["(A) 電腦斷層檢查（CT）","(B) 多變項核磁共振檢查（multiparametric MRI）","(C) 檢查組織纖維細胞生長因子受體3（FGFR3）及p53基因表現","(D) 經尿道膀胱腫瘤切除（TURBT）及肌肉層切片檢查"],"answer":3,"image":""},{"id":"md5-114-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"114年第1次第66題","year":114,"session":1,"number":66,"question":"下列何者不是腎細胞癌（renal cell carcinoma）合併下腔靜脈腫瘤栓塞常見的表徵？","options":["(A) 下肢水腫","(B) 血尿","(C) 肺栓塞","(D) 右心房內腫塊"],"answer":1,"image":""},{"id":"md5-114-1-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"114年第1次第67題","year":114,"session":1,"number":67,"question":"下列有關良性前列腺增生（benign prostatic hyperplasia）病人檢查的敘述，何者最不恰當？","options":["(A) 病人需要進行尿液分析以排除感染或血尿，並視需要進行血清肌酸酐測量以評估腎功能","(B) 建議每位病人都應安排上泌尿道的影像學檢查（腎臟超音波或電腦斷層掃描），以了解前列腺增生造成膀胱出口阻塞的嚴重程度","(C) 不建議常規施行膀胱鏡檢查來確定病人是否需要治療，但若進行膀胱鏡檢查可以幫助要接受侵入性治療的病人選擇其手術方法","(D) 疑似神經性膀胱或前列腺手術失敗的病人，可考慮先施行膀胱壓力圖和進一步的尿路動力學檢查"],"answer":1,"image":""},{"id":"md5-114-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"114年第1次第68題","year":114,"session":1,"number":68,"question":"下列何種疾病或手術最不會造成逼尿肌收縮力低下（detrusor underactivity）？","options":["(A) 腦中風","(B) 根治性子宮切除術","(C) 糖尿病","(D) 尿路結石"],"answer":3,"image":""},{"id":"md5-114-1-69","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"114年第1次第69題","year":114,"session":1,"number":69,"question":"36歲男性因不孕症求診，精液分析顯示無精子，抽血檢驗生殖相關荷爾蒙都正常。身體診察發現兩側睪丸及輸精管皆正常，兩側副睪腫脹飽滿。睪丸切片檢查發現睪丸組織造精都正常。預計安排試管嬰兒治療，須進行取精手術。下列何處最不可能取到精子？","options":["(A) 睪丸（testis）","(B) 副睪（epididymis）","(C) 輸精管（vas deferens）","(D) 儲精囊（seminal vesicle）"],"answer":3,"image":""},{"id":"md5-114-1-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"114年第1次第70題","year":114,"session":1,"number":70,"question":"下列有關尿道下裂的手術，何者正確？","options":["(A) 嚴重的陰莖彎曲並不會影響手術的成功率","(B) 第一次手術失敗後，最好在3個月內再度施行第二次手術，以減少病人心理負擔","(C) 手術中原有的尿道板（urethral plate）應予以保留","(D) 使用包皮的旋轉皮瓣不是一個好的手術方法"],"answer":2,"image":""},{"id":"md5-114-1-71","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"114年第1次第71題","year":114,"session":1,"number":71,"question":"有關膀胱輸尿管逆流之敘述，下列何者正確？","options":["(A) 逆流的程度可以分為五級，第一級是指逆流到腎盂","(B) 第一級到第三級逆流，輸尿管及腎盂並未擴張","(C) 手術可以將輸尿管埋在膀胱的黏膜下通道來矯正逆流，通道的長度與輸尿管的直徑比例建議為5：1","(D) 目前主要的治療已轉變為將膠原蛋白或玻尿酸注射到輸尿管開口來矯正逆流，再也不需要靠侵入性的手術來治療"],"answer":2,"image":""},{"id":"md5-114-1-72","subject":"md5","topic":"消化器外科","meta":"114年第1次第72題","year":114,"session":1,"number":72,"question":"75歲老人由療養院送來，主訴腹脹，腹部X光片如圖（A），下消化道鋇劑攝影如圖（B），則其最可能的診斷為下列何者？","options":["(A) 無力性腸阻塞（adynamic ileus）","(B) 上腸繫膜動脈症候群（superior mesenteric artery syndrome）","(C) 乙狀結腸扭轉（sigmoid volvulus）","(D) 近端腸環症候群（afferent loop syndrome）"],"answer":2,"image":"md5-114-1-72.jpeg"},{"id":"md5-114-1-73","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"114年第1次第73題","year":114,"session":1,"number":73,"question":"附圖是一位13歲女性脛骨骨肉瘤（osteosarcoma）的膝部X光影像，箭頭所指的影像表現是下列何者？","options":["(A) 遊動體（loose body）","(B) 軟組織鈣化（soft tissue calcification）","(C) 骨膜反應（periosteal reaction）","(D) 骨折（fracture）"],"answer":2,"image":"md5-114-1-73.jpeg"},{"id":"md5-114-1-74","subject":"md5","topic":"神經外科","meta":"114年第1次第74題","year":114,"session":1,"number":74,"question":"78歲女性，主訴一週以來步態不穩且頭痛。未注射顯影劑的頭部電腦斷層影像如圖，最可能的診斷為何？","options":["(A) bilateral subarachnoid hemorrhage","(B) bilateral meningioma","(C) bilateral subacute epidural hematoma","(D) bilateral subacute subdural hematoma"],"answer":3,"image":"md5-114-1-74.jpeg"},{"id":"md5-114-1-75","subject":"md5","topic":"泌尿-結石與感染","meta":"114年第1次第75題","year":114,"session":1,"number":75,"question":"25歲女性因發燒到急診，病人主訴雙側腰痠痛及頻尿。體溫39℃，血壓110/78 mmHg，心跳92/min。抽血檢查發現：白血球10,000/μL，血紅素12 g/dL，血小板165,000/μL。肝腎功能正常。尿液檢查發現白血球＞100/HPF，紅血球5～10/HPF，尿液懷孕測驗為陰性。下列敘述何者最適當？","options":["(A) 做血液細菌培養的結果有20%與尿液培養結果不同","(B) 腎臟超音波檢查是診斷有無結石或腎膿瘍的最敏感方法","(C) 此病人最可能的診斷為腎盂腎炎（pyelonephritis）","(D) 此病人需要給與7～14天的靜脈注射抗生素治療"],"answer":2,"image":""},{"id":"md5-114-1-76","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"114年第1次第76題","year":114,"session":1,"number":76,"question":"15歲男性，因陰囊疼痛數小時後至急診，發現睪丸腫大及壓痛，有關此臨床狀況，下列敘述何者最不適當？","options":["(A) 如合併頻尿及解尿疼痛時，診斷為副睪炎比睪丸扭轉機率高","(B) 懷疑睪丸扭轉時，檢查常發現患側提睪反射（cremasteric reflex）消失","(C) 診斷為精索靜脈曲張（varicocele）的可能性比副睪炎或睪丸扭轉機率高","(D) 使用超音波診斷睪丸扭轉比電腦斷層掃描更適當"],"answer":2,"image":""},{"id":"md5-114-1-77","subject":"md5","topic":"外科-休克創傷傷口","meta":"114年第1次第77題","year":114,"session":1,"number":77,"question":"關於傷口處置，下列何者最適當？","options":["(A) 頭皮之傷口，以刮鬍刀剔除比用剪刀剪短毛髮可降低傷口感染率","(B) 成人上眼眶的傷口，不應該剃除眉毛，以免毛髮無法生長","(C) 傷口縫合後一律開立抗生素","(D) 沖洗液加入雙氧水沖洗傷口有更好效果"],"answer":1,"image":""},{"id":"md5-114-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"114年第1次第78題","year":114,"session":1,"number":78,"question":"有關醫病關係，下列何者是最適當的描述？","options":["(A) 文化差異使得病人對於何謂「良好醫療照護」會有不同的想法","(B) 病人疾病診斷會受到醫病關係的影響","(C) 無論疾病的種類或急慢性，病人對醫病關係及醫病溝通的期待都相同","(D) 病患滿意度可作為醫病溝通是否良好的主要評量"],"answer":0,"image":""},{"id":"md5-114-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"114年第1次第79題","year":114,"session":1,"number":79,"question":"有關醫療錯誤（medical errors），下列敘述何者最恰當？","options":["(A) 因為手術過程的疏失導致病人受到傷害，稱為不採取行動的錯誤（errors of omission）","(B) 為避免徒增病人的憂慮而隱瞞醫療錯誤，並不違反醫學倫理","(C) 醫師可能在未疏忽的情況下犯錯，仍應誠實告知病人","(D) 為減少醫療意外事件，醫院應積極追究醫師醫療錯誤的責任"],"answer":2,"image":""},{"id":"md5-114-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"114年第1次第80題","year":114,"session":1,"number":80,"question":"王先生89歲，育有5位子女，與小兒子同住，10年前被診斷阿茲海默症。王先生在罹病前就已經指定了一位很要好的朋友蔡先生為其代理人，當病情逐年惡化，已無法經進食攝取足夠維持生理需求之能量。試過放置鼻胃管，但多次被王先生拔除。你是一般外科醫師，王先生被家屬帶來門診，由神經內科轉至外科希望你能幫王先生做灌食用胃造口手術，小兒子同意，但其他不同住的子女反對，下列何者最適當？","options":["(A) 因為蔡先生沒有血緣關係，所以蔡先生並沒有參與醫療決策的權利","(B) 5位子女意見不同時，應以長子的意見為優先","(C) 5位子女意見不同時，應以主要照顧的小兒子意見為主","(D) 如果找不到蔡先生，醫院應邀集5位子女，共同協議以達成決定"],"answer":3,"image":""},{"id":"md5-114-2-1","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"最常使用的能量評估公式Harris-Benedict Equation，不包含下列那一項變數？","options":["(A) 年齡","(B) 身高","(C) 體重","(D) 體表面積"],"answer":3,"image":""},{"id":"md5-114-2-2","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"術前病人的營養狀態（pre-operative nutrition status），常會影響術後合併症的發生及死亡率；對於病患術前營養狀態的評估為不良者，術前需積極營養介入性治療，但下列何者除外？2","options":["(A) Body Mass Index（BMI）＜18.5 kg/m","(B) Unintentional weight loss over 6 months period＞10%","(C) Serum albumin＜3 g/dL","(D) Serum pre-albumin＜40 mg/dL"],"answer":3,"image":""},{"id":"md5-114-2-3","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"下列何者不是肝臟移植的適應症？","options":["(A) 乙醯胺酚（acetaminophen）過量引發的肝毒性導致急性肝衰竭","(B) 慢性B型肝炎引發急性發作及肝衰竭","(C) 慢性C型肝炎合併肝硬化、嚴重腹水及肝腎症候群（hepatorenal syndrome）","(D) 小型肝細胞癌合併門脈分枝腫瘤血栓及末期肝病"],"answer":3,"image":""},{"id":"md5-114-2-4","subject":"md5","topic":"外科-休克創傷傷口","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"有關毒蛇咬傷的敘述，下列何者錯誤？","options":["(A) 被百步蛇咬傷後的局部特徵為組織腫脹、劇痛及瘀血，嚴重時可造成肢體的腔室症候群及大量組織壞死","(B) 當被毒蛇咬傷時切勿將傷口劃開，亦不可將毒液吸出或使用止血帶","(C) 毒蛇咬傷之嚴重度評估包含局部組織腫脹及瘀血範圍、疼痛程度、水泡、瘀斑的形成及生命徵象是否異常等","(D) 毒蛇血清的給與需及時，通常會依據病人的體重來計算應給與劑量"],"answer":3,"image":""},{"id":"md5-114-2-5","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"關於免疫抑制劑（immunosuppressant）的敘述，下列何者錯誤？","options":["(A) Azathioprine會抑制骨髓","(B) Cyclosporine可直接抑制macrophage產生IL-1","(C) OKT3會使T cell釋出細胞激素（cytokine）而引起發燒、畏寒、低血壓等症狀","(D) Pulse steroid therapy可能出現高血糖、高血壓、睡眠困擾等症狀"],"answer":1,"image":""},{"id":"md5-114-2-6","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"一位因短腸症（short bowel syndrome）併腹瀉，而長期接受全中心靜脈營養（total parenteral nutrition）的病人，如果發生perioral pustular rash, darkening of skin creases及neuritis，最可能是因缺乏下列何項營養成分？","options":["(A) 蛋白質","(B) 脂肪酸","(C) 維生素B","(D) 鋅離子"],"answer":3,"image":""},{"id":"md5-114-2-7","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"身體創傷後的代謝反應會明顯改變，不同的創傷會造成不同程度的基礎能量消耗（basal energy expenditure, BEE），下列三種損傷的BEE變化由高而低之排序為何？","options":["(A) 嚴重燒燙傷＞飢餓＞外科手術","(B) 外科手術＞嚴重燒燙傷＞飢餓","(C) 飢餓＞嚴重燒燙傷＞外科手術","(D) 嚴重燒燙傷＞外科手術＞飢餓"],"answer":3,"image":""},{"id":"md5-114-2-8","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"Rituximab是一種單株抗體（monoclonal antibody），可以抑制B細胞（B-cell）對移植器官的排斥反應，主要是針對B細胞表面何種標誌（cell surface marker）？","options":["(A) CD4","(B) CD8","(C) CD20","(D) CD34"],"answer":2,"image":""},{"id":"md5-114-2-9","subject":"md5","topic":"神經外科","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"一位18歲男性因車禍送來急診，剛開始意識清楚可以對答問題，頭皮有一撕裂傷；30分鐘後，在縫合的過程中，意識狀況變差至E2V1M4。下列何項處置最適當？","options":["(A) 趕快安排brain CT，以排除顱內出血的可能","(B) 立即執行bedside FAST，檢查是否有腹內器官破裂出血的可能","(C) 抽血檢查以評估是否有電解質的異常，造成意識模糊","(D) 重新量測生命徵象，必要時給與氣管內管插管，維持呼吸道通暢"],"answer":3,"image":""},{"id":"md5-114-2-10","subject":"md5","topic":"神經外科","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"承上題，brain CT做完後如附圖所示，下列敘述何者錯誤？","options":["(A) 左腦為epidural hematoma，右腦為contused intracranial hematoma","(B) 右腦的出血來源多半為顱骨骨折造成中腦膜動脈（middle meningeal artery）破裂而產生","(C) 左腦的出血來源多半為大腦本身的血管破裂而產生","(D) 若病人的瞳孔出現放大的情形，則建議進行開顱減壓手術"],"answer":0,"image":"md5-114-2-10.jpeg"},{"id":"md5-114-2-11","subject":"md5","topic":"神經外科","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"下列關於central cord syndrome的敘述，何者錯誤？","options":["(A) 上肢的運動功能缺損大於下肢","(B) 常導因於acute cervical hyperflexion injury","(C) 可能伴隨有sphincter dysfunction，通常造成urinary retention","(D) 通常下肢的肌力會比上肢的肌力早回復"],"answer":1,"image":""},{"id":"md5-114-2-12","subject":"md5","topic":"神經外科","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"關於脊椎腫瘤，下列敘述何者錯誤？","options":["(A) 硬膜外（extradural）腫瘤以良性居多","(B) 硬膜內、髓膜外（intradural extramedullary）的腫瘤，以腦膜瘤（meningioma）及神經鞘瘤（schwannoma）最常見","(C) 髓膜內（intramedullary）腫瘤以星形細胞瘤（astrocytoma）及室管膜瘤（ependymoma）最常見","(D) 最好發的部位是胸椎"],"answer":0,"image":""},{"id":"md5-114-2-13","subject":"md5","topic":"神經外科","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"下列腦瘤中何者較常見於孩童，較少見於成人？","options":["(A) 多形性神經膠質母細胞瘤（glioblastoma multiforme）","(B) 腦膜瘤（meningioma）","(C) 腦下垂體腺瘤（pituitary adenoma）","(D) 神經管胚細胞瘤（medulloblastoma）"],"answer":3,"image":""},{"id":"md5-114-2-14","subject":"md5","topic":"神經外科","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"有關毛毛樣血管疾病（moyamoya disease）的敘述，下列何者錯誤？","options":["(A) 亞洲人較多","(B) 多發生在兩側血管","(C) 影像上最常見中大腦動脈與後大腦動脈血管狹窄萎縮","(D) 小孩通常以缺血性腦病變表現"],"answer":2,"image":""},{"id":"md5-114-2-15","subject":"md5","topic":"整形重建外科","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"當周邊神經（peripheral nerve）只有髓鞘（myelin sheath）受傷時的neurapraxia，需多久才能恢復功能？","options":["(A) 一星期","(B) 一個月","(C) 六星期","(D) 三個月"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第15題除未作答者不給分外，其餘均給分 (原公告答案 D)"},{"id":"md5-114-2-16","subject":"md5","topic":"整形重建外科","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"下列何者不是斷指顯微重接（digital replantation）的絶對適應症（strong indications）？","options":["(A) 多根手指截斷時（multiple digital amputations）","(B) 拇指截斷時（thumb amputation）","(C) 小孩子任一手指截斷時（any amputated part in children）","(D) 成人單一手指在屈指淺肌近端處截斷時（amputation at proximal flexor digitorum superficialis of a single finger in adults）"],"answer":3,"image":""},{"id":"md5-114-2-17","subject":"md5","topic":"整形重建外科","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"Z形整形術（Z-plasty）的目的之一是可以延伸主軸的長度。在兩側臂線與主軸成60度時，則可以增加主軸長度的多少？","options":["(A) 60%","(B) 75%","(C) 90%","(D) 100%"],"answer":1,"image":""},{"id":"md5-114-2-18","subject":"md5","topic":"整形重建外科","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"皮膚張力鬆弛線（relaxed skin tension lines, RSTLs）和皮膚切口相關，下列敘述何者正確？","options":["(A) 與皮下肌肉走向成45度","(B) 有表情時與面部形成的皺紋線成垂直線","(C) 與皮下肌肉走向垂直","(D) 和唇緣線垂直"],"answer":[2,3],"image":"","answer_note":"更正:第18題答Ｃ或Ｄ或CD者均給分"},{"id":"md5-114-2-19","subject":"md5","topic":"外科-休克創傷傷口","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"一位28歲70公斤的男性被送到急診時，初步評估全身有70%深二度燒傷，需評估前8小時內體液的補充。根據Parkland formula下列何者為最佳選擇？","options":["(A) 9,800 mL lactated Ringer（LR）輸液","(B) 9,800 mL normal saline（NS）輸液","(C) 4,900 mL 5% Dextrose輸液","(D) 4,900 mL lactated Ringer（LR）輸液"],"answer":0,"image":""},{"id":"md5-114-2-20","subject":"md5","topic":"心臟血管外科","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"以剝離侵犯範圍而言，主動脈剝離（aortic dissection）DeBakey type IIIa與type IIIb間最大區別在於那一部分的主動脈？","options":["(A) 升主動脈（ascending aorta）","(B) 主動脈弓（aortic arch）","(C) 降主動脈（descending aorta）","(D) 腹主動脈（abdominal aorta）"],"answer":3,"image":""},{"id":"md5-114-2-21","subject":"md5","topic":"心臟血管外科","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"40歲男性病患無任何舊疾及創傷，因左下肢突然出現冰冷、無脈、疼痛且感覺異常至急診室就診。3個月前心臟超音波報告發現二尖瓣嚴重狹窄且左心房擴大，心律為心房顫動（atrial fibrillation），則下列敘述何者錯誤？","options":["(A) 下肢動脈血管急性血栓阻塞（embolism）最為可能","(B) 緊急下肢動脈血管打通後，體內鉀離子濃度將可能上升","(C) 若有骨骼肌溶解現象（rhabdomyolysis），將因下肢動脈血管打通後，肌蛋白尿（myoglobinuria）狀況會立即緩解","(D) 若缺血時間越久，則下肢動脈血管打通後下肢腫脹得越厲害"],"answer":2,"image":""},{"id":"md5-114-2-22","subject":"md5","topic":"小兒外科","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"40天大男嬰出生後診斷為法洛氏四重症（tetralogy of Fallot），因經皮血氧濃度（oxygen saturation）降至65%，經緊急插管後，下列後續處置何者較不合適？","options":["(A) 給與乙型阻斷劑（beta blocker）","(B) 給與輸液（hydration）","(C) 給與血管擴張劑（vasodilator）","(D) 麻醉鎮定（sedation）"],"answer":2,"image":""},{"id":"md5-114-2-23","subject":"md5","topic":"心臟血管外科","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"有關胸主動脈瘤之敘述，下列何者錯誤？","options":["(A) 以現有之觀念，先天性雙主動脈瓣（congenital bicuspid aortic valve）可以視為高危險群，有演變為升主動脈瘤之可能","(B) 若女性患者的主動脈瘤最大直徑為7公分，即可建議手術","(C) 升主動脈瘤最大直徑為6公分，且無主動脈逆流，不一定非進行主動脈根部置換術（aortic root replacement）不可，可以考慮行瓣膜保留術式（valve-sparing procedure）","(D) 血管內支架術式（endovascular stenting）已成為治療升主動脈瘤之主流，一般以DeBakey分類來評估是否適合放置支架及有無影響腦部血流的風險"],"answer":3,"image":""},{"id":"md5-114-2-24","subject":"md5","topic":"心臟血管外科","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"有關腹主動脈瘤（abdominal aortic aneurysm）之敘述，下列何者正確？","options":["(A) 若無破裂現象，腹主動脈瘤之最大直徑大於4公分，即可建議手術","(B) 血管支架治療比起傳統開腹主動脈置換手術，再次介入（re-intervention）比率低","(C) 以住院的手術存活率而言，傳統開腹主動脈置換手術比血管支架治療為低","(D) 手術時，下腸繫膜動脈（inferior mesenteric artery）一定要重新再吻合，以減少腸缺血（ischemic bowel）之合併症"],"answer":2,"image":""},{"id":"md5-114-2-25","subject":"md5","topic":"胸腔外科","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"下列症狀何者與胸腔疾病最不相關？","options":["(A) superior vena cava syndrome","(B) Horner syndrome","(C) pseudopolycythemia","(D) Pancoast syndrome"],"answer":2,"image":""},{"id":"md5-114-2-26","subject":"md5","topic":"胸腔外科","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"小孩子最常發現的縱隔腔腫瘤是：","options":["(A) 胸腺囊腫（thymic cyst）","(B) 淋巴瘤（lymphoma）","(C) 神經源腫瘤（neurogenic tumor）","(D) 生殖細胞腫瘤（germ cell tumor）"],"answer":2,"image":""},{"id":"md5-114-2-27","subject":"md5","topic":"胸腔外科","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"關於呼吸道的疾病，下列敘述何者最不適當？","options":["(A) 氣管的腺樣囊狀癌（adenoid cystic carcinoma）可能沿著神經上下擴散","(B) 需長期使用呼吸器者，不適合做氣管修補手術","(C) 曲黴菌球（aspergilloma fungus ball）使用抗黴菌藥物治療3個月為首選","(D) 局部的支氣管擴張症適合手術切除"],"answer":2,"image":""},{"id":"md5-114-2-28","subject":"md5","topic":"消化器外科","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"關於食道功能性疾病的處置，下列敘述何者錯誤？","options":["(A) 常需要高解析度測壓機（high resolution manometry）及pH檢測，來區分疾病的種類及範圍","(B) 胡桃夾子食道（nutcracker esophagus）為最常見的食道過度收縮疾病，應避免喝咖啡、過冷、過熱食物","(C) 廣泛性食道痙攣（diffuse esophageal spasm）主要為藥物及內視鏡治療","(D) 賁門弛緩不能（achalasia）治療上，氣球擴張和肉毒桿菌注射效果一樣好"],"answer":3,"image":""},{"id":"md5-114-2-29","subject":"md5","topic":"消化器外科","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"下列對於誤吞腐蝕性液體病人之處置，何者較不適當？","options":["(A) 給與廣效型抗生素","(B) 可嘗試以胃鏡評估","(C) 立即放置鼻胃管，並以生理食鹽水沖洗","(D) 注意喉部及呼吸道是否暢通"],"answer":2,"image":""},{"id":"md5-114-2-30","subject":"md5","topic":"消化器外科","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"下列關於paraesophageal hernia之敘述，何者最不適當？","options":["(A) 經診斷後，應一律手術，以防發生complication","(B) 由於hiatus之續漸寬大引起","(C) 胃是最常herniate的器官","(D) 阻塞性之症狀為最常見"],"answer":0,"image":""},{"id":"md5-114-2-31","subject":"md5","topic":"消化器外科","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"有關鼠蹊部疝氣（inguinal hernia），下列敘述何者錯誤？","options":["(A) 鼠蹊部疝氣可分為直接型或間接型疝氣","(B) 馬庫型疝氣（pantaloon-type hernia）是指兩種都有","(C) 間接型疝氣指的是因腹壓增加，而間接形成的疝氣","(D) 直接型疝氣的疝氣囊（sac）直接由Hesselbach's triangle鼓出"],"answer":2,"image":""},{"id":"md5-114-2-32","subject":"md5","topic":"消化器外科","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"常見的食道靜脈曲張出血，下列處置何者錯誤？","options":["(A) 治療首要是維持生命徵兆（vital signs）","(B) 可以給與octreotide或vasopressin控制出血","(C) 對於大量出血病患，可以考慮以外科分流手術或肝內門靜脈分流術（TIPS）止血","(D) 對於連續出血不止的病患，可以使用血管攝影栓塞術進行止血"],"answer":3,"image":""},{"id":"md5-114-2-33","subject":"md5","topic":"消化器外科","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"對於十二指腸潰瘍的治療，下列何者錯誤？","options":["(A) 藥物控制為治療的第一線考慮","(B) 對於疼痛無法控制的潰瘍，可以考慮次全胃切除手術","(C) 對於急性潰瘍穿孔的手術方針是越簡單越好，術後輔以氫離子阻斷劑使用為佳","(D) 與胃潰瘍不同，十二指腸潰瘍沒有惡性腫瘤的機會"],"answer":3,"image":""},{"id":"md5-114-2-34","subject":"md5","topic":"消化器外科","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"Zollinger–Ellison syndrome是由下列何種腫瘤所導致的？","options":["(A) Insulinoma","(B) Gastrinoma","(C) Glucagonoma","(D) Vasoactive intestinal peptide-secreting tumor"],"answer":1,"image":""},{"id":"md5-114-2-35","subject":"md5","topic":"消化器外科","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"肝臟血管瘤需要開刀的原因不包含下列何者？","options":["(A) 發生Kasabach-Merritt syndrome","(B) 腫瘤破裂","(C) 腫瘤明顯變大","(D) 腫瘤大於5公分"],"answer":3,"image":""},{"id":"md5-114-2-36","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"大腸癌併發肝臟轉移的病人，下列何項不是影響其手術切除肝臟腫瘤後存活的主要因素？","options":["(A) CEA血中濃度大於200ng/mL","(B) 肝轉移腫瘤的大小大於5公分","(C) 原發腫瘤的位置在直腸（rectum）","(D) 與原發的大腸癌同時發現的肝臟轉移腫瘤（synchronous liver metastasis）"],"answer":2,"image":""},{"id":"md5-114-2-37","subject":"md5","topic":"消化器外科","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"有關肝膽胰外科解剖學，下列何者正確？ ①左肝（left liver）和右肝（right liver）的功能性分界為中肝靜脈（middle hepatic vein） ②肝左葉（left lobe）和右葉（right lobe）的分界為康德黎線（Cantlie’s line） ③Calot三角的邊包括膽囊管（cystic duct）、肝腹側表面（ventral surface of liver）、總膽管（common bile duct） ④肝十二指腸韌帶（hepatoduodenal ligament）包括門靜脈（portal vein）、固有肝動脈（proper hepatic artery）、總膽管（common bile duct） ⑤左側肝（left lateral segment）及左中肝（left medial segment）的分界為鐮韌帶（falciform ligament）","options":["(A) ②③④⑤","(B) ①③④⑤","(C) ①②③④","(D) ①②④⑤"],"answer":3,"image":""},{"id":"md5-114-2-38","subject":"md5","topic":"消化器外科","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"下列有關急性膽管炎的敘述，何者正確？①Charcot triad是指黃疸、右上腹痛、發燒 ②患者在Charcot triad的階段，緊急手術並非是必要的 ③Reynolds pentad是指Charcot triad再加上休克及代謝性酸中毒 ④當患者有Reynolds pentad時，若不予以緊急引流處置，會有致命的危險 ⑤膽汁細菌培養最常見的細菌是Klebsiella, E.Coli, Enterobacter, Pseudomonas及Citrobacter spp.","options":["(A) ①②③④","(B) ②③④⑤","(C) ①②④⑤","(D) 僅③④⑤"],"answer":2,"image":""},{"id":"md5-114-2-39","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"下列關於follicular thyroid carcinoma的敘述，何者錯誤？","options":["(A) 發生率有下降的趨勢，可能與食鹽加碘，及病理組織分類的進步有關","(B) 手術前無法經由fine needle aspiration cytology診斷是follicular adenoma或是follicular carcinoma","(C) 頸部淋巴結轉移發生率較低","(D) 經常為multi-focal，故手術須將甲狀腺切除乾淨"],"answer":3,"image":""},{"id":"md5-114-2-40","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"下列關於primary hyperparathyroidism的敘述，何者正確？","options":["(A) 80%的病人合併有MEN 1或MEN 2B","(B) 病人的副甲狀腺數量通常多於四顆以上","(C) 若病因為solitary parathyroid tumor，parathyoid adenoma與parathyroid carcinoma的比例約為1：3","(D) 對於parathyroid adenoma的定位檢查，sestamibi scan的敏感度（sensitivity）大於80%"],"answer":3,"image":""},{"id":"md5-114-2-41","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"一位65歲女性因頸部腫大多年就醫，理學檢查時，下列何者徵象表示可能有胸內甲狀腺腫（intrathoracic goiter）導致上腔靜脈壓迫情形？","options":["(A) Carnett sign","(B) Kehr sign","(C) Phalen sign","(D) Pemberton sign"],"answer":3,"image":""},{"id":"md5-114-2-42","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"乳房腫瘤的病理切片中，下列何者可能是乳癌的高危險群？","options":["(A) 乳突狀瘤（papilloma）","(B) 硬化腺症（sclerosing adenosis）","(C) 放射狀疤痕（radial scar）","(D) 纖維腺瘤（fibroadenoma）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第42題除未作答者不給分外，其餘均給分 (原公告答案 C)"},{"id":"md5-114-2-43","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"關於乳房疾病，下列敘述何者錯誤？","options":["(A) 乳房良性纖維腺瘤（fibroadenoma）和乳房水囊（cyst）可以用超音波進行鑑別診斷","(B) 經由乳房攝影檢查發現的乳房微小鈣化（microcalcification），進行手術切片診斷最常見的是硬化性腺腫大（sclerosing adenosis）","(C) 乳管原位癌（DCIS）包括四種亞型，其中papillary與comedo type是屬於高惡性分化度，而solid與cribriform是屬於低惡性分化度","(D) 乳癌的預後和其組織學上的亞型有關，包括分化度、荷爾蒙受體（ER、PR）及生長因子受體2（HER2/neu）"],"answer":2,"image":""},{"id":"md5-114-2-44","subject":"md5","topic":"整形重建外科","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"關於乳癌術後之乳房重建手術的考量，下列何者錯誤？","options":["(A) 對於病患考慮乳房重建，外科醫師除負責手術切除腫瘤之外，其建議也會影響病患的選擇","(B) 乳房重建的方式有自體組織皮瓣移植及義乳植入","(C) 乳房重建手術必須等腫瘤切除及術後化學治療完成半年後，經由會診再安排手術","(D) 會考慮乳房重建的病患，通常年紀較輕，社經地位較高"],"answer":2,"image":""},{"id":"md5-114-2-45","subject":"md5","topic":"小兒外科","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"鼠蹊疝氣（inguinal hernia）是兒童最常見手術，有關兒童之先天性鼠蹊疝氣，下列敘述何者錯誤？","options":["(A) 發生原因係正常出生前會關閉之腹膜鞘突（processus vaginalis）未閉合造成","(B) 男性較女性常見，右側較左側常見","(C) 傳統或腹腔鏡疝氣修補手術為關閉腹膜鞘突（processus vaginalis）","(D) 一歲以下之幼兒因鼠蹊環較窄，所以發生嵌頓性疝氣（incarceration）之風險較低"],"answer":3,"image":""},{"id":"md5-114-2-46","subject":"md5","topic":"小兒外科","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"一名體重約2.5公斤的女嬰，出生時有呼吸窘迫、腹部凹陷的現象。X光檢查發現在左側胸腔內充滿腸氣（如圖）。下列敘述何者錯誤？","options":["(A) 此新生兒為先天性橫膈疝氣（congenital diaphragmatic hernia），其腸道經由橫膈缺損處進入胸腔","(B) 此疾病的發生原因尚未十分清楚，但推測可能是在胚胎時期，胸腹膜管（pleuroperitoneal canal）沒有正常閉合造成，約80%發生在左側","(C) 肺動脈高壓（pulmonary hypertension）常是罹患此病新生兒的致死原因","(D) 因為腹部臟器在胸腔，會嚴重影響新生兒的呼吸與換氣，因此在出生後要立即安排緊急手術將腹部臟器復位並修補橫膈缺損"],"answer":3,"image":"md5-114-2-46.jpeg"},{"id":"md5-114-2-47","subject":"md5","topic":"小兒外科","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"一名3歲大男童，被父母親帶到小兒外科門診。據父母表示，男童在出生的時候，他們就發現到前胸壁有凹陷的情況，但是不太明顯。隨著男童長大，這個狀況逐漸嚴重。有關此男童的狀況，下列敘述何者錯誤？","options":["(A) 這男孩的狀況是漏斗胸（pectus excavatum）。漏斗胸的發生率約為1/400，且男孩的人數是女孩的3～4倍","(B) 發現孩子有此狀況時，要特別注意有無合併先天性心臟疾病，如二尖瓣脫垂（mitral valve prolapse），或其他結締組織疾病，如Ehlers-Danlos syndrome、Marfan syndrome","(C) 此疾病是否嚴重到需要手術矯正，應該進行多項評估，包括凹陷指數（Haller index）、心肺功能及其胸壁變形的速率等","(D) Nuss procedure是目前最常運用的手術方式，而最適合的矯正年齡為3歲之前。其置入的矯正板，約在2～ 3年後需再次手術取出"],"answer":3,"image":""},{"id":"md5-114-2-48","subject":"md5","topic":"小兒外科","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"一名7歲女童，右側前頸部處有一個反覆發炎的皮下腫塊，媽媽主訴這個頸部腫塊在出生後即有發現。理學檢查發現腫塊位於胸鎖乳突肌的前緣，且上面有一個細小的開口。下列對這個頸部腫塊的敘述，何者錯誤？","options":["(A) 依此病灶的分布位置及其表面有小開口，可以推斷此病灶應為鰓裂遺跡（branchial cleft remnants）","(B) 病灶會依其胚胎來源的不同，而有不同的位置。其中以第一對鰓裂遺跡（first branchial cleft remnants）最為常見","(C) 此類病灶臨床的表現方式有時局部會有黏液分泌（mucoid drainage）","(D) 此病灶要根除一般需進行手術治療"],"answer":1,"image":""},{"id":"md5-114-2-49","subject":"md5","topic":"小兒外科","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"1歲半男嬰因為摸不到左側睪丸來求診，下列何種處置最適當？","options":["(A) 若腹部超音波顯示左側睪丸在腹腔內，則必須密切追蹤，最好預約三個月回門診一次","(B) 若身體檢查與影像檢查皆無法發現左側睪丸，仍需安排探查手術","(C) 若手術探查結果左側睪丸在腹內，且明顯較右側睪丸小，因未來併發惡性腫瘤機率較高，則必須進行左側睪丸切除","(D) 若在較放鬆狀態下檢查左側睪丸在陰囊內，且大小與右側睪丸相當，但因其提睪肌反射較強，仍應安排睪丸固定手術"],"answer":1,"image":""},{"id":"md5-114-2-50","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"關於大腸直腸癌的敘述，下列何者錯誤？","options":["(A) 絕大部分大腸直腸癌的生成是因為後天的基因突變","(B) 在部分的大腸直腸癌病患的檢體中會發現K-ras基因突變","(C) 第三期結腸癌病患手術後都應接受標靶藥物治療","(D) 目前的大腸直腸癌標靶藥物有針對血管新生因子（VEGF）及上皮細胞受器（EGFR）兩大類"],"answer":2,"image":""},{"id":"md5-114-2-51","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"114年第2次第51題","year":114,"session":2,"number":51,"question":"35歲男性主訴2週前用力解便後開始出現肛門疼痛，偶爾解便出血。在門診以肛門鏡檢查，發現肛門後側有一0.5公分傷口，肛門外出現皮膚突起（skin tag），其最可能的診斷為何？","options":["(A) 痔瘡脫出（hemorrhoids prolapse）","(B) 肛門膿瘍（abscess）","(C) 肛裂（anal fissure）","(D) 肛門瘻管（fistula in ano）"],"answer":2,"image":""},{"id":"md5-114-2-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"114年第2次第52題","year":114,"session":2,"number":52,"question":"60歲男性，過去病史有高血壓，自訴從三個月前開始陸續解血便，近一個月有食慾不振，容易腹脹及排便習慣改變等症狀，體重在這一個月內由75公斤下降至69公斤。在診所接受乙狀結腸鏡檢查後，發現在乙狀結腸（距離肛門約20公分處）有腫瘤，切片病理報告為惡性腫瘤。依據上述情況，下列敘述何者錯誤？","options":["(A) 可建議患者接受完整大腸鏡檢查，藉此確認右側大腸是否同時有腫瘤","(B) 大多數的大腸惡性腫瘤為偶發性，且多數由腺性息肉轉變而來（adenoma-carcinoma sequence）","(C) 如患者惡性腫瘤評估可以手術切除，根據大型臨床試驗如Colon Carcinoma Laparoscopic or Open Resection（COLOR）trial的結果，應建議患者接受傳統開腹手術，而非腹腔鏡手術來切除惡性腫瘤","(D) 安排患者接受影像學檢查（應包括胸腔，腹腔及骨盆腔），藉此來評估臨床分期"],"answer":2,"image":""},{"id":"md5-114-2-53","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"114年第2次第53題","year":114,"session":2,"number":53,"question":"承上題，若患者手術後乙狀結腸癌病理分期為第三期（stage III），關於後續治療或追蹤，下列何者最不適當？","options":["(A) 若術前血清癌胚胎抗原（carcinoembryonic antigen, CEA）未上升，則後續追蹤可不用追蹤血清癌胚胎抗原","(B) 因病患為第三期，可建議病患接受輔助性化學治療","(C) 術後滿12個月可建議患者做大腸鏡檢查來追蹤","(D) 追蹤過程中若出現肝臟或肺臟單一遠端轉移，在謹慎的評估後，有些患者仍然可以接受轉移腫瘤切除手術"],"answer":0,"image":""},{"id":"md5-114-2-54","subject":"md5","topic":"消化器外科","meta":"114年第2次第54題","year":114,"session":2,"number":54,"question":"關於腹腔鏡膽囊切除手術與傳統開腹手術之比較，下列敘述何者錯誤？","options":["(A) 腹腔鏡膽囊切除手術的嚴重併發症遠低於開腹手術","(B) 腹腔鏡膽囊切除手術的術後疼痛較低","(C) 腹腔鏡膽囊切除手術的術後恢復較快","(D) 腹腔鏡膽囊切除手術應用於急性膽囊炎，需要較長的手術時間且有較高機率造成膽管損傷"],"answer":0,"image":""},{"id":"md5-114-2-55","subject":"md5","topic":"消化器外科","meta":"114年第2次第55題","year":114,"session":2,"number":55,"question":"有關腹腔鏡的充氣，下列敘述何者錯誤？","options":["(A) 二氧化碳（CO2）和一氧化二氮（N2O）都可以用來做腹腔鏡的充氣之用，其中N2O的優點是具生理性的鈍性（physiologically inert）及快速吸收的效果","(B) 在手術過程中，一旦身體的緩衝系統（buffer）飽和，隨著二氧化碳的吸收及從緩衝系統的釋放，呼吸性酸中毒就會迅速發生","(C) 氣腹（pneumoperitoneum）後應注意深層靜脈血栓（deep vein thrombosis）的預防，否則可能會增加肺栓塞的危險性","(D) 腹腔鏡手術的腹內氣壓應維持在25mmHg左右，心輸出量（cardiac output）才可以維持穩定"],"answer":3,"image":""},{"id":"md5-114-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"114年第2次第56題","year":114,"session":2,"number":56,"question":"下列關於偽腫瘤（pseudotumorous conditions）的敘述，何者最不適當？","options":["(A) 棕色腫瘤（brown tumor）是常見的代謝疾病，因副甲狀腺激素（parathyroid hormone）增加導致類似骨腫瘤的形成","(B) Gaucher氏病（Gaucher disease）是一種罕見的家族性疾病，由於glucocerebroside的累積導致肝臟、脾臟和骨髓組織增大","(C) 骨壞死（bone infarct）常見於長骨的骨幹（diaphysis）","(D) 膝關節是色素性絨毛結節性滑膜炎（pigmented villonodular synovitis）最常見的侵犯部位"],"answer":2,"image":""},{"id":"md5-114-2-57","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"114年第2次第57題","year":114,"session":2,"number":57,"question":"有關骨折的敘述，下列何者最不適當？","options":["(A) 骨折部位的附近有傷口，不一定是開放性骨折","(B) 即使是開放性骨折，部分病人也能立即接受骨髓內釘固定手術","(C) 根據Gustilo分類，骨折部位有嚴重傷口污染，應歸類為grade II","(D) 若合併大血管斷裂，先將骨折部位穩定再修補血管"],"answer":2,"image":""},{"id":"md5-114-2-58","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"114年第2次第58題","year":114,"session":2,"number":58,"question":"下列關於骨盆骨折相關損傷（associated injuries）的敘述，何者最不適當？","options":["(A) 不穩定型骨盆骨折須注意是否合併神經損傷","(B) L3至S1的神經根損傷，其整體預後比周邊神經損傷（peripheral nerve injuries）要好","(C) 男性的尿道損傷（urethral injury）發生率（incidence)高於女性","(D) 尿道口有血跡時，置放Foley氏導尿管（Foley catheter）前應先安排逆行性尿道造影（retrograde urethrogram）檢查"],"answer":1,"image":""},{"id":"md5-114-2-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"114年第2次第59題","year":114,"session":2,"number":59,"question":"一位大專甲組運動員發生壓力性骨折（stress fracture），下列敘述何者最不適當？","options":["(A) 增加運動量時就會疼痛","(B) 可能會發生在骨盆、股骨頸、脛骨、舟狀骨（navicular）與蹠骨（metatarsals）等部位","(C) 女性運動員合併營養不良、骨質疏鬆與月經停止時，容易發生","(D) 最佳的治療方式是以手術復位後骨釘固定"],"answer":3,"image":""},{"id":"md5-114-2-60","subject":"md5","topic":"骨科-關節重建","meta":"114年第2次第60題","year":114,"session":2,"number":60,"question":"下列何種血液測量值的改變，與腎性骨病（renal osteodystrophy）的直接相關性最小？","options":["(A) 鈣（calcium）","(B) 磷（phosphorus）","(C) 維生素D（vitamin D）","(D) 甲狀腺激素（thyroid hormone）"],"answer":3,"image":""},{"id":"md5-114-2-61","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"114年第2次第61題","year":114,"session":2,"number":61,"question":"30歲的卡車司機，因手腕中央疼痛多年，影像學檢查發現月狀骨缺血性壞死。下列治療方式何者最不適當？","options":["(A) 橈骨延長術（radial lengthening）","(B) 頭狀骨縮短術（capitate shortening）","(C) 帶血管的自體骨移植（vascularized autograft）","(D) 月狀骨切除及部分腕關節融合（lunate excision and partial carpal fusion）"],"answer":0,"image":""},{"id":"md5-114-2-62","subject":"md5","topic":"神經外科","meta":"114年第2次第62題","year":114,"session":2,"number":62,"question":"有關頸椎脊髓病變（cervical spondylotic myelopathy），下列敘述何者最不適當？","options":["(A) 通常會有感覺異常（paresthesia）和運動困難（dyskinesia）等症狀","(B) 脊髓病變（myelopathy）很嚴重時會有Lhermitte sign陽性","(C) 上下肢深層肌腱反射（deep tendon reflex）皆會增強，且下肢會有明顯的對稱陣攣（clonus）","(D) 腹部反射（abdominal reflex）通常是正常的，並可藉此與肌萎縮性脊髓側索硬化症（amyotrophic lateral sclerosis）鑑別診斷"],"answer":2,"image":""},{"id":"md5-114-2-63","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"114年第2次第63題","year":114,"session":2,"number":63,"question":"下列何者不是髖關節後側的短外旋肌群（short external rotators）？","options":["(A) piriformis","(B) quadriceps","(C) obturator","(D) gemellus"],"answer":1,"image":""},{"id":"md5-114-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"114年第2次第64題","year":114,"session":2,"number":64,"question":"目前對於急性腎絞痛（acute renal colic）病人最快速且準確的影像診斷檢查是：","options":["(A) 無顯影劑電腦斷層掃描（noncontrast computed tomography）","(B) 靜脈注射泌尿系統攝影檢查（intravenous pyelography）","(C) 逆行性腎盂攝影（retrograde pyelography）","(D) 核子閃爍尿路攝影（nuclear scintigraphy）"],"answer":0,"image":""},{"id":"md5-114-2-65","subject":"md5","topic":"內分泌與乳房外科","meta":"114年第2次第65題","year":114,"session":2,"number":65,"question":"下列有關腎上腺瘤（adrenal tumor）之敘述，何者錯誤？","options":["(A) 大於6公分腎上腺瘤如無功能，首先建議密集追蹤即可","(B) 目前最佳腎上腺切除方法為利用腹腔鏡手術進行","(C) 小於4公分且有功能的腎上腺瘤，建議手術切除治療","(D) 腎上腺瘤大部分為影像檢查時意外發現"],"answer":0,"image":""},{"id":"md5-114-2-66","subject":"md5","topic":"泌尿-腫瘤","meta":"114年第2次第66題","year":114,"session":2,"number":66,"question":"前列腺癌好發區依序為：","options":["(A) transition zone ＞ peripheral zone ＞ central zone","(B) peripheral zone ＞ central zone ＞ transition zone","(C) peripheral zone ＞ transition zone ＞ central zone","(D) central zone ＞ transition zone ＞ peripheral zone"],"answer":2,"image":""},{"id":"md5-114-2-67","subject":"md5","topic":"泌尿-腫瘤","meta":"114年第2次第67題","year":114,"session":2,"number":67,"question":"一位45歲女性病人，健檢時超音波檢查發現右腎有一直徑2.5公分，邊界清楚的圓形實質腫瘤，其體積的一半向上突出於右腎上緣，並無任何症狀，下列何者錯誤？","options":["(A) 如果超音波是低回音性（hypoechoic）的實質腫瘤，且呈現中心不均質（heterogeneous）的現象，最可能是腎細胞癌（renal cell carcinoma）","(B) 如果超音波是高回音性（hyperechoic）的實質腫瘤，最可能是一種含有脂肪成分的良性腫瘤","(C) 如果懷疑是腎細胞癌時，必須做經皮穿刺切片進行病理診斷","(D) 如果懷疑是良性腫瘤時，可以暫時不做處理追蹤即可"],"answer":2,"image":""},{"id":"md5-114-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"114年第2次第68題","year":114,"session":2,"number":68,"question":"下列何者是糖尿病導致膀胱病變（diabetic cystopathy）在尿路動力學檢查最典型的發現？","options":["(A) 逼尿肌括約肌共濟失調（detrusor-sphincter dyssynergia）","(B) 逼尿肌過動（detrusor overactivity）","(C) 尿道括約肌機能障礙（urethral sphincter dysfunction）","(D) 膀胱感覺損傷（impaired bladder sensation）"],"answer":3,"image":""},{"id":"md5-114-2-69","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"114年第2次第69題","year":114,"session":2,"number":69,"question":"下列何種因子不存在於陰莖海綿體的平滑肌，促使其鬆弛充血引起勃起？","options":["(A) cyclic guanosine monophosphate（cGMP）","(B) protein kinase G","(C) dopamine","(D) nitric oxide"],"answer":2,"image":""},{"id":"md5-114-2-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"114年第2次第70題","year":114,"session":2,"number":70,"question":"依Weigert-Meyer rule，在單側雙套輸尿管（duplicated ureter）的病人，下列敘述何者正確？","options":["(A) 引流上端腎臟的輸尿管，其開口位於膀胱上端及外側","(B) 引流上端腎臟的輸尿管，其開口位於膀胱下端及內側","(C) 只有引流下端腎臟的輸尿管較易發生逆流","(D) 單側三套輸尿管所有分型亦適用Weigert-Meyer rule"],"answer":1,"image":""},{"id":"md5-114-2-71","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"114年第2次第71題","year":114,"session":2,"number":71,"question":"小兒神經性膀胱的膀胱壓力至少在多少cm H2O以上時，比較容易造成上泌尿道病變？","options":["(A) 40 cm H2O","(B) 30 cm H2O","(C) 20 cm H2O","(D) 10 cm H2O"],"answer":0,"image":""},{"id":"md5-114-2-72","subject":"md5","topic":"胸腔外科","meta":"114年第2次第72題","year":114,"session":2,"number":72,"question":"關於疑似氣胸之胸部X光影像，下列敘述何者最不恰當？","options":["(A) 若影像中氣胸不明顯，可請患者吐氣後再照一張胸部後前位（postero-anterior view）X光影像以協助診斷","(B) 張力性氣胸的特徵包括縱隔（mediastinum）偏移","(C) 橫膈膜反轉（inversion）可發生於張力性氣胸","(D) 張力性氣胸的特徵通常為少量的空氣漏至肋膜腔"],"answer":3,"image":""},{"id":"md5-114-2-73","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"114年第2次第73題","year":114,"session":2,"number":73,"question":"20歲男性病人因打球摔傷，膝部疼痛接受電腦斷層檢查，發現脛骨近端有骨折如圖。最可能合併下列何者傷害？","options":["(A) 前十字韌帶（anterior cruciate ligament）","(B) 後十字韌帶（posterior cruciate ligament）","(C) 內側副韌帶（medial collateral ligament）","(D) 臏韌帶（patellar ligament）"],"answer":0,"image":"md5-114-2-73.jpeg"},{"id":"md5-114-2-74","subject":"md5","topic":"消化器外科","meta":"114年第2次第74題","year":114,"session":2,"number":74,"question":"病人主訴腹脹、反胃及腹部悶痛；腹部電腦斷層檢查呈現如附圖。下列何項初診斷最恰當？","options":["(A) volvulus","(B) intussusception","(C) parasite infection","(D) acute appendicitis"],"answer":0,"image":"md5-114-2-74.jpeg"},{"id":"md5-114-2-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"114年第2次第75題","year":114,"session":2,"number":75,"question":"下列那一個病人最適合在急診進行緊急開胸手術（ED thoracotomy）？","options":["(A) 25歲男性從10樓跳下，胸部與下肢變形，到院心電圖監視器呈現心跳停止","(B) 18歲男性工作時從鋼架上跌落，被鋼筋插穿胸口，到院時血壓70/40 mmHg","(C) 30歲男性被尖刀刺傷左前胸，到院時心電圖呈現無脈性電氣活動","(D) 19歲男性開車車禍前胸撞擊方向盤，到院時心電圖監視器呈現無脈性電氣活動"],"answer":2,"image":""},{"id":"md5-114-2-76","subject":"md5","topic":"消化器外科","meta":"114年第2次第76題","year":114,"session":2,"number":76,"question":"有關腸阻塞病人至急診，下列敘述何者最適當？","options":["(A) 小腸阻塞發生的機率多於大腸阻塞機率","(B) 腸阻塞病人腸子蠕動變快，抗痙攣藥物如Buscopan（hyoscine butylbromide）應儘早使用","(C) 常見血液中脂肪酶（lipase）濃度會上升5倍以上","(D) 小腸阻塞很少是因為疝氣或手術後造成的"],"answer":0,"image":""},{"id":"md5-114-2-77","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"114年第2次第77題","year":114,"session":2,"number":77,"question":"有關睪丸扭轉（testicular torsion）之敘述，下列何者錯誤？","options":["(A) 常發生在青少年時期","(B) 症狀發生6小時內處置，預後較好","(C) 病人的左睪丸常為順時鐘方向扭轉，右睪丸為逆時鐘方向扭轉","(D) 最適當的檢查為陰囊核磁共振檢查（MRI）"],"answer":3,"image":""},{"id":"md5-114-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"114年第2次第78題","year":114,"session":2,"number":78,"question":"40歲病人因工作意外導致顱內大量出血併重度昏迷，臨床上需施行緊急開顱手術以避免腦壓過高導致腦死。醫師讀取病人健保卡資料時發現病人曾經簽署預立醫療決定不施行「心肺復甦術」及「維生醫療」，此時的醫療決策何者最適當？","options":["(A) 因非末期病人，故應告知家屬病情並獲同意後施行開顱手術","(B) 應尊重病人不施行「心肺復甦術」及「維生醫療」意願，並給予安寧緩和醫療","(C) 應依病情發展，先給予維生醫療支持，如預後不佳則施予安寧緩和醫療","(D) 應告知家屬可能的嚴重後遺症，建議家屬不為病人施行手術"],"answer":0,"image":""},{"id":"md5-114-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"114年第2次第79題","year":114,"session":2,"number":79,"question":"40歲男子要求進行手術回復其5年前的男性結紮。他在前一段婚姻有一個小孩，現在準備要再婚。當醫師幫他做身體診察時，發現他兩側睪丸萎縮。男子表示，自其青春期後，睪丸發育大小都一直沒有變化。進一步檢查，發現其染色體核型為46, XX。此時，下列處理方式何者最恰當？","options":["(A) 手術照做，行禮如儀，以免節外生枝","(B) 如實以告，並且解釋無法幫他做手術的原委","(C) 找理由不幫他動手術，建議另請其他醫師處理","(D) 請其未婚妻前來，一起解釋"],"answer":1,"image":""},{"id":"md5-114-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"114年第2次第80題","year":114,"session":2,"number":80,"question":"甲醫師具中央主管機關核定之心臟移植資格，到任至不具心臟移植資格的乙醫院工作，當乙醫院有器官捐贈者進行心臟捐贈時，下列敘述何者正確？","options":["(A) 甲醫師具中央主管機關核定之心臟移植資格，可於乙醫院進行心臟之摘取、移植手術","(B) 乙醫院未經中央主管機關核定，不可進行心臟之摘取、移植手術","(C) 甲醫師在乙醫院不可摘取也不可移植心臟","(D) 甲醫師在乙醫院僅可摘取但不可移植心臟"],"answer":3,"image":""},{"id":"md5-115-1-1","subject":"md5","topic":"小兒外科","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"有關小孩外傷的敘述，下列何者最適當？","options":["(A) 小孩的頭皮撕裂傷流血，容易造成失血性休克","(B) 由於小孩的肋骨仍在發育中，當胸部受到撞擊時會比大人容易有肋骨骨折","(C) 比起成年人，小孩的肝脾臟受到胸廓（rib cage）的保護部分較多","(D) 脾臟破裂採取非手術療法處置，比成人有較低的成功率"],"answer":0,"image":""},{"id":"md5-115-1-2","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"關於滑液囊腫（ganglion cyst）的好發位置，下列何者錯誤？","options":["(A) 最常發生於手腕背側，與舟月韌帶（scapholunate ligament）相關","(B) 常見於手腕掌側，可能與橈動脈鄰近","(C) 常見於手指遠端指間關節（DIP joint），亦稱為mucous cyst","(D) 常發生於A2 pulley，可能影響屈指肌腱活動"],"answer":3,"image":""},{"id":"md5-115-1-3","subject":"md5","topic":"心臟血管外科","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"支配心臟血液循環的主要冠狀動脈（coronary arteries），下列何者錯誤？","options":["(A) Left main coronary artery","(B) Left anterior descending coronary artery","(C) Circumflex coronary artery","(D) Radial coronary artery"],"answer":3,"image":""},{"id":"md5-115-1-4","subject":"md5","topic":"心臟血管外科","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"30歲女性，因急性心衰竭以及肺水腫至急診就診，心臟超音波檢查發現僧帽瓣前葉腱索斷裂（rupture of chordae）並且有嚴重僧帽瓣逆流。此僧帽瓣逆流在Carpentier分類（Carpentier classification）中屬於何種dysfunction？","options":["(A) Type Ⅰ","(B) Type Ⅱ","(C) Type Ⅲa","(D) Type ⅢB"],"answer":1,"image":""},{"id":"md5-115-1-5","subject":"md5","topic":"胸腔外科","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"有關肺挫傷（pulmonary contusions），下列敘述何者最不適當？","options":["(A) 常於受傷後12小時內惡化","(B) 可能需呼吸器（mechanical ventilation）甚至葉克膜（extracorporeal membrane oxygenation）支持","(C) 最初之胸腔X光（initial chest radiograph）最適合評估其嚴重度","(D) 兒童之肋骨較柔韌，胸腔鈍傷時就算沒有骨折，仍常有肺挫傷"],"answer":2,"image":""},{"id":"md5-115-1-6","subject":"md5","topic":"胸腔外科","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"下列何者不是食道穿孔治療的重要原則？","options":["(A) 積極的引流控制感染","(B) 早期診斷與治療","(C) 維持腸道營養","(D) 保留食道切勿切除"],"answer":3,"image":""},{"id":"md5-115-1-7","subject":"md5","topic":"胸腔外科","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"68歲男性罹患肺炎，合併出現發燒和胸膜性胸痛。經抗生素治療後，胸部X光檢查顯示有胸腔積水。經胸腔穿刺術檢查，胸腔積水的pH值為7.1，葡萄糖濃度為30 mg/dL，積液呈化膿樣。根據這些發現，下列何者是最適當的下一步處置方式？","options":["(A) 繼續使用原本的抗生素並觀察患者以等待抗生素發揮效用，無需安排進一步醫療介入干預","(B) 反覆進行胸腔穿刺術並監測後續是否仍有積液蓄積","(C) 儘早安排肋膜腔積液引流或胸腔鏡手術介入","(D) 開始使用更廣效的抗生素，並安排在1週內進行追蹤性胸腔穿刺術"],"answer":2,"image":""},{"id":"md5-115-1-8","subject":"md5","topic":"消化器外科","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"關於膽結石合併急性膽囊炎（acute calculous cholecystitis）的敘述，何者最不適當？","options":["(A) 常以發燒和右上腹痛來表現","(B) 電腦斷層診斷的敏感度優於超音波","(C) 手術時若無法分出明確的構造時，可以只作部分膽囊切除以避免傷害總膽管","(D) 先打抗生素作為保守治療，症狀改善後再作延遲的膽囊切除手術，這種策略約有20％的失敗機會"],"answer":1,"image":""},{"id":"md5-115-1-9","subject":"md5","topic":"消化器外科","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"胰腺癌（pancreatic adenocarcinomas）預後相當不好，又俗稱癌王，下列關於此類腫瘤的敘述，何者最不恰當？","options":["(A) 將近約2/3的胰臟腺癌發生於胰臟頭（head）或鈎突（uncinate process）","(B) 發生於胰臟尾端的腫瘤於診斷時通常較大，可手術切除治癒的比例相對較低","(C) 發生於胰臟頭部的腫瘤通常會導致阻塞性黃疸，可比較早期被診斷，手術切除治癒的可能性也相對較高","(D) 腺鱗癌（adenosquamous carcinoma）是一種變異型的胰腺癌，同時具有腺細胞和鱗狀細胞，因為分化良好，所以預後相較胰管腺癌（ductal adenocarcinoma）好"],"answer":3,"image":""},{"id":"md5-115-1-10","subject":"md5","topic":"消化器外科","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"腹股溝深環（deep inguinal ring）位於下列何結構？","options":["(A) 腹外斜肌腱膜（aponeurosis of external oblique muscle）","(B) 腹內斜肌（internal oblique muscle）","(C) 腹橫筋膜（transversalis fascia）","(D) 錐狀肌（pyramidalis muscle）"],"answer":2,"image":""},{"id":"md5-115-1-11","subject":"md5","topic":"消化器外科","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"下列何者屬於presinusoidal portal hypertension的原因？","options":["(A) primary biliary cirrhosis","(B) congestive heart failure","(C) intrahepatic vascular occlusive disease","(D) sarcoid"],"answer":3,"image":""},{"id":"md5-115-1-12","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"病人在接受甲狀腺手術後，平時講話尚可並無聲帶麻痺現象，但唱歌時無法發出高音，最可能的原因為下列何者？","options":["(A) 舌下神經（hypoglossal nerve）損傷","(B) 上喉神經外分枝（external branch of the superior laryngeal nerve）損傷","(C) 喉返神經（recurrent laryngeal nerve）損傷","(D) 迷走神經（vagus nerve）損傷"],"answer":1,"image":""},{"id":"md5-115-1-13","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"關於甲狀腺癌的腫瘤生成與致癌機轉，下列敘述何者最不適當？","options":["(A) BRAF基因突變常見於乳突癌（papillary thyroid carcinoma）與未分化癌（anaplastic thyroid carcinoma）腫瘤","(B) RET基因突變可見於甲狀腺髓質癌（medullary thyroid carcinoma）腫瘤","(C) RAS基因突變可見於甲狀腺濾泡腺瘤與濾泡癌（follicular thyroid adenoma and carcinoma）腫瘤","(D) p53基因是一種致癌基因，其突變常見於未分化甲狀腺癌（anaplastic thyroid cancer）腫瘤"],"answer":3,"image":""},{"id":"md5-115-1-14","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"40歲女性，家裡有乳癌病史，自己也有BRCA1 mutation。兩週前自己感覺到左乳房有硬塊。到門診做進一步檢查，懷疑有惡性可能。該患者從來沒有接受過任何乳房檢查。接下來將安排之檢查，下列何者最不適合？","options":["(A) 乳房超音波（ultrasonography）","(B) 乳房攝影（mammography）","(C) 磁振造影（magnetic resonance imaging）","(D) 正子斷層造影（positron emission tomography）"],"answer":3,"image":""},{"id":"md5-115-1-15","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"51歲女性患者，每月仍有固定月經週期，近一年來體重緩慢下降且偶爾有飽餐後腹漲不適的感覺，但因腹部不適持續的時間不長，也就不以為意。在接受成人健康檢查時，發現血色素低到7.0 g/dL，且糞便潛血呈現陽性反應。在接受大腸鏡鏡檢時，意外發現升結腸有快要堵住腸腔的腫瘤，腸鏡也因腸道狹窄無法穿過腫瘤到達cecum。腸鏡切片結果為adenocarcinoma, microsatellite stable（MSS）。在電腦斷層檢查後，發現腫瘤疑似有侵犯臟層腹膜（visceral peritoneum），腫瘤附近可見6顆直徑大於1公分腫大的淋巴結，其他器官則沒有明顯轉移跡象。根據檢查結果，下列敘述何者錯誤？","options":["(A) 罹患右側大腸癌比左側大腸直腸癌易出現貧血的臨床表現","(B) 此患者的臨床分期為cT3N2bM0","(C) 對於此患者，標準的手術術式為radical right hemicolectomy with lymph node dissection","(D) 目前的研究認為，immunotherapy對於MSS的colon adenocarcinoma效果有限"],"answer":1,"image":""},{"id":"md5-115-1-16","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"關於大腸憩室炎之敘述，下列何者正確？","options":["(A) 急性發作時，大腸鏡檢查是適合的處置","(B) 目前的治療指南對於非複雜性的大腸憩室炎應進行手術切除","(C) 膿瘍不管大小，一律建議在電腦斷層或腹部超音波下先進行經皮引流（percutaneous drainage）","(D) 急性非複雜型的憩室炎在緩解後4～8週要進行大腸鏡檢查"],"answer":3,"image":""},{"id":"md5-115-1-17","subject":"md5","topic":"消化器外科","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"關於腹腔鏡及機械手臂在遠端胰臟切除術（distal pancreatectomy）之應用成果，下列敘述何者錯誤？","options":["(A) 兩者皆保有微創手術相對於開腹手術的優點","(B) 兩者重大併發症，如：胰臟瘻管等發生率相近","(C) 機械手臂手術轉為開腹率及脾臟保留率均較腹腔鏡手術較低","(D) 腹腔鏡手術花費較低"],"answer":2,"image":""},{"id":"md5-115-1-18","subject":"md5","topic":"消化器外科","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"關於腹腔鏡及機械手臂等微創手術在肝臟切除術之角色，下列敘述何者錯誤？","options":["(A) 一般而言，機械手臂切肝手術較腹腔鏡切肝手術耗費時間短、失血較少，但醫療費用較高","(B) 腹腔鏡與機械手臂切肝手術在適應症上大致相同","(C) 腹腔鏡與機械手臂切肝手術在併發症及轉為開腹率方面並沒有顯著差異","(D) 微創手術已成為肝臟邊緣病灶切除的標準治療方式"],"answer":0,"image":""},{"id":"md5-115-1-19","subject":"md5","topic":"消化器外科","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"55歲男性，因罹患B肝長期在胃腸肝膽內科進行追蹤，近期因超音波檢查發現疑似有右肝腫瘤，抽血檢查發現GOT:25 IU/L，GPT:21 IU/L，Total bilirubin:0.8 mg/dL，PT:1.5s，albumin:4.38 g/dL。電腦斷層檢查顯示肝臟第五葉有顆2.5公分大的腫瘤，並有些微肝硬化之表現但無明顯腹水，經皮細針抽取檢體證實為肝細胞癌，故轉介一般外科進行手術評估，抽血檢查發現胎兒蛋白值（AFP）為350 ng/mL，且無肝腦病變之發現。該男性之肝功能分級Child–Pugh Score為多少以及後續建議之治療方法何者較適當？","options":["(A) Child–Pugh A，將安排腹腔鏡肝臟部分切除手術","(B) Child–Pugh B，將安排靛氰綠（Indocyanine green）肝功能檢查，以評估是否適合腹腔鏡手術","(C) Child–Pugh C，建議射頻灼燒術（Radiofrequency ablation）","(D) Child–Pugh B，將安排經動脈導管肝臟腫瘤化學栓塞術（Trans-Arterial Chemo-Embolization）"],"answer":0,"image":""},{"id":"md5-115-1-20","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"關於人體水分組成的敘述，下列何者錯誤？","options":["(A) 水分約占體重（total body weight）約50～60％","(B) 相較於骨骼或脂肪，肌肉或實質器官（solid organ）含有更高的水分含量","(C) 年長者的體內水分比例低於身體質量指數（BMI）＝22的年輕男性","(D) 18歲男性體內的水分占比高於一般正常的新生兒（newborn）"],"answer":3,"image":""},{"id":"md5-115-1-21","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"陳先生，身高175公分、體重70公斤，預計入院接受腹腔鏡膽囊切除手術，術前檢驗數據：Hb:14.8 g/dL，Hct:45％，WBC:8,600/μL，platelet: 246,000/μL，BUN:16 mg/dL，creatinine:0.9 mg/dL，glucose:95 mg/dL，Na:142 mmol/L，K:4.1 mmol/L。下列敘述何者錯誤？","options":["(A) 身體的總水分約38公斤","(B) 血液的滲透壓約為315 mOsm/L","(C) 身體的水分分布，分為細胞外液（extra-cellular fluid, ECF），例如：血漿與組織間液，和細胞內液（intra-cellular fluid, ICF）","(D) 體內的細胞內液的總重量約25公斤"],"answer":1,"image":""},{"id":"md5-115-1-22","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"關於高血鉀症（hyperkalemia）常見的原因，下列何種情況較不會出現？","options":["(A) 大面積的壓軋傷（crush injury）病患","(B) 跑了超長（＞24小時）馬拉松的跑者","(C) 術後腹膜炎感染，敗血症酸中毒的病人","(D) 穩定使用利尿劑furosemide的55歲男性高血壓病人"],"answer":3,"image":""},{"id":"md5-115-1-23","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"臨床上可運用Model for end-stage liver disease（MELD）score，來預測等待肝臟移植的末期肝病患者於三個月內的死亡風險。下列何者不是計算MELD score的參數？","options":["(A) 血清肌酸酐（serum creatinine）","(B) 血清總膽紅素（serum total bilirubin）","(C) 國際標準化比值（international normalized ratio, INR）","(D) 血清白蛋白（serum albumin）"],"answer":3,"image":""},{"id":"md5-115-1-24","subject":"md5","topic":"外科-休克創傷傷口","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"傷口癒合期間，不同細胞會分別出現於傷口。下列敘述何者正確？","options":["(A) 淋巴球（lymphocytes）為起始增生期之主要細胞","(B) 嗜酸性球（eosinophils）為最初止血期之主要細胞","(C) 嗜中性球（neutrophils）為最初發炎期之主要細胞","(D) 纖維母細胞（fibroblasts）在傷口癒合最初期即達到數量高峰"],"answer":2,"image":""},{"id":"md5-115-1-25","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"關於有效減少手術部位感染（surgical site infection）之方式，下列何者最不適當？","options":["(A) 肥胖者於術前減重","(B) 腹部手術者於術前接受腸道準備（bowel preparation）","(C) 術前一週預先施打強效預防性抗生素（prophylactic antibiotic）","(D) 手術時才移除手術部位之毛髮"],"answer":2,"image":""},{"id":"md5-115-1-26","subject":"md5","topic":"神經外科","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"67歲男性，有長期高血壓病史，突然發生右側肢體無力與構音障礙。電腦斷層顯示左側基底核出血。下列何者最可能為其致病機轉？","options":["(A) 老年性腦病變併發澱粉樣血管病（amyloid angiopathy）造成穿通動脈破裂","(B) 小動脈破裂（Charcot-Bouchard aneurysm rupture）造成穿通動脈出血","(C) 頸內動脈與海綿竇瘻管（carotid-cavernous fistula）導致靜脈高壓性出血","(D) 血栓溶解治療後產生再灌流性出血（hemorrhagic transformation after thrombolysis）"],"answer":1,"image":""},{"id":"md5-115-1-27","subject":"md5","topic":"神經外科","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"關於兒童腦幹膠質瘤（pediatric brainstem glioma），下列何者錯誤？","options":["(A) diffuse pontine glioma多為惡性","(B) midbrain glioma（包括tectal and tegmental glioma）預後優於diffuse pontine glioma","(C) diffuse pontine glioma的治療以手術為主","(D) tectal glioma常合併水腦"],"answer":2,"image":""},{"id":"md5-115-1-28","subject":"md5","topic":"神經外科","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"下列何者不屬於癲癎手術？","options":["(A) anterior temporal lobectomy","(B) vagus nerve stimulation","(C) corpus callosotomy","(D) microvascular decompression"],"answer":3,"image":""},{"id":"md5-115-1-29","subject":"md5","topic":"神經外科","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"新生兒及嬰兒水腦症的原因有congenital or acquired etiology，下列敘述何者最不適當？","options":["(A) aqueductal stenosis造成的hydrocephalus屬congenital etiology","(B) aqueductal stenosis造成的hydrocephalus屬communicating hydrocephalus","(C) 新生兒meningitis後，造成postinfectious hydrocephalus，多屬communicating hydrocephalus","(D) Chiari Ⅱ malformation造成的hydrocephalus屬congenital etiology"],"answer":1,"image":""},{"id":"md5-115-1-30","subject":"md5","topic":"神經外科","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"下列關於頸椎退化性疾病的敘述，何者最不適當？","options":["(A) 急性頸椎椎間盤突出有著典型症狀，仔細的臨床評估可以診斷","(B) 最主要的影像學診斷工具為無顯影劑的核磁共振造影檢查","(C) 如果病人無法接受核磁共振造影檢查，則可以用骨頭掃描攝影來取代","(D) 肌電圖和神經傳導檢查，可以用來區分臂神經叢病變和周邊神經病變"],"answer":2,"image":""},{"id":"md5-115-1-31","subject":"md5","topic":"神經外科","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"在顱內壓上升的病人身上可能觀察到的三樣表徵稱為Cushing's triad，下列那一項不是三樣表徵之一？","options":["(A) 血壓上升","(B) 心跳變慢","(C) 頭痛","(D) 呼吸不規則"],"answer":2,"image":""},{"id":"md5-115-1-32","subject":"md5","topic":"外科-休克創傷傷口","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"下列處理嚴重碾壓肢體（mangled extremity）優先順序之敘述，何者錯誤？","options":["(A) 生命優先於肢體（life over limbs）","(B) 血管重建（revascularization）","(C) 反覆清創（repeated debridement）","(D) 神經重建優先於骨骼重建（nerve over bone）"],"answer":3,"image":""},{"id":"md5-115-1-33","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"關於狹窄性腱鞘炎（tenosynovitis），下列敘述何者最適當？","options":["(A) de Quervain病主要影響第二背側腱鞘區（second dorsal compartment）","(B) 交叉症候群（intersection syndrome）的病變主要發生於A1滑車（A1 pulley）","(C) 板機指（trigger finger）的病變可能導致指關節無法完全伸展","(D) de Quervain病的診斷主要依賴X光檢查來區分其他疾病"],"answer":2,"image":""},{"id":"md5-115-1-34","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"25歲男性於籃球比賽時，試圖阻擋對手傳球，被籃球高速撞擊其右手食指末端，出現劇痛、遠端指間關節（DIPJ）屈曲無法主動伸直，近端指間關節（PIPJ）關節活動正常，X光顯示無明顯骨折且無開放性傷口，經急診醫師診斷為①，建議持續配戴副木。然而病人半年後回整形外科門診追蹤，主訴手指外觀近端指間關節（PIPJ）過度伸直、遠端指間關節（DIPJ）持續屈曲，影響籃球握球與傳球動作，經醫師再評估為②，建議考慮手術治療。根據上述情境，下列何者為最適合的①及②之診斷？","options":["(A) ①mallet finger；②swan neck deformity","(B) ①trigger finger；②swan neck deformity","(C) ①jersey finger；②boutonnière deformity","(D) ①trigger finger；②boutonnière deformity"],"answer":0,"image":""},{"id":"md5-115-1-35","subject":"md5","topic":"小兒外科","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"體重小於20公斤（或小於兩歲）之嚴重燒燙傷孩童，24小時之輸液復甦（resuscitation），除乳酸林格氏液（Lactated Ringer's solution）外，建議添加下列何者最適當？","options":["(A) 鉀離子","(B) 鈉離子","(C) 鈣離子","(D) 葡萄糖"],"answer":3,"image":""},{"id":"md5-115-1-36","subject":"md5","topic":"心臟血管外科","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"所謂急性主動脈綜合症（acute aortic syndrome）不包含下列何者？","options":["(A) 主動脈粥狀動脈硬化（Aortic atherosclerosis）","(B) 急性主動脈剝離（Acute aortic dissection）","(C) 主動脈壁內血腫（Intramural hematoma）","(D) 穿透性主動脈潰瘍（Penetrating aortic ulcer）"],"answer":0,"image":""},{"id":"md5-115-1-37","subject":"md5","topic":"心臟血管外科","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"關於主動脈剝離（aortic dissection, AD）、主動脈壁內血腫（intramural hematoma, IMH）及穿透性主動脈潰瘍（penetrating aortic ulcer, PAU）的敘述，下列何者最不適當？","options":["(A) 急性Type A AD手術死亡率高，藥物治療無效再考慮手術治療","(B) 複雜Type B AD如器官灌注不良（malperfusion），需考慮手術治療","(C) 急性Type A IMH開刀適應症，應比照急性Type A AD","(D) PAU應藥物治療優先，但針對PAU內徑＞20 mm及PAU neck＞10 mm，建議儘早手術介入治療"],"answer":0,"image":""},{"id":"md5-115-1-38","subject":"md5","topic":"心臟血管外科","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"關於深層靜脈栓塞（deep venous thrombosis, DVT），下列敘述何者錯誤？","options":["(A) 臨床上可能有Homan sign，但敏感性（sensitivity）與特異性（specificity）皆不高","(B) 用檢測D-dimer作為唯一正確診斷之工具，但陰性預測值（negative predictive value）＜90％","(C) 可使用超音波（duplex ultrasound）幫助診斷，可檢視血栓，或以壓迫（compression）方式進行測試","(D) 靜脈攝影（venography）可做較精確的診斷，缺點是較侵入性，且須注射顯影劑"],"answer":1,"image":""},{"id":"md5-115-1-39","subject":"md5","topic":"胸腔外科","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"關於惡性肋膜間質細胞瘤（mesothelioma）之描述，下列何者最不適當？","options":["(A) 與石綿暴露有關，好發於40歲以上之男性","(B) 外科角色主要在於切片診斷及姑息性肋膜沾黏治療","(C) 單獨外科、化學或放射治療皆無法延長存活","(D) 肋膜外全肺切除包括切除肺、臟層、壁層肋膜、心包膜與橫膈"],"answer":[1,2],"image":"","answer_note":"更正:第39題答Ｂ或Ｃ或BC者均給分"},{"id":"md5-115-1-40","subject":"md5","topic":"泌尿-腫瘤","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"關於惡性生殖細胞瘤（malignant germ cell tumor）之敘述，下列何者最不適當？","options":["(A) 精細胞瘤（seminoma）對放射線治療敏感","(B) 惡性非精細胞瘤（non-seminomatous tumor）生殖細胞腫瘤很少對放射線治療敏感","(C) 惡性非精細胞瘤（non-seminomatous tumor）生殖細胞腫瘤包括絨毛膜癌（choriocarcinomas）、胚胎細胞癌（embryonal cell carcinomas）等","(D) 惡性非精細胞瘤（non-seminomatous tumor）生殖細胞腫瘤多發生於女性"],"answer":3,"image":""},{"id":"md5-115-1-41","subject":"md5","topic":"胸腔外科","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"關於Ivor Lewis式食道切除術的描述，下列何者正確？","options":["(A) Ivor Lewis式食道切除術是一種微創手術，傷口小，恢復快","(B) 主要適用於食道上段腫瘤","(C) 需進行胸腔與上腹部的淋巴結清掃","(D) 術後併發症發生率小於5％"],"answer":2,"image":""},{"id":"md5-115-1-42","subject":"md5","topic":"消化器外科","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"關於腹股溝疝氣手術後復發之描述，何者最不適當？","options":["(A) 造成復發常見的原因與手術技術有關（technical factors）","(B) 間接型疝氣相對於直接型疝氣，修補後比較容易復發","(C) 大約有5～10％的股疝氣（femoral hernia）會在疝氣復發時被發現","(D) 使用無張力（tension-free）與人造網膜（mesh）修補，可以有效降低再復發的機會"],"answer":1,"image":""},{"id":"md5-115-1-43","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"關於減重手術後的併發症，下列何者最適當？","options":["(A) sleeve gastrectomy術後胃食道逆流病（GERD）的發生率下降","(B) Roux-en-Y胃繞道術後最常見的營養缺乏為維生素B12和鐵缺乏","(C) 可調式胃束帶術（LAGB）的長期體重回升率較Roux-en-Y胃繞道術低","(D) 膽胰分流術合併十二指腸轉位術（BPD-DS）因繞道後作用的腸道變短，術後低血糖的風險最低"],"answer":1,"image":""},{"id":"md5-115-1-44","subject":"md5","topic":"消化器外科","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"關於急性胰臟炎的手術適應症，下列敘述何者最適當？","options":["(A) 對於嚴重型的急性胰臟炎，一旦確認就要及早進行手術清創","(B) 手術只有在感染性壞死或感染的積聚才建議執行","(C) 急性胰臟炎所造成的偽囊腫（pseudocyst）形成，一般是外引流比內引流較佳","(D) 偽囊腫（pseudocyst）形成時，選擇手術引流會優先於內視鏡引流"],"answer":1,"image":""},{"id":"md5-115-1-45","subject":"md5","topic":"消化器外科","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"胃食道逆流（gastroesophageal reflux disease, GERD）是相當常見的下食道疾病，通常是因為下食道括約肌的收縮功能異常，導致胃內容物逆流造成食道傷害。關於此疾病，下列敘述何者最不適當？","options":["(A) 大多數患者會出現胸口燒灼感（heartburn）的症狀","(B) 通常建議改變生活飲食習慣，如減肥、戒菸、少量多餐可減緩症狀","(C) 以制酸劑減少胃酸分泌，再加上改變生活飲食習慣可以治癒大多數患者","(D) 手術治療以重建下食道括約肌為主，需要實施近端胃部切除再重建"],"answer":3,"image":""},{"id":"md5-115-1-46","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"86歲男性病患因意識不清被送往急診室，到院呈重度昏迷，理學檢查血壓120/78 mmHg，心跳每分鐘82次，呼吸每分鐘12次，體溫36.5℃，兩眼瞳孔等距0.4公分，Glasgow coma scale：E1M1V1，血清生化檢查： +-+ glucose 92 mg/dL，ethanol＜10 mg/dL，Na 136 mEq/L，Cl 102 mEq/L，K 3.9 mEq/L，Ca 14.6 mg/dL，BUN 38 mg/dL，creatinine 1.4 mg/dL，SGOT 32 μIU/L，SGPT 24 μIU/L，下列何項處置最不適當？","options":["(A) 應檢驗血清磷及副甲狀腺素（PTH）以鑑別高血鈣症","(B) 應給與大量生理食鹽水灌注再給與thiazide","(C) 可給與雙磷酸鹽藥物（bisphosphonate）","(D) 可給與抑鈣素（calcitonin）"],"answer":1,"image":""},{"id":"md5-115-1-47","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"單側乳頭出現分泌物最常見病因為何？","options":["(A) intraductal papilloma","(B) fibroadenoma","(C) invasive breast cancer","(D) fibrocystic change"],"answer":0,"image":""},{"id":"md5-115-1-48","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"65歲停經女性，接受全乳切除手術（mastectomy），病理報告為8 cm之乳管原位癌（ductal carcinoma in situ, DCIS），前哨淋巴結取4顆均無轉移，影像並無懷疑之遠端轉移病灶，腫瘤之免疫染色顯示為：雌激素受體陽性（estrogen receptor, ER：95％）、黃體素受體陽性（progesterone receptor, PR：90％）、HER2/neu：0、Ki-67（MIB-1）：9％、grade 2，下列治療何者最適當？","options":["(A) 給與抗荷爾蒙藥物","(B) 因腫瘤大於5公分，需給與手術後放射線治療","(C) 因腫瘤大於5公分，需做輔助性化療","(D) 需做腫瘤基因檢測，作為後續治療的重要參考"],"answer":0,"image":""},{"id":"md5-115-1-49","subject":"md5","topic":"小兒外科","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"2歲男童因反覆無痛性大量暗紅色便（melena）至急診就醫。理學檢查穩定，腹部軟，無壓痛。實驗室顯示輕度貧血。懷疑Meckel diverticulum。下列那一項初步處置或診斷方式最適當？","options":["(A) 腹部X光可確定是否為Meckel diverticulum出血","(B) 立即行小腸攝影檢查確認病灶位置99m","(C) Tc-pertechnetate掃描檢查異位胃黏膜","(D) 安排腹腔鏡立即切除並送病理以確認診斷"],"answer":2,"image":""},{"id":"md5-115-1-50","subject":"md5","topic":"小兒外科","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"關於兒童腹股溝疝氣之敘述，下列何者最適當？","options":["(A) 兒童腹股溝疝氣發生的原因大多來自於大聲哭鬧，導致破壞腹壁肌肉組織強度，是直接型的疝氣（direct type）","(B) 治療方式，應該予以植入人工網膜來補強其結構","(C) 手術時機考量到麻醉的風險，應該年齡大於3歲或體重10公斤以上進行，較為安全","(D) 手術的併發症包括輸精管以及睪丸血管損傷等，不易於手術中察覺"],"answer":3,"image":""},{"id":"md5-115-1-51","subject":"md5","topic":"小兒外科","meta":"115年第1次第51題","year":115,"session":1,"number":51,"question":"關於威爾姆氏腫瘤（Wilms tumor）的敘述，下列何者錯誤？","options":["(A) 通常沒有明顯症狀，經常是照顧者意外觸摸所發現","(B) 癌細胞的來源是腎上腺細胞，在發育時產生變異，因此患者都有高血壓的問題","(C) 病理診斷可將腫瘤組織區分為有利的（favorable）與不利的（unfavorable）兩大類，對於治療以及預後，有相當大的關聯性","(D) 治療上以根除性手術切除為主，因此手術前完整的影像學檢查與計畫，攸關手術的成敗"],"answer":1,"image":""},{"id":"md5-115-1-52","subject":"md5","topic":"小兒外科","meta":"115年第1次第52題","year":115,"session":1,"number":52,"question":"附圖為兒童左頸部瘻管之顯影劑攝影（如圖一）和手術切口實際圖示（如圖二、圖三）。下方傷口為瘻管開口所在位置（如圖中①），上方傷口（如圖中②）靠近下頷（mandible）（如圖中③）。瘻管由下方傷口分離後（如圖二），移轉至上方傷口繼續向上分離後再進行結紮（如圖三）。下列何者最符合本病患之疾病？","options":["(A) 甲狀舌骨瘻管（thyroglossal duct fistula）","(B) 第一對鰓裂瘻管（1st branchial fistula）","(C) 第二對鰓裂瘻管（2nd branchial fistula）","(D) 梨狀竇瘻管（pyriform sinus fistula）"],"answer":[0,1,2,3],"image":"md5-115-1-52.jpeg","answer_note":"送分:第52題一律給分 (原公告答案 C)"},{"id":"md5-115-1-53","subject":"md5","topic":"小兒外科","meta":"115年第1次第53題","year":115,"session":1,"number":53,"question":"關於兒童誤食或誤吸入異物的相關敘述，下列何者最不恰當？","options":["(A) 花生可能阻塞氣道造成支氣管擴張症（bronchiectasis），也容易因為其中的油脂成分引起氣道刺激與肺炎","(B) 氣道異物吸入，最常見的停留位置是左側支氣管","(C) 硬幣卡在上食道時，可嘗試使用咽喉鏡（laryngoscopy）輔助取出","(D) 若誤食電池且在食道停留時間過久，可能引起食道黏膜及周邊組織的傷害，可以視為急症"],"answer":1,"image":""},{"id":"md5-115-1-54","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"115年第1次第54題","year":115,"session":1,"number":54,"question":"關於大腸直腸外科術後加速康復計畫（enhanced recovery protocol, ERP）的術前及術中處置，下列敘述何者正確？","options":["(A) 術前僅使用機械性腸道準備即可有效降低術後感染風險","(B) 進行左側或直腸切除手術時，機械性腸道準備結合口服抗生素是目前常見的術前準備方式","(C) 硫噴妥鈉（gabapentin）和鴉片類藥物是術後疼痛管理的首選方式，可促進腸功能恢復","(D) 腹腔引流管應常規使用，以減少術後感染及腸道功能障礙"],"answer":1,"image":""},{"id":"md5-115-1-55","subject":"md5","topic":"消化器外科","meta":"115年第1次第55題","year":115,"session":1,"number":55,"question":"為促進肝膽微創手術的完成，下列敘述何者正確？","options":["(A) 所有的切肝手術都需要Pringle手法","(B) 為有效控制減少手術出血，Pringle手法通常在整個手術中持續使用，手術完成再鬆開","(C) 氣腹手術中的低血壓，一旦懷疑gas emboli，應該給予病人頭高腳低左側躺，並考慮用中央靜脈導管抽出心室中的空氣","(D) 如果懷孕病人需要手術，應儘量安排在妊娠中期（second trimester）進行"],"answer":3,"image":""},{"id":"md5-115-1-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第1次第56題","year":115,"session":1,"number":56,"question":"有關骨骼肌肉系統腫瘤活體組織切片（biopsy）的敘述，下列何者最適當？","options":["(A) 在四肢部位應採用與肢體長軸線呈橫向（transverse）切開傷口","(B) 臨床症狀及影像學檢查皆已臆斷為骨骼肌肉系統腫瘤的個案時，仍需同時執行切片部位的細菌培養","(C) 執行核心（core）或細針（fine-needle）活體組織切片時，應儘可能經由兩個腔室間的筋膜平面（fascial plane）穿刺進入","(D) 對於一位病史不明，但高度懷疑為病理性肱骨骨折的患者，仍應緊急執行開放性手術復位和髓內釘固定及活體組織切片手術，術後再進行全身腫瘤探查（survey）與分級（staging）"],"answer":1,"image":""},{"id":"md5-115-1-57","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第1次第57題","year":115,"session":1,"number":57,"question":"有關骨肉瘤（osteosarcoma）的敘述，下列何者最不適當？","options":["(A) 原發性傳統骨肉瘤（conventional osteosarcoma）的治療包括：術前新輔助（neoadjuvant）化學治療、廣泛性腫瘤切除及術後輔助（adjuvant）化學治療","(B) 依世界衛生組織（WHO）對各種次分類的預後比較，以次發性骨肉瘤最差，其次是原發性傳統骨肉瘤（conventional osteosarcoma），而骨膜外（parosteal）骨肉瘤較佳","(C) 原發性傳統骨肉瘤（conventional osteosarcoma）患者的病理切片中，依接受術前化學治療後的腫瘤細胞壞死百分率，可以約略推測此患者的預後","(D) Ollier氏症及Maffucci氏症候群的患者，最常發生惡性化轉型（malignant transformation）成為次發性骨肉瘤"],"answer":3,"image":""},{"id":"md5-115-1-58","subject":"md5","topic":"骨科-關節重建","meta":"115年第1次第58題","year":115,"session":1,"number":58,"question":"有關骨質疏鬆症（ostepoporosis）之敘述，下列何者最不適當？","options":["(A) 原發性（primary）第一型骨質疏鬆症，是女性荷爾蒙缺乏導致","(B) 次發性（secondary）骨質疏鬆症的常見原因之一是荷爾蒙失調","(C) 雙磷酸鹽（bisphosphonates）的主要機轉是作用在蝕骨細胞（osteoclast）上","(D) 副甲狀腺素荷爾蒙（parathyroid hormone）的主要作用機轉之一是抑制蝕骨細胞（osteoclast）的功能"],"answer":3,"image":""},{"id":"md5-115-1-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"115年第1次第59題","year":115,"session":1,"number":59,"question":"下列X光片的骨折診斷，何者最適當？","options":["(A) Colles fracture","(B) Galeazzi fracture","(C) boxer's fracture","(D) Monteggia fracture"],"answer":3,"image":"md5-115-1-59.jpeg"},{"id":"md5-115-1-60","subject":"md5","topic":"泌尿-結石與感染","meta":"115年第1次第60題","year":115,"session":1,"number":60,"question":"35歲男性因車禍導致骨盆骨折，血壓穩定，但身體診察發現有血液從陰莖的尿道口流出。應最優先考慮下列何者？","options":["(A) 立即放置導尿管","(B) 骨盆腔的超音波檢查","(C) 動脈攝影檢查及血管栓塞治療","(D) 動態性逆行性尿道造影術檢查"],"answer":3,"image":""},{"id":"md5-115-1-61","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"115年第1次第61題","year":115,"session":1,"number":61,"question":"有關典型的外傷性肩關節前向脫臼（anterior dislocation）之敘述，下列何者最不適當？","options":["(A) 30歲以下的年輕人較常發生","(B) 也會發生在老年人，而且常有合併傷害","(C) 常發生Bankart氏病灶（Bankart lesion）","(D) 年輕人不易發生復發，通常不需手術治療"],"answer":3,"image":""},{"id":"md5-115-1-62","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第1次第62題","year":115,"session":1,"number":62,"question":"有關先天性併指症（syndactyly）的敘述，下列何者最不適當？","options":["(A) 複合併指（complex syndactyly）除軟組織的黏合之外，骨骼亦有黏合","(B) 單純併指（simple syndactyly）及複合併指（complex syndactyly）都呈現皮膚黏合","(C) 較常發生在第四蹼間（fourth web space）","(D) 較少發生在第一蹼間（first web space）"],"answer":2,"image":""},{"id":"md5-115-1-63","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第1次第63題","year":115,"session":1,"number":63,"question":"有關Scheuermann氏駝背症（Scheuermann kyphosis）的敘述，下列何者最適當？","options":["(A) 角度介於20至45度，且其角度不會隨年齡而增加","(B) 可合併脊柱側彎","(C) 椎體出現軟骨內骨化（enchondral ossification）異常，蛋白聚醣（proteoglycan）較低","(D) 平均身高較矮，骨齡（bone age）偏向早熟"],"answer":1,"image":""},{"id":"md5-115-1-64","subject":"md5","topic":"泌尿-結石與感染","meta":"115年第1次第64題","year":115,"session":1,"number":64,"question":"感染性結石最常見相關的細菌是：","options":["(A) 克雷伯氏肺炎菌（Klebsiella pneumoniae）","(B) 綠膿桿菌（Pseudomonas aeruginosa）","(C) 金黃色葡萄球菌（Staphylococcus aureus）","(D) 奇異變形桿菌（Proteus mirabilis）"],"answer":3,"image":""},{"id":"md5-115-1-65","subject":"md5","topic":"泌尿-腫瘤","meta":"115年第1次第65題","year":115,"session":1,"number":65,"question":"依據Bosniak classification的分類，下列有關腎臟囊泡（renal cysts）的敘述，何者錯誤？","options":["(A) type I屬於單純平滑內壁及含清澈液體之腎臟囊泡（simple and smooth-walled, with clear fluid）","(B) type II腎臟囊泡有33%惡性腫瘤機率","(C) type IIF腎臟囊泡有18%以上惡性腫瘤機率","(D) type IV腎臟囊泡有90%以上惡性腫瘤機率"],"answer":[1,2],"image":"","answer_note":"更正:第65題答Ｂ或Ｃ或BC者均給分"},{"id":"md5-115-1-66","subject":"md5","topic":"泌尿-腫瘤","meta":"115年第1次第66題","year":115,"session":1,"number":66,"question":"臨床上使用RENAL scoring系統來評估腎臟手術的複雜性，下列何者不是RENAL score的評估項目？","options":["(A) 腫瘤直徑大小（tumor radius）","(B) 與集尿系統的距離（nearness to collecting system）","(C) 腫瘤包埋在腎實質的深度（endo/exophytic）","(D) 與腎動脈的距離"],"answer":3,"image":""},{"id":"md5-115-1-67","subject":"md5","topic":"泌尿-腫瘤","meta":"115年第1次第67題","year":115,"session":1,"number":67,"question":"下列有關攝護腺癌之敘述，何者錯誤？","options":["(A) 肛門指診如有發現硬塊，應要懷疑腫瘤的可能性","(B) 主要為腺癌（adenocarcinoma）","(C) 骨轉移多為osteoclastic lesion","(D) 最常發生在攝護腺peripheral zone"],"answer":2,"image":""},{"id":"md5-115-1-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"115年第1次第68題","year":115,"session":1,"number":68,"question":"下列有關良性前列腺增生（benign prostatic hyperplasia）病理學的敘述，何者最不恰當？","options":["(A) 良性前列腺增生主要發生在前列腺過渡區（transition zone）","(B) 前列腺是由基質和上皮兩種成分組成，基質中的平滑肌過度增生造成良性前列腺增生，所以使用α腎上腺素受體阻斷劑治療可以有效解除良性前列腺增生患者的症狀","(C) 上皮增生造成的良性前列腺增生患者，使用5α-還原酶抑制劑（5 alpha-reductase inhibitors）的效果可能更好","(D) 當過渡區（transition zone）中的良性前列腺結節增大時，它們會壓縮前列腺的中央區（central zone），從而形成所謂的手術包膜（surgical capsule）"],"answer":3,"image":""},{"id":"md5-115-1-69","subject":"md5","topic":"泌尿-結石與感染","meta":"115年第1次第69題","year":115,"session":1,"number":69,"question":"下列有關急性腎盂腎炎（acute pyelonephritis）的描述，何者最不正確？","options":["(A) 最常見的感染細菌是大腸桿菌","(B) 通常來自膀胱細菌的上行性感染","(C) 一般給與抗生素治療3到5天","(D) 病人通常會有發燒及腰部酸痛的現象"],"answer":2,"image":""},{"id":"md5-115-1-70","subject":"md5","topic":"泌尿-結石與感染","meta":"115年第1次第70題","year":115,"session":1,"number":70,"question":"有關福尼爾壞疽（Fournier gangrene），下列敘述何者最不正確？","options":["(A) 常見於血糖控制不良的糖尿病患者","(B) 常見於曾有泌尿道外傷、尿道狹窄、或性病病史的病人","(C) 常合併尿路感染、副睪炎或肛門周邊膿瘍","(D) 細菌感染沿著深層筋膜蔓延"],"answer":3,"image":""},{"id":"md5-115-1-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"115年第1次第71題","year":115,"session":1,"number":71,"question":"陰莖勃起充血時，可以分成0～7個phases（flaccid；latent；tumescence；full erection；rigid erection；initial detumescence；slow detumescence；fast detumescence），其中血流量在那一個phase最少？","options":["(A) tumescence","(B) full erection","(C) rigid erection","(D) detumescence"],"answer":2,"image":""},{"id":"md5-115-1-72","subject":"md5","topic":"消化器外科","meta":"115年第1次第72題","year":115,"session":1,"number":72,"question":"在施行肝癌（HCC）病人之血管栓塞術時，除了主要的動脈血管供應為左肝或右肝動脈外，偶會發現肝癌存在其他的肝外腫瘤血管供應（extrahepatic blood supply），其中以下列何種血管最常見？","options":["(A) 內乳動脈（internal mammary artery）","(B) 下腸繫膜動脈（inferior mesenteric artery）","(C) 右側橫膈膜下動脈（right inferior phrenic artery）","(D) 網膜動脈（omental artery）"],"answer":2,"image":""},{"id":"md5-115-1-73","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"115年第1次第73題","year":115,"session":1,"number":73,"question":"35歲女性病人主訴下腹疼痛，超音波檢查發現疑似右側卵巢腫塊，電腦斷層檢查呈現如圖，箭號所示最有可能的診斷為何？","options":["(A) dermoid cyst","(B) endometrioma","(C) theca lutein cyst","(D) cystadenocarcinoma"],"answer":0,"image":"md5-115-1-73.jpeg"},{"id":"md5-115-1-74","subject":"md5","topic":"骨科-關節重建","meta":"115年第1次第74題","year":115,"session":1,"number":74,"question":"49歲男性，長期酗酒，近3個月來開始覺得左髖部附近疼痛。附圖為X光及磁振造影（T1WI）影像，最可能的診斷為何？","options":["(A) avascular necrosis of the femoral head","(B) severe osteoarthritis of the hip","(C) osteogenic sarcoma of the femur","(D) eosinophilic granuloma of the femur"],"answer":0,"image":"md5-115-1-74.jpeg"},{"id":"md5-115-1-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"115年第1次第75題","year":115,"session":1,"number":75,"question":"有關泌尿系統急症，下列敘述何者最不適當？","options":["(A) 當有泌尿系統外傷時，血尿程度與損傷嚴重程度未必有正相關","(B) 懷疑有膀胱破裂時，診斷的黃金標準為逆行性膀胱攝影","(C) 腎損傷的分級主要是與腎臟需要手術修復及腎切除術相關","(D) 當尿道口有血時，可放導尿管引流，以監控出血量及排尿量"],"answer":3,"image":""},{"id":"md5-115-1-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"115年第1次第76題","year":115,"session":1,"number":76,"question":"腔室症候群（compartment syndrome）的治療下列何者最不適當？","options":["(A) 生理食鹽水1,000～2,000 mL單次快速輸注","(B) 乳酸林格氏液每小時1,000 mL輸注","(C) 監測鉀離子濃度","(D) 監測尿量"],"answer":1,"image":""},{"id":"md5-115-1-77","subject":"md5","topic":"外科-休克創傷傷口","meta":"115年第1次第77題","year":115,"session":1,"number":77,"question":"關於哺乳動物咬傷的傷口，下列何者最不適當？","options":["(A) 貓咬傷之傷口感染，常因巴斯德氏菌（Pasteurella multocida）引起","(B) 任何部位的哺乳動物咬傷，均屬高感染風險傷口","(C) 哺乳動物咬傷臉部或頭皮之傷口，可考慮初級縫合","(D) 人類咬傷的傷口大都是多重細菌感染，最常見的細菌為葡萄球菌和鏈球菌"],"answer":1,"image":""},{"id":"md5-115-1-78","subject":"md5","topic":"醫學倫理與法規","meta":"115年第1次第78題","year":115,"session":1,"number":78,"question":"「醫師在對病患執行治療前，必須先取得其同意」。下列對「同意」的描述，何者最不恰當？","options":["(A) 「同意」是指「個別病患對所接受醫療介入之自主授權」","(B) 「同意」包含告知（disclosure）、能力（capacity）、自願（voluntariness）這三個要素","(C) 為病人抽血時，當病人捲起袖子、伸出手臂時，即意謂他同意接受抽血檢查","(D) 簽妥同意書就代表完成「同意」的過程"],"answer":3,"image":""},{"id":"md5-115-1-79","subject":"md5","topic":"醫學倫理與法規","meta":"115年第1次第79題","year":115,"session":1,"number":79,"question":"李先生患末期腎病洗腎多年，1年前結婚並生有一女。妻子考慮活體捐腎給李先生，但妻子的娘家都反對。關於本案之處置，下列敘述何者最恰當？","options":["(A) 李先生結婚未滿2年，妻子目前捐腎不符我國法律","(B) 妻子捐腎，李先生同意即可","(C) 妻子捐腎需出具娘家最近親屬之書面證明","(D) 妻子年齡須大於18歲方可捐腎"],"answer":2,"image":""},{"id":"md5-115-1-80","subject":"md5","topic":"醫學倫理與法規","meta":"115年第1次第80題","year":115,"session":1,"number":80,"question":"曹女士90歲患肺癌末期，有多處轉移合併肺功能衰竭，主治王醫師將進行家庭會議。下列敘述何者最不適當？","options":["(A) 王醫師應自我介紹並知道在場人士與病人的關係","(B) 以開放問句了解曹女士和家人對病情的態度","(C) 家庭會議不應預設目標，以開放態度進行醫病溝通","(D) 會議中應注意曹女士的身心狀態，及時以適當的方式回應"],"answer":2,"image":""},{"id":"md5-115-2-1","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"50歲女性因為急性膽囊炎而接受緊急傳統剖腹式膽囊切除術（open cholecystectomy）。術後第一天病人發燒至39.5 ℃，右上腹的傷口十分疼痛，微微發紅並有分泌物由傷口流出，故將分泌物做革蘭氏染色（Gram stain）。下列那個檢查結果最能代表傷口感染是由於梭狀芽孢菌屬（Clostridium）細菌造成？","options":["(A) 革蘭氏陽性桿菌","(B) 革蘭氏陽性球菌","(C) 革蘭氏陰性桿菌","(D) 革蘭氏陰性球菌"],"answer":0,"image":""},{"id":"md5-115-2-2","subject":"md5","topic":"胸腔外科","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"有關外傷氣胸（pneumothorax）的敘述，下列何者最適當？","options":["(A) 開放性氣胸不會發展成增壓性氣胸","(B) 對於增壓性氣胸的外傷病人，只要在前胸放置大號針頭減壓後，無須再放置胸管","(C) 胸部X光檢查看到的少量皮下氣腫，通常是因為氣胸造成","(D) 只要胸部X光檢查看到氣胸的存在，均需放置胸管"],"answer":2,"image":""},{"id":"md5-115-2-3","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"28歲陳小姐因近期發現頸部腫大，至外科門診就診。超音波檢測發現右側甲狀腺有3×2公分之單一結節，經fine needle aspiration（FNA）細胞學檢驗為疑似惡性，建議安排甲狀腺切除手術。手術醫師於術前充分告知陳小姐此次甲狀腺手術可能發生之併發症，下列何者錯誤？","options":["(A) 單側喉返神經若受損，發生呼吸困難的風險很高","(B) 一旦發生呼吸道損害（如：氣道損傷），可能須進行暫時或永久性氣管切開術","(C) 若發生暫時性之副甲狀腺功能低下，大多數病例在6個月內會消退","(D) 術後頸部血腫有機會造成呼吸困難，必要時須緊急切開傷口進行引流減壓"],"answer":0,"image":""},{"id":"md5-115-2-4","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"對於腹腔內纖維瘤（desmoid fibromatosis）的治療，下列敘述何者錯誤？","options":["(A) 傳統上，切除腫瘤和大範圍正常組織是標準治療方法","(B) 由於極少轉移，於手術切除後，大多不會局部復發","(C) 放射治療主要用作無法完整手術切除後的輔助治療","(D) 全身性治療方案包括抗荷爾蒙療法、非類固醇抗發炎藥物（NSAID）、低劑量化療、酪胺酸激酶抑制劑（tyrosine kinase inhibitors, TKI）和全劑量化療"],"answer":1,"image":""},{"id":"md5-115-2-5","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"對於微量營養素（micronutrients）硒元素（Selenium），下列敘述何者錯誤？","options":["(A) 其功用為增加細胞內的過氧化氫，保護細胞膜脂層（membrane lipids）免受氧化傷害","(B) 缺乏時將導致生長遲緩、肌肉疼痛和無力、肌肉病變、心肌病變","(C) 在細胞參與的免疫功能中起重要的作用；若發生缺陷，可能會導致甲狀腺激素代謝改變及血漿中麩胱甘肽（glutathione）濃度升高","(D) 每個麩胱甘肽過氧化氫酶（glutathione peroxidase）含有4個硒原子，主要功能是將游離的過氧化氫還原為水"],"answer":0,"image":""},{"id":"md5-115-2-6","subject":"md5","topic":"神經外科","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"關於創傷性腦損傷（TBI）的敘述，下列何者最適當？","options":["(A) 主要腦損傷（primary brain injury）可以透過藥物治療來逆轉","(B) 硬腦膜上血腫（epidural hematoma）常與橋靜脈（bridging veins）撕裂有關","(C) 頭部外傷後短暫喪失意識並出現清醒期（lucid interval），可能提示硬腦膜上血腫的發生","(D) 早期使用糖皮質類固醇（corticosteroids）可有效減少TBI患者的腦水腫並改善預後"],"answer":2,"image":""},{"id":"md5-115-2-7","subject":"md5","topic":"心臟血管外科","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"心絞痛（angina）需區分穩定和不穩定，有關不穩定心絞痛（unstable angina）的特徵，下列何者錯誤？","options":["(A) 越來越頻繁發生","(B) 疼痛程度增加","(C) 僅在做運動時會發生","(D) 疼痛持續更久的時間"],"answer":2,"image":""},{"id":"md5-115-2-8","subject":"md5","topic":"心臟血管外科","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"一位來到急診的病人被診斷為Stanford Type B主動脈剝離，並無神經學症狀、腹腔內器官缺血或下肢缺血等症狀，對這位病人最主要的治療方式為何？","options":["(A) 緊急手術治療","(B) 主動脈支架血管置放術","(C) 積極的降血壓藥物治療","(D) 心包膜穿刺引流"],"answer":2,"image":""},{"id":"md5-115-2-9","subject":"md5","topic":"心臟血管外科","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"對於一位罹患心房中膈缺損（ASD）合併Eisenmenger's syndrome的成人病患，下列何者治療最適當？","options":["(A) 外科手術關閉心房中膈缺損（ASD）","(B) 心內膜炎預防（infective endocarditis prophylaxis）","(C) 導管手術關閉心房中膈缺損（ASD）","(D) 居家氧氣治療"],"answer":[1,3],"image":"","answer_note":"更正:第9題答Ｂ或Ｄ或BD者均給分"},{"id":"md5-115-2-10","subject":"md5","topic":"胸腔外科","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"有關外傷張力性氣胸（tension pneumothorax）之敘述，下列何者最不適當？","options":["(A) 主要表徵為呼吸窘迫（respiratory distress）及低血壓（hypotension）","(B) 單側呼吸音消失或減弱（lack of or decreased breath sound）","(C) 可能有氣管偏移（tracheal deviation）或皮下氣腫（subcutaneous emphysema）","(D) 血氧飽和度（oxygen saturation）良好之病患，應先排除其他原因導致之低血壓"],"answer":3,"image":""},{"id":"md5-115-2-11","subject":"md5","topic":"消化器外科","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"關於高解析度食道壓力測試（high-resolution manometry motility study），下列何者最接近胃食道逆流的病人？","options":["(A) ","(B) ","(C) ","(D) "],"answer":0,"image":"md5-115-2-11.jpeg"},{"id":"md5-115-2-12","subject":"md5","topic":"胸腔外科","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"關於橫膈肌損傷修補的敘述，下列何者錯誤？","options":["(A) 鈍性橫膈肌損傷的修補通常經由腹部切開進入探查，以處理相關的內臟損傷","(B) 經腹部探查後，受傷的橫膈膜可使用粗的不可吸收縫線進行縫補","(C) 對於所有類型的橫膈肌損傷，胸腔鏡手術應為首選的介入治療方式，以減少不必要的傷害","(D) 大面積撕裂脫落的橫膈膜缺損，可使用人工或生物網片（mesh）進行修補"],"answer":2,"image":""},{"id":"md5-115-2-13","subject":"md5","topic":"消化器外科","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"有關腹股溝疝氣的危險因子，下列何者最不適當？","options":["(A) 慢性阻塞性肺病（chronic obstructive pulmonary disease）","(B) 肥胖","(C) 腹水","(D) 出生時體重超過3000克"],"answer":3,"image":""},{"id":"md5-115-2-14","subject":"md5","topic":"消化器外科","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"關於胃切除術後的傾倒症候群（dumping syndrome），下列敘述何者最適當？","options":["(A) early dumping syndrome是因為低血糖造成","(B) late dumping syndrome是因為高滲透壓的食物造成","(C) 飲食治療是dumping syndrome首選","(D) 全胃切除是手術的治療方式"],"answer":2,"image":""},{"id":"md5-115-2-15","subject":"md5","topic":"消化器外科","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"關於腸壁積氣（pneumatosis intestinalis），下列敘述何者最適當？","options":["(A) 通常看見腸壁積氣都需要手術切除","(B) 如果在嬰兒發現，需要懷疑壞死性腸炎（necrotizing enterocolitis）","(C) 大部分腸壁積氣都跟腹膜炎有關","(D) 腸壁積氣跟癌症沒有關聯"],"answer":1,"image":""},{"id":"md5-115-2-16","subject":"md5","topic":"消化器外科","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"關於二氧化碳氣腹（CO2 pneumoperitoneum），下列敘述何者正確？","options":["(A) 二氧化碳不易被腹膜吸收進入循環","(B) 若術中產生呼吸性酸中毒（respiratory acidosis），於肺功能正常的病人可藉由調整呼吸器之呼吸速率（ventilatory rate）或肺活量（vital capacity）來改善酸中毒之情況","(C) 體內最主要可吸收二氧化碳提供緩衝以減少產生呼吸性酸中毒的組織為肌肉","(D) 高碳血症（hypercarbia）會造成心搏過緩（bradycardia）及降低全身性血管阻力（systemic vascular resistance）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第16題一律給分 (原公告答案 B)"},{"id":"md5-115-2-17","subject":"md5","topic":"外科-併發症輸液營養感染","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"病人接受腹部手術後常會出現手術後腸阻塞（post-operative ileus），下列敘述何者錯誤？","options":["(A) 低血鉀、低血鈉、低血鎂會引起ileus，需適時矯正電解質異常","(B) 肺炎、腹膜炎、敗血症會引起ileus，需及時控制感染","(C) 咀嚼口香糖及使用紅黴素（erythromycin）是目前已被證實有效治療ileus的方式","(D) 類固醇類消炎止痛藥（nonsteroidal anti-inflammatory drug, NSAIDs）相較於嗎啡藥物，造成ileus的機率較低，可考慮作為術後止痛使用"],"answer":[2,3],"image":"","answer_note":"更正:第17題答Ｃ或Ｄ或CD者均給分"},{"id":"md5-115-2-18","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"下列何者不是器官移植後晚期感染的風險因子？","options":["(A) 免疫抑制劑的長期使用","(B) 受贈者既存的病毒感染","(C) 處在裝修中的工作環境","(D) 經常輸血"],"answer":3,"image":""},{"id":"md5-115-2-19","subject":"md5","topic":"外科-移植與外科腫瘤學","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"下列有關器官移植排斥的描述，何者正確？","options":["(A) 人類白血球抗原（human leukocyte antigen, HLA）是編碼人類的主要組織相容性複合體（major histocompatibility complex）的基因，它位在第6對染色體的短臂上，與人類的免疫系統功能有關","(B) 人類的主要組織相容性複合體（major histocompatibility complex）主要分為兩大類，其中第一類 + （class I HLA）是與CD4的T細胞結合後活化T細胞","(C) T細胞經由異種辨識（allorecognition）後經細胞內訊息傳遞，產生介白素-6（interleukin-6, IL-6）並活化T細胞","(D) 鈣調磷酸酶抑制劑（calcineurin inhibitor, CNI）可經由抑制異種辨識（allorecognition）途徑，阻斷T細胞被活化，進而達到抑制排斥的效果"],"answer":0,"image":""},{"id":"md5-115-2-20","subject":"md5","topic":"消化器外科","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"有關脾臟手術或相關處置，下列敘述何者最適當？","options":["(A) 脾臟摘除手術後，罹患encapsulated細菌感染（overwhelming postsplenectomy sepsis）的機會高，因此病人須長期服用抗生素","(B) 脾臟受傷後，若採用非手術治療，小孩比大人有較高的失敗率","(C) 若脾臟嚴重破裂，即使病人血壓不穩定，應用血管栓塞方式堵住脾臟動脈分枝減少出血，有必要時再手術較安全","(D) 脾臟受傷程度，可使用電腦斷層做評估"],"answer":3,"image":""},{"id":"md5-115-2-21","subject":"md5","topic":"神經外科","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"關於急性脊髓損傷（acute spinal cord injury, acute SCI）處理的敘述，下列何者最適當？","options":["(A) 皮質類固醇（corticosteroids）治療acute SCI已被證實可明顯改善長期功能預後，應作為標準治療","(B) 急性頸椎損傷患者應該儘早移除頸圈（cervical collar）以降低壓瘡的風險，即使尚未確定是否有骨折或不穩定性","(C) 對於不完全的急性脊髓損傷合併脊髓壓迫，手術減壓（spinal cord decompression）若能在24小時內進行，可能有助於改善神經功能","(D) 在所有疑似acute SCI的患者中，首選影像學檢查為磁振造影（MRI），因為MRI可清楚顯示骨骼和軟組織"],"answer":2,"image":""},{"id":"md5-115-2-22","subject":"md5","topic":"神經外科","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"有關頸椎脊髓病變（cervical myelopathy）之敘述，下列何者最適當？","options":["(A) 頸椎MRI沒有明顯顯示椎管的狹窄","(B) 深層肌腱反應（deep tendon reflex）會下降","(C) 臨床表現常合併肌肉痙攣（spasticity）或是肌陣攣（clonus）","(D) 感覺神經為正常"],"answer":2,"image":""},{"id":"md5-115-2-23","subject":"md5","topic":"神經外科","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"有關膠質細胞瘤（glioma）的敘述，下列何者最不適當？","options":["(A) 大多數原發性腦腫瘤是由神經膠質細胞或神經其他支持結構發展而來，統稱為神經膠質瘤","(B) 由於膠質瘤能夠沿著白質束廣泛浸潤，因此大部分膠質瘤可以完全手術切除","(C) 膠質瘤放射治療和化學療法的治療選擇，會根據腦腫瘤的組織學而有不同的治療方式","(D) 兒童瀰漫性橋腦膠質瘤（diffuse pontine glioma）臨床表現可能為多發性腦神經麻痺"],"answer":1,"image":""},{"id":"md5-115-2-24","subject":"md5","topic":"神經外科","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"有關顱內硬腦膜動靜脈瘻管（dural arteriovenous fistula）的相關敘述，下列何者最不適當？","options":["(A) 臨床症狀以頭痛為主，不會破裂出血","(B) 可能會演變成動靜脈畸形（arteriovenous malformation）","(C) 含第二型的頸動脈–海綿竇瘻管（carotid-cavernous fistula）","(D) 成因與靜脈竇栓塞有關"],"answer":0,"image":""},{"id":"md5-115-2-25","subject":"md5","topic":"神經外科","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"有關神經纖維瘤第一型（neurofibromatosis type 1, NF1）之敘述，下列何者錯誤？","options":["(A) NF1乃體染色體顯性（autosomal dominant）所致的基因突變（gene mutation）","(B) 基因突變（gene mutation）位於染色體17q11.2.","(C) 發展成惡性周邊神經鞘腫瘤（malignant peripheral nerve sheath tumor, MPNST）的機會約為10％","(D) 與schwannomas、gliomas的生成無關"],"answer":3,"image":""},{"id":"md5-115-2-26","subject":"md5","topic":"整形重建外科","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"先天性黑色素痣（congenital melanocytic nevi, CMN）直徑超過多少公分，惡性變化之可能最高？","options":["(A) ＜1.5公分","(B) 1.5～10公分","(C) 11～20公分","(D) ＞20公分"],"answer":3,"image":""},{"id":"md5-115-2-27","subject":"md5","topic":"整形重建外科","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"關於Guyon canal syndrome的敘述，下列何者錯誤？","options":["(A) Guyon canal由hook of the hamate、pisiform、piso-hamate ligament、palmar carpal ligament構成","(B) 可能造成正中神經壓迫","(C) 理學檢查可能出現Tinel sign","(D) 壓迫原因可能是ganglion、giant cell tumor、ulnar artery thrombosis"],"answer":1,"image":""},{"id":"md5-115-2-28","subject":"md5","topic":"整形重建外科","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"使用2.5％calcium gluconate gel治療一般氫氟酸（hydrofluoric acid）導致的傷口時，建議在疼痛緩解前，間隔多久需塗抺藥一次？","options":["(A) 15分鐘","(B) 30分鐘","(C) 60分鐘","(D) 90分鐘"],"answer":0,"image":""},{"id":"md5-115-2-29","subject":"md5","topic":"整形重建外科","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"影響疤痕形成的敘述，下列何者錯誤？","options":["(A) 一個不適宜的（unfavorable）疤痕形成肥厚性疤痕或蟹足腫，是由於過多的膠原蛋白（collagen）堆積造成的","(B) 肥厚性疤痕或和蟹足腫兩者的不同是前者在受傷後六個月即停止生長","(C) 在縫合的過程中最重要需要精確對齊的組織是表皮層（epidermis）以促進傷口癒合","(D) 可吸收（absorbable）縫線比不可吸收（nonabsorbable）縫線造成組織發炎（inflammation）反應的程度更強"],"answer":2,"image":""},{"id":"md5-115-2-30","subject":"md5","topic":"心臟血管外科","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"70歲女性患者至門診，主訴左腳疼痛到無法走路有一週，過去病史有長期抽菸和三高，檢視患者左腳如圖所示，患側量測之ankle-brachial index（ABI）：0.3，下一步的檢查或治療，何者不適當？","options":["(A) 診斷性動脈攝影（angiography）","(B) 口服阿斯匹靈（Aspirin）","(C) 口服抗凝血劑（Warfarin）","(D) 討論血管再暢通（revascularization）的策略：血管腔內治療（endovascular therapy）或繞道手術治療（bypass surgery）"],"answer":2,"image":"md5-115-2-30.jpeg"},{"id":"md5-115-2-31","subject":"md5","topic":"心臟血管外科","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"有關慢性下肢潰瘍，下列敘述何者最適當？","options":["(A) 不論動脈或靜脈型通常都是很痛的","(B) 靜脈潰瘍很少發生在足部","(C) 動脈潰瘍很少發生在腿部","(D) 腿部潰瘍對糖尿病患者的影響低於其他患者族群"],"answer":1,"image":""},{"id":"md5-115-2-32","subject":"md5","topic":"心臟血管外科","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"執行冠狀動脈繞道手術時，若使用橈動脈（radial artery）作為繞道的血管，下列敘述何者最適當？","options":["(A) 橈動脈與大隱靜脈比較，有較差的5年通暢率（patency rate），是因橈動脈有比較高的比率會發生血管痙攣（spasm）","(B) 橈動脈比大隱靜脈更不容易受到競爭血流（competitive flow）的影響，因此橈動脈更適合吻合至前端狹窄小於60％的冠狀動脈","(C) 所有迄今的研究報告均顯示使用橈動脈比使用大隱靜脈作為繞道血管，病人有較好的長期存活率","(D) 使用橈動脈作為繞道血管，須配合使用血管擴張劑以降低血管痙攣"],"answer":3,"image":""},{"id":"md5-115-2-33","subject":"md5","topic":"胸腔外科","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"下列有關於乳糜胸的敘述，何者最不適當？","options":["(A) 其乳糜主要成分為脂肪","(B) 最常見之原因為腫瘤侵犯造成","(C) 初始以支持性治療為原則，若失敗應儘速手術治療","(D) 手術治療以經胸結紮胸管為較常見之方式"],"answer":1,"image":""},{"id":"md5-115-2-34","subject":"md5","topic":"胸腔外科","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"關於縱膈腔神經源性腫瘤（neurogenic tumor）之敘述，下列何者最不適當？","options":["(A) 在兒童之惡性率較低","(B) 常見於後縱膈腔","(C) 成人最常見的是許旺氏細胞瘤（schwannoma）","(D) 許旺氏細胞瘤（schwannoma）可以來自任何胸神經（thoracic nerve）"],"answer":0,"image":""},{"id":"md5-115-2-35","subject":"md5","topic":"消化器外科","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"脾臟（spleen）可視為人類最大的淋巴器官，防禦莢膜形細菌有關鍵的免疫作用，因此脾臟切除之後有較高的風險發生特定的細菌感染，下列何種細菌的感染比較不常見？","options":["(A) 肺炎鏈球菌（Streptococcus pneumoniae）","(B) B型流感嗜血桿菌（Haemophilus influenzae type b）","(C) 新型隱球菌（Cryptococcus neoformans）","(D) 腦膜炎奈瑟菌（Neisseria meningitidis）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第35題一律給分 (原公告答案 C)"},{"id":"md5-115-2-36","subject":"md5","topic":"消化器外科","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"下列何種激素可被視為胃腸道內分泌系統的universal \"off\" switch，抑制胃酸分泌、腸道水分與電解質分泌以及多種內分泌激素的釋放？","options":["(A) 促胰液素（secretin）","(B) 胃動素（motilin）","(C) 血管活性腸肽（vasoactive intestinal peptide, VIP）","(D) 生長抑素（somatostatin）"],"answer":3,"image":""},{"id":"md5-115-2-37","subject":"md5","topic":"消化器外科","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"有關Caroli's疾病的敘述，下列何者最適當？","options":["(A) 肝內膽管先天性導管板（ductal plate）畸形所造成，其特徵是肝內膽管連續性囊性擴張","(B) 通常發生於肝硬化病人，並與囊性腎病有關","(C) 大部分發生於年輕人，男性和女性無差異","(D) 治療以肝臟切除術為主"],"answer":2,"image":""},{"id":"md5-115-2-38","subject":"md5","topic":"消化器外科","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"關於胰臟惡性腫瘤的手術，下列敘述何者最適當？","options":["(A) 手術中若發現肝臟轉移，肝門（hilum）淋巴有侵犯，若可清除宜繼續手術，因為胰臟癌預後不好","(B) 胰臟癌的Whipple procedure，併發症以膽汁滲漏最常見","(C) 胰臟神經內分泌腫瘤若轉移只限於肝臟，仍可進行肝臟移植","(D) 目前對於邊緣性切除手術（borderline resection）仍傾向先手術再化學治療，甚至放射線治療，來提高廓清率"],"answer":2,"image":""},{"id":"md5-115-2-39","subject":"md5","topic":"消化器外科","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"為了降低肝硬化病人接受肝癌切除手術後產生併發症，下列何者不是必要之術前準備？","options":["(A) 術前預防性抗生素","(B) 經皮穿肝膽汁引流（percutaneous transhepatic biliary drainage, PTBD）","(C) 補充適當的靜脈輸液","(D) 補充足夠的營養"],"answer":1,"image":""},{"id":"md5-115-2-40","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"三級副甲狀腺功能亢進症（tertiary hyperparathyroidism）較可能發生於下列何種情況？","options":["(A) 原發性副甲狀腺功能亢進症（primary hyperparathyroidism），成功治療後","(B) 低血鈣症（hypocalcemia）發生後","(C) 因慢性腎衰竭（chronic renal failure）進行腎移植（renal transplantation）後","(D) 甲狀腺切除術後"],"answer":2,"image":""},{"id":"md5-115-2-41","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"關於甲狀腺乳突癌（papillary thyroid carcinoma）的手術治療，下列敘述何者最不適當？","options":["(A) 高風險甲狀腺乳突癌或雙側腫瘤患者，應接受全甲狀腺切除術（total thyroidectomy）或近全切除術（near-total thyroidectomy）","(B) 手術後若需接受放射碘治療（RAI）患者，接受腫瘤側單葉切除即可","(C) 甲狀腺乳突癌若腫瘤大於1公分且小於4公分，且無甲狀腺外侵犯或淋巴結轉移（cN0）者，可視病患情況，施行甲狀腺全切除手術或腫瘤側單葉切除","(D) 對於小於1公分的微小甲狀腺乳突癌（papillary thyroid microcarcinoma）若無甲狀腺外侵犯或淋巴轉移可考慮先積極監測（active surveillance），暫不手術"],"answer":1,"image":""},{"id":"md5-115-2-42","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"40歲女性病人左頸不舒服兩個月，其左頸有個可隨吞嚥上下移動的腫塊約3公分。側頸部無明顯淋巴腫，脈搏每分鐘72次。無甲狀腺癌家族史，幼時未接受過頭頸部放射治療。頸超音波檢查發現左上甲狀腺後側方有一不規則含顯微鈣化結節長徑約3.23公分，下列處置何者最能提供確定訊息？","options":["(A) 抽血檢驗甲狀腺球蛋白（thyroglobulin），有助於鑑別良惡性","(B) 安排細針抽吸細胞學檢查，以鑑別良惡性","(C) 安排核醫甲狀腺掃描，有助於排除惡性結節","(D) 安排甲狀腺核磁共振掃描，有助於排除惡性結節"],"answer":1,"image":""},{"id":"md5-115-2-43","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"33歲女性發現右側乳房有一硬塊，已持續約兩週未消退。臨床上懷疑有惡性病變的可能性。針對年齡「30歲以上未滿40歲」且可觸及的病灶，下列進一步評估檢查或處置，何者最適當？","options":["(A) 直接安排乳房超音波導引細針抽吸細胞學檢查（fine needle aspiration cytology）","(B) 建議直接手術切除腫瘤，送病理化驗","(C) 先做乳房超音波（breast ultrasound），必要時搭配診斷性乳房攝影（mammogram）","(D) 由於年紀輕女性多屬緻密乳房，應先做乳房磁振造影檢查（MRI）"],"answer":2,"image":""},{"id":"md5-115-2-44","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"35歲女性，母親有乳癌病史。病患進行乳房MRI檢查，報告顯示右側乳房有一個直徑1.5 cm的病灶，動態影像呈現快速增強後迅速消退（washout pattern）。對此影像結果，下列何者最符合下一步處置？","options":["(A) 粗針切片（core needle biopsy）","(B) 進行正子攝影PET-CT確認","(C) 安排手術切除腫瘤","(D) 乳房X光攝影（mammogram）檢查若未見異常，每半年追蹤"],"answer":0,"image":""},{"id":"md5-115-2-45","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"45歲女性右側乳房有一硬塊，報告顯示腫瘤可能為乳腺小葉癌（invasive lobular carcinoma），此類腫瘤常見的特別影像表現為何？","options":["(A) 清晰邊緣和單一腫塊","(B) 擴散性分布，邊緣模糊","(C) 高回聲且伴隨血流訊號增加","(D) 腫塊內鈣化均勻分布"],"answer":1,"image":""},{"id":"md5-115-2-46","subject":"md5","topic":"小兒外科","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"一名出生第10天、體重950克的早產兒，開始經口餵食後幾天，出現進食不耐、腹部脹大、觸摸時有壓痛，並觀察到糞便中帶有血絲。護理師回報體溫不穩定、偶有呼吸暫停與心跳過慢。腹部X光顯示腸壁內有氣體（pneumatosis intestinalis）。初步懷疑是壞死性腸炎（necrotizing enterocolitis），接續處置下列何者最適當？","options":["(A) 口服抗生素治療","(B) 安排上消化道攝影確認是否造成腸道狹窄","(C) 立即手術治療切除可疑腸段，必要時進行空腸造口","(D) 禁食，並放置口胃管引流，給與輸液與廣效抗生素治療"],"answer":3,"image":""},{"id":"md5-115-2-47","subject":"md5","topic":"小兒外科","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"承上題，若此早產兒後續腹部X光發現門靜脈有空氣（portal venous gas），且有自由氣體（free air），且生命徵象也不穩定，團隊決定下一步於床邊進行治療。下列何者為最適合目前病況的治療？","options":["(A) 正中垂直開腹手術，切除壞死腸道並行腸道吻合","(B) 正中橫向開腹手術，切除壞死腸道並行空腸造口","(C) 放置腹膜引流管，以減壓與減少感染","(D) 放置中央靜脈導管，增加輸液的量"],"answer":2,"image":""},{"id":"md5-115-2-48","subject":"md5","topic":"泌尿-腫瘤","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"門診有一位國中男生，14歲，主訴為左側陰囊腫大，經診所醫師轉診，懷疑為睪丸腫瘤。下列處置何者錯誤？","options":["(A) 理學檢查必須仔細，排除睪丸受傷，陰囊水腫，或是腹股溝疝氣","(B) 若為惡性腫瘤，標準的術式為根除性睪丸切除（radical inguinal orchiectomy），包括鼠蹊部整條精索","(C) 腫瘤指數（tumor markers）是日後追蹤治療效果的指標，最重要的是癌胚（胎）抗原（carcinoembryonic antigen, CEA）以及攝護腺特定抗原（prostate specific antigen, PSA）","(D) 如果懷疑是惡性睪丸腫瘤，必須在手術前完成所有的影像學檢查，做為期別診斷"],"answer":2,"image":""},{"id":"md5-115-2-49","subject":"md5","topic":"小兒外科","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"一幼兒因嘔吐帶黃綠色乳狀物求診，腹部超音波檢查所見如附圖，右圖為左圖附近切面彩色都卜勒之影像。下列何種病況最符合此腹部超音波所見？","options":["(A) 腸旋轉不良（malrotation）","(B) 腸扭轉（volvulus）","(C) 腸套疊（intussusception）","(D) 腹腔內腫瘤（intraabdominal tumor）"],"answer":1,"image":"md5-115-2-49.jpeg"},{"id":"md5-115-2-50","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"下列有關尿道下裂之敘述，何者最適當？","options":["(A) 常合併陰莖背面纖維黏連（dorsal chordee）","(B) 陰莖腹面包皮（ventral foreskin）缺損為其外觀特徵","(C) 病童須接受荷爾蒙評估（hormone studies）和染色體核型分析（chromosome karyotyping）","(D) 病童尿道海綿體（corpus spongiosum）發育缺失，所以矯正手術步驟包含尿道海綿體重建"],"answer":1,"image":""},{"id":"md5-115-2-51","subject":"md5","topic":"小兒外科","meta":"115年第2次第51題","year":115,"session":2,"number":51,"question":"Wilms腫瘤與下列何種基因異常最相關？","options":["(A) WT1、WT2基因突變","(B) N-MYC擴增（amplification）","(C) p53基因突變","(D) RET基因突變"],"answer":0,"image":""},{"id":"md5-115-2-52","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"115年第2次第52題","year":115,"session":2,"number":52,"question":"67歲男性，因排便習慣改變及間歇性腹痛就診。大腸鏡檢查發現一個位於左側結腸的大型腫瘤。進一步影像學檢查顯示該腫瘤侵及腸壁外組織（cT3），但無淋巴結（N0）或遠端轉移（M0）的跡象，其臨床期別為cT3N0M0。針對此患者，下一步最適合的治療策略為何？","options":["(A) 新輔助化學治療（neoadjuvant chemotherapy）","(B) 內視鏡下局部切除腫瘤（endoscopic submucosal dissection, ESD）","(C) 結腸腫瘤的部分結腸切除併淋巴結清除手術（colonic resection with radical lymph nodes dissection）","(D) 術前輔助化學放療（neoadjuvant concurrent chemoradiotherapy, neoadjuvant CCRT）"],"answer":2,"image":""},{"id":"md5-115-2-53","subject":"md5","topic":"大腸直腸與內視鏡外科","meta":"115年第2次第53題","year":115,"session":2,"number":53,"question":"陳伯伯因腹痛、腹脹於急診求助，經診斷為乙狀結腸腸扭轉；此時，住院醫師發現陳伯伯出現發燒、心跳加速，左下腹部有局部壓痛合併反彈痛（rebounding tenderness），下列臨床處置或敘述何者較不適當？","options":["(A) 給與靜脈輸液，矯正體液及電解質之異常","(B) 安排緊急大腸鏡檢查，嘗試將腸扭轉復位減壓","(C) 懷疑有敗血症應行血液培養及投與抗生素治療","(D) 安排緊急剖腹探查手術"],"answer":1,"image":""},{"id":"md5-115-2-54","subject":"md5","topic":"消化器外科","meta":"115年第2次第54題","year":115,"session":2,"number":54,"question":"氣腹（pneumoperitoneum）是進行腹腔鏡手術時開展術野的重要手段。有關氣腹及其生理影響的敘述，下列何者錯誤？","options":["(A) 目前最常用來製造氣腹的氣體是二氧化碳","(B) 氣腹壓力不足會使術野受限，手術難以進行；壓力太高又會影響病患生理機能，臨床上適當壓力約在12至15毫米汞柱（mmHg）之間","(C) 二氧化碳會經由腹膜吸收進入血液循環中，形成碳酸導致酸血症。臨床上這些碳酸主要靠腎臟排出","(D) 建立氣腹時，灌注氣體過快可能會刺激迷走神經活性，導致心搏過緩甚至低血壓，需要暫時消氣並給與迷走神經抑制劑"],"answer":2,"image":""},{"id":"md5-115-2-55","subject":"md5","topic":"消化器外科","meta":"115年第2次第55題","year":115,"session":2,"number":55,"question":"對於遠端胃癌病人接受部分胃切除手術（gastrectomy）及D2淋巴結清除手術步驟的描述，下列何者錯誤？","options":["(A) 需結紮血管：右及左胃網膜動脈（right and left gastroepiploic artery (or right gastro-omental artery)）、上腸繫膜動脈（superior mesenteric artery）、左胃動脈（left gastric artery）、右胃動脈（right gastric artery）","(B) 切除手術範圍，包括切除胃幽門及胃竇（antrum），取決於腫瘤位置及手術安全距離","(C) 殘留胃重建方式：胃–十二指腸吻合或胃–空腸吻合","(D) D2淋巴結清除須清除胃小彎、胃大彎、門靜脈（portal vein）、總肝動脈（common hepatic artery）、脾臟附近的淋巴結，而且需要清除至少15顆淋巴結"],"answer":0,"image":""},{"id":"md5-115-2-56","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第2次第56題","year":115,"session":2,"number":56,"question":"有關骨代謝疾病的敘述，下列何者最適當？","options":["(A) 棕色腫瘤（brown tumor）是一種骨代謝異常疾病，經由局部病灶腫瘤採樣即可確認診斷","(B) Gaucher氏病（Gaucher disease）是家族性疾病，會造成肝臟、脾臟腫大及骨壞死（bone infarct）","(C) 佩吉特骨病（Paget disease）在病灶處的骨母細胞（osteoblast）會出現包涵體（inclusion bodies），因此推測與病毒感染有關","(D) 佩吉特骨病（Paget disease），好發於年輕族群，X光攝影可能出現骨生成（osteoblastic change）或蝕骨（osteolytic change）現象"],"answer":1,"image":""},{"id":"md5-115-2-57","subject":"md5","topic":"骨科-關節重建","meta":"115年第2次第57題","year":115,"session":2,"number":57,"question":"關於附圖髖關節正位前後照（AP view）中各個解剖標記（landmarks）的敘述，何者最不適當？","options":["(A) 編號1的實線為髂恥線（iliopectineal line），起始自髂骨（ilium）的坐骨大切跡（greater sciatic notch），向下往恥骨結節（pubic tubercle）延伸","(B) 編號2的虛線為髂坐線（ilioischial line），是由髂骨（ilium）方形區（quadrilateral surface）的後側五分之四所構成","(C) 編號5的實線為髖臼頂（roof of the acetabulum）","(D) 編號6的虛線為髖臼後唇的邊緣（edge of the posterior lip of the acetabulum）"],"answer":2,"image":"md5-115-2-57.jpeg"},{"id":"md5-115-2-58","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第2次第58題","year":115,"session":2,"number":58,"question":"有關掌腱膜攣縮症（Dupuytren contracture）的敘述，下列何者最不適當？","options":["(A) 好發於男性","(B) 歐洲人比亞洲人少見","(C) 早期病人可考慮保守治療","(D) 常侵犯掌指關節"],"answer":1,"image":""},{"id":"md5-115-2-59","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"115年第2次第59題","year":115,"session":2,"number":59,"question":"關於肩關節盂肱關節（glenohumeral joint）的解剖結構，下列敘述何者最適當？","options":["(A) 盂肱韌帶（glenohumeral ligaments）是界線分明的帶狀韌帶，其膠原纖維呈平行排列","(B) 肩胛骨與胸廓之間存在一個真正的滑液關節（synovial joint）","(C) 鎖骨是上肢與中軸骨骼之間唯一的骨性連接","(D) 肩盂窩（glenoid）的關節面積，約為肱骨頭（humeral head）的二分之一，提供了良好的穩定性"],"answer":2,"image":""},{"id":"md5-115-2-60","subject":"md5","topic":"骨科-腫瘤小兒手脊椎","meta":"115年第2次第60題","year":115,"session":2,"number":60,"question":"一位3歲的男孩，被診斷為先天性脊柱側彎。X光片顯示在T8～T9處，有一個單側分節缺陷（unilateral bar），對側有一個完整的半椎體（hemivertebra），下列那一項關於治療和預後的判斷最適當？","options":["(A) 患者年齡小，重塑潛力很大，應以觀察為主","(B) 以矯正背架設法延遲手術至骨骼成熟","(C) 應立即進行脊柱牽引，以減輕畸形處的壓力","(D) 這種畸形組合通常會導致快速彎曲惡化，需考慮早期手術來阻止進展"],"answer":3,"image":""},{"id":"md5-115-2-61","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"115年第2次第61題","year":115,"session":2,"number":61,"question":"一位25歲籃球選手跳起落地時，聽到右膝「啪」一聲，隨後膝關節劇痛無法伸直。理學檢查發現右膝屈曲無法完全伸直，Lachman test陽性，anterior drawer test陽性。磁振造影顯示前十字韌帶完全斷裂合併外側半月板破裂。下列關於治療的敘述何者最適當？","options":["(A) 前十字韌帶重建必須延遲至傷後6個月，以降低關節僵硬風險","(B) 年輕運動員應優先考慮前十字韌帶初級修補，而非重建","(C) 前十字韌帶重建後，可立即開始全範圍膝關節活動","(D) 同時進行半月板修補和前十字韌帶重建"],"answer":3,"image":""},{"id":"md5-115-2-62","subject":"md5","topic":"神經外科","meta":"115年第2次第62題","year":115,"session":2,"number":62,"question":"有關脊髓休克（spinal shock），下列敘述何者最不適當？","options":["(A) 要診斷完全或不完全脊髓損傷（spinal cord injury），必須要等過了脊髓休克階段，才能確立診斷","(B) 脊髓休克會造成脊髓損傷節段以下的所有反射、運動及感覺功能都消失","(C) 提睪反射（cremasteric reflex）是最早回復的反射，且表示脊髓休克已經結束","(D) 目前對脊髓休克沒有特定的治療方法"],"answer":2,"image":""},{"id":"md5-115-2-63","subject":"md5","topic":"骨科-關節重建","meta":"115年第2次第63題","year":115,"session":2,"number":63,"question":"關於股骨頭骨壞死（osteonecrosis of the femoral head），下列敘述何者最適當？","options":["(A) 早期的病變先發生在股骨頭的前外上部區域的關節軟骨，然後擴及深層的鈣化軟骨層","(B) 股骨頭塌陷前的早期骨壞死，建議進行人工關節置換，以改善症狀","(C) 有新月徵（crescent sign）時，不適合接受保守性治療，如雙磷酸鹽類（bisphosphonates）、statins、高壓氧和體外震波療法等","(D) 股骨頭塌陷後較適合接受核心減壓和結構性骨移植（core decompression with structural bone grafting），增加血液供應，再生骨軟骨"],"answer":2,"image":""},{"id":"md5-115-2-64","subject":"md5","topic":"泌尿-結石與感染","meta":"115年第2次第64題","year":115,"session":2,"number":64,"question":"76歲黃女士因左側腰痛以及血尿到急診室就醫。在急診同時發現有高燒以及低血壓，身體檢查發現左側腰部有明顯敲痛以及尿液檢查發現有膿尿（pyuria），抽血有腎功能損傷，緊急安排電腦斷層檢查發現左側約一公分輸尿管結石合併水腎（hydronephrosis）以及左側二到三公分大小腎臟結石。針對上述臨床情境，下列那個治療處置以及相關敘述是錯誤？","options":["(A) 與家屬討論時告知此輸尿管結石大小自行排出機率不高","(B) 儘速安排左側經皮穿腎引流管（PCN）置放或左側雙J導管置放","(C) 儘速安排軟式輸尿管鏡手術一併處理輸尿管及腎臟結石","(D) 與家屬討論時告知體外震波碎石手術（ESWL）目前不適合"],"answer":2,"image":""},{"id":"md5-115-2-65","subject":"md5","topic":"內分泌與乳房外科","meta":"115年第2次第65題","year":115,"session":2,"number":65,"question":"一名33歲女性因腹痛接受腹部電腦斷層檢查（computed tomography），意外發現一顆1.5公分的腎上腺結節。其血壓為145/95 mmHg，未使用任何降壓藥物。她否認頭痛或潮紅症狀，實驗室檢查顯示血鉀3.3 mEq/L。下列何者為最適當的後續處置？","options":["(A) 進行腎上腺切除（adrenalectomy）","(B) 篩檢原發性醛固酮增多症（primary aldosteronism）","(C) 進行腎上腺切片（adrenal biopsy）","(D) 六個月後進行腹部電腦斷層檢查"],"answer":1,"image":""},{"id":"md5-115-2-66","subject":"md5","topic":"泌尿-腫瘤","meta":"115年第2次第66題","year":115,"session":2,"number":66,"question":"一位60歲男性的腹部電腦斷層檢查，發現左側腎臟有一個5.5公分的囊腫（renal cyst），其邊緣不規則（shaggy margins），且有實心結節（solid nodules）。依據Bosniak囊腫分類，此一囊腫屬於下列那一種類？","options":["(A) 第一類","(B) 第二類","(C) 第三類","(D) 第四類"],"answer":3,"image":""},{"id":"md5-115-2-67","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"115年第2次第67題","year":115,"session":2,"number":67,"question":"下列有關良性攝護腺增生（benign prostatic hyperplasia）的5α-還原酶抑制劑藥物治療，何者最不適當？","options":["(A) 5α-還原酶抑制劑可阻斷睪固酮轉化為更有作用能力的二羥睪固酮（dihydrotestosterone）","(B) 該藥物影響攝護腺的上皮增生，導致腺體縮小和症狀改善","(C) 需要6個月的治療時間才能達到對攝護腺大小的最大影響（約減少30％）和症狀改善","(D) 無論原先攝護腺大小，均可有效改善下泌尿道症狀"],"answer":3,"image":""},{"id":"md5-115-2-68","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"115年第2次第68題","year":115,"session":2,"number":68,"question":"關於男性外陰部動脈血流來源，下列敘述何者錯誤？","options":["(A) 內髂（internal iliac）動脈分支上膀胱（superior vesical）動脈，供應輸精管（vas deferens）","(B) 內髂（internal iliac）動脈分支臍（umbilical）動脈，供應提睪肌（cremaster）","(C) 外髂（external iliac）動脈分支下淺腹（inferior epigastric）動脈，供應提睪肌（cremaster）","(D) 主動脈（aorta）分支睪丸（testicular）動脈，供應睪丸（testis）"],"answer":1,"image":""},{"id":"md5-115-2-69","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"115年第2次第69題","year":115,"session":2,"number":69,"question":"一名4歲兒童近期已經接受膀胱訓練白天脫離了尿布，然而夜間仍然持續尿床，因此心急如焚的媽媽帶來就診。關於尿床的敘述，下列何者錯誤？","options":["(A) 尿床的成因來自這三個因素之間的不匹配：夜間尿液產生量、夜間膀胱儲尿能力、睡眠中喚醒能力","(B) 尿床從6歲開始建議進行積極治療，4歲以前不需要過度治療","(C) 強力證據支持抗利尿激素類似物desmopressin與夜尿警鈴作為單一症狀尿床的第一線治療。Desmopressin其效果是立即的，若在最初一週內沒有反應，則沒有證據支持繼續長期使用","(D) 在第6號與第11號染色體的兩個基因座上發現基因變異，這些可能的夜尿症風險基因與睡眠、尿液生成及膀胱功能相關9999"],"answer":[2,3],"image":"","answer_note":"更正:第69題答Ｃ或Ｄ或CD者均給分"},{"id":"md5-115-2-70","subject":"md5","topic":"泌尿-先天移植婦女泌尿","meta":"115年第2次第70題","year":115,"session":2,"number":70,"question":"關於腎移植患者使用mTc-MAG3或mTc-DTPA之動態腎臟閃爍攝影（dynamic renal scintigraphy）區分急性排斥（acute rejection）以及移植腎功能延遲恢復（delayed graft function），下列何者錯誤？","options":["(A) 急性排斥反應通常呈現腎灌流下降","(B) 腎臟切片仍是區分急性排斥與移植腎功能延遲恢復的最佳方式","(C) 在追蹤影像（serial imaging）中，移植腎功能延遲恢復者通常呈現逐漸改善的影像表現","(D) 動態腎臟閃爍攝影無法用於偵測吻合口（anastomotic）外漏"],"answer":3,"image":""},{"id":"md5-115-2-71","subject":"md5","topic":"泌尿-排尿障礙與男性學","meta":"115年第2次第71題","year":115,"session":2,"number":71,"question":"一名28歲男性出現右側精索靜脈曲張，醫師懷疑其靜脈回流途徑受阻。下列何者為右側睪丸的正常靜脈回流血管？","options":["(A) 下腔靜脈（inferior vena cava）","(B) 右腎靜脈（right renal vein）","(C) 右外髂靜脈（right external iliac vein）","(D) 右下腹壁靜脈（right inferior epigastric vein）"],"answer":0,"image":""},{"id":"md5-115-2-72","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"115年第2次第72題","year":115,"session":2,"number":72,"question":"35歲男性病人跌倒後被送到急診室，左肩劇烈疼痛且肩膀無法活動。他的左肩電腦斷層橫切面影像如圖所示，下列關於病況的敘述何者最恰當？","options":["(A) 這是肩盂肱關節（glenohumeral joint）最常見的脫臼","(B) 這類病患肩盂前部（anterior glenoid）會比肩盂後部（posterior glenoid）更容易受到損傷","(C) 這類病患未治療前，肩部無法做出外轉（external rotation）的動作","(D) 這類病患大部分都需要緊急開刀"],"answer":2,"image":"md5-115-2-72.jpeg"},{"id":"md5-115-2-73","subject":"md5","topic":"泌尿-結石與感染","meta":"115年第2次第73題","year":115,"session":2,"number":73,"question":"32歲男性病人，主訴為無痛性血尿，腹部X光片（KUB）顯示如附圖。下列診斷何者最恰當？","options":["(A) 腎髓質鈣化症（medullary nephrocalcinosis）","(B) 腎水腫（hydronephrosis）","(C) 急性腎結核（acute renal tuberculosis）","(D) 泌尿上皮細胞癌（urothelial cell carcinoma）"],"answer":0,"image":"md5-115-2-73.jpeg"},{"id":"md5-115-2-74","subject":"md5","topic":"胸腔外科","meta":"115年第2次第74題","year":115,"session":2,"number":74,"question":"24歲女性，因胸部X光發現異常，經電腦斷層檢查影像如附圖。下列何者為最可能的診斷？","options":["(A) 主動脈剝離（aortic dissection）","(B) 畸胎瘤（teratoma）","(C) 肺癌（lung cancer）","(D) 神經源性腫瘤（neurogenic tumor）"],"answer":1,"image":"md5-115-2-74.jpeg"},{"id":"md5-115-2-75","subject":"md5","topic":"外科-休克創傷傷口","meta":"115年第2次第75題","year":115,"session":2,"number":75,"question":"關於外傷的敘述，下列何者最不適當？","options":["(A) 最常造成外傷的機轉是鈍傷","(B) 頭皮、臉部傷口因表皮細菌較多，較容易細菌感染","(C) 殘留於傷口內的鐵片，大多數可在X光影像中看出","(D) 下肢傷口比上肢傷口容易感染"],"answer":1,"image":""},{"id":"md5-115-2-76","subject":"md5","topic":"外科-休克創傷傷口","meta":"115年第2次第76題","year":115,"session":2,"number":76,"question":"一位48歲司機有繫安全帶，在高速公路發生車禍，身體檢查發現病人意識清楚，血壓126/82 mmHg，心跳86/min，腹部有一帶狀瘀傷，X光發現第一腰椎有Chance fracture，則病人那個器官最可能受到傷害？","options":["(A) 降主動脈","(B) 胃","(C) 脾臟","(D) 十二指腸"],"answer":3,"image":""},{"id":"md5-115-2-77","subject":"md5","topic":"骨科-骨折與運動醫學","meta":"115年第2次第77題","year":115,"session":2,"number":77,"question":"一位27歲運動員膝蓋受傷，如懷疑有前十字韌帶受傷，則下列何種檢查陽性可以證實診斷？","options":["(A) Varus stress test","(B) Lachman test","(C) Thomas test","(D) FABER test"],"answer":1,"image":""},{"id":"md5-115-2-78","subject":"md5","topic":"醫學倫理與法規","meta":"115年第2次第78題","year":115,"session":2,"number":78,"question":"有關告知病人壞消息（imparting bad news），例如得到癌症或可能面臨死亡的威脅，乃遵守醫學倫理中的何項原則？","options":["(A) 行善原則（beneficence）","(B) 不傷害原則（nonmaleficence）","(C) 正義原則（justice）","(D) 尊重自主原則（respect for autonomy）"],"answer":3,"image":""},{"id":"md5-115-2-79","subject":"md5","topic":"醫學倫理與法規","meta":"115年第2次第79題","year":115,"session":2,"number":79,"question":"19歲男性病人因車禍導致嚴重腦外傷。手術後二週，病人在加護病房，使用呼吸器治療。病人昏迷指數（Glasgow Coma Scale, GCS）E1M1VT，兩側瞳孔放大無光反射，抽痰時也無咳嗽反射，升壓劑使用下血壓102/66毫米汞柱。經會診兩位腦神經專科醫師評估後，判定為腦死狀態。主治醫師與單親的外籍母親討論，不希望病人繼續受苦，希望終止病人在加護病房的治療。但是母親一直不願意接受這樣的訊息，認為她的兒子只是昏迷，將來一定會醒來，堅持繼續在加護病房治療。下列作法何者最為合適？","options":["(A) 因病人已判定為腦死，依據法律應直接判定病人死亡","(B) 接受母親的要求，繼續在加護病房治療，直到母親同意終止治療","(C) 向母親解釋病情，將病人轉出加護病房","(D) 醫師自行決定停止升壓劑使用，讓病人順其自然"],"answer":2,"image":""},{"id":"md5-115-2-80","subject":"md5","topic":"醫學倫理與法規","meta":"115年第2次第80題","year":115,"session":2,"number":80,"question":"34歲男子要求進行男性結紮手術。他已經有兩個小孩，不想再生了。當醫師幫他做身體診察時，發現他沒有輸精管（在陰囊兩側精索位置都摸不到輸精管），應是屬於先天兩側輸精管發育缺失（congenital bilateral absence of vas deferens）。此時，下列處理方式何者最恰當？","options":["(A) 手術照做，行禮如儀，以免節外生枝","(B) 如實以告，並且建議先去做精液分析確認","(C) 建議另請其他醫師處理","(D) 找理由拒絕開這一台手術"],"answer":1,"image":""}];
